function normalizeConfidence(value) {
  const text = String(value || "").trim().toUpperCase();
  return ["A", "B", "C", "D"].includes(text) ? text : null;
}

function normalizeVisibility(value) {
  const text = String(value || "").trim();
  if (["eligible", "hidden", "reference_only"].includes(text)) return text;
  return "eligible";
}

function numberOrNull(value) {
  if (value === null || value === undefined || value === "") return null;
  const number = Number(String(value).replace(/,/g, ""));
  return Number.isFinite(number) ? number : null;
}

function normalizeChannelUrls(value) {
  if (Array.isArray(value)) return value.map((item) => String(item || "").trim()).filter(Boolean);
  return String(value || "")
    .split(/\r?\n|,\s*/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function normalizeSignalType(value, fallback = "search_volume") {
  const text = String(value || "").trim();
  return ["naver_trend", "search_volume", "sns_mentions"].includes(text) ? text : fallback;
}

function normalizeSignalScope(value, fallback = "region_keyword") {
  const text = String(value || "").trim();
  return ["region_keyword", "property_keyword"].includes(text) ? text : fallback;
}

function normalizeSignalSource(value) {
  const text = String(value || "").trim();
  if (["naver_trend", "naver_searchad", "sns", "manual_admin", "verified_admin"].includes(text)) return text;
  return "manual_admin";
}

function normalizeSignalStatus(value) {
  const text = String(value || "").trim();
  if (["collected", "manual", "verified", "pending_connector"].includes(text)) return text;
  return "manual";
}

function normalizeExecutionStatus(value) {
  const text = String(value || "").trim();
  if (["not_started", "in_progress", "done", "blocked"].includes(text)) return text;
  return "not_started";
}

function normalizeSignalJobStatus(value) {
  const text = String(value || "").trim();
  if (["queued", "collecting", "succeeded", "failed", "retry_scheduled", "review_required", "cancelled"].includes(text)) return text;
  return "queued";
}

function normalizeConnectorSource(value, signalType = "") {
  const text = String(value || "").trim();
  if (["naver_trend", "naver_searchad", "sns"].includes(text)) return text;
  if (signalType === "naver_trend") return "naver_trend";
  if (signalType === "sns_mentions") return "sns";
  return "naver_searchad";
}

function signalTypeForConnector(source = "") {
  if (source === "naver_trend") return "naver_trend";
  if (source === "sns") return "sns_mentions";
  return "search_volume";
}

