function normalizeExternalConnectorId(value, fallback = "naver_searchad") {
  const text = String(value || "").trim();
  if (EXTERNAL_CONNECTORS[text]) return text;
  if (text === "sns") return "sns_mentions";
  if (text === "search_volume") return "naver_searchad";
  return fallback;
}

function connectorIdForInterestJob(job = {}) {
  if (job.source === "naver_trend" || job.signalType === "naver_trend") return "naver_trend";
  if (job.source === "sns" || job.signalType === "sns_mentions") return "sns_mentions";
  return "naver_searchad";
}

function connectorSourceForId(connectorId = "") {
  const connector = EXTERNAL_CONNECTORS[normalizeExternalConnectorId(connectorId)];
  return connector?.source || "";
}

function normalizeConnectorMode(value) {
  const text = String(value || "").trim().toLowerCase();
  return ["auto", "mock", "real"].includes(text) ? text : "auto";
}

function defaultExternalConnectorSchedule(connectorId = "") {
  const id = normalizeExternalConnectorId(connectorId || "naver_searchad");
  const isOta = id === "ota_exposure";
  return {
    connectorId: id,
    enabled: false,
    intervalMinutes: id === "naver_trend" ? 1440 : 720,
    targetScope: isOta ? "region_or_company" : "queued_and_retry",
    dailyLimit: isOta ? 10 : 25,
    retryLimit: 2,
    quotaWarningThreshold: 70,
    quotaStopThreshold: 90,
    nextRunAt: "",
    lastRunAt: "",
    lastOutcome: "",
    runOptions: isOta
      ? { otaChannels: DEFAULT_OTA_EXPOSURE_CHANNELS.join(", "), region: "", companyId: "", companyName: "" }
      : { connectorMode: "auto" },
    updatedAt: "",
    updatedBy: "system"
  };
}

function normalizeScheduleBoolean(value, fallback = false) {
  if (typeof value === "boolean") return value;
  if (value === undefined || value === null || value === "") return fallback;
  return ["1", "true", "yes", "y", "enabled", "on"].includes(String(value).trim().toLowerCase());
}

function normalizeSchedulePolicy(input = {}, existing = null) {
  const connectorId = normalizeExternalConnectorId(input.connectorId || existing?.connectorId || "naver_searchad");
  const defaults = defaultExternalConnectorSchedule(connectorId);
  const base = existing || defaults;
  const intervalMinutes = Math.max(15, Math.min(10080, Number(input.intervalMinutes ?? base.intervalMinutes ?? defaults.intervalMinutes)));
  const dailyLimit = Math.max(1, Math.min(1000, Number(input.dailyLimit ?? base.dailyLimit ?? defaults.dailyLimit)));
  const retryLimit = Math.max(0, Math.min(10, Number(input.retryLimit ?? base.retryLimit ?? defaults.retryLimit)));
  const quotaWarningThreshold = Math.max(1, Math.min(100, Number(input.quotaWarningThreshold ?? base.quotaWarningThreshold ?? defaults.quotaWarningThreshold)));
  const quotaStopThreshold = Math.max(quotaWarningThreshold, Math.min(100, Number(input.quotaStopThreshold ?? base.quotaStopThreshold ?? defaults.quotaStopThreshold)));
  return {
    ...defaults,
    ...base,
    connectorId,
    enabled: normalizeScheduleBoolean(input.enabled, Boolean(base.enabled)),
    intervalMinutes,
    targetScope: String(input.targetScope ?? base.targetScope ?? defaults.targetScope).trim() || defaults.targetScope,
    dailyLimit,
    retryLimit,
    quotaWarningThreshold,
    quotaStopThreshold,
    nextRunAt: String(input.nextRunAt ?? base.nextRunAt ?? "").trim(),
    lastRunAt: String(input.lastRunAt ?? base.lastRunAt ?? "").trim(),
    lastOutcome: String(input.lastOutcome ?? base.lastOutcome ?? "").trim(),
    runOptions: {
      ...(defaults.runOptions || {}),
      ...(base.runOptions || {}),
      ...(input.runOptions || {})
    },
    updatedAt: input.updatedAt || new Date().toISOString(),
    updatedBy: String(input.updatedBy || input.admin || base.updatedBy || "admin").trim()
  };
}

function externalConnectorPolicyList(data = {}) {
  const byId = new Map((data.policies || []).map((item) => [normalizeExternalConnectorId(item.connectorId), item]));
  return Object.keys(EXTERNAL_CONNECTORS).map((connectorId) => normalizeSchedulePolicy({ connectorId }, byId.get(connectorId)));
}

function nextRunAtForPolicy(policy = {}, now = new Date()) {
  if (!policy.enabled) return "";
  const existingNext = Date.parse(policy.nextRunAt || "");
  if (Number.isFinite(existingNext) && existingNext > now.getTime()) return new Date(existingNext).toISOString();
  const lastRunAt = Date.parse(policy.lastRunAt || "");
  const intervalMs = Math.max(15, Number(policy.intervalMinutes || 60)) * 60000;
  if (Number.isFinite(lastRunAt)) return new Date(lastRunAt + intervalMs).toISOString();
  return now.toISOString();
}

function connectorDailyLogCount(logs = [], connectorId = "", today = new Date().toISOString().slice(0, 10)) {
  return logs.filter((item) => item.connectorId === connectorId && String(item.startedAt || item.finishedAt || "").slice(0, 10) === today).length;
}

function quotaRiskForPolicy(policy = {}, usedToday = 0) {
  const limit = Math.max(1, Number(policy.dailyLimit || 1));
  const usedRate = Math.round((usedToday / limit) * 100);
  const level = usedRate >= Number(policy.quotaStopThreshold || 90)
    ? "danger"
    : usedRate >= Number(policy.quotaWarningThreshold || 70)
      ? "warning"
      : "normal";
  return {
    level,
    usedToday,
    dailyLimit: limit,
    usedRate,
    blocked: level === "danger",
    message: level === "danger"
      ? "Daily quota stop threshold reached."
      : level === "warning"
        ? "Daily quota warning threshold reached."
        : "Quota usage is within policy."
  };
}

function connectorFailurePendingCounts({ connectorId = "", logs = [], jobs = [] } = {}) {
  const counts = {};
  for (const log of logs) {
    if (log.connectorId !== connectorId) continue;
    if (!["failed", "retry_scheduled", "review_required"].includes(log.status)) continue;
    const key = log.failureType || log.status || "unknown";
    counts[key] = (counts[key] || 0) + 1;
  }
  for (const job of jobs) {
    if (connectorIdForInterestJob(job) !== connectorId) continue;
    if (!["failed", "retry_scheduled", "review_required"].includes(job.status)) continue;
    const key = job.failureType || job.status || "unknown";
    counts[key] = (counts[key] || 0) + 1;
  }
  return counts;
}

function connectorPendingQueueCounts(connectorId = "", jobs = []) {
  const rows = jobs.filter((job) => connectorIdForInterestJob(job) === connectorId);
  return rows.reduce((acc, job) => {
    acc[job.status || "queued"] = (acc[job.status || "queued"] || 0) + 1;
    return acc;
  }, {});
}

function isScheduleTimeDue(policy = {}, now = Date.now()) {
  const nextRunAt = Date.parse(policy.nextRunAt || "");
  return Number.isFinite(nextRunAt) && nextRunAt <= now;
}

function schedulePolicySnapshot(policy = {}) {
  if (!policy || !Object.keys(policy).length) return null;
  return {
    connectorId: normalizeExternalConnectorId(policy.connectorId),
    enabled: Boolean(policy.enabled),
    intervalMinutes: Number(policy.intervalMinutes || 0),
    targetScope: String(policy.targetScope || ""),
    dailyLimit: Number(policy.dailyLimit || 0),
    retryLimit: Number(policy.retryLimit || 0),
    quotaWarningThreshold: Number(policy.quotaWarningThreshold || 0),
    quotaStopThreshold: Number(policy.quotaStopThreshold || 0),
    nextRunAt: String(policy.nextRunAt || ""),
    lastRunAt: String(policy.lastRunAt || ""),
    lastOutcome: String(policy.lastOutcome || ""),
    runOptions: policy.runOptions || {},
    updatedAt: String(policy.updatedAt || ""),
    updatedBy: String(policy.updatedBy || "")
  };
}

function schedulePolicyChanges(beforePolicy = {}, afterPolicy = {}) {
  const before = schedulePolicySnapshot(beforePolicy) || {};
  const after = schedulePolicySnapshot(afterPolicy) || {};
  const fields = [
    "enabled",
    "intervalMinutes",
    "targetScope",
    "dailyLimit",
    "retryLimit",
    "quotaWarningThreshold",
    "quotaStopThreshold",
    "nextRunAt",
    "lastRunAt",
    "lastOutcome",
    "runOptions"
  ];
  return fields
    .filter((field) => !sameJson(before[field], after[field]))
    .map((field) => ({ field, before: before[field] ?? null, after: after[field] ?? null }));
}

function scheduleRunResultStatus(result = {}) {
  const counts = result.counts || {};
  if (Number(counts.failed || 0) > 0) return "failed";
  if (Number(counts.retry_scheduled || 0) > 0) return "retry_scheduled";
  if (Number(counts.review_required || 0) > 0) return "review_required";
  if (Number(result.requested || 0) <= 0) return "skipped";
  return "succeeded";
}

function scheduleRunResultSummary(result = {}) {
  const counts = result.counts || {};
  const candidateCounts = result.candidateCounts || {};
  const parts = [
    `requested ${Number(result.requested || 0)}`,
    `success ${Number(counts.succeeded || 0)}`,
    `retry ${Number(counts.retry_scheduled || 0)}`,
    `review ${Number(counts.review_required || 0)}`,
    `failed ${Number(counts.failed || 0)}`
  ];
  if (Number(candidateCounts.retry_scheduled || 0) > 0) {
    parts.push(`retry candidates ${Number(candidateCounts.retry_scheduled || 0)}`);
  }
  return parts.join(" / ");
}

async function appendExternalConnectorScheduleAuditLog(input = {}) {
  const data = await readExternalConnectorScheduleAuditLogs();
  const now = new Date().toISOString();
  const beforePolicy = schedulePolicySnapshot(input.beforePolicy);
  const afterPolicy = schedulePolicySnapshot(input.afterPolicy);
  const item = {
    auditId: input.auditId || hashId("xcsalog", `${input.eventType || ""}|${input.connectorId || ""}|${now}|${crypto.randomUUID()}`),
    eventType: String(input.eventType || "schedule_event").trim(),
    connectorId: normalizeExternalConnectorId(input.connectorId || beforePolicy?.connectorId || afterPolicy?.connectorId),
    source: String(input.source || connectorSourceForId(input.connectorId || beforePolicy?.connectorId || afterPolicy?.connectorId)).trim(),
    actor: String(input.actor || input.updatedBy || "admin").trim(),
    trigger: String(input.trigger || "").trim(),
    status: String(input.status || "recorded").trim(),
    resultSummary: String(input.resultSummary || "").trim(),
    failureType: String(input.failureType || "").trim(),
    error: String(input.error || "").trim().slice(0, 500),
    previousNextRunAt: String(input.previousNextRunAt || beforePolicy?.nextRunAt || "").trim(),
    nextRunAt: String(input.nextRunAt || afterPolicy?.nextRunAt || "").trim(),
    quotaRisk: input.quotaRisk || null,
    runMode: String(input.runMode || "").trim(),
    forced: Boolean(input.forced),
    requestedCount: Number(input.requestedCount || 0),
    resultCounts: input.resultCounts || {},
    candidateCounts: input.candidateCounts || {},
    changes: input.changes || schedulePolicyChanges(beforePolicy, afterPolicy),
    beforePolicy,
    afterPolicy,
    createdAt: now
  };
  const items = [item, ...(data.items || [])].slice(0, 3000);
  await writeExternalConnectorScheduleAuditLogs({ ...data, items });
  return item;
}

function filterExternalConnectorScheduleAuditLogs(data = {}, params) {
  const connectorId = params.get("connectorId");
  const eventType = params.get("eventType");
  const status = params.get("status");
  const actor = params.get("actor");
  const limit = Math.max(1, Math.min(1000, Number(params.get("limit") || 100)));
  const normalizedConnectorId = connectorId ? normalizeExternalConnectorId(connectorId) : "";
  const items = (data.items || [])
    .filter((item) => !normalizedConnectorId || item.connectorId === normalizedConnectorId)
    .filter((item) => !eventType || item.eventType === eventType)
    .filter((item) => !status || item.status === status)
    .filter((item) => !actor || String(item.actor || "").toLowerCase().includes(String(actor).toLowerCase()))
    .slice(0, limit);
  return { ...data, items };
}

async function externalConnectorScheduleAuditReport(params = new URLSearchParams()) {
  const data = filterExternalConnectorScheduleAuditLogs(await readExternalConnectorScheduleAuditLogs(), params);
  const items = data.items || [];
  const summary = {
    total: items.length,
    policyEvents: items.filter((item) => String(item.eventType || "").startsWith("policy_")).length,
    executionEvents: items.filter((item) => ["scheduled_run", "forced_run", "retry_run_result"].includes(item.eventType)).length,
    quotaBlocked: items.filter((item) => item.eventType === "quota_blocked").length,
    forcedRuns: items.filter((item) => item.eventType === "forced_run").length,
    retryResults: items.filter((item) => item.eventType === "retry_run_result").length,
    failed: items.filter((item) => ["failed", "retry_scheduled"].includes(item.status)).length
  };
  return {
    role: "admin",
    generatedAt: new Date().toISOString(),
    schema: "external_connector_schedule_audit_log_v1",
    summary,
    items
  };
}

function scheduleOperationDateKey(value = "") {
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return "";
  return date.toISOString().slice(0, 10);
}

function scheduleOperationWeekKey(value = "") {
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return "";
  const utc = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
  const dayOffset = (utc.getUTCDay() + 6) % 7;
  utc.setUTCDate(utc.getUTCDate() - dayOffset);
  return utc.toISOString().slice(0, 10);
}

function normalizeScheduleOperationReportFilters(params = new URLSearchParams()) {
  const today = new Date();
  const defaultEnd = today.toISOString().slice(0, 10);
  const defaultStartDate = new Date(today.getTime() - 29 * 24 * 60 * 60 * 1000);
  const defaultStart = defaultStartDate.toISOString().slice(0, 10);
  const connectorId = params.get("connectorId") ? normalizeExternalConnectorId(params.get("connectorId")) : "";
  const startDate = /^\d{4}-\d{2}-\d{2}$/.test(params.get("startDate") || "") ? params.get("startDate") : defaultStart;
  const endDate = /^\d{4}-\d{2}-\d{2}$/.test(params.get("endDate") || "") ? params.get("endDate") : defaultEnd;
  return {
    connectorId,
    eventType: String(params.get("eventType") || "").trim(),
    startDate,
    endDate,
    format: String(params.get("format") || "").trim().toLowerCase()
  };
}

function isSchedulePolicyEvent(item = {}) {
  return String(item.eventType || "").startsWith("policy_");
}

function isScheduleExecutionEvent(item = {}) {
  return ["scheduled_run", "forced_run", "retry_run_result"].includes(item.eventType);
}

function emptyScheduleOperationMetrics(connectorId = "", periodType = "total", periodKey = "total") {
  return {
    connectorId,
    connectorLabel: EXTERNAL_CONNECTORS[connectorId]?.label || connectorId || "all",
    periodType,
    periodKey,
    totalEvents: 0,
    executionEvents: 0,
    successfulRuns: 0,
    failedRuns: 0,
    retryEvents: 0,
    retrySuccesses: 0,
    quotaBlocked: 0,
    policyChanges: 0,
    requestedCount: 0,
    failureReasons: {}
  };
}

function addScheduleOperationEvent(metrics, item = {}) {
  metrics.totalEvents += 1;
  metrics.requestedCount += Number(item.requestedCount || 0);
  if (isScheduleExecutionEvent(item)) {
    metrics.executionEvents += 1;
    if (item.status === "succeeded") metrics.successfulRuns += 1;
    if (["failed", "retry_scheduled", "review_required"].includes(item.status)) metrics.failedRuns += 1;
  }
  if (item.eventType === "retry_run_result") {
    metrics.retryEvents += 1;
    if (item.status === "succeeded") metrics.retrySuccesses += 1;
  }
  if (item.eventType === "quota_blocked") metrics.quotaBlocked += 1;
  if (isSchedulePolicyEvent(item)) metrics.policyChanges += 1;
  if (item.failureType || ["failed", "retry_scheduled", "review_required", "blocked"].includes(item.status)) {
    const key = item.failureType || item.status || "unknown";
    metrics.failureReasons[key] = (metrics.failureReasons[key] || 0) + 1;
  }
}

function finalizeScheduleOperationMetrics(metrics = {}) {
  const successRate = metrics.executionEvents
    ? Math.round((metrics.successfulRuns / metrics.executionEvents) * 100)
    : null;
  const retrySuccessRate = metrics.retryEvents
    ? Math.round((metrics.retrySuccesses / metrics.retryEvents) * 100)
    : null;
  const failureReasonList = Object.entries(metrics.failureReasons || {})
    .map(([reason, count]) => ({ reason, count }))
    .sort((a, b) => b.count - a.count || a.reason.localeCompare(b.reason));
  return {
    ...metrics,
    successRate,
    retrySuccessRate,
    failureReasonList
  };
}

function scheduleOperationReportUrl(filters = {}, format = "") {
  const params = new URLSearchParams();
  if (filters.connectorId) params.set("connectorId", filters.connectorId);
  if (filters.eventType) params.set("eventType", filters.eventType);
  if (filters.startDate) params.set("startDate", filters.startDate);
  if (filters.endDate) params.set("endDate", filters.endDate);
  if (format) params.set("format", format);
  return `/api/admin/master-db/external-connector-schedule-operation-report?${params.toString()}`;
}

function scheduleOperationExportRows(report = {}) {
  const rows = [];
  for (const row of report.byConnector || []) {
    rows.push({
      section: "connector",
      periodType: "total",
      periodKey: "total",
      connectorId: row.connectorId,
      connectorLabel: row.connectorLabel,
      executionEvents: row.executionEvents,
      successfulRuns: row.successfulRuns,
      successRate: row.successRate ?? "",
      retryEvents: row.retryEvents,
      retrySuccessRate: row.retrySuccessRate ?? "",
      quotaBlocked: row.quotaBlocked,
      policyChanges: row.policyChanges,
      failureReasons: (row.failureReasonList || []).map((item) => `${item.reason}:${item.count}`).join(" | ")
    });
  }
  for (const row of [...(report.daily || []), ...(report.weekly || [])]) {
    rows.push({
      section: "period",
      periodType: row.periodType,
      periodKey: row.periodKey,
      connectorId: row.connectorId,
      connectorLabel: row.connectorLabel,
      executionEvents: row.executionEvents,
      successfulRuns: row.successfulRuns,
      successRate: row.successRate ?? "",
      retryEvents: row.retryEvents,
      retrySuccessRate: row.retrySuccessRate ?? "",
      quotaBlocked: row.quotaBlocked,
      policyChanges: row.policyChanges,
      failureReasons: (row.failureReasonList || []).map((item) => `${item.reason}:${item.count}`).join(" | ")
    });
  }
  return rows;
}

function scheduleOperationReportCsv(report = {}) {
  const rows = scheduleOperationExportRows(report);
  if (!rows.length) return "section,periodType,periodKey,connectorId,connectorLabel,executionEvents,successfulRuns,successRate,retryEvents,retrySuccessRate,quotaBlocked,policyChanges,failureReasons\n";
  const columns = Object.keys(rows[0]);
  return [
    columns.join(","),
    ...rows.map((row) => columns.map((column) => csvEscape(row[column])).join(","))
  ].join("\n");
}

function scheduleOperationReportFilename(filters = {}, format = "json") {
  const safeConnector = String(filters.connectorId || "all").replace(/[^a-zA-Z0-9_-]/g, "_");
  const safeStart = String(filters.startDate || "").replace(/[^0-9-]/g, "");
  const safeEnd = String(filters.endDate || "").replace(/[^0-9-]/g, "");
  return `external_connector_schedule_operation_${safeConnector}_${safeStart}_${safeEnd}.${format}`;
}

async function externalConnectorScheduleOperationReport(params = new URLSearchParams()) {
  const filters = normalizeScheduleOperationReportFilters(params);
  const data = await readExternalConnectorScheduleAuditLogs();
  const startDate = filters.startDate;
  const endDate = filters.endDate;
  const items = (data.items || [])
    .filter((item) => !filters.connectorId || item.connectorId === filters.connectorId)
    .filter((item) => !filters.eventType || item.eventType === filters.eventType)
    .filter((item) => {
      const day = scheduleOperationDateKey(item.createdAt);
      return day && day >= startDate && day <= endDate;
    });
  const connectorMap = new Map();
  const dailyMap = new Map();
  const weeklyMap = new Map();
  const summary = emptyScheduleOperationMetrics("all", "total", "total");
  for (const item of items) {
    const connectorId = normalizeExternalConnectorId(item.connectorId);
    const day = scheduleOperationDateKey(item.createdAt);
    const week = scheduleOperationWeekKey(item.createdAt);
    if (!connectorMap.has(connectorId)) connectorMap.set(connectorId, emptyScheduleOperationMetrics(connectorId, "total", "total"));
    const dayKey = `${connectorId}|${day}`;
    if (!dailyMap.has(dayKey)) dailyMap.set(dayKey, emptyScheduleOperationMetrics(connectorId, "day", day));
    const weekKey = `${connectorId}|${week}`;
    if (!weeklyMap.has(weekKey)) weeklyMap.set(weekKey, emptyScheduleOperationMetrics(connectorId, "week", week));
    addScheduleOperationEvent(summary, item);
    addScheduleOperationEvent(connectorMap.get(connectorId), item);
    addScheduleOperationEvent(dailyMap.get(dayKey), item);
    addScheduleOperationEvent(weeklyMap.get(weekKey), item);
  }
  const report = {
    role: "admin",
    generatedAt: new Date().toISOString(),
    schema: "external_connector_schedule_operation_report_v1",
    filters,
    summary: finalizeScheduleOperationMetrics(summary),
    byConnector: [...connectorMap.values()].map(finalizeScheduleOperationMetrics).sort((a, b) => b.totalEvents - a.totalEvents || a.connectorId.localeCompare(b.connectorId)),
    daily: [...dailyMap.values()].map(finalizeScheduleOperationMetrics).sort((a, b) => b.periodKey.localeCompare(a.periodKey) || a.connectorId.localeCompare(b.connectorId)),
    weekly: [...weeklyMap.values()].map(finalizeScheduleOperationMetrics).sort((a, b) => b.periodKey.localeCompare(a.periodKey) || a.connectorId.localeCompare(b.connectorId)),
    exportUrls: {
      csv: scheduleOperationReportUrl(filters, "csv"),
      json: scheduleOperationReportUrl(filters, "json")
    },
    exportRows: []
  };
  report.exportRows = scheduleOperationExportRows(report);
  return report;
}

function normalizeOperationAlertStatus(value = "") {
  const text = String(value || "").trim();
  return ["open", "in_progress", "done", "dismissed"].includes(text) ? text : "open";
}

function operationAlertDueState(item = {}, now = new Date()) {
  const dueDate = String(item.dueDate || "").trim();
  if (!dueDate) return "no_due";
  const due = new Date(`${dueDate}T23:59:59`);
  if (Number.isNaN(due.getTime())) return "no_due";
  if (["done", "dismissed"].includes(item.status)) return "closed";
  if (due < now) return "overdue";
  if (due.getTime() - now.getTime() <= 7 * 24 * 60 * 60 * 1000) return "this_week";
  return "upcoming";
}

function operationAlertLevel(score = 0) {
  if (score >= 90) return "danger";
  if (score >= 65) return "warning";
  return "notice";
}

function operationAlertPriority(level = "") {
  if (level === "danger") return "high";
  if (level === "warning") return "medium";
  return "low";
}

function buildOperationAlertCandidate(row = {}, warningType = "", detail = {}, filters = {}) {
  const level = operationAlertLevel(detail.score || 0);
  const connectorId = row.connectorId || "all";
  return {
    queueItemId: hashId("xopq", [connectorId, warningType, filters.startDate, filters.endDate, detail.sourceKey || ""].join("|")),
    warningType,
    warningLabel: detail.label || warningType,
    connectorId,
    connectorLabel: row.connectorLabel || EXTERNAL_CONNECTORS[connectorId]?.label || connectorId,
    alertLevel: level,
    priority: operationAlertPriority(level),
    rootMetric: detail.rootMetric || "",
    rootMetricValue: detail.rootMetricValue ?? null,
    title: detail.title || `${row.connectorLabel || connectorId} operation alert`,
    description: detail.description || "",
    recommendedAction: detail.recommendedAction || "",
    evidence: detail.evidence || [],
    sourceReportFilters: filters,
    sourceMetricSnapshot: {
      executionEvents: row.executionEvents || 0,
      successfulRuns: row.successfulRuns || 0,
      successRate: row.successRate,
      retryEvents: row.retryEvents || 0,
      retrySuccessRate: row.retrySuccessRate,
      quotaBlocked: row.quotaBlocked || 0,
      policyChanges: row.policyChanges || 0,
      failureReasonList: row.failureReasonList || []
    },
    generatedAt: new Date().toISOString(),
    status: "open",
    assignee: "",
    dueDate: "",
    memo: "",
    updatedBy: "",
    updatedAt: null,
    resolvedAt: null
  };
}

function operationAlertCandidatesFromReport(report = {}) {
  const candidates = [];
  const filters = report.filters || {};
  for (const row of report.byConnector || []) {
    if (Number(row.executionEvents || 0) >= 2 && row.successRate !== null && Number(row.successRate) < 70) {
      candidates.push(buildOperationAlertCandidate(row, "low_success_rate", {
        score: Number(row.successRate) < 50 ? 95 : 72,
        rootMetric: "successRate",
        rootMetricValue: row.successRate,
        label: "실행 성공률 저하",
        title: `${row.connectorLabel} 실행 성공률 저하`,
        description: "선택 기간의 커넥터 실행 성공률이 운영 기준보다 낮습니다.",
        recommendedAction: "최근 실패 로그와 인증/쿼터/어댑터 상태를 확인하고 재시도 정책을 조정하십시오.",
        evidence: [`성공률 ${row.successRate}%`, `성공 ${row.successfulRuns}/${row.executionEvents}`, scheduleOperationFailureTextForServer(row)]
      }, filters));
    }
    if (Number(row.retryEvents || 0) >= 2 && (row.retrySuccessRate === null || Number(row.retrySuccessRate) < 50)) {
      candidates.push(buildOperationAlertCandidate(row, "retry_failure_increase", {
        score: Number(row.retrySuccessRate || 0) < 25 ? 92 : 70,
        rootMetric: "retrySuccessRate",
        rootMetricValue: row.retrySuccessRate,
        label: "재시도 실패 증가",
        title: `${row.connectorLabel} 재시도 실패 증가`,
        description: "재시도된 수집 작업이 충분히 회복되지 않고 있습니다.",
        recommendedAction: "실패 원인별 재시도 간격, 일일 한도, 검수 전환 기준을 점검하십시오.",
        evidence: [`재시도 성공률 ${row.retrySuccessRate ?? "-"}%`, `재시도 ${row.retrySuccesses}/${row.retryEvents}`]
      }, filters));
    }
    if (Number(row.quotaBlocked || 0) > 0) {
      candidates.push(buildOperationAlertCandidate(row, "quota_block_repeat", {
        score: Number(row.quotaBlocked || 0) >= 3 ? 94 : 72,
        rootMetric: "quotaBlocked",
        rootMetricValue: row.quotaBlocked,
        label: "쿼터 차단 반복",
        title: `${row.connectorLabel} 쿼터 차단`,
        description: "쿼터 보호 기준으로 자동 실행이 차단된 이력이 있습니다.",
        recommendedAction: "일일 실행 한도와 자동 실행 주기를 낮추거나 API 쿼터를 증설하십시오.",
        evidence: [`쿼터 차단 ${row.quotaBlocked}건`, `정책 변경 ${row.policyChanges}건`]
      }, filters));
    }
    const topFailure = (row.failureReasonList || [])[0];
    if (topFailure && Number(topFailure.count || 0) >= 2) {
      candidates.push(buildOperationAlertCandidate(row, "failure_reason_spike", {
        score: Number(topFailure.count || 0) >= 4 ? 90 : 68,
        rootMetric: `failureReason.${topFailure.reason}`,
        rootMetricValue: topFailure.count,
        sourceKey: topFailure.reason,
        label: "특정 실패 원인 급증",
        title: `${row.connectorLabel} ${topFailure.reason} 증가`,
        description: "특정 실패 원인이 반복되어 수집 품질 저하 가능성이 있습니다.",
        recommendedAction: "해당 실패 원인의 요청 파라미터, 인증, 쿼터, 빈 결과 조건을 분리 점검하십시오.",
        evidence: (row.failureReasonList || []).slice(0, 3).map((item) => `${item.reason}: ${item.count}건`)
      }, filters));
    }
    if (Number(row.policyChanges || 0) >= 3) {
      candidates.push(buildOperationAlertCandidate(row, "frequent_policy_changes", {
        score: Number(row.policyChanges || 0) >= 5 ? 90 : 66,
        rootMetric: "policyChanges",
        rootMetricValue: row.policyChanges,
        label: "잦은 정책 변경",
        title: `${row.connectorLabel} 스케줄 정책 변경 과다`,
        description: "짧은 기간에 스케줄 정책 변경이 반복되고 있습니다.",
        recommendedAction: "변경 사유를 정리하고 안정 기준을 승인된 운영 정책으로 고정하십시오.",
        evidence: [`정책 변경 ${row.policyChanges}건`, `기간 ${filters.startDate || "-"} ~ ${filters.endDate || "-"}`]
      }, filters));
    }
  }
  return candidates;
}

function scheduleOperationFailureTextForServer(row = {}) {
  const reasons = row.failureReasonList || [];
  if (!reasons.length) return "failure reasons none";
  return reasons.slice(0, 3).map((item) => `${item.reason}:${item.count}`).join(" / ");
}

function mergeOperationAlertQueue(candidates = [], savedItems = []) {
  const savedById = new Map(savedItems.map((item) => [item.queueItemId, item]));
  const candidateIds = new Set(candidates.map((item) => item.queueItemId));
  const merged = candidates.map((candidate) => {
    const saved = savedById.get(candidate.queueItemId) || {};
    return {
      ...candidate,
      status: normalizeOperationAlertStatus(saved.status || candidate.status),
      assignee: saved.assignee || "",
      dueDate: saved.dueDate || "",
      memo: saved.memo || "",
      updatedBy: saved.updatedBy || "",
      updatedAt: saved.updatedAt || null,
      resolvedAt: saved.resolvedAt || null,
      currentCandidate: true,
      stale: false
    };
  });
  const stale = savedItems
    .filter((item) => !candidateIds.has(item.queueItemId))
    .map((item) => ({
      ...item,
      status: normalizeOperationAlertStatus(item.status),
      currentCandidate: false,
      stale: true
    }));
  return [...merged, ...stale];
}

function filterOperationAlertQueueItems(items = [], params = new URLSearchParams()) {
  const status = params.get("status") || "";
  const alertLevel = params.get("alertLevel") || "";
  const connectorId = params.get("connectorId") ? normalizeExternalConnectorId(params.get("connectorId")) : "";
  const warningType = params.get("warningType") || "";
  const assignee = compactKeyword(params.get("assignee") || "");
  const dueState = params.get("dueState") || "";
  const limit = Math.max(1, Math.min(1000, Number(params.get("limit") || 200)));
  return items
    .map((item) => ({ ...item, dueState: operationAlertDueState(item) }))
    .filter((item) => !status || item.status === status)
    .filter((item) => !alertLevel || item.alertLevel === alertLevel)
    .filter((item) => !connectorId || item.connectorId === connectorId)
    .filter((item) => !warningType || item.warningType === warningType)
    .filter((item) => !assignee || compactKeyword(item.assignee).includes(assignee))
    .filter((item) => !dueState || item.dueState === dueState)
    .sort((a, b) => {
      const levelRank = { danger: 3, warning: 2, notice: 1 };
      const statusRank = { open: 3, in_progress: 2, done: 0, dismissed: 0 };
      return (statusRank[b.status] || 0) - (statusRank[a.status] || 0)
        || (levelRank[b.alertLevel] || 0) - (levelRank[a.alertLevel] || 0)
        || String(a.dueDate || "9999-12-31").localeCompare(String(b.dueDate || "9999-12-31"));
    })
    .slice(0, limit);
}

function operationAlertQueueSummary(items = []) {
  const byStatus = items.reduce((acc, item) => {
    const status = normalizeOperationAlertStatus(item.status);
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  const byLevel = items.reduce((acc, item) => {
    acc[item.alertLevel || "notice"] = (acc[item.alertLevel || "notice"] || 0) + 1;
    return acc;
  }, {});
  return {
    total: items.length,
    open: byStatus.open || 0,
    inProgress: byStatus.in_progress || 0,
    done: byStatus.done || 0,
    dismissed: byStatus.dismissed || 0,
    danger: byLevel.danger || 0,
    warning: byLevel.warning || 0,
    overdue: items.filter((item) => operationAlertDueState(item) === "overdue").length,
    thisWeek: items.filter((item) => operationAlertDueState(item) === "this_week").length,
    stale: items.filter((item) => item.stale).length,
    byStatus,
    byLevel
  };
}

function operationAlertLogChanges(beforeItem = {}, afterItem = {}) {
  return ["status", "assignee", "dueDate", "memo"].reduce((changes, field) => {
    const before = beforeItem[field] ?? "";
    const after = afterItem[field] ?? "";
    if (!sameJson(before, after)) changes.push({ field, before, after });
    return changes;
  }, []);
}

function operationAlertLogEventType(beforeItem = {}, afterItem = {}) {
  if (beforeItem.status !== afterItem.status && afterItem.status === "done") return "completed";
  if (beforeItem.status !== afterItem.status && afterItem.status === "dismissed") return "dismissed";
  if (beforeItem.status !== afterItem.status) return "status_changed";
  return "updated";
}

async function appendExternalConnectorOperationAlertQueueLog(input = {}) {
  const data = await readExternalConnectorOperationAlertQueueLogs();
  const now = new Date().toISOString();
  const beforeItem = input.beforeItem || {};
  const afterItem = input.afterItem || {};
  const changes = input.changes || operationAlertLogChanges(beforeItem, afterItem);
  const item = {
    logId: input.logId || hashId("xoplog", `${input.queueItemId || afterItem.queueItemId || ""}|${now}|${crypto.randomUUID()}`),
    queueItemId: String(input.queueItemId || afterItem.queueItemId || beforeItem.queueItemId || "").trim(),
    connectorId: normalizeExternalConnectorId(input.connectorId || afterItem.connectorId || beforeItem.connectorId || "naver_searchad"),
    connectorLabel: String(input.connectorLabel || afterItem.connectorLabel || beforeItem.connectorLabel || "").trim(),
    warningType: String(input.warningType || afterItem.warningType || beforeItem.warningType || "").trim(),
    warningLabel: String(input.warningLabel || afterItem.warningLabel || beforeItem.warningLabel || "").trim(),
    alertLevel: String(input.alertLevel || afterItem.alertLevel || beforeItem.alertLevel || "").trim(),
    eventType: String(input.eventType || operationAlertLogEventType(beforeItem, afterItem)).trim(),
    changedBy: String(input.changedBy || input.updatedBy || afterItem.updatedBy || "admin").trim(),
    changedAt: now,
    previousStatus: String(beforeItem.status || "").trim(),
    nextStatus: String(afterItem.status || "").trim(),
    previousAssignee: String(beforeItem.assignee || "").trim(),
    nextAssignee: String(afterItem.assignee || "").trim(),
    previousDueDate: String(beforeItem.dueDate || "").trim(),
    nextDueDate: String(afterItem.dueDate || "").trim(),
    previousMemo: String(beforeItem.memo || "").trim(),
    nextMemo: String(afterItem.memo || "").trim(),
    changes,
    before: {
      status: beforeItem.status || "",
      assignee: beforeItem.assignee || "",
      dueDate: beforeItem.dueDate || "",
      memo: beforeItem.memo || ""
    },
    after: {
      status: afterItem.status || "",
      assignee: afterItem.assignee || "",
      dueDate: afterItem.dueDate || "",
      memo: afterItem.memo || ""
    }
  };
  const items = [item, ...(data.items || [])].slice(0, 3000);
  await writeExternalConnectorOperationAlertQueueLogs({ ...data, items });
  return item;
}

function filterOperationAlertQueueLogs(data = {}, params = new URLSearchParams()) {
  const queueItemId = params.get("queueItemId") || "";
  const connectorId = params.get("connectorId") ? normalizeExternalConnectorId(params.get("connectorId")) : "";
  const eventType = params.get("eventType") || "";
  const changedBy = compactKeyword(params.get("changedBy") || "");
  const limit = Math.max(1, Math.min(1000, Number(params.get("limit") || 100)));
  const items = (data.items || [])
    .filter((item) => !queueItemId || item.queueItemId === queueItemId)
    .filter((item) => !connectorId || item.connectorId === connectorId)
    .filter((item) => !eventType || item.eventType === eventType)
    .filter((item) => !changedBy || compactKeyword(item.changedBy).includes(changedBy))
    .slice(0, limit);
  return {
    ...data,
    summary: {
      total: items.length,
      completed: items.filter((item) => item.eventType === "completed").length,
      dismissed: items.filter((item) => item.eventType === "dismissed").length,
      statusChanged: items.filter((item) => item.eventType === "status_changed").length
    },
    items
  };
}

function normalizeOperationAlertQualityFilters(params = new URLSearchParams(), logs = []) {
  const latestLogMonth = (logs || [])
    .map((item) => monthKey(item.changedAt))
    .filter(Boolean)
    .sort()
    .pop();
  const requestedMonth = String(params.get("month") || "").trim();
  const month = /^\d{4}-\d{2}$/.test(requestedMonth)
    ? requestedMonth
    : latestLogMonth || monthKey(new Date().toISOString());
  return {
    month,
    connectorId: params.get("connectorId") ? normalizeExternalConnectorId(params.get("connectorId")) : ""
  };
}

function operationAlertLogAssignee(log = {}, queueItem = {}) {
  return String(
    log.nextAssignee
    || log.previousAssignee
    || queueItem.assignee
    || log.changedBy
    || "unassigned"
  ).trim() || "unassigned";
}

function operationAlertHoursBetween(startAt = "", endAt = "") {
  const start = new Date(startAt);
  const end = new Date(endAt);
  if (!Number.isFinite(start.getTime()) || !Number.isFinite(end.getTime())) return null;
  const diff = end.getTime() - start.getTime();
  if (diff < 0) return null;
  return Number((diff / 3600000).toFixed(2));
}

function operationAlertResolvedLate(log = {}, queueItem = {}) {
  const dueDate = String(log.nextDueDate || queueItem.dueDate || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate) || !log.changedAt) return false;
  const dueEnd = new Date(`${dueDate}T23:59:59.999Z`);
  const resolvedAt = new Date(log.changedAt);
  if (!Number.isFinite(dueEnd.getTime()) || !Number.isFinite(resolvedAt.getTime())) return false;
  return resolvedAt.getTime() > dueEnd.getTime();
}

const OPERATION_ALERT_QUALITY_CRITERIA = Object.freeze({
  avgProcessingHours: {
    label: "평균 처리 시간",
    warning: 72,
    danger: 120,
    unit: "hours",
    lowerIsBetter: true
  },
  delayedResolutionRate: {
    label: "지연 해소율",
    warning: 10,
    danger: 30,
    unit: "percent",
    lowerIsBetter: true
  },
  dismissedRatio: {
    label: "보류 비율",
    warning: 30,
    danger: 50,
    unit: "percent",
    lowerIsBetter: true
  },
  reopenRate: {
    label: "재오픈 빈도",
    warning: 10,
    danger: 20,
    unit: "percent",
    lowerIsBetter: true
  },
  throughputRate: {
    label: "처리 전환율",
    warning: 60,
    danger: 30,
    unit: "percent",
    lowerIsBetter: false
  }
});

function operationAlertQualityGradeLabel(grade = "normal") {
  return {
    normal: "정상",
    warning: "주의",
    danger: "위험"
  }[grade] || "정상";
}

function operationAlertQualityIssue(field, level, value, message, recommendation) {
  const criteria = OPERATION_ALERT_QUALITY_CRITERIA[field] || {};
  return {
    field,
    label: criteria.label || field,
    level,
    levelLabel: operationAlertQualityGradeLabel(level),
    value,
    warningThreshold: criteria.warning ?? null,
    dangerThreshold: criteria.danger ?? null,
    unit: criteria.unit || "",
    message,
    recommendation
  };
}

function operationAlertQualityHealth(metrics = {}) {
  const issues = [];
  const avgHours = metrics.avgProcessingHours;
  if (avgHours !== null && avgHours !== undefined) {
    if (avgHours > OPERATION_ALERT_QUALITY_CRITERIA.avgProcessingHours.danger) {
      issues.push(operationAlertQualityIssue(
        "avgProcessingHours",
        "danger",
        avgHours,
        "평균 처리 시간이 위험 기준을 초과했습니다.",
        "고위험 경고를 먼저 배정하고 목표일을 앞당기십시오."
      ));
    } else if (avgHours > OPERATION_ALERT_QUALITY_CRITERIA.avgProcessingHours.warning) {
      issues.push(operationAlertQualityIssue(
        "avgProcessingHours",
        "warning",
        avgHours,
        "평균 처리 시간이 주의 기준을 넘었습니다.",
        "담당자별 미처리 경고와 지연 항목을 우선 정리하십시오."
      ));
    }
  }
  const delayedRate = metrics.delayedResolutionRate;
  if (delayedRate !== null && delayedRate !== undefined) {
    if (delayedRate >= OPERATION_ALERT_QUALITY_CRITERIA.delayedResolutionRate.danger) {
      issues.push(operationAlertQualityIssue("delayedResolutionRate", "danger", delayedRate, "지연 해소율이 위험 기준입니다.", "목표일 초과 항목의 원인을 분류하고 재발 방지 조치를 배정하십시오."));
    } else if (delayedRate >= OPERATION_ALERT_QUALITY_CRITERIA.delayedResolutionRate.warning) {
      issues.push(operationAlertQualityIssue("delayedResolutionRate", "warning", delayedRate, "지연 해소율이 주의 기준입니다.", "이번 주 처리 항목과 지연 항목을 분리해 추적하십시오."));
    }
  }
  const dismissedRatio = metrics.dismissedRatio;
  if (dismissedRatio !== null && dismissedRatio !== undefined) {
    if (dismissedRatio >= OPERATION_ALERT_QUALITY_CRITERIA.dismissedRatio.danger) {
      issues.push(operationAlertQualityIssue("dismissedRatio", "danger", dismissedRatio, "보류 비율이 위험 기준입니다.", "보류 사유를 검수하고 실제 해결 또는 정책 조정 항목으로 전환하십시오."));
    } else if (dismissedRatio >= OPERATION_ALERT_QUALITY_CRITERIA.dismissedRatio.warning) {
      issues.push(operationAlertQualityIssue("dismissedRatio", "warning", dismissedRatio, "보류 비율이 주의 기준입니다.", "반복 보류되는 경고 유형을 점검하십시오."));
    }
  }
  const reopenRate = metrics.reopenRate;
  if (reopenRate !== null && reopenRate !== undefined) {
    if (reopenRate >= OPERATION_ALERT_QUALITY_CRITERIA.reopenRate.danger) {
      issues.push(operationAlertQualityIssue("reopenRate", "danger", reopenRate, "재오픈 빈도가 위험 기준입니다.", "완료 판정 기준과 후속 검증 절차를 강화하십시오."));
    } else if (reopenRate >= OPERATION_ALERT_QUALITY_CRITERIA.reopenRate.warning) {
      issues.push(operationAlertQualityIssue("reopenRate", "warning", reopenRate, "재오픈 빈도가 주의 기준입니다.", "재오픈된 항목의 공통 원인을 확인하십시오."));
    }
  }
  const throughputRate = metrics.throughputRate;
  if (throughputRate !== null && throughputRate !== undefined && metrics.changeCount > 0) {
    if (throughputRate <= OPERATION_ALERT_QUALITY_CRITERIA.throughputRate.danger) {
      issues.push(operationAlertQualityIssue("throughputRate", "danger", throughputRate, "처리 전환율이 위험 기준입니다.", "담당자 배정과 목표일을 재조정하고 미처리 항목을 우선 처리하십시오."));
    } else if (throughputRate < OPERATION_ALERT_QUALITY_CRITERIA.throughputRate.warning) {
      issues.push(operationAlertQualityIssue("throughputRate", "warning", throughputRate, "처리 전환율이 주의 기준입니다.", "진행중 항목의 완료 조건을 명확히 하십시오."));
    }
  }
  const grade = issues.some((item) => item.level === "danger")
    ? "danger"
    : issues.some((item) => item.level === "warning")
      ? "warning"
      : "normal";
  return {
    grade,
    gradeLabel: operationAlertQualityGradeLabel(grade),
    issueCount: issues.length,
    issues,
    improvementItems: issues.map((item) => item.recommendation)
  };
}

function emptyOperationAlertQualityBucket(key = "total", label = "전체") {
  return {
    key,
    label,
    changeCount: 0,
    handledCount: 0,
    completedCount: 0,
    dismissedCount: 0,
    delayedResolvedCount: 0,
    reopenCount: 0,
    processingHoursTotal: 0,
    processingHoursSamples: 0
  };
}

function addOperationAlertQualityLog(bucket, log = {}, queueItem = {}) {
  const eventType = String(log.eventType || "").trim();
  const isResolved = ["completed", "dismissed"].includes(eventType);
  const isReopened = ["done", "dismissed"].includes(log.previousStatus) && ["open", "in_progress"].includes(log.nextStatus);
  bucket.changeCount += 1;
  if (eventType === "completed") bucket.completedCount += 1;
  if (eventType === "dismissed") bucket.dismissedCount += 1;
  if (isResolved) {
    bucket.handledCount += 1;
    if (operationAlertResolvedLate(log, queueItem)) bucket.delayedResolvedCount += 1;
    const startAt = queueItem.generatedAt || queueItem.createdAt || log.firstChangedAt || log.changedAt;
    const hours = operationAlertHoursBetween(startAt, log.changedAt);
    if (hours !== null) {
      bucket.processingHoursTotal += hours;
      bucket.processingHoursSamples += 1;
    }
  }
  if (isReopened) bucket.reopenCount += 1;
}

function finalizeOperationAlertQualityBucket(bucket = {}) {
  const handledCount = bucket.handledCount || 0;
  const changeCount = bucket.changeCount || 0;
  const avgProcessingHours = bucket.processingHoursSamples
    ? Number((bucket.processingHoursTotal / bucket.processingHoursSamples).toFixed(2))
    : null;
  const delayedResolutionRate = handledCount
    ? Math.round((bucket.delayedResolvedCount / handledCount) * 100)
    : null;
  const completedRatio = handledCount
    ? Math.round((bucket.completedCount / handledCount) * 100)
    : null;
  const dismissedRatio = handledCount
    ? Math.round((bucket.dismissedCount / handledCount) * 100)
    : null;
  const throughputRate = changeCount
    ? Math.round((handledCount / changeCount) * 100)
    : null;
  const reopenRate = handledCount
    ? Math.round(((bucket.reopenCount || 0) / handledCount) * 100)
    : changeCount
      ? Math.round(((bucket.reopenCount || 0) / changeCount) * 100)
      : null;
  const metrics = {
    key: bucket.key,
    label: bucket.label,
    changeCount,
    handledCount,
    completedCount: bucket.completedCount || 0,
    dismissedCount: bucket.dismissedCount || 0,
    delayedResolvedCount: bucket.delayedResolvedCount || 0,
    delayedResolutionRate,
    avgProcessingHours,
    completedRatio,
    dismissedRatio,
    reopenCount: bucket.reopenCount || 0,
    reopenRate,
    throughputRate
  };
  const health = operationAlertQualityHealth(metrics);
  return {
    ...metrics,
    healthGrade: health.grade,
    healthLabel: health.gradeLabel,
    warningIssues: health.issues,
    warningBadgeSummary: health.issues.map((issue) => ({
      field: issue.field,
      label: issue.label,
      level: issue.level,
      levelLabel: issue.levelLabel,
      value: issue.value,
      unit: issue.unit,
      message: issue.message
    })),
    improvementItemCount: health.improvementItems.length,
    improvementItems: health.improvementItems
  };
}

async function externalConnectorOperationAlertQuality(params = new URLSearchParams()) {
  const [queueData, logsData] = await Promise.all([
    readExternalConnectorOperationAlertQueue(),
    readExternalConnectorOperationAlertQueueLogs()
  ]);
  const logs = logsData.items || [];
  const filters = normalizeOperationAlertQualityFilters(params, logs);
  const queueById = new Map((queueData.items || []).map((item) => [item.queueItemId, item]));
  const firstLogByQueueId = new Map();
  for (const log of logs.slice().sort((a, b) => String(a.changedAt || "").localeCompare(String(b.changedAt || "")))) {
    if (log.queueItemId && !firstLogByQueueId.has(log.queueItemId)) firstLogByQueueId.set(log.queueItemId, log);
  }
  const filteredLogs = logs
    .filter((log) => !filters.month || monthKey(log.changedAt) === filters.month)
    .filter((log) => !filters.connectorId || log.connectorId === filters.connectorId)
    .map((log) => ({
      ...log,
      firstChangedAt: firstLogByQueueId.get(log.queueItemId)?.changedAt || log.changedAt
    }));
  const summaryBucket = emptyOperationAlertQualityBucket("total", "전체");
  const assigneeMap = new Map();
  const monthlyMap = new Map();
  for (const log of filteredLogs) {
    const queueItem = queueById.get(log.queueItemId) || {};
    const assignee = operationAlertLogAssignee(log, queueItem);
    const logMonth = monthKey(log.changedAt) || "unknown";
    if (!assigneeMap.has(assignee)) assigneeMap.set(assignee, emptyOperationAlertQualityBucket(assignee, assignee));
    if (!monthlyMap.has(logMonth)) monthlyMap.set(logMonth, emptyOperationAlertQualityBucket(logMonth, logMonth));
    addOperationAlertQualityLog(summaryBucket, log, queueItem);
    addOperationAlertQualityLog(assigneeMap.get(assignee), log, queueItem);
    addOperationAlertQualityLog(monthlyMap.get(logMonth), log, queueItem);
  }
  return {
    role: "admin",
    schema: "external_connector_operation_alert_quality_v1",
    generatedAt: new Date().toISOString(),
    filters,
    criteria: OPERATION_ALERT_QUALITY_CRITERIA,
    summary: finalizeOperationAlertQualityBucket(summaryBucket),
    byAssignee: [...assigneeMap.values()]
      .map(finalizeOperationAlertQualityBucket)
      .sort((a, b) => b.handledCount - a.handledCount || b.changeCount - a.changeCount || a.label.localeCompare(b.label)),
    monthly: [...monthlyMap.values()]
      .map(finalizeOperationAlertQualityBucket)
      .sort((a, b) => b.key.localeCompare(a.key)),
    sourceCounts: {
      logs: logs.length,
      filteredLogs: filteredLogs.length,
      queueItems: queueData.items?.length || 0
    }
  };
}

function normalizeOperationQualityActionStatus(value = "") {
  const text = String(value || "").trim();
  return ["candidate", "reviewing", "saved", "in_progress", "done", "dismissed"].includes(text) ? text : "candidate";
}

function operationQualityActionPriority(level = "") {
  if (level === "danger") return "high";
  if (level === "warning") return "medium";
  return "low";
}

function operationQualityPriorityRank(priority = "low") {
  return ({ low: 1, medium: 2, high: 3 }[String(priority || "").trim()] || 1);
}

function operationQualityPriorityFromRank(rank = 1) {
  if (rank >= 3) return "high";
  if (rank >= 2) return "medium";
  return "low";
}

function adjustOperationQualityPriority(priority = "low", step = 0) {
  return operationQualityPriorityFromRank(clampNumber(operationQualityPriorityRank(priority) + step, 1, 3));
}

function operationQualityActionDueDate(level = "") {
  return level === "danger" ? kstDate(3) : kstDate(7);
}

function operationQualityActionTitle(scopeType = "", row = {}, issue = {}) {
  const scopeLabel = scopeType === "assignee" ? `담당자 ${row.label || row.key || "미지정"}` : `${row.label || row.key || "월별"} 집계`;
  return `${scopeLabel} · ${issue.label || issue.field || "운영 품질"} 개선`;
}

function operationQualityActionCandidateFromIssue(quality = {}, scopeType = "monthly", row = {}, issue = {}) {
  const month = quality.filters?.month || row.key || monthKey(new Date().toISOString());
  const connectorId = quality.filters?.connectorId || "";
  const scopeKey = String(row.key || row.label || scopeType).trim();
  const field = String(issue.field || "").trim();
  const level = String(issue.level || row.healthGrade || "warning").trim();
  const actionId = hashId("xoqact", [month, connectorId || "all", scopeType, scopeKey, field, level].join("|"));
  const targetAssignee = scopeType === "assignee" && scopeKey !== "unassigned" ? scopeKey : "";
  return {
    actionId,
    status: "candidate",
    sourceType: "external_connector_operation_quality",
    sourceMonth: month,
    connectorId,
    scopeType,
    scopeKey,
    scopeLabel: row.label || row.key || "",
    title: operationQualityActionTitle(scopeType, row, issue),
    description: issue.message || "",
    rootMetric: field,
    rootMetricLabel: issue.label || field,
    rootMetricValue: issue.value ?? null,
    riskLevel: level,
    riskLabel: issue.levelLabel || operationAlertQualityGradeLabel(level),
    priority: operationQualityActionPriority(level),
    recommendedAction: issue.recommendation || "",
    assignee: targetAssignee,
    dueDate: operationQualityActionDueDate(level),
    memo: "",
    sourceSnapshot: {
      changeCount: row.changeCount || 0,
      handledCount: row.handledCount || 0,
      avgProcessingHours: row.avgProcessingHours ?? null,
      delayedResolutionRate: row.delayedResolutionRate ?? null,
      dismissedRatio: row.dismissedRatio ?? null,
      reopenRate: row.reopenRate ?? null,
      throughputRate: row.throughputRate ?? null
    },
    generatedAt: quality.generatedAt || new Date().toISOString(),
    sourceQualityFilters: quality.filters || {}
  };
}

function operationQualityActionCandidatesFromQuality(quality = {}) {
  const candidates = [];
  for (const row of quality.monthly || []) {
    if (!["warning", "danger"].includes(row.healthGrade)) continue;
    for (const issue of row.warningIssues || []) {
      candidates.push(operationQualityActionCandidateFromIssue(quality, "monthly", row, issue));
    }
  }
  for (const row of quality.byAssignee || []) {
    if (!["warning", "danger"].includes(row.healthGrade)) continue;
    for (const issue of row.warningIssues || []) {
      candidates.push(operationQualityActionCandidateFromIssue(quality, "assignee", row, issue));
    }
  }
  return candidates;
}

function operationQualityActionMatchesFilters(item = {}, filters = {}) {
  return (!filters.month || item.sourceMonth === filters.month)
    && (!filters.connectorId || item.connectorId === filters.connectorId);
}

function operationQualityActionDueState(item = {}, today = kstDate(0)) {
  const status = normalizeOperationQualityActionStatus(item.status);
  if (["done", "dismissed"].includes(status)) return "closed";
  const dueDate = String(item.dueDate || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) return "no_due";
  if (dueDate < today) return "overdue";
  if (dueDate <= kstDate(7)) return "this_week";
  return "upcoming";
}

function normalizeOperationQualityActionFilters(params = new URLSearchParams(), qualityFilters = {}) {
  return {
    month: qualityFilters.month || "",
    connectorId: qualityFilters.connectorId || "",
    status: normalizeOperationQualityActionStatus(params.get("status") || ""),
    statusProvided: Boolean(params.get("status")),
    assignee: compactKeyword(params.get("assignee") || ""),
    dueState: String(params.get("dueState") || "").trim(),
    priority: String(params.get("priority") || "").trim(),
    riskLevel: String(params.get("riskLevel") || "").trim(),
    rootMetric: String(params.get("rootMetric") || "").trim()
  };
}

function filterOperationQualityActionItems(items = [], filters = {}) {
  return items
    .filter((item) => !filters.statusProvided || normalizeOperationQualityActionStatus(item.status) === filters.status)
    .filter((item) => !filters.assignee || compactKeyword(item.assignee || "unassigned").includes(filters.assignee))
    .filter((item) => !filters.dueState || operationQualityActionDueState(item) === filters.dueState)
    .filter((item) => !filters.priority || item.priority === filters.priority)
    .filter((item) => !filters.riskLevel || item.riskLevel === filters.riskLevel)
    .filter((item) => !filters.rootMetric || item.rootMetric === filters.rootMetric);
}

function mergeOperationQualityActions(candidates = [], savedItems = [], filters = {}) {
  const candidateById = new Map(candidates.map((item) => [item.actionId, item]));
  const merged = candidates.map((candidate) => {
    const saved = savedItems.find((item) => item.actionId === candidate.actionId) || {};
    return {
      ...candidate,
      ...saved,
      currentCandidate: true,
      stale: false,
      status: normalizeOperationQualityActionStatus(saved.status || candidate.status),
      assignee: String(saved.assignee ?? candidate.assignee ?? "").trim(),
      dueDate: String(saved.dueDate ?? candidate.dueDate ?? "").trim(),
      memo: String(saved.memo ?? candidate.memo ?? "").trim(),
      dueState: operationQualityActionDueState({ ...candidate, ...saved })
    };
  });
  for (const saved of savedItems) {
    if (candidateById.has(saved.actionId)) continue;
    if (!operationQualityActionMatchesFilters(saved, filters)) continue;
    merged.push({
      ...saved,
      currentCandidate: false,
      stale: true,
      status: normalizeOperationQualityActionStatus(saved.status),
      dueState: operationQualityActionDueState(saved)
    });
  }
  return merged.sort((a, b) => {
    const levelRank = { danger: 3, warning: 2, normal: 1 };
    const priorityRank = { high: 3, medium: 2, low: 1 };
    return (levelRank[b.riskLevel] || 0) - (levelRank[a.riskLevel] || 0)
      || (priorityRank[b.priority] || 0) - (priorityRank[a.priority] || 0)
      || String(a.dueDate || "9999-12-31").localeCompare(String(b.dueDate || "9999-12-31"))
      || String(a.scopeLabel || "").localeCompare(String(b.scopeLabel || ""));
  });
}

function operationQualityActionSummary(items = []) {
  const byStatus = items.reduce((acc, item) => {
    const status = normalizeOperationQualityActionStatus(item.status);
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  const unresolved = items.filter((item) => !["candidate", "done", "dismissed"].includes(normalizeOperationQualityActionStatus(item.status)));
  return {
    total: items.length,
    candidate: byStatus.candidate || 0,
    reviewing: byStatus.reviewing || 0,
    saved: byStatus.saved || 0,
    inProgress: byStatus.in_progress || 0,
    done: byStatus.done || 0,
    dismissed: byStatus.dismissed || 0,
    danger: items.filter((item) => item.riskLevel === "danger").length,
    warning: items.filter((item) => item.riskLevel === "warning").length,
    overdue: unresolved.filter((item) => operationQualityActionDueState(item) === "overdue").length,
    thisWeek: unresolved.filter((item) => operationQualityActionDueState(item) === "this_week").length,
    unresolved: unresolved.length,
    completedWithSnapshot: items.filter((item) => item.completionQualitySnapshot).length,
    stale: items.filter((item) => item.stale).length,
    byStatus
  };
}

function operationQualityActionFocus(items = []) {
  const unresolved = items.filter((item) => !["candidate", "done", "dismissed"].includes(normalizeOperationQualityActionStatus(item.status)));
  const overdue = unresolved.filter((item) => operationQualityActionDueState(item) === "overdue");
  const thisWeek = unresolved.filter((item) => operationQualityActionDueState(item) === "this_week");
  const ownerMap = new Map();
  for (const item of unresolved) {
    const owner = String(item.assignee || "unassigned").trim() || "unassigned";
    if (!ownerMap.has(owner)) ownerMap.set(owner, { owner, open: 0, overdue: 0, highRisk: 0 });
    const row = ownerMap.get(owner);
    row.open += 1;
    if (operationQualityActionDueState(item) === "overdue") row.overdue += 1;
    if (item.riskLevel === "danger" || item.priority === "high") row.highRisk += 1;
  }
  return {
    overdue: overdue.slice(0, 8),
    thisWeek: thisWeek.slice(0, 8),
    ownerUnresolved: [...ownerMap.values()].sort((a, b) => b.overdue - a.overdue || b.highRisk - a.highRisk || b.open - a.open || a.owner.localeCompare(b.owner))
  };
}

async function externalConnectorOperationQualityActions(params = new URLSearchParams()) {
  const [quality, saved, history] = await Promise.all([
    externalConnectorOperationAlertQuality(params),
    readExternalConnectorOperationQualityActions(),
    readExternalConnectorOperationQualityActionReassessmentHistory()
  ]);
  const historyItems = (history.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const rawCandidates = operationQualityActionCandidatesFromQuality(quality);
  const adjustmentData = await upsertOperationQualityRecommendationAdjustmentProposals(rawCandidates, historyItems);
  const candidates = applyOperationQualityActionHistoryAdjustments(
    rawCandidates,
    historyItems,
    adjustmentData.items || []
  );
  const merged = mergeOperationQualityActions(candidates, saved.items || [], quality.filters || {});
  const actionFilters = normalizeOperationQualityActionFilters(params, quality.filters || {});
  const filtered = filterOperationQualityActionItems(merged, actionFilters);
  return {
    role: "admin",
    schema: "external_connector_operation_quality_action_queue_v1",
    generatedAt: new Date().toISOString(),
    filters: actionFilters,
    sourceQuality: {
      summary: quality.summary,
      criteria: quality.criteria
    },
    summary: operationQualityActionSummary(filtered),
    totalSummary: operationQualityActionSummary(merged),
    recommendationLearning: operationQualityActionHistoryAdjustmentSummary(filtered),
    focus: operationQualityActionFocus(filtered),
    items: filtered
  };
}

async function updateExternalConnectorOperationQualityAction(actionId = "", payload = {}) {
  const sourceFilters = payload.sourceQualityFilters || {};
  const params = new URLSearchParams();
  if (sourceFilters.month) params.set("month", sourceFilters.month);
  if (sourceFilters.connectorId) params.set("connectorId", sourceFilters.connectorId);
  const current = await externalConnectorOperationQualityActions(params);
  const currentItem = (current.items || []).find((item) => item.actionId === actionId);
  if (!currentItem) return null;
  const saved = await readExternalConnectorOperationQualityActions();
  const items = saved.items || [];
  const index = items.findIndex((item) => item.actionId === actionId);
  const existing = index >= 0 ? items[index] : {};
  const previousStatus = normalizeOperationQualityActionStatus(existing.status || currentItem.status);
  const status = normalizeOperationQualityActionStatus(payload.status || existing.status || currentItem.status || "saved");
  const now = new Date().toISOString();
  const activeHistoryAdjustment = Boolean(currentItem.historyPriorityAdjustment?.active);
  const updated = {
    ...currentItem,
    ...existing,
    status: status === "candidate" ? "saved" : status,
    assignee: String(payload.assignee ?? existing.assignee ?? currentItem.assignee ?? "").trim(),
    dueDate: String(payload.dueDate ?? existing.dueDate ?? currentItem.dueDate ?? "").trim(),
    memo: String(payload.memo ?? existing.memo ?? currentItem.memo ?? "").trim(),
    originalPriority: currentItem.originalPriority || existing.originalPriority || currentItem.priority || "",
    priority: activeHistoryAdjustment ? currentItem.priority : (existing.priority || currentItem.priority || ""),
    priorityAdjusted: activeHistoryAdjustment ? Boolean(currentItem.priorityAdjusted) : Boolean(existing.priorityAdjusted),
    historyPriorityAdjustment: currentItem.historyPriorityAdjustment || existing.historyPriorityAdjustment || null,
    recommendationCorrectionBasis: activeHistoryAdjustment ? (currentItem.recommendationCorrectionBasis || "") : (existing.recommendationCorrectionBasis || ""),
    recommendedAction: activeHistoryAdjustment ? (currentItem.recommendedAction || existing.recommendedAction || "") : (existing.recommendedAction || currentItem.recommendedAction || ""),
    updatedBy: String(payload.updatedBy || existing.updatedBy || "admin").trim(),
    updatedAt: now,
    savedAt: existing.savedAt || now,
    completedAt: status === "done" ? (existing.completedAt || now) : existing.completedAt || null,
    completionQualitySnapshot: status === "done" && previousStatus !== "done"
      ? {
          capturedAt: now,
          filters: current.filters || {},
          summary: current.sourceQuality?.summary || {},
          criteria: current.sourceQuality?.criteria || {},
          actionSourceSnapshot: currentItem.sourceSnapshot || {}
        }
      : existing.completionQualitySnapshot || null
  };
  if (index >= 0) items[index] = updated;
  else items.push(updated);
  const next = await writeExternalConnectorOperationQualityActions({
    ...saved,
    items: items.sort((a, b) => String(b.updatedAt || b.generatedAt || "").localeCompare(String(a.updatedAt || a.generatedAt || "")))
  });
  return {
    item: updated,
    counts: {
      externalConnectorOperationQualityActions: next.items.length
    }
  };
}

function operationQualityActionMetricDefinition(metric = "") {
  return OPERATION_ALERT_QUALITY_CRITERIA[metric] || {
    label: metric || "unknown",
    warning: null,
    danger: null,
    unit: "",
    lowerIsBetter: true
  };
}

function operationQualityActionMetricValue(source = {}, metric = "") {
  const direct = Number(source?.[metric]);
  if (Number.isFinite(direct)) return direct;
  return null;
}

function operationQualityActionReassessmentCurrentRow(quality = {}, action = {}) {
  const scopeType = String(action.scopeType || "").trim();
  if (scopeType === "assignee") {
    const scopeKey = String(action.scopeKey || action.assignee || "").trim();
    const scopeLabel = String(action.scopeLabel || "").trim();
    const row = (quality.byAssignee || []).find((item) => (
      String(item.key || "").trim() === scopeKey
      || String(item.label || "").trim() === scopeLabel
      || String(item.key || "").trim() === String(action.assignee || "").trim()
    ));
    if (row) return row;
  }
  if (scopeType === "monthly") {
    const sourceMonth = String(action.sourceMonth || quality.filters?.month || "").trim();
    const row = (quality.monthly || []).find((item) => String(item.key || "").trim() === sourceMonth);
    if (row) return row;
  }
  return quality.summary || {};
}

function operationQualityActionEffectScore(metric = "", beforeValue = null, currentValue = null, currentGrade = "normal", recurrence = false, currentDataMissing = false) {
  const definition = operationQualityActionMetricDefinition(metric);
  let score = 50;
  if (currentDataMissing) score -= 10;
  if (Number.isFinite(Number(beforeValue)) && Number.isFinite(Number(currentValue))) {
    const before = Number(beforeValue);
    const current = Number(currentValue);
    const improvement = definition.lowerIsBetter === false ? current - before : before - current;
    const scaleBase = Math.max(
      Math.abs(before),
      Math.abs(current),
      Math.abs(Number(definition.warning || 0)),
      Math.abs(Number(definition.danger || 0)),
      1
    );
    score += clampNumber((improvement / scaleBase) * 50, -35, 35);
  }
  if (currentGrade === "normal") score += 15;
  if (currentGrade === "warning") score -= 5;
  if (currentGrade === "danger") score -= 20;
  if (recurrence) score -= 15;
  return Math.round(clampNumber(score, 0, 100));
}

function operationQualityActionImprovementState(metric = "", beforeValue = null, currentValue = null) {
  if (!Number.isFinite(Number(beforeValue)) || !Number.isFinite(Number(currentValue))) return "unknown";
  const definition = operationQualityActionMetricDefinition(metric);
  const before = Number(beforeValue);
  const current = Number(currentValue);
  const delta = definition.lowerIsBetter === false ? current - before : before - current;
  const tolerance = Math.max(Math.abs(before) * 0.05, 1);
  if (delta > tolerance) return "improved";
  if (delta < -tolerance) return "worse";
  return "unchanged";
}

function operationQualityActionReassessmentOutcome(metric = "", beforeValue = null, currentValue = null, currentGrade = "normal", recurrence = false, effectScore = 50, currentDataMissing = false) {
  if (currentDataMissing) return "unchanged";
  const state = operationQualityActionImprovementState(metric, beforeValue, currentValue);
  if ((recurrence && effectScore < 60) || currentGrade === "danger" || effectScore <= 40 || state === "worse") return "worse";
  if (state === "improved" && effectScore >= 60 && !recurrence) return "improved";
  if (currentGrade === "normal" && effectScore >= 70 && !recurrence) return "improved";
  return "unchanged";
}

function operationQualityActionReassessmentReason(reassessment = {}) {
  if (reassessment.currentDataMissing) return "완료 이후 비교 가능한 최신 운영 품질 지표가 부족합니다.";
  if (reassessment.recurrence) return "완료 후에도 동일 원인 지표가 주의/위험 범위에 다시 감지됐습니다.";
  if (reassessment.outcome === "worse") return "완료 시점 대비 최신 운영 품질 지표가 악화됐습니다.";
  if (reassessment.outcome === "improved") return "완료 시점 대비 최신 운영 품질 지표가 개선됐습니다.";
  return "완료 이후 지표 변화가 크지 않아 추가 모니터링이 필요합니다.";
}

function operationQualityActionReassessmentItem(action = {}, quality = {}, followUpActionIds = []) {
  const metric = String(action.rootMetric || "").trim();
  const definition = operationQualityActionMetricDefinition(metric);
  const currentRow = operationQualityActionReassessmentCurrentRow(quality, action);
  const baselineSnapshot = action.completionQualitySnapshot?.actionSourceSnapshot || action.sourceSnapshot || {};
  const baselineValue = operationQualityActionMetricValue(baselineSnapshot, metric) ?? operationQualityActionMetricValue(action, "rootMetricValue");
  const currentValue = operationQualityActionMetricValue(currentRow, metric);
  const currentDataMissing = currentValue === null;
  const activeIssue = (currentRow.warningIssues || []).find((issue) => String(issue.field || "").trim() === metric);
  const recurrence = Boolean(activeIssue && ["warning", "danger"].includes(activeIssue.level));
  const currentGrade = currentRow.healthGrade || quality.summary?.healthGrade || "normal";
  const baselineGrade = action.completionQualitySnapshot?.summary?.healthGrade || action.riskLevel || "warning";
  const effectScore = operationQualityActionEffectScore(metric, baselineValue, currentValue, currentGrade, recurrence, currentDataMissing);
  const outcome = operationQualityActionReassessmentOutcome(metric, baselineValue, currentValue, currentGrade, recurrence, effectScore, currentDataMissing);
  const metricDelta = Number.isFinite(Number(baselineValue)) && Number.isFinite(Number(currentValue))
    ? Number((Number(currentValue) - Number(baselineValue)).toFixed(2))
    : null;
  const followUpNeeded = Boolean(currentDataMissing || recurrence || outcome === "worse" || effectScore < 60 || currentGrade === "danger");
  const reassessment = {
    actionId: action.actionId,
    title: action.title || "",
    sourceActionId: action.sourceActionId || "",
    sourceMonth: action.sourceMonth || quality.filters?.month || "",
    connectorId: action.connectorId || quality.filters?.connectorId || "",
    scopeType: action.scopeType || "",
    scopeKey: action.scopeKey || "",
    scopeLabel: action.scopeLabel || "",
    assignee: action.assignee || "",
    completedAt: action.completedAt || action.updatedAt || "",
    evaluatedAt: new Date().toISOString(),
    rootMetric: metric,
    rootMetricLabel: action.rootMetricLabel || definition.label || metric,
    unit: definition.unit || "",
    baselineValue,
    currentValue,
    metricDelta,
    baselineGrade,
    currentGrade,
    currentGradeLabel: operationAlertQualityGradeLabel(currentGrade),
    effectScore,
    outcome,
    outcomeLabel: ({ improved: "개선", unchanged: "유지", worse: "악화" }[outcome] || "유지"),
    recurrence,
    currentDataMissing,
    followUpNeeded,
    followUpReason: "",
    recommendedFollowUpAction: followUpNeeded
      ? "후속 개선 액션을 열어 원인 지표를 재점검하고 목표일/담당자를 다시 배정하십시오."
      : "현재는 추가 액션 없이 다음 운영 품질 집계에서 재확인하십시오.",
    followUpCreated: followUpActionIds.length > 0,
    followUpActionIds,
    completionQualitySnapshot: action.completionQualitySnapshot || null,
    baselineSnapshot,
    currentQualitySnapshot: {
      capturedAt: quality.generatedAt || new Date().toISOString(),
      filters: quality.filters || {},
      metrics: currentRow,
      activeIssue: activeIssue || null
    },
    sourceQualityFilters: quality.filters || {},
    sourceAction: action
  };
  reassessment.followUpReason = operationQualityActionReassessmentReason(reassessment);
  return reassessment;
}

function normalizeOperationQualityActionReassessmentFilters(params = new URLSearchParams(), qualityFilters = {}) {
  const limit = Math.max(1, Math.min(200, Number(params.get("limit") || 80)));
  return {
    month: qualityFilters.month || "",
    connectorId: qualityFilters.connectorId || "",
    outcome: String(params.get("outcome") || "").trim(),
    followUp: String(params.get("followUp") || "").trim(),
    assignee: compactKeyword(params.get("assignee") || ""),
    riskLevel: String(params.get("riskLevel") || "").trim(),
    rootMetric: String(params.get("rootMetric") || "").trim(),
    limit
  };
}

function filterOperationQualityActionReassessmentItems(items = [], filters = {}) {
  return items
    .filter((item) => !filters.outcome || item.outcome === filters.outcome)
    .filter((item) => filters.followUp === "needed" ? item.followUpNeeded : filters.followUp === "none" ? !item.followUpNeeded : true)
    .filter((item) => !filters.assignee || compactKeyword(item.assignee || "unassigned").includes(filters.assignee))
    .filter((item) => !filters.riskLevel || item.currentGrade === filters.riskLevel || item.baselineGrade === filters.riskLevel)
    .filter((item) => !filters.rootMetric || item.rootMetric === filters.rootMetric);
}

function operationQualityActionReassessmentSummary(items = []) {
  const total = items.length;
  const scoreItems = items.filter((item) => Number.isFinite(Number(item.effectScore)));
  return {
    total,
    improved: items.filter((item) => item.outcome === "improved").length,
    unchanged: items.filter((item) => item.outcome === "unchanged").length,
    worse: items.filter((item) => item.outcome === "worse").length,
    recurrence: items.filter((item) => item.recurrence).length,
    followUpNeeded: items.filter((item) => item.followUpNeeded).length,
    followUpCreated: items.filter((item) => item.followUpCreated).length,
    currentDataMissing: items.filter((item) => item.currentDataMissing).length,
    averageEffectScore: scoreItems.length
      ? Math.round(scoreItems.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / scoreItems.length)
      : 0
  };
}

function operationQualityActionReassessmentHistoryId(item = {}) {
  return hashId("xoqrh", [
    item.actionId || "",
    item.sourceMonth || item.evaluatedMonth || "",
    item.rootMetric || "",
    item.completedAt || ""
  ].join("|"));
}

function normalizeOperationQualityActionReassessmentHistoryItem(input = {}) {
  const evaluatedAt = input.evaluatedAt || new Date().toISOString();
  const evaluatedDate = String(input.evaluatedDate || evaluatedAt).slice(0, 10);
  const evaluatedMonth = String(input.evaluatedMonth || monthKey(evaluatedAt) || monthKey(evaluatedDate) || "unknown");
  const effectScore = Math.round(clampNumber(input.effectScore ?? 0, 0, 100));
  const followUpActionIds = Array.isArray(input.followUpActionIds)
    ? [...new Set(input.followUpActionIds.filter(Boolean).map(String))]
    : String(input.followUpActionId || "").trim()
      ? [String(input.followUpActionId).trim()]
      : [];
  const normalized = {
    historyId: String(input.historyId || "").trim(),
    actionId: String(input.actionId || "").trim(),
    sourceActionId: String(input.sourceActionId || "").trim(),
    title: String(input.title || "").trim(),
    sourceMonth: String(input.sourceMonth || "").trim(),
    connectorId: String(input.connectorId || "").trim(),
    scopeType: String(input.scopeType || "").trim(),
    scopeKey: String(input.scopeKey || "").trim(),
    scopeLabel: String(input.scopeLabel || "").trim(),
    assignee: String(input.assignee || "unassigned").trim() || "unassigned",
    completedAt: input.completedAt || "",
    evaluatedAt,
    evaluatedDate,
    evaluatedMonth,
    rootMetric: String(input.rootMetric || "").trim(),
    rootMetricLabel: String(input.rootMetricLabel || input.rootMetric || "").trim(),
    unit: String(input.unit || "").trim(),
    baselineValue: input.baselineValue ?? null,
    currentValue: input.currentValue ?? null,
    metricDelta: input.metricDelta ?? null,
    baselineGrade: String(input.baselineGrade || "").trim(),
    currentGrade: String(input.currentGrade || "").trim(),
    currentGradeLabel: String(input.currentGradeLabel || operationAlertQualityGradeLabel(input.currentGrade || "")).trim(),
    effectScore,
    outcome: String(input.outcome || "unchanged").trim() || "unchanged",
    outcomeLabel: String(input.outcomeLabel || "").trim(),
    recurrence: Boolean(input.recurrence),
    currentDataMissing: Boolean(input.currentDataMissing),
    followUpNeeded: Boolean(input.followUpNeeded),
    followUpReason: String(input.followUpReason || "").trim(),
    followUpCreated: Boolean(input.followUpCreated || followUpActionIds.length),
    followUpActionIds,
    followUpCreatedAt: input.followUpCreatedAt || "",
    recommendedFollowUpAction: String(input.recommendedFollowUpAction || "").trim(),
    sourceQualityFilters: input.sourceQualityFilters && typeof input.sourceQualityFilters === "object" ? input.sourceQualityFilters : {},
    baselineSnapshot: input.baselineSnapshot && typeof input.baselineSnapshot === "object" ? input.baselineSnapshot : {},
    currentQualitySnapshot: input.currentQualitySnapshot && typeof input.currentQualitySnapshot === "object" ? input.currentQualitySnapshot : {},
    firstRecordedAt: input.firstRecordedAt || input.recordedAt || new Date().toISOString(),
    recordedAt: input.recordedAt || new Date().toISOString(),
    recordedBy: String(input.recordedBy || "system").trim() || "system",
    revisionCount: Math.max(1, Number(input.revisionCount || 1))
  };
  return {
    ...normalized,
    historyId: normalized.historyId || operationQualityActionReassessmentHistoryId(normalized)
  };
}

function historyItemFromOperationQualityReassessment(item = {}, options = {}) {
  const followUpAction = options.followUpAction || null;
  return normalizeOperationQualityActionReassessmentHistoryItem({
    ...item,
    followUpCreated: Boolean(item.followUpCreated || followUpAction || options.followUpCreated),
    followUpActionIds: [
      ...((item.followUpActionIds || []).filter(Boolean)),
      followUpAction?.actionId || options.followUpActionId || ""
    ].filter(Boolean),
    followUpCreatedAt: followUpAction?.updatedAt || followUpAction?.savedAt || followUpAction?.generatedAt || options.followUpCreatedAt || item.followUpCreatedAt || "",
    recordedBy: options.recordedBy || "system"
  });
}

async function upsertExternalConnectorOperationQualityActionReassessmentHistoryItems(items = [], options = {}) {
  const normalized = items
    .map((item) => historyItemFromOperationQualityReassessment(item, options))
    .filter((item) => item.actionId && item.historyId);
  if (!normalized.length) {
    return {
      externalConnectorOperationQualityActionReassessmentHistory: null,
      upserted: 0,
      items: []
    };
  }
  const data = await readExternalConnectorOperationQualityActionReassessmentHistory();
  const existing = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityActionReassessmentHistoryItem)
    : [];
  const byId = new Map(existing.map((item) => [item.historyId, item]));
  normalized.forEach((item) => {
    const previous = byId.get(item.historyId);
    const followUpActionIds = [...new Set([
      ...((previous?.followUpActionIds || []).filter(Boolean)),
      ...((item.followUpActionIds || []).filter(Boolean))
    ])];
    byId.set(item.historyId, normalizeOperationQualityActionReassessmentHistoryItem({
      ...(previous || {}),
      ...item,
      firstRecordedAt: previous?.firstRecordedAt || item.firstRecordedAt,
      revisionCount: (previous?.revisionCount || 0) + 1,
      followUpCreated: Boolean(previous?.followUpCreated || item.followUpCreated || followUpActionIds.length),
      followUpActionIds,
      followUpCreatedAt: item.followUpCreatedAt || previous?.followUpCreatedAt || ""
    }));
  });
  const updated = await writeExternalConnectorOperationQualityActionReassessmentHistory({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")))
  });
  return {
    externalConnectorOperationQualityActionReassessmentHistory: {
      schema: updated.schema || "external_connector_operation_quality_action_reassessment_history_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    upserted: normalized.length,
    items: normalized
  };
}

async function markExternalConnectorOperationQualityActionReassessmentHistoryFollowUp(sourceItem = {}, followUpAction = {}, recordedBy = "admin") {
  const upsert = await upsertExternalConnectorOperationQualityActionReassessmentHistoryItems([sourceItem], {
    followUpAction,
    recordedBy,
    followUpCreated: true
  });
  return {
    externalConnectorOperationQualityActionReassessmentHistory: upsert.externalConnectorOperationQualityActionReassessmentHistory,
    updated: upsert.upserted,
    item: upsert.items?.[0] || null
  };
}

function operationQualityActionReassessmentHistoryParam(params = {}, key = "") {
  if (params && typeof params.get === "function") return params.get(key) || "";
  return params?.[key] || "";
}

function filterOperationQualityActionReassessmentHistoryItems(items = [], params = {}) {
  const month = String(operationQualityActionReassessmentHistoryParam(params, "month") || "").trim();
  const connectorId = operationQualityActionReassessmentHistoryParam(params, "connectorId")
    ? normalizeExternalConnectorId(operationQualityActionReassessmentHistoryParam(params, "connectorId"))
    : "";
  const assignee = compactKeyword(operationQualityActionReassessmentHistoryParam(params, "assignee") || "");
  const rootMetric = String(operationQualityActionReassessmentHistoryParam(params, "rootMetric") || "").trim();
  const outcome = String(operationQualityActionReassessmentHistoryParam(params, "outcome") || "").trim();
  const followUp = String(operationQualityActionReassessmentHistoryParam(params, "followUp") || "").trim();
  return items
    .filter((item) => !month || item.sourceMonth === month || item.evaluatedMonth === month)
    .filter((item) => !connectorId || item.connectorId === connectorId)
    .filter((item) => !assignee || compactKeyword(item.assignee || "unassigned").includes(assignee))
    .filter((item) => !rootMetric || item.rootMetric === rootMetric)
    .filter((item) => !outcome || item.outcome === outcome)
    .filter((item) => followUp === "created" ? item.followUpCreated : followUp === "needed" ? item.followUpNeeded : followUp === "none" ? !item.followUpNeeded : true);
}

function operationQualityActionReassessmentHistoryGroups(items = [], keyFn = () => "", labelFn = (key) => key) {
  const groups = new Map();
  for (const item of items) {
    const key = String(keyFn(item) || "unknown").trim() || "unknown";
    if (!groups.has(key)) {
      groups.set(key, {
        key,
        label: labelFn(key, item),
        total: 0,
        improved: 0,
        unchanged: 0,
        worse: 0,
        recurrence: 0,
        followUpNeeded: 0,
        followUpCreated: 0,
        effectScoreTotal: 0
      });
    }
    const row = groups.get(key);
    row.total += 1;
    row.improved += item.outcome === "improved" ? 1 : 0;
    row.unchanged += item.outcome === "unchanged" ? 1 : 0;
    row.worse += item.outcome === "worse" ? 1 : 0;
    row.recurrence += item.recurrence ? 1 : 0;
    row.followUpNeeded += item.followUpNeeded ? 1 : 0;
    row.followUpCreated += item.followUpCreated ? 1 : 0;
    row.effectScoreTotal += Number(item.effectScore || 0);
  }
  return [...groups.values()].map((row) => ({
    ...row,
    averageEffectScore: row.total ? Math.round(row.effectScoreTotal / row.total) : 0,
    improvedRate: row.total ? Math.round((row.improved / row.total) * 100) : 0,
    worseRate: row.total ? Math.round((row.worse / row.total) * 100) : 0,
    recurrenceRate: row.total ? Math.round((row.recurrence / row.total) * 100) : 0,
    followUpCreatedRate: row.followUpNeeded ? Math.round((row.followUpCreated / row.followUpNeeded) * 100) : 0
  }));
}

function operationQualityActionReassessmentHistoryAggregates(items = []) {
  const byRootMetric = operationQualityActionReassessmentHistoryGroups(
    items,
    (item) => item.rootMetric || "unknown",
    (key, item) => item.rootMetricLabel || key
  ).sort((a, b) => b.total - a.total || b.averageEffectScore - a.averageEffectScore || a.label.localeCompare(b.label));
  return {
    byMonth: operationQualityActionReassessmentHistoryGroups(items, (item) => item.sourceMonth || item.evaluatedMonth || "unknown")
      .sort((a, b) => b.key.localeCompare(a.key)),
    byAssignee: operationQualityActionReassessmentHistoryGroups(items, (item) => item.assignee || "unassigned")
      .sort((a, b) => b.total - a.total || b.averageEffectScore - a.averageEffectScore || a.label.localeCompare(b.label)),
    byRootMetric,
    effectiveActionTypes: [...byRootMetric]
      .filter((row) => row.total > 0)
      .sort((a, b) => b.averageEffectScore - a.averageEffectScore || b.improvedRate - a.improvedRate || a.label.localeCompare(b.label))
      .slice(0, 5),
    weakActionTypes: [...byRootMetric]
      .filter((row) => row.total > 0)
      .sort((a, b) => a.averageEffectScore - b.averageEffectScore || b.worseRate - a.worseRate || b.recurrenceRate - a.recurrenceRate || a.label.localeCompare(b.label))
      .slice(0, 5)
  };
}

function operationQualityActionHistoryEvidence(action = {}, historyItems = []) {
  const metric = String(action.rootMetric || "").trim();
  const assignee = String(action.assignee || (action.scopeType === "assignee" ? action.scopeKey : "") || "").trim();
  const sourceMonth = String(action.sourceMonth || "").trim();
  const evidence = [];
  for (const item of historyItems) {
    let weight = 0;
    const dimensions = [];
    if (metric && item.rootMetric === metric) {
      weight += 1;
      dimensions.push("metric");
    }
    if (assignee && item.assignee === assignee) {
      weight += 0.45;
      dimensions.push("assignee");
    }
    if (sourceMonth && (item.sourceMonth === sourceMonth || item.evaluatedMonth === sourceMonth)) {
      weight += 0.25;
      dimensions.push("month");
    }
    if (weight > 0) evidence.push({ item, weight, dimensions });
  }
  const weightTotal = evidence.reduce((sum, row) => sum + row.weight, 0);
  const sampleIds = new Set(evidence.map((row) => row.item.historyId || row.item.actionId).filter(Boolean));
  if (!weightTotal) {
    return {
      sampleSize: 0,
      weightedSampleSize: 0,
      historyEffectScore: 0,
      improvedRate: 0,
      worseRate: 0,
      recurrenceRate: 0,
      followUpNeededRate: 0,
      metricSampleSize: 0,
      assigneeSampleSize: 0,
      monthSampleSize: 0
    };
  }
  const weighted = (predicate) => evidence.reduce((sum, row) => sum + (predicate(row.item) ? row.weight : 0), 0);
  return {
    sampleSize: sampleIds.size,
    weightedSampleSize: Number(weightTotal.toFixed(2)),
    historyEffectScore: Math.round(evidence.reduce((sum, row) => sum + Number(row.item.effectScore || 0) * row.weight, 0) / weightTotal),
    improvedRate: Math.round((weighted((item) => item.outcome === "improved") / weightTotal) * 100),
    worseRate: Math.round((weighted((item) => item.outcome === "worse") / weightTotal) * 100),
    recurrenceRate: Math.round((weighted((item) => item.recurrence) / weightTotal) * 100),
    followUpNeededRate: Math.round((weighted((item) => item.followUpNeeded) / weightTotal) * 100),
    metricSampleSize: new Set(evidence.filter((row) => row.dimensions.includes("metric")).map((row) => row.item.historyId || row.item.actionId).filter(Boolean)).size,
    assigneeSampleSize: new Set(evidence.filter((row) => row.dimensions.includes("assignee")).map((row) => row.item.historyId || row.item.actionId).filter(Boolean)).size,
    monthSampleSize: new Set(evidence.filter((row) => row.dimensions.includes("month")).map((row) => row.item.historyId || row.item.actionId).filter(Boolean)).size
  };
}

function operationQualityActionHistoryPriorityAdjustment(action = {}, historyItems = []) {
  const evidence = operationQualityActionHistoryEvidence(action, historyItems);
  const originalPriority = action.priority || operationQualityActionPriority(action.riskLevel);
  let adjustedPriority = originalPriority;
  let direction = "none";
  const reasons = [];
  if (!evidence.sampleSize) {
    return {
      applied: false,
      direction,
      originalPriority,
      adjustedPriority,
      delta: 0,
      ...evidence,
      adminReason: "No reassessment history matched this action yet."
    };
  }
  if (evidence.historyEffectScore >= 70 && evidence.improvedRate >= 50 && evidence.recurrenceRate <= 25) {
    adjustedPriority = adjustOperationQualityPriority(originalPriority, 1);
    direction = adjustedPriority === originalPriority ? "reinforce" : "boost";
    reasons.push(`History score ${evidence.historyEffectScore} with ${evidence.improvedRate}% improved results.`);
    reasons.push("Similar completed actions were effective, so this recommendation should be handled earlier.");
  } else if (evidence.historyEffectScore < 45 || evidence.recurrenceRate >= 50 || evidence.worseRate >= 50) {
    adjustedPriority = adjustOperationQualityPriority(originalPriority, -1);
    direction = adjustedPriority === originalPriority ? "caution" : "downgrade";
    reasons.push(`History score ${evidence.historyEffectScore}, recurrence ${evidence.recurrenceRate}%, worse ${evidence.worseRate}%.`);
    reasons.push("Similar actions had weak or recurring outcomes, so validate the cause before relying on this action.");
  } else if (evidence.historyEffectScore < 60 || evidence.followUpNeededRate >= 50) {
    direction = "caution";
    reasons.push(`History score ${evidence.historyEffectScore} with follow-up need ${evidence.followUpNeededRate}%.`);
    reasons.push("Keep priority but add review caution because outcomes were not stable enough.");
  }
  return {
    applied: direction !== "none",
    direction,
    originalPriority,
    adjustedPriority,
    delta: operationQualityPriorityRank(adjustedPriority) - operationQualityPriorityRank(originalPriority),
    ...evidence,
    adminReason: reasons.join(" ")
  };
}

const EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY = Object.freeze({
  policyVersion: "external_connector_operation_quality_auto_approval_v1.0",
  enabled: true,
  minSampleSize: 3,
  minHistoryEffectScore: 75,
  maxRecurrenceRate: 20,
  maxPriorityStepChange: 1,
  minHistoricalApprovalSuccessRate: 70,
  lowImpactScopes: ["connector", "assignee"],
  manualReviewDirections: ["downgrade"],
  defaultHistoricalApprovalSuccessRate: 100,
  rootMetricRules: {},
  assigneeRules: {}
});

function cloneOperationQualityAutoApprovalPolicy(policy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  return {
    ...policy,
    lowImpactScopes: [...(policy.lowImpactScopes || [])],
    manualReviewDirections: [...(policy.manualReviewDirections || [])],
    rootMetricRules: { ...(policy.rootMetricRules || {}) },
    assigneeRules: { ...(policy.assigneeRules || {}) },
    activeAdjustmentIds: [...(policy.activeAdjustmentIds || [])]
  };
}

function applyOperationQualityAutoApprovalPolicyPatch(policy = {}, patch = {}) {
  const next = cloneOperationQualityAutoApprovalPolicy(policy);
  Object.entries(patch.global || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== "") next[key] = value;
  });
  (patch.removeRootMetricRules || []).forEach((metric) => {
    if (metric) delete next.rootMetricRules[metric];
  });
  (patch.removeAssigneeRules || []).forEach((assignee) => {
    if (assignee) delete next.assigneeRules[assignee];
  });
  Object.entries(patch.rootMetricRules || {}).forEach(([metric, rule]) => {
    if (!metric) return;
    if (rule === null || rule?.remove === true) {
      delete next.rootMetricRules[metric];
      return;
    }
    next.rootMetricRules[metric] = {
      ...(next.rootMetricRules[metric] || {}),
      ...(rule || {})
    };
  });
  Object.entries(patch.assigneeRules || {}).forEach(([assignee, rule]) => {
    if (!assignee) return;
    if (rule === null || rule?.remove === true) {
      delete next.assigneeRules[assignee];
      return;
    }
    next.assigneeRules[assignee] = {
      ...(next.assigneeRules[assignee] || {}),
      ...(rule || {})
    };
  });
  return next;
}

function activeOperationQualityAutoApprovalPolicy(policyAdjustments = []) {
  const approved = policyAdjustments
    .map(normalizeOperationQualityAutoApprovalPolicyAdjustment)
    .filter((item) => item.status === "approved")
    .sort((a, b) => String(a.approvedAt || a.updatedAt || "").localeCompare(String(b.approvedAt || b.updatedAt || "")));
  const policy = approved.reduce((current, item) => applyOperationQualityAutoApprovalPolicyPatch(current, item.policyPatch || {}), cloneOperationQualityAutoApprovalPolicy());
  return {
    ...policy,
    policyVersion: `${EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY.policyVersion}+${approved.length}`,
    activeAdjustmentIds: approved.map((item) => item.policyAdjustmentId)
  };
}

function operationQualityRecommendationAdjustmentId(action = {}, adjustment = {}) {
  return hashId("xoqadj", [
    action.sourceMonth || "",
    action.connectorId || "all",
    action.scopeType || "",
    action.scopeKey || "",
    action.rootMetric || "",
    adjustment.originalPriority || action.priority || ""
  ].join("|"));
}

function normalizeOperationQualityRecommendationAdjustment(input = {}) {
  const status = ["proposed", "approved", "rejected"].includes(String(input.status || "").trim())
    ? String(input.status || "").trim()
    : "proposed";
  const proposedAt = input.proposedAt || input.createdAt || input.generatedAt || new Date().toISOString();
  const normalized = {
    adjustmentId: String(input.adjustmentId || "").trim(),
    status,
    active: status === "approved" && input.active !== false,
    candidateActionId: String(input.candidateActionId || input.actionId || "").trim(),
    sourceMonth: String(input.sourceMonth || "").trim(),
    connectorId: String(input.connectorId || "").trim(),
    scopeType: String(input.scopeType || "").trim(),
    scopeKey: String(input.scopeKey || "").trim(),
    scopeLabel: String(input.scopeLabel || "").trim(),
    title: String(input.title || "").trim(),
    rootMetric: String(input.rootMetric || "").trim(),
    rootMetricLabel: String(input.rootMetricLabel || input.rootMetric || "").trim(),
    riskLevel: String(input.riskLevel || "").trim(),
    direction: String(input.direction || "none").trim(),
    originalPriority: String(input.originalPriority || "low").trim(),
    proposedPriority: String(input.proposedPriority || input.adjustedPriority || input.originalPriority || "low").trim(),
    approvedPriority: String(input.approvedPriority || "").trim(),
    delta: Number(input.delta || 0) || 0,
    sampleSize: Number(input.sampleSize || 0) || 0,
    weightedSampleSize: Number(input.weightedSampleSize || 0) || 0,
    historyEffectScore: Math.round(clampNumber(input.historyEffectScore || 0, 0, 100)),
    improvedRate: Math.round(clampNumber(input.improvedRate || 0, 0, 100)),
    worseRate: Math.round(clampNumber(input.worseRate || 0, 0, 100)),
    recurrenceRate: Math.round(clampNumber(input.recurrenceRate || 0, 0, 100)),
    followUpNeededRate: Math.round(clampNumber(input.followUpNeededRate || 0, 0, 100)),
    metricSampleSize: Number(input.metricSampleSize || 0) || 0,
    assigneeSampleSize: Number(input.assigneeSampleSize || 0) || 0,
    monthSampleSize: Number(input.monthSampleSize || 0) || 0,
    adminReason: String(input.adminReason || "").trim(),
    beforeRecommendedAction: String(input.beforeRecommendedAction || "").trim(),
    proposedRecommendedAction: String(input.proposedRecommendedAction || input.afterRecommendedAction || "").trim(),
    approvedRecommendedAction: String(input.approvedRecommendedAction || "").trim(),
    impactSummary: input.impactSummary && typeof input.impactSummary === "object" ? input.impactSummary : {},
    approvalMode: ["auto", "manual", "none"].includes(String(input.approvalMode || "").trim())
      ? String(input.approvalMode || "").trim()
      : status === "approved" && String(input.approvedBy || "").startsWith("system_auto")
        ? "auto"
        : status === "approved" || status === "rejected"
          ? "manual"
          : "none",
    autoApprovalPolicy: input.autoApprovalPolicy && typeof input.autoApprovalPolicy === "object" ? input.autoApprovalPolicy : null,
    autoApprovalRiskLevel: String(input.autoApprovalRiskLevel || input.autoApprovalPolicy?.riskLevel || "").trim(),
    rollbackAvailable: Boolean(input.rollbackAvailable),
    rolledBackAt: input.rolledBackAt || "",
    rolledBackBy: String(input.rolledBackBy || "").trim(),
    rollbackReason: String(input.rollbackReason || "").trim(),
    autoApprovalLogId: String(input.autoApprovalLogId || "").trim(),
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    proposedAt,
    updatedAt: input.updatedAt || proposedAt,
    approvedBy: String(input.approvedBy || "").trim(),
    approvedAt: input.approvedAt || "",
    rejectedBy: String(input.rejectedBy || "").trim(),
    rejectedAt: input.rejectedAt || "",
    rejectReason: String(input.rejectReason || input.reason || "").trim(),
    reviewReason: String(input.reviewReason || "").trim(),
    decisionHistory: Array.isArray(input.decisionHistory) ? input.decisionHistory : []
  };
  return {
    ...normalized,
    adjustmentId: normalized.adjustmentId || operationQualityRecommendationAdjustmentId(normalized, {
      originalPriority: normalized.originalPriority,
      adjustedPriority: normalized.proposedPriority
    })
  };
}

function operationQualityRecommendationAdjustmentFromCandidate(candidate = {}, adjustment = {}) {
  const adjustmentId = operationQualityRecommendationAdjustmentId(candidate, adjustment);
  const proposedRecommendedAction = [
    candidate.recommendedAction || "",
    adjustment.adminReason ? `History adjustment: ${adjustment.adminReason}` : ""
  ].filter(Boolean).join(" ");
  return normalizeOperationQualityRecommendationAdjustment({
    adjustmentId,
    status: "proposed",
    active: false,
    candidateActionId: candidate.actionId || "",
    sourceMonth: candidate.sourceMonth || "",
    connectorId: candidate.connectorId || "",
    scopeType: candidate.scopeType || "",
    scopeKey: candidate.scopeKey || "",
    scopeLabel: candidate.scopeLabel || "",
    title: candidate.title || "",
    rootMetric: candidate.rootMetric || "",
    rootMetricLabel: candidate.rootMetricLabel || "",
    riskLevel: candidate.riskLevel || "",
    direction: adjustment.direction || "none",
    originalPriority: adjustment.originalPriority || candidate.priority || "",
    proposedPriority: adjustment.adjustedPriority || candidate.priority || "",
    delta: adjustment.delta || 0,
    sampleSize: adjustment.sampleSize || 0,
    weightedSampleSize: adjustment.weightedSampleSize || 0,
    historyEffectScore: adjustment.historyEffectScore || 0,
    improvedRate: adjustment.improvedRate || 0,
    worseRate: adjustment.worseRate || 0,
    recurrenceRate: adjustment.recurrenceRate || 0,
    followUpNeededRate: adjustment.followUpNeededRate || 0,
    metricSampleSize: adjustment.metricSampleSize || 0,
    assigneeSampleSize: adjustment.assigneeSampleSize || 0,
    monthSampleSize: adjustment.monthSampleSize || 0,
    adminReason: adjustment.adminReason || "",
    beforeRecommendedAction: candidate.recommendedAction || "",
    proposedRecommendedAction,
    impactSummary: {
      priorityChanged: adjustment.adjustedPriority !== adjustment.originalPriority,
      beforePriority: adjustment.originalPriority,
      afterPriority: adjustment.adjustedPriority,
      recommendationChanged: proposedRecommendedAction !== (candidate.recommendedAction || "")
    }
  });
}

function operationQualityRecommendationImpactScope(proposal = {}, policy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const scopeType = String(proposal.scopeType || "").trim() || "global";
  const priorityStepChange = Math.abs(operationQualityPriorityRank(proposal.proposedPriority) - operationQualityPriorityRank(proposal.originalPriority));
  let level = (policy.lowImpactScopes || []).includes(scopeType) ? "low" : "medium";
  if (priorityStepChange > Number(policy.maxPriorityStepChange || 1)) level = "high";
  if (scopeType === "global" || scopeType === "all") level = "high";
  return {
    scopeType,
    level,
    priorityStepChange,
    reason: level === "low"
      ? "Connector/assignee scoped adjustment with limited operational impact."
      : level === "medium"
        ? "Scoped adjustment can affect a connector group and should remain reviewable."
        : "Broad scope or large priority movement can change connector operations materially."
  };
}

function operationQualityRecommendationHistoricalApprovalStats(proposal = {}, existingItems = [], policy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const reviewed = existingItems
    .map(normalizeOperationQualityRecommendationAdjustment)
    .filter((item) => item.adjustmentId !== proposal.adjustmentId)
    .filter((item) => ["approved", "rejected"].includes(item.status))
    .filter((item) => item.rootMetric === proposal.rootMetric && item.direction === proposal.direction);
  const approved = reviewed.filter((item) => item.status === "approved").length;
  const rejected = reviewed.filter((item) => item.status === "rejected").length;
  const total = approved + rejected;
  return {
    reviewed: total,
    approved,
    rejected,
    successRate: total ? Math.round((approved / total) * 100) : Number(policy.defaultHistoricalApprovalSuccessRate || 100),
    basis: total ? "same metric and direction review history" : "no prior review conflict; default safe baseline"
  };
}

function operationQualityAutoApprovalPolicyForProposal(policy = {}, proposal = {}) {
  const rootMetric = String(proposal.rootMetric || "").trim();
  const assignee = String(proposal.scopeType === "assignee" ? proposal.scopeKey || proposal.assignee || "" : "").trim();
  const rootRule = rootMetric ? (policy.rootMetricRules || {})[rootMetric] || {} : {};
  const assigneeRule = assignee ? (policy.assigneeRules || {})[assignee] || {} : {};
  const merged = {
    enabled: policy.enabled,
    minSampleSize: Number(policy.minSampleSize || 3),
    minHistoryEffectScore: Number(policy.minHistoryEffectScore || 75),
    maxRecurrenceRate: Number(policy.maxRecurrenceRate || 20),
    maxPriorityStepChange: Number(policy.maxPriorityStepChange || 1),
    minHistoricalApprovalSuccessRate: Number(policy.minHistoricalApprovalSuccessRate || 70),
    manualReviewDirections: policy.manualReviewDirections || [],
    rootMetricRule: rootRule,
    assigneeRule,
    ruleReasons: []
  };
  [rootRule, assigneeRule].forEach((rule) => {
    if (!rule || typeof rule !== "object") return;
    if (rule.autoApprovalEnabled === false) merged.enabled = false;
    if (rule.autoApprovalEnabled === true && merged.enabled !== false) merged.enabled = true;
    ["minSampleSize", "minHistoryEffectScore", "maxRecurrenceRate", "maxPriorityStepChange", "minHistoricalApprovalSuccessRate"].forEach((key) => {
      if (rule[key] !== undefined && rule[key] !== null && rule[key] !== "") merged[key] = Number(rule[key]);
    });
    if (rule.reason) merged.ruleReasons.push(String(rule.reason));
  });
  return merged;
}

function evaluateOperationQualityRecommendationAutoApproval(proposal = {}, existingItems = [], policy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const proposalPolicy = operationQualityAutoApprovalPolicyForProposal(policy, proposal);
  const impact = operationQualityRecommendationImpactScope(proposal, policy);
  const historicalApproval = operationQualityRecommendationHistoricalApprovalStats(proposal, existingItems, policy);
  const sampleSize = Number(proposal.sampleSize || 0);
  const effectScore = Number(proposal.historyEffectScore || 0);
  const recurrenceRate = Number(proposal.recurrenceRate || 0);
  const direction = String(proposal.direction || "none").trim();
  const priorityStepChange = impact.priorityStepChange;
  const criteria = {
    policyEnabled: Boolean(proposalPolicy.enabled),
    sampleSizeOk: sampleSize >= Number(proposalPolicy.minSampleSize || 3),
    effectScoreOk: effectScore >= Number(proposalPolicy.minHistoryEffectScore || 75),
    recurrenceOk: recurrenceRate <= Number(proposalPolicy.maxRecurrenceRate || 20),
    impactScopeOk: impact.level === "low",
    priorityStepOk: priorityStepChange <= Number(proposalPolicy.maxPriorityStepChange || 1),
    historicalApprovalOk: historicalApproval.successRate >= Number(proposalPolicy.minHistoricalApprovalSuccessRate || 70),
    directionOk: !(proposalPolicy.manualReviewDirections || []).includes(direction)
  };
  const blockingReasons = [];
  if (!criteria.policyEnabled) blockingReasons.push("Auto approval policy is disabled.");
  if (!criteria.sampleSizeOk) blockingReasons.push(`Sample size ${sampleSize} is below ${proposalPolicy.minSampleSize}.`);
  if (!criteria.effectScoreOk) blockingReasons.push(`Effect score ${effectScore} is below ${proposalPolicy.minHistoryEffectScore}.`);
  if (!criteria.recurrenceOk) blockingReasons.push(`Recurrence ${recurrenceRate}% exceeds ${proposalPolicy.maxRecurrenceRate}%.`);
  if (!criteria.impactScopeOk) blockingReasons.push(`Impact scope is ${impact.level}, not low.`);
  if (!criteria.priorityStepOk) blockingReasons.push(`Priority movement is ${priorityStepChange} step(s).`);
  if (!criteria.historicalApprovalOk) blockingReasons.push(`Past approval success ${historicalApproval.successRate}% is below ${proposalPolicy.minHistoricalApprovalSuccessRate}%.`);
  if (!criteria.directionOk) blockingReasons.push(`Direction ${direction} requires manual review.`);
  let riskLevel = "low";
  if (blockingReasons.length) riskLevel = "medium";
  if (
    impact.level === "high" ||
    sampleSize < 2 ||
    effectScore < 50 ||
    recurrenceRate >= 50 ||
    historicalApproval.successRate < 50 ||
    (proposalPolicy.manualReviewDirections || []).includes(direction)
  ) {
    riskLevel = "high";
  }
  const eligible = proposalPolicy.enabled && riskLevel === "low" && Object.values(criteria).every(Boolean);
  const reasons = eligible
    ? [
        `Auto-approved by ${policy.policyVersion}.`,
        `Samples ${sampleSize}, effect ${effectScore}, recurrence ${recurrenceRate}%.`,
        `Impact ${impact.level}, past approval success ${historicalApproval.successRate}%.`
      ]
    : blockingReasons;
  return {
    policyVersion: policy.policyVersion,
    evaluatedAt: new Date().toISOString(),
    eligible,
    riskLevel,
    criteria,
    proposalPolicy,
    metrics: {
      sampleSize,
      effectScore,
      recurrenceRate,
      direction,
      priorityStepChange,
      originalPriority: proposal.originalPriority || "",
      proposedPriority: proposal.proposedPriority || ""
    },
    impact,
    historicalApproval,
    reasons
  };
}

function operationQualityRecommendationAutoApprovalLogId(adjustmentId = "", eventType = "", eventAt = "") {
  return hashId("xoqaal", [adjustmentId, eventType, eventAt].join("|"));
}

function normalizeOperationQualityRecommendationAutoApprovalLog(input = {}) {
  const eventAt = input.eventAt || new Date().toISOString();
  const adjustmentId = String(input.adjustmentId || "").trim();
  const eventType = String(input.eventType || "auto_approved").trim();
  return {
    logId: String(input.logId || operationQualityRecommendationAutoApprovalLogId(adjustmentId, eventType, eventAt)).trim(),
    adjustmentId,
    candidateActionId: String(input.candidateActionId || "").trim(),
    connectorId: String(input.connectorId || "").trim(),
    sourceMonth: String(input.sourceMonth || "").trim(),
    rootMetric: String(input.rootMetric || "").trim(),
    eventType,
    eventAt,
    eventBy: String(input.eventBy || "system_auto").trim() || "system_auto",
    previousStatus: String(input.previousStatus || "").trim(),
    nextStatus: String(input.nextStatus || "").trim(),
    rollbackAvailable: Boolean(input.rollbackAvailable),
    rolledBack: Boolean(input.rolledBack),
    policyDecision: input.policyDecision && typeof input.policyDecision === "object" ? input.policyDecision : {},
    reason: String(input.reason || "").trim()
  };
}

async function appendOperationQualityRecommendationAutoApprovalLog(entry = {}) {
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalLogs();
  const normalized = normalizeOperationQualityRecommendationAutoApprovalLog(entry);
  const items = Array.isArray(data.items) ? data.items.map(normalizeOperationQualityRecommendationAutoApprovalLog) : [];
  if (items.some((item) => item.adjustmentId === normalized.adjustmentId && item.eventType === normalized.eventType && item.nextStatus === normalized.nextStatus)) {
    return {
      log: normalized,
      data
    };
  }
  const updated = await writeExternalConnectorOperationQualityRecommendationAutoApprovalLogs({
    ...data,
    items: [normalized, ...items].sort((a, b) => String(b.eventAt || "").localeCompare(String(a.eventAt || "")))
  });
  return {
    log: normalized,
    data: updated
  };
}

async function upsertOperationQualityRecommendationAdjustmentProposals(candidates = [], historyItems = []) {
  const [data, policyAdjustmentData] = await Promise.all([
    readExternalConnectorOperationQualityRecommendationAdjustments(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments()
  ]);
  const activePolicy = activeOperationQualityAutoApprovalPolicy(policyAdjustmentData.items || []);
  const existing = (data.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const byId = new Map(existing.map((item) => [item.adjustmentId, item]));
  let changed = false;
  for (const candidate of candidates) {
    const adjustment = operationQualityActionHistoryPriorityAdjustment(candidate, historyItems);
    if (!adjustment.applied || !adjustment.sampleSize) continue;
    const proposal = operationQualityRecommendationAdjustmentFromCandidate(candidate, adjustment);
    const previous = byId.get(proposal.adjustmentId);
    if (previous && ["approved", "rejected"].includes(previous.status)) continue;
    const policyDecision = evaluateOperationQualityRecommendationAutoApproval(proposal, existing, activePolicy);
    const now = policyDecision.evaluatedAt || new Date().toISOString();
    const next = normalizeOperationQualityRecommendationAdjustment(policyDecision.eligible
      ? {
          ...(previous || {}),
          ...proposal,
          status: "approved",
          active: true,
          approvalMode: "auto",
          autoApprovalPolicy: policyDecision,
          autoApprovalRiskLevel: policyDecision.riskLevel,
          rollbackAvailable: true,
          approvedPriority: proposal.proposedPriority,
          approvedRecommendedAction: proposal.proposedRecommendedAction,
          approvedBy: "system_auto",
          approvedAt: now,
          reviewReason: policyDecision.reasons.join(" "),
          proposedBy: previous?.proposedBy || proposal.proposedBy,
          proposedAt: previous?.proposedAt || proposal.proposedAt,
          updatedAt: now,
          decisionHistory: [
            ...(previous?.decisionHistory || []),
            {
              decision: "auto_approve",
              beforeStatus: previous?.status || "proposed",
              decidedBy: "system_auto",
              decidedAt: now,
              reason: policyDecision.reasons.join(" ")
            }
          ]
        }
      : {
          ...(previous || {}),
          ...proposal,
          status: "proposed",
          active: false,
          approvalMode: "none",
          autoApprovalPolicy: policyDecision,
          autoApprovalRiskLevel: policyDecision.riskLevel,
          rollbackAvailable: false,
          proposedBy: previous?.proposedBy || proposal.proposedBy,
          proposedAt: previous?.proposedAt || proposal.proposedAt,
          updatedAt: now,
          decisionHistory: previous?.decisionHistory || []
        });
    byId.set(proposal.adjustmentId, next);
    changed = true;
    if (next.status === "approved" && next.approvalMode === "auto" && previous?.status !== "approved") {
      await appendOperationQualityRecommendationAutoApprovalLog({
        adjustmentId: next.adjustmentId,
        candidateActionId: next.candidateActionId,
        connectorId: next.connectorId,
        sourceMonth: next.sourceMonth,
        rootMetric: next.rootMetric,
        eventType: "auto_approved",
        eventAt: next.approvedAt || now,
        eventBy: "system_auto",
        previousStatus: previous?.status || "proposed",
        nextStatus: "approved",
        rollbackAvailable: true,
        policyDecision,
        reason: next.reviewReason
      });
    }
  }
  if (!changed) {
    return {
      ...data,
      items: existing
    };
  }
  return writeExternalConnectorOperationQualityRecommendationAdjustments({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
}

function operationQualityActiveAdjustmentForCandidate(candidate = {}, adjustment = {}, adjustments = []) {
  const adjustmentId = operationQualityRecommendationAdjustmentId(candidate, adjustment);
  return adjustments
    .map(normalizeOperationQualityRecommendationAdjustment)
    .find((item) => item.adjustmentId === adjustmentId && item.status === "approved" && item.active);
}

function operationQualitySavedAdjustmentForCandidate(candidate = {}, adjustment = {}, adjustments = []) {
  const adjustmentId = operationQualityRecommendationAdjustmentId(candidate, adjustment);
  return adjustments
    .map(normalizeOperationQualityRecommendationAdjustment)
    .find((item) => item.adjustmentId === adjustmentId);
}

function applyOperationQualityActionHistoryAdjustments(candidates = [], historyItems = [], recommendationAdjustments = []) {
  return candidates.map((candidate) => {
    const adjustment = operationQualityActionHistoryPriorityAdjustment(candidate, historyItems);
    const proposed = adjustment.applied && adjustment.sampleSize
      ? operationQualityRecommendationAdjustmentFromCandidate(candidate, adjustment)
      : null;
    const savedAdjustment = proposed
      ? operationQualitySavedAdjustmentForCandidate(candidate, adjustment, recommendationAdjustments)
      : null;
    const activeAdjustment = proposed
      ? operationQualityActiveAdjustmentForCandidate(candidate, adjustment, recommendationAdjustments)
      : null;
    if (!adjustment.applied) {
      return {
        ...candidate,
        historyPriorityAdjustment: adjustment
      };
    }
    const workflowStatus = activeAdjustment?.status || savedAdjustment?.status || proposed?.status || "proposed";
    const workflowAdjustment = {
      ...adjustment,
      adjustmentId: savedAdjustment?.adjustmentId || proposed?.adjustmentId || "",
      workflowStatus,
      active: Boolean(activeAdjustment),
      approvalMode: savedAdjustment?.approvalMode || "none",
      autoApprovalRiskLevel: savedAdjustment?.autoApprovalRiskLevel || savedAdjustment?.autoApprovalPolicy?.riskLevel || "",
      autoApprovalPolicy: savedAdjustment?.autoApprovalPolicy || null,
      rollbackAvailable: Boolean(savedAdjustment?.rollbackAvailable),
      approvedAt: activeAdjustment?.approvedAt || "",
      approvedBy: activeAdjustment?.approvedBy || "",
      proposedPriority: savedAdjustment?.proposedPriority || proposed?.proposedPriority || adjustment.adjustedPriority,
      adjustedPriority: activeAdjustment?.approvedPriority || activeAdjustment?.proposedPriority || adjustment.originalPriority,
      adminReason: activeAdjustment?.adminReason || adjustment.adminReason
    };
    if (!activeAdjustment) {
      return {
        ...candidate,
        originalPriority: adjustment.originalPriority,
        priorityAdjusted: false,
        historyPriorityAdjustment: workflowAdjustment
      };
    }
    const adjustmentNote = `Approved history adjustment: ${activeAdjustment.adminReason || adjustment.adminReason}`;
    return {
      ...candidate,
      originalPriority: activeAdjustment.originalPriority,
      priority: activeAdjustment.approvedPriority || activeAdjustment.proposedPriority || adjustment.adjustedPriority,
      priorityAdjusted: (activeAdjustment.approvedPriority || activeAdjustment.proposedPriority) !== activeAdjustment.originalPriority,
      historyPriorityAdjustment: workflowAdjustment,
      recommendedAction: activeAdjustment.approvedRecommendedAction || activeAdjustment.proposedRecommendedAction || [candidate.recommendedAction || "", adjustmentNote].filter(Boolean).join(" "),
      activeRecommendationAdjustmentId: activeAdjustment.adjustmentId
    };
  });
}

function operationQualityActionHistoryAdjustmentSummary(items = []) {
  const adjusted = items.filter((item) => item.historyPriorityAdjustment?.applied);
  const active = adjusted.filter((item) => item.historyPriorityAdjustment?.active);
  const proposed = adjusted.filter((item) => item.historyPriorityAdjustment?.workflowStatus === "proposed" && !item.historyPriorityAdjustment?.active);
  return {
    totalCandidates: items.length,
    adjusted: adjusted.length,
    active: active.length,
    proposed: proposed.length,
    boosted: active.filter((item) => ["boost", "reinforce"].includes(item.historyPriorityAdjustment?.direction)).length,
    downgraded: active.filter((item) => item.historyPriorityAdjustment?.direction === "downgrade").length,
    caution: adjusted.filter((item) => item.historyPriorityAdjustment?.direction === "caution").length,
    averageHistoryEffectScore: adjusted.length
      ? Math.round(adjusted.reduce((sum, item) => sum + Number(item.historyPriorityAdjustment?.historyEffectScore || 0), 0) / adjusted.length)
      : 0
  };
}

function operationQualityRecommendationAdjustmentParam(params = {}, key = "") {
  if (params && typeof params.get === "function") return params.get(key) || "";
  return params?.[key] || "";
}

function filterOperationQualityRecommendationAdjustments(items = [], params = {}) {
  const month = String(operationQualityRecommendationAdjustmentParam(params, "month") || "").trim();
  const connectorId = operationQualityRecommendationAdjustmentParam(params, "connectorId")
    ? normalizeExternalConnectorId(operationQualityRecommendationAdjustmentParam(params, "connectorId"))
    : "";
  const status = String(operationQualityRecommendationAdjustmentParam(params, "status") || "").trim();
  const rootMetric = String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim();
  const direction = String(operationQualityRecommendationAdjustmentParam(params, "direction") || "").trim();
  return items
    .filter((item) => !month || item.sourceMonth === month)
    .filter((item) => !connectorId || item.connectorId === connectorId)
    .filter((item) => !status || item.status === status)
    .filter((item) => !rootMetric || item.rootMetric === rootMetric)
    .filter((item) => !direction || item.direction === direction);
}

function operationQualityRecommendationAdjustmentSummary(items = []) {
  const scoreItems = items.filter((item) => Number.isFinite(Number(item.historyEffectScore)));
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    active: items.filter((item) => item.status === "approved" && item.active).length,
    autoApproved: items.filter((item) => item.status === "approved" && item.approvalMode === "auto").length,
    manualReviewRequired: items.filter((item) => item.status === "proposed" && item.approvalMode !== "auto").length,
    rollbackAvailable: items.filter((item) => item.rollbackAvailable).length,
    lowRisk: items.filter((item) => item.autoApprovalRiskLevel === "low").length,
    mediumRisk: items.filter((item) => item.autoApprovalRiskLevel === "medium").length,
    highRisk: items.filter((item) => item.autoApprovalRiskLevel === "high").length,
    boost: items.filter((item) => ["boost", "reinforce"].includes(item.direction)).length,
    downgrade: items.filter((item) => item.direction === "downgrade").length,
    caution: items.filter((item) => item.direction === "caution").length,
    averageHistoryEffectScore: scoreItems.length
      ? Math.round(scoreItems.reduce((sum, item) => sum + Number(item.historyEffectScore || 0), 0) / scoreItems.length)
      : 0
  };
}

async function externalConnectorOperationQualityRecommendationAdjustmentsReport(params = new URLSearchParams()) {
  const [data, logData, policyAdjustmentData] = await Promise.all([
    readExternalConnectorOperationQualityRecommendationAdjustments(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalLogs(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments()
  ]);
  const activePolicy = activeOperationQualityAutoApprovalPolicy(policyAdjustmentData.items || []);
  const allItems = (data.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const filtered = filterOperationQualityRecommendationAdjustments(allItems, params);
  const filteredIds = new Set(filtered.map((item) => item.adjustmentId));
  const autoApprovalLogs = (logData.items || [])
    .map(normalizeOperationQualityRecommendationAutoApprovalLog)
    .filter((log) => !filteredIds.size || filteredIds.has(log.adjustmentId))
    .sort((a, b) => String(b.eventAt || "").localeCompare(String(a.eventAt || "")));
  const limit = Math.max(1, Math.min(300, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)));
  return {
    role: "admin",
    schema: "external_connector_operation_quality_recommendation_adjustment_v1",
    generatedAt: new Date().toISOString(),
    autoApprovalPolicy: activePolicy,
    filters: {
      month: String(operationQualityRecommendationAdjustmentParam(params, "month") || "").trim(),
      connectorId: operationQualityRecommendationAdjustmentParam(params, "connectorId")
        ? normalizeExternalConnectorId(operationQualityRecommendationAdjustmentParam(params, "connectorId"))
        : "",
      status: String(operationQualityRecommendationAdjustmentParam(params, "status") || "").trim(),
      rootMetric: String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim(),
      direction: String(operationQualityRecommendationAdjustmentParam(params, "direction") || "").trim(),
      limit
    },
    summary: operationQualityRecommendationAdjustmentSummary(filtered),
    fullSummary: operationQualityRecommendationAdjustmentSummary(allItems),
    autoApprovalSummary: {
      ...operationQualityRecommendationAdjustmentSummary(filtered),
      logCount: autoApprovalLogs.length,
      rolledBack: autoApprovalLogs.filter((log) => log.eventType === "rollback").length,
      autoApprovedLogCount: autoApprovalLogs.filter((log) => log.eventType === "auto_approved").length
    },
    autoApprovalLogs: autoApprovalLogs.slice(0, 80),
    manualReviewItems: filtered
      .filter((item) => item.status === "proposed")
      .sort((a, b) => {
        const riskRank = { high: 3, medium: 2, low: 1 };
        return (riskRank[b.autoApprovalRiskLevel] || 0) - (riskRank[a.autoApprovalRiskLevel] || 0)
          || String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
      })
      .slice(0, 80),
    items: filtered
      .sort((a, b) => {
        const statusRank = { proposed: 3, approved: 2, rejected: 1 };
        return (statusRank[b.status] || 0) - (statusRank[a.status] || 0)
          || String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
      })
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only external connector operation quality recommendation adjustment approval workflow",
      hiddenFromBusiness: ["recommendation adjustment proposal", "approval history", "effect score", "recurrence rate", "internal formula", "operation warning", "follow-up queue"]
    }
  };
}

function operationQualityRecommendationAutoApprovalLinkedHistory(adjustment = {}, historyItems = []) {
  const approvedAt = adjustment.approvedAt || adjustment.updatedAt || adjustment.proposedAt || "";
  const approvedTime = new Date(approvedAt).getTime();
  const candidateActionId = String(adjustment.candidateActionId || "").trim();
  const rootMetric = String(adjustment.rootMetric || "").trim();
  const sourceMonth = String(adjustment.sourceMonth || "").trim();
  const connectorId = String(adjustment.connectorId || "").trim();
  const assignee = String(adjustment.scopeType === "assignee" ? adjustment.scopeKey : "").trim().toLowerCase();
  return historyItems
    .map(normalizeOperationQualityActionReassessmentHistoryItem)
    .filter((item) => {
      const evaluatedTime = new Date(item.evaluatedAt || item.recordedAt || "").getTime();
      const afterApproval = !Number.isFinite(approvedTime) || !Number.isFinite(evaluatedTime) || evaluatedTime >= approvedTime;
      const sameAction = candidateActionId && (item.actionId === candidateActionId || item.sourceActionId === candidateActionId);
      const sameMetric = rootMetric && item.rootMetric === rootMetric;
      const sameMonth = !sourceMonth || item.sourceMonth === sourceMonth || item.evaluatedMonth === sourceMonth;
      const sameConnector = !connectorId || item.connectorId === connectorId;
      const sameAssignee = !assignee || String(item.assignee || "").trim().toLowerCase() === assignee;
      return afterApproval && (candidateActionId ? sameAction : (sameMetric && sameMonth && sameConnector && sameAssignee));
    })
    .sort((a, b) => String(b.evaluatedAt || b.recordedAt || "").localeCompare(String(a.evaluatedAt || a.recordedAt || "")));
}

function operationQualityRecommendationAutoApprovalPerformanceOutcome(adjustment = {}, linkedHistory = [], logs = []) {
  const rolledBack = Boolean(adjustment.rolledBackAt || logs.some((log) => log.adjustmentId === adjustment.adjustmentId && log.eventType === "rollback"));
  const evaluatedCount = linkedHistory.length;
  const avgEffectScore = evaluatedCount ? Math.round(linkedHistory.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / evaluatedCount) : 0;
  const improved = linkedHistory.filter((item) => item.outcome === "improved").length;
  const worse = linkedHistory.filter((item) => item.outcome === "worse").length;
  const recurrence = linkedHistory.filter((item) => item.recurrence).length;
  const followUpNeeded = linkedHistory.filter((item) => item.followUpNeeded).length;
  const improvedRate = evaluatedCount ? Math.round((improved / evaluatedCount) * 100) : 0;
  const worseRate = evaluatedCount ? Math.round((worse / evaluatedCount) * 100) : 0;
  const recurrenceRate = evaluatedCount ? Math.round((recurrence / evaluatedCount) * 100) : 0;
  const followUpNeededRate = evaluatedCount ? Math.round((followUpNeeded / evaluatedCount) * 100) : 0;
  const falsePositive = evaluatedCount > 0 && (worseRate >= 50 || recurrenceRate >= 50 || avgEffectScore < 45 || followUpNeededRate >= 50);
  const successful = evaluatedCount > 0 && !falsePositive && avgEffectScore >= 60 && improvedRate >= 50 && recurrenceRate < 50;
  let outcome = "pending";
  if (rolledBack) outcome = "rolled_back";
  else if (falsePositive) outcome = "false_positive";
  else if (successful) outcome = "successful";
  else if (evaluatedCount > 0) outcome = "mixed";
  return {
    outcome,
    evaluatedCount,
    avgEffectScore,
    improved,
    improvedRate,
    worse,
    worseRate,
    recurrence,
    recurrenceRate,
    followUpNeeded,
    followUpNeededRate,
    falsePositive,
    successful,
    rolledBack
  };
}

function operationQualityRecommendationAutoApprovalPerformanceItem(adjustment = {}, historyItems = [], autoApprovalLogs = []) {
  const logs = autoApprovalLogs.filter((log) => log.adjustmentId === adjustment.adjustmentId);
  const linkedHistory = operationQualityRecommendationAutoApprovalLinkedHistory(adjustment, historyItems);
  const outcome = operationQualityRecommendationAutoApprovalPerformanceOutcome(adjustment, linkedHistory, logs);
  const assignee = adjustment.scopeType === "assignee"
    ? String(adjustment.scopeKey || "unassigned").trim() || "unassigned"
    : "unassigned";
  return {
    adjustmentId: adjustment.adjustmentId,
    candidateActionId: adjustment.candidateActionId,
    approvalMonth: monthKey(adjustment.approvedAt || adjustment.updatedAt || adjustment.proposedAt),
    approvedAt: adjustment.approvedAt || "",
    sourceMonth: adjustment.sourceMonth || "",
    connectorId: adjustment.connectorId || "",
    scopeType: adjustment.scopeType || "",
    scopeKey: adjustment.scopeKey || "",
    scopeLabel: adjustment.scopeLabel || "",
    assignee,
    title: adjustment.title || "",
    rootMetric: adjustment.rootMetric || "",
    rootMetricLabel: adjustment.rootMetricLabel || adjustment.rootMetric || "",
    direction: adjustment.direction || "",
    originalPriority: adjustment.originalPriority || "",
    proposedPriority: adjustment.proposedPriority || "",
    approvedPriority: adjustment.approvedPriority || "",
    policyRiskLevel: adjustment.autoApprovalRiskLevel || adjustment.autoApprovalPolicy?.riskLevel || "",
    policyVersion: adjustment.autoApprovalPolicy?.policyVersion || "",
    rollbackAvailable: Boolean(adjustment.rollbackAvailable),
    rolledBackAt: adjustment.rolledBackAt || "",
    rolledBackBy: adjustment.rolledBackBy || "",
    outcome,
    linkedHistory: linkedHistory.slice(0, 6).map((item) => ({
      historyId: item.historyId,
      actionId: item.actionId,
      evaluatedAt: item.evaluatedAt,
      evaluatedMonth: item.evaluatedMonth,
      sourceMonth: item.sourceMonth,
      assignee: item.assignee,
      rootMetric: item.rootMetric,
      effectScore: item.effectScore,
      outcome: item.outcome,
      recurrence: item.recurrence,
      followUpNeeded: item.followUpNeeded
    })),
    logCount: logs.length
  };
}

function filterOperationQualityRecommendationAutoApprovalPerformanceItems(items = [], params = {}) {
  const month = String(operationQualityRecommendationAdjustmentParam(params, "month") || "").trim();
  const assignee = String(operationQualityRecommendationAdjustmentParam(params, "assignee") || "").trim().toLowerCase();
  const rootMetric = String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim();
  const outcome = String(operationQualityRecommendationAdjustmentParam(params, "outcome") || "").trim();
  return items
    .filter((item) => !month || item.approvalMonth === month || item.sourceMonth === month || item.linkedHistory.some((history) => history.evaluatedMonth === month || history.sourceMonth === month))
    .filter((item) => !assignee || String(item.assignee || "").toLowerCase().includes(assignee))
    .filter((item) => !rootMetric || item.rootMetric === rootMetric)
    .filter((item) => !outcome || item.outcome?.outcome === outcome);
}

function operationQualityAutoApprovalPolicyAdjustmentId(candidate = {}) {
  return hashId("xoqpol", [
    candidate.type || candidate.candidateType || "",
    candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "",
    candidate.sourceSuggestionType || candidate.sourceContext?.suggestionType || "",
    candidate.rootMetric || "",
    candidate.assignee || "",
    candidate.target || ""
  ].join("|"));
}

function normalizeOperationQualityAutoApprovalPolicyAdjustment(input = {}) {
  const status = ["proposed", "approved", "rejected"].includes(String(input.status || "").trim())
    ? String(input.status || "").trim()
    : "proposed";
  const proposedAt = input.proposedAt || input.createdAt || new Date().toISOString();
  return {
    policyAdjustmentId: String(input.policyAdjustmentId || operationQualityAutoApprovalPolicyAdjustmentId(input)).trim(),
    candidateType: String(input.candidateType || input.type || "policy_adjustment").trim(),
    target: String(input.target || input.rootMetric || input.assignee || "").trim(),
    rootMetric: String(input.rootMetric || "").trim(),
    assignee: String(input.assignee || "").trim(),
    priority: String(input.priority || "medium").trim(),
    metrics: input.metrics && typeof input.metrics === "object" ? input.metrics : {},
    basis: String(input.basis || "").trim(),
    recommendation: String(input.recommendation || "").trim(),
    policyPatch: input.policyPatch && typeof input.policyPatch === "object" ? input.policyPatch : {},
    beforePolicy: input.beforePolicy && typeof input.beforePolicy === "object" ? input.beforePolicy : {},
    afterPolicy: input.afterPolicy && typeof input.afterPolicy === "object" ? input.afterPolicy : {},
    expectedImpact: input.expectedImpact && typeof input.expectedImpact === "object" ? input.expectedImpact : {},
    sourceContext: input.sourceContext && typeof input.sourceContext === "object" ? input.sourceContext : {},
    qualityCalibration: input.qualityCalibration && typeof input.qualityCalibration === "object"
      ? input.qualityCalibration
      : input.sourceContext?.qualityCalibration && typeof input.sourceContext.qualityCalibration === "object"
        ? input.sourceContext.qualityCalibration
        : {},
    sourcePolicyAdjustmentId: String(input.sourcePolicyAdjustmentId || input.sourceContext?.policyAdjustmentId || "").trim(),
    sourceSuggestionType: String(input.sourceSuggestionType || input.sourceContext?.suggestionType || "").trim(),
    sourceEffectOutcome: String(input.sourceEffectOutcome || input.sourceContext?.outcome || "").trim(),
    sourceEffectScore: input.sourceEffectScore ?? input.sourceContext?.effectScore ?? null,
    status,
    active: status === "approved" && input.active !== false,
    proposedAt,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    updatedAt: input.updatedAt || proposedAt,
    updatedBy: String(input.updatedBy || input.proposedBy || "system").trim() || "system",
    approvedAt: input.approvedAt || "",
    approvedBy: String(input.approvedBy || "").trim(),
    rejectedAt: input.rejectedAt || "",
    rejectedBy: String(input.rejectedBy || "").trim(),
    reviewReason: String(input.reviewReason || "").trim(),
    rejectReason: String(input.rejectReason || input.reason || "").trim(),
    duplicateStatus: String(input.duplicateStatus || "").trim(),
    decisionHistory: Array.isArray(input.decisionHistory) ? input.decisionHistory : []
  };
}

function operationQualityAutoApprovalPolicySnapshot(policy = {}, candidate = {}) {
  const rootMetric = String(candidate.rootMetric || "").trim();
  const assignee = String(candidate.assignee || "").trim();
  return {
    policyVersion: policy.policyVersion || "",
    enabled: Boolean(policy.enabled),
    minSampleSize: Number(policy.minSampleSize || 0),
    minHistoryEffectScore: Number(policy.minHistoryEffectScore || 0),
    maxRecurrenceRate: Number(policy.maxRecurrenceRate || 0),
    maxPriorityStepChange: Number(policy.maxPriorityStepChange || 0),
    minHistoricalApprovalSuccessRate: Number(policy.minHistoricalApprovalSuccessRate || 0),
    rootMetricRule: rootMetric ? (policy.rootMetricRules || {})[rootMetric] || {} : {},
    assigneeRule: assignee ? (policy.assigneeRules || {})[assignee] || {} : {},
    activeAdjustmentIds: policy.activeAdjustmentIds || []
  };
}

function operationQualityAutoApprovalPolicyPatchFromCandidate(candidate = {}, policy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const type = String(candidate.type || candidate.candidateType || "").trim();
  const rootMetric = String(candidate.rootMetric || "").trim();
  const assignee = String(candidate.assignee || "").trim();
  const scopedValue = (key, fallback = 0) => {
    const snapshot = operationQualityAutoApprovalPolicySnapshot(policy, candidate);
    const scoped = rootMetric ? snapshot.rootMetricRule : assignee ? snapshot.assigneeRule : {};
    return Number(scoped?.[key] ?? snapshot[key] ?? fallback);
  };
  if (type === "rollback_policy_adjustment") {
    const rollbackTo = candidate.rollbackToPolicySnapshot || candidate.sourceContext?.beforePolicy || {};
    if (rootMetric) {
      const rule = rollbackTo.rootMetricRule || {};
      return Object.keys(rule).length
        ? {
            rootMetricRules: {
              [rootMetric]: {
                ...rule,
                reason: candidate.basis || "Post-effect review requested rollback to the previous root metric policy."
              }
            }
          }
        : { removeRootMetricRules: [rootMetric] };
    }
    if (assignee) {
      const rule = rollbackTo.assigneeRule || {};
      return Object.keys(rule).length
        ? {
            assigneeRules: {
              [assignee]: {
                ...rule,
                reason: candidate.basis || "Post-effect review requested rollback to the previous assignee policy."
              }
            }
          }
        : { removeAssigneeRules: [assignee] };
    }
    return {
      global: {
        minSampleSize: Math.max(3, Number(rollbackTo.minSampleSize || policy.minSampleSize || 3)),
        minHistoryEffectScore: Math.max(70, Number(rollbackTo.minHistoryEffectScore || policy.minHistoryEffectScore || 75))
      }
    };
  }
  if (type === "additional_tightening_policy") {
    if (rootMetric) {
      return {
        rootMetricRules: {
          [rootMetric]: {
            autoApprovalEnabled: false,
            minSampleSize: Math.min(12, scopedValue("minSampleSize", 3) + 2),
            minHistoryEffectScore: Math.min(98, scopedValue("minHistoryEffectScore", 75) + 10),
            maxRecurrenceRate: Math.max(0, scopedValue("maxRecurrenceRate", 20) - 10),
            minHistoricalApprovalSuccessRate: Math.min(98, scopedValue("minHistoricalApprovalSuccessRate", 70) + 10),
            reason: candidate.basis || "Post-effect review requested additional root metric tightening."
          }
        }
      };
    }
    if (assignee) {
      return {
        assigneeRules: {
          [assignee]: {
            autoApprovalEnabled: false,
            minSampleSize: Math.min(12, scopedValue("minSampleSize", 3) + 2),
            minHistoryEffectScore: Math.min(98, scopedValue("minHistoryEffectScore", 75) + 8),
            maxRecurrenceRate: Math.max(0, scopedValue("maxRecurrenceRate", 20) - 8),
            minHistoricalApprovalSuccessRate: Math.min(98, scopedValue("minHistoricalApprovalSuccessRate", 70) + 8),
            reason: candidate.basis || "Post-effect review requested additional assignee tightening."
          }
        }
      };
    }
    return {
      global: {
        minSampleSize: Math.min(12, scopedValue("minSampleSize", 3) + 1),
        minHistoryEffectScore: Math.min(98, scopedValue("minHistoryEffectScore", 75) + 5)
      }
    };
  }
  if (type === "maintain_or_relax_policy") {
    if (rootMetric) {
      return {
        rootMetricRules: {
          [rootMetric]: {
            autoApprovalEnabled: true,
            minSampleSize: Math.max(2, scopedValue("minSampleSize", 3) - 1),
            minHistoryEffectScore: Math.max(65, scopedValue("minHistoryEffectScore", 75) - 5),
            maxRecurrenceRate: Math.min(30, scopedValue("maxRecurrenceRate", 20) + 5),
            reason: candidate.basis || "Post-effect review found stable policy performance."
          }
        }
      };
    }
    if (assignee) {
      return {
        assigneeRules: {
          [assignee]: {
            autoApprovalEnabled: true,
            minSampleSize: Math.max(2, scopedValue("minSampleSize", 3) - 1),
            minHistoryEffectScore: Math.max(65, scopedValue("minHistoryEffectScore", 75) - 5),
            maxRecurrenceRate: Math.min(30, scopedValue("maxRecurrenceRate", 20) + 5),
            reason: candidate.basis || "Post-effect review found stable assignee policy performance."
          }
        }
      };
    }
  }
  if (type === "tighten_root_metric_policy" && rootMetric) {
    return {
      rootMetricRules: {
        [rootMetric]: {
          autoApprovalEnabled: false,
          minSampleSize: Number(policy.minSampleSize || 3) + 2,
          minHistoryEffectScore: Math.min(95, Number(policy.minHistoryEffectScore || 75) + 10),
          maxRecurrenceRate: Math.max(5, Number(policy.maxRecurrenceRate || 20) - 10),
          minHistoricalApprovalSuccessRate: Math.min(95, Number(policy.minHistoricalApprovalSuccessRate || 70) + 10),
          reason: candidate.basis || "Performance report requested tighter root metric policy."
        }
      }
    };
  }
  if (type === "tighten_assignee_scope_policy" && assignee) {
    return {
      assigneeRules: {
        [assignee]: {
          autoApprovalEnabled: false,
          minSampleSize: Number(policy.minSampleSize || 3) + 1,
          minHistoryEffectScore: Math.min(95, Number(policy.minHistoryEffectScore || 75) + 5),
          maxRecurrenceRate: Math.max(5, Number(policy.maxRecurrenceRate || 20) - 5),
          reason: candidate.basis || "Performance report requested tighter assignee policy."
        }
      }
    };
  }
  if (type === "maintain_or_relax_root_metric_policy" && rootMetric) {
    return {
      rootMetricRules: {
        [rootMetric]: {
          autoApprovalEnabled: true,
          minSampleSize: Math.max(2, Number(policy.minSampleSize || 3) - 1),
          minHistoryEffectScore: Math.max(65, Number(policy.minHistoryEffectScore || 75) - 5),
          maxRecurrenceRate: Math.min(25, Number(policy.maxRecurrenceRate || 20) + 5),
          reason: candidate.basis || "Performance report found stable root metric auto approvals."
        }
      }
    };
  }
  if (type === "increase_reassessment_capture") {
    return {
      global: {
        minSampleSize: Number(policy.minSampleSize || 3) + 1
      }
    };
  }
  return {};
}

function operationQualityAutoApprovalExpectedImpact(candidate = {}) {
  const metrics = candidate.metrics || {};
  const type = String(candidate.type || candidate.candidateType || "").trim();
  const tightening = type.startsWith("tighten") || type === "additional_tightening_policy";
  const rollback = type === "rollback_policy_adjustment";
  const relaxing = type === "maintain_or_relax_policy" || type === "maintain_or_relax_root_metric_policy";
  return {
    affectedScope: candidate.rootMetric ? `rootMetric:${candidate.rootMetric}` : candidate.assignee ? `assignee:${candidate.assignee}` : "global",
    expectedSuccessRateChange: tightening || rollback ? Math.max(5, Math.round(Number(metrics.falsePositiveRate || metrics.afterFalsePositiveRate || 0) / 2)) : relaxing ? 0 : 0,
    expectedFalsePositiveChange: tightening || rollback ? -Math.max(5, Math.round(Number(metrics.falsePositiveRate || metrics.afterFalsePositiveRate || 0) / 2)) : 0,
    expectedRollbackChange: tightening || rollback ? -Math.max(5, Math.round(Number(metrics.rollbackRate || metrics.afterRollbackRate || 0) / 2)) : 0,
    expectedManualReviewIncrease: rollback ? 20 : tightening ? 10 : relaxing ? -5 : 0
  };
}

function buildOperationQualityAutoApprovalPolicyAdjustmentProposal(candidate = {}, activePolicy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY, existing = null) {
  const candidateType = String(candidate.candidateType || candidate.type || "policy_adjustment").trim();
  const policyPatch = candidate.policyPatch && typeof candidate.policyPatch === "object"
    ? candidate.policyPatch
    : operationQualityAutoApprovalPolicyPatchFromCandidate({ ...candidate, candidateType }, activePolicy);
  const beforePolicy = operationQualityAutoApprovalPolicySnapshot(activePolicy, candidate);
  const afterPolicy = operationQualityAutoApprovalPolicySnapshot(applyOperationQualityAutoApprovalPolicyPatch(activePolicy, policyPatch), candidate);
  return normalizeOperationQualityAutoApprovalPolicyAdjustment({
    ...(existing || {}),
    ...candidate,
    candidateType,
    policyPatch,
    beforePolicy,
    afterPolicy,
    expectedImpact: candidate.expectedImpact && typeof candidate.expectedImpact === "object"
      ? candidate.expectedImpact
      : operationQualityAutoApprovalExpectedImpact({ ...candidate, candidateType }),
    status: existing?.status || "proposed",
    proposedAt: existing?.proposedAt || new Date().toISOString(),
    proposedBy: existing?.proposedBy || "system",
    updatedAt: existing?.updatedAt || new Date().toISOString(),
    updatedBy: existing?.updatedBy || "system"
  });
}

async function upsertOperationQualityAutoApprovalPolicyAdjustmentProposals(candidates = [], activePolicy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const existingItems = Array.isArray(data.items) ? data.items.map(normalizeOperationQualityAutoApprovalPolicyAdjustment) : [];
  const byId = new Map(existingItems.map((item) => [item.policyAdjustmentId, item]));
  const proposals = [];
  candidates.forEach((candidate) => {
    const candidateId = String(candidate.policyAdjustmentId || operationQualityAutoApprovalPolicyAdjustmentId(candidate)).trim();
    const existing = byId.get(candidateId) || null;
    if (existing && ["approved", "rejected"].includes(existing.status)) {
      proposals.push(normalizeOperationQualityAutoApprovalPolicyAdjustment({
        ...existing,
        duplicateStatus: `existing_${existing.status}`
      }));
      return;
    }
    const proposal = normalizeOperationQualityAutoApprovalPolicyAdjustment({
      ...buildOperationQualityAutoApprovalPolicyAdjustmentProposal(candidate, activePolicy, existing),
      duplicateStatus: existing ? "existing_proposed" : "created"
    });
    byId.set(proposal.policyAdjustmentId, proposal);
    proposals.push(proposal);
  });
  await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments({
    ...data,
    items: [...byId.values()].sort((a, b) => {
      const statusRank = { proposed: 0, approved: 1, rejected: 2 };
      return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9)
        || String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
    })
  });
  return proposals;
}

function filterOperationQualityAutoApprovalPolicyAdjustments(items = [], params = {}) {
  const status = String(operationQualityRecommendationAdjustmentParam(params, "status") || "").trim();
  const candidateType = String(operationQualityRecommendationAdjustmentParam(params, "candidateType") || "").trim();
  const rootMetric = String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim();
  const assignee = String(operationQualityRecommendationAdjustmentParam(params, "assignee") || "").trim().toLowerCase();
  const priority = String(operationQualityRecommendationAdjustmentParam(params, "priority") || "").trim();
  return items
    .filter((item) => !status || item.status === status)
    .filter((item) => !candidateType || item.candidateType === candidateType)
    .filter((item) => !rootMetric || item.rootMetric === rootMetric)
    .filter((item) => !assignee || String(item.assignee || item.target || "").toLowerCase().includes(assignee))
    .filter((item) => !priority || item.priority === priority);
}

function operationQualityAutoApprovalPolicyAdjustmentSummary(items = []) {
  return items.reduce((summary, item) => {
    summary.total += 1;
    summary[item.status] = (summary[item.status] || 0) + 1;
    if (item.active) summary.active += 1;
    if (item.priority === "high" || item.priority === "urgent") summary.high += 1;
    if (item.priority === "medium") summary.medium += 1;
    if (item.duplicateStatus) summary.duplicates += 1;
    return summary;
  }, {
    total: 0,
    proposed: 0,
    approved: 0,
    rejected: 0,
    active: 0,
    high: 0,
    medium: 0,
    duplicates: 0
  });
}

function operationQualityAutoApprovalPolicyAdjustmentScope(policyAdjustment = {}) {
  const rootMetric = String(policyAdjustment.rootMetric || "").trim();
  const assignee = String(policyAdjustment.assignee || "").trim();
  if (rootMetric) {
    return {
      type: "rootMetric",
      key: rootMetric,
      label: policyAdjustment.target || rootMetric
    };
  }
  if (assignee) {
    return {
      type: "assignee",
      key: assignee.toLowerCase(),
      label: policyAdjustment.target || assignee
    };
  }
  return {
    type: "global",
    key: "all",
    label: policyAdjustment.target || policyAdjustment.candidateType || "all auto approvals"
  };
}

function operationQualityAutoApprovalPolicyAdjustmentEventTime(item = {}, fallback = 0) {
  const value = item.approvedAt || item.updatedAt || item.proposedAt || item.createdAt || "";
  const time = new Date(value).getTime();
  return Number.isFinite(time) ? time : fallback;
}

function operationQualityAutoApprovalRecommendationEventTime(item = {}, fallback = 0) {
  const value = item.approvedAt || item.rejectedAt || item.updatedAt || item.proposedAt || item.createdAt || "";
  const time = new Date(value).getTime();
  return Number.isFinite(time) ? time : fallback;
}

function operationQualityAutoApprovalPolicyScopeMatches(policyAdjustment = {}, item = {}) {
  const scope = operationQualityAutoApprovalPolicyAdjustmentScope(policyAdjustment);
  if (scope.type === "global") return true;
  if (scope.type === "rootMetric") return String(item.rootMetric || "").trim() === scope.key;
  if (scope.type === "assignee") {
    const assignee = item.assignee || (item.scopeType === "assignee" ? item.scopeKey : "unassigned");
    return String(assignee || "unassigned").trim().toLowerCase() === scope.key;
  }
  return false;
}

function operationQualityAutoApprovalPolicyRecommendationStats(recommendationItems = []) {
  const totalRecommendations = recommendationItems.length;
  const autoApprovals = recommendationItems.filter((item) => item.status === "approved" && item.approvalMode === "auto").length;
  const manualReviewTransitions = recommendationItems.filter((item) => {
    if (item.status === "approved" && item.approvalMode === "auto") return false;
    return item.status === "proposed" || item.status === "rejected" || item.approvalMode === "manual" || item.approvalMode === "none" || item.autoApprovalPolicy?.eligible === false;
  }).length;
  return {
    totalRecommendations,
    autoApprovals,
    manualReviewTransitions,
    manualReviewTransitionRate: totalRecommendations ? Math.round((manualReviewTransitions / totalRecommendations) * 100) : 0
  };
}

function operationQualityAutoApprovalPolicyPerformanceStats(performanceItems = [], recommendationItems = []) {
  const recommendationStats = operationQualityAutoApprovalPolicyRecommendationStats(recommendationItems);
  const autoApprovalTotal = performanceItems.length;
  const evaluatedItems = performanceItems.filter((item) => Number(item.outcome?.evaluatedCount || 0) > 0);
  const evaluated = evaluatedItems.length;
  const successful = evaluatedItems.filter((item) => item.outcome?.successful).length;
  const falsePositive = evaluatedItems.filter((item) => item.outcome?.falsePositive).length;
  const recurrence = evaluatedItems.filter((item) => Number(item.outcome?.recurrence || 0) > 0).length;
  const rolledBack = performanceItems.filter((item) => item.outcome?.rolledBack || item.rolledBackAt).length;
  const avgEffectScore = evaluated
    ? Math.round(evaluatedItems.reduce((sum, item) => sum + Number(item.outcome?.avgEffectScore || 0), 0) / evaluated)
    : 0;
  return {
    ...recommendationStats,
    autoApprovalTotal,
    evaluated,
    successful,
    falsePositive,
    rolledBack,
    recurrence,
    successRate: evaluated ? Math.round((successful / evaluated) * 100) : 0,
    falsePositiveRate: evaluated ? Math.round((falsePositive / evaluated) * 100) : 0,
    rollbackRate: autoApprovalTotal ? Math.round((rolledBack / autoApprovalTotal) * 100) : 0,
    recurrenceRate: evaluated ? Math.round((recurrence / evaluated) * 100) : 0,
    avgEffectScore
  };
}

function operationQualityAutoApprovalPolicyEffectDelta(before = {}, after = {}) {
  return {
    successRate: Number(after.successRate || 0) - Number(before.successRate || 0),
    falsePositiveRate: Number(after.falsePositiveRate || 0) - Number(before.falsePositiveRate || 0),
    rollbackRate: Number(after.rollbackRate || 0) - Number(before.rollbackRate || 0),
    recurrenceRate: Number(after.recurrenceRate || 0) - Number(before.recurrenceRate || 0),
    manualReviewTransitionRate: Number(after.manualReviewTransitionRate || 0) - Number(before.manualReviewTransitionRate || 0),
    avgEffectScore: Number(after.avgEffectScore || 0) - Number(before.avgEffectScore || 0)
  };
}

function operationQualityAutoApprovalPolicyEffectOutcome(before = {}, after = {}, delta = {}) {
  if (!after.totalRecommendations && !after.autoApprovalTotal) return "pending";
  if (!after.evaluated && !after.manualReviewTransitions) return "pending";
  const riskImproved = Number(delta.falsePositiveRate || 0) <= -10 || Number(delta.rollbackRate || 0) <= -10 || Number(delta.recurrenceRate || 0) <= -10;
  const riskWorse = Number(delta.falsePositiveRate || 0) >= 10 || Number(delta.rollbackRate || 0) >= 10 || Number(delta.recurrenceRate || 0) >= 10;
  const successImproved = Number(delta.successRate || 0) >= 10 || Number(delta.avgEffectScore || 0) >= 10;
  const successWorse = Number(delta.successRate || 0) <= -10 || Number(delta.avgEffectScore || 0) <= -10;
  if (riskWorse || successWorse) return "worse";
  if (riskImproved || successImproved || Number(delta.manualReviewTransitionRate || 0) >= 10) return "improved";
  return "stable";
}

function operationQualityAutoApprovalPolicyEffectScore(before = {}, after = {}, delta = {}, outcome = "pending") {
  if (outcome === "pending") return 0;
  const score = 55
    + Number(delta.successRate || 0) * 0.35
    - Number(delta.falsePositiveRate || 0) * 0.35
    - Number(delta.rollbackRate || 0) * 0.25
    - Number(delta.recurrenceRate || 0) * 0.25
    + Number(delta.manualReviewTransitionRate || 0) * 0.12
    + Number(delta.avgEffectScore || 0) * 0.2;
  return Math.round(clampNumber(score, 0, 100));
}

function operationQualityAutoApprovalPolicyEffectSuggestions(policyAdjustment = {}, before = {}, after = {}, delta = {}, outcome = "pending", effectScore = 0) {
  const suggestions = [];
  const scope = operationQualityAutoApprovalPolicyAdjustmentScope(policyAdjustment);
  if (outcome === "pending") {
    suggestions.push({
      type: "wait_for_more_data",
      priority: "medium",
      reason: "Approved policy has not accumulated enough post-application evidence yet.",
      recommendedAction: "Keep the policy active and reassess after more recommendations or reassessment history is recorded."
    });
    return suggestions;
  }
  if (outcome === "worse" || effectScore < 45) {
    suggestions.push({
      type: "rollback_policy_adjustment",
      priority: "high",
      reason: `Post-policy performance worsened for ${scope.label}: success ${after.successRate}%, false-positive ${after.falsePositiveRate}%, rollback ${after.rollbackRate}%.`,
      recommendedAction: "Review this approved policy for rollback and return the affected scope to manual review until performance stabilizes."
    });
  }
  if (after.falsePositiveRate >= 40 || after.rollbackRate >= 30 || after.recurrenceRate >= 50) {
    suggestions.push({
      type: "additional_tightening",
      priority: after.falsePositiveRate >= 50 || after.rollbackRate >= 40 ? "high" : "medium",
      reason: `Residual risk remains high after policy application: false-positive ${after.falsePositiveRate}%, rollback ${after.rollbackRate}%, recurrence ${after.recurrenceRate}%.`,
      recommendedAction: "Generate an additional tightening candidate or require manual review for this scope."
    });
  }
  if (!suggestions.length) {
    suggestions.push({
      type: "maintain_policy",
      priority: "low",
      reason: `Policy appears ${outcome}; no rollback signal is detected.`,
      recommendedAction: "Keep the approved policy active and continue monitoring post-effect metrics."
    });
  }
  return suggestions;
}

function operationQualityAutoApprovalPolicyPostEffectItem(policyAdjustment = {}, performanceItems = [], recommendationItems = []) {
  const effectiveAt = policyAdjustment.approvedAt || policyAdjustment.updatedAt || policyAdjustment.proposedAt || "";
  const effectiveTime = operationQualityAutoApprovalPolicyAdjustmentEventTime(policyAdjustment, Date.now());
  const matchingPerformance = performanceItems.filter((item) => operationQualityAutoApprovalPolicyScopeMatches(policyAdjustment, item));
  const matchingRecommendations = recommendationItems.filter((item) => operationQualityAutoApprovalPolicyScopeMatches(policyAdjustment, item));
  const beforePerformance = matchingPerformance.filter((item) => operationQualityAutoApprovalPolicyAdjustmentEventTime(item, 0) < effectiveTime);
  const afterPerformance = matchingPerformance.filter((item) => operationQualityAutoApprovalPolicyAdjustmentEventTime(item, 0) >= effectiveTime);
  const beforeRecommendations = matchingRecommendations.filter((item) => operationQualityAutoApprovalRecommendationEventTime(item, 0) < effectiveTime);
  const afterRecommendations = matchingRecommendations.filter((item) => operationQualityAutoApprovalRecommendationEventTime(item, 0) >= effectiveTime);
  const before = operationQualityAutoApprovalPolicyPerformanceStats(beforePerformance, beforeRecommendations);
  const after = operationQualityAutoApprovalPolicyPerformanceStats(afterPerformance, afterRecommendations);
  const delta = operationQualityAutoApprovalPolicyEffectDelta(before, after);
  const outcome = operationQualityAutoApprovalPolicyEffectOutcome(before, after, delta);
  const effectScore = operationQualityAutoApprovalPolicyEffectScore(before, after, delta, outcome);
  const scope = operationQualityAutoApprovalPolicyAdjustmentScope(policyAdjustment);
  return {
    policyAdjustmentId: policyAdjustment.policyAdjustmentId,
    status: policyAdjustment.status,
    active: Boolean(policyAdjustment.active),
    candidateType: policyAdjustment.candidateType,
    target: policyAdjustment.target,
    scope,
    priority: policyAdjustment.priority,
    approvedAt: policyAdjustment.approvedAt || "",
    approvedBy: policyAdjustment.approvedBy || "",
    sourceRecommendation: policyAdjustment.recommendation || "",
    sourcePolicyPatch: policyAdjustment.policyPatch || {},
    sourceBeforePolicy: policyAdjustment.beforePolicy || {},
    sourceAfterPolicy: policyAdjustment.afterPolicy || {},
    effectScore,
    outcome,
    before,
    after,
    delta,
    suggestions: operationQualityAutoApprovalPolicyEffectSuggestions(policyAdjustment, before, after, delta, outcome, effectScore),
    recentAfterItems: afterPerformance
      .sort((a, b) => String(b.approvedAt || "").localeCompare(String(a.approvedAt || "")))
      .slice(0, 5)
      .map((item) => ({
        adjustmentId: item.adjustmentId,
        title: item.title,
        approvedAt: item.approvedAt,
        rootMetric: item.rootMetric,
        assignee: item.assignee,
        outcome: item.outcome?.outcome || "pending",
        effectScore: item.outcome?.avgEffectScore || 0,
        falsePositive: Boolean(item.outcome?.falsePositive),
        rolledBack: Boolean(item.outcome?.rolledBack || item.rolledBackAt)
      }))
  };
}

function operationQualityAutoApprovalPolicyPostEffectSummary(items = []) {
  const evaluated = items.filter((item) => item.outcome !== "pending");
  return {
    total: items.length,
    evaluated: evaluated.length,
    pending: items.filter((item) => item.outcome === "pending").length,
    improved: items.filter((item) => item.outcome === "improved").length,
    stable: items.filter((item) => item.outcome === "stable").length,
    worse: items.filter((item) => item.outcome === "worse").length,
    rollbackSuggested: items.filter((item) => (item.suggestions || []).some((suggestion) => suggestion.type === "rollback_policy_adjustment")).length,
    additionalAdjustmentSuggested: items.filter((item) => (item.suggestions || []).some((suggestion) => suggestion.type === "additional_tightening")).length,
    averageEffectScore: evaluated.length
      ? Math.round(evaluated.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / evaluated.length)
      : 0
  };
}

function operationQualityAutoApprovalPolicyPostEffectReport(policyAdjustments = [], performanceItems = [], recommendationItems = [], params = new URLSearchParams()) {
  const status = String(operationQualityRecommendationAdjustmentParam(params, "policyEffectStatus") || "").trim();
  const items = policyAdjustments
    .map(normalizeOperationQualityAutoApprovalPolicyAdjustment)
    .filter((item) => item.status === "approved")
    .map((item) => operationQualityAutoApprovalPolicyPostEffectItem(item, performanceItems, recommendationItems))
    .filter((item) => !status || item.outcome === status)
    .sort((a, b) => {
      const outcomeRank = { worse: 0, pending: 1, stable: 2, improved: 3 };
      return (outcomeRank[a.outcome] ?? 9) - (outcomeRank[b.outcome] ?? 9)
        || String(b.approvedAt || "").localeCompare(String(a.approvedAt || ""));
    });
  return {
    schema: "external_connector_operation_quality_auto_approval_policy_post_effect_v1",
    generatedAt: new Date().toISOString(),
    filters: { policyEffectStatus: status },
    summary: operationQualityAutoApprovalPolicyPostEffectSummary(items),
    items,
    reportBoundaries: {
      source: "admin-only external connector auto approval policy post-effect tracking",
      hiddenFromBusiness: ["auto approval policy effect", "rollback suggestion", "manual review transition rate", "false positive rate", "internal formula"]
    }
  };
}

function isOperationQualityPostEffectGeneratedPolicyAdjustment(item = {}) {
  return item.sourceContext?.source === "external_connector_auto_approval_policy_post_effect" ||
    Boolean(item.sourcePolicyAdjustmentId && item.sourceSuggestionType);
}

function operationQualityPostEffectCandidateQualityOutcome(candidate = {}, effectByPolicyId = new Map()) {
  if (candidate.status === "rejected") return "rejected";
  if (candidate.status === "proposed") return "pending_review";
  const postEffect = effectByPolicyId.get(candidate.policyAdjustmentId) || null;
  if (!postEffect) return candidate.status === "approved" ? "pending_effect" : "pending_review";
  if (postEffect.outcome === "improved" || postEffect.outcome === "stable") return "successful";
  if (postEffect.outcome === "worse") return "failed";
  if (postEffect.outcome === "pending") return "pending_effect";
  return "neutral";
}

function operationQualityPostEffectCandidateRepeat(candidate = {}, candidates = []) {
  const candidateTime = operationQualityAutoApprovalPolicyAdjustmentEventTime(candidate, 0);
  const rootMetric = String(candidate.rootMetric || "").trim();
  const assignee = String(candidate.assignee || "").trim();
  const candidateType = String(candidate.candidateType || "").trim();
  const sourceId = String(candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "").trim();
  const repeat = candidates
    .filter((item) => item.policyAdjustmentId !== candidate.policyAdjustmentId)
    .filter((item) => String(item.candidateType || "").trim() === candidateType)
    .filter((item) => String(item.rootMetric || "").trim() === rootMetric)
    .filter((item) => String(item.assignee || "").trim() === assignee)
    .filter((item) => {
      const itemTime = operationQualityAutoApprovalPolicyAdjustmentEventTime(item, 0);
      return itemTime >= candidateTime;
    })
    .find((item) => {
      const itemSourceId = String(item.sourcePolicyAdjustmentId || item.sourceContext?.policyAdjustmentId || "").trim();
      return !sourceId || !itemSourceId || itemSourceId !== sourceId || item.status === "proposed";
    });
  return {
    repeatRecommended: Boolean(repeat),
    repeatPolicyAdjustmentId: repeat?.policyAdjustmentId || "",
    reason: repeat
      ? `Another ${candidateType} candidate was generated again for ${rootMetric || assignee || candidate.target || "the same scope"}.`
      : ""
  };
}

function operationQualityPostEffectCandidateQualityItem(candidate = {}, effectByPolicyId = new Map(), allCandidates = []) {
  const postEffect = effectByPolicyId.get(candidate.policyAdjustmentId) || null;
  const repeat = operationQualityPostEffectCandidateRepeat(candidate, allCandidates);
  const outcome = operationQualityPostEffectCandidateQualityOutcome(candidate, effectByPolicyId);
  return {
    policyAdjustmentId: candidate.policyAdjustmentId,
    candidateType: candidate.candidateType,
    target: candidate.target,
    rootMetric: candidate.rootMetric,
    assignee: candidate.assignee,
    priority: candidate.priority,
    status: candidate.status,
    sourcePolicyAdjustmentId: candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "",
    sourceSuggestionType: candidate.sourceSuggestionType || candidate.sourceContext?.suggestionType || "",
    sourceEffectOutcome: candidate.sourceEffectOutcome || candidate.sourceContext?.outcome || "",
    sourceEffectScore: candidate.sourceEffectScore ?? candidate.sourceContext?.effectScore ?? null,
    proposedAt: candidate.proposedAt || "",
    approvedAt: candidate.approvedAt || "",
    approvedBy: candidate.approvedBy || "",
    rejectedAt: candidate.rejectedAt || "",
    rejectedBy: candidate.rejectedBy || "",
    reviewReason: candidate.reviewReason || candidate.rejectReason || "",
    postEffectOutcome: postEffect?.outcome || "",
    postEffectScore: postEffect?.effectScore ?? null,
    postEffectDelta: postEffect?.delta || {},
    qualityOutcome: outcome,
    successful: outcome === "successful",
    evaluated: ["successful", "failed", "neutral"].includes(outcome),
    repeatRecommended: repeat.repeatRecommended,
    repeatPolicyAdjustmentId: repeat.repeatPolicyAdjustmentId,
    repeatRecommendationReason: repeat.reason
  };
}

function operationQualityPostEffectCandidateQualityGroup(items = [], candidateType = "all") {
  const total = items.length;
  const approved = items.filter((item) => item.status === "approved").length;
  const rejected = items.filter((item) => item.status === "rejected").length;
  const proposed = items.filter((item) => item.status === "proposed").length;
  const evaluated = items.filter((item) => item.evaluated).length;
  const successful = items.filter((item) => item.successful).length;
  const failed = items.filter((item) => item.qualityOutcome === "failed").length;
  const repeatRecommended = items.filter((item) => item.repeatRecommended).length;
  const rejectionReasonMap = new Map();
  items
    .filter((item) => item.status === "rejected")
    .forEach((item) => {
      const reason = item.reviewReason || "No rejection reason recorded.";
      rejectionReasonMap.set(reason, (rejectionReasonMap.get(reason) || 0) + 1);
    });
  return {
    candidateType,
    total,
    proposed,
    approved,
    rejected,
    evaluated,
    successful,
    failed,
    repeatRecommended,
    approvalRate: approved + rejected ? Math.round((approved / (approved + rejected)) * 100) : 0,
    approvalSuccessRate: evaluated ? Math.round((successful / evaluated) * 100) : 0,
    repeatRecommendationRate: total ? Math.round((repeatRecommended / total) * 100) : 0,
    rejectionReasons: [...rejectionReasonMap.entries()]
      .map(([reason, count]) => ({ reason, count }))
      .sort((a, b) => b.count - a.count || String(a.reason).localeCompare(String(b.reason)))
      .slice(0, 8)
  };
}

function operationQualityPostEffectCandidateQualityReport(policyAdjustments = [], postEffectItems = [], params = new URLSearchParams()) {
  const effectByPolicyId = new Map(postEffectItems.map((item) => [item.policyAdjustmentId, item]));
  const allCandidates = policyAdjustments
    .map(normalizeOperationQualityAutoApprovalPolicyAdjustment)
    .filter(isOperationQualityPostEffectGeneratedPolicyAdjustment);
  const type = String(operationQualityRecommendationAdjustmentParam(params, "candidateType") || "").trim();
  const target = String(operationQualityRecommendationAdjustmentParam(params, "target") || "").trim().toLowerCase();
  const filtered = allCandidates
    .filter((item) => !type || item.candidateType === type)
    .filter((item) => !target || String(item.target || item.rootMetric || item.assignee || "").toLowerCase().includes(target))
    .map((item) => operationQualityPostEffectCandidateQualityItem(item, effectByPolicyId, allCandidates));
  const byType = [...new Set(filtered.map((item) => item.candidateType || "unknown"))]
    .sort()
    .map((candidateType) => operationQualityPostEffectCandidateQualityGroup(filtered.filter((item) => item.candidateType === candidateType), candidateType))
    .filter((row) => row.total > 0);
  return {
    schema: "external_connector_operation_quality_auto_approval_post_effect_candidate_quality_v1",
    generatedAt: new Date().toISOString(),
    filters: { candidateType: type, target },
    summary: operationQualityPostEffectCandidateQualityGroup(filtered, "all"),
    byType,
    items: filtered
      .sort((a, b) => Number(b.repeatRecommended || 0) - Number(a.repeatRecommended || 0)
        || String(b.approvedAt || b.rejectedAt || b.proposedAt || "").localeCompare(String(a.approvedAt || a.rejectedAt || a.proposedAt || "")))
      .slice(0, Math.max(1, Math.min(500, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)))),
    reportBoundaries: {
      source: "admin-only external connector post-effect policy candidate quality tracking",
      hiddenFromBusiness: ["policy candidate quality", "approval success", "rejection reasons", "repeat recommendation", "post-effect outcomes", "internal formula"]
    }
  };
}

function operationQualityPostEffectCandidateQualityBasis(qualityReport = {}, candidateType = "") {
  const row = (qualityReport.byType || []).find((item) => item.candidateType === candidateType) || {};
  const total = Number(row.total || 0);
  const rejected = Number(row.rejected || 0);
  const repeatRecommended = Number(row.repeatRecommended || 0);
  const topRejection = row.rejectionReasons?.[0] || null;
  return {
    candidateType,
    total,
    proposed: Number(row.proposed || 0),
    approved: Number(row.approved || 0),
    rejected,
    evaluated: Number(row.evaluated || 0),
    successful: Number(row.successful || 0),
    failed: Number(row.failed || 0),
    approvalRate: Number(row.approvalRate || 0),
    approvalSuccessRate: Number(row.approvalSuccessRate || 0),
    repeatRecommended,
    repeatRecommendationRate: Number(row.repeatRecommendationRate || (total ? Math.round((repeatRecommended / total) * 100) : 0)),
    rejectionRate: total ? Math.round((rejected / total) * 100) : 0,
    topRejectionReason: topRejection?.reason || "",
    topRejectionCount: Number(topRejection?.count || 0),
    rejectionReasons: (row.rejectionReasons || []).slice(0, 3)
  };
}

function operationQualityPostEffectCandidateQualityLearning(candidate = {}, qualityReport = {}) {
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  const previousQuality = operationQualityPostEffectCandidateQualityBasis(qualityReport, candidateType);
  const priorityBefore = ["low", "medium", "high"].includes(String(candidate.priority || "").trim())
    ? String(candidate.priority || "").trim()
    : "medium";
  const strongHistory = previousQuality.evaluated >= 1 &&
    previousQuality.approved >= 1 &&
    previousQuality.approvalSuccessRate >= 70 &&
    previousQuality.repeatRecommendationRate <= 25 &&
    previousQuality.rejectionRate <= 40;
  const weakHistory = (previousQuality.evaluated >= 1 && previousQuality.approvalSuccessRate <= 40) ||
    previousQuality.repeatRecommendationRate >= 50 ||
    (previousQuality.rejected >= 2 && previousQuality.approvalRate <= 40);
  const direction = strongHistory ? "boost" : weakHistory ? "downgrade" : "neutral";
  const priorityAfter = adjustOperationQualityPriority(priorityBefore, direction === "boost" ? 1 : direction === "downgrade" ? -1 : 0);
  const applied = direction !== "neutral" && priorityAfter !== priorityBefore;
  let reason = "No prior external connector post-effect candidate quality history; base priority is retained.";
  if (previousQuality.total > 0 && direction === "boost") {
    reason = `Previous ${candidateType} candidates show ${previousQuality.approvalSuccessRate}% approved-success across ${previousQuality.evaluated} evaluated item(s), ${previousQuality.repeatRecommendationRate}% repeat recommendation, and ${previousQuality.rejectionRate}% rejection; priority ${priorityBefore} -> ${priorityAfter}.`;
  } else if (previousQuality.total > 0 && direction === "downgrade") {
    reason = `Previous ${candidateType} candidates show ${previousQuality.approvalSuccessRate}% approved-success, ${previousQuality.repeatRecommendationRate}% repeat recommendation, and ${previousQuality.rejectionRate}% rejection${previousQuality.topRejectionReason ? `; top rejection reason: ${previousQuality.topRejectionReason}` : ""}; priority ${priorityBefore} -> ${priorityAfter}.`;
  } else if (previousQuality.total > 0) {
    reason = `Previous ${candidateType} candidate quality is mixed: approved-success ${previousQuality.approvalSuccessRate}%, repeat ${previousQuality.repeatRecommendationRate}%, rejection ${previousQuality.rejectionRate}%; priority remains ${priorityBefore}.`;
  }
  return {
    applied,
    active: previousQuality.total > 0,
    direction,
    candidateType,
    priorityBefore,
    priorityAfter,
    suggestedPriorityAfter: priorityAfter,
    reason,
    previousQuality
  };
}

function operationQualityPostEffectCandidateQualityLearningCalibrationId(candidate = {}) {
  return hashId("xoqpql", [
    candidate.candidateType || candidate.type || "",
    "external_connector_post_effect_candidate_quality_learning"
  ].join("|"));
}

function operationQualityPostEffectCandidateQualityLearningSimulation(candidate = {}, suggested = {}, active = null) {
  const priorityBefore = ["low", "medium", "high"].includes(String(candidate.priority || suggested.priorityBefore || "").trim())
    ? String(candidate.priority || suggested.priorityBefore || "").trim()
    : "medium";
  const suggestedPriorityAfter = ["low", "medium", "high"].includes(String(suggested.priorityAfter || "").trim())
    ? String(suggested.priorityAfter || "").trim()
    : priorityBefore;
  const activePriorityAfter = active && ["low", "medium", "high"].includes(String(active.priorityAfter || "").trim())
    ? String(active.priorityAfter || "").trim()
    : priorityBefore;
  const recommendationBefore = String(candidate.recommendation || "").trim();
  const suggestedRecommendationAfter = [recommendationBefore, `Quality learning proposal: ${suggested.reason || ""}`].filter(Boolean).join(" ");
  const activeRecommendationAfter = active
    ? [recommendationBefore, `Approved quality learning: ${active.reason || suggested.reason || ""}`].filter(Boolean).join(" ")
    : recommendationBefore;
  return {
    priorityBefore,
    suggestedPriorityAfter,
    activePriorityAfter,
    recommendationBefore,
    suggestedRecommendationAfter,
    activeRecommendationAfter,
    expectedImpactBefore: candidate.expectedImpact || {},
    expectedImpactAfter: {
      ...(candidate.expectedImpact || {}),
      priorityBefore,
      suggestedPriorityAfter,
      activePriorityAfter,
      learningApplied: Boolean(active),
      learningBasis: active?.reason || suggested.reason || "",
      previousQuality: suggested.previousQuality || {}
    }
  };
}

function normalizeOperationQualityPostEffectCandidateQualityCalibration(input = {}) {
  const now = new Date().toISOString();
  const suggested = input.suggestedCalibration && typeof input.suggestedCalibration === "object"
    ? input.suggestedCalibration
    : input.qualityCalibration?.suggestedCalibration && typeof input.qualityCalibration.suggestedCalibration === "object"
      ? input.qualityCalibration.suggestedCalibration
      : input.qualityCalibration && typeof input.qualityCalibration === "object"
        ? input.qualityCalibration
        : {};
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(input.status || "proposed");
  const activeCalibration = input.activeCalibration && typeof input.activeCalibration === "object"
    ? input.activeCalibration
    : slaPolicyCandidateQualityCalibrationActive({ status })
      ? suggested
      : null;
  return {
    calibrationId: String(input.calibrationId || operationQualityPostEffectCandidateQualityLearningCalibrationId(input)).trim(),
    candidateType: String(input.candidateType || input.type || suggested.candidateType || "").trim(),
    target: String(input.target || "").trim(),
    status,
    active: slaPolicyCandidateQualityCalibrationActive({ status }),
    suggestedCalibration: suggested,
    activeCalibration,
    simulation: input.simulation && typeof input.simulation === "object" ? input.simulation : {},
    previousQuality: input.previousQuality && typeof input.previousQuality === "object" ? input.previousQuality : suggested.previousQuality || {},
    reviewReason: String(input.reviewReason || input.reason || "").trim(),
    overrideReason: String(input.overrideReason || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    updatedAt: input.updatedAt || input.reviewedAt || input.proposedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system",
    events: Array.isArray(input.events) ? input.events.map(slaPolicyCandidateQualityCalibrationEvent) : []
  };
}

function operationQualityPostEffectCandidateQualityCalibrationMap(items = []) {
  return new Map(items
    .map(normalizeOperationQualityPostEffectCandidateQualityCalibration)
    .map((item) => [item.calibrationId, item]));
}

function applyOperationQualityPostEffectCandidateQualityLearning(candidate = {}, qualityReport = {}, workflowItems = []) {
  const calibrationId = operationQualityPostEffectCandidateQualityLearningCalibrationId(candidate);
  const suggestedCalibration = operationQualityPostEffectCandidateQualityLearning(candidate, qualityReport);
  const workflowItem = operationQualityPostEffectCandidateQualityCalibrationMap(workflowItems).get(calibrationId) || null;
  const activeWorkflow = workflowItem && slaPolicyCandidateQualityCalibrationActive(workflowItem) ? workflowItem : null;
  const activeCalibration = activeWorkflow?.activeCalibration || null;
  const priorityAfter = activeCalibration?.priorityAfter || suggestedCalibration.priorityBefore || candidate.priority || "medium";
  const learningSuffix = activeCalibration
    ? `Approved quality learning: ${activeCalibration.reason || suggestedCalibration.reason}`
    : "";
  const simulation = operationQualityPostEffectCandidateQualityLearningSimulation(candidate, suggestedCalibration, activeCalibration);
  const qualityCalibration = {
    calibrationId,
    status: workflowItem?.status || (suggestedCalibration.previousQuality?.total ? "proposed" : "none"),
    active: Boolean(activeCalibration),
    applied: Boolean(activeCalibration && priorityAfter !== suggestedCalibration.priorityBefore),
    direction: activeCalibration?.direction || suggestedCalibration.direction,
    candidateType: suggestedCalibration.candidateType,
    priorityBefore: suggestedCalibration.priorityBefore,
    priorityAfter,
    suggestedPriorityAfter: suggestedCalibration.priorityAfter,
    reason: activeCalibration?.reason || suggestedCalibration.reason,
    reviewReason: workflowItem?.reviewReason || "",
    overrideReason: workflowItem?.overrideReason || "",
    previousQuality: suggestedCalibration.previousQuality,
    suggestedCalibration,
    activeCalibration,
    simulation,
    reviewedAt: workflowItem?.reviewedAt || "",
    reviewedBy: workflowItem?.reviewedBy || "",
    learningSource: "external_connector_post_effect_candidate_quality"
  };
  return {
    ...candidate,
    priority: priorityAfter,
    basis: [candidate.basis, learningSuffix].filter(Boolean).join(" "),
    recommendation: [candidate.recommendation, learningSuffix].filter(Boolean).join(" "),
    qualityCalibration,
    sourceContext: {
      ...(candidate.sourceContext || {}),
      qualityCalibration
    }
  };
}

function shouldStoreOperationQualityPostEffectCandidateQualityCalibration(candidate = {}) {
  const calibration = candidate.qualityCalibration || {};
  const suggested = calibration.suggestedCalibration || calibration;
  return Boolean(suggested?.previousQuality?.total || suggested?.direction !== "neutral");
}

function buildOperationQualityPostEffectCandidateQualityCalibrationProposal(candidate = {}, existing = null) {
  const calibration = candidate.qualityCalibration || {};
  const suggested = calibration.suggestedCalibration || calibration;
  const existingNormalized = existing ? normalizeOperationQualityPostEffectCandidateQualityCalibration(existing) : null;
  const status = existingNormalized?.status || "proposed";
  const activeCalibration = slaPolicyCandidateQualityCalibrationActive({ status })
    ? existingNormalized?.activeCalibration || suggested
    : null;
  const calibrationId = calibration.calibrationId || operationQualityPostEffectCandidateQualityLearningCalibrationId(candidate);
  const simulationCandidate = {
    ...candidate,
    priority: suggested.priorityBefore || existingNormalized?.simulation?.priorityBefore || candidate.priority,
    recommendation: calibration.simulation?.recommendationBefore || existingNormalized?.simulation?.recommendationBefore || candidate.recommendation,
    expectedImpact: calibration.simulation?.expectedImpactBefore || existingNormalized?.simulation?.expectedImpactBefore || candidate.expectedImpact
  };
  const creationEvent = slaPolicyCandidateQualityCalibrationEvent({
    calibrationId,
    eventType: existingNormalized ? "refreshed" : "proposed",
    previousStatus: existingNormalized?.status || "",
    nextStatus: status,
    reason: "External connector post-effect candidate quality learning proposal generated."
  });
  return normalizeOperationQualityPostEffectCandidateQualityCalibration({
    ...(existing || {}),
    calibrationId,
    candidateType: candidate.candidateType,
    target: candidate.target,
    status,
    suggestedCalibration: suggested,
    activeCalibration,
    simulation: operationQualityPostEffectCandidateQualityLearningSimulation(simulationCandidate, suggested, activeCalibration),
    previousQuality: suggested.previousQuality || {},
    reviewReason: existingNormalized?.reviewReason || "",
    overrideReason: existingNormalized?.overrideReason || "",
    proposedAt: existingNormalized?.proposedAt || new Date().toISOString(),
    proposedBy: existingNormalized?.proposedBy || "system",
    updatedAt: new Date().toISOString(),
    updatedBy: "system",
    events: existingNormalized?.events?.length ? existingNormalized.events : [creationEvent]
  });
}

async function upsertOperationQualityPostEffectCandidateQualityCalibrationProposals(candidates = []) {
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations();
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityPostEffectCandidateQualityCalibration)
    : [];
  const byId = new Map(existingItems.map((item) => [item.calibrationId, item]));
  candidates
    .filter(shouldStoreOperationQualityPostEffectCandidateQualityCalibration)
    .forEach((candidate) => {
      const calibrationId = candidate.qualityCalibration?.calibrationId ||
        operationQualityPostEffectCandidateQualityLearningCalibrationId(candidate);
      const proposal = buildOperationQualityPostEffectCandidateQualityCalibrationProposal(candidate, byId.get(calibrationId) || null);
      byId.set(calibrationId, proposal);
    });
  const sorted = [...byId.values()].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, overridden: 2, rejected: 3, deactivated: 4 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
  });
  await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations({
    ...data,
    items: sorted
  });
  return sorted;
}

function filterOperationQualityPostEffectCandidateQualityCalibrations(items = [], params = {}) {
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(operationQualityRecommendationAdjustmentParam(params, "status") || "");
  const type = String(operationQualityRecommendationAdjustmentParam(params, "candidateType") || operationQualityRecommendationAdjustmentParam(params, "type") || "").trim();
  return items
    .filter((item) => !operationQualityRecommendationAdjustmentParam(params, "status") || item.status === status)
    .filter((item) => !type || item.candidateType === type);
}

function operationQualityPostEffectCandidateQualityCalibrationSummary(items = []) {
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    overridden: items.filter((item) => item.status === "overridden").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    active: items.filter((item) => slaPolicyCandidateQualityCalibrationActive(item)).length,
    boost: items.filter((item) => (item.suggestedCalibration || {}).direction === "boost").length,
    downgrade: items.filter((item) => (item.suggestedCalibration || {}).direction === "downgrade").length
  };
}

function operationQualityPostEffectCandidateQualityCalibrationWorkflowReport(items = [], params = {}) {
  const normalized = items.map(normalizeOperationQualityPostEffectCandidateQualityCalibration);
  const filtered = filterOperationQualityPostEffectCandidateQualityCalibrations(normalized, params);
  const limit = Math.max(1, Math.min(500, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)));
  return {
    role: "admin",
    schema: "external_connector_operation_quality_post_effect_candidate_quality_calibration_workflow_v1",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(operationQualityRecommendationAdjustmentParam(params, "status") || "").trim(),
      candidateType: String(operationQualityRecommendationAdjustmentParam(params, "candidateType") || operationQualityRecommendationAdjustmentParam(params, "type") || "").trim(),
      limit
    },
    summary: operationQualityPostEffectCandidateQualityCalibrationSummary(filtered),
    fullSummary: operationQualityPostEffectCandidateQualityCalibrationSummary(normalized),
    items: filtered
      .sort((a, b) => {
        const statusRank = { proposed: 0, approved: 1, overridden: 2, rejected: 3, deactivated: 4 };
        return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
          String(b.updatedAt || b.reviewedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.reviewedAt || a.proposedAt || ""));
      })
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only external connector post-effect candidate quality learning calibration workflow",
      hiddenFromBusiness: ["quality learning proposals", "approval status", "override reasons", "candidate quality history", "operator review events", "internal formula"]
    }
  };
}

async function externalConnectorOperationQualityPostEffectCandidateQualityCalibrationWorkflowReport(params = new URLSearchParams()) {
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations();
  return operationQualityPostEffectCandidateQualityCalibrationWorkflowReport(data.items || [], params);
}

async function reviewExternalConnectorOperationQualityPostEffectCandidateQualityCalibration(payload = {}) {
  const calibrationId = String(payload.calibrationId || payload.id || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  const status = decision === "override" ? "overridden" : normalizeSlaPolicyCandidateQualityCalibrationStatus(decision);
  if (!calibrationId || !["approved", "rejected", "overridden"].includes(status)) {
    const error = new Error("External connector candidate quality calibration id and approved/rejected/override decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityPostEffectCandidateQualityCalibration)
    : [];
  const target = items.find((item) => item.calibrationId === calibrationId);
  if (!target) {
    const error = new Error("External connector candidate quality calibration proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reviewReason = String(payload.reviewReason || payload.reason || "").trim();
  const overrideReason = String(payload.overrideReason || "").trim();
  const suggested = target.suggestedCalibration || {};
  let activeCalibration = null;
  if (status === "approved") {
    activeCalibration = {
      ...suggested,
      applied: suggested.direction !== "neutral" && suggested.priorityAfter !== suggested.priorityBefore,
      reason: reviewReason || suggested.reason || "Admin approved suggested external connector post-effect candidate quality learning."
    };
  } else if (status === "overridden") {
    const priorityBefore = ["low", "medium", "high"].includes(String(suggested.priorityBefore || "").trim())
      ? String(suggested.priorityBefore || "").trim()
      : "medium";
    const overridePriorityAfter = ["low", "medium", "high"].includes(String(payload.overridePriorityAfter || payload.priorityAfter || "").trim())
      ? String(payload.overridePriorityAfter || payload.priorityAfter || "").trim()
      : suggested.priorityAfter || priorityBefore;
    const beforeRank = operationQualityPriorityRank(priorityBefore);
    const afterRank = operationQualityPriorityRank(overridePriorityAfter);
    activeCalibration = {
      ...suggested,
      direction: afterRank > beforeRank ? "boost" : afterRank < beforeRank ? "downgrade" : "neutral",
      priorityAfter: overridePriorityAfter,
      applied: overridePriorityAfter !== priorityBefore,
      reason: overrideReason || reviewReason || `Admin override set active external connector quality learning priority ${priorityBefore} -> ${overridePriorityAfter}.`
    };
  }
  const simulationCandidate = {
    priority: suggested.priorityBefore,
    recommendation: target.simulation?.recommendationBefore || "",
    expectedImpact: target.simulation?.expectedImpactBefore || {}
  };
  const event = slaPolicyCandidateQualityCalibrationEvent({
    calibrationId,
    eventType: status,
    eventAt: now,
    eventBy: reviewer,
    previousStatus: target.status,
    nextStatus: status,
    reason: reviewReason,
    overridePriorityAfter: activeCalibration?.priorityAfter || "",
    overrideReason
  });
  const updatedTarget = normalizeOperationQualityPostEffectCandidateQualityCalibration({
    ...target,
    status,
    activeCalibration,
    simulation: operationQualityPostEffectCandidateQualityLearningSimulation(
      simulationCandidate,
      suggested,
      activeCalibration
    ),
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason,
    overrideReason,
    updatedAt: now,
    updatedBy: reviewer,
    events: [event, ...(target.events || [])]
  });
  const updatedItems = items.map((item) => item.calibrationId === calibrationId ? updatedTarget : item);
  await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  await appendExternalConnectorOperationQualityPostEffectCandidateQualityCalibrationLog(event);
  return {
    ok: true,
    item: updatedTarget,
    workflow: operationQualityPostEffectCandidateQualityCalibrationWorkflowReport(updatedItems, {}),
    reportBoundaries: {
      source: "admin-only external connector post-effect candidate quality calibration review decision",
      hiddenFromBusiness: ["quality learning approval status", "override reason", "candidate quality evidence", "review events"]
    }
  };
}

function operationQualityPostEffectCandidateQualityCalibrationPerformanceItem(calibration = {}, candidateQualityReport = {}) {
  const normalized = normalizeOperationQualityPostEffectCandidateQualityCalibration(calibration);
  const byType = new Map((candidateQualityReport.byType || []).map((row) => [row.candidateType, row]));
  const before = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetric(
    normalized.previousQuality || normalized.suggestedCalibration?.previousQuality || {}
  );
  const after = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetric(
    byType.get(normalized.candidateType) || {}
  );
  const delta = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetricDelta(before, after);
  const performanceScore = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceScore(before, after, normalized.status);
  const base = {
    calibrationId: normalized.calibrationId,
    candidateType: normalized.candidateType,
    target: normalized.target,
    status: normalized.status,
    active: slaPolicyCandidateQualityCalibrationActive(normalized),
    decisionType: normalized.status,
    decisionAt: normalized.reviewedAt || normalized.updatedAt || normalized.proposedAt,
    decisionBy: normalized.reviewedBy || normalized.updatedBy || normalized.proposedBy,
    reviewReason: normalized.reviewReason,
    overrideReason: normalized.overrideReason,
    direction: normalized.activeCalibration?.direction || normalized.suggestedCalibration?.direction || "neutral",
    priorityBefore: normalized.suggestedCalibration?.priorityBefore || "",
    suggestedPriorityAfter: normalized.suggestedCalibration?.priorityAfter || "",
    activePriorityAfter: normalized.activeCalibration?.priorityAfter || "",
    before,
    after,
    delta,
    rejectionReasonChange: {
      beforeTopReason: before.topRejectionReason || "",
      beforeTopCount: before.topRejectionCount || 0,
      afterTopReason: after.topRejectionReason || "",
      afterTopCount: after.topRejectionCount || 0,
      changed: String(before.topRejectionReason || "") !== String(after.topRejectionReason || "")
    },
    performanceScore,
    performanceGrade: performanceGrade(performanceScore)
  };
  const performanceState = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceState(base);
  const reReviewReason = performanceState === "weak_active"
    ? `Active ${normalized.candidateType} external connector candidate quality calibration is underperforming: score ${performanceScore}, approval success ${after.approvalSuccessRate}%, repeat ${after.repeatRecommendationRate}%, rejection ${after.rejectionRate}%.`
    : "";
  return {
    ...base,
    performanceState,
    reReviewNeeded: Boolean(reReviewReason),
    reReviewReason
  };
}

function operationQualityPostEffectCandidateQualityCalibrationReReviewCandidate(item = {}) {
  return {
    rereviewId: hashId("xoqpqlrr", [
      item.calibrationId || "",
      item.candidateType || "",
      item.performanceState || "",
      item.performanceScore ?? ""
    ].join("|")),
    source: "external_connector_post_effect_candidate_quality_calibration_performance",
    calibrationId: item.calibrationId,
    candidateType: item.candidateType,
    target: item.target || "",
    status: "candidate",
    owner: item.decisionBy || "admin",
    dueDate: kstDate(7),
    priority: Number(item.performanceScore || 0) <= 35 ? "urgent" : "high",
    performanceScore: item.performanceScore,
    performanceState: item.performanceState,
    decisionType: item.decisionType,
    decisionAt: item.decisionAt,
    reason: item.reReviewReason,
    recommendedAction: "reopen_external_connector_candidate_quality_calibration_review",
    before: item.before,
    after: item.after,
    delta: item.delta,
    sourceSnapshot: {
      calibrationId: item.calibrationId,
      candidateType: item.candidateType,
      status: item.status,
      active: item.active,
      performanceScore: item.performanceScore,
      performanceState: item.performanceState,
      rejectionReasonChange: item.rejectionReasonChange || {}
    }
  };
}

function operationQualityPostEffectCandidateQualityCalibrationPerformanceReport(calibrations = [], candidateQualityReport = {}, params = {}) {
  const allItems = calibrations
    .map((item) => operationQualityPostEffectCandidateQualityCalibrationPerformanceItem(item, candidateQualityReport))
    .filter((item) => ["approved", "overridden", "rejected"].includes(item.status));
  const filtered = filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceItems(allItems, params);
  const limit = Math.max(1, Math.min(500, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || params.limit || 120)));
  const sorted = [...filtered].sort((a, b) => {
    const stateRank = { weak_active: 0, watch: 1, pending: 2, strong_match: 3 };
    return (stateRank[a.performanceState] ?? 9) - (stateRank[b.performanceState] ?? 9) ||
      Number(a.performanceScore || 0) - Number(b.performanceScore || 0) ||
      String(b.decisionAt || "").localeCompare(String(a.decisionAt || ""));
  });
  const reReviewCandidates = sorted
    .filter((item) => item.reReviewNeeded && item.active)
    .map(operationQualityPostEffectCandidateQualityCalibrationReReviewCandidate);
  return {
    role: "admin",
    schema: "external_connector_operation_quality_post_effect_candidate_quality_calibration_performance_v1",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(operationQualityRecommendationAdjustmentParam(params, "status") || "").trim(),
      candidateType: String(operationQualityRecommendationAdjustmentParam(params, "candidateType") || operationQualityRecommendationAdjustmentParam(params, "type") || "").trim(),
      performanceState: String(operationQualityRecommendationAdjustmentParam(params, "performanceState") || operationQualityRecommendationAdjustmentParam(params, "state") || "").trim(),
      limit
    },
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceSummary(allItems),
    byDecision: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceGroup(filtered, (item) => item.decisionType, (item) => item.decisionType),
    byType: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceGroup(filtered, (item) => item.candidateType, (item) => item.candidateType),
    reReviewCandidates: reReviewCandidates.slice(0, limit),
    items: sorted.slice(0, limit),
    reportBoundaries: {
      source: "admin-only external connector candidate quality calibration decision performance",
      hiddenFromBusiness: ["quality calibration decision performance", "approval and override decisions", "re-review candidates", "candidate approval outcomes", "rejection reason changes", "operator quality signals", "internal formula"]
    }
  };
}

async function externalConnectorOperationQualityPostEffectCandidateQualityCalibrationPerformanceReport(params = new URLSearchParams()) {
  const [calibrationData, policyAdjustmentData, adjustmentData, historyData, logData] = await Promise.all([
    readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments(),
    readExternalConnectorOperationQualityRecommendationAdjustments(),
    readExternalConnectorOperationQualityActionReassessmentHistory(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalLogs()
  ]);
  const historyItems = (historyData.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const logs = (logData.items || []).map(normalizeOperationQualityRecommendationAutoApprovalLog);
  const recommendationItems = (adjustmentData.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const performanceItems = recommendationItems
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible)
    .map((item) => operationQualityRecommendationAutoApprovalPerformanceItem(item, historyItems, logs));
  const postEffectReport = operationQualityAutoApprovalPolicyPostEffectReport(policyAdjustmentData.items || [], performanceItems, recommendationItems, params);
  const candidateQuality = operationQualityPostEffectCandidateQualityReport(policyAdjustmentData.items || [], postEffectReport.items || [], params);
  return operationQualityPostEffectCandidateQualityCalibrationPerformanceReport(calibrationData.items || [], candidateQuality, params);
}

function operationQualityPostEffectCandidateQualityCalibrationRereviewId(item = {}) {
  return hashId("xoqpqlor", [
    item.calibrationId || "",
    item.candidateType || "",
    "external_connector_candidate_quality_calibration_rereview"
  ].join("|"));
}

function normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview(input = {}) {
  const now = new Date().toISOString();
  const dueDate = String(input.dueDate || input.targetDate || "").slice(0, 10);
  return {
    rereviewId: String(input.rereviewId || operationQualityPostEffectCandidateQualityCalibrationRereviewId(input)).trim(),
    source: String(input.source || "external_connector_post_effect_candidate_quality_calibration_performance").trim(),
    calibrationId: String(input.calibrationId || "").trim(),
    candidateType: String(input.candidateType || "").trim(),
    target: String(input.target || "").trim(),
    owner: String(input.owner || input.assignee || "").trim(),
    dueDate,
    dueState: slaPolicyCandidateQualityRereviewDueState(dueDate),
    status: normalizeSlaPolicyCandidateQualityRereviewStatus(input.status || input.reviewStatus || "open"),
    memo: String(input.memo || "").trim(),
    followUpActionType: normalizeSlaPolicyCandidateQualityRereviewAction(input.followUpActionType || input.actionType || "watch"),
    performanceScore: Math.max(0, Math.min(100, Math.round(Number(input.performanceScore || 0)))),
    performanceState: String(input.performanceState || "").trim(),
    decisionType: String(input.decisionType || "").trim(),
    decisionAt: input.decisionAt || "",
    reReviewReason: String(input.reReviewReason || input.reason || "").trim(),
    recommendedAction: String(input.recommendedAction || "").trim(),
    sourceSnapshot: input.sourceSnapshot && typeof input.sourceSnapshot === "object" ? input.sourceSnapshot : {},
    before: input.before && typeof input.before === "object" ? input.before : {},
    after: input.after && typeof input.after === "object" ? input.after : {},
    delta: input.delta && typeof input.delta === "object" ? input.delta : {},
    createdAt: input.createdAt || now,
    createdBy: String(input.createdBy || "system").trim() || "system",
    updatedAt: input.updatedAt || now,
    updatedBy: String(input.updatedBy || input.owner || "system").trim() || "system",
    completedAt: input.completedAt || "",
    completedBy: String(input.completedBy || "").trim(),
    completionResult: String(input.completionResult || "").trim(),
    linkedCalibrationResult: input.linkedCalibrationResult && typeof input.linkedCalibrationResult === "object" ? input.linkedCalibrationResult : null,
    events: Array.isArray(input.events) ? input.events : []
  };
}

function buildOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidate(candidate = {}, existing = null) {
  const current = existing ? normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview(existing) : null;
  const now = new Date().toISOString();
  return normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview({
    ...(current || {}),
    rereviewId: current?.rereviewId || operationQualityPostEffectCandidateQualityCalibrationRereviewId(candidate),
    source: "external_connector_post_effect_candidate_quality_calibration_performance",
    calibrationId: candidate.calibrationId,
    candidateType: candidate.candidateType,
    target: candidate.target,
    owner: current?.owner || candidate.owner || candidate.decisionBy || "admin",
    dueDate: current?.dueDate || candidate.dueDate || kstDate(7),
    status: current?.status || "open",
    memo: current?.memo || "",
    followUpActionType: current?.followUpActionType || "watch",
    performanceScore: candidate.performanceScore,
    performanceState: candidate.performanceState,
    decisionType: candidate.decisionType,
    decisionAt: candidate.decisionAt,
    reReviewReason: candidate.reason || candidate.reReviewReason,
    recommendedAction: candidate.recommendedAction || "reopen_external_connector_candidate_quality_calibration_review",
    sourceSnapshot: {
      ...(candidate.sourceSnapshot || {}),
      calibrationId: candidate.calibrationId,
      candidateType: candidate.candidateType,
      decisionType: candidate.decisionType,
      decisionAt: candidate.decisionAt,
      performanceScore: candidate.performanceScore,
      performanceState: candidate.performanceState,
      priority: candidate.priority
    },
    before: candidate.before || current?.before || {},
    after: candidate.after || current?.after || {},
    delta: candidate.delta || current?.delta || {},
    createdAt: current?.createdAt || now,
    createdBy: current?.createdBy || "system",
    updatedAt: now,
    updatedBy: current ? current.updatedBy || "system" : "system",
    completedAt: current?.completedAt || "",
    completedBy: current?.completedBy || "",
    completionResult: current?.completionResult || "",
    linkedCalibrationResult: current?.linkedCalibrationResult || null,
    events: current?.events?.length ? current.events : [{
      eventType: "created",
      eventAt: now,
      eventBy: "system",
      reason: candidate.reason || candidate.reReviewReason || "External connector candidate quality calibration performance requires re-review."
    }]
  });
}

async function upsertOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(performance = {}) {
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview)
    : [];
  const byId = new Map(existingItems.map((item) => [item.rereviewId, item]));
  const touched = [];
  (performance.reReviewCandidates || []).forEach((candidate) => {
    const rereviewId = operationQualityPostEffectCandidateQualityCalibrationRereviewId(candidate);
    const existing = byId.get(rereviewId) || null;
    if (existing && ["completed", "dismissed"].includes(existing.status)) {
      touched.push(existing);
      return;
    }
    const item = buildOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidate(candidate, existing);
    byId.set(item.rereviewId, item);
    touched.push(item);
  });
  await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  return touched;
}

function operationQualityPostEffectCandidateQualityCalibrationRereviewSummary(items = []) {
  return {
    total: items.length,
    open: items.filter((item) => item.status === "open").length,
    inProgress: items.filter((item) => item.status === "in_progress").length,
    completed: items.filter((item) => item.status === "completed").length,
    deferred: items.filter((item) => item.status === "deferred").length,
    dismissed: items.filter((item) => item.status === "dismissed").length,
    overdue: items.filter((item) => item.status !== "completed" && item.dueState === "overdue").length,
    thisWeek: items.filter((item) => item.status !== "completed" && item.dueState === "this_week").length,
    weakActive: items.filter((item) => item.performanceState === "weak_active").length,
    avgPerformanceScore: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.performanceScore || 0), 0) / items.length) : 0
  };
}

function filterOperationQualityPostEffectCandidateQualityCalibrationRereviews(items = [], params = {}) {
  const statusText = String(operationQualityRecommendationAdjustmentParam(params, "status") || operationQualityRecommendationAdjustmentParam(params, "rereviewStatus") || "").trim();
  const status = normalizeSlaPolicyCandidateQualityRereviewStatus(statusText);
  const owner = String(operationQualityRecommendationAdjustmentParam(params, "owner") || operationQualityRecommendationAdjustmentParam(params, "assignee") || operationQualityRecommendationAdjustmentParam(params, "rereviewOwner") || "").trim().toLowerCase();
  const due = String(operationQualityRecommendationAdjustmentParam(params, "due") || operationQualityRecommendationAdjustmentParam(params, "dueState") || operationQualityRecommendationAdjustmentParam(params, "rereviewDue") || "").trim();
  const minScoreText = operationQualityRecommendationAdjustmentParam(params, "minScore") || operationQualityRecommendationAdjustmentParam(params, "rereviewMinScore") || "";
  const maxScoreText = operationQualityRecommendationAdjustmentParam(params, "maxScore") || operationQualityRecommendationAdjustmentParam(params, "rereviewMaxScore") || "";
  const minScore = minScoreText === "" ? null : Number(minScoreText);
  const maxScore = maxScoreText === "" ? null : Number(maxScoreText);
  return items
    .filter((item) => !statusText || item.status === status)
    .filter((item) => !owner || String(item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !due || item.dueState === due)
    .filter((item) => !Number.isFinite(minScore) || Number(item.performanceScore || 0) >= minScore)
    .filter((item) => !Number.isFinite(maxScore) || Number(item.performanceScore || 0) <= maxScore);
}

function operationQualityPostEffectCandidateQualityCalibrationRereviewReport(items = [], params = {}) {
  const normalized = items.map(normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview);
  const filtered = filterOperationQualityPostEffectCandidateQualityCalibrationRereviews(normalized, params);
  const limit = Math.max(1, Math.min(500, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)));
  const filters = {
    status: String(operationQualityRecommendationAdjustmentParam(params, "status") || operationQualityRecommendationAdjustmentParam(params, "rereviewStatus") || "").trim(),
    owner: String(operationQualityRecommendationAdjustmentParam(params, "owner") || operationQualityRecommendationAdjustmentParam(params, "rereviewOwner") || "").trim(),
    due: String(operationQualityRecommendationAdjustmentParam(params, "due") || operationQualityRecommendationAdjustmentParam(params, "dueState") || operationQualityRecommendationAdjustmentParam(params, "rereviewDue") || "").trim(),
    minScore: operationQualityRecommendationAdjustmentParam(params, "minScore") || operationQualityRecommendationAdjustmentParam(params, "rereviewMinScore") || "",
    maxScore: operationQualityRecommendationAdjustmentParam(params, "maxScore") || operationQualityRecommendationAdjustmentParam(params, "rereviewMaxScore") || "",
    limit
  };
  return {
    role: "admin",
    schema: "external_connector_operation_quality_post_effect_candidate_quality_calibration_rereview_queue_v1",
    generatedAt: new Date().toISOString(),
    filters,
    summary: operationQualityPostEffectCandidateQualityCalibrationRereviewSummary(filtered),
    fullSummary: operationQualityPostEffectCandidateQualityCalibrationRereviewSummary(normalized),
    items: filtered
      .sort((a, b) => Number(a.performanceScore || 0) - Number(b.performanceScore || 0) ||
        String(a.dueDate || "9999-99-99").localeCompare(String(b.dueDate || "9999-99-99")) ||
        String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only external connector candidate quality calibration re-review operations queue",
      hiddenFromBusiness: ["auto approval policy", "quality calibration re-review queue", "owners", "due dates", "follow-up actions", "operational memos", "change history", "internal formula"]
    }
  };
}

async function externalConnectorOperationQualityPostEffectCandidateQualityCalibrationRereviewsReport(params = new URLSearchParams()) {
  const performance = await externalConnectorOperationQualityPostEffectCandidateQualityCalibrationPerformanceReport(params);
  await upsertOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(performance);
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
  return {
    ...operationQualityPostEffectCandidateQualityCalibrationRereviewReport(data.items || [], params),
    generatedCandidates: performance.reReviewCandidates || [],
    performanceSummary: performance.summary || {}
  };
}

async function applyOperationQualityPostEffectCandidateQualityCalibrationRereviewCompletion(rereview = {}, payload = {}) {
  if (rereview.status !== "completed") return null;
  const actionType = normalizeSlaPolicyCandidateQualityRereviewAction(rereview.followUpActionType);
  if (!rereview.calibrationId || actionType === "none" || actionType === "watch") return null;
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityPostEffectCandidateQualityCalibration)
    : [];
  const target = items.find((item) => item.calibrationId === rereview.calibrationId);
  if (!target) return null;
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.completedBy || rereview.completedBy || "admin").trim() || "admin";
  let updatedTarget = target;
  if (actionType === "maintain_active") {
    updatedTarget = normalizeOperationQualityPostEffectCandidateQualityCalibration({
      ...target,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "external_connector_quality_rereview_maintained",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: target.status,
          reason: rereview.memo || rereview.reReviewReason
        }),
        ...(target.events || [])
      ]
    });
  } else if (actionType === "deactivate_active") {
    updatedTarget = normalizeOperationQualityPostEffectCandidateQualityCalibration({
      ...target,
      status: "deactivated",
      activeCalibration: null,
      reviewReason: rereview.memo || target.reviewReason,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "external_connector_quality_rereview_deactivated",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: "deactivated",
          reason: rereview.memo || rereview.reReviewReason
        }),
        ...(target.events || [])
      ]
    });
  } else if (actionType === "propose_modified_calibration") {
    const suggested = target.suggestedCalibration || {};
    const active = target.activeCalibration || suggested;
    const nextSuggested = {
      ...suggested,
      direction: active?.direction || suggested.direction || "neutral",
      priorityAfter: active?.priorityAfter || suggested.priorityAfter || suggested.priorityBefore || "medium",
      reason: rereview.memo || `Re-review proposes modifying active external connector quality calibration after performance score ${rereview.performanceScore}.`
    };
    const simulationCandidate = {
      priority: nextSuggested.priorityBefore,
      recommendation: target.simulation?.recommendationBefore || "",
      expectedImpact: target.simulation?.expectedImpactBefore || {}
    };
    updatedTarget = normalizeOperationQualityPostEffectCandidateQualityCalibration({
      ...target,
      status: "proposed",
      activeCalibration: null,
      suggestedCalibration: nextSuggested,
      simulation: operationQualityPostEffectCandidateQualityLearningSimulation(simulationCandidate, nextSuggested, null),
      reviewReason: rereview.memo || target.reviewReason,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "external_connector_quality_rereview_modify_proposed",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: "proposed",
          reason: rereview.memo || rereview.reReviewReason,
          overridePriorityAfter: active?.priorityAfter || ""
        }),
        ...(target.events || [])
      ]
    });
  }
  const updatedItems = items.map((item) => item.calibrationId === rereview.calibrationId ? updatedTarget : item);
  await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  await appendExternalConnectorOperationQualityPostEffectCandidateQualityCalibrationLog({
    calibrationId: target.calibrationId,
    eventType: `rereview_${actionType}`,
    eventAt: now,
    eventBy: actor,
    previousStatus: target.status,
    nextStatus: updatedTarget.status,
    reason: rereview.memo || rereview.reReviewReason,
    overridePriorityAfter: updatedTarget.activeCalibration?.priorityAfter || updatedTarget.suggestedCalibration?.priorityAfter || ""
  });
  return {
    ...updatedTarget,
    linkSummary: {
      calibrationId: target.calibrationId,
      actionType,
      previousStatus: target.status,
      nextStatus: updatedTarget.status,
      previousActive: Boolean(target.activeCalibration),
      nextActive: Boolean(updatedTarget.activeCalibration),
      changedAt: now,
      changedBy: actor
    }
  };
}

async function upsertOperationQualityPostEffectCandidateQualityCalibrationRereview(payload = {}) {
  const rereviewId = String(payload.rereviewId || payload.id || "").trim();
  if (!rereviewId) {
    const error = new Error("External connector candidate quality calibration re-review id is required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview)
    : [];
  const existing = items.find((item) => item.rereviewId === rereviewId);
  if (!existing) {
    const error = new Error("External connector candidate quality calibration re-review item not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.owner || "admin").trim() || "admin";
  const nextStatus = payload.status ? normalizeSlaPolicyCandidateQualityRereviewStatus(payload.status) : existing.status;
  const updated = normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview({
    ...existing,
    owner: payload.owner !== undefined ? payload.owner : existing.owner,
    dueDate: payload.dueDate !== undefined ? payload.dueDate : existing.dueDate,
    status: nextStatus,
    memo: payload.memo !== undefined ? payload.memo : existing.memo,
    followUpActionType: payload.followUpActionType !== undefined ? payload.followUpActionType : existing.followUpActionType,
    updatedAt: now,
    updatedBy: actor,
    completedAt: nextStatus === "completed" ? existing.completedAt || now : existing.completedAt,
    completedBy: nextStatus === "completed" ? String(payload.completedBy || actor).trim() : existing.completedBy,
    completionResult: nextStatus === "completed" ? normalizeSlaPolicyCandidateQualityRereviewAction(payload.followUpActionType || existing.followUpActionType) : existing.completionResult,
    events: [
      {
        eventType: nextStatus === "completed" ? "completed" : "updated",
        eventAt: now,
        eventBy: actor,
        previousStatus: existing.status,
        nextStatus,
        reason: String(payload.memo || payload.reason || "").trim(),
        followUpActionType: normalizeSlaPolicyCandidateQualityRereviewAction(payload.followUpActionType || existing.followUpActionType)
      },
      ...(existing.events || [])
    ]
  });
  const linkedCalibration = await applyOperationQualityPostEffectCandidateQualityCalibrationRereviewCompletion(updated, payload);
  const finalUpdated = normalizeOperationQualityPostEffectCandidateQualityCalibrationRereview({
    ...updated,
    linkedCalibrationResult: linkedCalibration?.linkSummary || updated.linkedCalibrationResult || null
  });
  const updatedItems = items.map((item) => item.rereviewId === rereviewId ? finalUpdated : item);
  const saved = await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  const rereviews = operationQualityPostEffectCandidateQualityCalibrationRereviewReport(saved.items || [], {});
  return {
    ok: true,
    item: rereviews.items.find((item) => item.rereviewId === finalUpdated.rereviewId) || finalUpdated,
    linkedCalibration,
    rereviews,
    reportBoundaries: {
      source: "admin-only external connector candidate quality calibration re-review update",
      hiddenFromBusiness: ["auto approval policy", "re-review queue", "owners", "due dates", "memos", "follow-up actions", "active calibration linkage", "internal formula"]
    }
  };
}

function operationQualityAutoApprovalPolicyCandidateFromPostEffect(effectItem = {}, suggestion = {}) {
  const suggestionType = String(suggestion.type || "").trim();
  if (!suggestionType || suggestionType === "wait_for_more_data") return null;
  const scope = effectItem.scope || {};
  const rootMetric = scope.type === "rootMetric" ? String(scope.key || "").trim() : "";
  const assignee = scope.type === "assignee" ? String(scope.key || "").trim() : "";
  let candidateType = "";
  if (suggestionType === "rollback_policy_adjustment") candidateType = "rollback_policy_adjustment";
  else if (suggestionType === "additional_tightening") candidateType = "additional_tightening_policy";
  else if (suggestionType === "maintain_policy") candidateType = "maintain_or_relax_policy";
  if (!candidateType) return null;
  const target = [
    effectItem.target || scope.label || rootMetric || assignee || "external connector policy",
    suggestionType.replace(/_/g, " ")
  ].filter(Boolean).join(" / ");
  const candidate = {
    policyAdjustmentId: hashId("xoqpol", [
      "post_effect",
      effectItem.policyAdjustmentId || "",
      suggestionType,
      rootMetric,
      assignee
    ].join("|")),
    type: candidateType,
    candidateType,
    target,
    rootMetric,
    assignee,
    priority: suggestion.priority || (candidateType === "rollback_policy_adjustment" ? "high" : "medium"),
    metrics: {
      beforeSuccessRate: effectItem.before?.successRate || 0,
      afterSuccessRate: effectItem.after?.successRate || 0,
      beforeFalsePositiveRate: effectItem.before?.falsePositiveRate || 0,
      afterFalsePositiveRate: effectItem.after?.falsePositiveRate || 0,
      beforeRollbackRate: effectItem.before?.rollbackRate || 0,
      afterRollbackRate: effectItem.after?.rollbackRate || 0,
      beforeRecurrenceRate: effectItem.before?.recurrenceRate || 0,
      afterRecurrenceRate: effectItem.after?.recurrenceRate || 0,
      falsePositiveRate: effectItem.after?.falsePositiveRate || 0,
      rollbackRate: effectItem.after?.rollbackRate || 0,
      recurrenceRate: effectItem.after?.recurrenceRate || 0,
      manualReviewTransitionRate: effectItem.after?.manualReviewTransitionRate || 0,
      effectScore: effectItem.effectScore || 0
    },
    basis: suggestion.reason || `Post-effect outcome ${effectItem.outcome || "unknown"} generated ${suggestionType}.`,
    recommendation: suggestion.recommendedAction || "",
    rollbackToPolicySnapshot: effectItem.sourceBeforePolicy || {},
    sourcePolicyAdjustmentId: effectItem.policyAdjustmentId || "",
    sourceSuggestionType: suggestionType,
    sourceEffectOutcome: effectItem.outcome || "",
    sourceEffectScore: effectItem.effectScore || 0,
    sourceContext: {
      source: "external_connector_auto_approval_policy_post_effect",
      policyAdjustmentId: effectItem.policyAdjustmentId || "",
      suggestionType,
      outcome: effectItem.outcome || "",
      effectScore: effectItem.effectScore || 0,
      scope,
      before: effectItem.before || {},
      after: effectItem.after || {},
      delta: effectItem.delta || {},
      beforePolicy: effectItem.sourceBeforePolicy || {},
      afterPolicy: effectItem.sourceAfterPolicy || {}
    }
  };
  return candidate;
}

function operationQualityAutoApprovalPolicyCandidatesFromPostEffects(postEffectReport = {}, qualityReport = {}, workflowItems = []) {
  return (postEffectReport.items || [])
    .flatMap((effectItem) => (effectItem.suggestions || [])
      .map((suggestion) => operationQualityAutoApprovalPolicyCandidateFromPostEffect(effectItem, suggestion))
      .filter(Boolean))
    .map((candidate) => applyOperationQualityPostEffectCandidateQualityLearning(candidate, qualityReport, workflowItems));
}

async function attachOperationQualityAutoApprovalPolicyPostEffectCandidates(postEffectReport = {}, activePolicy = EXTERNAL_CONNECTOR_OPERATION_QUALITY_RECOMMENDATION_AUTO_APPROVAL_POLICY, qualityReport = {}) {
  const draftCandidates = operationQualityAutoApprovalPolicyCandidatesFromPostEffects(postEffectReport, qualityReport, []);
  const qualityCalibrationItems = await upsertOperationQualityPostEffectCandidateQualityCalibrationProposals(draftCandidates);
  const qualityCalibrationWorkflow = operationQualityPostEffectCandidateQualityCalibrationWorkflowReport(qualityCalibrationItems, {});
  const candidates = operationQualityAutoApprovalPolicyCandidatesFromPostEffects(postEffectReport, qualityReport, qualityCalibrationItems);
  const proposals = candidates.length
    ? await upsertOperationQualityAutoApprovalPolicyAdjustmentProposals(candidates, activePolicy)
    : [];
  const proposalsBySource = proposals.reduce((map, proposal) => {
    const sourceId = proposal.sourcePolicyAdjustmentId || proposal.sourceContext?.policyAdjustmentId || "";
    if (!sourceId) return map;
    if (!map.has(sourceId)) map.set(sourceId, []);
    map.get(sourceId).push(proposal);
    return map;
  }, new Map());
  return {
    ...postEffectReport,
    candidateQualityLearning: {
      summary: qualityReport.summary || {},
      byType: qualityReport.byType || []
    },
    candidateQualityCalibrationWorkflow: qualityCalibrationWorkflow,
    generatedPolicyAdjustmentCandidates: candidates,
    generatedPolicyAdjustmentProposals: proposals,
    items: (postEffectReport.items || []).map((item) => ({
      ...item,
      generatedPolicyAdjustmentProposals: proposalsBySource.get(item.policyAdjustmentId) || []
    }))
  };
}

async function externalConnectorOperationQualityAutoApprovalPolicyEffectsReport(params = new URLSearchParams()) {
  const [policyAdjustmentData, adjustmentData, historyData, logData] = await Promise.all([
    readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments(),
    readExternalConnectorOperationQualityRecommendationAdjustments(),
    readExternalConnectorOperationQualityActionReassessmentHistory(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalLogs()
  ]);
  const historyItems = (historyData.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const logs = (logData.items || []).map(normalizeOperationQualityRecommendationAutoApprovalLog);
  const recommendationItems = (adjustmentData.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const performanceItems = recommendationItems
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible)
    .map((item) => operationQualityRecommendationAutoApprovalPerformanceItem(item, historyItems, logs));
  const activePolicy = activeOperationQualityAutoApprovalPolicy(policyAdjustmentData.items || []);
  const basePostEffectReport = operationQualityAutoApprovalPolicyPostEffectReport(policyAdjustmentData.items || [], performanceItems, recommendationItems, params);
  const candidateQualityBasis = operationQualityPostEffectCandidateQualityReport(policyAdjustmentData.items || [], basePostEffectReport.items || [], new URLSearchParams());
  const report = await attachOperationQualityAutoApprovalPolicyPostEffectCandidates(
    basePostEffectReport,
    activePolicy,
    candidateQualityBasis
  );
  const latestPolicyAdjustmentData = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const candidateQuality = operationQualityPostEffectCandidateQualityReport(latestPolicyAdjustmentData.items || [], report.items || [], params);
  const candidateQualityCalibrationPerformance = operationQualityPostEffectCandidateQualityCalibrationPerformanceReport(
    report.candidateQualityCalibrationWorkflow?.items || [],
    candidateQuality,
    params
  );
  return {
    role: "admin",
    ...report,
    candidateQuality,
    candidateQualityCalibrationPerformance
  };
}

async function externalConnectorOperationQualityAutoApprovalPolicyAdjustmentsReport(params = new URLSearchParams()) {
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const allItems = (data.items || [])
    .map(normalizeOperationQualityAutoApprovalPolicyAdjustment)
    .sort((a, b) => {
      const statusRank = { proposed: 0, approved: 1, rejected: 2 };
      return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9)
        || String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
    });
  const filtered = filterOperationQualityAutoApprovalPolicyAdjustments(allItems, params);
  const limit = Math.max(1, Math.min(300, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)));
  return {
    role: "admin",
    schema: "external_connector_operation_quality_auto_approval_policy_adjustments_v1",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(operationQualityRecommendationAdjustmentParam(params, "status") || "").trim(),
      candidateType: String(operationQualityRecommendationAdjustmentParam(params, "candidateType") || "").trim(),
      rootMetric: String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim(),
      assignee: String(operationQualityRecommendationAdjustmentParam(params, "assignee") || "").trim(),
      priority: String(operationQualityRecommendationAdjustmentParam(params, "priority") || "").trim(),
      limit
    },
    summary: operationQualityAutoApprovalPolicyAdjustmentSummary(filtered),
    fullSummary: operationQualityAutoApprovalPolicyAdjustmentSummary(allItems),
    activePolicy: activeOperationQualityAutoApprovalPolicy(allItems),
    items: filtered.slice(0, limit),
    reportBoundaries: {
      source: "admin-only external connector operation quality auto approval policy workflow",
      hiddenFromBusiness: ["auto approval policy", "policy adjustment workflow", "policy patch", "approval history", "internal formula"]
    }
  };
}

async function reviewExternalConnectorOperationQualityAutoApprovalPolicyAdjustment(policyAdjustmentId = "", decision = "", payload = {}) {
  const normalizedDecision = decision === "approved" ? "approve" : decision === "rejected" ? "reject" : decision;
  if (!["approve", "reject"].includes(normalizedDecision)) {
    const error = new Error("Unsupported auto approval policy adjustment decision.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const items = (data.items || []).map(normalizeOperationQualityAutoApprovalPolicyAdjustment);
  const index = items.findIndex((item) => item.policyAdjustmentId === policyAdjustmentId);
  if (index < 0) return null;
  const target = items[index];
  if (target.status !== "proposed") {
    const error = new Error("Only proposed auto approval policy adjustments can be reviewed.");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.reviewedBy || payload.approvedBy || payload.rejectedBy || payload.updatedBy || "admin").trim() || "admin";
  const reason = String(payload.reason || payload.reviewReason || payload.rejectReason || "").trim();
  const historyEvent = {
    decision: normalizedDecision === "approve" ? "approved" : "rejected",
    beforeStatus: target.status,
    decidedBy: actor,
    decidedAt: now,
    reason: reason || (normalizedDecision === "approve" ? "Approved for active policy." : "Rejected after admin review.")
  };
  const updated = normalizeOperationQualityAutoApprovalPolicyAdjustment(normalizedDecision === "approve"
    ? {
        ...target,
        status: "approved",
        active: true,
        approvedAt: now,
        approvedBy: actor,
        reviewReason: historyEvent.reason,
        updatedAt: now,
        updatedBy: actor,
        decisionHistory: [...(target.decisionHistory || []), historyEvent]
      }
    : {
        ...target,
        status: "rejected",
        active: false,
        rejectedAt: now,
        rejectedBy: actor,
        rejectReason: historyEvent.reason,
        updatedAt: now,
        updatedBy: actor,
        decisionHistory: [...(target.decisionHistory || []), historyEvent]
      });
  items[index] = updated;
  const saved = await writeExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments({
    ...data,
    items: items.sort((a, b) => {
      const statusRank = { proposed: 0, approved: 1, rejected: 2 };
      return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9)
        || String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
    })
  });
  return {
    role: "admin",
    schema: "external_connector_operation_quality_auto_approval_policy_adjustment_review_v1",
    generatedAt: now,
    decision: normalizedDecision,
    item: updated,
    summary: operationQualityAutoApprovalPolicyAdjustmentSummary(saved.items || []),
    activePolicy: activeOperationQualityAutoApprovalPolicy(saved.items || []),
    reportBoundaries: {
      source: "admin-only external connector operation quality auto approval policy decision",
      hiddenFromBusiness: ["auto approval policy decision", "policy patch", "approval history", "internal formula"]
    }
  };
}

function operationQualityRecommendationAutoApprovalPolicyAdjustmentCandidates(items = [], aggregates = {}) {
  const candidates = [];
  const riskyMetrics = (aggregates.byRootMetric || []).filter((row) => row.evaluated >= 1 && (row.falsePositiveRate >= 40 || row.recurrenceRate >= 50 || row.rollbackRate >= 30));
  riskyMetrics.slice(0, 6).forEach((row) => {
    candidates.push({
      type: "tighten_root_metric_policy",
      priority: row.falsePositiveRate >= 50 || row.rollbackRate >= 40 ? "high" : "medium",
      target: row.label,
      rootMetric: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `False positive ${row.falsePositiveRate}%, recurrence ${row.recurrenceRate}%, rollback ${row.rollbackRate}% across ${row.evaluated} evaluated auto approvals.`,
      recommendation: "Keep this root metric in manual review or raise sample/effect thresholds before auto approval."
    });
  });
  const riskyAssignees = (aggregates.byAssignee || []).filter((row) => row.evaluated >= 1 && (row.falsePositiveRate >= 40 || row.rollbackRate >= 30));
  riskyAssignees.slice(0, 4).forEach((row) => {
    candidates.push({
      type: "tighten_assignee_scope_policy",
      priority: row.falsePositiveRate >= 50 || row.rollbackRate >= 40 ? "high" : "medium",
      target: row.label,
      assignee: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `Assignee scope shows false positive ${row.falsePositiveRate}% and rollback ${row.rollbackRate}%.`,
      recommendation: "Require manual review for this assignee scope until post-assessment quality improves."
    });
  });
  const strongMetrics = (aggregates.byRootMetric || []).filter((row) => row.evaluated >= 3 && row.successRate >= 80 && row.falsePositiveRate === 0 && row.rollbackRate === 0);
  strongMetrics.slice(0, 4).forEach((row) => {
    candidates.push({
      type: "maintain_or_relax_root_metric_policy",
      priority: "low",
      target: row.label,
      rootMetric: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `Success ${row.successRate}% with no false positives or rollbacks across ${row.evaluated} evaluated auto approvals.`,
      recommendation: "Keep low-risk auto approval active for this metric; broad monthly/global scopes should still remain manual."
    });
  });
  const pendingRate = items.length ? Math.round((items.filter((item) => item.outcome?.outcome === "pending").length / items.length) * 100) : 0;
  if (pendingRate >= 60 && items.length >= 3) {
    candidates.push({
      type: "increase_reassessment_capture",
      priority: "medium",
      target: "pending_external_connector_auto_approval",
      rootMetric: "",
      metrics: {
        total: items.length,
        evaluated: items.filter((item) => item.outcome?.evaluatedCount > 0).length,
        successRate: slaAutoApprovalPerformanceSummary(items).successRate,
        falsePositiveRate: slaAutoApprovalPerformanceSummary(items).falsePositiveRate,
        rollbackRate: slaAutoApprovalPerformanceSummary(items).rollbackRate,
        recurrenceRate: slaAutoApprovalPerformanceSummary(items).recurrenceRate,
        pendingRate
      },
      basis: `${pendingRate}% of external connector auto approvals do not yet have linked reassessment history.`,
      recommendation: "Capture completion/reassessment evidence before widening auto approval coverage."
    });
  }
  return candidates;
}

async function externalConnectorOperationQualityRecommendationAutoApprovalPerformanceReport(params = new URLSearchParams()) {
  const [adjustmentData, historyData, logData, policyAdjustmentData] = await Promise.all([
    readExternalConnectorOperationQualityRecommendationAdjustments(),
    readExternalConnectorOperationQualityActionReassessmentHistory(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalLogs(),
    readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments()
  ]);
  const activePolicy = activeOperationQualityAutoApprovalPolicy(policyAdjustmentData.items || []);
  const historyItems = (historyData.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const logs = (logData.items || []).map(normalizeOperationQualityRecommendationAutoApprovalLog);
  const recommendationAdjustments = (adjustmentData.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const autoAdjustments = recommendationAdjustments
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible);
  const allItems = autoAdjustments
    .map((item) => operationQualityRecommendationAutoApprovalPerformanceItem(item, historyItems, logs))
    .sort((a, b) => String(b.approvedAt || "").localeCompare(String(a.approvedAt || "")));
  const filtered = filterOperationQualityRecommendationAutoApprovalPerformanceItems(allItems, params);
  const aggregates = {
    byMonth: slaAutoApprovalPerformanceGroups(filtered, (item) => item.approvalMonth || "unknown"),
    byRootMetric: slaAutoApprovalPerformanceGroups(filtered, (item) => item.rootMetric || "unknown", (key, item) => item.rootMetricLabel || key),
    byAssignee: slaAutoApprovalPerformanceGroups(filtered, (item) => item.assignee || "unassigned")
  };
  const limit = Math.max(1, Math.min(500, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)));
  const policyAdjustmentCandidates = operationQualityRecommendationAutoApprovalPolicyAdjustmentCandidates(filtered, aggregates);
  const policyAdjustmentProposals = await upsertOperationQualityAutoApprovalPolicyAdjustmentProposals(policyAdjustmentCandidates, activePolicy);
  let policyAdjustmentWorkflow = await externalConnectorOperationQualityAutoApprovalPolicyAdjustmentsReport(params);
  let policyAdjustmentPostEffect = operationQualityAutoApprovalPolicyPostEffectReport(
    policyAdjustmentData.items || [],
    allItems,
    recommendationAdjustments,
    params
  );
  policyAdjustmentPostEffect = await attachOperationQualityAutoApprovalPolicyPostEffectCandidates(
    policyAdjustmentPostEffect,
    policyAdjustmentWorkflow.activePolicy || activePolicy,
    operationQualityPostEffectCandidateQualityReport(policyAdjustmentData.items || [], policyAdjustmentPostEffect.items || [], new URLSearchParams())
  );
  policyAdjustmentWorkflow = await externalConnectorOperationQualityAutoApprovalPolicyAdjustmentsReport(params);
  const latestPolicyAdjustmentData = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const policyAdjustmentCandidateQuality = operationQualityPostEffectCandidateQualityReport(
    latestPolicyAdjustmentData.items || [],
    policyAdjustmentPostEffect.items || [],
    params
  );
  const policyAdjustmentQualityCalibrationPerformance = operationQualityPostEffectCandidateQualityCalibrationPerformanceReport(
    policyAdjustmentPostEffect.candidateQualityCalibrationWorkflow?.items || [],
    policyAdjustmentCandidateQuality,
    params
  );
  await upsertOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(policyAdjustmentQualityCalibrationPerformance);
  const policyAdjustmentQualityCalibrationRereviewData = await readExternalConnectorOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
  const policyAdjustmentQualityCalibrationRereviews = operationQualityPostEffectCandidateQualityCalibrationRereviewReport(
    policyAdjustmentQualityCalibrationRereviewData.items || [],
    params
  );
  return {
    role: "admin",
    schema: "external_connector_operation_quality_recommendation_auto_approval_performance_v1",
    generatedAt: new Date().toISOString(),
    filters: {
      month: String(operationQualityRecommendationAdjustmentParam(params, "month") || "").trim(),
      assignee: String(operationQualityRecommendationAdjustmentParam(params, "assignee") || "").trim(),
      rootMetric: String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim(),
      outcome: String(operationQualityRecommendationAdjustmentParam(params, "outcome") || "").trim(),
      limit
    },
    summary: slaAutoApprovalPerformanceSummary(filtered),
    fullSummary: slaAutoApprovalPerformanceSummary(allItems),
    aggregates,
    policyAdjustmentCandidates,
    policyAdjustmentProposals,
    policyAdjustmentWorkflow,
    policyAdjustmentPostEffect,
    policyAdjustmentCandidateQuality,
    policyAdjustmentQualityCalibrationPerformance,
    policyAdjustmentQualityCalibrationRereviews,
    activePolicy: policyAdjustmentWorkflow.activePolicy || activePolicy,
    items: filtered.slice(0, limit),
    autoApprovalLogs: logs.slice(0, 80),
    reportBoundaries: {
      source: "admin-only external connector operation quality auto approval performance tracking",
      hiddenFromBusiness: ["auto approval performance", "rollback rate", "false positive rate", "operation quality metrics", "policy adjustment candidates", "internal formula"]
    }
  };
}

async function decideExternalConnectorOperationQualityRecommendationAdjustment(adjustmentId = "", decision = "", payload = {}) {
  const data = await readExternalConnectorOperationQualityRecommendationAdjustments();
  const items = (data.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const index = items.findIndex((item) => item.adjustmentId === adjustmentId);
  if (index < 0) return null;
  const target = items[index];
  const now = new Date().toISOString();
  const actor = String(payload.approvedBy || payload.rejectedBy || payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const historyEvent = {
    decision,
    beforeStatus: target.status,
    decidedBy: actor,
    decidedAt: now,
    reason: String(payload.reason || payload.reviewReason || payload.rejectReason || "").trim()
  };
  let updated;
  if (decision === "approve") {
    if (target.status !== "proposed") {
      const error = new Error("Only proposed recommendation adjustments can be approved.");
      error.statusCode = 400;
      throw error;
    }
    updated = normalizeOperationQualityRecommendationAdjustment({
      ...target,
      status: "approved",
      active: true,
      approvalMode: "manual",
      rollbackAvailable: false,
      approvedPriority: String(payload.approvedPriority || target.proposedPriority || target.originalPriority).trim(),
      approvedRecommendedAction: String(payload.approvedRecommendedAction || target.proposedRecommendedAction || target.beforeRecommendedAction || "").trim(),
      approvedBy: actor,
      approvedAt: now,
      reviewReason: historyEvent.reason || "Approved after admin review.",
      updatedAt: now,
      decisionHistory: [...(target.decisionHistory || []), historyEvent]
    });
  } else if (decision === "reject") {
    if (target.status !== "proposed") {
      const error = new Error("Only proposed recommendation adjustments can be rejected.");
      error.statusCode = 400;
      throw error;
    }
    updated = normalizeOperationQualityRecommendationAdjustment({
      ...target,
      status: "rejected",
      active: false,
      approvalMode: "manual",
      rollbackAvailable: false,
      rejectedBy: actor,
      rejectedAt: now,
      rejectReason: historyEvent.reason || "Rejected after admin review.",
      updatedAt: now,
      decisionHistory: [...(target.decisionHistory || []), historyEvent]
    });
  } else {
    const error = new Error("Unsupported recommendation adjustment decision.");
    error.statusCode = 400;
    throw error;
  }
  items[index] = updated;
  const saved = await writeExternalConnectorOperationQualityRecommendationAdjustments({
    ...data,
    items: items.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    role: "admin",
    schema: "external_connector_operation_quality_recommendation_adjustment_decision_v1",
    generatedAt: now,
    decision,
    item: updated,
    summary: operationQualityRecommendationAdjustmentSummary(saved.items || []),
    reportBoundaries: {
      source: "admin-only external connector recommendation adjustment approval decision",
      hiddenFromBusiness: ["recommendation adjustment approval", "approval history", "effect score", "recurrence rate", "internal formula"]
    }
  };
}

async function rollbackExternalConnectorOperationQualityRecommendationAutoApproval(adjustmentId = "", payload = {}) {
  const data = await readExternalConnectorOperationQualityRecommendationAdjustments();
  const items = (data.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const index = items.findIndex((item) => item.adjustmentId === adjustmentId);
  if (index < 0) return null;
  const target = items[index];
  if (target.status !== "approved" || target.approvalMode !== "auto" || !target.rollbackAvailable) {
    const error = new Error("Only rollback-available auto-approved recommendation adjustments can be rolled back.");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.rolledBackBy || payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reason = String(payload.rollbackReason || payload.reason || "").trim();
  const historyEvent = {
    decision: "rollback_auto_approval",
    beforeStatus: target.status,
    decidedBy: actor,
    decidedAt: now,
    reason: reason || "Auto approval rolled back for manual review."
  };
  const rolledBack = normalizeOperationQualityRecommendationAdjustment({
    ...target,
    status: "proposed",
    active: false,
    approvalMode: "none",
    approvedPriority: "",
    approvedRecommendedAction: "",
    approvedBy: "",
    approvedAt: "",
    rollbackAvailable: false,
    rolledBackAt: now,
    rolledBackBy: actor,
    rollbackReason: reason || "Auto approval rolled back for manual review.",
    reviewReason: reason ? `Auto approval rolled back: ${reason}` : "Auto approval rolled back for manual review.",
    updatedAt: now,
    decisionHistory: [...(target.decisionHistory || []), historyEvent]
  });
  items[index] = rolledBack;
  const saved = await writeExternalConnectorOperationQualityRecommendationAdjustments({
    ...data,
    items: items.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  await appendOperationQualityRecommendationAutoApprovalLog({
    adjustmentId,
    candidateActionId: target.candidateActionId,
    connectorId: target.connectorId,
    sourceMonth: target.sourceMonth,
    rootMetric: target.rootMetric,
    eventType: "rollback",
    eventAt: now,
    eventBy: actor,
    previousStatus: "approved",
    nextStatus: "proposed",
    rollbackAvailable: false,
    rolledBack: true,
    policyDecision: target.autoApprovalPolicy || {},
    reason: rolledBack.reviewReason
  });
  return {
    role: "admin",
    schema: "external_connector_operation_quality_recommendation_adjustment_rollback_v1",
    generatedAt: now,
    item: rolledBack,
    summary: operationQualityRecommendationAdjustmentSummary(saved.items || []),
    reportBoundaries: {
      source: "admin-only external connector recommendation adjustment auto-approval rollback",
      hiddenFromBusiness: ["auto approval rollback", "approval history", "effect score", "recurrence rate", "internal formula"]
    }
  };
}

