async function externalConnectorOperationQualityActionReassessment(params = new URLSearchParams()) {
  const [quality, saved] = await Promise.all([
    externalConnectorOperationAlertQuality(params),
    readExternalConnectorOperationQualityActions()
  ]);
  const followUpBySourceId = new Map();
  for (const item of saved.items || []) {
    if (item.sourceType !== "external_connector_operation_quality_follow_up" || !item.sourceActionId) continue;
    if (!followUpBySourceId.has(item.sourceActionId)) followUpBySourceId.set(item.sourceActionId, []);
    followUpBySourceId.get(item.sourceActionId).push(item.actionId);
  }
  const completed = (saved.items || [])
    .filter((item) => item.sourceType !== "external_connector_operation_quality_follow_up")
    .filter((item) => normalizeOperationQualityActionStatus(item.status) === "done" && item.completionQualitySnapshot)
    .filter((item) => operationQualityActionMatchesFilters(item, quality.filters || {}));
  const allItems = completed.map((item) => operationQualityActionReassessmentItem(item, quality, followUpBySourceId.get(item.actionId) || []));
  const filters = normalizeOperationQualityActionReassessmentFilters(params, quality.filters || {});
  const filtered = filterOperationQualityActionReassessmentItems(allItems, filters)
    .sort((a, b) => Number(b.followUpNeeded || 0) - Number(a.followUpNeeded || 0)
      || Number(a.effectScore || 0) - Number(b.effectScore || 0)
      || String(b.completedAt || "").localeCompare(String(a.completedAt || "")));
  const persistValue = params.get("persist");
  const shouldPersist = persistValue === null || String(persistValue).trim().toLowerCase() !== "false";
  const historyWrite = shouldPersist
    ? await upsertExternalConnectorOperationQualityActionReassessmentHistoryItems(allItems, { recordedBy: "system" })
    : null;
  return {
    role: "admin",
    schema: "external_connector_operation_quality_action_reassessment_v1",
    generatedAt: new Date().toISOString(),
    filters,
    summary: operationQualityActionReassessmentSummary(filtered),
    fullSummary: operationQualityActionReassessmentSummary(allItems),
    historyWrite: historyWrite?.externalConnectorOperationQualityActionReassessmentHistory || null,
    sourceQuality: {
      summary: quality.summary,
      criteria: quality.criteria
    },
    items: filtered.slice(0, filters.limit),
    reportBoundaries: {
      source: "admin-only external connector operation quality action post-completion reassessment",
      hiddenFromBusiness: ["operation warning", "follow-up queue", "quality metrics", "internal connector logs", "quota state", "warning grade", "improvement action", "post-completion reassessment"]
    }
  };
}

async function createExternalConnectorOperationQualityActionFollowUp(actionId = "", payload = {}) {
  const sourceFilters = payload.sourceQualityFilters || {};
  const params = new URLSearchParams();
  if (sourceFilters.month) params.set("month", sourceFilters.month);
  if (sourceFilters.connectorId) params.set("connectorId", sourceFilters.connectorId);
  const report = await externalConnectorOperationQualityActionReassessment(params);
  const reassessment = (report.items || []).find((item) => item.actionId === actionId);
  if (!reassessment) return null;
  if (!reassessment.followUpNeeded) {
    const error = new Error("This completed external connector operation quality action does not require a follow-up.");
    error.statusCode = 400;
    throw error;
  }
  const saved = await readExternalConnectorOperationQualityActions();
  const items = saved.items || [];
  const existing = items.find((item) => (
    item.sourceType === "external_connector_operation_quality_follow_up"
    && item.sourceActionId === actionId
    && normalizeOperationQualityActionStatus(item.status) !== "dismissed"
  ));
  if (existing) {
    const historyUpdate = await markExternalConnectorOperationQualityActionReassessmentHistoryFollowUp(
      reassessment,
      existing,
      payload.updatedBy || payload.createdBy || "admin"
    );
    return {
      item: existing,
      reassessment: {
        ...reassessment,
        followUpCreated: true,
        followUpActionIds: [...new Set([...(reassessment.followUpActionIds || []), existing.actionId].filter(Boolean))]
      },
      created: false,
      externalConnectorOperationQualityActionReassessmentHistory: historyUpdate.externalConnectorOperationQualityActionReassessmentHistory,
      counts: {
        externalConnectorOperationQualityActions: items.length
      }
    };
  }
  const now = new Date().toISOString();
  const riskLevel = reassessment.outcome === "worse" || reassessment.recurrence ? "danger" : "warning";
  const action = {
    actionId: hashId("xoqfu", [actionId, reassessment.rootMetric, reassessment.sourceMonth, "followup"].join("|")),
    status: normalizeOperationQualityActionStatus(payload.status || "saved") === "candidate" ? "saved" : normalizeOperationQualityActionStatus(payload.status || "saved"),
    sourceType: "external_connector_operation_quality_follow_up",
    sourceActionId: actionId,
    sourceReassessmentId: hashId("xoqrea", [actionId, reassessment.evaluatedAt, reassessment.effectScore].join("|")),
    sourceMonth: reassessment.sourceMonth,
    connectorId: reassessment.connectorId,
    scopeType: reassessment.scopeType,
    scopeKey: reassessment.scopeKey,
    scopeLabel: reassessment.scopeLabel,
    title: `후속 조치 · ${reassessment.title || reassessment.rootMetricLabel || "운영 품질"}`,
    description: reassessment.followUpReason || "",
    rootMetric: reassessment.rootMetric,
    rootMetricLabel: reassessment.rootMetricLabel,
    rootMetricValue: reassessment.currentValue,
    riskLevel,
    riskLabel: operationAlertQualityGradeLabel(riskLevel),
    priority: operationQualityActionPriority(riskLevel),
    recommendedAction: String(payload.recommendedAction || payload.recommendation || reassessment.recommendedFollowUpAction || "").trim(),
    assignee: String(payload.assignee || reassessment.assignee || "").trim(),
    dueDate: String(payload.dueDate || operationQualityActionDueDate(riskLevel)).trim(),
    memo: String(payload.memo || reassessment.followUpReason || "").trim(),
    sourceSnapshot: {
      ...(reassessment.currentQualitySnapshot?.metrics || {}),
      effectScore: reassessment.effectScore,
      recurrence: reassessment.recurrence ? 1 : 0,
      followUpNeeded: reassessment.followUpNeeded ? 1 : 0
    },
    sourceQualityFilters: report.filters || {},
    reassessmentSummary: {
      outcome: reassessment.outcome,
      effectScore: reassessment.effectScore,
      recurrence: reassessment.recurrence,
      followUpNeeded: reassessment.followUpNeeded,
      baselineValue: reassessment.baselineValue,
      currentValue: reassessment.currentValue,
      metricDelta: reassessment.metricDelta
    },
    generatedAt: now,
    savedAt: now,
    updatedAt: now,
    updatedBy: String(payload.updatedBy || payload.createdBy || "admin").trim()
  };
  items.push(action);
  const next = await writeExternalConnectorOperationQualityActions({
    ...saved,
    items: items.sort((a, b) => String(b.updatedAt || b.generatedAt || "").localeCompare(String(a.updatedAt || a.generatedAt || "")))
  });
  const historyUpdate = await markExternalConnectorOperationQualityActionReassessmentHistoryFollowUp(
    reassessment,
    action,
    payload.updatedBy || payload.createdBy || "admin"
  );
  return {
    item: action,
    reassessment: {
      ...reassessment,
      followUpCreated: true,
      followUpActionIds: [action.actionId]
    },
    created: true,
    externalConnectorOperationQualityActionReassessmentHistory: historyUpdate.externalConnectorOperationQualityActionReassessmentHistory,
    counts: {
      externalConnectorOperationQualityActions: next.items.length
    }
  };
}

function attachOperationAlertLogs(items = [], logs = []) {
  const logsByQueueId = new Map();
  for (const log of logs) {
    if (!logsByQueueId.has(log.queueItemId)) logsByQueueId.set(log.queueItemId, []);
    logsByQueueId.get(log.queueItemId).push(log);
  }
  return items.map((item) => {
    const history = (logsByQueueId.get(item.queueItemId) || [])
      .sort((a, b) => String(b.changedAt || "").localeCompare(String(a.changedAt || "")));
    return {
      ...item,
      changeHistory: history.slice(0, 10),
      resolutionHistory: history.filter((log) => ["completed", "dismissed"].includes(log.eventType)).slice(0, 10)
    };
  });
}

async function externalConnectorOperationAlertQueue(params = new URLSearchParams()) {
  const [report, saved, logsData] = await Promise.all([
    externalConnectorScheduleOperationReport(params),
    readExternalConnectorOperationAlertQueue(),
    readExternalConnectorOperationAlertQueueLogs()
  ]);
  const candidates = operationAlertCandidatesFromReport(report);
  const merged = mergeOperationAlertQueue(candidates, saved.items || []);
  const filtered = attachOperationAlertLogs(filterOperationAlertQueueItems(merged, params), logsData.items || []);
  return {
    role: "admin",
    schema: "external_connector_operation_alert_queue_v1",
    generatedAt: new Date().toISOString(),
    sourceReport: {
      filters: report.filters,
      summary: report.summary
    },
    summary: operationAlertQueueSummary(merged),
    items: filtered
  };
}

async function updateExternalConnectorOperationAlertQueueItem(queueItemId = "", payload = {}) {
  const currentParams = new URLSearchParams({ limit: "1000" });
  const sourceFilters = payload.sourceReportFilters || {};
  ["connectorId", "eventType", "startDate", "endDate"].forEach((key) => {
    if (sourceFilters[key]) currentParams.set(key, sourceFilters[key]);
  });
  const currentQueue = await externalConnectorOperationAlertQueue(currentParams);
  const currentItem = (currentQueue.items || []).find((item) => item.queueItemId === queueItemId);
  if (!currentItem) return null;
  const saved = await readExternalConnectorOperationAlertQueue();
  const items = saved.items || [];
  const index = items.findIndex((item) => item.queueItemId === queueItemId);
  const existing = index >= 0 ? items[index] : {};
  const beforeItem = {
    ...currentItem,
    ...existing,
    status: normalizeOperationAlertStatus(existing.status || currentItem.status),
    assignee: String(existing.assignee ?? currentItem.assignee ?? "").trim(),
    dueDate: String(existing.dueDate ?? currentItem.dueDate ?? "").trim(),
    memo: String(existing.memo ?? currentItem.memo ?? "").trim()
  };
  const status = normalizeOperationAlertStatus(payload.status || existing.status || currentItem.status);
  const now = new Date().toISOString();
  const updated = {
    ...currentItem,
    ...existing,
    status,
    assignee: String(payload.assignee ?? existing.assignee ?? "").trim(),
    dueDate: String(payload.dueDate ?? existing.dueDate ?? "").trim(),
    memo: String(payload.memo ?? existing.memo ?? "").trim(),
    updatedBy: String(payload.updatedBy || existing.updatedBy || "admin").trim(),
    updatedAt: now,
    resolvedAt: ["done", "dismissed"].includes(status) ? (existing.resolvedAt || now) : null
  };
  if (index >= 0) items[index] = updated;
  else items.push(updated);
  const savedQueue = await writeExternalConnectorOperationAlertQueue({
    ...saved,
    items: items.sort((a, b) => String(b.updatedAt || b.generatedAt || "").localeCompare(String(a.updatedAt || a.generatedAt || "")))
  });
  const changes = operationAlertLogChanges(beforeItem, updated);
  let changeLog = null;
  if (changes.length) {
    changeLog = await appendExternalConnectorOperationAlertQueueLog({
      queueItemId,
      beforeItem,
      afterItem: updated,
      changes,
      changedBy: updated.updatedBy
    });
  }
  return {
    item: updated,
    changeLog,
    counts: {
      externalConnectorOperationAlertQueue: savedQueue.items.length
    }
  };
}

function sameJson(left, right) {
  return JSON.stringify(left ?? null) === JSON.stringify(right ?? null);
}

function setIfChanged(target, field, value, changes) {
  const before = target[field] ?? null;
  const after = value ?? null;
  if (sameJson(before, after)) return;
  target[field] = value;
  changes.push({ field, before, after });
}

function setOverrideIfChanged(target, field, value, changes) {
  const before = target[field] ?? null;
  const after = value ?? null;
  if (sameJson(before, after)) return;
  target[field] = value;
  changes.push({ field: `overrides.${field}`, before, after });
}

function verifiedPatchFromPayload(payload = {}) {
  const overrides = payload.overrides || {};
  return {
    canonicalName: String(payload.canonicalName || "").trim(),
    region: String(payload.region || "").trim(),
    category: String(payload.category || "").trim(),
    verifiedStatus: String(payload.verifiedStatus || "").trim() || "reviewed",
    finalConfidence: normalizeConfidence(payload.finalConfidence),
    b2bVisibility: normalizeVisibility(payload.b2bVisibility),
    notes: String(payload.notes || "").trim(),
    reviewedBy: String(payload.reviewedBy || "").trim() || "admin",
    overrides: {
      roomTotal: numberOrNull(overrides.roomTotal ?? payload.roomTotal),
      dayUseTotal: numberOrNull(overrides.dayUseTotal ?? payload.dayUseTotal),
      channelUrls: normalizeChannelUrls(overrides.channelUrls ?? payload.channelUrls)
    }
  };
}

async function companyDetail(companyId) {
  const [companies, observations, profiles, changeLogs] = await Promise.all([
    readCompanyMaster(),
    readPropertyObservations(),
    readVerifiedProfiles(),
    readVerifiedChangeLogs()
  ]);
  const company = (companies.items || []).find((item) => item.companyId === companyId);
  if (!company) return null;
  return {
    company,
    profile: (profiles.items || []).find((item) => item.companyId === companyId) || buildVerifiedProfileDraft(company),
    observations: (observations.items || []).filter((item) => item.companyId === companyId).slice(0, 100),
    changeLogs: (changeLogs.items || []).filter((item) => item.companyId === companyId).slice(0, 100)
  };
}

async function updateVerifiedProfile(companyId, payload = {}) {
  const [companies, profiles, changeLogs] = await Promise.all([
    readCompanyMaster(),
    readVerifiedProfiles(),
    readVerifiedChangeLogs()
  ]);
  const companyIndex = (companies.items || []).findIndex((item) => item.companyId === companyId);
  if (companyIndex < 0) return null;

  const company = companies.items[companyIndex];
  const profileItems = profiles.items || [];
  const profileIndex = profileItems.findIndex((item) => item.companyId === companyId);
  const existing = profileIndex >= 0 ? profileItems[profileIndex] : buildVerifiedProfileDraft(company);
  const updated = {
    ...existing,
    overrides: { ...(existing.overrides || {}) }
  };
  const patch = verifiedPatchFromPayload({
    ...payload,
    canonicalName: payload.canonicalName ?? existing.canonicalName ?? company.canonicalName,
    region: payload.region ?? existing.region ?? company.region,
    category: payload.category ?? existing.category ?? company.category,
    b2bVisibility: payload.b2bVisibility ?? existing.b2bVisibility ?? company.b2bVisibility
  });
  const changes = [];

  setIfChanged(updated, "canonicalName", patch.canonicalName, changes);
  setIfChanged(updated, "region", patch.region, changes);
  setIfChanged(updated, "category", patch.category, changes);
  setIfChanged(updated, "verifiedStatus", patch.verifiedStatus, changes);
  setIfChanged(updated, "finalConfidence", patch.finalConfidence, changes);
  setIfChanged(updated, "b2bVisibility", patch.b2bVisibility, changes);
  setIfChanged(updated, "notes", patch.notes, changes);
  setIfChanged(updated, "reviewedBy", patch.reviewedBy, changes);
  setOverrideIfChanged(updated.overrides, "roomTotal", patch.overrides.roomTotal, changes);
  setOverrideIfChanged(updated.overrides, "dayUseTotal", patch.overrides.dayUseTotal, changes);
  setOverrideIfChanged(updated.overrides, "channelUrls", patch.overrides.channelUrls, changes);

  updated.reviewedAt = new Date().toISOString();
  updated.updatedAt = updated.reviewedAt;

  if (profileIndex >= 0) profileItems[profileIndex] = updated;
  else profileItems.push(updated);

  companies.items[companyIndex] = {
    ...company,
    verifiedStatus: updated.verifiedStatus,
    b2bVisibility: updated.b2bVisibility,
    lastReviewedAt: updated.reviewedAt
  };

  const scopedChanges = changes.map((change) => ({
    changeId: hashId("chg", `${companyId}|${updated.reviewedAt}|${change.field}|${JSON.stringify(change.after)}`),
    companyId,
    field: change.field,
    before: change.before,
    after: change.after,
    changedBy: updated.reviewedBy || "admin",
    changedAt: updated.reviewedAt
  }));

  const mergedLogs = {
    ...changeLogs,
    items: [...(changeLogs.items || []), ...scopedChanges].sort((a, b) => String(b.changedAt).localeCompare(String(a.changedAt)))
  };

  await writeJsonFile(COMPANY_MASTER_FILE, companies);
  await writeJsonFile(COMPANY_VERIFIED_PROFILE_FILE, { ...profiles, items: profileItems });
  await writeJsonFile(VERIFIED_CHANGE_LOGS_FILE, mergedLogs);

  return {
    company: companies.items[companyIndex],
    profile: updated,
    changes: scopedChanges
  };
}

function reliabilityNameKey(value = "") {
  return compactKeyword(value).toLowerCase();
}

function rawValueCounts(values = []) {
  return values.reduce((acc, value) => {
    const key = String(value ?? "").trim();
    if (!key) return acc;
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
}

function reliabilityFieldValue(company = {}, profile = {}, observations = [], field = "") {
  if (field === "canonicalName") return company.canonicalName || "";
  if (field === "region" || field === "category") {
    return company[field] || topRawKey(rawValueCounts(observations.map((item) => item[field]))) || "";
  }
  if (field === "roomTotal") {
    return numberOrNull(company.roomTotal) ?? numberOrNull(topRawKey(rawValueCounts(observations.map((item) => item.totalRooms))));
  }
  return company[field] || "";
}

function verifiedFieldValue(profile = {}, field = "") {
  if (field === "roomTotal") return numberOrNull(profile.overrides?.roomTotal);
  if (field === "channelUrls") return Array.isArray(profile.overrides?.channelUrls) ? profile.overrides.channelUrls : [];
  return profile[field] || "";
}

function dataReliabilityConflictRows(company = {}, profile = {}, observations = []) {
  const rows = [];
  ["canonicalName", "region", "category"].forEach((field) => {
    const automaticValue = reliabilityFieldValue(company, profile, observations, field);
    const verifiedValue = verifiedFieldValue(profile, field);
    if (!verifiedValue || !automaticValue) return;
    if (reliabilityNameKey(automaticValue) === reliabilityNameKey(verifiedValue)) return;
    rows.push({
      field,
      automaticValue,
      verifiedValue,
      severity: field === "canonicalName" ? "high" : "medium",
      note: "automatic and verified values differ"
    });
  });

  const automaticRoomTotal = reliabilityFieldValue(company, profile, observations, "roomTotal");
  const verifiedRoomTotal = verifiedFieldValue(profile, "roomTotal");
  if (verifiedRoomTotal !== null && automaticRoomTotal !== null && Number(automaticRoomTotal) !== Number(verifiedRoomTotal)) {
    rows.push({
      field: "roomTotal",
      automaticValue: automaticRoomTotal,
      verifiedValue: verifiedRoomTotal,
      severity: "medium",
      note: "room/site count differs from observed value"
    });
  }
  return rows;
}

function dataReliabilityObservationSummary(observations = []) {
  const latestObservedAt = observations
    .map((item) => item.observedAt || item.collectedAt || item.updatedAt || "")
    .filter(Boolean)
    .sort()
    .reverse()[0] || null;
  const channels = [...new Set(observations.map((item) => item.channel).filter(Boolean))].slice(0, 8);
  return {
    total: observations.length,
    modes: collectionModeCounts(observations),
    channels,
    latestObservedAt
  };
}

function dataReliabilityIdQuality(company = {}, duplicateCandidates = []) {
  const reasons = [];
  const identityKey = company.identityKey || "";
  const hasExternalId = /^naver_(place|booking):/.test(identityKey);
  const hasStableId = /^cmp_[a-f0-9]{14}$/.test(String(company.companyId || ""));
  if (!hasStableId) reasons.push("company_id format needs review");
  if (!identityKey) reasons.push("identity key is missing");
  if (identityKey.startsWith("name_region:")) reasons.push("name+region fallback identity");
  if (!company.region) reasons.push("region is missing");
  if (!company.category) reasons.push("category is missing");
  if (duplicateCandidates.length) reasons.push("possible duplicate company_id exists");
  const status = !hasStableId || !identityKey ? "weak" : reasons.length ? "needs_review" : "stable";
  return {
    status,
    identityKey,
    hasExternalId,
    aliasCount: (company.aliases || []).length,
    reasons
  };
}

function dataReliabilityDuplicateCandidates(company = {}, companies = []) {
  const nameKey = reliabilityNameKey(company.canonicalName || "");
  const regionKey = reliabilityNameKey(company.region || "");
  if (!nameKey) return [];
  return companies
    .filter((item) => item.companyId !== company.companyId)
    .map((item) => {
      const candidateNameKey = reliabilityNameKey(item.canonicalName || "");
      const candidateRegionKey = reliabilityNameKey(item.region || "");
      const reasons = [];
      let score = 0;
      if (candidateNameKey && candidateNameKey === nameKey) {
        score += 70;
        reasons.push("same normalized name");
      } else if (candidateNameKey && (candidateNameKey.includes(nameKey) || nameKey.includes(candidateNameKey))) {
        score += 45;
        reasons.push("similar normalized name");
      }
      if (regionKey && candidateRegionKey && regionKey === candidateRegionKey) {
        score += 20;
        reasons.push("same region");
      }
      if (company.identityKey && item.identityKey && company.identityKey === item.identityKey) {
        score += 90;
        reasons.push("same identity key");
      }
      return {
        companyId: item.companyId,
        name: item.canonicalName || "",
        region: item.region || "",
        category: item.category || "",
        score: Math.min(100, score),
        reasons
      };
    })
    .filter((item) => item.score >= 60)
    .sort((a, b) => b.score - a.score)
    .slice(0, 5);
}

function dataReliabilityRecommendedActions({ conflicts = [], duplicateCandidates = [], idQuality = {}, profile = {}, observations = [], locationCardAudit = null } = {}) {
  const actions = [];
  if (duplicateCandidates.length) actions.push("review merge/split candidates");
  if (conflicts.length) actions.push("compare automatic observations with verified profile");
  if (idQuality.status !== "stable") actions.push("strengthen company_id identity fields");
  if (!profile.finalConfidence) actions.push("set final confidence grade");
  if (!observations.length) actions.push("collect fast/detailed observations");
  if (locationCardAudit?.missing) actions.push("create location card for region/category/company_id");
  if (locationCardAudit?.reviewRequired) actions.push("review location card before business exposure");
  if (locationCardAudit && !locationCardAudit.publicReady && !locationCardAudit.missing && !locationCardAudit.reviewRequired) actions.push("publish public-safe location card summary");
  if (locationCardAudit?.conflictCount) actions.push("resolve location card and observation conflict");
  return actions.length ? actions : ["monitor"];
}

function dataReliabilityScore({ profile = {}, observations = [], conflicts = [], duplicateCandidates = [], idQuality = {}, locationCardAudit = null } = {}) {
  let score = 20;
  if (idQuality.status === "stable") score += 25;
  else if (idQuality.status === "needs_review") score += 12;
  if (observations.length >= 8) score += 20;
  else if (observations.length >= 3) score += 12;
  else if (observations.length > 0) score += 6;
  if (["A", "B"].includes(String(profile.finalConfidence || "").toUpperCase())) score += 20;
  else if (profile.finalConfidence === "C") score += 10;
  if (!conflicts.length) score += 15;
  else score -= Math.min(20, conflicts.length * 6);
  if (!duplicateCandidates.length) score += 10;
  else score -= Math.min(15, duplicateCandidates.length * 5);
  if (locationCardAudit?.publicReady && !locationCardAudit.conflictCount) score += 8;
  if (locationCardAudit?.missing) score -= 8;
  if (locationCardAudit?.reviewRequired) score -= 5;
  if (locationCardAudit?.conflictCount) score -= Math.min(12, locationCardAudit.conflictCount * 4);
  return Math.round(Math.max(0, Math.min(100, score)));
}

function buildDataReliabilityAuditItem(company = {}, context = {}) {
  const profilesById = context.profilesById || new Map();
  const observationsByCompany = context.observationsByCompany || new Map();
  const companies = context.companies || [];
  const profile = profilesById.get(company.companyId) || buildVerifiedProfileDraft(company);
  const observations = observationsByCompany.get(company.companyId) || [];
  const duplicateCandidates = dataReliabilityDuplicateCandidates(company, companies);
  const conflicts = dataReliabilityConflictRows(company, profile, observations);
  const idQuality = dataReliabilityIdQuality(company, duplicateCandidates);
  const locationCardAudit = buildLocationCardReliabilityAudit(company, context, observations);
  const qualityScore = dataReliabilityScore({ profile, observations, conflicts, duplicateCandidates, idQuality, locationCardAudit });
  const qualityGrade = confidenceGrade(qualityScore);
  return {
    companyId: company.companyId,
    name: profile.canonicalName || company.canonicalName || "",
    region: profile.region || company.region || "",
    category: profile.category || company.category || "",
    autoConfidence: company.autoConfidence || "D",
    finalConfidence: profile.finalConfidence || null,
    qualityScore,
    qualityGrade,
    confidenceBasis: [
      `id:${idQuality.status}`,
      `observations:${observations.length}`,
      `conflicts:${conflicts.length}`,
      `duplicates:${duplicateCandidates.length}`,
      `final:${profile.finalConfidence || "-"}`,
      ...(locationCardAudit.basis || [])
    ],
    idQuality,
    duplicateCandidates,
    conflicts,
    locationCardAudit,
    observationSummary: dataReliabilityObservationSummary(observations),
    recommendedActions: dataReliabilityRecommendedActions({ conflicts, duplicateCandidates, idQuality, profile, observations, locationCardAudit })
  };
}

function dataReliabilityDuplicateGroups(items = []) {
  const groups = new Map();
  items.forEach((item) => {
    const nameKey = reliabilityNameKey(item.name);
    const regionKey = reliabilityNameKey(item.region);
    const key = `${nameKey}|${regionKey}`;
    if (!nameKey) return;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  });
  return [...groups.entries()]
    .filter(([, groupItems]) => groupItems.length > 1)
    .map(([groupKey, groupItems]) => ({
      groupKey,
      reason: "same normalized name and region",
      suggestedAction: "merge_review",
      items: groupItems.map((item) => ({
        companyId: item.companyId,
        name: item.name,
        region: item.region,
        qualityGrade: item.qualityGrade,
        qualityScore: item.qualityScore
      }))
    }));
}

async function dataReliabilityAudit(params = new URLSearchParams()) {
  const [companiesData, observationsData, profilesData, locationCardsData] = await Promise.all([
    readCompanyMaster(),
    readPropertyObservations(),
    readVerifiedProfiles(),
    readLocationCards()
  ]);
  const companyId = params.get("companyId") || "";
  const issue = params.get("issue") || "";
  const limit = Math.max(1, Math.min(500, Number(params.get("limit") || 100)));
  const companies = companiesData.items || [];
  const profilesById = new Map((profilesData.items || []).map((item) => [item.companyId, item]));
  const observationsByCompany = new Map();
  (observationsData.items || []).forEach((item) => {
    if (!observationsByCompany.has(item.companyId)) observationsByCompany.set(item.companyId, []);
    observationsByCompany.get(item.companyId).push(item);
  });
  let items = companies.map((company) => buildDataReliabilityAuditItem(company, {
    companies,
    profilesById,
    observationsByCompany,
    locationCards: locationCardsData.items || []
  }));
  const duplicateGroups = dataReliabilityDuplicateGroups(items);
  if (companyId) items = items.filter((item) => item.companyId === companyId);
  if (issue === "duplicates") items = items.filter((item) => item.duplicateCandidates.length);
  if (issue === "conflicts") items = items.filter((item) => item.conflicts.length);
  if (issue === "id_quality") items = items.filter((item) => item.idQuality.status !== "stable");
  if (issue === "low_confidence") items = items.filter((item) => ["C", "D"].includes(item.qualityGrade));
  if (issue === "location_card") items = items.filter((item) => item.locationCardAudit?.status !== "public_ready");
  const gradeCounts = items.reduce((acc, item) => {
    acc[item.qualityGrade] = (acc[item.qualityGrade] || 0) + 1;
    return acc;
  }, { A: 0, B: 0, C: 0, D: 0 });
  return {
    schema: "data_reliability_audit_v1",
    generatedAt: new Date().toISOString(),
    summary: {
      companies: companies.length,
      scopedCompanies: items.length,
      duplicateGroups: duplicateGroups.length,
      mergeCandidates: items.filter((item) => item.duplicateCandidates.length).length,
      conflicts: items.reduce((sum, item) => sum + item.conflicts.length, 0),
      locationCardMissing: items.filter((item) => item.locationCardAudit?.missing).length,
      locationCardReviewRequired: items.filter((item) => item.locationCardAudit?.reviewRequired).length,
      locationCardPublicReady: items.filter((item) => item.locationCardAudit?.publicReady).length,
      locationCardConflicts: items.reduce((sum, item) => sum + (item.locationCardAudit?.conflictCount || 0), 0),
      idWarnings: items.filter((item) => item.idQuality.status !== "stable").length,
      lowConfidence: items.filter((item) => ["C", "D"].includes(item.qualityGrade)).length,
      gradeCounts
    },
    duplicateGroups,
    items: items
      .sort((a, b) => (
        b.conflicts.length +
        b.duplicateCandidates.length +
        (b.locationCardAudit?.missing ? 2 : 0) +
        (b.locationCardAudit?.reviewRequired ? 1 : 0) +
        (b.locationCardAudit?.conflictCount || 0)
      ) - (
        a.conflicts.length +
        a.duplicateCandidates.length +
        (a.locationCardAudit?.missing ? 2 : 0) +
        (a.locationCardAudit?.reviewRequired ? 1 : 0) +
        (a.locationCardAudit?.conflictCount || 0)
      ) || a.qualityScore - b.qualityScore)
      .slice(0, limit)
  };
}

function normalizeDataReliabilityQueueStatus(value = "") {
  const text = String(value || "").trim();
  if (["open", "in_progress", "done", "dismissed"].includes(text)) return text;
  return "open";
}

function dataReliabilityQueueStatusCounts(items = []) {
  return items.reduce((counts, item) => {
    const status = normalizeDataReliabilityQueueStatus(item.status);
    counts[status] = (counts[status] || 0) + 1;
    return counts;
  }, {});
}

function dataReliabilityActionTypeLabel(type = "") {
  return {
    duplicate_merge: "duplicate/merge candidate",
    company_id_quality: "company_id quality",
    location_card_missing: "location card missing",
    location_card_review: "location card review required",
    location_card_publication: "location card publication required",
    location_card_conflict: "location card conflict"
  }[type] || type || "data reliability action";
}

function dataReliabilityQueueDueState(item = {}, now = new Date()) {
  const dueDate = String(item.dueDate || "").trim();
  if (!dueDate) return "no_due";
  const due = new Date(`${dueDate}T23:59:59`);
  if (Number.isNaN(due.getTime())) return "no_due";
  if (["done", "dismissed"].includes(item.status)) return "closed";
  if (due < now) return "overdue";
  const sevenDays = 7 * 24 * 60 * 60 * 1000;
  if (due.getTime() - now.getTime() <= sevenDays) return "this_week";
  return "upcoming";
}

function dataReliabilityQueueItem(auditItem = {}, issueType = "", detail = {}) {
  const sourceKey = String(detail.sourceKey || issueType || "").trim();
  return {
    queueItemId: hashId("drq", [auditItem.companyId, issueType, sourceKey].join("|")),
    issueType,
    issueLabel: dataReliabilityActionTypeLabel(issueType),
    sourceKey,
    companyId: auditItem.companyId || "",
    companyName: auditItem.name || "",
    region: auditItem.region || "",
    category: auditItem.category || "",
    title: detail.title || dataReliabilityActionTypeLabel(issueType),
    description: detail.description || "",
    severity: detail.severity || "medium",
    recommendedAction: detail.recommendedAction || "",
    evidence: detail.evidence || [],
    relatedIds: detail.relatedIds || [],
    qualityGrade: auditItem.qualityGrade || "",
    qualityScore: auditItem.qualityScore || 0,
    generatedAt: new Date().toISOString(),
    status: "open",
    assignee: "",
    dueDate: "",
    memo: "",
    updatedBy: "",
    updatedAt: null,
    resolvedAt: null
  };
}

function dataReliabilityActionCandidatesFromAudit(audit = {}) {
  const candidates = [];
  for (const item of audit.items || []) {
    if ((item.duplicateCandidates || []).length) {
      candidates.push(dataReliabilityQueueItem(item, "duplicate_merge", {
        sourceKey: (item.duplicateCandidates || []).map((candidate) => candidate.companyId).sort().join("|"),
        title: `${item.name || item.companyId} duplicate/merge review`,
        description: "Review possible duplicate company records before merging or splitting IDs.",
        severity: "high",
        recommendedAction: "compare candidate company IDs and decide merge/split",
        relatedIds: (item.duplicateCandidates || []).map((candidate) => candidate.companyId),
        evidence: (item.duplicateCandidates || []).map((candidate) => `${candidate.companyId} ${candidate.name || ""} score ${candidate.score || 0}`)
      }));
    }
    if (item.idQuality?.status && item.idQuality.status !== "stable") {
      candidates.push(dataReliabilityQueueItem(item, "company_id_quality", {
        sourceKey: item.idQuality.status,
        title: `${item.name || item.companyId} company_id quality review`,
        description: "Strengthen company identity fields used for duplicate-safe matching.",
        severity: item.idQuality.status === "weak" ? "high" : "medium",
        recommendedAction: "verify identity key, region, category, and external IDs",
        evidence: item.idQuality.reasons || []
      }));
    }
    const locationAudit = item.locationCardAudit || {};
    if (locationAudit.missing) {
      candidates.push(dataReliabilityQueueItem(item, "location_card_missing", {
        sourceKey: `${item.region}|${item.category}`,
        title: `${item.name || item.companyId} location card missing`,
        description: "Create a location card by company_id, region, or category.",
        severity: "medium",
        recommendedAction: "create verified location card summary",
        evidence: locationAudit.basis || []
      }));
    }
    if (locationAudit.reviewRequired) {
      candidates.push(dataReliabilityQueueItem(item, "location_card_review", {
        sourceKey: locationAudit.bestMatch?.locationCardId || "review_required",
        title: `${item.name || item.companyId} location card review`,
        description: "Review the draft or review-required location card before business exposure.",
        severity: "medium",
        recommendedAction: "complete admin review and set public-safe exposure",
        relatedIds: [locationAudit.bestMatch?.locationCardId].filter(Boolean),
        evidence: locationAudit.basis || []
      }));
    }
    if (locationAudit.status === "not_public") {
      candidates.push(dataReliabilityQueueItem(item, "location_card_publication", {
        sourceKey: locationAudit.bestMatch?.locationCardId || "not_public",
        title: `${item.name || item.companyId} location card publication`,
        description: "A location card exists but is not available as a public-safe business summary.",
        severity: "low",
        recommendedAction: "enable public-safe summary or keep hidden with reason",
        relatedIds: [locationAudit.bestMatch?.locationCardId].filter(Boolean),
        evidence: locationAudit.basis || []
      }));
    }
    if (locationAudit.conflictCount) {
      candidates.push(dataReliabilityQueueItem(item, "location_card_conflict", {
        sourceKey: (locationAudit.conflicts || []).map((conflict) => conflict.field).join("|") || "conflict",
        title: `${item.name || item.companyId} location card conflict`,
        description: "Resolve differences between automatic observations and location card summary.",
        severity: (locationAudit.conflicts || []).some((conflict) => conflict.severity === "high") ? "high" : "medium",
        recommendedAction: "compare observed region/category with location card summary",
        relatedIds: [locationAudit.bestMatch?.locationCardId].filter(Boolean),
        evidence: (locationAudit.conflicts || []).map((conflict) => `${conflict.field}: ${conflict.automaticValue || "-"} -> ${conflict.locationCardValue || "-"}`)
      }));
    }
  }
  return candidates;
}

function mergeDataReliabilityActionCandidates(candidates = [], savedItems = []) {
  const savedById = new Map(savedItems.map((item) => [item.queueItemId, item]));
  const candidateIds = new Set(candidates.map((item) => item.queueItemId));
  const merged = candidates.map((candidate) => {
    const saved = savedById.get(candidate.queueItemId) || {};
    return {
      ...candidate,
      status: normalizeDataReliabilityQueueStatus(saved.status || candidate.status),
      assignee: saved.assignee || "",
      dueDate: saved.dueDate || "",
      memo: saved.memo || "",
      updatedBy: saved.updatedBy || "",
      updatedAt: saved.updatedAt || null,
      resolvedAt: saved.resolvedAt || null,
      currentCandidate: true,
      stale: false
    };
  });
  const stale = savedItems
    .filter((item) => !candidateIds.has(item.queueItemId))
    .map((item) => ({
      ...item,
      issueLabel: item.issueLabel || dataReliabilityActionTypeLabel(item.issueType),
      status: normalizeDataReliabilityQueueStatus(item.status),
      currentCandidate: false,
      stale: true
    }));
  return [...merged, ...stale];
}

function filterDataReliabilityActionQueueItems(items = [], params = new URLSearchParams()) {
  const status = params.get("status") || "";
  const issueType = params.get("issueType") || "";
  const assignee = compactKeyword(params.get("assignee") || "");
  const dueState = params.get("dueState") || "";
  const companyId = params.get("companyId") || "";
  const query = compactKeyword(params.get("q") || "");
  const limit = Math.max(1, Math.min(1000, Number(params.get("limit") || 200)));
  return items
    .map((item) => ({ ...item, dueState: dataReliabilityQueueDueState(item) }))
    .filter((item) => !status || item.status === status)
    .filter((item) => !issueType || item.issueType === issueType)
    .filter((item) => !assignee || compactKeyword(item.assignee).includes(assignee))
    .filter((item) => !dueState || item.dueState === dueState)
    .filter((item) => !companyId || item.companyId === companyId)
    .filter((item) => {
      if (!query) return true;
      return compactKeyword([
        item.companyName,
        item.region,
        item.category,
        item.title,
        item.description,
        item.assignee,
        item.memo
      ].join(" ")).includes(query);
    })
    .sort((a, b) => {
      const severityRank = { high: 3, medium: 2, low: 1 };
      const statusRank = { open: 3, in_progress: 2, done: 0, dismissed: 0 };
      return (statusRank[b.status] || 0) - (statusRank[a.status] || 0)
        || (severityRank[b.severity] || 0) - (severityRank[a.severity] || 0)
        || String(a.dueDate || "9999-12-31").localeCompare(String(b.dueDate || "9999-12-31"));
    })
    .slice(0, limit);
}

function dataReliabilityActionQueueSummary(items = []) {
  const byStatus = dataReliabilityQueueStatusCounts(items);
  const byType = items.reduce((counts, item) => {
    counts[item.issueType] = (counts[item.issueType] || 0) + 1;
    return counts;
  }, {});
  return {
    total: items.length,
    open: byStatus.open || 0,
    inProgress: byStatus.in_progress || 0,
    done: byStatus.done || 0,
    dismissed: byStatus.dismissed || 0,
    overdue: items.filter((item) => dataReliabilityQueueDueState(item) === "overdue").length,
    thisWeek: items.filter((item) => dataReliabilityQueueDueState(item) === "this_week").length,
    stale: items.filter((item) => item.stale).length,
    byStatus,
    byType
  };
}

async function dataReliabilityActionQueue(params = new URLSearchParams()) {
  const [audit, saved] = await Promise.all([
    dataReliabilityAudit(new URLSearchParams({ limit: "500" })),
    readDataReliabilityActionQueue()
  ]);
  const candidates = dataReliabilityActionCandidatesFromAudit(audit);
  const merged = mergeDataReliabilityActionCandidates(candidates, saved.items || []);
  const filtered = filterDataReliabilityActionQueueItems(merged, params);
  return {
    schema: "data_reliability_action_queue_v1",
    generatedAt: new Date().toISOString(),
    summary: dataReliabilityActionQueueSummary(merged),
    items: filtered
  };
}

async function writeDataReliabilityActionQueue(payload = {}) {
  return writeJsonFile(DATA_RELIABILITY_ACTION_QUEUE_FILE, {
    version: 1,
    name: "data_reliability_action_queue",
    schema: "data_reliability_action_queue_v1",
    items: Array.isArray(payload.items) ? payload.items : []
  });
}

async function updateDataReliabilityActionQueueItem(queueItemId = "", payload = {}) {
  const currentQueue = await dataReliabilityActionQueue(new URLSearchParams({ limit: "1000" }));
  const currentItem = (currentQueue.items || []).find((item) => item.queueItemId === queueItemId);
  if (!currentItem) return null;
  const saved = await readDataReliabilityActionQueue();
  const items = saved.items || [];
  const index = items.findIndex((item) => item.queueItemId === queueItemId);
  const existing = index >= 0 ? items[index] : {};
  const status = normalizeDataReliabilityQueueStatus(payload.status || existing.status || currentItem.status);
  const now = new Date().toISOString();
  const updated = {
    ...currentItem,
    ...existing,
    status,
    assignee: String(payload.assignee ?? existing.assignee ?? "").trim(),
    dueDate: String(payload.dueDate ?? existing.dueDate ?? "").trim(),
    memo: String(payload.memo ?? existing.memo ?? "").trim(),
    updatedBy: String(payload.updatedBy || existing.updatedBy || "admin").trim(),
    updatedAt: now,
    resolvedAt: ["done", "dismissed"].includes(status) ? (existing.resolvedAt || now) : null
  };
  if (index >= 0) items[index] = updated;
  else items.push(updated);
  const savedQueue = await writeDataReliabilityActionQueue({
    ...saved,
    items: items.sort((a, b) => String(b.updatedAt || b.generatedAt || "").localeCompare(String(a.updatedAt || a.generatedAt || "")))
  });
  return {
    item: updated,
    counts: {
      dataReliabilityActionQueue: savedQueue.items.length,
      byStatus: dataReliabilityQueueStatusCounts(savedQueue.items)
    }
  };
}

function buildCompanyRecord(item = {}, run = {}, existing = null) {
  const companyId = companyIdForItem(item);
  const now = new Date().toISOString();
  const naverPlaceId = extractNaverPlaceId(item.url);
  const naverBookingId = extractNaverBookingId(item.url);
  const sourceRunIds = new Set([...(existing?.sourceRunIds || []), run.id].filter(Boolean));
  const aliases = new Set([...(existing?.aliases || []), item.name].filter(Boolean));
  const urls = new Set([...(existing?.urls || []), item.url].filter(Boolean));
  const bestRank = Number(item.rank);
  const existingBestRank = Number(existing?.bestRank);

  return {
    companyId,
    identityKey: identityKeyForCompany(item),
    canonicalName: existing?.canonicalName || item.name || "",
    aliases: [...aliases],
    region: existing?.region || item.region || "",
    address: existing?.address || item.address || "",
    category: existing?.category || item.category || "",
    externalIds: {
      ...(existing?.externalIds || {}),
      ...(naverPlaceId ? { naverPlaceId } : {}),
      ...(naverBookingId ? { naverBookingId } : {})
    },
    urls: [...urls],
    bestRank: Number.isFinite(existingBestRank) && Number.isFinite(bestRank)
      ? Math.min(existingBestRank, bestRank)
      : Number.isFinite(existingBestRank)
        ? existingBestRank
        : Number.isFinite(bestRank)
          ? bestRank
          : null,
    firstSeenAt: existing?.firstSeenAt || now,
    lastSeenAt: now,
    sourceRunIds: [...sourceRunIds],
    autoConfidence: automaticConfidenceForItem(item),
    verifiedStatus: existing?.verifiedStatus || "unverified",
    b2bVisibility: existing?.b2bVisibility || "eligible"
  };
}

function buildObservationRecord(item = {}, run = {}, companyId = "", options = {}) {
  const collectionMode = normalizeCollectionMode(options.collectionMode, inferBaseCollectionMode(item));
  const observedAt = options.observedAt || observedAtForRun(run);
  const targetDate = targetDateForObservation(run, item, options);
  const channel = channelForObservation(collectionMode, item, options);
  const productKey = productKeyForObservation(run, item, options);
  const record = {
    companyId,
    source: options.source || "run_summary",
    runId: run.id || "",
    observedAt,
    collectionMode,
    searchScope: searchScopeForObservation(collectionMode, run, options),
    channel,
    targetDate,
    leadTimeDays: leadTimeDaysFor(targetDate, observedAt),
    productKey,
    checkIn: run.checkIn || "",
    checkOut: run.checkOut || "",
    productMode: run.productMode || "",
    province: run.province || "",
    provinceLabel: run.provinceLabel || "",
    region: item.region || "",
    rank: item.rank || null,
    price: item.price || "",
    availableRooms: item.availableRooms || null,
    totalRooms: item.totalRooms || null,
    soldOutRooms: item.soldOutRooms || null,
    soldOutRate: item.soldOutRate || null,
    reservationRate: item.weeklyAvgReservationRate ?? item.reservationRate ?? item.soldOutRate ?? null,
    weeklyReservationRateDetail: item.weeklyReservationRateDetail || "",
    weeklyTotalSoldOut: item.weeklyTotalSoldOut ?? null,
    weeklyTotalStock: item.weeklyTotalStock ?? null,
    url: item.url || "",
    autoConfidence: automaticConfidenceForItem(item)
  };
  record.observationGroupKey = observationGroupKeyFor(record);
  record.observationId = options.preserveLegacyId
    ? observationIdForItem(run.id, companyId, item)
    : observationIdForRecord(record, item);
  return record;
}

function buildObservationRecords(item = {}, run = {}, companyId = "") {
  const records = [
    buildObservationRecord(item, run, companyId, {
      collectionMode: inferBaseCollectionMode(item),
      preserveLegacyId: true
    })
  ];

  if (hasInventorySignal(item)) {
    records.push(buildObservationRecord(item, run, companyId, {
      collectionMode: "leadtime_observation",
      source: "leadtime_probe",
      channel: "naver_booking",
      searchScope: "property_date_product"
    }));
  }

  return records;
}

function buildOtaExposureObservationRecords(company = {}, run = {}, companyId = "") {
  const platforms = Array.isArray(company.platforms) ? company.platforms : [];
  return platforms.map((platform) => buildObservationRecord({
    rank: platform.rank || company.bestRank || null,
    price: platform.price || "",
    url: platform.url || "",
    region: company.region || "",
    reservationRate: platform.weeklyAvgReservationRate ?? null,
    weeklyReservationRateDetail: platform.weeklyReservationRateDetail || "",
    weeklyTotalSoldOut: platform.weeklyTotalSoldOut ?? null,
    weeklyTotalStock: platform.weeklyTotalStock ?? null,
    channel: platform.platform || "ota",
    totalRooms: null,
    availableRooms: null
  }, run, companyId, {
    collectionMode: "ota_exposure",
    source: "platform_summary",
    channel: platform.platform || "ota",
    searchScope: "ota_channel_presence",
    productKey: `ota:${platform.platform || "unknown"}`
  })).map((record, index) => ({
    ...record,
    otaExposure: {
      present: true,
      status: platforms[index]?.status || "",
      group: platforms[index]?.group || "",
      inventoryNote: platforms[index]?.inventoryNote || ""
    }
  }));
}

function buildManualObservation(payload = {}, company = {}) {
  const run = {
    id: String(payload.runId || `manual_${Date.now()}`),
    checkIn: isoDate(payload.checkIn || payload.targetDate),
    checkOut: isoDate(payload.checkOut),
    productMode: payload.productMode || "",
    province: payload.province || "",
    provinceLabel: payload.provinceLabel || ""
  };
  const item = {
    region: payload.region || company.region || "",
    rank: numberOrNull(payload.rank),
    price: payload.price || "",
    availableRooms: numberOrNull(payload.availableRooms),
    totalRooms: numberOrNull(payload.totalRooms),
    soldOutRooms: numberOrNull(payload.soldOutRooms),
    soldOutRate: numberOrNull(payload.soldOutRate),
    reservationRate: numberOrNull(payload.reservationRate),
    weeklyReservationRateDetail: payload.weeklyReservationRateDetail || "",
    weeklyTotalSoldOut: numberOrNull(payload.weeklyTotalSoldOut),
    weeklyTotalStock: numberOrNull(payload.weeklyTotalStock),
    url: payload.url || ""
  };
  return buildObservationRecord(item, run, company.companyId, {
    collectionMode: normalizeCollectionMode(payload.collectionMode, "leadtime_observation"),
    source: payload.source || "manual_admin",
    observedAt: payload.observedAt || new Date().toISOString(),
    targetDate: payload.targetDate,
    channel: payload.channel,
    searchScope: payload.searchScope,
    productKey: payload.productKey
  });
}

function buildVerifiedProfileDraft(company = {}) {
  return {
    companyId: company.companyId,
    canonicalName: company.canonicalName || "",
    region: company.region || "",
    category: company.category || "",
    verifiedStatus: "unverified",
    finalConfidence: null,
    b2bVisibility: company.b2bVisibility || "eligible",
    overrides: {},
    notes: "",
    reviewedBy: "",
    reviewedAt: null,
    createdAt: new Date().toISOString(),
    updatedAt: null
  };
}

async function rebuildMasterDbFromRuns(options = {}) {
  const runs = await listRuns();
  const targetRunIds = options.runId ? [String(options.runId)] : runs.map((run) => run.id);
  const existingMaster = await readCompanyMaster();
  const existingObservations = await readPropertyObservations();
  const existingProfiles = await readVerifiedProfiles();
  const companiesById = new Map((existingMaster.items || []).map((item) => [item.companyId, item]));
  const observationsById = new Map((existingObservations.items || []).map((item) => [item.observationId, item]));
  const profilesById = new Map((existingProfiles.items || []).map((item) => [item.companyId, item]));
  const importedRunIds = [];
  let skippedItems = 0;

  for (const runId of targetRunIds) {
    const data = await loadRun(runId);
    if (!data) continue;
    importedRunIds.push(runId);
    const items = data.availability?.items || [];

    for (const item of items) {
      const companyId = companyIdForItem(item);
      if (!companyId) {
        skippedItems += 1;
        continue;
      }
      const company = buildCompanyRecord(item, data.run, companiesById.get(companyId));
      companiesById.set(companyId, company);

      for (const observation of buildObservationRecords(item, data.run, companyId)) {
        observationsById.set(observation.observationId, observation);
      }

      if (!profilesById.has(companyId)) {
        profilesById.set(companyId, buildVerifiedProfileDraft(company));
      }
    }

    for (const region of data.regions || []) {
      for (const place of region.places || []) {
        const item = {
          ...place,
          region: place.region || region.region || "",
          category: place.category || "",
          url: place.url || ""
        };
        const matchedCompany = findCompanyByName(companiesById, item.name);
        const companyId = matchedCompany?.companyId || companyIdForItem(item);
        if (!companyId) {
          skippedItems += 1;
          continue;
        }

        const company = buildCompanyRecord(item, data.run, companiesById.get(companyId));
        companiesById.set(companyId, company);
        const observation = buildObservationRecord(item, data.run, companyId, {
          collectionMode: "fast_search",
          source: "regional_rank_summary",
          channel: "naver_place",
          searchScope: "region_category",
          preserveLegacyId: false
        });
        observationsById.set(observation.observationId, observation);

        if (!profilesById.has(companyId)) {
          profilesById.set(companyId, buildVerifiedProfileDraft(company));
        }
      }
    }

    for (const platformCompany of data.companyPlatforms || []) {
      const item = {
        name: platformCompany.name,
        rank: platformCompany.bestRank,
        url: platformCompany.platforms?.[0]?.url || "",
        region: "",
        category: ""
      };
      const matchedCompany = findCompanyByName(companiesById, platformCompany.name);
      const companyId = matchedCompany?.companyId || companyIdForItem(item);
      if (!companyId) {
        skippedItems += 1;
        continue;
      }

      const company = buildCompanyRecord(item, data.run, companiesById.get(companyId));
      companiesById.set(companyId, company);

      for (const observation of buildOtaExposureObservationRecords(platformCompany, data.run, companyId)) {
        observationsById.set(observation.observationId, observation);
      }

      if (!profilesById.has(companyId)) {
        profilesById.set(companyId, buildVerifiedProfileDraft(company));
      }
    }
  }

  const masterPayload = await writeJsonFile(COMPANY_MASTER_FILE, {
    version: 1,
    name: "company_master",
    items: [...companiesById.values()].sort((a, b) => String(a.canonicalName).localeCompare(String(b.canonicalName), "ko"))
  });
  const observationPayload = await writeJsonFile(PROPERTY_OBSERVATIONS_FILE, {
    version: 1,
    name: "property_observations",
    items: [...observationsById.values()].sort((a, b) => String(b.observedAt).localeCompare(String(a.observedAt)))
  });
  const profilePayload = await writeJsonFile(COMPANY_VERIFIED_PROFILE_FILE, {
    version: 1,
    name: "company_verified_profile",
    items: [...profilesById.values()].sort((a, b) => String(a.canonicalName).localeCompare(String(b.canonicalName), "ko"))
  });

  return {
    importedRunIds,
    skippedItems,
    files: {
      companyMaster: COMPANY_MASTER_FILE,
      propertyObservations: PROPERTY_OBSERVATIONS_FILE,
      verifiedProfiles: COMPANY_VERIFIED_PROFILE_FILE
    },
    counts: {
      companies: masterPayload.items.length,
      observations: observationPayload.items.length,
      verifiedProfiles: profilePayload.items.length
    }
  };
}

function collectionModeCounts(observations = []) {
  return observations.reduce((counts, item) => {
    const mode = normalizeCollectionMode(item.collectionMode, "fast_search");
    counts[mode] = (counts[mode] || 0) + 1;
    return counts;
  }, {});
}

