async function upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationProposals(candidates = []) {
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations();
  const existingItems = Array.isArray(data.items)
    ? data.items.map((item) => normalizeOperationQualityPostEffectCandidateQualityCalibration(deploymentOperationQualityAdminObject(item)))
    : [];
  const byId = new Map(existingItems.map((item) => [item.calibrationId, item]));
  candidates
    .filter(shouldStoreOperationQualityPostEffectCandidateQualityCalibration)
    .forEach((candidate) => {
      const calibrationId = candidate.qualityCalibration?.calibrationId ||
        operationQualityPostEffectCandidateQualityLearningCalibrationId(candidate);
      const proposal = buildDeploymentOperationQualityPostEffectCandidateQualityCalibrationProposal(candidate, byId.get(calibrationId) || null);
      byId.set(calibrationId, proposal);
    });
  const sorted = [...byId.values()].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, overridden: 2, rejected: 3, deactivated: 4 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
  });
  await writeDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations({
    ...data,
    items: sorted
  });
  return sorted;
}

