async function reviewDeploymentOperationQualityPostEffectCandidateQualityCalibration(payload = {}) {
  const calibrationId = String(payload.calibrationId || payload.id || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  const status = decision === "override" ? "overridden" : normalizeSlaPolicyCandidateQualityCalibrationStatus(decision);
  if (!calibrationId || !["approved", "rejected", "overridden"].includes(status)) {
    const error = new Error("Deployment operation candidate quality calibration id and approved/rejected/override decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations();
  const items = Array.isArray(data.items)
    ? data.items.map((item) => normalizeOperationQualityPostEffectCandidateQualityCalibration(deploymentOperationQualityAdminObject(item)))
    : [];
  const target = items.find((item) => item.calibrationId === calibrationId);
  if (!target) {
    const error = new Error("Deployment operation candidate quality calibration proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reviewReason = deploymentOperationQualityAdminText(payload.reviewReason || payload.reason || "");
  const overrideReason = deploymentOperationQualityAdminText(payload.overrideReason || "");
  const suggested = deploymentOperationQualityAdminObject(target.suggestedCalibration || {});
  let activeCalibration = null;
  if (status === "approved") {
    activeCalibration = {
      ...suggested,
      applied: suggested.direction !== "neutral" && suggested.priorityAfter !== suggested.priorityBefore,
      reason: reviewReason || suggested.reason || "Admin approved suggested deployment operation alert post-effect candidate quality learning."
    };
  } else if (status === "overridden") {
    const priorityBefore = ["low", "medium", "high"].includes(String(suggested.priorityBefore || "").trim())
      ? String(suggested.priorityBefore || "").trim()
      : "medium";
    const overridePriorityAfter = ["low", "medium", "high"].includes(String(payload.overridePriorityAfter || payload.priorityAfter || "").trim())
      ? String(payload.overridePriorityAfter || payload.priorityAfter || "").trim()
      : suggested.priorityAfter || priorityBefore;
    const beforeRank = operationQualityPriorityRank(priorityBefore);
    const afterRank = operationQualityPriorityRank(overridePriorityAfter);
    activeCalibration = {
      ...suggested,
      direction: afterRank > beforeRank ? "boost" : afterRank < beforeRank ? "downgrade" : "neutral",
      priorityAfter: overridePriorityAfter,
      applied: overridePriorityAfter !== priorityBefore,
      reason: overrideReason || reviewReason || `Admin override set active deployment operation alert quality learning priority ${priorityBefore} -> ${overridePriorityAfter}.`
    };
  }
  const simulationCandidate = {
    priority: suggested.priorityBefore,
    recommendation: target.simulation?.recommendationBefore || "",
    expectedImpact: target.simulation?.expectedImpactBefore || {}
  };
  const event = deploymentOperationQualityAdminObject(slaPolicyCandidateQualityCalibrationEvent({
    calibrationId,
    eventType: status,
    eventAt: now,
    eventBy: reviewer,
    previousStatus: target.status,
    nextStatus: status,
    reason: reviewReason,
    overridePriorityAfter: activeCalibration?.priorityAfter || "",
    overrideReason
  }));
  const updatedTarget = normalizeOperationQualityPostEffectCandidateQualityCalibration(deploymentOperationQualityAdminObject({
    ...target,
    status,
    activeCalibration,
    simulation: operationQualityPostEffectCandidateQualityLearningSimulation(
      simulationCandidate,
      suggested,
      activeCalibration
    ),
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason,
    overrideReason,
    updatedAt: now,
    updatedBy: reviewer,
    events: [event, ...(target.events || [])]
  }));
  const updatedItems = items.map((item) => item.calibrationId === calibrationId ? updatedTarget : item);
  await writeDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  await appendDeploymentOperationQualityPostEffectCandidateQualityCalibrationLog(event);
  return {
    ok: true,
    item: updatedTarget,
    workflow: deploymentOperationQualityPostEffectCandidateQualityCalibrationWorkflowReport(updatedItems, {}),
    reportBoundaries: {
      source: "admin-only deployment operation alert post-effect candidate quality calibration review decision",
      hiddenFromBusiness: ["quality learning approval status", "override reason", "candidate quality evidence", "review events", "backup paths", "security/deployment checks"]
    }
  };
}

