async function upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(performance = {}) {
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereview)
    : [];
  const byId = new Map(existingItems.map((item) => [item.rereviewId, item]));
  const touched = [];
  (performance.reReviewCandidates || []).forEach((candidate) => {
    const rereviewId = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewId(candidate);
    const existing = byId.get(rereviewId) || null;
    if (existing && ["completed", "dismissed"].includes(existing.status)) {
      touched.push(existing);
      return;
    }
    const item = buildDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidate(candidate, existing);
    byId.set(item.rereviewId, item);
    touched.push(item);
  });
  await writeDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  return touched;
}

