async function upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustmentProposals(actions = [], historyItems = []) {
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAdjustments();
  const existing = Array.isArray(data.items)
    ? data.items.map(normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustment)
    : [];
  const byId = new Map(existing.map((item) => [item.adjustmentId, item]));
  const activeAutoApprovalPolicy = await activeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPolicyFromStore();
  let changed = false;
  for (const action of actions) {
    const baseAction = normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewAction(action);
    const adjustment = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionHistoryAdjustment(baseAction, historyItems);
    if (!adjustment.applied || !adjustment.sampleSize || adjustment.direction === "neutral") continue;
    const proposal = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustmentFromAction(baseAction, adjustment);
    const previous = byId.get(proposal.adjustmentId);
    if (previous && ["approved", "rejected"].includes(previous.status)) continue;
    const now = new Date().toISOString();
    const mergedProposal = normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustment({
      ...(previous || {}),
      ...proposal,
      proposedBy: previous?.proposedBy || proposal.proposedBy,
      proposedAt: previous?.proposedAt || proposal.proposedAt
    });
    const policyDecision = evaluateDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApproval(mergedProposal, existing, activeAutoApprovalPolicy);
    const decisionHistory = previous?.decisionHistory || [];
    const autoDecisionHistory = policyDecision.eligible && previous?.status !== "approved"
      ? [
          ...decisionHistory,
          {
            decision: "approved",
            beforeStatus: previous?.status || "proposed",
            approvalMode: "auto",
            decidedBy: "system_auto",
            decidedAt: policyDecision.evaluatedAt,
            reason: policyDecision.reasons.join(" ")
          }
        ]
      : decisionHistory;
    const next = normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustment({
      ...mergedProposal,
      status: policyDecision.eligible ? "approved" : "proposed",
      active: policyDecision.eligible,
      approvalMode: policyDecision.eligible ? "auto" : "none",
      autoApprovalPolicy: policyDecision,
      autoApprovalRiskLevel: policyDecision.riskLevel || "",
      rollbackAvailable: policyDecision.eligible,
      manualApprovalRequired: !policyDecision.eligible,
      reviewMode: policyDecision.eligible ? "auto_approved" : "admin_required",
      approvedPriority: policyDecision.eligible ? mergedProposal.proposedPriority : "",
      approvedRecommendedAction: policyDecision.eligible ? mergedProposal.proposedRecommendedAction : "",
      approvedBy: policyDecision.eligible ? "system_auto" : "",
      approvedAt: policyDecision.eligible ? policyDecision.evaluatedAt : "",
      reviewReason: policyDecision.eligible ? policyDecision.reasons.join(" ") : "",
      updatedAt: policyDecision.evaluatedAt || now,
      updatedBy: policyDecision.eligible ? "system_auto" : "system",
      decisionHistory: autoDecisionHistory
    });
    byId.set(next.adjustmentId, next);
    changed = true;
    if (next.status === "approved" && next.approvalMode === "auto" && previous?.status !== "approved") {
      await appendDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalLog({
        adjustmentId: next.adjustmentId,
        sourceKey: next.sourceKey,
        eventType: "auto_approved",
        eventAt: next.approvedAt || next.updatedAt,
        eventBy: "system_auto",
        previousStatus: previous?.status || "proposed",
        nextStatus: "approved",
        rollbackAvailable: true,
        policyDecision,
        reason: next.reviewReason
      });
    }
  }
  if (!changed) {
    return {
      ...data,
      items: existing
    };
  }
  return writeDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAdjustments({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
}

