function applyDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPolicyPatch(policy = {}, patch = {}) {
  const next = {
    ...deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPolicy(),
    ...cloneSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policy),
    policyVersion: policy.policyVersion || "deployment_operation_quality_candidate_quality_rereview_action_rec_auto_approval_v1"
  };
  if (patch.global && typeof patch.global === "object") {
    Object.entries(patch.global).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== "") next[key] = value;
    });
  }
  if (patch.issueRules && typeof patch.issueRules === "object") {
    next.issueRules = {
      ...(next.issueRules || {})
    };
    Object.entries(patch.issueRules).forEach(([issueKey, rule]) => {
      next.issueRules[issueKey] = {
        ...(next.issueRules[issueKey] || {}),
        ...(rule || {})
      };
    });
  }
  return next;
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalExpectedImpact(candidate = {}) {
  const metrics = candidate.metrics || {};
  const currentSuccessRate = Number(metrics.successRate ?? 0);
  let expectedSuccessRate = currentSuccessRate;
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  if (candidateType.includes("tighten") || candidateType.includes("monitoring") || candidateType.includes("rollback")) {
    const riskPressure = Math.round((Number(metrics.falsePositiveRate || 0) + Number(metrics.rollbackRate || 0) + Number(metrics.recurrenceRate || 0)) / 6);
    expectedSuccessRate = Math.min(100, currentSuccessRate + Math.max(5, riskPressure));
  } else if (candidateType.includes("relax")) {
    expectedSuccessRate = Math.max(0, currentSuccessRate - 5);
  }
  return {
    scope: candidateType === "increase_operation_alert_rereview_auto_approval_monitoring_window" || candidateType === "tighten_owner_scoped_operation_alert_auto_policy" ? "global_policy" : "issue_policy",
    affectedTarget: String(candidate.target || candidate.issueKey || candidate.rootMetric || candidate.assignee || "").trim(),
    currentSuccessRate,
    expectedSuccessRate,
    expectedSuccessRateChange: expectedSuccessRate - currentSuccessRate,
    currentFalsePositiveRate: Number(metrics.falsePositiveRate || 0),
    currentRollbackRate: Number(metrics.rollbackRate || 0),
    currentRecurrenceRate: Number(metrics.recurrenceRate || 0),
    expectedManualReviewChange: candidateType.includes("tighten") || candidateType.includes("monitoring") ? 8 : candidateType.includes("relax") ? -5 : 0,
    evaluated: Number(metrics.evaluated || 0),
    total: Number(metrics.total || 0),
    basis: candidate.basis || ""
  };
}

