function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalLinkedHistory(adjustment = {}, historyItems = []) {
  const approvedAt = adjustment.approvedAt || adjustment.reviewedAt || adjustment.updatedAt || "";
  const approvedTime = new Date(approvedAt).getTime();
  const owner = String(adjustment.owner || adjustment.assignee || "").trim().toLowerCase();
  const issueKey = String(adjustment.issueKey || adjustment.rootMetric || "").trim();
  const actionId = String(adjustment.actionId || adjustment.candidateActionId || "").trim();
  return historyItems
    .map(normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistoryItem)
    .filter((item) => {
      const evaluatedTime = new Date(item.evaluatedAt || item.recordedAt || "").getTime();
      const afterApproval = !Number.isFinite(approvedTime) || !Number.isFinite(evaluatedTime) || evaluatedTime >= approvedTime;
      const sameAction = actionId && [item.actionId, item.sourceActionId].some((value) => String(value || "") === actionId);
      const sameFollowUpAction = actionId && (item.followUpActionIds || []).some((value) => String(value || "") === actionId);
      const sameSource = item.sourceKey && item.sourceKey === adjustment.sourceKey;
      const sameIssue = issueKey && [item.issueKey, item.rootMetric, item.metricKey].some((value) => String(value || "") === issueKey);
      const sameOwner = !owner || String(item.assignee || item.owner || "").toLowerCase() === owner;
      return afterApproval && (sameAction || sameFollowUpAction || sameSource || (sameIssue && sameOwner));
    })
    .sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")));
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPerformanceOutcome(adjustment = {}, linkedHistory = [], logs = []) {
  const rolledBack = Boolean(adjustment.rolledBackAt || logs.some((log) => log.adjustmentId === adjustment.adjustmentId && log.eventType === "rollback"));
  const evaluatedCount = linkedHistory.length;
  const avgEffectScore = evaluatedCount ? Math.round(linkedHistory.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / evaluatedCount) : 0;
  const improved = linkedHistory.filter((item) => item.outcome === "improved" || item.evaluationState === "improved").length;
  const worse = linkedHistory.filter((item) => item.outcome === "worse" || item.evaluationState === "worse").length;
  const recurrence = linkedHistory.filter((item) => item.recurrence).length;
  const followUpNeeded = linkedHistory.filter((item) => item.followUpNeeded).length;
  const improvedRate = evaluatedCount ? Math.round((improved / evaluatedCount) * 100) : 0;
  const worseRate = evaluatedCount ? Math.round((worse / evaluatedCount) * 100) : 0;
  const recurrenceRate = evaluatedCount ? Math.round((recurrence / evaluatedCount) * 100) : 0;
  const followUpNeededRate = evaluatedCount ? Math.round((followUpNeeded / evaluatedCount) * 100) : 0;
  const falsePositive = evaluatedCount > 0 && (worseRate >= 50 || recurrenceRate >= 50 || avgEffectScore < 45 || followUpNeededRate >= 50);
  const successful = evaluatedCount > 0 && !rolledBack && !falsePositive && avgEffectScore >= 65 && improvedRate >= 50 && recurrenceRate < 50;
  let outcome = "pending";
  if (rolledBack) outcome = "rolled_back";
  else if (falsePositive) outcome = "false_positive";
  else if (successful) outcome = "successful";
  else if (evaluatedCount > 0) outcome = "mixed";
  return {
    outcome,
    evaluatedCount,
    avgEffectScore,
    improved,
    improvedRate,
    worse,
    worseRate,
    recurrence,
    recurrenceRate,
    followUpNeeded,
    followUpNeededRate,
    falsePositive,
    successful,
    rolledBack
  };
}

