function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPolicyCandidates(items = [], aggregates = {}) {
  const candidates = [];
  const riskyMetrics = (aggregates.byRootMetric || []).filter((row) => row.evaluated >= 1 && (row.falsePositiveRate >= 40 || row.recurrenceRate >= 50 || row.rollbackRate >= 30));
  riskyMetrics.slice(0, 6).forEach((row) => {
    candidates.push({
      candidateId: hashId("doqacrrpaapc", ["tighten", row.key || row.label || "", row.falsePositiveRate, row.rollbackRate, row.recurrenceRate].join("|")),
      type: "tighten_operation_alert_rereview_action_auto_policy",
      priority: row.falsePositiveRate >= 50 || row.rollbackRate >= 40 ? "high" : "medium",
      target: row.label,
      issueKey: row.key || row.label,
      rootMetric: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `False positive ${row.falsePositiveRate}%, recurrence ${row.recurrenceRate}%, rollback ${row.rollbackRate}% across ${row.evaluated} evaluated operation-alert re-review auto approvals.`,
      recommendation: "Keep this root metric in manual review or raise sample/effect thresholds before automatic approval."
    });
  });
  const riskyAssignees = (aggregates.byAssignee || []).filter((row) => row.evaluated >= 1 && (row.falsePositiveRate >= 40 || row.rollbackRate >= 30));
  riskyAssignees.slice(0, 4).forEach((row) => {
    candidates.push({
      candidateId: hashId("doqacrrpaapc", ["owner", row.key || row.label || "", row.falsePositiveRate, row.rollbackRate].join("|")),
      type: "tighten_owner_scoped_operation_alert_auto_policy",
      priority: row.falsePositiveRate >= 50 || row.rollbackRate >= 40 ? "high" : "medium",
      target: row.label,
      assignee: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `Owner scope shows false positive ${row.falsePositiveRate}% and rollback ${row.rollbackRate}% across ${row.evaluated} evaluated auto approvals.`,
      recommendation: "Keep owner-scoped auto approval narrow until this assignee scope shows stable post-reassessment results."
    });
  });
  const strongMetrics = (aggregates.byRootMetric || []).filter((row) => row.evaluated >= 3 && row.successRate >= 80 && row.falsePositiveRate === 0 && row.rollbackRate === 0 && row.recurrenceRate < 30);
  strongMetrics.slice(0, 4).forEach((row) => {
    candidates.push({
      candidateId: hashId("doqacrrpaapc", ["relax", row.key || row.label || "", row.successRate, row.evaluated].join("|")),
      type: "consider_relaxing_operation_alert_rereview_action_auto_policy",
      priority: "low",
      target: row.label,
      issueKey: row.key || row.label,
      rootMetric: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `Success ${row.successRate}% with no false positives or rollbacks across ${row.evaluated} evaluated auto approvals.`,
      recommendation: "Consider keeping this root metric eligible for low-risk auto approval while broad scopes remain manual."
    });
  });
  const pendingRate = items.length ? Math.round((items.filter((item) => item.outcome?.outcome === "pending").length / items.length) * 100) : 0;
  if (pendingRate >= 60 && items.length >= 3) {
    const summary = slaAutoApprovalPerformanceSummary(items);
    candidates.push({
      candidateId: hashId("doqacrrpaapc", ["monitoring", pendingRate, items.length].join("|")),
      type: "increase_operation_alert_rereview_auto_approval_monitoring_window",
      priority: "medium",
      target: "pending_operation_alert_rereview_auto_approval_followup",
      issueKey: "pending_operation_alert_rereview_auto_approval_followup",
      metrics: {
        total: items.length,
        evaluated: items.filter((item) => item.outcome?.evaluatedCount > 0).length,
        successRate: summary.successRate,
        falsePositiveRate: summary.falsePositiveRate,
        rollbackRate: summary.rollbackRate,
        recurrenceRate: summary.recurrenceRate,
        pendingRate
      },
      basis: `${pendingRate}% of operation-alert re-review auto approvals still have no linked post-assessment evidence.`,
      recommendation: "Require post-assessment history capture before widening auto-approval coverage."
    });
  }
  return candidates;
}

