async function reviewDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustment(payload = {}) {
  const adjustmentId = String(payload.adjustmentId || payload.id || "").trim();
  const decision = String(payload.decision || "").trim();
  const normalizedDecision = decision === "approve" ? "approved" : decision === "reject" ? "rejected" : decision;
  if (!adjustmentId || !["approved", "rejected"].includes(normalizedDecision)) {
    const error = new Error("Adjustment id and approved/rejected decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAdjustments();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustment)
    : [];
  const target = items.find((item) => item.adjustmentId === adjustmentId);
  if (!target) {
    const error = new Error("Deployment operation re-review action recommendation adjustment not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reviewReason = String(payload.reviewReason || payload.reason || "").trim();
  const updatedTarget = normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustment({
    ...target,
    status: normalizedDecision,
    active: normalizedDecision === "approved",
    approvalMode: "manual",
    approvedPriority: normalizedDecision === "approved" ? target.proposedPriority : "",
    approvedRecommendedAction: normalizedDecision === "approved" ? target.proposedRecommendedAction : "",
    approvedBy: normalizedDecision === "approved" ? reviewer : "",
    approvedAt: normalizedDecision === "approved" ? now : "",
    rejectedBy: normalizedDecision === "rejected" ? reviewer : "",
    rejectedAt: normalizedDecision === "rejected" ? now : "",
    rejectReason: normalizedDecision === "rejected" ? reviewReason : "",
    reviewReason: reviewReason || (normalizedDecision === "approved"
      ? "Admin approved history-based re-review action recommendation correction."
      : "Admin rejected history-based re-review action recommendation correction."),
    updatedAt: now,
    decisionHistory: [
      ...(target.decisionHistory || []),
      {
        decision: normalizedDecision,
        beforeStatus: target.status || "proposed",
        decidedBy: reviewer,
        decidedAt: now,
        reason: reviewReason || ""
      }
    ]
  });
  const saved = await writeDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAdjustments({
    ...data,
    items: items
      .map((item) => item.adjustmentId === adjustmentId ? updatedTarget : item)
      .sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  const [logData, historyData] = await Promise.all([
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAutoApprovalLogs(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionReassessmentHistory()
  ]);
  const workflow = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAdjustmentWorkflow(saved.items || [], payload, logData.items || [], historyData.items || []);
  workflow.autoApprovalPerformance = await deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPerformanceReportFromData(
    saved.items || [],
    historyData.items || [],
    logData.items || [],
    payload
  );
  workflow.autoApprovalPolicy = workflow.autoApprovalPerformance.activePolicy || workflow.autoApprovalPolicy;
  return {
    ok: true,
    decision: normalizedDecision,
    adjustment: updatedTarget,
    workflow,
    reportBoundaries: {
      source: "admin-only deployment operation re-review action recommendation adjustment decision",
      hiddenFromBusiness: ["recommendation adjustment approval", "approval and rejection history", "effect score", "recurrence evidence", "operational quality metrics", "internal formulas"]
    }
  };
}

function mergeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActions(candidates = [], savedActions = []) {
  const savedBySourceKey = new Map(savedActions.map((item) => [
    item.sourceKey,
    normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewAction(item)
  ]));
  const candidateSourceKeys = new Set(candidates.map((item) => item.sourceKey));
  const mergedCandidates = candidates.map((candidate) => {
    const saved = savedBySourceKey.get(candidate.sourceKey);
    return saved
      ? { ...candidate, ...saved, historyAdjustment: saved.historyAdjustment || candidate.historyAdjustment, isSaved: true, candidateStatus: "saved" }
      : { ...candidate, isSaved: false, candidateStatus: "generated" };
  });
  const orphanSaved = savedActions
    .map(normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewAction)
    .filter((item) => item.sourceKey && !candidateSourceKeys.has(item.sourceKey))
    .map((item) => ({ ...item, isSaved: true, candidateStatus: "saved_only" }));
  const levelRank = { danger: 0, warning: 1, normal: 2 };
  const priorityRank = { urgent: 0, high: 1, medium: 2, low: 3 };
  return [...mergedCandidates, ...orphanSaved].sort((a, b) => (
    (levelRank[a.slaLevel] ?? 9) - (levelRank[b.slaLevel] ?? 9) ||
    (priorityRank[a.priority] ?? 9) - (priorityRank[b.priority] ?? 9) ||
    String(a.targetDate || "").localeCompare(String(b.targetDate || "")) ||
    String(a.sourceLabel || "").localeCompare(String(b.sourceLabel || ""))
  ));
}

function enrichDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewAction(action = {}) {
  const normalized = normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewAction(action);
  const dueState = slaPolicyCandidateQualityRereviewActionDueState(normalized);
  const riskLevel = calibrationSlaActionRiskLevel(normalized);
  return {
    ...normalized,
    isSaved: Boolean(action.isSaved),
    candidateStatus: action.candidateStatus || (action.isSaved ? "saved" : "generated"),
    dueState,
    riskLevel,
    isOpen: calibrationSlaActionIsOpen(normalized),
    isOverdue: dueState === "overdue",
    isThisWeek: dueState === "this_week",
    isCompleted: normalized.status === "done"
  };
}

