    sourceType: operationQualityRecommendationAdjustmentParam(params, "actionSourceType"),
    due: operationQualityRecommendationAdjustmentParam(params, "actionDue"),
    targetDate: operationQualityRecommendationAdjustmentParam(params, "actionTargetDate"),
    priority: operationQualityRecommendationAdjustmentParam(params, "actionPriority"),
    risk: operationQualityRecommendationAdjustmentParam(params, "actionRisk"),
    issueKey: operationQualityRecommendationAdjustmentParam(params, "actionIssue"),
