      due: String(operationQualityRecommendationAdjustmentParam(params, "actionDue") || "").trim(),
      targetDate: String(operationQualityRecommendationAdjustmentParam(params, "actionTargetDate") || "").trim(),
      priority: String(operationQualityRecommendationAdjustmentParam(params, "actionPriority") || "").trim(),
