function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionMetricValue(row = {}, key = "") {
  if (!row || typeof row !== "object") return null;
  const fallbackKey = key === "activeLinkIssue" ? "activeLinkUnprocessed" : "";
  const value = Number(row[key]);
  if (Number.isFinite(value)) return value;
  if (fallbackKey) {
    const fallback = Number(row[fallbackKey]);
    if (Number.isFinite(fallback)) return fallback;
  }
  return null;
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewRowWarning(row = {}) {
  const operationWarning = row?.operationWarning || {};
  const sla = row?.sla || {};
  const level = String(row?.warningSeverity || operationWarning.level || sla.level || "normal").trim().toLowerCase() || "normal";
  return {
    level,
    label: row?.warningLabel || operationWarning.label || sla.label || level,
    improvementItems: operationWarning.improvementItems || sla.improvementItems || []
  };
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionBaselineSnapshot(action = {}) {
  const snapshot = action.completionQualitySnapshot || {};
  if (action.sourceType === "owner" && snapshot.owner) return snapshot.owner;
  if (action.sourceType === "month" && snapshot.month) return snapshot.month;
  return snapshot.summary || snapshot.owner || snapshot.month || action.sourceMetrics || {};
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionCurrentSnapshot(action = {}, quality = {}) {
  if (action.sourceType === "owner") {
    const owner = String(action.owner || action.assignee || "").trim();
    const row = (quality.ownerPerformance || []).find((item) => String(item.key || item.label || "").trim() === owner || String(item.label || "").trim() === owner);
    return row || quality.summary || {};
  }
  if (action.sourceType === "month") {
    const month = String(action.month || monthKey(action.targetDate) || "").trim();
    const row = (quality.monthly || []).find((item) => String(item.key || item.label || "").trim() === month || String(item.label || "").trim() === month);
    return row || quality.summary || {};
  }
  return quality.summary || {};
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionCurrentDataMissing(current = {}, metric = {}) {
  return deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionMetricValue(current, metric.key) === null;
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionEffectScore(metric = {}, baselineValue = null, currentValue = null, baselineLevel = "warning", currentLevel = "normal", recurrence = false, currentDataMissing = false) {
  let score = 50;
  if (Number.isFinite(Number(baselineValue)) && Number.isFinite(Number(currentValue))) {
    const metricDelta = Number(currentValue) - Number(baselineValue);
    const improvementAmount = metric.higherIsBetter ? metricDelta : -metricDelta;
    score += clampNumber(improvementAmount * Number(metric.weight || 1), -35, 35);
  } else {
    score -= 8;
  }
  score += (slaPolicyCandidateQualityRereviewSlaLevelScore(currentLevel) - slaPolicyCandidateQualityRereviewSlaLevelScore(baselineLevel)) * 12;
  if (currentDataMissing) score -= 10;
  if (currentLevel === "normal") score += 8;
  if (currentLevel === "danger") score -= 15;
  if (recurrence) score -= 12;
  return Math.round(clampNumber(score, 0, 100));
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionOutcome(metric = {}, baselineValue = null, currentValue = null, currentLevel = "normal", recurrence = false, effectScore = 50, currentDataMissing = false) {
  if (currentDataMissing) return "unchanged";
  let metricWorse = false;
  let metricImproved = false;
  if (Number.isFinite(Number(baselineValue)) && Number.isFinite(Number(currentValue))) {
    const metricDelta = Number(currentValue) - Number(baselineValue);
    const improvementAmount = metric.higherIsBetter ? metricDelta : -metricDelta;
    const tolerance = Math.max(Math.abs(Number(baselineValue)) * 0.05, 0.5);
    metricWorse = improvementAmount < -tolerance;
    metricImproved = improvementAmount > tolerance;
  }
  if ((recurrence && effectScore < 60) || currentLevel === "danger" || effectScore <= 40 || metricWorse) return "worse";
  if ((metricImproved || currentLevel === "normal") && effectScore >= 70 && !recurrence) return "improved";
  return "unchanged";
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionFollowUpText(item = {}) {
  const metricLabel = item.metric?.label || item.rootMetric || item.issueKey || "operation quality";
  if (item.currentDataMissing) return `Refresh the re-review operational quality report and verify ${metricLabel} before closing the cycle.`;
  if (item.outcome === "worse") return `Reopen the ${metricLabel} corrective work, assign a short target date, and inspect the latest re-review logs.`;
  if (item.recurrence) return `Create a targeted follow-up for recurring ${metricLabel} and require owner confirmation before closing.`;
  if (Number(item.effectScore || 0) < 60) return `Run one more quality check for ${metricLabel} and keep the action visible until the score is stable.`;
  return `Keep monitoring ${metricLabel}; no immediate follow-up is required.`;
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentItem(action = {}, quality = {}, followUpAction = null) {
  const baseline = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionBaselineSnapshot(action);
  const current = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionCurrentSnapshot(action, quality);
  const metric = slaPolicyCandidateQualityRereviewActionReassessmentMetric(action);
  const baselineWarning = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewRowWarning(baseline);
  const currentWarning = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewRowWarning(current);
  const baselineValue = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionMetricValue(baseline, metric.key);
  const currentValue = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionMetricValue(current, metric.key);
  const metricDelta = Number.isFinite(Number(baselineValue)) && Number.isFinite(Number(currentValue))
    ? Number((Number(currentValue) - Number(baselineValue)).toFixed(2))
    : null;
  const currentDataMissing = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionCurrentDataMissing(current, metric);
  const sameIssueStillOpen = (currentWarning.improvementItems || []).some((item) => {
    const key = String(item.key || item.rootMetric || item.metric || "").trim();
    return key && [action.issueKey, action.rootMetric, metric.key].some((candidate) => String(candidate || "").trim() === key);
  });
  const metricWorse = metricDelta !== null && (metric.higherIsBetter ? metricDelta < 0 : metricDelta > 0);
  const recurrence = Boolean(sameIssueStillOpen || (metricWorse && ["warning", "danger"].includes(currentWarning.level)));
  const improvementAmount = metricDelta === null ? null : Number((metric.higherIsBetter ? metricDelta : -metricDelta).toFixed(2));
  const effectScore = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionEffectScore(
    metric,
    baselineValue,
    currentValue,
    baselineWarning.level,
    currentWarning.level,
    recurrence,
    currentDataMissing
  );
  const outcome = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionOutcome(
    metric,
    baselineValue,
    currentValue,
    currentWarning.level,
    recurrence,
    effectScore,
    currentDataMissing
  );
  const followUpNeeded = Boolean(currentDataMissing || outcome === "worse" || recurrence || effectScore < 60 || currentWarning.level === "danger");
  const reassessment = {
    reassessmentId: hashId("doqacrrar", [
      action.actionId || "",
      action.completedAt || action.completionQualitySnapshot?.capturedAt || "",
      metric.key,
      baselineValue ?? "",
      currentValue ?? "",
      currentWarning.level
    ].join("|")),
    actionId: action.actionId || "",
    sourceKey: action.sourceKey || "",
    sourceType: action.sourceType || "",
    sourceLabel: action.sourceLabel || "",
    sourceMonth: action.month || monthKey(action.targetDate) || monthKey(action.completedAt) || "",
    scopeType: action.sourceType || "summary",
    scopeKey: action.sourceType === "owner" ? action.owner || action.assignee || "" : action.sourceType === "month" ? action.month || monthKey(action.targetDate) || "" : "summary",
    scopeLabel: action.sourceLabel || action.owner || action.month || "summary",
    owner: action.owner || "",
    assignee: action.assignee || action.owner || "",
    targetDate: action.targetDate || "",
    completedAt: action.completedAt || action.updatedAt || "",
    completedBy: action.completedBy || "",
    evaluatedAt: new Date().toISOString(),
    evaluatedDate: kstDate(0),
    issueKey: action.issueKey || "",
    rootMetric: action.rootMetric || "",
    rootMetricLabel: metric.label || action.rootMetric || action.issueKey || "",
    unit: metric.unit || "",
    baselineGrade: baselineWarning.level,
    baselineGradeLabel: baselineWarning.label,
    currentGrade: currentWarning.level,
    currentGradeLabel: currentWarning.label,
    metric,
    baseline: {
      value: baselineValue,
      warning: baselineWarning,
      row: baseline || {}
    },
    current: {
      value: currentValue,
      warning: currentWarning,
      row: current || {}
    },
    comparison: {
      metricDelta,
      improvementAmount,
      warningLevelDelta: slaPolicyCandidateQualityRereviewSlaLevelScore(currentWarning.level) - slaPolicyCandidateQualityRereviewSlaLevelScore(baselineWarning.level)
    },
    baselineValue,
    currentValue,
    metricDelta,
    effectScore,
    outcome,
    outcomeLabel: ({ improved: "Improved", unchanged: "Stable", worse: "Worse" }[outcome] || "Stable"),
    recurrence,
    currentDataMissing,
    followUpNeeded,
    followUpReason: "",
    suggestedFollowUp: "",
    recommendedFollowUpAction: "",
    followUpCreated: Boolean(followUpAction),
    followUpActionId: followUpAction?.actionId || "",
    followUpActionIds: followUpAction?.actionId ? [followUpAction.actionId] : [],
    followUpActionSourceKey: followUpAction?.sourceKey || "",
    followUpCreatedAt: followUpAction?.createdAt || followUpAction?.updatedAt || "",
    completionQualitySnapshot: action.completionQualitySnapshot || null,
    currentQualitySnapshot: {
      capturedAt: new Date().toISOString(),
      sourceType: action.sourceType || "summary",
      metrics: compactDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewQualitySnapshot(current)
    },
    sourceAction: {
      actionId: action.actionId,
      sourceKey: action.sourceKey,
      sourceType: action.sourceType,
      sourceLabel: action.sourceLabel,
      recommendation: action.recommendation,
      priority: action.priority,
      status: action.status,
      assignee: action.assignee,
      sourceMetrics: action.sourceMetrics || {}
    }
  };
  reassessment.followUpReason = [
    currentDataMissing ? "latest metric is missing" : "",
    outcome === "worse" ? "latest metric is worse than completion snapshot" : "",
    recurrence ? "same root issue still appears in current warning items" : "",
    effectScore < 60 ? "effect score is below follow-up threshold" : "",
    currentWarning.level === "danger" ? "current warning level is risk" : ""
  ].filter(Boolean).join("; ") || "Effect is stable; keep monitoring in the next operation cycle.";
  reassessment.suggestedFollowUp = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionFollowUpText(reassessment);
  reassessment.recommendedFollowUpAction = reassessment.suggestedFollowUp;
  return reassessment;
}

function filterDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessments(items = [], params = {}) {
  const owner = String(operationQualityRecommendationAdjustmentParam(params, "reassessmentOwner") || operationQualityRecommendationAdjustmentParam(params, "assignee") || operationQualityRecommendationAdjustmentParam(params, "owner") || "").trim().toLowerCase();
  const issue = String(operationQualityRecommendationAdjustmentParam(params, "reassessmentIssue") || operationQualityRecommendationAdjustmentParam(params, "issueKey") || operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim().toLowerCase();
  const outcome = String(operationQualityRecommendationAdjustmentParam(params, "reassessmentOutcome") || operationQualityRecommendationAdjustmentParam(params, "outcome") || "").trim().toLowerCase();
  const followUpText = String(operationQualityRecommendationAdjustmentParam(params, "reassessmentFollowUpNeeded") ?? operationQualityRecommendationAdjustmentParam(params, "followUpNeeded") ?? "").trim().toLowerCase();
  const followUpNeeded = ["true", "yes", "needed"].includes(followUpText) ? true : ["false", "no", "none"].includes(followUpText) ? false : null;
  return items
    .filter((item) => !owner || String(item.assignee || item.owner || "unassigned").toLowerCase().includes(owner))
    .filter((item) => !issue || [item.issueKey, item.rootMetric, item.metric?.key, item.metric?.label, item.sourceLabel].some((value) => String(value || "").toLowerCase().includes(issue)))
    .filter((item) => !outcome || item.outcome === outcome)
    .filter((item) => followUpNeeded === null || item.followUpNeeded === followUpNeeded);
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentSummary(items = []) {
  const total = items.length;
  const scoreItems = items.filter((item) => Number.isFinite(Number(item.effectScore)));
  return {
    total,
    avgEffectScore: scoreItems.length ? Math.round(scoreItems.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / scoreItems.length) : 0,
    averageEffectScore: scoreItems.length ? Math.round(scoreItems.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / scoreItems.length) : 0,
    improved: items.filter((item) => item.outcome === "improved").length,
    unchanged: items.filter((item) => item.outcome === "unchanged").length,
    worse: items.filter((item) => item.outcome === "worse").length,
    recurrence: items.filter((item) => item.recurrence).length,
    followUpNeeded: items.filter((item) => item.followUpNeeded).length,
    followUpCreated: items.filter((item) => item.followUpCreated).length,
    currentDataMissing: items.filter((item) => item.currentDataMissing).length,
    byIssue: countByField(items, "issueKey"),
    byOutcome: countByField(items, "outcome"),
    byAssignee: countByField(items, "assignee")
  };
}

