async function upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistoryItems(items = [], options = {}) {
  const normalized = items
    .map((item) => historyItemFromDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessment(item, options))
    .filter((item) => item.actionId && item.historyId);
  if (!normalized.length) {
    return {
      deploymentOperationQualityCandidateQualityRereviewActionReassessmentHistory: null,
      upserted: 0,
      items: []
    };
  }
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionReassessmentHistory();
  const existing = Array.isArray(data.items)
    ? data.items.map(normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistoryItem)
    : [];
  const byId = new Map(existing.map((item) => [item.historyId, item]));
  normalized.forEach((item) => {
    const previous = byId.get(item.historyId);
    const followUpActionIds = [...new Set([
      ...((previous?.followUpActionIds || []).filter(Boolean)),
      ...((item.followUpActionIds || []).filter(Boolean))
    ])];
    byId.set(item.historyId, normalizeDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistoryItem({
      ...(previous || {}),
      ...item,
      firstRecordedAt: previous?.firstRecordedAt || item.firstRecordedAt,
      revisionCount: (previous?.revisionCount || 0) + 1,
      followUpCreated: Boolean(previous?.followUpCreated || item.followUpCreated || followUpActionIds.length),
      followUpActionIds,
      followUpCreatedAt: item.followUpCreatedAt || previous?.followUpCreatedAt || ""
    }));
  });
  const updated = await writeDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionReassessmentHistory({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")))
  });
  return {
    deploymentOperationQualityCandidateQualityRereviewActionReassessmentHistory: {
      schema: updated.schema || "deployment_operation_quality_recommendation_auto_approval_policy_effect_candidate_quality_rereview_action_reassessment_history_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    upserted: normalized.length,
    items: normalized
  };
}

