async function attachDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistory(report = {}, params = new URLSearchParams()) {
  const postReassessment = report.operationalQuality?.improvementActions?.postReassessment;
  if (!postReassessment) return report;
  const persistValue = String(operationQualityRecommendationAdjustmentParam(params, "persistReassessmentHistory") ?? "").trim().toLowerCase();
  const shouldPersist = persistValue !== "false";
  const historyWrite = shouldPersist
    ? await upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistoryItems(postReassessment.items || [], {
      recordedBy: operationQualityRecommendationAdjustmentParam(params, "recordedBy") || "system"
    })
    : { deploymentOperationQualityCandidateQualityRereviewActionReassessmentHistory: null, upserted: 0, items: [] };
  const history = await deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentHistoryReport(params);
  const nextPostReassessment = {
    ...postReassessment,
    historyWrite: historyWrite.deploymentOperationQualityCandidateQualityRereviewActionReassessmentHistory,
    history,
    historySummary: history.summary || {},
    historyAggregates: history.aggregates || {}
  };
  const improvementActions = {
    ...(report.operationalQuality?.improvementActions || {}),
    postReassessment: nextPostReassessment
  };
  return {
    ...report,
    operationalQuality: {
      ...(report.operationalQuality || {}),
      improvementActions,
      slaActions: improvementActions
    }
  };
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentBlock(quality = {}, actions = [], params = {}) {
  const savedActions = actions.filter((item) => item.isSaved);
  const completedActions = savedActions
    .filter((item) => item.status === "done")
    .filter((item) => item.completionQualitySnapshot);
  const items = completedActions.map((action) => {
    const followUp = savedActions.find((item) => (
      (item.parentActionId && item.parentActionId === action.actionId)
      || (item.followUpForActionId && item.followUpForActionId === action.actionId)
    ));
    return deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentItem(action, quality, followUp || null);
  });
  const filtered = filterDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessments(items, params);
  const limit = Math.max(1, Math.min(200, Number(operationQualityRecommendationAdjustmentParam(params, "reassessmentLimit") || operationQualityRecommendationAdjustmentParam(params, "limit") || 80)));
  return {
    summary: deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentSummary(filtered),
    fullSummary: deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentSummary(items),
    filters: {
      owner: String(operationQualityRecommendationAdjustmentParam(params, "reassessmentOwner") || operationQualityRecommendationAdjustmentParam(params, "assignee") || operationQualityRecommendationAdjustmentParam(params, "owner") || "").trim(),
      issue: String(operationQualityRecommendationAdjustmentParam(params, "reassessmentIssue") || operationQualityRecommendationAdjustmentParam(params, "issueKey") || operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim(),
      outcome: String(operationQualityRecommendationAdjustmentParam(params, "reassessmentOutcome") || operationQualityRecommendationAdjustmentParam(params, "outcome") || "").trim(),
      followUpNeeded: String(operationQualityRecommendationAdjustmentParam(params, "reassessmentFollowUpNeeded") ?? operationQualityRecommendationAdjustmentParam(params, "followUpNeeded") ?? "").trim(),
      limit
    },
    items: filtered
      .sort((a, b) => Number(b.followUpNeeded || 0) - Number(a.followUpNeeded || 0)
        || Number(a.effectScore || 0) - Number(b.effectScore || 0)
        || String(b.completedAt || "").localeCompare(String(a.completedAt || "")))
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only deployment operation re-review warning action post-completion reassessment",
      hiddenFromBusiness: ["completion snapshots", "current operation warning metrics", "effect score", "recurrence diagnosis", "follow-up action linkage", "internal formulas"]
    }
  };
}

function deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionReassessmentParams(params = {}) {
  const mapped = new URLSearchParams();
  if (params instanceof URLSearchParams) {
    params.forEach((value, key) => mapped.set(key, value));
  } else {
    Object.entries(params || {}).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== "") mapped.set(key, String(value));
    });
  }
  mapped.set("actionStatus", "done");
  mapped.set("actionIncludeGenerated", "false");
  if (!mapped.get("reassessmentLimit") && mapped.get("limit")) mapped.set("reassessmentLimit", mapped.get("limit"));
  return mapped;
}

