async function deploymentOperationQualityAutoApprovalPolicyEffectsReport(params = new URLSearchParams()) {
  const [policyAdjustmentData, adjustmentData, historyData, logData] = await Promise.all([
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyAdjustments(),
    readDeploymentOperationQualityRecommendationAdjustments(),
    readDeploymentOperationQualityActionReassessmentHistory(),
    readDeploymentOperationQualityRecommendationAutoApprovalLogs()
  ]);
  const historyItems = (historyData.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const logs = (logData.items || []).map(normalizeOperationQualityRecommendationAutoApprovalLog);
  const recommendationItems = (adjustmentData.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const performanceItems = recommendationItems
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible)
    .map((item) => operationQualityRecommendationAutoApprovalPerformanceItem(item, historyItems, logs));
  const activePolicy = activeDeploymentOperationQualityRecommendationAutoApprovalPolicy(policyAdjustmentData.items || []);
  const basePostEffectReport = deploymentOperationQualityAutoApprovalPolicyPostEffectReport(policyAdjustmentData.items || [], performanceItems, recommendationItems, params);
  const candidateQualityBasis = deploymentOperationQualityPostEffectCandidateQualityReport(
    policyAdjustmentData.items || [],
    basePostEffectReport.items || [],
    params
  );
  const report = await attachDeploymentOperationQualityAutoApprovalPolicyPostEffectCandidates(
    basePostEffectReport,
    activePolicy,
    candidateQualityBasis
  );
  const latestPolicyAdjustmentData = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const policyAdjustmentWorkflow = await deploymentOperationQualityAutoApprovalPolicyAdjustmentsReport(params);
  const policyAdjustmentCandidateQuality = deploymentOperationQualityPostEffectCandidateQualityReport(
    latestPolicyAdjustmentData.items || [],
    report.items || [],
    params
  );
  const policyAdjustmentQualityCalibrationPerformance = deploymentOperationQualityPostEffectCandidateQualityCalibrationPerformanceReport(
    report.candidateQualityCalibrationWorkflow?.items || [],
    policyAdjustmentCandidateQuality,
    params
  );
  await upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(policyAdjustmentQualityCalibrationPerformance);
  const [policyAdjustmentQualityCalibrationRereviewData, policyAdjustmentQualityCalibrationRereviewLogData, policyAdjustmentQualityCalibrationRereviewActionData, policyAdjustmentQualityCalibrationRereviewActionHistoryData, policyAdjustmentQualityCalibrationRereviewActionAdjustmentData, policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData] = await Promise.all([
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewLogs(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActions(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionReassessmentHistory(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAdjustments(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAutoApprovalLogs()
  ]);
  let policyAdjustmentQualityCalibrationRereviews = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewReport(
    policyAdjustmentQualityCalibrationRereviewData.items || [],
    params,
    policyAdjustmentQualityCalibrationRereviewLogData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionHistoryData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData.items || []
  );
  const actionRecommendationAutoApprovalPerformance = await deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPerformanceReportFromData(
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionHistoryData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData.items || [],
    params
  );
  const nestedPolicyAdjustmentQualityCalibrationPerformance = actionRecommendationAutoApprovalPerformance.policyAdjustmentQualityCalibrationPerformance || {};
  const nestedGeneratedCandidates = nestedPolicyAdjustmentQualityCalibrationPerformance.reReviewCandidates || [];
  if (nestedGeneratedCandidates.length) {
    await upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(nestedPolicyAdjustmentQualityCalibrationPerformance);
    const refreshedRereviewData = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
    policyAdjustmentQualityCalibrationRereviews = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewReport(
      refreshedRereviewData.items || [],
      params,
      policyAdjustmentQualityCalibrationRereviewLogData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionHistoryData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionAdjustmentData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData.items || []
    );
  }
  const generatedRereviewCandidatesById = new Map();
  [...(policyAdjustmentQualityCalibrationPerformance.reReviewCandidates || []), ...nestedGeneratedCandidates].forEach((candidate) => {
    const rereviewId = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewId(candidate);
    generatedRereviewCandidatesById.set(rereviewId, {
      ...candidate,
      rereviewId
    });
  });
  policyAdjustmentQualityCalibrationRereviews = {
    ...policyAdjustmentQualityCalibrationRereviews,
    generatedCandidates: [...generatedRereviewCandidatesById.values()],
    generatedCandidateSources: {
      directPerformance: (policyAdjustmentQualityCalibrationPerformance.reReviewCandidates || []).length,
      policyAdjustmentQualityCalibration: nestedGeneratedCandidates.length
    },
    performanceSummary: policyAdjustmentQualityCalibrationPerformance.summary || {},
    policyAdjustmentQualityCalibrationPerformanceSummary: nestedPolicyAdjustmentQualityCalibrationPerformance.summary || {}
  };
  if (policyAdjustmentQualityCalibrationRereviews.operationalQuality?.improvementActions?.recommendationAdjustmentWorkflow) {
    policyAdjustmentQualityCalibrationRereviews.operationalQuality.improvementActions.recommendationAdjustmentWorkflow.autoApprovalPerformance = actionRecommendationAutoApprovalPerformance;
    policyAdjustmentQualityCalibrationRereviews.operationalQuality.improvementActions.recommendationAdjustmentWorkflow.autoApprovalPolicy = actionRecommendationAutoApprovalPerformance.activePolicy || policyAdjustmentQualityCalibrationRereviews.operationalQuality.improvementActions.recommendationAdjustmentWorkflow.autoApprovalPolicy;
  }
  return {
    role: "admin",
    ...report,
    policyAdjustmentWorkflow,
    policyAdjustmentCandidateQuality,
    policyAdjustmentQualityCalibrationPerformance,
    policyAdjustmentQualityCalibrationRereviews,
    activePolicy: activeDeploymentOperationQualityRecommendationAutoApprovalPolicy(latestPolicyAdjustmentData.items || [])
  };
}

async function deploymentOperationQualityRecommendationAutoApprovalPerformanceReport(params = new URLSearchParams()) {
  const [adjustmentData, historyData, logData, policyAdjustmentData] = await Promise.all([
    readDeploymentOperationQualityRecommendationAdjustments(),
    readDeploymentOperationQualityActionReassessmentHistory(),
    readDeploymentOperationQualityRecommendationAutoApprovalLogs(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyAdjustments()
  ]);
  const historyItems = (historyData.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const logs = (logData.items || []).map(normalizeOperationQualityRecommendationAutoApprovalLog);
  const recommendationAdjustments = (adjustmentData.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const autoAdjustments = recommendationAdjustments
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible);
  const allItems = autoAdjustments
    .map((item) => operationQualityRecommendationAutoApprovalPerformanceItem(item, historyItems, logs))
    .sort((a, b) => String(b.approvedAt || "").localeCompare(String(a.approvedAt || "")));
  const filtered = filterOperationQualityRecommendationAutoApprovalPerformanceItems(allItems, params);
  const aggregates = {
    byMonth: slaAutoApprovalPerformanceGroups(filtered, (item) => item.approvalMonth || "unknown"),
    byRootMetric: slaAutoApprovalPerformanceGroups(filtered, (item) => item.rootMetric || "unknown", (key, item) => item.rootMetricLabel || key),
    byAssignee: slaAutoApprovalPerformanceGroups(filtered, (item) => item.assignee || "unassigned")
  };
  const limit = Math.max(1, Math.min(500, Number(operationQualityRecommendationAdjustmentParam(params, "limit") || 120)));
  const policyAdjustmentCandidates = deploymentOperationQualityAutoApprovalPolicyAdjustmentCandidates(filtered, aggregates);
  const activePolicy = activeDeploymentOperationQualityRecommendationAutoApprovalPolicy(policyAdjustmentData.items || []);
  const policyAdjustmentProposals = policyAdjustmentCandidates.length
    ? await upsertDeploymentOperationQualityAutoApprovalPolicyAdjustmentProposals(policyAdjustmentCandidates, activePolicy)
    : [];
  let policyAdjustmentWorkflow = await deploymentOperationQualityAutoApprovalPolicyAdjustmentsReport(new URLSearchParams({
    limit: String(limit)
  }));
  let policyAdjustmentPostEffect = deploymentOperationQualityAutoApprovalPolicyPostEffectReport(
    policyAdjustmentData.items || [],
    allItems,
    recommendationAdjustments,
    params
  );
  const candidateQualityBasis = deploymentOperationQualityPostEffectCandidateQualityReport(
    policyAdjustmentData.items || [],
    policyAdjustmentPostEffect.items || [],
    params
  );
  policyAdjustmentPostEffect = await attachDeploymentOperationQualityAutoApprovalPolicyPostEffectCandidates(
    policyAdjustmentPostEffect,
    policyAdjustmentWorkflow.activePolicy || activePolicy,
    candidateQualityBasis
  );
  policyAdjustmentWorkflow = await deploymentOperationQualityAutoApprovalPolicyAdjustmentsReport(new URLSearchParams({
    limit: String(limit)
  }));
  const latestPolicyAdjustmentData = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const policyAdjustmentCandidateQuality = deploymentOperationQualityPostEffectCandidateQualityReport(
    latestPolicyAdjustmentData.items || [],
    policyAdjustmentPostEffect.items || [],
    params
  );
  const policyAdjustmentQualityCalibrationPerformance = deploymentOperationQualityPostEffectCandidateQualityCalibrationPerformanceReport(
    policyAdjustmentPostEffect.candidateQualityCalibrationWorkflow?.items || [],
    policyAdjustmentCandidateQuality,
    params
  );
  await upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(policyAdjustmentQualityCalibrationPerformance);
  const [policyAdjustmentQualityCalibrationRereviewData, policyAdjustmentQualityCalibrationRereviewLogData, policyAdjustmentQualityCalibrationRereviewActionData, policyAdjustmentQualityCalibrationRereviewActionHistoryData, policyAdjustmentQualityCalibrationRereviewActionAdjustmentData, policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData] = await Promise.all([
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewLogs(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActions(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionReassessmentHistory(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAdjustments(),
    readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviewActionRecommendationAutoApprovalLogs()
  ]);
  let policyAdjustmentQualityCalibrationRereviews = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewReport(
    policyAdjustmentQualityCalibrationRereviewData.items || [],
    params,
    policyAdjustmentQualityCalibrationRereviewLogData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionHistoryData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData.items || []
  );
  const actionRecommendationAutoApprovalPerformance = await deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewActionRecommendationAutoApprovalPerformanceReportFromData(
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionHistoryData.items || [],
    policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData.items || [],
    params
  );
  const nestedPolicyAdjustmentQualityCalibrationPerformance = actionRecommendationAutoApprovalPerformance.policyAdjustmentQualityCalibrationPerformance || {};
  const nestedGeneratedCandidates = nestedPolicyAdjustmentQualityCalibrationPerformance.reReviewCandidates || [];
  if (nestedGeneratedCandidates.length) {
    await upsertDeploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewCandidates(nestedPolicyAdjustmentQualityCalibrationPerformance);
    const refreshedRereviewData = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyEffectCandidateQualityRereviews();
    policyAdjustmentQualityCalibrationRereviews = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewReport(
      refreshedRereviewData.items || [],
      params,
      policyAdjustmentQualityCalibrationRereviewLogData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionHistoryData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionAdjustmentData.items || [],
      policyAdjustmentQualityCalibrationRereviewActionAdjustmentLogData.items || []
    );
  }
  const generatedRereviewCandidatesById = new Map();
  [...(policyAdjustmentQualityCalibrationPerformance.reReviewCandidates || []), ...nestedGeneratedCandidates].forEach((candidate) => {
    const rereviewId = deploymentOperationQualityPostEffectCandidateQualityCalibrationRereviewId(candidate);
    generatedRereviewCandidatesById.set(rereviewId, {
      ...candidate,
      rereviewId
    });
  });
  policyAdjustmentQualityCalibrationRereviews = {
    ...policyAdjustmentQualityCalibrationRereviews,
    generatedCandidates: [...generatedRereviewCandidatesById.values()],
    generatedCandidateSources: {
      directPerformance: (policyAdjustmentQualityCalibrationPerformance.reReviewCandidates || []).length,
      policyAdjustmentQualityCalibration: nestedGeneratedCandidates.length
    },
    performanceSummary: policyAdjustmentQualityCalibrationPerformance.summary || {},
    policyAdjustmentQualityCalibrationPerformanceSummary: nestedPolicyAdjustmentQualityCalibrationPerformance.summary || {}
  };
  if (policyAdjustmentQualityCalibrationRereviews.operationalQuality?.improvementActions?.recommendationAdjustmentWorkflow) {
    policyAdjustmentQualityCalibrationRereviews.operationalQuality.improvementActions.recommendationAdjustmentWorkflow.autoApprovalPerformance = actionRecommendationAutoApprovalPerformance;
    policyAdjustmentQualityCalibrationRereviews.operationalQuality.improvementActions.recommendationAdjustmentWorkflow.autoApprovalPolicy = actionRecommendationAutoApprovalPerformance.activePolicy || policyAdjustmentQualityCalibrationRereviews.operationalQuality.improvementActions.recommendationAdjustmentWorkflow.autoApprovalPolicy;
  }
  return {
    role: "admin",
    schema: "deployment_operation_quality_recommendation_auto_approval_performance_v1",
    generatedAt: new Date().toISOString(),
    filters: {
      month: String(operationQualityRecommendationAdjustmentParam(params, "month") || "").trim(),
      assignee: String(operationQualityRecommendationAdjustmentParam(params, "assignee") || "").trim(),
      rootMetric: String(operationQualityRecommendationAdjustmentParam(params, "rootMetric") || "").trim(),
      outcome: String(operationQualityRecommendationAdjustmentParam(params, "outcome") || "").trim(),
      limit
    },
    summary: slaAutoApprovalPerformanceSummary(filtered),
    fullSummary: slaAutoApprovalPerformanceSummary(allItems),
    aggregates,
    policyAdjustmentCandidates,
    policyAdjustmentProposals,
    policyAdjustmentWorkflow,
    policyAdjustmentPostEffect,
    policyAdjustmentCandidateQuality,
    policyAdjustmentQualityCalibrationPerformance,
    policyAdjustmentQualityCalibrationRereviews,
    actionRecommendationAutoApprovalPerformance,
    activePolicy: policyAdjustmentWorkflow.activePolicy || activePolicy,
    items: filtered.slice(0, limit),
    autoApprovalLogs: logs.slice(0, 80),
    reportBoundaries: {
      source: "admin-only deployment operation alert auto approval performance tracking",
      hiddenFromBusiness: ["auto approval performance", "rollback rate", "false positive rate", "recurrence rate", "operation quality metrics", "policy adjustment candidates", "policy candidate quality", "candidate approval success", "policy adjustment workflow", "policy post-effect report", "rollback/additional adjustment suggestions", "approval history", "internal formula", "backup paths", "security/deployment checks"]
    }
  };
}

async function reviewDeploymentOperationQualityAutoApprovalPolicyAdjustment(policyAdjustmentId = "", decision = "", payload = {}) {
  const normalizedDecision = decision === "approved" ? "approve" : decision === "rejected" ? "reject" : decision;
  if (!["approve", "reject"].includes(normalizedDecision)) {
    const error = new Error("Unsupported deployment operation auto approval policy adjustment decision.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readDeploymentOperationQualityRecommendationAutoApprovalPolicyAdjustments();
  const items = (data.items || []).map(normalizeOperationQualityAutoApprovalPolicyAdjustment);
  const index = items.findIndex((item) => item.policyAdjustmentId === policyAdjustmentId);
  if (index < 0) return null;
  const target = items[index];
  if (target.status !== "proposed") {
    const error = new Error("Only proposed deployment operation auto approval policy adjustments can be reviewed.");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.reviewedBy || payload.approvedBy || payload.rejectedBy || payload.updatedBy || "admin").trim() || "admin";
  const reason = String(payload.reason || payload.reviewReason || payload.rejectReason || "").trim();
  const historyEvent = {
    decision: normalizedDecision === "approve" ? "approved" : "rejected",
    beforeStatus: target.status,
    decidedBy: actor,
    decidedAt: now,
    reason: reason || (normalizedDecision === "approve" ? "Approved for deployment operation active policy." : "Rejected after deployment operation policy review.")
  };
  const updated = normalizeOperationQualityAutoApprovalPolicyAdjustment(normalizedDecision === "approve"
    ? {
        ...target,
        status: "approved",
        active: true,
        approvedAt: now,
        approvedBy: actor,
        reviewReason: historyEvent.reason,
        updatedAt: now,
        updatedBy: actor,
        decisionHistory: [...(target.decisionHistory || []), historyEvent]
      }
    : {
        ...target,
        status: "rejected",
        active: false,
        rejectedAt: now,
        rejectedBy: actor,
        rejectReason: historyEvent.reason,
        updatedAt: now,
        updatedBy: actor,
        decisionHistory: [...(target.decisionHistory || []), historyEvent]
      });
  items[index] = updated;
  const saved = await writeDeploymentOperationQualityRecommendationAutoApprovalPolicyAdjustments({
    ...data,
    items: items.sort((a, b) => {
      const statusRank = { proposed: 0, approved: 1, rejected: 2 };
      return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9)
        || String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
    })
  });
  return {
    role: "admin",
    schema: "deployment_operation_quality_auto_approval_policy_adjustment_review_v1",
    generatedAt: now,
    decision: normalizedDecision,
    item: updated,
    summary: operationQualityAutoApprovalPolicyAdjustmentSummary(saved.items || []),
    activePolicy: activeDeploymentOperationQualityRecommendationAutoApprovalPolicy(saved.items || []),
    reportBoundaries: {
      source: "admin-only deployment operation auto approval policy decision",
      hiddenFromBusiness: ["auto approval policy decision", "policy patch", "approval history", "expected impact", "internal formula", "backup paths", "security/deployment checks"]
    }
  };
}

async function decideDeploymentOperationQualityRecommendationAdjustment(adjustmentId = "", decision = "", payload = {}) {
  const normalizedDecision = decision === "approve" ? "approved" : decision === "reject" ? "rejected" : decision;
  if (!adjustmentId || !["approved", "rejected"].includes(normalizedDecision)) {
    const error = new Error("Adjustment id and approved/rejected decision are required.");
    error.status = 400;
    throw error;
  }
  const data = await readDeploymentOperationQualityRecommendationAdjustments();
  const items = (data.items || []).map(normalizeOperationQualityRecommendationAdjustment);
  const target = items.find((item) => item.adjustmentId === adjustmentId);
  if (!target) return null;
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reason = String(payload.reviewReason || payload.reason || "").trim();
  const updatedTarget = normalizeOperationQualityRecommendationAdjustment({
    ...target,
    status: normalizedDecision,
    active: normalizedDecision === "approved",
    approvalMode: "manual",
    approvedPriority: normalizedDecision === "approved" ? target.proposedPriority : "",
    approvedRecommendedAction: normalizedDecision === "approved" ? target.proposedRecommendedAction : "",
    approvedBy: normalizedDecision === "approved" ? reviewer : "",
    approvedAt: normalizedDecision === "approved" ? now : "",
    rejectedBy: normalizedDecision === "rejected" ? reviewer : "",
    rejectedAt: normalizedDecision === "rejected" ? now : "",
    rejectReason: normalizedDecision === "rejected" ? reason : "",
    reviewReason: reason || (normalizedDecision === "approved" ? "Admin approved history-based recommendation correction." : "Admin rejected history-based recommendation correction."),
    updatedAt: now,
    decisionHistory: [
      ...(target.decisionHistory || []),
      {
        decision: normalizedDecision,
        decidedBy: reviewer,
        decidedAt: now,
        reason: reason || ""
      }
    ]
  });
  const updatedItems = items.map((item) => item.adjustmentId === adjustmentId ? updatedTarget : item);
  const updated = await writeDeploymentOperationQualityRecommendationAdjustments({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    item: updatedTarget,
    counts: {
      deploymentOperationQualityRecommendationAdjustments: updated.items.length
    }
  };
}

async function updateDeploymentOperationQualityAction(actionId = "", payload = {}) {
  const sourceFilters = payload.sourceQualityFilters || {};
  const params = new URLSearchParams();
  if (sourceFilters.month || payload.sourceMonth) params.set("month", sourceFilters.month || payload.sourceMonth);
  const current = await deploymentOperationQualityActions(params);
  const currentItem = (current.items || []).find((item) => item.actionId === actionId);
  if (!currentItem) return null;
  const saved = await readDeploymentOperationQualityActions();
  const items = saved.items || [];
  const index = items.findIndex((item) => item.actionId === actionId);
  const existing = index >= 0 ? items[index] : {};
  const previousStatus = normalizeOperationQualityActionStatus(existing.status || currentItem.status);
  const status = normalizeOperationQualityActionStatus(payload.status || existing.status || currentItem.status || "saved");
  const now = new Date().toISOString();
  const activeHistoryAdjustment = currentItem.historyPriorityAdjustment?.active ? currentItem.historyPriorityAdjustment : null;
  const updated = {
    ...currentItem,
    ...existing,
    status: status === "candidate" ? "saved" : status,
    originalPriority: activeHistoryAdjustment ? currentItem.originalPriority : existing.originalPriority || currentItem.originalPriority || "",
    priority: activeHistoryAdjustment ? currentItem.priority : existing.priority || currentItem.priority || "",
    priorityAdjusted: activeHistoryAdjustment ? Boolean(currentItem.priorityAdjusted) : Boolean(existing.priorityAdjusted || currentItem.priorityAdjusted),
    historyPriorityAdjustment: activeHistoryAdjustment || existing.historyPriorityAdjustment || currentItem.historyPriorityAdjustment || null,
    recommendationCorrectionBasis: activeHistoryAdjustment
      ? currentItem.recommendationCorrectionBasis || activeHistoryAdjustment.recommendationCorrectionBasis || ""
      : existing.recommendationCorrectionBasis || currentItem.recommendationCorrectionBasis || "",
    recommendedAction: activeHistoryAdjustment
      ? currentItem.recommendedAction || activeHistoryAdjustment.recommendationCorrectionBasis || existing.recommendedAction || ""
      : existing.recommendedAction || currentItem.recommendedAction || "",
    assignee: String(payload.assignee ?? existing.assignee ?? currentItem.assignee ?? "").trim(),
    dueDate: String(payload.dueDate ?? existing.dueDate ?? currentItem.dueDate ?? "").trim(),
    memo: String(payload.memo ?? existing.memo ?? currentItem.memo ?? "").trim(),
    updatedBy: String(payload.updatedBy || existing.updatedBy || "admin").trim(),
    updatedAt: now,
    savedAt: existing.savedAt || now,
    completedAt: status === "done" ? (existing.completedAt || now) : existing.completedAt || null,
    completionQualitySnapshot: status === "done" && previousStatus !== "done"
      ? {
          capturedAt: now,
          filters: current.filters || {},
          sourceQualityFilters: currentItem.sourceQualityFilters || {},
          summary: current.sourceQuality?.summary || {},
          warningSummary: current.sourceQuality?.warningSummary || {},
          criteria: current.sourceQuality?.criteria || {},
          operationStandards: current.sourceQuality?.operationStandards || [],
          operationalQueue: current.operationalQueue || {},
          actionSourceSnapshot: currentItem.sourceSnapshot || {}
        }
      : existing.completionQualitySnapshot || null
  };
  if (index >= 0) items[index] = updated;
  else items.push(updated);
  const next = await writeDeploymentOperationQualityActions({
    ...saved,
    items: items.sort((a, b) => String(b.updatedAt || b.generatedAt || "").localeCompare(String(a.updatedAt || a.generatedAt || "")))
  });
  return {
    item: updated,
    counts: {
      deploymentOperationQualityActions: next.items.length
    }
  };
}

function deploymentOperationQualityActionMetricDefinition(metric = "") {
  return DEPLOYMENT_OPERATION_ALERT_QUALITY_CRITERIA[metric] || {
    label: metric || "unknown",
    warning: null,
    danger: null,
    unit: "",
    lowerIsBetter: true
  };
}

function deploymentOperationQualityActionMetricValue(source = {}, metric = "") {
  const direct = Number(source?.[metric]);
  return Number.isFinite(direct) ? direct : null;
}

function deploymentOperationQualityActionReassessmentCurrentRow(quality = {}, action = {}) {
  const scopeType = String(action.scopeType || "").trim();
  if (scopeType === "assignee") {
    const scopeKey = String(action.scopeKey || action.assignee || "").trim();
    const scopeLabel = String(action.scopeLabel || "").trim();
    const row = (quality.byAssignee || []).find((item) => (
      String(item.key || "").trim() === scopeKey
      || String(item.label || "").trim() === scopeLabel
      || String(item.key || "").trim() === String(action.assignee || "").trim()
    ));
    if (row) return row;
  }
  if (scopeType === "monthly") {
    const sourceMonth = String(action.sourceMonth || quality.filters?.month || "").trim();
    const row = (quality.monthly || []).find((item) => String(item.key || "").trim() === sourceMonth);
    if (row) return row;
  }
  return quality.summary || {};
}

function deploymentOperationQualityActionEffectScore(metric = "", beforeValue = null, currentValue = null, currentGrade = "normal", recurrence = false, currentDataMissing = false) {
  const definition = deploymentOperationQualityActionMetricDefinition(metric);
  let score = 50;
  if (currentDataMissing) score -= 10;
  if (Number.isFinite(Number(beforeValue)) && Number.isFinite(Number(currentValue))) {
    const before = Number(beforeValue);
    const current = Number(currentValue);
    const improvement = definition.lowerIsBetter === false ? current - before : before - current;
    const scaleBase = Math.max(
      Math.abs(before),
      Math.abs(current),
      Math.abs(Number(definition.warning || 0)),
      Math.abs(Number(definition.danger || 0)),
      1
    );
    score += clampNumber((improvement / scaleBase) * 50, -35, 35);
  }
  if (currentGrade === "normal") score += 15;
  if (currentGrade === "warning") score -= 5;
  if (currentGrade === "danger") score -= 20;
  if (recurrence) score -= 15;
  return Math.round(clampNumber(score, 0, 100));
}

function deploymentOperationQualityActionImprovementState(metric = "", beforeValue = null, currentValue = null) {
  if (!Number.isFinite(Number(beforeValue)) || !Number.isFinite(Number(currentValue))) return "unknown";
  const definition = deploymentOperationQualityActionMetricDefinition(metric);
  const before = Number(beforeValue);
  const current = Number(currentValue);
  const delta = definition.lowerIsBetter === false ? current - before : before - current;
  const tolerance = Math.max(Math.abs(before) * 0.05, 1);
  if (delta > tolerance) return "improved";
  if (delta < -tolerance) return "worse";
  return "unchanged";
}

function deploymentOperationQualityActionReassessmentOutcome(metric = "", beforeValue = null, currentValue = null, currentGrade = "normal", recurrence = false, effectScore = 50, currentDataMissing = false) {
  if (currentDataMissing) return "unchanged";
  const state = deploymentOperationQualityActionImprovementState(metric, beforeValue, currentValue);
  if ((recurrence && effectScore < 60) || currentGrade === "danger" || effectScore <= 40 || state === "worse") return "worse";
  if (state === "improved" && effectScore >= 60 && !recurrence) return "improved";
  if (currentGrade === "normal" && effectScore >= 70 && !recurrence) return "improved";
  return "unchanged";
}

function deploymentOperationQualityActionReassessmentReason(reassessment = {}) {
  if (reassessment.currentDataMissing) return "Latest response quality data is not available after completion, so this action needs another check.";
  if (reassessment.recurrence) return "The same root metric is still in watch/risk range after the completed action.";
  if (reassessment.outcome === "worse") return "Latest response quality is worse than the completion snapshot.";
  if (reassessment.outcome === "improved") return "Latest response quality improved compared with the completion snapshot.";
  return "The result is stable, but the next operation quality cycle should keep monitoring this action.";
}

function deploymentOperationQualityActionRecommendedFollowUp(reassessment = {}) {
  if (reassessment.currentDataMissing) return "Refresh the operation alert quality report, then reassign the action if the metric is still missing.";
  if (reassessment.recurrence) return "Create a follow-up owner task, confirm the recurring root cause, and set a shorter due date.";
  if (reassessment.outcome === "worse") return "Escalate this action, review the latest alert history, and reset the target owner/date.";
  if (Number(reassessment.effectScore || 0) < 60) return "Run one more quality check and keep the action visible until the effect score is stable.";
  return "No extra action is required now. Keep it visible in the next monthly quality review.";
}

function deploymentOperationQualityActionReassessmentItem(action = {}, quality = {}, followUpActionIds = []) {
  const metric = String(action.rootMetric || "").trim();
  const definition = deploymentOperationQualityActionMetricDefinition(metric);
  const currentRow = deploymentOperationQualityActionReassessmentCurrentRow(quality, action);
  const baselineSnapshot = action.completionQualitySnapshot?.actionSourceSnapshot || action.sourceSnapshot || {};
  const baselineValue = deploymentOperationQualityActionMetricValue(baselineSnapshot, metric)
    ?? deploymentOperationQualityActionMetricValue(action, "rootMetricValue");
  const currentValue = deploymentOperationQualityActionMetricValue(currentRow, metric);
  const currentDataMissing = currentValue === null;
  const activeIssue = (currentRow.warningIssues || []).find((issue) => String(issue.field || "").trim() === metric);
  const recurrence = Boolean(activeIssue && ["warning", "danger"].includes(activeIssue.level));
  const currentGrade = currentRow.healthGrade || quality.summary?.healthGrade || "normal";
  const baselineGrade = action.completionQualitySnapshot?.summary?.healthGrade || action.riskLevel || "warning";
  const effectScore = deploymentOperationQualityActionEffectScore(metric, baselineValue, currentValue, currentGrade, recurrence, currentDataMissing);
  const outcome = deploymentOperationQualityActionReassessmentOutcome(metric, baselineValue, currentValue, currentGrade, recurrence, effectScore, currentDataMissing);
  const metricDelta = Number.isFinite(Number(baselineValue)) && Number.isFinite(Number(currentValue))
    ? Number((Number(currentValue) - Number(baselineValue)).toFixed(2))
    : null;
  const followUpNeeded = Boolean(currentDataMissing || recurrence || outcome === "worse" || effectScore < 60 || currentGrade === "danger");
  const reassessment = {
    actionId: action.actionId,
    title: action.title || "",
    sourceActionId: action.sourceActionId || "",
    sourceMonth: action.sourceMonth || quality.filters?.month || "",
    scopeType: action.scopeType || "",
    scopeKey: action.scopeKey || "",
    scopeLabel: action.scopeLabel || "",
    assignee: action.assignee || "",
    completedAt: action.completedAt || action.updatedAt || "",
    evaluatedAt: new Date().toISOString(),
    rootMetric: metric,
    rootMetricLabel: action.rootMetricLabel || definition.label || metric,
    unit: definition.unit || "",
    baselineValue,
    currentValue,
    metricDelta,
    baselineGrade,
    baselineGradeLabel: deploymentOperationAlertQualityGradeLabel(baselineGrade),
    currentGrade,
    currentGradeLabel: deploymentOperationAlertQualityGradeLabel(currentGrade),
    effectScore,
    outcome,
    outcomeLabel: ({ improved: "Improved", unchanged: "Stable", worse: "Worse" }[outcome] || "Stable"),
    recurrence,
    currentDataMissing,
    followUpNeeded,
    followUpReason: "",
    recommendedFollowUpAction: "",
    followUpCreated: followUpActionIds.length > 0,
    followUpActionIds,
    completionQualitySnapshot: action.completionQualitySnapshot || null,
    baselineSnapshot,
    currentQualitySnapshot: {
      capturedAt: quality.generatedAt || new Date().toISOString(),
      filters: quality.filters || {},
      metrics: currentRow,
      activeIssue: activeIssue || null
    },
    sourceQualityFilters: quality.filters || {},
    sourceAction: action
  };
  reassessment.followUpReason = deploymentOperationQualityActionReassessmentReason(reassessment);
  reassessment.recommendedFollowUpAction = deploymentOperationQualityActionRecommendedFollowUp(reassessment);
  return reassessment;
}

function normalizeDeploymentOperationQualityActionReassessmentFilters(params = new URLSearchParams(), qualityFilters = {}) {
  const limit = Math.max(1, Math.min(200, Number(params.get("limit") || 80)));
  return {
    month: qualityFilters.month || "",
    outcome: String(params.get("outcome") || "").trim(),
    followUp: String(params.get("followUp") || "").trim(),
    assignee: compactKeyword(params.get("assignee") || ""),
    riskLevel: String(params.get("riskLevel") || "").trim(),
    rootMetric: String(params.get("rootMetric") || "").trim(),
    scopeType: String(params.get("scopeType") || "").trim(),
    limit
  };
}

function filterDeploymentOperationQualityActionReassessmentItems(items = [], filters = {}) {
  return items
    .filter((item) => !filters.outcome || item.outcome === filters.outcome)
    .filter((item) => filters.followUp === "needed" ? item.followUpNeeded : filters.followUp === "none" ? !item.followUpNeeded : true)
    .filter((item) => !filters.assignee || compactKeyword(item.assignee || "unassigned").includes(filters.assignee))
    .filter((item) => !filters.riskLevel || item.currentGrade === filters.riskLevel || item.baselineGrade === filters.riskLevel)
    .filter((item) => !filters.rootMetric || item.rootMetric === filters.rootMetric)
    .filter((item) => !filters.scopeType || item.scopeType === filters.scopeType);
}

function deploymentOperationQualityActionReassessmentSummary(items = []) {
  const total = items.length;
  const scoreItems = items.filter((item) => Number.isFinite(Number(item.effectScore)));
  return {
    total,
    improved: items.filter((item) => item.outcome === "improved").length,
    unchanged: items.filter((item) => item.outcome === "unchanged").length,
    worse: items.filter((item) => item.outcome === "worse").length,
    recurrence: items.filter((item) => item.recurrence).length,
    followUpNeeded: items.filter((item) => item.followUpNeeded).length,
    followUpCreated: items.filter((item) => item.followUpCreated).length,
    currentDataMissing: items.filter((item) => item.currentDataMissing).length,
    averageEffectScore: scoreItems.length
      ? Math.round(scoreItems.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / scoreItems.length)
      : 0
  };
}

function deploymentOperationQualityActionReassessmentHistoryId(item = {}) {
  return hashId("doqrh", [
    item.actionId || "",
    item.sourceMonth || item.evaluatedMonth || "",
    item.rootMetric || "",
    item.completedAt || ""
  ].join("|"));
}

function historyItemFromDeploymentOperationQualityReassessment(item = {}, options = {}) {
  const followUpAction = options.followUpAction || null;
  return normalizeOperationQualityActionReassessmentHistoryItem({
    ...item,
    historyId: item.historyId || deploymentOperationQualityActionReassessmentHistoryId(item),
    connectorId: "",
    followUpCreated: Boolean(item.followUpCreated || followUpAction || options.followUpCreated),
    followUpActionIds: [
      ...((item.followUpActionIds || []).filter(Boolean)),
      followUpAction?.actionId || options.followUpActionId || ""
    ].filter(Boolean),
    followUpCreatedAt: followUpAction?.updatedAt || followUpAction?.savedAt || followUpAction?.generatedAt || options.followUpCreatedAt || item.followUpCreatedAt || "",
    recordedBy: options.recordedBy || "system"
  });
}

async function upsertDeploymentOperationQualityActionReassessmentHistoryItems(items = [], options = {}) {
  const normalized = items
    .map((item) => historyItemFromDeploymentOperationQualityReassessment(item, options))
    .filter((item) => item.actionId && item.historyId);
  if (!normalized.length) {
    return {
      deploymentOperationQualityActionReassessmentHistory: null,
      upserted: 0,
      items: []
    };
  }
  const data = await readDeploymentOperationQualityActionReassessmentHistory();
  const existing = Array.isArray(data.items)
    ? data.items.map(normalizeOperationQualityActionReassessmentHistoryItem)
    : [];
  const byId = new Map(existing.map((item) => [item.historyId, item]));
  normalized.forEach((item) => {
    const previous = byId.get(item.historyId);
    const followUpActionIds = [...new Set([
      ...((previous?.followUpActionIds || []).filter(Boolean)),
      ...((item.followUpActionIds || []).filter(Boolean))
    ])];
    byId.set(item.historyId, normalizeOperationQualityActionReassessmentHistoryItem({
      ...(previous || {}),
      ...item,
      historyId: item.historyId,
      connectorId: "",
      firstRecordedAt: previous?.firstRecordedAt || item.firstRecordedAt,
      revisionCount: (previous?.revisionCount || 0) + 1,
      followUpCreated: Boolean(previous?.followUpCreated || item.followUpCreated || followUpActionIds.length),
      followUpActionIds,
      followUpCreatedAt: item.followUpCreatedAt || previous?.followUpCreatedAt || ""
    }));
  });
  const updated = await writeDeploymentOperationQualityActionReassessmentHistory({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")))
  });
  return {
    deploymentOperationQualityActionReassessmentHistory: {
      schema: updated.schema || "deployment_operation_quality_action_reassessment_history_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    upserted: normalized.length,
    items: normalized
  };
}

async function markDeploymentOperationQualityActionReassessmentHistoryFollowUp(sourceItem = {}, followUpAction = {}, recordedBy = "admin") {
  const upsert = await upsertDeploymentOperationQualityActionReassessmentHistoryItems([sourceItem], {
    followUpAction,
    recordedBy,
    followUpCreated: true
  });
  return {
    deploymentOperationQualityActionReassessmentHistory: upsert.deploymentOperationQualityActionReassessmentHistory,
    updated: upsert.upserted,
    item: upsert.items?.[0] || null
  };
}

async function deploymentOperationQualityActionReassessmentHistoryReport(params = new URLSearchParams()) {
  const data = await readDeploymentOperationQualityActionReassessmentHistory();
  const allItems = (data.items || []).map(normalizeOperationQualityActionReassessmentHistoryItem);
  const filtered = filterOperationQualityActionReassessmentHistoryItems(allItems, params);
  const limit = Math.max(1, Math.min(300, Number(operationQualityActionReassessmentHistoryParam(params, "limit") || 120)));
  return {
    role: "admin",
    schema: "deployment_operation_quality_action_reassessment_history_v1",
    generatedAt: new Date().toISOString(),
    filters: {
      month: String(operationQualityActionReassessmentHistoryParam(params, "month") || "").trim(),
      assignee: String(operationQualityActionReassessmentHistoryParam(params, "assignee") || "").trim(),
      rootMetric: String(operationQualityActionReassessmentHistoryParam(params, "rootMetric") || "").trim(),
      outcome: String(operationQualityActionReassessmentHistoryParam(params, "outcome") || "").trim(),
      followUp: String(operationQualityActionReassessmentHistoryParam(params, "followUp") || "").trim(),
      limit
    },
    summary: deploymentOperationQualityActionReassessmentSummary(filtered),
    fullSummary: deploymentOperationQualityActionReassessmentSummary(allItems),
    aggregates: operationQualityActionReassessmentHistoryAggregates(filtered),
    items: filtered
      .sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")))
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only deployment operation response quality action reassessment history",
      hiddenFromBusiness: ["operation alert history", "response quality metrics history", "improvement action reassessment history", "effect score history", "recurrence history", "follow-up creation history", "internal logs", "backup paths", "security and deployment checks", "internal formula"]
    }
  };
}

async function deploymentOperationQualityActionReassessment(params = new URLSearchParams()) {
  const [quality, saved] = await Promise.all([
    deploymentOperationAlertQuality(params),
    readDeploymentOperationQualityActions()
  ]);
  const followUpBySourceId = new Map();
  for (const item of saved.items || []) {
    if (item.sourceType !== "deployment_operation_quality_follow_up" || !item.sourceActionId) continue;
    if (!followUpBySourceId.has(item.sourceActionId)) followUpBySourceId.set(item.sourceActionId, []);
    followUpBySourceId.get(item.sourceActionId).push(item.actionId);
  }
  const completed = (saved.items || [])
    .filter((item) => item.sourceType !== "deployment_operation_quality_follow_up")
    .filter((item) => normalizeOperationQualityActionStatus(item.status) === "done" && item.completionQualitySnapshot)
    .filter((item) => deploymentOperationQualityActionMatchesFilters(item, quality.filters || {}));
  const allItems = completed.map((item) => deploymentOperationQualityActionReassessmentItem(item, quality, followUpBySourceId.get(item.actionId) || []));
  const filters = normalizeDeploymentOperationQualityActionReassessmentFilters(params, quality.filters || {});
  const filtered = filterDeploymentOperationQualityActionReassessmentItems(allItems, filters)
    .sort((a, b) => Number(b.followUpNeeded || 0) - Number(a.followUpNeeded || 0)
      || Number(a.effectScore || 0) - Number(b.effectScore || 0)
      || String(b.completedAt || "").localeCompare(String(a.completedAt || "")));
  const persistValue = params.get("persist");
  const shouldPersist = persistValue === null || String(persistValue).trim().toLowerCase() !== "false";
  const historyWrite = shouldPersist
    ? await upsertDeploymentOperationQualityActionReassessmentHistoryItems(allItems, { recordedBy: "system" })
    : null;
  return {
    role: "admin",
    schema: "deployment_operation_quality_action_reassessment_v1",
    generatedAt: new Date().toISOString(),
    filters,
    summary: deploymentOperationQualityActionReassessmentSummary(filtered),
    fullSummary: deploymentOperationQualityActionReassessmentSummary(allItems),
    historyWrite: historyWrite?.deploymentOperationQualityActionReassessmentHistory || null,
    sourceQuality: {
      summary: quality.summary,
      criteria: quality.criteria,
      warningSummary: quality.warningSummary
    },
    items: filtered.slice(0, filters.limit),
    reportBoundaries: {
      source: "admin-only deployment operation response quality action post-completion reassessment",
      hiddenFromBusiness: ["operation alerts", "change logs", "response quality metrics", "warning grades", "improvement actions", "post-completion reassessment", "completion snapshots", "internal readiness diagnostics", "backup paths", "security and deployment checks", "internal formulas"]
    }
  };
}

async function createDeploymentOperationQualityActionFollowUp(actionId = "", payload = {}) {
  const sourceFilters = payload.sourceQualityFilters || {};
  const params = new URLSearchParams();
  if (sourceFilters.month || payload.sourceMonth) params.set("month", sourceFilters.month || payload.sourceMonth);
  const report = await deploymentOperationQualityActionReassessment(params);
  const reassessment = (report.items || []).find((item) => item.actionId === actionId);
  if (!reassessment) return null;
  if (!reassessment.followUpNeeded) {
    const error = new Error("This completed deployment operation quality action does not require a follow-up.");
    error.statusCode = 400;
    throw error;
  }
  const saved = await readDeploymentOperationQualityActions();
  const items = saved.items || [];
  const existing = items.find((item) => (
    item.sourceType === "deployment_operation_quality_follow_up"
    && item.sourceActionId === actionId
    && normalizeOperationQualityActionStatus(item.status) !== "dismissed"
  ));
  if (existing) {
    const historyUpdate = await markDeploymentOperationQualityActionReassessmentHistoryFollowUp(
      reassessment,
      existing,
      payload.updatedBy || payload.createdBy || "admin"
    );
    return {
      item: existing,
      reassessment: {
        ...reassessment,
        followUpCreated: true,
        followUpActionIds: [...new Set([...(reassessment.followUpActionIds || []), existing.actionId].filter(Boolean))]
      },
      created: false,
      deploymentOperationQualityActionReassessmentHistory: historyUpdate.deploymentOperationQualityActionReassessmentHistory,
      counts: {
        deploymentOperationQualityActions: items.length
      }
    };
  }
  const now = new Date().toISOString();
  const riskLevel = reassessment.outcome === "worse" || reassessment.recurrence ? "danger" : "warning";
  const status = normalizeOperationQualityActionStatus(payload.status || "saved");
  const action = {
    actionId: hashId("doqfu", [actionId, reassessment.rootMetric, reassessment.sourceMonth, "followup"].join("|")),
    status: status === "candidate" ? "saved" : status,
    sourceType: "deployment_operation_quality_follow_up",
    sourceActionId: actionId,
    sourceReassessmentId: hashId("doqrea", [actionId, reassessment.evaluatedAt, reassessment.effectScore].join("|")),
    sourceMonth: reassessment.sourceMonth,
    scopeType: reassessment.scopeType,
    scopeKey: reassessment.scopeKey,
    scopeLabel: reassessment.scopeLabel,
    title: `Follow-up · ${reassessment.title || reassessment.rootMetricLabel || "Operation quality"}`,
    description: reassessment.followUpReason || "",
    rootMetric: reassessment.rootMetric,
    rootMetricLabel: reassessment.rootMetricLabel,
    rootMetricValue: reassessment.currentValue,
    riskLevel,
    riskLabel: deploymentOperationAlertQualityGradeLabel(riskLevel),
    priority: operationQualityActionPriority(riskLevel),
    recommendedAction: String(payload.recommendedAction || payload.recommendation || reassessment.recommendedFollowUpAction || "").trim(),
    assignee: String(payload.assignee || reassessment.assignee || "").trim(),
    dueDate: String(payload.dueDate || operationQualityActionDueDate(riskLevel)).trim(),
    memo: String(payload.memo || reassessment.followUpReason || "").trim(),
    sourceSnapshot: {
      ...(reassessment.currentQualitySnapshot?.metrics || {}),
      effectScore: reassessment.effectScore,
      recurrence: reassessment.recurrence ? 1 : 0,
      followUpNeeded: reassessment.followUpNeeded ? 1 : 0
    },
    sourceQualityFilters: report.filters || {},
    reassessmentSummary: {
      outcome: reassessment.outcome,
      effectScore: reassessment.effectScore,
      recurrence: reassessment.recurrence,
      followUpNeeded: reassessment.followUpNeeded,
      baselineValue: reassessment.baselineValue,
      currentValue: reassessment.currentValue,
      metricDelta: reassessment.metricDelta
    },
    generatedAt: now,
    savedAt: now,
    updatedAt: now,
    updatedBy: String(payload.updatedBy || payload.createdBy || "admin").trim()
  };
  items.push(action);
  const next = await writeDeploymentOperationQualityActions({
    ...saved,
    items: items.sort((a, b) => String(b.updatedAt || b.generatedAt || "").localeCompare(String(a.updatedAt || a.generatedAt || "")))
  });
  const historyUpdate = await markDeploymentOperationQualityActionReassessmentHistoryFollowUp(
    reassessment,
    action,
    payload.updatedBy || payload.createdBy || "admin"
  );
  return {
    item: action,
    reassessment: {
      ...reassessment,
      followUpCreated: true,
      followUpActionIds: [action.actionId]
    },
    created: true,
    deploymentOperationQualityActionReassessmentHistory: historyUpdate.deploymentOperationQualityActionReassessmentHistory,
    counts: {
      deploymentOperationQualityActions: next.items.length
    }
  };
}

async function deploymentOperationAlertQueue(params = new URLSearchParams()) {
  const [smoke, backup, security, deployment, saved, logsData] = await Promise.all([
    deploymentSmokeTestReport(new URLSearchParams({ limit: "20" })),
    backupRestoreReadinessReport(),
    securityReadinessReport(),
    deploymentReadinessReport(),
    readDeploymentOperationAlertQueue(),
    readDeploymentOperationAlertLogs()
  ]);
  const candidates = [
    ...deploymentOperationAlertCandidatesFromSmoke(smoke),
    ...deploymentOperationAlertCandidatesFromActionItems(backup, "backup_restore_readiness", "backup_restore_unready", false, "#backupRestorePanel"),
    ...deploymentOperationAlertCandidatesFromActionItems(security, "security_readiness", "security_blocked", true, "#securityReadinessPanel"),
    ...deploymentOperationAlertCandidatesFromActionItems(deployment, "deployment_readiness", "deployment_blocked", true, "#deploymentReadinessPanel")
  ];
  const merged = mergeDeploymentOperationAlertQueue(candidates, saved.items || []);
  await writeDeploymentOperationAlertQueue({ ...saved, items: merged });
  const filtered = attachDeploymentOperationAlertLogs(filterDeploymentOperationAlertQueueItems(merged, params), logsData.items || []);
  return {
    role: "admin",
    schema: "deployment_operation_alert_queue_v1",
    generatedAt: new Date().toISOString(),
    sourceSummary: {
      latestSmokeRunId: smoke.latestRun?.runId || "",
      latestSmokeStatus: smoke.latestRun?.status || "",
      backupReadiness: backup.summary?.readiness || "",
      securityReadiness: security.summary?.readiness || "",
      deploymentReadiness: deployment.summary?.readiness || ""
    },
    summary: deploymentOperationAlertQueueSummary(merged),
    filters: Object.fromEntries(params.entries()),
    items: filtered
  };
}

async function updateDeploymentOperationAlertQueueItem(alertId = "", payload = {}) {
  const currentQueue = await deploymentOperationAlertQueue(new URLSearchParams({ limit: "500" }));
  const currentItem = (currentQueue.items || []).find((item) => item.alertId === alertId);
  if (!currentItem) return null;
  const data = await readDeploymentOperationAlertQueue();
  const items = data.items || [];
  const index = items.findIndex((item) => item.alertId === alertId);
  const existing = index >= 0 ? items[index] : {};
  const beforeItem = sanitizeDeploymentOperationAlertQueueItem({
    ...currentItem,
    ...existing,
    status: normalizeDeploymentAlertStatus(existing.status || currentItem.status),
    priority: normalizeDeploymentAlertPriority(existing.priority || currentItem.priority),
    assignee: String(existing.assignee ?? currentItem.assignee ?? "").trim(),
    dueDate: String(existing.dueDate ?? currentItem.dueDate ?? "").trim(),
    memo: String(existing.memo ?? currentItem.memo ?? "").trim()
  });
  const status = normalizeDeploymentAlertStatus(payload.status || existing.status || currentItem.status);
  const now = new Date().toISOString();
  const updated = sanitizeDeploymentOperationAlertQueueItem({
    ...currentItem,
    ...existing,
    status,
    priority: normalizeDeploymentAlertPriority(payload.priority || existing.priority || currentItem.priority),
    assignee: String(payload.assignee ?? existing.assignee ?? currentItem.assignee ?? "").trim(),
    dueDate: String(payload.dueDate ?? existing.dueDate ?? currentItem.dueDate ?? "").trim(),
    memo: String(payload.memo ?? existing.memo ?? currentItem.memo ?? "").trim(),
    updatedBy: String(payload.updatedBy || existing.updatedBy || "admin").trim(),
    updatedAt: now,
    resolvedAt: ["resolved", "dismissed"].includes(status) ? (existing.resolvedAt || now) : null
  });
  if (index >= 0) items[index] = updated;
  else items.push(updated);
  const saved = await writeDeploymentOperationAlertQueue({
    ...data,
    items: items.sort((a, b) => String(b.updatedAt || b.lastSeenAt || "").localeCompare(String(a.updatedAt || a.lastSeenAt || "")))
  });
  const changes = deploymentOperationAlertLogChanges(beforeItem, updated);
  let changeLog = null;
  if (changes.length) {
    changeLog = await appendDeploymentOperationAlertLog({
      alertId,
      beforeItem,
      afterItem: updated,
      changes,
      changedBy: updated.updatedBy
    });
  }
  return {
    role: "admin",
    item: {
      ...updated,
      dueState: deploymentAlertDueState(updated)
    },
    changeLog,
    summary: deploymentOperationAlertQueueSummary(saved.items || [])
  };
}

