function commercialLaunchGateSummaryStatus(summary = {}) {
  if (Number(summary.blocked || 0) > 0) return "blocked";
  if (Number(summary.warning || 0) > 0) return "warning";
  return "passed";
}

function commercialLaunchGateAutomaticItem(id = "", label = "", status = "passed", detail = "", action = "", href = "", metrics = {}) {
  const normalizedStatus = ["passed", "warning", "blocked"].includes(status) ? status : "blocked";
  return {
    checkId: id,
    label,
    status: normalizedStatus,
    detail,
    action,
    href,
    metrics
  };
}

function commercialLaunchGateAutomaticSummary(items = []) {
  const summary = items.reduce((acc, item) => {
    acc.total += 1;
    acc[item.status] += 1;
    return acc;
  }, { total: 0, passed: 0, warning: 0, blocked: 0 });
  return {
    ...summary,
    readyRate: summary.total ? Math.round((summary.passed / summary.total) * 100) : 0,
    recommendation: summary.blocked > 0 ? "no_go" : summary.warning > 0 ? "operator_review" : "go_candidate"
  };
}

function commercialLaunchGateFingerprint(items = []) {
  const stable = items.map((item) => ({
    checkId: item.checkId,
    status: item.status,
    metrics: item.metrics
  }));
  return hashId("launchstate", JSON.stringify(stable));
}

function commercialLaunchGateEvidenceRows(latestReview = null) {
  const saved = new Map((latestReview?.manualEvidence || []).map((item) => [item.evidenceId, item]));
  return COMMERCIAL_LAUNCH_GATE_MANUAL_EVIDENCE.map((template) => {
    const current = saved.get(template.evidenceId) || {};
    return {
      ...template,
      required: true,
      confirmed: Boolean(current.confirmed),
      reference: String(current.reference || ""),
      confirmedAt: String(current.confirmedAt || ""),
      confirmedBy: String(current.confirmedBy || "")
    };
  });
}

function commercialLaunchGateSnapshot(automaticItems = [], automaticSummary = {}, extra = {}) {
  return {
    capturedAt: new Date().toISOString(),
    automaticFingerprint: commercialLaunchGateFingerprint(automaticItems),
    automaticSummary: {
      total: Number(automaticSummary.total || 0),
      passed: Number(automaticSummary.passed || 0),
      warning: Number(automaticSummary.warning || 0),
      blocked: Number(automaticSummary.blocked || 0),
      readyRate: Number(automaticSummary.readyRate || 0),
      recommendation: automaticSummary.recommendation || ""
    },
    checks: automaticItems.map((item) => ({
      checkId: item.checkId,
      label: item.label,
      status: item.status,
      metrics: item.metrics
    })),
    ...extra
  };
}

async function commercialLaunchGateReport() {
  const [productQa, deployment, backup, smoke, externalApi, keyRotation, reviewData] = await Promise.all([
    productStabilizationQaReport(),
    deploymentReadinessReport(),
    backupRestoreReadinessReport(),
    deploymentSmokeTestReport(new URLSearchParams({ limit: "20" })),
    externalApiOperationV1LockReport(),
    authKeyRotationService.status(),
    readCommercialLaunchGateReviews()
  ]);
  const productSummary = productQa.summary || {};
  const deploymentSummary = deployment.summary || {};
  const backupSummary = backup.summary || {};
  const smokeLatest = smoke.latestRun || null;
  const externalSummary = externalApi.summary || {};
  const externalLocked = externalApi.lock?.status === "locked" && externalApi.businessBoundaryAudit?.status === "passed";
  const externalStatus = !externalLocked
    ? "blocked"
    : Number(externalSummary.remainingAttentionItems || 0) > 0 ? "warning" : "passed";
  const authLocked = AUTH_SECURITY_V1_LOCK.status === "locked";
  const authStatus = !authLocked || keyRotation.status === "blocked"
    ? "blocked"
    : keyRotation.status === "ready" ? "passed" : "warning";
  const automaticItems = [
    commercialLaunchGateAutomaticItem(
      "product_qa",
      "Product QA",
      commercialLaunchGateSummaryStatus(productSummary),
      `${productSummary.readyRate || 0}% ready; ${productSummary.blocked || 0} blocked and ${productSummary.warning || 0} warning item(s).`,
      "Close product entry, data, permission, and customer-boundary blockers before release.",
      "#productQaPanel",
      { readyRate: productSummary.readyRate || 0, blocked: productSummary.blocked || 0, warning: productSummary.warning || 0 }
    ),
    commercialLaunchGateAutomaticItem(
      "deployment_readiness",
      "Deployment readiness",
      commercialLaunchGateSummaryStatus(deploymentSummary),
      `${deploymentSummary.readyRate || 0}% ready; ${deploymentSummary.blocked || 0} blocked and ${deploymentSummary.warning || 0} warning item(s).`,
      "Resolve Render, persistent storage, environment, authentication, and deployment checklist gaps.",
      "#deploymentReadinessPanel",
      { readyRate: deploymentSummary.readyRate || 0, blocked: deploymentSummary.blocked || 0, warning: deploymentSummary.warning || 0 }
    ),
    commercialLaunchGateAutomaticItem(
      "backup_restore",
      "Backup and restore readiness",
      commercialLaunchGateSummaryStatus(backupSummary),
      `${backupSummary.readyRate || 0}% ready; ${backup.backups?.summary?.total || 0} backup(s) and ${backup.rehearsals?.summary?.passed || 0} passed rehearsal(s).`,
      "Create a current backup and record a passed restore rehearsal before final approval.",
      "#backupRestorePanel",
      {
        readyRate: backupSummary.readyRate || 0,
        blocked: backupSummary.blocked || 0,
        warning: backupSummary.warning || 0,
        backups: backup.backups?.summary?.total || 0,
        passedRehearsals: backup.rehearsals?.summary?.passed || 0
      }
    ),
    commercialLaunchGateAutomaticItem(
      "deployment_smoke",
      "Deployment smoke test",
      !smokeLatest ? "blocked" : smokeLatest.status === "failed" ? "blocked" : smokeLatest.status === "warning" ? "warning" : "passed",
      smokeLatest
        ? `${smokeLatest.runId} finished ${smokeLatest.status}; ${smokeLatest.summary?.failed || 0} failed and ${smokeLatest.summary?.warning || 0} warning step(s).`
        : "No deployment smoke test has been recorded.",
      "Run the complete post-deploy smoke suite and resolve failed steps.",
      "#smokeTestPanel",
      {
        latestRunId: smokeLatest?.runId || "",
        latestStatus: smokeLatest?.status || "not_run",
        failed: smokeLatest?.summary?.failed || 0,
        warning: smokeLatest?.summary?.warning || 0,
        passed: smokeLatest?.summary?.passed || 0
      }
    ),
    commercialLaunchGateAutomaticItem(
      "external_api_v1_lock",
      "External API operation v1.0",
      externalStatus,
      `Lock ${externalApi.lock?.status || "unknown"}; business boundary ${externalApi.businessBoundaryAudit?.status || "unknown"}; ${externalSummary.remainingAttentionItems || 0} attention item(s).`,
      "Keep the v1.0 scope locked and record each connector's mock or real launch mode in manual evidence.",
      "#externalConnectorConsole",
      {
        lockStatus: externalApi.lock?.status || "unknown",
        businessBoundary: externalApi.businessBoundaryAudit?.status || "unknown",
        connectorTotal: externalSummary.connectorTotal || 0,
        realReady: externalSummary.realReady || 0,
        remainingAttentionItems: externalSummary.remainingAttentionItems || 0
      }
    ),
    commercialLaunchGateAutomaticItem(
      "sla_v1_lock",
      "SLA v1.0 lock",
      INTERNAL_QUALITY_SLA_V1_LOCK.status === "locked" ? "passed" : "blocked",
      `Internal quality SLA is ${INTERNAL_QUALITY_SLA_V1_LOCK.status}; recursive extensions remain stopped.`,
      "Operate only the frozen internal quality scope.",
      "#internalQualityLock",
      { lockStatus: INTERNAL_QUALITY_SLA_V1_LOCK.status, lockedAtPhase: INTERNAL_QUALITY_SLA_V1_LOCK.lockedAtPhase }
    ),
    commercialLaunchGateAutomaticItem(
      "auth_security_v1_lock",
      "Authentication and security v1.0",
      authStatus,
      `Lock ${AUTH_SECURITY_V1_LOCK.status}; key state ${keyRotation.status}; active version ${keyRotation.activeVersion || "uninitialized"}.`,
      "Resolve key blockers and retain passing post-rotation smoke evidence before release.",
      "#authAccountPanel",
      {
        lockStatus: AUTH_SECURITY_V1_LOCK.status,
        keyStatus: keyRotation.status,
        currentVersion: keyRotation.currentVersion || "",
        activeVersion: keyRotation.activeVersion || "",
        unreadableRecords: keyRotation.summary?.unreadableRecords || 0,
        postRotationSmokeStatus: keyRotation.postRotationSmoke?.latest?.status || "not_run"
      }
    )
  ];
  const automaticSummary = commercialLaunchGateAutomaticSummary(automaticItems);
  const automaticFingerprint = commercialLaunchGateFingerprint(automaticItems);
  const reviews = (reviewData.items || []).sort((a, b) => String(b.reviewedAt || "").localeCompare(String(a.reviewedAt || "")));
  const latestReview = reviews[0] || null;
  const requiredEvidence = commercialLaunchGateEvidenceRows(latestReview);
  const completedEvidence = requiredEvidence.filter((item) => item.confirmed && item.reference.trim()).length;
  const evidenceComplete = completedEvidence === requiredEvidence.length;
  const approvalStale = Boolean(latestReview?.finalDecision === "approved" && latestReview.automaticFingerprint !== automaticFingerprint);
  let launchDecision = automaticSummary.blocked > 0 ? "no_go" : "pending_review";
  if (automaticSummary.blocked === 0 && latestReview?.finalDecision === "hold") launchDecision = "hold";
  if (automaticSummary.blocked === 0 && latestReview?.finalDecision === "approved") {
    launchDecision = approvalStale ? "review_required" : evidenceComplete ? "go" : "pending_review";
  }
  return {
    role: "admin",
    schema: "commercial_launch_gate_v1",
    generatedAt: new Date().toISOString(),
    summary: {
      launchDecision,
      launchable: launchDecision === "go",
      approvalStale,
      automatic: automaticSummary,
      manualEvidence: {
        total: requiredEvidence.length,
        completed: completedEvidence,
        missing: requiredEvidence.length - completedEvidence,
        complete: evidenceComplete
      },
      blockerCount: automaticSummary.blocked,
      warningCount: automaticSummary.warning
    },
    automaticFingerprint,
    automaticChecks: automaticItems,
    requiredEvidence,
    blockers: automaticItems.filter((item) => item.status === "blocked"),
    warnings: automaticItems.filter((item) => item.status === "warning"),
    latestReview,
    approvalSnapshot: latestReview ? {
      before: latestReview.beforeSnapshot,
      after: latestReview.afterSnapshot,
      changedSinceApproval: approvalStale
    } : null,
    history: reviews.slice(0, 30),
    policy: {
      approvalMode: "manual_only",
      automaticApproval: false,
      recursiveQualityExpansion: false,
      rule: "A final administrator may approve only when automatic blockers are zero and every required manual evidence item has a reference. Any automatic fingerprint change requires a new review."
    }
  };
}

function commercialLaunchGateText(value = "", limit = 1000) {
  return String(value || "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, limit);
}

async function saveCommercialLaunchGateDecision(payload = {}, actor = {}) {
  const decision = payload.decision === "approved" ? "approved" : payload.decision === "hold" ? "hold" : "";
  if (!decision) {
    const error = new Error("Decision must be approved or hold.");
    error.statusCode = 400;
    throw error;
  }
  const report = await commercialLaunchGateReport();
  const now = new Date().toISOString();
  const incoming = new Map((Array.isArray(payload.manualEvidence) ? payload.manualEvidence : []).map((item) => [String(item.evidenceId || ""), item]));
  const previousEvidence = new Map((report.latestReview?.manualEvidence || []).map((item) => [item.evidenceId, item]));
  const manualEvidence = COMMERCIAL_LAUNCH_GATE_MANUAL_EVIDENCE.map((template) => {
    const value = incoming.get(template.evidenceId) || {};
    const previous = previousEvidence.get(template.evidenceId) || {};
    const confirmed = Boolean(value.confirmed);
    const reference = commercialLaunchGateText(value.reference, 500);
    return {
      evidenceId: template.evidenceId,
      label: template.label,
      confirmed,
      reference,
      confirmedAt: confirmed ? previous.confirmedAt || now : "",
      confirmedBy: confirmed ? commercialLaunchGateText(actor.username || actor.userId || "administrator", 120) : ""
    };
  });
  const missingEvidence = manualEvidence.filter((item) => !item.confirmed || !item.reference);
  const finalApprover = commercialLaunchGateText(payload.finalApprover, 120);
  const releaseNote = commercialLaunchGateText(payload.releaseNote, 4000);
  if (decision === "approved" && report.summary.blockerCount > 0) {
    const error = new Error(`Release approval is blocked by ${report.summary.blockerCount} automatic check(s).`);
    error.statusCode = 409;
    throw error;
  }
  if (decision === "approved" && missingEvidence.length) {
    const error = new Error(`Complete all required evidence references before approval (${missingEvidence.length} missing).`);
    error.statusCode = 409;
    throw error;
  }
  if (decision === "approved" && (!finalApprover || !releaseNote)) {
    const error = new Error("Final approver and release note are required for approval.");
    error.statusCode = 400;
    throw error;
  }
  const reviewId = hashId("launchreview", `${now}|${actor.userId || actor.username || "admin"}|${crypto.randomUUID()}`);
  const beforeSnapshot = commercialLaunchGateSnapshot(report.automaticChecks, report.summary.automatic, {
    previousReviewId: report.latestReview?.reviewId || "",
    previousDecision: report.latestReview?.finalDecision || "none",
    currentRecommendation: report.summary.launchDecision
  });
  const afterSnapshot = commercialLaunchGateSnapshot(report.automaticChecks, report.summary.automatic, {
    reviewId,
    finalDecision: decision,
    releaseRecommendation: decision === "approved" ? "go" : "hold",
    completedEvidence: manualEvidence.filter((item) => item.confirmed && item.reference).length,
    requiredEvidence: manualEvidence.length
  });
  const review = {
    reviewId,
    schema: "commercial_launch_gate_review_v1",
    finalDecision: decision,
    finalApprover,
    approvedAt: decision === "approved" ? now : "",
    reviewedAt: now,
    reviewedBy: commercialLaunchGateText(actor.username || actor.userId || "administrator", 120),
    releaseNote,
    automaticFingerprint: report.automaticFingerprint,
    automaticSummary: report.summary.automatic,
    manualEvidence,
    beforeSnapshot,
    afterSnapshot
  };
  const data = await readCommercialLaunchGateReviews();
  await writeCommercialLaunchGateReviews({
    ...data,
    items: [review, ...(data.items || []).filter((item) => item.reviewId !== reviewId)]
  });
  return {
    role: "admin",
    review,
    report: await commercialLaunchGateReport()
  };
}

const COMMERCIAL_LAUNCH_RC_ENVIRONMENTS = Object.freeze(["local", "staging", "render"]);
const COMMERCIAL_LAUNCH_RC_OWNERS = Object.freeze([
  "releaseOwner",
  "rollbackOwner",
  "smokeTestOwner",
  "customerSupportOwner",
  "incidentCommunicationOwner"
]);

function commercialLaunchRcRuntime() {
  const renderDetected = Boolean(process.env.RENDER || process.env.RENDER_SERVICE_ID || process.env.RENDER_EXTERNAL_URL);
  const configured = String(process.env.RC_RUNTIME_ENVIRONMENT || process.env.APP_ENVIRONMENT || "").trim().toLowerCase();
  const environment = renderDetected ? "render" : configured === "staging" ? "staging" : "local";
  const defaultUrl = String(AUTH_PUBLIC_BASE_URL || process.env.RENDER_EXTERNAL_URL || `http://${HOST === "0.0.0.0" ? "127.0.0.1" : HOST}:${PORT}`).trim();
  const release = commercialLaunchRcReleaseIdentity();
  return {
    environment,
    label: environment === "render" ? "Render operation" : environment === "staging" ? "Staging" : "Local",
    productionRuntime: IS_PRODUCTION_RUNTIME,
    renderDetected,
    defaultUrl,
    runtimeReference: commercialLaunchGateText(process.env.RENDER_SERVICE_NAME || process.env.RENDER_SERVICE_ID || environment, 160),
    release
  };
}

function commercialLaunchRcCommit(value = "") {
  const normalized = commercialLaunchGateText(value, 64).toLowerCase();
  return /^[a-f0-9]{7,64}$/.test(normalized) ? normalized : "";
}

function commercialLaunchRcReleaseIdentity() {
  const commit = commercialLaunchRcCommit(process.env.RENDER_GIT_COMMIT || process.env.APP_RELEASE_COMMIT || "");
  return {
    commit,
    shortCommit: commit ? commit.slice(0, 12) : "",
    branch: commercialLaunchGateText(process.env.RENDER_GIT_BRANCH || process.env.APP_RELEASE_BRANCH || "", 160),
    repoSlug: commercialLaunchGateText(process.env.RENDER_GIT_REPO_SLUG || "", 240),
    contract: "commercial_launch_rc_stage_218"
  };
}

function commercialLaunchRcReleaseSource(item = {}, runtime = commercialLaunchRcRuntime()) {
  const expectedInput = commercialLaunchGateText(item.expectedCommit, 64).toLowerCase();
  const expectedCommit = commercialLaunchRcCommit(expectedInput);
  const detectedCommit = commercialLaunchRcCommit(runtime.release?.commit);
  const validExpected = Boolean(expectedCommit);
  const matches = Boolean(validExpected && detectedCommit
    && (expectedCommit.startsWith(detectedCommit) || detectedCommit.startsWith(expectedCommit)));
  let status = "blocked";
  let detail = "Expected release commit is missing.";
  let action = "Enter the tested Git commit before collecting release evidence.";
  if (runtime.environment === "local") {
    status = "warning";
    detail = detectedCommit
      ? `Local source ${detectedCommit.slice(0, 12)} is functional evidence only.`
      : "Local source identity is unavailable and never counts as Render release evidence.";
    action = "Deploy the tested commit to staging or Render and run this rehearsal there.";
  } else if (expectedInput && !validExpected) {
    detail = "Expected release commit is not a valid Git commit prefix.";
    action = "Enter at least 7 hexadecimal characters from the tested commit.";
  } else if (!validExpected) {
    detail = "Expected release commit is missing.";
  } else if (!detectedCommit) {
    detail = "The running service did not expose RENDER_GIT_COMMIT or APP_RELEASE_COMMIT.";
    action = "Confirm the service is deployed from Git and that runtime release metadata is available.";
  } else if (!matches) {
    detail = `Expected ${expectedCommit.slice(0, 12)} but this process runs ${detectedCommit.slice(0, 12)}.`;
    action = "Deploy the expected commit, then create or synchronize a fresh rehearsal.";
  } else {
    status = "passed";
    detail = `Expected and running source match at ${detectedCommit.slice(0, 12)}.`;
    action = "Keep this commit fixed until the manual Go/No-Go decision is recorded.";
  }
  return {
    status,
    expectedCommit,
    detectedCommit,
    shortExpectedCommit: expectedCommit ? expectedCommit.slice(0, 12) : "",
    shortDetectedCommit: detectedCommit ? detectedCommit.slice(0, 12) : "",
    matches,
    branch: runtime.release?.branch || "",
    repoSlug: runtime.release?.repoSlug || "",
    contract: runtime.release?.contract || "commercial_launch_rc_stage_218",
    detail,
    action
  };
}

function commercialLaunchRcTargetValidation(targetUrl = "", environment = "local") {
  const value = commercialLaunchGateText(targetUrl, 500);
  if (!value) return { valid: false, reason: "target_url_missing", normalizedUrl: "" };
  try {
    const parsed = new URL(value);
    if (!["http:", "https:"].includes(parsed.protocol)) return { valid: false, reason: "target_url_protocol", normalizedUrl: "" };
    if (environment !== "local" && parsed.protocol !== "https:") return { valid: false, reason: "https_required", normalizedUrl: parsed.toString().replace(/\/$/, "") };
    return { valid: true, reason: "valid", normalizedUrl: parsed.toString().replace(/\/$/, "") };
  } catch {
    return { valid: false, reason: "target_url_invalid", normalizedUrl: "" };
  }
}

function commercialLaunchRcEnvironment(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return COMMERCIAL_LAUNCH_RC_ENVIRONMENTS.includes(normalized) ? normalized : commercialLaunchRcRuntime().environment;
}

function commercialLaunchRcConnectorModes(input = [], diagnostics = []) {
  const incoming = new Map((Array.isArray(input) ? input : []).map((item) => [String(item.connectorId || ""), item]));
  return (diagnostics || []).map((connector) => {
    const value = incoming.get(connector.connectorId) || {};
    const requestedMode = ["mock", "real"].includes(String(value.mode || "")) ? String(value.mode) : "";
    return {
      connectorId: connector.connectorId,
      label: connector.label,
      mode: requestedMode,
      notes: commercialLaunchGateText(value.notes, 500),
      realReady: Boolean(connector.realReady),
      diagnosticStatus: connector.status || "unknown"
    };
  });
}

function commercialLaunchRcEvidenceSummary(evidence = {}) {
  return {
    backup: evidence.backup ? {
      backupId: evidence.backup.backupId || "",
      status: evidence.backup.status || "",
      createdAt: evidence.backup.createdAt || ""
    } : null,
    restore: evidence.restore ? {
      rehearsalId: evidence.restore.rehearsalId || "",
      backupId: evidence.restore.backupId || "",
      status: evidence.restore.status || "",
      checkedAt: evidence.restore.checkedAt || ""
    } : null,
    authPreflight: evidence.authPreflight ? {
      runId: evidence.authPreflight.runId || "",
      status: evidence.authPreflight.status || "",
      currentVersion: evidence.authPreflight.currentVersion || "",
      generatedAt: evidence.authPreflight.generatedAt || ""
    } : null,
    authSmoke: evidence.authSmoke ? {
      runId: evidence.authSmoke.runId || "",
      status: evidence.authSmoke.status || "",
      currentVersion: evidence.authSmoke.currentVersion || "",
      activeVersion: evidence.authSmoke.activeVersion || "",
      generatedAt: evidence.authSmoke.generatedAt || ""
    } : null,
    deploymentSmoke: evidence.deploymentSmoke ? {
      runId: evidence.deploymentSmoke.runId || "",
      status: evidence.deploymentSmoke.status || "",
      triggeredAt: evidence.deploymentSmoke.triggeredAt || "",
      finishedAt: evidence.deploymentSmoke.finishedAt || ""
    } : null
  };
}

function commercialLaunchRcStep(stepId, order, label, status, detail, action, href = "") {
  return {
    stepId,
    order,
    label,
    status: ["passed", "warning", "pending", "blocked"].includes(status) ? status : "pending",
    detail,
    action,
    href
  };
}

function commercialLaunchRcSteps(item = {}, context = {}) {
  const runtime = context.runtime || commercialLaunchRcRuntime();
  const releaseSource = context.releaseSource || commercialLaunchRcReleaseSource(item, runtime);
  const target = commercialLaunchRcTargetValidation(item.targetUrl, item.requestedEnvironment);
  const evidence = commercialLaunchRcEvidenceSummary(item.evidence || {});
  const keyRotation = context.keyRotation || {};
  const environmentMatches = item.requestedEnvironment === runtime.environment;
  const environmentStatus = !environmentMatches || !target.valid
    ? "blocked"
    : runtime.environment === "local" ? "warning" : "passed";
  const backupReady = evidence.backup?.status === "succeeded";
  const restoreReady = evidence.restore?.status === "passed"
    && evidence.restore?.backupId === evidence.backup?.backupId;
  const keyReady = keyRotation.status === "ready"
    && keyRotation.activeVersion
    && keyRotation.activeVersion === keyRotation.currentVersion;
  const keyStatus = keyRotation.status === "blocked" ? "blocked" : keyReady ? "passed" : "pending";
  const authSmokeReady = evidence.authSmoke?.status === "passed"
    && evidence.authSmoke?.currentVersion === keyRotation.currentVersion
    && evidence.authSmoke?.activeVersion === keyRotation.currentVersion;
  const connectorModes = context.connectorModes || [];
  const missingConnectorModes = connectorModes.filter((connector) => !connector.mode);
  const unavailableReal = connectorModes.filter((connector) => connector.mode === "real" && !connector.realReady);
  const undocumentedMock = connectorModes.filter((connector) => connector.mode === "mock" && !connector.notes);
  const connectorStatus = unavailableReal.length ? "blocked"
    : missingConnectorModes.length ? "pending"
      : undocumentedMock.length ? "warning" : "passed";
  const ownersMissing = COMMERCIAL_LAUNCH_RC_OWNERS.filter((key) => !String(item.owners?.[key] || "").trim());
  const deploymentStatus = !evidence.deploymentSmoke ? "pending"
    : evidence.deploymentSmoke.status === "failed" ? "blocked"
      : evidence.deploymentSmoke.status === "warning" ? "warning" : "passed";
  return [
    commercialLaunchRcStep(
      "runtime_environment",
      1,
      "Execution environment and target route",
      environmentStatus,
      !environmentMatches
        ? `Requested ${item.requestedEnvironment}; this process is ${runtime.environment}. Results cannot be mixed across environments.`
        : !target.valid ? `Target URL is not valid for ${item.requestedEnvironment}: ${target.reason}.`
          : runtime.environment === "local" ? "Local evidence is recorded separately and cannot satisfy staging or Render release evidence." : `${runtime.label} and HTTPS target match.`,
      "Select the environment that is actually running this process and verify its public route.",
      "#deploymentReadinessPanel"
    ),
    commercialLaunchRcStep("release_source_parity", 2, "Deployed release source", releaseSource.status, releaseSource.detail, releaseSource.action, "#deploymentReadinessPanel"),
    commercialLaunchRcStep("current_backup", 3, "Current backup", backupReady ? "passed" : evidence.backup ? "blocked" : "pending", backupReady ? `${evidence.backup.backupId} created ${evidence.backup.createdAt || ""}.` : "Create a backup of db, config, and outputs before rehearsal.", "Create a fresh backup from this rehearsal.", "#backupRestorePanel"),
    commercialLaunchRcStep("restore_rehearsal", 4, "Restore and rollback rehearsal", restoreReady ? "passed" : evidence.restore?.status === "failed" ? "blocked" : "pending", restoreReady ? `${evidence.restore.rehearsalId} passed for ${evidence.restore.backupId}.` : "Record an operator-verified restore rehearsal against the current backup.", "Complete the restore checklist in an isolated rehearsal window, then record the result.", "#backupRestorePanel"),
    commercialLaunchRcStep("auth_key_activation", 5, "Authentication key activation", keyStatus, keyReady ? `Active ${keyRotation.activeVersion}; current ${keyRotation.currentVersion}.` : `Key status ${keyRotation.status || "unknown"}; active ${keyRotation.activeVersion || "uninitialized"}; current ${keyRotation.currentVersion || "unknown"}.`, "Run preflight here. Apply the current key only from the authentication panel because applying it revokes sessions.", "#authAccountPanel"),
    commercialLaunchRcStep("auth_post_rotation_smoke", 6, "Authentication and security smoke", authSmokeReady ? "passed" : evidence.authSmoke?.status === "failed" ? "blocked" : "pending", authSmokeReady ? `${evidence.authSmoke.runId} passed for ${evidence.authSmoke.currentVersion}.` : "Run login, MFA, CSRF, invitation, email retry, and webhook smoke after key activation.", "Run the post-rotation smoke only after the current version is active.", "#authAccountPanel"),
    commercialLaunchRcStep("connector_launch_modes", 7, "External connector launch modes", connectorStatus, unavailableReal.length ? `${unavailableReal.map((item) => item.label).join(", ")} cannot run in real mode yet.` : missingConnectorModes.length ? `${missingConnectorModes.length} connector mode decision(s) are missing.` : undocumentedMock.length ? `${undocumentedMock.length} mock launch decision(s) need an operator note.` : `${connectorModes.filter((item) => item.mode === "real").length} real and ${connectorModes.filter((item) => item.mode === "mock").length} mock mode(s) documented.`, "Record mock or real for every connector; mock is allowed only with a launch note.", "#externalConnectorConsole"),
    commercialLaunchRcStep("admin_mfa_recovery", 8, "Administrator MFA and recovery drill", item.confirmations?.mfaRecoveryVerified ? "passed" : "pending", item.confirmations?.mfaRecoveryVerified ? "Administrator MFA step-up and an offline recovery procedure were manually verified." : "No administrator MFA and recovery drill confirmation is recorded.", "Verify one MFA step-up and recovery-code procedure without storing secret values.", "#authAccountPanel"),
    commercialLaunchRcStep("deployment_smoke", 9, "Post-deploy smoke test", deploymentStatus, evidence.deploymentSmoke ? `${evidence.deploymentSmoke.runId} finished ${evidence.deploymentSmoke.status}.` : "No smoke run is linked to this rehearsal.", "Run the complete deployment smoke suite on this environment.", "#smokeTestPanel"),
    commercialLaunchRcStep("release_owners", 10, "Release, rollback, and customer response owners", ownersMissing.length ? "pending" : "passed", ownersMissing.length ? `${ownersMissing.length} required owner assignment(s) are missing.` : "Release, rollback, smoke, customer support, and incident communication owners are assigned.", "Assign every operational owner before final review.")
  ];
}

function commercialLaunchRcEvidenceSuggestions(item = {}, steps = [], context = {}) {
  const byId = new Map(steps.map((step) => [step.stepId, step]));
  const evidence = commercialLaunchRcEvidenceSummary(item.evidence || {});
  const connectorSummary = (context.connectorModes || []).map((connector) => `${connector.label}:${connector.mode || "undecided"}`).join(", ");
  const suggestion = (evidenceId, ready, reference) => ({ evidenceId, ready: Boolean(ready), reference: commercialLaunchGateText(reference, 500) });
  return [
    suggestion("production_environment", byId.get("runtime_environment")?.status === "passed" && byId.get("release_source_parity")?.status === "passed", `${item.requestedEnvironment} ${item.targetUrl || "route missing"} / commit ${context.releaseSource?.shortDetectedCommit || "missing"} / RC ${item.rehearsalId || "draft"}`),
    suggestion("backup_restore_rehearsal", byId.get("current_backup")?.status === "passed" && byId.get("restore_rehearsal")?.status === "passed", `backup ${evidence.backup?.backupId || "missing"} / restore ${evidence.restore?.rehearsalId || "missing"} / rollback ${item.owners?.rollbackOwner || "unassigned"}`),
    suggestion("security_access_recovery", byId.get("auth_key_activation")?.status === "passed" && byId.get("auth_post_rotation_smoke")?.status === "passed" && byId.get("admin_mfa_recovery")?.status === "passed", `key ${context.keyRotation?.activeVersion || "inactive"} / smoke ${evidence.authSmoke?.runId || "missing"} / MFA recovery ${item.confirmations?.mfaRecoveryVerified ? "verified" : "pending"}`),
    suggestion("connector_provider_cutover", byId.get("connector_launch_modes")?.status === "passed" && Boolean(item.confirmations?.providerWebhookVerified), `${connectorSummary || "connector decisions missing"} / provider webhook ${item.confirmations?.providerWebhookVerified ? "verified" : "pending"}`),
    suggestion("release_rollback_communication", byId.get("deployment_smoke")?.status === "passed" && byId.get("release_owners")?.status === "passed", `smoke ${evidence.deploymentSmoke?.runId || "missing"} / release ${item.owners?.releaseOwner || "unassigned"} / rollback ${item.owners?.rollbackOwner || "unassigned"} / support ${item.owners?.customerSupportOwner || "unassigned"}`)
  ];
}

async function commercialLaunchRcReport(params = new URLSearchParams()) {
  const [data, diagnostics, keyRotation] = await Promise.all([
    readCommercialLaunchRcRehearsals(),
    externalConnectorDiagnostics(),
    authKeyRotationService.status()
  ]);
  const runtime = commercialLaunchRcRuntime();
  const requestedId = params.get("rehearsalId") || "";
  const storedItems = (data.items || []).sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")));
  const stored = requestedId
    ? storedItems.find((item) => item.rehearsalId === requestedId) || null
    : storedItems[0] || null;
  const item = stored || {
    rehearsalId: "",
    schema: "commercial_launch_rc_rehearsal_v1",
    requestedEnvironment: runtime.environment,
    targetUrl: runtime.defaultUrl,
    expectedCommit: "",
    executionIdentity: null,
    owners: Object.fromEntries(COMMERCIAL_LAUNCH_RC_OWNERS.map((key) => [key, ""])),
    confirmations: { mfaRecoveryVerified: false, providerWebhookVerified: false },
    connectorModes: [],
    evidence: {},
    notes: "",
    createdAt: "",
    updatedAt: ""
  };
  const connectorModes = commercialLaunchRcConnectorModes(item.connectorModes, diagnostics.connectors || []);
  const releaseSource = commercialLaunchRcReleaseSource(item, runtime);
  const context = { runtime, keyRotation, connectorModes, releaseSource };
  const steps = commercialLaunchRcSteps(item, context);
  const summary = steps.reduce((acc, step) => {
    acc.total += 1;
    acc[step.status] += 1;
    return acc;
  }, { total: 0, passed: 0, warning: 0, pending: 0, blocked: 0 });
  const allOperationalStepsComplete = summary.blocked === 0 && summary.pending === 0;
  const rehearsalStatus = summary.blocked > 0 ? "blocked"
    : !allOperationalStepsComplete ? "in_progress"
      : runtime.environment === "local" ? "local_rehearsal_complete"
        : summary.warning > 0 ? "operator_review" : "ready_for_final_review";
  const evidenceSuggestions = commercialLaunchRcEvidenceSuggestions(item, steps, context);
  const operatorActions = steps.filter((step) => step.status !== "passed").map((step) => ({
    stepId: step.stepId,
    order: step.order,
    status: step.status,
    label: step.label,
    requiredAction: step.action,
    href: step.href || ""
  }));
  return {
    role: "admin",
    schema: "commercial_launch_rc_rehearsals_v1",
    generatedAt: new Date().toISOString(),
    rehearsal: {
      ...item,
      connectorModes,
      evidence: commercialLaunchRcEvidenceSummary(item.evidence || {}),
      status: rehearsalStatus
    },
    runtime,
    releaseCandidate: {
      ...releaseSource,
      executionIdentity: item.executionIdentity || null,
      manualApprovalRequired: true
    },
    environmentComparison: {
      requested: item.requestedEnvironment,
      executed: runtime.environment,
      matches: item.requestedEnvironment === runtime.environment,
      target: commercialLaunchRcTargetValidation(item.targetUrl, item.requestedEnvironment),
      localEvidenceCountsForRelease: false
    },
    keyActivation: {
      status: keyRotation.status,
      currentVersion: keyRotation.currentVersion,
      activeVersion: keyRotation.activeVersion,
      blockers: keyRotation.blockers || [],
      currentKeysConfigured: keyRotation.summary?.currentKeysConfigured || 0,
      requiredCurrentKeys: keyRotation.summary?.requiredCurrentKeys || 0,
      latestPreflight: keyRotation.preflight?.latest ? {
        runId: keyRotation.preflight.latest.runId,
        status: keyRotation.preflight.latest.status,
        generatedAt: keyRotation.preflight.latest.generatedAt
      } : null,
      latestSmoke: keyRotation.postRotationSmoke?.latest ? {
        runId: keyRotation.postRotationSmoke.latest.runId,
        status: keyRotation.postRotationSmoke.latest.status,
        generatedAt: keyRotation.postRotationSmoke.latest.generatedAt
      } : null,
      applyMode: "manual_from_authentication_panel"
    },
    steps,
    summary: {
      ...summary,
      status: rehearsalStatus,
      readyForFinalReview: rehearsalStatus === "ready_for_final_review",
      localOnly: runtime.environment === "local"
    },
    evidenceSuggestions,
    readyEvidence: evidenceSuggestions.filter((entry) => entry.ready),
    operatorActions,
    history: storedItems.slice(0, 30).map((entry) => ({
      rehearsalId: entry.rehearsalId,
      requestedEnvironment: entry.requestedEnvironment,
      targetUrl: entry.targetUrl,
      expectedCommit: entry.expectedCommit || "",
      executedCommit: entry.executionIdentity?.commit || "",
      executedEnvironment: entry.executionIdentity?.environment || "",
      updatedAt: entry.updatedAt,
      updatedBy: entry.updatedBy,
      notes: entry.notes || ""
    })),
    policy: {
      finalApproval: "manual_only",
      automaticApproval: false,
      recursiveQualityExpansion: false,
      keyActivation: "explicit_admin_action_only",
      sourceParity: "expected_commit_must_match_running_release",
      environmentIsolation: "Local evidence never satisfies staging or Render evidence. A rehearsal must execute in the environment it claims."
    }
  };
}

async function upsertCommercialLaunchRcRehearsal(payload = {}, actor = {}) {
  const [data, diagnostics] = await Promise.all([readCommercialLaunchRcRehearsals(), externalConnectorDiagnostics()]);
  const now = new Date().toISOString();
  const rehearsalId = commercialLaunchGateText(payload.rehearsalId, 120)
    || hashId("launchrc", `${now}|${actor.userId || actor.username || "admin"}|${crypto.randomUUID()}`);
  const existing = (data.items || []).find((item) => item.rehearsalId === rehearsalId) || {};
  const requestedEnvironment = commercialLaunchRcEnvironment(payload.requestedEnvironment || existing.requestedEnvironment);
  const target = commercialLaunchRcTargetValidation(payload.targetUrl || existing.targetUrl || commercialLaunchRcRuntime().defaultUrl, requestedEnvironment);
  const owners = Object.fromEntries(COMMERCIAL_LAUNCH_RC_OWNERS.map((key) => [
    key,
    commercialLaunchGateText(payload.owners?.[key] ?? existing.owners?.[key] ?? "", 160)
  ]));
  const connectorModes = commercialLaunchRcConnectorModes(payload.connectorModes ?? existing.connectorModes ?? [], diagnostics.connectors || []);
  const runtime = commercialLaunchRcRuntime();
  const expectedCommit = commercialLaunchGateText(payload.expectedCommit ?? existing.expectedCommit ?? "", 64).toLowerCase();
  const item = {
    ...existing,
    rehearsalId,
    schema: "commercial_launch_rc_rehearsal_v1",
    requestedEnvironment,
    targetUrl: target.normalizedUrl || commercialLaunchGateText(payload.targetUrl || existing.targetUrl, 500),
    expectedCommit,
    executionIdentity: {
      environment: runtime.environment,
      commit: runtime.release?.commit || "",
      branch: runtime.release?.branch || "",
      repoSlug: runtime.release?.repoSlug || "",
      recordedAt: now
    },
    owners,
    confirmations: {
      mfaRecoveryVerified: Boolean(payload.confirmations?.mfaRecoveryVerified ?? existing.confirmations?.mfaRecoveryVerified),
      providerWebhookVerified: Boolean(payload.confirmations?.providerWebhookVerified ?? existing.confirmations?.providerWebhookVerified)
    },
    connectorModes,
    evidence: existing.evidence || {},
    notes: commercialLaunchGateText(payload.notes ?? existing.notes, 4000),
    createdAt: existing.createdAt || now,
    createdBy: existing.createdBy || commercialLaunchGateText(actor.username || actor.userId || "administrator", 160),
    updatedAt: now,
    updatedBy: commercialLaunchGateText(actor.username || actor.userId || "administrator", 160),
    actionHistory: (existing.actionHistory || []).slice(0, 100)
  };
  await writeCommercialLaunchRcRehearsals({
    ...data,
    items: [item, ...(data.items || []).filter((entry) => entry.rehearsalId !== rehearsalId)]
  });
  return commercialLaunchRcReport(new URLSearchParams({ rehearsalId }));
}

async function commercialLaunchRcLatestEvidence() {
  const [backups, restores, smoke, keyRotation] = await Promise.all([
    readBackupManifest(),
    readBackupRestoreRehearsals(),
    readDeploymentSmokeTestRuns(),
    authKeyRotationService.status()
  ]);
  const latestBackup = [...(backups.items || [])].sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")))[0] || null;
  const latestRestore = [...(restores.items || [])]
    .filter((item) => !latestBackup || item.backupId === latestBackup.backupId)
    .sort((a, b) => String(b.checkedAt || b.createdAt || "").localeCompare(String(a.checkedAt || a.createdAt || "")))[0] || null;
  const latestSmoke = [...(smoke.items || [])].sort((a, b) => String(b.triggeredAt || "").localeCompare(String(a.triggeredAt || "")))[0] || null;
  return {
    backup: latestBackup,
    restore: latestRestore,
    authPreflight: keyRotation.preflight?.latest || null,
    authSmoke: keyRotation.postRotationSmoke?.latest || null,
    deploymentSmoke: latestSmoke
  };
}

async function runCommercialLaunchRcAction(rehearsalId = "", action = "", payload = {}, actor = {}, metadata = {}) {
  const data = await readCommercialLaunchRcRehearsals();
  const existing = (data.items || []).find((item) => item.rehearsalId === rehearsalId);
  if (!existing) {
    const error = new Error("RC rehearsal was not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  let evidence = { ...(existing.evidence || {}) };
  let resultStatus = "recorded";
  if (action === "create_backup") {
    const result = await createManualBackup({
      includeOutputs: payload.includeOutputs !== false,
      createdBy: actor.username || actor.userId || "administrator",
      notes: `RC ${rehearsalId}: ${commercialLaunchGateText(payload.notes || existing.notes, 1000)}`
    });
    evidence.backup = result.backup;
    evidence.restore = null;
    resultStatus = result.backup.status;
  } else if (action === "record_restore") {
    const backupId = commercialLaunchGateText(payload.backupId || evidence.backup?.backupId, 120);
    const status = ["planned", "in_progress", "passed", "failed", "blocked"].includes(String(payload.status || "")) ? String(payload.status) : "planned";
    const notes = commercialLaunchGateText(payload.notes, 2000);
    if (status === "passed" && notes.length < 12) {
      const error = new Error("A passed restore rehearsal requires an operator note describing the isolated restore check.");
      error.statusCode = 400;
      throw error;
    }
    const result = await upsertBackupRestoreRehearsal({
      backupId,
      status,
      notes,
      checkedBy: actor.username || actor.userId || "administrator",
      targetService: existing.requestedEnvironment,
      preflightStatus: status === "passed" ? "passed" : "needs_review",
      restoreDecision: status === "passed" ? "candidate_ready" : "not_ready"
    });
    evidence.restore = result.rehearsal;
    resultStatus = result.rehearsal.status;
  } else if (action === "auth_preflight") {
    const result = await authKeyRotationService.runPreflight(actor, metadata);
    evidence.authPreflight = result.run;
    resultStatus = result.run.status;
  } else if (action === "auth_smoke") {
    const result = await authKeyRotationService.runPostRotationSmoke(actor, metadata);
    evidence.authSmoke = result.run;
    resultStatus = result.run.status;
  } else if (action === "deployment_smoke") {
    const result = await runDeploymentSmokeTests({ triggeredBy: actor.username || actor.userId || "administrator" });
    evidence.deploymentSmoke = result.run;
    resultStatus = result.run.status;
  } else if (action === "sync_current") {
    evidence = await commercialLaunchRcLatestEvidence();
    resultStatus = "synchronized";
  } else {
    const error = new Error("Unsupported RC rehearsal action.");
    error.statusCode = 400;
    throw error;
  }
  const actionEntry = {
    actionId: hashId("rcaction", `${rehearsalId}|${action}|${now}|${crypto.randomUUID()}`),
    action,
    status: resultStatus,
    executedAt: now,
    executedEnvironment: commercialLaunchRcRuntime().environment,
    executedCommit: commercialLaunchRcRuntime().release?.commit || "",
    executedBy: commercialLaunchGateText(actor.username || actor.userId || "administrator", 160)
  };
  const runtime = commercialLaunchRcRuntime();
  const item = {
    ...existing,
    evidence,
    executionIdentity: {
      environment: runtime.environment,
      commit: runtime.release?.commit || "",
      branch: runtime.release?.branch || "",
      repoSlug: runtime.release?.repoSlug || "",
      recordedAt: now
    },
    updatedAt: now,
    updatedBy: actionEntry.executedBy,
    actionHistory: [actionEntry, ...(existing.actionHistory || [])].slice(0, 100)
  };
  await writeCommercialLaunchRcRehearsals({
    ...data,
    items: [item, ...(data.items || []).filter((entry) => entry.rehearsalId !== rehearsalId)]
  });
  return commercialLaunchRcReport(new URLSearchParams({ rehearsalId }));
}

async function externalConnectorScheduleReport() {
  const [scheduleData, logsData, jobsData, diagnostics] = await Promise.all([
    readExternalConnectorSchedules(),
    readExternalConnectorRunLogs(),
    readInterestSignalJobs(),
    externalConnectorDiagnostics()
  ]);
  const logs = logsData.items || [];
  const jobs = jobsData.items || [];
  const today = new Date().toISOString().slice(0, 10);
  const policies = externalConnectorPolicyList(scheduleData);
  const items = policies.map((policy) => {
    const connector = diagnostics.connectors.find((item) => item.connectorId === policy.connectorId) || {};
    const usedToday = connectorDailyLogCount(logs, policy.connectorId, today);
    const quotaRisk = quotaRiskForPolicy(policy, usedToday);
    const pendingQueue = connectorPendingQueueCounts(policy.connectorId, jobs);
    const failurePending = connectorFailurePendingCounts({ connectorId: policy.connectorId, logs, jobs });
    const nextRunAt = nextRunAtForPolicy(policy);
    const due = Boolean(policy.enabled && nextRunAt && Date.parse(nextRunAt) <= Date.now() && !quotaRisk.blocked);
    return {
      ...policy,
      label: connector.label || policy.connectorId,
      source: connector.source || connectorSourceForId(policy.connectorId),
      realReady: Boolean(connector.realReady),
      connectorStatus: connector.status || "unknown",
      nextRunAt,
      due,
      pendingQueue,
      failurePending,
      quotaRisk,
      lastRun: connector.lastRun || null
    };
  });
  const summary = {
    total: items.length,
    enabled: items.filter((item) => item.enabled).length,
    due: items.filter((item) => item.due).length,
    quotaWarning: items.filter((item) => item.quotaRisk.level === "warning").length,
    quotaDanger: items.filter((item) => item.quotaRisk.level === "danger").length,
    retryPending: items.reduce((sum, item) => sum + Number(item.pendingQueue.retry_scheduled || 0), 0),
    reviewPending: items.reduce((sum, item) => sum + Number(item.pendingQueue.review_required || 0), 0),
    failedPending: items.reduce((sum, item) => sum + Number(item.pendingQueue.failed || 0), 0)
  };
  return {
    role: "admin",
    generatedAt: new Date().toISOString(),
    schema: "external_connector_scheduler_v1",
    summary,
    items
  };
}

async function updateExternalConnectorSchedules(payload = {}) {
  const scheduleData = await readExternalConnectorSchedules();
  const existing = new Map(externalConnectorPolicyList(scheduleData).map((item) => [item.connectorId, item]));
  const persistedIds = new Set((scheduleData.policies || []).map((item) => normalizeExternalConnectorId(item.connectorId)));
  const incoming = Array.isArray(payload.policies) ? payload.policies : [payload.policy || payload];
  const auditEntries = [];
  for (const raw of incoming) {
    if (!raw || !raw.connectorId) continue;
    const connectorId = normalizeExternalConnectorId(raw.connectorId);
    const beforePolicy = existing.get(connectorId) || defaultExternalConnectorSchedule(connectorId);
    const normalized = normalizeSchedulePolicy({
      ...raw,
      updatedBy: raw.updatedBy || payload.updatedBy || "admin"
    }, beforePolicy);
    normalized.nextRunAt = nextRunAtForPolicy(normalized);
    const changes = schedulePolicyChanges(beforePolicy, normalized);
    auditEntries.push({
      eventType: persistedIds.has(connectorId) ? "policy_saved" : "policy_created",
      connectorId,
      actor: normalized.updatedBy,
      trigger: payload.trigger || "admin_save",
      status: changes.length ? "changed" : "unchanged",
      resultSummary: changes.length ? `${changes.length} schedule policy fields changed.` : "Schedule policy saved without field changes.",
      previousNextRunAt: beforePolicy.nextRunAt || "",
      nextRunAt: normalized.nextRunAt || "",
      beforePolicy,
      afterPolicy: normalized,
      changes
    });
    existing.set(connectorId, normalized);
  }
  const policies = Object.keys(EXTERNAL_CONNECTORS).map((connectorId) => existing.get(connectorId) || defaultExternalConnectorSchedule(connectorId));
  await writeExternalConnectorSchedules({
    ...scheduleData,
    policies
  });
  for (const entry of auditEntries) {
    await appendExternalConnectorScheduleAuditLog(entry);
  }
  return externalConnectorScheduleReport();
}

function retryDueInterestJobs(jobs = [], connectorId = "", retryLimit = 2) {
  const now = Date.now();
  return jobs.filter((job) => {
    if (connectorIdForInterestJob(job) !== connectorId) return false;
    if (job.status === "queued") return true;
    if (job.status !== "retry_scheduled") return false;
    if (Number(job.attemptCount || 0) >= Number(retryLimit || 0)) return false;
    const nextRetryAt = Date.parse(job.nextRetryAt || "");
    return !Number.isFinite(nextRetryAt) || nextRetryAt <= now;
  });
}

async function runScheduledInterestConnector(policy = {}) {
  const jobsData = await readInterestSignalJobs();
  const candidates = retryDueInterestJobs(jobsData.items || [], policy.connectorId, policy.retryLimit);
  const candidateCounts = candidates.reduce((acc, item) => {
    const status = item.status || "queued";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  const limit = Math.max(1, Math.min(Number(policy.dailyLimit || 25), candidates.length || 1));
  const source = connectorSourceForId(policy.connectorId);
  const results = [];
  for (const job of candidates.slice(0, limit)) {
    const result = await runInterestSignalJob(job.jobId, {
      ...(policy.runOptions || {}),
      connectorId: policy.connectorId,
      source,
      connectorMode: policy.runOptions?.connectorMode || "auto"
    });
    if (result) results.push(result);
  }
  const counts = results.reduce((acc, item) => {
    const status = item.job?.status || "unknown";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  return { requested: Math.min(limit, candidates.length), results, counts, candidateCounts };
}

async function runDueExternalConnectorSchedules(payload = {}) {
  const report = await externalConnectorScheduleReport();
  const requestedConnectorId = payload.connectorId ? normalizeExternalConnectorId(payload.connectorId) : "";
  const now = Date.now();
  const consideredPolicies = report.items
    .filter((item) => item.enabled)
    .filter((item) => !requestedConnectorId || item.connectorId === requestedConnectorId)
    .filter((item) => payload.force || isScheduleTimeDue(item, now));
  const quotaBlockedPolicies = consideredPolicies.filter((item) => !payload.force && item.quotaRisk?.blocked);
  const duePolicies = consideredPolicies.filter((item) => payload.force || !item.quotaRisk?.blocked);
  const scheduleData = await readExternalConnectorSchedules();
  const policyMap = new Map(externalConnectorPolicyList(scheduleData).map((item) => [item.connectorId, item]));
  const results = [];
  for (const policy of quotaBlockedPolicies) {
    await appendExternalConnectorScheduleAuditLog({
      eventType: "quota_blocked",
      connectorId: policy.connectorId,
      actor: payload.actor || "scheduler",
      trigger: requestedConnectorId ? "connector_schedule_run" : "due_schedule_run",
      status: "blocked",
      resultSummary: policy.quotaRisk?.message || "Schedule run blocked by quota policy.",
      failureType: "quota_blocked",
      quotaRisk: policy.quotaRisk || null,
      previousNextRunAt: policy.nextRunAt || "",
      nextRunAt: policy.nextRunAt || "",
      beforePolicy: policy,
      afterPolicy: policy
    });
  }
  for (const policy of duePolicies) {
    const runStart = new Date().toISOString();
    const current = policyMap.get(policy.connectorId) || policy;
    const result = policy.connectorId === "ota_exposure"
      ? await runOtaExposureConnector({
        ...(policy.runOptions || {}),
        connectorMode: policy.runOptions?.connectorMode || "auto",
        limit: Math.max(1, Math.min(Number(policy.dailyLimit || 10), Number(policy.runOptions?.limit || policy.dailyLimit || 10)))
      })
      : await runScheduledInterestConnector(policy);
    const nextPolicy = normalizeSchedulePolicy({
      ...current,
      lastRunAt: runStart,
      lastOutcome: JSON.stringify(result.counts || {}),
      nextRunAt: new Date(Date.parse(runStart) + Math.max(15, Number(current.intervalMinutes || 60)) * 60000).toISOString(),
      updatedBy: "scheduler"
    }, current);
    policyMap.set(policy.connectorId, nextPolicy);
    const status = scheduleRunResultStatus(result);
    await appendExternalConnectorScheduleAuditLog({
      eventType: payload.force ? "forced_run" : "scheduled_run",
      connectorId: policy.connectorId,
      actor: payload.actor || (payload.force ? "admin" : "scheduler"),
      trigger: payload.force ? "manual_force_run" : "due_schedule_run",
      status,
      resultSummary: scheduleRunResultSummary(result),
      failureType: status === "failed" || status === "retry_scheduled" ? "connector_result" : "",
      quotaRisk: policy.quotaRisk || null,
      runMode: policy.runOptions?.connectorMode || "auto",
      forced: Boolean(payload.force),
      requestedCount: Number(result.requested || 0),
      resultCounts: result.counts || {},
      candidateCounts: result.candidateCounts || {},
      previousNextRunAt: current.nextRunAt || policy.nextRunAt || "",
      nextRunAt: nextPolicy.nextRunAt || "",
      beforePolicy: current,
      afterPolicy: nextPolicy,
      changes: schedulePolicyChanges(current, nextPolicy)
    });
    if (Number(result.candidateCounts?.retry_scheduled || 0) > 0) {
      await appendExternalConnectorScheduleAuditLog({
        eventType: "retry_run_result",
        connectorId: policy.connectorId,
        actor: payload.actor || (payload.force ? "admin" : "scheduler"),
        trigger: payload.force ? "manual_force_retry_run" : "due_retry_run",
        status,
        resultSummary: scheduleRunResultSummary(result),
        failureType: status === "failed" || status === "retry_scheduled" ? "connector_retry_result" : "",
        quotaRisk: policy.quotaRisk || null,
        runMode: policy.runOptions?.connectorMode || "auto",
        forced: Boolean(payload.force),
        requestedCount: Number(result.requested || 0),
        resultCounts: result.counts || {},
        candidateCounts: result.candidateCounts || {},
        previousNextRunAt: current.nextRunAt || policy.nextRunAt || "",
        nextRunAt: nextPolicy.nextRunAt || "",
        beforePolicy: current,
        afterPolicy: nextPolicy,
        changes: schedulePolicyChanges(current, nextPolicy)
      });
    }
    results.push({ connectorId: policy.connectorId, result });
  }
  await writeExternalConnectorSchedules({
    ...scheduleData,
    policies: Object.keys(EXTERNAL_CONNECTORS).map((connectorId) => policyMap.get(connectorId) || defaultExternalConnectorSchedule(connectorId))
  });
  return {
    role: "admin",
    requested: duePolicies.length,
    quotaBlocked: quotaBlockedPolicies.length,
    results,
    schedule: await externalConnectorScheduleReport()
  };
}

function resolveConnectorExecution(connectorId, requestedMode, diagnostics = null) {
  const id = normalizeExternalConnectorId(connectorId);
  const mode = normalizeConnectorMode(requestedMode);
  const connector = EXTERNAL_CONNECTORS[id] || EXTERNAL_CONNECTORS.naver_searchad;
  const diagnostic = diagnostics?.connectors?.find((item) => item.connectorId === id);
  const realReady = Boolean(diagnostic?.realReady);
  if (mode === "mock") {
    return { connector, requestedMode: mode, resolvedMode: "mock", fallbackReason: "" };
  }
  if (realReady) {
    return { connector, requestedMode: mode, resolvedMode: "real", fallbackReason: "" };
  }
  const fallbackReason = diagnostic?.configured
    ? "real adapter is not implemented yet; mock fallback used"
    : "API credentials are missing; mock fallback used";
  return { connector, requestedMode: mode, resolvedMode: "mock", fallbackReason };
}

function filterExternalConnectorRunLogs(data = {}, params) {
  const connectorId = params.get("connectorId");
  const source = params.get("source");
  const status = params.get("status");
  const resolvedMode = params.get("resolvedMode");
  const failureType = params.get("failureType");
  const jobId = params.get("jobId");
  const limit = Math.max(1, Math.min(1000, Number(params.get("limit") || 100)));
  const normalizedConnectorId = connectorId ? normalizeExternalConnectorId(connectorId) : "";
  const items = (data.items || [])
    .filter((item) => !normalizedConnectorId || item.connectorId === normalizedConnectorId)
    .filter((item) => !source || item.source === source || connectorSourceForId(item.connectorId) === source)
    .filter((item) => !status || item.status === status)
    .filter((item) => !resolvedMode || item.resolvedMode === resolvedMode)
    .filter((item) => !failureType || item.failureType === failureType)
    .filter((item) => !jobId || item.jobId === jobId)
    .slice(0, limit);
  return { ...data, items };
}

async function appendExternalConnectorRunLog(input = {}) {
  const logsData = await readExternalConnectorRunLogs();
  const now = new Date().toISOString();
  const item = {
    logId: input.logId || hashId("xclog", `${input.jobId || ""}|${input.connectorId || ""}|${input.startedAt || now}|${crypto.randomUUID()}`),
    connectorId: normalizeExternalConnectorId(input.connectorId || input.source),
    source: String(input.source || connectorSourceForId(input.connectorId)).trim(),
    jobId: String(input.jobId || "").trim(),
    signalId: String(input.signalId || "").trim(),
    signalType: String(input.signalType || "").trim(),
    scope: String(input.scope || "").trim(),
    companyId: String(input.companyId || "").trim(),
    keyword: String(input.keyword || "").trim(),
    requestedMode: normalizeConnectorMode(input.requestedMode),
    resolvedMode: normalizeConnectorMode(input.resolvedMode || "mock"),
    status: normalizeSignalJobStatus(input.status || "failed"),
    outcome: String(input.outcome || input.status || "failed").trim(),
    attemptCount: Number(input.attemptCount || 0),
    failureType: String(input.failureType || "").trim(),
    httpStatus: input.httpStatus === undefined || input.httpStatus === null ? null : Number(input.httpStatus),
    nextRetryAt: String(input.nextRetryAt || "").trim(),
    fallbackReason: String(input.fallbackReason || "").trim(),
    resultSummary: String(input.resultSummary || "").trim(),
    error: String(input.error || "").trim().slice(0, 500),
    retryable: Boolean(input.retryable),
    comparisonScore: input.comparisonScore === undefined || input.comparisonScore === null ? null : Number(input.comparisonScore),
    comparisonConfidence: String(input.comparisonConfidence || "").trim(),
    startedAt: input.startedAt || now,
    finishedAt: input.finishedAt || now,
    durationMs: Number(input.durationMs || 0),
    createdAt: now
  };
  const items = [item, ...(logsData.items || [])].slice(0, 2000);
  await writeExternalConnectorRunLogs({ ...logsData, items });
  return item;
}

function mockSeedForJob(job = {}) {
  const hex = crypto
    .createHash("sha1")
    .update([job.queueKey, job.keyword, job.source, job.signalType].join("|"), "utf8")
    .digest("hex")
    .slice(0, 8);
  return parseInt(hex, 16);
}

function confidenceFromScore(score) {
  if (score >= 85) return "A";
  if (score >= 70) return "B";
  if (score >= 55) return "C";
  return "D";
}

function mockInterestConnectorResult(job = {}, options = {}) {
  const keyword = String(job.keyword || "");
  const seed = mockSeedForJob(job);
  if (!keyword.trim() || keyword.includes("실패") || keyword.toLowerCase().includes("fail")) {
    return {
      outcome: "failed",
      status: "failed",
      error: "mock connector failed before external API integration"
    };
  }
  if (keyword.includes("검수") || keyword.toLowerCase().includes("review")) {
    return {
      outcome: "review_required",
      status: "review_required",
      reviewReason: "mock connector marked this keyword for admin review"
    };
  }

  const score = 45 + (seed % 51);
  const confidence = confidenceFromScore(score);
  const payload = {
    status: "succeeded",
    score,
    confidence,
    connectorMode: "mock",
    reviewedBy: "mock_connector",
    notes: `mock connector result for ${job.source}`
  };

  if (job.signalType === "naver_trend") {
    payload.trendIndex = score;
    payload.lastResultSummary = `mock trend index ${score}`;
  } else if (job.signalType === "sns_mentions") {
    const mentionCount = 15 + (seed % 920);
    const snsOptions = normalizeSnsOptions(options.sns || options);
    payload.mentionCount = mentionCount;
    payload.positiveMentionCount = Math.round(mentionCount * (0.45 + ((seed % 20) / 100)));
    payload.negativeMentionCount = Math.round(mentionCount * (0.05 + ((seed % 8) / 100)));
    payload.sampleSize = mentionCount;
    payload.sourceCoverage = 58 + (seed % 35);
    payload.snsProvider = snsOptions.provider;
    payload.snsPlatforms = snsOptions.platforms;
    payload.lastResultSummary = `mock sns mentions ${mentionCount}`;
  } else {
    const monthlySearchVolume = 400 + (seed % 48000);
    payload.monthlySearchVolume = monthlySearchVolume;
    payload.pcSearchVolume = Math.round(monthlySearchVolume * (0.28 + ((seed % 18) / 100)));
    payload.mobileSearchVolume = Math.max(0, monthlySearchVolume - payload.pcSearchVolume);
    payload.lastResultSummary = `mock monthly search ${monthlySearchVolume}`;
  }

  return {
    outcome: "succeeded",
    status: "succeeded",
    payload
  };
}

async function realInterestConnectorResult(job = {}, connector = {}, options = {}) {
  if (connector.connectorId === "naver_trend" && job.signalType === "naver_trend") {
    const keys = await readTrafficKeys();
    const metric = await collectNaverDatalabTrend(job.keyword, keys, options);
    if (!metric.collectable) {
      const failureType = metric.failureType || classifySearchAdFailure(metric.status || 0, metric.reason).failureType;
      if (metric.reviewRequired || failureType === "empty_result") {
        return {
          outcome: "review_required",
          status: "review_required",
          failureType,
          httpStatus: metric.status ?? null,
          reviewReason: metric.reason || "Naver DataLab returned an empty trend result."
        };
      }
      if (metric.retryable) {
        const nextRetryAt = nextRetryAtForFailure(failureType);
        return {
          outcome: "retry_scheduled",
          status: "retry_scheduled",
          failureType,
          httpStatus: metric.status ?? null,
          retryable: true,
          nextRetryAt,
          error: metric.reason || "Naver DataLab connector is temporarily retryable."
        };
      }
      return {
        outcome: "failed",
        status: "failed",
        failureType,
        httpStatus: metric.status ?? null,
        retryable: false,
        error: metric.reason || "Naver DataLab connector failed."
      };
    }

    const trendIndex = Math.round(clampNumber(metric.trendIndex, 0, 100));
    const confidenceScore = confidenceScoreForInterestSignal({
      status: "collected",
      signalType: "naver_trend",
      trendIndex,
      observedAt: new Date().toISOString(),
      reviewedBy: "naver_datalab_connector"
    });
    return {
      outcome: "succeeded",
      status: "succeeded",
      payload: {
        status: "succeeded",
        score: trendIndex,
        trendIndex,
        standardScore: trendIndex,
        normalizedScore: trendIndex,
        scoreGrade: confidenceGrade(trendIndex),
        confidenceScore,
        confidenceGrade: confidenceGrade(confidenceScore),
        formulaBasis: `Naver DataLab ${metric.requestOptions?.timeUnit || "date"} trend ratio weighted average 0-100`,
        confidence: confidenceFromScore(trendIndex),
        connectorMode: "real",
        reviewedBy: "naver_datalab_connector",
        rawMetricStatus: metric.status || 200,
        notes: `real Naver DataLab result ${metric.requestOptions?.startDate || ""}..${metric.requestOptions?.endDate || ""}`,
        lastResultSummary: `real trend index ${trendIndex} (${metric.pointCount || 0} points)`
      }
    };
  }

  if (connector.connectorId === "sns_mentions" && job.signalType === "sns_mentions") {
    const metric = await collectSnsMentionMetric(job.keyword, options);
    if (!metric.collectable) {
      const failureType = metric.failureType || classifySearchAdFailure(metric.status || 0, metric.reason).failureType;
      if (metric.reviewRequired || failureType === "empty_result") {
        return {
          outcome: "review_required",
          status: "review_required",
          failureType,
          httpStatus: metric.status ?? null,
          reviewReason: metric.reason || "SNS mention API returned an empty result."
        };
      }
      if (metric.retryable) {
        const nextRetryAt = nextRetryAtForFailure(failureType);
        return {
          outcome: "retry_scheduled",
          status: "retry_scheduled",
          failureType,
          httpStatus: metric.status ?? null,
          retryable: true,
          nextRetryAt,
          error: metric.reason || "SNS mention connector is temporarily retryable."
        };
      }
      return {
        outcome: "failed",
        status: "failed",
        failureType,
        httpStatus: metric.status ?? null,
        retryable: false,
        error: metric.reason || "SNS mention connector failed."
      };
    }

    const score = snsMentionStandardScore(metric);
    const confidenceScore = confidenceScoreForInterestSignal({
      status: "collected",
      signalType: "sns_mentions",
      mentionCount: metric.mentionCount,
      positiveMentionCount: metric.positiveMentionCount,
      negativeMentionCount: metric.negativeMentionCount,
      sampleSize: metric.sampleSize,
      sourceCoverage: metric.sourceCoverage,
      observedAt: new Date().toISOString(),
      reviewedBy: "sns_mentions_connector"
    });
    return {
      outcome: "succeeded",
      status: "succeeded",
      payload: {
        status: "succeeded",
        score,
        standardScore: score,
        normalizedScore: score,
        scoreGrade: confidenceGrade(score),
        confidenceScore,
        confidenceGrade: confidenceGrade(confidenceScore),
        formulaBasis: "log10(mentionCount + 1) with sentiment, sampleSize and sourceCoverage adjustment",
        confidence: confidenceFromScore(score),
        connectorMode: "real",
        reviewedBy: "sns_mentions_connector",
        mentionCount: metric.mentionCount,
        positiveMentionCount: metric.positiveMentionCount,
        negativeMentionCount: metric.negativeMentionCount,
        sampleSize: metric.sampleSize,
        sourceCoverage: metric.sourceCoverage,
        snsProvider: metric.provider,
        snsPlatforms: metric.platforms,
        rawMetricStatus: metric.status || 200,
        notes: `real SNS mention result ${metric.requestOptions?.startDate || ""}..${metric.requestOptions?.endDate || ""}`,
        lastResultSummary: `real sns mentions ${metric.mentionCount} (${metric.sourceCoverage}% coverage)`
      }
    };
  }

  if (connector.connectorId !== "naver_searchad" || job.signalType !== "search_volume") {
    return {
      outcome: "review_required",
      status: "review_required",
      reviewReason: "real connector adapter is prepared but not implemented for this source yet"
    };
  }

  const keys = await readTrafficKeys();
  const metric = await collectSearchAdMetric(job.keyword, keys);
  if (!metric.collectable) {
    const failureType = metric.failureType || classifySearchAdFailure(metric.status || 0, metric.reason).failureType;
    if (metric.reviewRequired || failureType === "empty_result") {
      return {
        outcome: "review_required",
        status: "review_required",
        failureType,
        httpStatus: metric.status ?? null,
        reviewReason: metric.reason || "Naver SearchAd returned an empty keyword result."
      };
    }
    if (metric.retryable) {
      const nextRetryAt = nextRetryAtForFailure(failureType);
      return {
        outcome: "retry_scheduled",
        status: "retry_scheduled",
        failureType,
        httpStatus: metric.status ?? null,
        retryable: true,
        nextRetryAt,
        error: metric.reason || "Naver SearchAd connector is temporarily retryable."
      };
    }
    return {
      outcome: "failed",
      status: "failed",
      failureType,
      httpStatus: metric.status ?? null,
      retryable: false,
      error: metric.reason || "Naver SearchAd connector returned no collectable keyword metric"
    };
  }

  const monthlySearchVolume = Number(metric.totalSearchVolume || 0);
  const score = Math.max(35, Math.min(100, Math.round(35 + Math.log10(monthlySearchVolume + 1) * 15)));
  const confidence = confidenceFromScore(score);
  const confidenceScore = confidenceScoreForInterestSignal({
    status: "collected",
    signalType: "search_volume",
    monthlySearchVolume,
    pcSearchVolume: Number(metric.monthlyPc || 0),
    mobileSearchVolume: Number(metric.monthlyMobile || 0),
    observedAt: new Date().toISOString(),
    reviewedBy: "naver_searchad_connector"
  });
  return {
    outcome: "succeeded",
    status: "succeeded",
    payload: {
      status: "succeeded",
      score,
      standardScore: score,
      normalizedScore: score,
      scoreGrade: confidenceGrade(score),
      confidenceScore,
      confidenceGrade: confidenceGrade(confidenceScore),
      formulaBasis: "log10(monthlySearchVolume + 1) scaled by Naver SearchAd keywordstool result",
      confidence,
      connectorMode: "real",
      reviewedBy: "naver_searchad_connector",
      monthlySearchVolume,
      pcSearchVolume: Number(metric.monthlyPc || 0),
      mobileSearchVolume: Number(metric.monthlyMobile || 0),
      rawMetricStatus: metric.status || 200,
      searchAdCompetition: metric.competition || "",
      notes: "real Naver SearchAd keywordstool result",
      lastResultSummary: `real monthly search ${monthlySearchVolume}`
    }
  };
}

async function runResolvedInterestConnector(job = {}, execution = {}) {
  if (execution.resolvedMode === "real") {
    return realInterestConnectorResult(job, execution.connector, execution.options || {});
  }
  const result = mockInterestConnectorResult(job, execution.options || {});
  if (result.payload) {
    result.payload = {
      ...result.payload,
      connectorMode: "mock",
      notes: execution.fallbackReason
        ? `${result.payload.notes || "mock connector result"}; ${execution.fallbackReason}`
        : result.payload.notes
    };
  }
  return result;
}

async function runInterestSignalJob(jobId, payload = {}) {
  const jobsData = await readInterestSignalJobs();
  const queuedJob = (jobsData.items || []).find((item) => item.jobId === jobId);
  if (!queuedJob) return null;
  const diagnostics = await externalConnectorDiagnostics();
  const execution = resolveConnectorExecution(
    payload.connectorId || payload.source || connectorIdForInterestJob(queuedJob),
    payload.connectorMode,
    diagnostics
  );
  execution.options = normalizeConnectorRunOptions(payload);
  const startedAt = new Date().toISOString();
  const started = await updateInterestSignalJob(jobId, {
    status: "collecting",
    lastError: "",
    reviewReason: "",
    connectorMode: execution.resolvedMode,
    lastResultSummary: execution.fallbackReason || "connector run started"
  });
  if (!started) return null;

  const attemptCount = Number(started.job.attemptCount || 0) + 1;
  const result = await runResolvedInterestConnector(started.job, execution);
  const finishedAt = new Date().toISOString();
  const baseLog = {
    connectorId: execution.connector.connectorId,
    source: execution.connector.source,
    jobId: started.job.jobId,
    signalId: started.job.signalId,
    signalType: started.job.signalType,
    scope: started.job.scope,
    companyId: started.job.companyId,
    keyword: started.job.keyword,
    requestedMode: execution.requestedMode,
    resolvedMode: execution.resolvedMode,
    attemptCount,
    fallbackReason: execution.fallbackReason,
    startedAt,
    finishedAt,
    durationMs: Date.parse(finishedAt) - Date.parse(startedAt)
  };
  if (result.outcome === "retry_scheduled") {
    const retry = await updateInterestSignalJob(jobId, {
      status: "retry_scheduled",
      attemptCount,
      lastError: result.error,
      failureType: result.failureType,
      nextRetryAt: result.nextRetryAt,
      connectorHttpStatus: result.httpStatus,
      connectorMode: execution.resolvedMode,
      lastResultSummary: `${result.failureType || "retry"}; next ${result.nextRetryAt || "-"}`
    });
    await appendExternalConnectorRunLog({
      ...baseLog,
      status: "retry_scheduled",
      outcome: "retry_scheduled",
      failureType: result.failureType,
      httpStatus: result.httpStatus,
      nextRetryAt: result.nextRetryAt,
      resultSummary: `${result.failureType || "retry_scheduled"}; next retry ${result.nextRetryAt || "-"}`,
      error: result.error,
      retryable: true
    });
    return { ...retry, connector: { connectorId: execution.connector.connectorId, mode: execution.resolvedMode, requestedMode: execution.requestedMode, outcome: "retry_scheduled", failureType: result.failureType, nextRetryAt: result.nextRetryAt, error: result.error, fallbackReason: execution.fallbackReason } };
  }
  if (result.outcome === "failed") {
    const failed = await updateInterestSignalJob(jobId, {
      status: "failed",
      attemptCount,
      lastError: result.error,
      failureType: result.failureType,
      connectorHttpStatus: result.httpStatus,
      connectorMode: execution.resolvedMode,
      lastResultSummary: result.error
    });
    await appendExternalConnectorRunLog({
      ...baseLog,
      status: "failed",
      outcome: "failed",
      failureType: result.failureType,
      httpStatus: result.httpStatus,
      resultSummary: result.error,
      error: result.error,
      retryable: Boolean(result.retryable)
    });
    return { ...failed, connector: { connectorId: execution.connector.connectorId, mode: execution.resolvedMode, requestedMode: execution.requestedMode, outcome: "failed", failureType: result.failureType, error: result.error, fallbackReason: execution.fallbackReason } };
  }
  if (result.outcome === "review_required") {
    const review = await updateInterestSignalJob(jobId, {
      status: "review_required",
      attemptCount,
      reviewReason: result.reviewReason,
      failureType: result.failureType,
      connectorHttpStatus: result.httpStatus,
      connectorMode: execution.resolvedMode,
      lastResultSummary: result.reviewReason,
      reviewedBy: execution.resolvedMode === "real" ? "real_connector" : "mock_connector"
    });
    await appendExternalConnectorRunLog({
      ...baseLog,
      status: "review_required",
      outcome: "review_required",
      failureType: result.failureType,
      httpStatus: result.httpStatus,
      resultSummary: result.reviewReason
    });
    return { ...review, connector: { connectorId: execution.connector.connectorId, mode: execution.resolvedMode, requestedMode: execution.requestedMode, outcome: "review_required", failureType: result.failureType, reviewReason: result.reviewReason, fallbackReason: execution.fallbackReason } };
  }

  const succeeded = await updateInterestSignalJob(jobId, {
    ...result.payload,
    attemptCount,
    connectorMode: execution.resolvedMode
  });
  await appendExternalConnectorRunLog({
    ...baseLog,
    status: "succeeded",
    outcome: "succeeded",
    httpStatus: result.payload.rawMetricStatus,
    comparisonScore: result.payload.score,
    comparisonConfidence: result.payload.confidence,
    resultSummary: result.payload.lastResultSummary || `score ${result.payload.score || "-"}`
  });
  return {
    ...succeeded,
    connector: {
      connectorId: execution.connector.connectorId,
      mode: execution.resolvedMode,
      requestedMode: execution.requestedMode,
      outcome: "succeeded",
      signalType: started.job.signalType,
      score: result.payload.score,
      confidence: result.payload.confidence,
      fallbackReason: execution.fallbackReason
    }
  };
}

async function runQueuedInterestSignalJobs(payload = {}) {
  const data = await readInterestSignalJobs();
  const limit = Math.max(1, Math.min(100, Number(payload.limit || 25)));
  const connectorId = payload.connectorId ? normalizeExternalConnectorId(payload.connectorId) : "";
  const source = String(payload.source || connectorSourceForId(connectorId) || "").trim();
  const jobs = (data.items || [])
    .filter((job) => job.status === "queued")
    .filter((job) => !source || job.source === source)
    .slice(0, limit);
  const results = [];
  for (const job of jobs) {
    const result = await runInterestSignalJob(job.jobId, payload);
    if (result) results.push(result);
  }
  const counts = results.reduce((acc, item) => {
    const status = item.job?.status || "unknown";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  return { requested: jobs.length, results, counts };
}

function observationFromOtaExposureItem(item = {}, company = {}, runId = "") {
  const channel = normalizeOtaChannelToken(item.channel || "ota");
  const observedAt = item.observedAt || new Date().toISOString();
  const record = buildObservationRecord({
    rank: item.rank ?? null,
    price: item.price || "",
    url: item.listingUrl || "",
    region: item.region || company.region || "",
    reservationRate: null,
    weeklyReservationRateDetail: "",
    channel,
    totalRooms: null,
    availableRooms: null
  }, {
    id: runId,
    productMode: "ota_exposure"
  }, company.companyId || item.companyId || "", {
    collectionMode: "ota_exposure",
    source: "ota_connector",
    observedAt,
    channel,
    searchScope: "ota_channel_presence",
    productKey: `ota:${channel}`
  });
  return {
    ...record,
    listingUrl: item.listingUrl || "",
    url: item.listingUrl || record.url || "",
    exposureScore: numberOrNull(item.exposureScore),
    otaExposure: {
      channel,
      listingUrl: item.listingUrl || "",
      exposed: Boolean(item.exposed),
      present: Boolean(item.exposed),
      exposureScore: numberOrNull(item.exposureScore),
      status: item.status || (item.exposed ? "exposed" : "not_exposed"),
      provider: item.provider || "",
      collectedBy: "external_connector"
    }
  };
}

async function saveOtaExposureObservations(company = {}, metric = {}, execution = {}) {
  const observations = await readPropertyObservations();
  const itemsById = new Map((observations.items || []).map((item) => [item.observationId, item]));
  const runId = `ota_${Date.now()}_${company.companyId || "target"}`;
  const records = (metric.items || []).map((item) => observationFromOtaExposureItem({
    ...item,
    provider: metric.provider || execution.connector?.connectorId || ""
  }, company, runId));
  for (const record of records) {
    itemsById.set(record.observationId, record);
  }
  const updated = await writeJsonFile(PROPERTY_OBSERVATIONS_FILE, {
    ...observations,
    items: [...itemsById.values()].sort((a, b) => String(b.observedAt).localeCompare(String(a.observedAt)))
  });
  return { records, counts: { observations: updated.items.length, observationsByMode: collectionModeCounts(updated.items) } };
}

function otaTargetCompanies(companies = [], payload = {}) {
  const companyId = String(payload.companyId || payload.otaCompanyId || "").trim();
  const region = compactKeyword(payload.region || payload.otaRegion || "");
  const category = compactKeyword(payload.category || payload.otaCategory || "");
  const query = compactKeyword(payload.companyName || payload.otaCompanyName || payload.q || "");
  const limit = Math.max(1, Math.min(50, Number(payload.limit || 10)));
  return companies
    .filter((company) => !companyId || company.companyId === companyId)
    .filter((company) => !region || compactKeyword(company.region).includes(region))
    .filter((company) => !category || compactKeyword(company.category).includes(category))
    .filter((company) => !query || compactKeyword(`${company.canonicalName} ${(company.aliases || []).join(" ")}`).includes(query))
    .slice(0, limit);
}

async function runOtaExposureConnector(payload = {}) {
  const [companiesData, diagnostics] = await Promise.all([
    readCompanyMaster(),
    externalConnectorDiagnostics()
  ]);
  const execution = resolveConnectorExecution("ota_exposure", payload.connectorMode, diagnostics);
  execution.options = normalizeConnectorRunOptions({ ...payload, connectorId: "ota_exposure" });
  const targets = otaTargetCompanies(companiesData.items || [], payload);
  const startedAt = new Date().toISOString();
  const results = [];

  for (const company of targets) {
    const companyStartedAt = new Date().toISOString();
    const metric = execution.resolvedMode === "real"
      ? await collectOtaExposureMetric(company, execution.options)
      : mockOtaExposureResult(company, execution.options);
    const finishedAt = new Date().toISOString();
    const baseLog = {
      connectorId: "ota_exposure",
      source: "ota",
      jobId: `ota:${company.companyId}:${Date.now()}`,
      companyId: company.companyId,
      keyword: company.canonicalName || company.companyId,
      requestedMode: execution.requestedMode,
      resolvedMode: execution.resolvedMode,
      fallbackReason: execution.fallbackReason,
      startedAt: companyStartedAt,
      finishedAt,
      durationMs: Date.parse(finishedAt) - Date.parse(companyStartedAt)
    };

    if (!metric.collectable) {
      const failureType = metric.failureType || classifySearchAdFailure(metric.status || 0, metric.reason).failureType;
      if (metric.reviewRequired || failureType === "empty_result") {
        await appendExternalConnectorRunLog({
          ...baseLog,
          status: "review_required",
          outcome: "review_required",
          failureType,
          httpStatus: metric.status ?? null,
          resultSummary: metric.reason || "OTA exposure result requires review."
        });
        results.push({ companyId: company.companyId, status: "review_required", failureType, reviewReason: metric.reason });
        continue;
      }
      if (metric.retryable) {
        const nextRetryAt = nextRetryAtForFailure(failureType);
        await appendExternalConnectorRunLog({
          ...baseLog,
          status: "retry_scheduled",
          outcome: "retry_scheduled",
          failureType,
          httpStatus: metric.status ?? null,
          nextRetryAt,
          resultSummary: `${failureType}; next retry ${nextRetryAt || "-"}`,
          error: metric.reason,
          retryable: true
        });
        results.push({ companyId: company.companyId, status: "retry_scheduled", failureType, nextRetryAt });
        continue;
      }
      await appendExternalConnectorRunLog({
        ...baseLog,
        status: "failed",
        outcome: "failed",
        failureType,
        httpStatus: metric.status ?? null,
        resultSummary: metric.reason || "OTA connector failed.",
        error: metric.reason,
        retryable: false
      });
      results.push({ companyId: company.companyId, status: "failed", failureType, error: metric.reason });
      continue;
    }

    const saved = await saveOtaExposureObservations(company, metric, execution);
    await appendExternalConnectorRunLog({
      ...baseLog,
      status: "succeeded",
      outcome: "succeeded",
      httpStatus: metric.status || 200,
      comparisonScore: metric.exposureScore,
      comparisonConfidence: confidenceFromScore(metric.exposureScore || 0),
      resultSummary: `OTA exposure ${metric.exposedChannelCount}/${metric.items.length} channels · score ${metric.exposureScore}`
    });
    results.push({
      companyId: company.companyId,
      status: "succeeded",
      exposureScore: metric.exposureScore,
      exposedChannelCount: metric.exposedChannelCount,
      channelCount: metric.items.length,
      observationCount: saved.records.length
    });
  }

  const counts = results.reduce((acc, item) => {
    acc[item.status] = (acc[item.status] || 0) + 1;
    return acc;
  }, {});
  return {
    connector: {
      connectorId: "ota_exposure",
      requestedMode: execution.requestedMode,
      mode: execution.resolvedMode,
      fallbackReason: execution.fallbackReason
    },
    requested: targets.length,
    startedAt,
    finishedAt: new Date().toISOString(),
    counts,
    results
  };
}

function publicInterestAggregate(label, signals = []) {
  const scored = signals
    .map((signal) => ({ ...signal, score: signalScore(signal) }))
    .filter((signal) => signal.score !== null);
  const avgScore = safeScore(average(scored.map((signal) => signal.score)));
  const confidence = safeScore(average(scored.map((signal) => signal.confidenceScore).filter((value) => value !== null && value !== undefined)));
  const byType = {};
  for (const type of ["naver_trend", "search_volume", "sns_mentions"]) {
    const typeRows = scored.filter((signal) => signal.signalType === type);
    byType[type] = {
      score: safeScore(average(typeRows.map((signal) => signal.score))),
      count: typeRows.length,
      grade: confidenceGrade(safeScore(average(typeRows.map((signal) => signal.score))) || 0)
    };
  }
  const latest = scored
    .sort((a, b) => String(b.observedAt || b.updatedAt || "").localeCompare(String(a.observedAt || a.updatedAt || "")))[0] || null;
  return {
    label,
    score: avgScore,
    grade: confidenceGrade(avgScore || 0),
    confidenceScore: confidence,
    confidenceGrade: confidenceGrade(confidence || 0),
    signalCount: scored.length,
    byType,
    primaryKeyword: latest?.keyword || "",
    basis: scored.length
      ? `표준점수 ${scored.length}개 신호 평균 · 신뢰도 ${confidenceGrade(confidence || 0)}`
      : "관심도 신호 보강 필요"
  };
}

function interestSignalsForIds(signals = [], companyIds = []) {
  const idSet = new Set(companyIds);
  return signals.filter((signal) => signal.companyId && idSet.has(signal.companyId));
}

function regionKeywordSignals(signals = [], region = "") {
  return signals.filter((signal) =>
    signal.scope === "region_keyword" &&
    (!region || compactKeyword(signal.region) === compactKeyword(region))
  );
}

function propertyAndRegionSignals(signals = [], companyIds = [], region = "") {
  return [
    ...interestSignalsForIds(signals, companyIds),
    ...regionKeywordSignals(signals, region)
  ];
}

function buildInterestAnalytics(target, visibleCompanies = [], interestSignals = []) {
  const enriched = enrichInterestSignals(interestSignals || []);
  const nationalIds = visibleCompanies.map((company) => company.companyId);
  const regionIds = visibleCompanies
    .filter((company) => !target.region || company.region === target.region)
    .map((company) => company.companyId);
  const comparableIds = visibleCompanies
    .filter((company) => company.companyId !== target.companyId)
    .filter((company) => !target.region || company.region === target.region)
    .filter((company) => !target.category || !company.category || company.category === target.category)
    .map((company) => company.companyId);
  const mySignals = propertyAndRegionSignals(enriched, [target.companyId], target.region);
  const comparableSignals = propertyAndRegionSignals(enriched, comparableIds, target.region);
  const regionSignals = propertyAndRegionSignals(enriched, regionIds, target.region);
  const nationalSignals = [
    ...interestSignalsForIds(enriched, nationalIds),
    ...enriched.filter((signal) => signal.scope === "region_keyword")
  ];
  return {
    national: publicInterestAggregate("전국 관심도", nationalSignals),
    region: publicInterestAggregate("지역 관심도", regionSignals),
    myProperty: publicInterestAggregate("내 숙소 관심도", mySignals),
    comparables: publicInterestAggregate("비교군 관심도", comparableSignals)
  };
}

function buildRegionCard(target, visibleCompanies = [], observations = [], leadtimeData = {}, interestSignals = [], interestAnalytics = null, locationCard = null, locationCardReadiness = null) {
  const region = target.region || "";
  const category = target.category || "";
  const profile = regionProfileForName(region);
  const regionCompanyIds = new Set(visibleCompanies.filter((company) => !region || company.region === region).map((company) => company.companyId));
  const regionObservations = observations.filter((item) => regionCompanyIds.has(item.companyId));
  const fastSearchObservations = regionObservations.filter((item) => item.collectionMode === "fast_search");
  const detailedObservations = regionObservations.filter((item) => item.collectionMode === "detailed_search");
  const otaObservations = regionObservations.filter((item) => item.collectionMode === "ota_exposure");
  const exposedOtaObservations = otaObservations.filter((item) => item.otaExposure?.exposed !== false);
  const regionPatterns = (leadtimeData.items || []).filter((item) => !region || item.region === region);
  const matchingSegments = (leadtimeData.segments || []).filter((item) =>
    (!region || item.region === region) && (!category || !item.category || item.category === category)
  );
  const channelNames = [...new Set(exposedOtaObservations.map((item) => item.channel).filter(Boolean))].slice(0, 8);
  const otaExposureScore = safeScore(average(otaObservations
    .map((item) => numberOrNull(item.exposureScore ?? item.otaExposure?.exposureScore))
    .filter((value) => value !== null)));
  const avgPace = average(regionPatterns.map((item) => item.bookingPaceScore));
  const avgConfidence = average(regionPatterns.map((item) => item.confidenceScore));
  const demandKeywords = regionCategoryKeywords(region, category, profile?.resources || []);
  const searchScore = regionObservationScore(regionObservations, observations);
  const segment = matchingSegments[0] || {};
  const enrichedSignals = enrichInterestSignals(interestSignals || []);
  const searchSignal = findInterestSignal(enrichedSignals, { region, signalType: "search_volume", scope: "region_keyword" }) ||
    findInterestSignal(enrichedSignals, { region, signalType: "naver_trend", scope: "region_keyword" });
  const snsSignal = findInterestSignal(enrichedSignals, { region, companyId: target.companyId, signalType: "sns_mentions", scope: "property_keyword" }) ||
    findInterestSignal(enrichedSignals, { region, signalType: "sns_mentions", scope: "region_keyword" });
  const regionalInterest = interestAnalytics?.region || null;
  const myInterest = interestAnalytics?.myProperty || null;
  const publicSearchSignal = publicSignal(searchSignal, {
    source: "observation_proxy",
    status: "derived",
    keyword: demandKeywords[0] || region,
    score: regionalInterest?.byType?.search_volume?.score ?? regionalInterest?.byType?.naver_trend?.score ?? searchScore,
    grade: regionalInterest?.grade || confidenceGrade(searchScore),
    confidenceGrade: regionalInterest?.confidenceGrade || null,
    basis: "지역/업종 자동 관측량 기반 초안 지표",
    updatedAt: null
  });
  const publicSnsSignal = publicSignal(snsSignal, {
    source: "not_connected",
    status: "pending_connector",
    keyword: demandKeywords[0] || region,
    score: myInterest?.byType?.sns_mentions?.score ?? null,
    grade: myInterest?.byType?.sns_mentions?.grade || null,
    confidenceGrade: myInterest?.confidenceGrade || null,
    basis: "SNS 언급량 수집 커넥터 연결 전 슬롯",
    updatedAt: null
  });

  const card = {
    region,
    category,
    province: profile?.provinceLabel || "",
    structure: {
      primary: profile?.primary || "확인필요",
      secondary: profile?.secondary || "확인필요",
      resources: profile?.resources || [],
      targetDemand: profile?.target || "",
      note: profile?.note || ""
    },
    access: {
      nearbyCities: nearbyRegionProfiles(profile),
      summary: profile?.target || "인접 도시 접근성 보강 필요"
    },
    demandKeywords,
    searchInterest: {
      source: publicSearchSignal.source,
      status: publicSearchSignal.status,
      keyword: publicSearchSignal.keyword,
      score: publicSearchSignal.score,
      grade: publicSearchSignal.grade,
      confidenceGrade: publicSearchSignal.confidenceGrade,
      fastSearchObservations: fastSearchObservations.length,
      detailedObservations: detailedObservations.length,
      basis: publicSearchSignal.basis,
      updatedAt: publicSearchSignal.updatedAt
    },
    snsInterest: {
      source: publicSnsSignal.source,
      status: publicSnsSignal.status,
      regionKeyword: demandKeywords[0] || region,
      propertyKeyword: target.name,
      keyword: publicSnsSignal.keyword,
      score: publicSnsSignal.score,
      grade: publicSnsSignal.grade,
      confidenceGrade: publicSnsSignal.confidenceGrade,
      basis: publicSnsSignal.basis,
      updatedAt: publicSnsSignal.updatedAt
    },
    otaExposure: {
      channelCount: channelNames.length,
      channels: channelNames,
      observationCount: otaObservations.length,
      exposedObservationCount: exposedOtaObservations.length,
      exposureScore: otaExposureScore,
      basis: otaObservations.length ? `OTA ${channelNames.length}개 채널 노출 관측 기준` : "OTA 노출 관측 대기"
    },
    leadtime: {
      patternCount: regionPatterns.length,
      segmentCount: matchingSegments.length,
      avgBookingPaceScore: safeScore(avgPace),
      avgConfidenceScore: safeScore(avgConfidence),
      confidenceGrade: confidenceGrade(safeScore(avgConfidence) || 0),
      segmentBookingPaceScore: segment.bookingPaceScore ?? null
    },
    strategyLinks: [
      profile?.primary ? `${profile.primary} 입지 특성에 맞춰 상품 메시지를 정리하십시오.` : "지역 구조 프로필을 보강해 입지 메시지를 정리하십시오.",
      channelNames.length < 2 ? "OTA 노출 채널이 적어 검색 수요를 충분히 받지 못할 수 있습니다." : "OTA 노출은 최소 기준을 충족하므로 채널별 가격 차이를 점검하십시오.",
      regionPatterns.length < 5 ? "리드타임 반복 관측을 늘려 다음달 예측 신뢰도를 높이십시오." : "지역 리드타임 패턴을 기준으로 성수 날짜 가격을 조정하십시오."
    ]
  };
  return applyPublicLocationCard(card, locationCard, locationCardReadiness);
}

function buildStrategySummary(targetCompany, myMetrics, comparableMetrics, regionalMetrics, nextMonth) {
  const messages = [];
  const priceCompare = compareMetric(myMetrics.price.avg, comparableMetrics.price.avg, false);
  const reservationCompare = compareMetric(myMetrics.reservation.avgRate, comparableMetrics.reservation.avgRate, true);
  const paceCompare = compareMetric(myMetrics.leadtime.avgBookingPaceScore, comparableMetrics.leadtime.avgBookingPaceScore, true);

  if (priceCompare.status === "above_baseline") {
    messages.push(`${nextMonth} 가격은 비교군 평균보다 높게 잡혀 있어, 예약률이 낮다면 주중/비성수 날짜부터 가격 방어선을 재점검하십시오.`);
  } else if (priceCompare.status === "below_baseline") {
    messages.push(`${nextMonth} 가격은 비교군보다 낮은 편입니다. 리드타임 예약 속도가 양호하면 주말/핵심 객실부터 단계적 인상을 테스트할 수 있습니다.`);
  } else {
    messages.push(`${nextMonth} 가격은 비교군과 유사합니다. 차별화는 제공사항, 노출 채널, 잔여 객실 운영에서 만드는 편이 적합합니다.`);
  }

  if (reservationCompare.status === "below_baseline" || paceCompare.status === "below_baseline") {
    messages.push("예약률 또는 booking pace가 비교군보다 약합니다. 네이버 예약 재고, 대표 이미지, 패키지 구성, OTA 노출 누락을 우선 점검하십시오.");
  } else if (reservationCompare.status === "above_baseline" || paceCompare.status === "above_baseline") {
    messages.push("예약 속도가 비교군보다 양호합니다. 성수 날짜는 할인보다 객실 타입별 가격 차등과 부가서비스 묶음 판매가 더 적합합니다.");
  } else {
    messages.push("예약 속도는 비교군과 큰 차이가 없습니다. 반복 관측을 늘려 주차별 변화를 본 뒤 가격 조정 폭을 결정하십시오.");
  }

  if (myMetrics.otaExposure.channelCount < Math.max(2, comparableMetrics.otaExposure.channelCount)) {
    messages.push("OTA 노출 채널 수가 충분하지 않습니다. 네이버 외 야놀자/NOL, 떠나요, 여기어때 노출 여부를 점검해 수요 접점을 넓히십시오.");
  }

  if (targetCompany.b2bVisibility === "reference_only") {
    messages.push("현재 B2B 리포트 노출은 참고 지표 수준입니다. 관리자 검수값을 보강하면 사업자용 추천 신뢰도를 올릴 수 있습니다.");
  } else if (targetCompany.b2bVisibility === "hidden") {
    messages.push("현재 B2B 노출 제외 상태입니다. 사업자 리포트 판매 대상에 포함하려면 관리자 검수에서 노출 상태를 변경해야 합니다.");
  }

  if (regionalMetrics.leadtime.patternCount < 5) {
    messages.push("지역 리드타임 샘플이 아직 적습니다. 같은 targetDate를 여러 날짜에 반복 관측해야 다음달 예측 신뢰도가 올라갑니다.");
  }

  return messages.slice(0, 5);
}

function metricSnapshot(myMetrics = {}, comparableMetrics = {}, regionalMetrics = {}, targetCompany = {}) {
  return {
    price: {
      myAvg: myMetrics.price?.avg ?? null,
      comparableAvg: comparableMetrics.price?.avg ?? null,
      position: compareMetric(myMetrics.price?.avg, comparableMetrics.price?.avg, false)
    },
    reservation: {
      myAvgRate: myMetrics.reservation?.avgRate ?? null,
      comparableAvgRate: comparableMetrics.reservation?.avgRate ?? null,
      position: compareMetric(myMetrics.reservation?.avgRate, comparableMetrics.reservation?.avgRate, true)
    },
    leadtime: {
      myBookingPaceScore: myMetrics.leadtime?.avgBookingPaceScore ?? null,
      comparableBookingPaceScore: comparableMetrics.leadtime?.avgBookingPaceScore ?? null,
      regionalPatternCount: regionalMetrics.leadtime?.patternCount || 0,
      confidenceGrade: myMetrics.leadtime?.confidenceGrade || "D",
      position: compareMetric(myMetrics.leadtime?.avgBookingPaceScore, comparableMetrics.leadtime?.avgBookingPaceScore, true)
    },
    interest: {
      myScore: myMetrics.interest?.score ?? null,
      myGrade: myMetrics.interest?.grade || "D",
      comparableScore: comparableMetrics.interest?.score ?? null,
      regionScore: regionalMetrics.interest?.score ?? null,
      confidenceGrade: myMetrics.interest?.confidenceGrade || "D",
      signalCount: myMetrics.interest?.signalCount || 0,
      position: compareMetric(myMetrics.interest?.score, comparableMetrics.interest?.score, true)
    },
    ota: {
      myChannelCount: myMetrics.otaExposure?.channelCount || 0,
      comparableChannelCount: comparableMetrics.otaExposure?.channelCount || 0,
      channels: myMetrics.otaExposure?.channels || []
    },
    b2b: {
      status: targetCompany.b2bVisibility || "reference_only",
      eligible: targetCompany.b2bVisibility === "eligible"
    },
    reliability: {
      companyConfidenceGrade: targetCompany.confidenceGrade || "D",
      observationCount: myMetrics.observationCount || 0
    }
  };
}

function strategyConfidenceGrade(metricKeys = [], snapshot = {}) {
  const gradeToScore = { A: 92, B: 76, C: 58, D: 38 };
  const scores = [];
  if (metricKeys.includes("interest")) scores.push(gradeToScore[snapshot.interest.confidenceGrade] || 38);
  if (metricKeys.includes("leadtime")) scores.push(gradeToScore[snapshot.leadtime.confidenceGrade] || 38);
  if (metricKeys.includes("reliability")) scores.push(gradeToScore[snapshot.reliability.companyConfidenceGrade] || 38);
  if (metricKeys.includes("reservation")) scores.push(snapshot.reservation.myAvgRate === null ? 42 : 70);
  if (metricKeys.includes("price")) scores.push(snapshot.price.myAvg === null ? 42 : 70);
  if (metricKeys.includes("ota")) scores.push(snapshot.ota.myChannelCount ? 72 : 45);
  return confidenceGrade(Math.round(average(scores.length ? scores : [45])));
}

function strategyExecutionMeta(category, priority, snapshot = {}) {
  const weakReservation = snapshot.reservation?.position?.status === "below_baseline";
  const weakLeadtime = snapshot.leadtime?.position?.status === "below_baseline";
  const weakInterest = snapshot.interest?.position?.status === "below_baseline";
  const lowChannels = (snapshot.ota?.myChannelCount || 0) < Math.max(2, snapshot.ota?.comparableChannelCount || 0);
  const highImpact = priority <= 1 || weakReservation || weakLeadtime || weakInterest || lowChannels;
  const difficulty = {
    "가격 전략": weakReservation || weakLeadtime ? "중간" : "낮음",
    "채널 전략": lowChannels ? "중간" : "낮음",
    "상품/패키지 전략": "중간",
    "콘텐츠/SNS 전략": weakInterest ? "중간" : "낮음",
    "리드타임 운영 전략": snapshot.leadtime?.regionalPatternCount < 5 ? "중간" : "낮음"
  }[category] || "중간";
  const timing = {
    "가격 전략": "다음달 판매 시작 전 7일 이내",
    "채널 전략": "이번 주 안에 노출/URL 검수",
    "상품/패키지 전략": "다음달 핵심 날짜 오픈 전",
    "콘텐츠/SNS 전략": "이번 주부터 주 2회 반복",
    "리드타임 운영 전략": "D-30, D-14, D-7 관측일"
  }[category] || "이번 주";
  return {
    difficulty,
    expectedEffect: highImpact ? "높음" : priority <= 3 ? "중간" : "보통",
    recommendedTiming: timing
  };
}

