function calibrationAuditEventRecords(items = []) {
  return items.flatMap((item) => {
    const events = [];
    if (item.proposedAt) {
      events.push({
        eventType: item.status === "draft" ? "drafted" : "proposed",
        eventAt: item.proposedAt,
        actor: item.proposedBy || "",
        versionId: item.versionId,
        versionNumber: item.versionNumber || 0,
        status: item.status || "",
        source: item.source || "",
        companyId: item.sourceCompanyId || "",
        targetMonth: item.sourceTargetMonth || "",
        reason: item.reason || ""
      });
    }
    if (item.approvedAt) {
      events.push({
        eventType: "approved",
        eventAt: item.approvedAt,
        actor: item.approvedBy || item.appliedBy || "",
        versionId: item.versionId,
        versionNumber: item.versionNumber || 0,
        status: item.status || "",
        source: item.source || "",
        companyId: item.sourceCompanyId || "",
        targetMonth: item.sourceTargetMonth || "",
        reason: item.reviewReason || item.reason || ""
      });
    } else if (item.appliedAt) {
      events.push({
        eventType: item.source === "rollback" ? "rollback" : "applied",
        eventAt: item.appliedAt,
        actor: item.appliedBy || "",
        versionId: item.versionId,
        versionNumber: item.versionNumber || 0,
        status: item.status || "",
        source: item.source || "",
        companyId: item.sourceCompanyId || "",
        targetMonth: item.sourceTargetMonth || "",
        reason: item.reason || item.reviewReason || ""
      });
    }
    if (item.rejectedAt) {
      events.push({
        eventType: "rejected",
        eventAt: item.rejectedAt,
        actor: item.rejectedBy || "",
        versionId: item.versionId,
        versionNumber: item.versionNumber || 0,
        status: item.status || "",
        source: item.source || "",
        companyId: item.sourceCompanyId || "",
        targetMonth: item.sourceTargetMonth || "",
        reason: item.rejectReason || item.reason || ""
      });
    }
    return events.map((event) => ({
      ...event,
      eventMonth: monthKey(event.eventAt)
    }));
  });
}

function calibrationAuditMonthly(events = [], versions = []) {
  const months = new Map();
  const ensure = (month) => {
    const key = month || "unknown";
    if (!months.has(key)) {
      months.set(key, {
        month: key,
        proposed: 0,
        drafted: 0,
        approved: 0,
        rejected: 0,
        rollback: 0,
        applied: 0,
        highRiskVersions: 0,
        mediumRiskVersions: 0,
        avgCandidateScoreImpact: 0,
        avgReadinessImpact: 0,
        avgPriorityImpact: 0,
        versionIds: []
      });
    }
    return months.get(key);
  };
  events.forEach((event) => {
    const row = ensure(event.eventMonth);
    if (row[event.eventType] !== undefined) row[event.eventType] += 1;
    if (!row.versionIds.includes(event.versionId)) row.versionIds.push(event.versionId);
  });
  versions.forEach((version) => {
    const row = ensure(monthKey(version.proposedAt || version.appliedAt || version.rejectedAt));
    const summary = version.impactSummary || {};
    if (Number(summary.highRiskCount || 0) > 0) row.highRiskVersions += 1;
    if (Number(summary.mediumRiskCount || 0) > 0) row.mediumRiskVersions += 1;
  });
  return [...months.values()]
    .map((row) => {
      const related = versions.filter((version) => row.versionIds.includes(version.versionId));
      return {
        ...row,
        totalEvents: row.proposed + row.drafted + row.approved + row.rejected + row.rollback + row.applied,
        avgCandidateScoreImpact: safeScore(average(related.map((version) => version.impactSummary?.candidateChanged))) || 0,
        avgReadinessImpact: safeScore(average(related.map((version) => version.impactSummary?.readinessChanged))) || 0,
        avgPriorityImpact: safeScore(average(related.map((version) => version.impactSummary?.priorityChanged))) || 0
      };
    })
    .sort((a, b) => String(b.month).localeCompare(String(a.month)));
}

function calibrationVersionExecutionPerformance(version = {}, executionPlans = []) {
  const companyId = version.sourceCompanyId || "";
  const targetMonth = version.sourceTargetMonth || "";
  const strategyIds = new Set((version.impactItems || []).map((item) => item.strategyId).filter(Boolean));
  const matchedPlans = (executionPlans || [])
    .filter((plan) => !companyId || plan.companyId === companyId)
    .filter((plan) => !targetMonth || plan.targetMonth === targetMonth)
    .filter((plan) => !strategyIds.size || strategyIds.has(plan.strategyId))
    .map((plan) => retrospectivePlan(plan));
  return {
    companyId,
    targetMonth,
    strategyCount: strategyIds.size,
    matchedPlans: matchedPlans.length,
    completedPlans: matchedPlans.filter((plan) => plan.isCompleted).length,
    overduePlans: matchedPlans.filter((plan) => plan.dueState === "overdue").length,
    avgProgress: safeScore(average(matchedPlans.map((plan) => plan.progress))) || 0,
    avgRetrospectiveScore: safeScore(average(matchedPlans.map((plan) => plan.score))) || 0,
    avgKpiAchievement: safeScore(average(matchedPlans.map((plan) => plan.kpiAchievement).filter((value) => value !== null))) || 0,
    plans: matchedPlans.slice(0, 10).map((plan) => ({
      planId: plan.planId,
      strategyId: plan.strategyId,
      title: plan.title,
      status: plan.status,
      dueState: plan.dueState,
      progress: plan.progress,
      score: plan.score,
      kpiAchievement: plan.kpiAchievement
    }))
  };
}

function calibrationAuditRiskLevel(version = {}) {
  const summary = version.impactSummary || {};
  if (Number(summary.highRiskCount || 0) > 0) return "high";
  if (Number(summary.mediumRiskCount || 0) > 0) return "medium";
  if ((version.impactItems || []).length || Object.keys(summary).length) return "low";
  return "none";
}

function normalizeCalibrationAuditStatus(value = "") {
  const status = String(value || "").trim().toLowerCase();
  if (["all", "any", "*"].includes(status)) return "";
  if (status === "draft") return "drafted";
  return status;
}

function normalizeCalibrationAuditRisk(value = "") {
  const risk = String(value || "").trim().toLowerCase();
  if (["all", "any", "*"].includes(risk)) return "";
  return ["high", "medium", "low", "none"].includes(risk) ? risk : "";
}

function normalizeCalibrationAuditReviewStatus(value = "") {
  const status = String(value || "").trim().toLowerCase();
  if (["all", "any", "*"].includes(status)) return "";
  if (["pending", "in_review", "action_required", "resolved", "deferred"].includes(status)) return status;
  return status ? "pending" : "";
}

function defaultCalibrationAuditReview(version = {}) {
  return {
    reviewId: version.versionId ? hashId("lcar", version.versionId) : "",
    versionId: version.versionId || "",
    companyId: version.sourceCompanyId || "",
    targetMonth: version.sourceTargetMonth || "",
    auditMonth: version.eventMonth || monthKey(version.proposedAt || version.appliedAt || version.rejectedAt),
    reviewStatus: "pending",
    adminMemo: "",
    followUpOwner: "",
    followUpDueDate: "",
    updatedBy: "",
    updatedAt: null,
    createdAt: null
  };
}

function normalizeCalibrationAuditReview(input = {}, version = {}) {
  const base = defaultCalibrationAuditReview(version);
  const dueDate = isoDate(input.followUpDueDate || input.dueDate || base.followUpDueDate);
  return {
    ...base,
    ...input,
    reviewId: input.reviewId || base.reviewId || hashId("lcar", input.versionId || base.versionId),
    versionId: String(input.versionId || base.versionId || "").trim(),
    companyId: String(input.companyId || input.sourceCompanyId || base.companyId || "").trim(),
    targetMonth: String(input.targetMonth || input.sourceTargetMonth || base.targetMonth || "").trim(),
    auditMonth: String(input.auditMonth || input.eventMonth || base.auditMonth || "").trim(),
    reviewStatus: normalizeCalibrationAuditReviewStatus(input.reviewStatus || base.reviewStatus) || "pending",
    adminMemo: String(input.adminMemo || input.memo || "").trim(),
    followUpOwner: String(input.followUpOwner || input.owner || input.assignee || "").trim(),
    followUpDueDate: dueDate,
    updatedBy: String(input.updatedBy || input.reviewedBy || base.updatedBy || "").trim(),
    updatedAt: input.updatedAt || base.updatedAt || null,
    createdAt: input.createdAt || base.createdAt || null
  };
}

function calibrationAuditReviewIsOverdue(review = {}) {
  return Boolean(
    review.followUpDueDate &&
    review.followUpDueDate < kstDate(0) &&
    !["resolved", "deferred"].includes(review.reviewStatus)
  );
}

function calibrationAuditReviewDueState(review = {}) {
  if (!review.followUpDueDate) return "no_due";
  if (calibrationAuditReviewIsOverdue(review)) return "overdue";
  const days = dateDiffDays(kstDate(0), review.followUpDueDate);
  if (Number.isFinite(days) && days <= 7) return "this_week";
  return "upcoming";
}

function calibrationAuditReviewIsOpen(review = {}) {
  return !["resolved", "deferred"].includes(review.reviewStatus || "pending");
}

function calibrationAuditReviewMap(data = {}) {
  return new Map((data.items || [])
    .map((item) => normalizeCalibrationAuditReview(item))
    .filter((item) => item.versionId)
    .map((item) => [item.versionId, item]));
}

const CALIBRATION_AUDIT_REVIEW_LOG_FIELDS = Object.freeze([
  "reviewStatus",
  "followUpOwner",
  "followUpDueDate",
  "adminMemo"
]);

function calibrationAuditReviewSnapshot(review = {}) {
  return {
    reviewStatus: review.reviewStatus || "pending",
    followUpOwner: review.followUpOwner || "",
    followUpDueDate: review.followUpDueDate || "",
    adminMemo: review.adminMemo || ""
  };
}

function calibrationAuditReviewChangedFields(before = {}, after = {}, allowedFields = CALIBRATION_AUDIT_REVIEW_LOG_FIELDS) {
  return allowedFields.filter((field) => String(before[field] || "") !== String(after[field] || ""));
}

function calibrationAuditReviewHistorySummaryText(log = {}) {
  const before = log.before || {};
  const after = log.after || {};
  return (log.changedFields || []).map((field) => `${field}: ${before[field] || "-"} -> ${after[field] || "-"}`).join(" / ");
}

function normalizeCalibrationAuditReviewLog(input = {}) {
  const changedAt = input.changedAt || new Date().toISOString();
  const operationType = String(input.operationType || "single").trim().toLowerCase() === "bulk" ? "bulk" : "single";
  const before = calibrationAuditReviewSnapshot(input.before || {});
  const after = calibrationAuditReviewSnapshot(input.after || {});
  const changedFields = (Array.isArray(input.changedFields) ? input.changedFields : calibrationAuditReviewChangedFields(before, after))
    .filter((field) => CALIBRATION_AUDIT_REVIEW_LOG_FIELDS.includes(field));
  const operationId = String(input.operationId || hashId("lcaop", `${operationType}|${changedAt}|${crypto.randomUUID()}`)).trim();
  const versionId = String(input.versionId || input.after?.versionId || input.before?.versionId || "").trim();
  return {
    logId: String(input.logId || hashId("lcal", `${operationId}|${versionId}|${changedFields.join("|")}|${changedAt}`)).trim(),
    operationId,
    operationType,
    versionId,
    companyId: String(input.companyId || input.after?.companyId || input.before?.companyId || "").trim(),
    targetMonth: String(input.targetMonth || input.after?.targetMonth || input.before?.targetMonth || "").trim(),
    auditMonth: String(input.auditMonth || input.after?.auditMonth || input.before?.auditMonth || "").trim(),
    changedBy: String(input.changedBy || input.updatedBy || "").trim() || "admin",
    changedAt,
    changedFields,
    before,
    after,
    summary: String(input.summary || calibrationAuditReviewHistorySummaryText({ changedFields, before, after })).trim()
  };
}

function calibrationAuditReviewLogMap(data = {}) {
  const map = new Map();
  (data.items || []).map(normalizeCalibrationAuditReviewLog).forEach((log) => {
    if (!log.versionId) return;
    const current = map.get(log.versionId) || [];
    current.push(log);
    map.set(log.versionId, current);
  });
  map.forEach((logs) => logs.sort((a, b) => String(b.changedAt || "").localeCompare(String(a.changedAt || ""))));
  return map;
}

function calibrationAuditReviewLogSummary(logs = []) {
  const sorted = [...logs].map(normalizeCalibrationAuditReviewLog)
    .sort((a, b) => String(b.changedAt || "").localeCompare(String(a.changedAt || "")));
  const latest = sorted[0] || null;
  return {
    count: sorted.length,
    latestChangedAt: latest?.changedAt || "",
    latestChangedBy: latest?.changedBy || "",
    latestOperationType: latest?.operationType || "",
    latestChangedFields: latest?.changedFields || [],
    latestSummary: latest?.summary || "",
    recent: sorted.slice(0, 5)
  };
}

function calibrationAuditBulkOperations(logs = []) {
  const operations = new Map();
  logs.map(normalizeCalibrationAuditReviewLog)
    .filter((log) => log.operationType === "bulk")
    .forEach((log) => {
      const current = operations.get(log.operationId) || {
        operationId: log.operationId,
        operationType: "bulk",
        changedAt: log.changedAt,
        changedBy: log.changedBy,
        itemCount: 0,
        changedFields: new Set(),
        versionIds: []
      };
      current.itemCount += 1;
      current.changedAt = String(log.changedAt || "").localeCompare(String(current.changedAt || "")) > 0 ? log.changedAt : current.changedAt;
      current.changedBy = log.changedBy || current.changedBy;
      log.changedFields.forEach((field) => current.changedFields.add(field));
      current.versionIds.push(log.versionId);
      operations.set(log.operationId, current);
    });
  return [...operations.values()].map((item) => ({
    ...item,
    changedFields: [...item.changedFields],
    versionIds: [...new Set(item.versionIds)]
  })).sort((a, b) => String(b.changedAt || "").localeCompare(String(a.changedAt || "")));
}

function calibrationAuditReviewTerminalStatus(status = "") {
  return ["resolved", "deferred"].includes(String(status || "").trim());
}

function calibrationAuditReviewOpenStatus(status = "") {
  return !calibrationAuditReviewTerminalStatus(status);
}

function calibrationAuditLogMonth(log = {}) {
  return monthKey(log.changedAt || "") || "unknown";
}

function calibrationAuditLogOwner(log = {}) {
  return String(log.after?.followUpOwner || log.before?.followUpOwner || log.changedBy || "unassigned").trim() || "unassigned";
}

function calibrationAuditLogChangedDate(log = {}) {
  return String(log.changedAt || "").slice(0, 10);
}

function calibrationAuditLogHoursBetween(startIso = "", endIso = "") {
  const start = new Date(startIso);
  const end = new Date(endIso);
  if (!Number.isFinite(start.getTime()) || !Number.isFinite(end.getTime())) return null;
  return Math.max(0, (end - start) / 3600000);
}

function calibrationAuditProcessingDaysForLog(log = {}, firstLogByVersion = new Map()) {
  if (!calibrationAuditReviewTerminalStatus(log.after?.reviewStatus)) return null;
  const first = firstLogByVersion.get(log.versionId);
  if (!first) return null;
  const hours = calibrationAuditLogHoursBetween(first.changedAt, log.changedAt);
  return hours === null ? null : Number((hours / 24).toFixed(2));
}

function calibrationAuditLogWasDelayed(log = {}) {
  const dueDate = log.before?.followUpDueDate || log.after?.followUpDueDate || "";
  const changedDate = calibrationAuditLogChangedDate(log);
  return Boolean(
    dueDate &&
    changedDate &&
    dueDate < changedDate &&
    calibrationAuditReviewOpenStatus(log.before?.reviewStatus)
  );
}

function calibrationAuditQualityBucket(base = {}) {
  return {
    month: base.month || "",
    owner: base.owner || "",
    totalChanges: 0,
    singleChanges: 0,
    bulkItemChanges: 0,
    bulkOperations: new Set(),
    memoChangeCount: 0,
    reopenCount: 0,
    delayedCandidates: 0,
    delayedResolved: 0,
    unresolvedDelayedItems: 0,
    terminalChanges: 0,
    processingDays: [],
    lastChangedAt: ""
  };
}

function calibrationAuditSlaEvaluation(metrics = {}) {
  const avgDays = metrics.avgProcessingDays;
  const delayedRate = Number(metrics.delayedResolutionRate || 0);
  const reopenRate = Number(metrics.reopenRate || 0);
  const unresolvedDelayed = Number(metrics.unresolvedDelayedItems || 0);
  const hasDelayResolutionSample = Number(metrics.delayedCandidates || 0) > unresolvedDelayed;
  const issues = [];
  if (avgDays !== null && avgDays !== undefined && Number(avgDays) > 5) {
    issues.push({ key: "avg_processing_days", severity: "danger", label: "Average processing time over 5 days" });
  } else if (avgDays !== null && avgDays !== undefined && Number(avgDays) > 2) {
    issues.push({ key: "avg_processing_days", severity: "warning", label: "Average processing time over 2 days" });
  }
  if (hasDelayResolutionSample && delayedRate < 60) {
    issues.push({ key: "delayed_resolution_rate", severity: "danger", label: "Delay resolution below 60%" });
  } else if (hasDelayResolutionSample && delayedRate < 80) {
    issues.push({ key: "delayed_resolution_rate", severity: "warning", label: "Delay resolution below 80%" });
  }
  if (reopenRate > 20) {
    issues.push({ key: "reopen_rate", severity: "danger", label: "Reopen rate over 20%" });
  } else if (reopenRate > 10) {
    issues.push({ key: "reopen_rate", severity: "warning", label: "Reopen rate over 10%" });
  }
  if (unresolvedDelayed > 2) {
    issues.push({ key: "unresolved_delayed_items", severity: "danger", label: "More than 2 unresolved delayed items" });
  } else if (unresolvedDelayed > 0) {
    issues.push({ key: "unresolved_delayed_items", severity: "warning", label: "Unresolved delayed items remain" });
  }
  const hasDanger = issues.some((item) => item.severity === "danger");
  const hasWarning = issues.some((item) => item.severity === "warning");
  const level = hasDanger ? "danger" : hasWarning ? "warning" : "normal";
  return {
    level,
    label: level === "danger" ? "Risk" : level === "warning" ? "Watch" : "Normal",
    improvementItems: issues,
    criteria: {
      normal: "avgProcessingDays <= 2, delayedResolutionRate >= 80%, reopenRate <= 10%, unresolvedDelayedItems = 0",
      warning: "avgProcessingDays <= 5, delayedResolutionRate >= 60% when resolution samples exist, reopenRate <= 20%, unresolvedDelayedItems <= 2",
      danger: "Any metric outside warning criteria"
    }
  };
}

function finalizeCalibrationAuditQualityBucket(bucket = {}) {
  const processingAverage = average(bucket.processingDays);
  const totalChanges = bucket.totalChanges || 0;
  const metrics = {
    month: bucket.month || "",
    owner: bucket.owner || "",
    totalChanges,
    singleChanges: bucket.singleChanges || 0,
    bulkItemChanges: bucket.bulkItemChanges || 0,
    bulkOperations: bucket.bulkOperations instanceof Set ? bucket.bulkOperations.size : Number(bucket.bulkOperations || 0),
    memoChangeCount: bucket.memoChangeCount || 0,
    reopenCount: bucket.reopenCount || 0,
    reopenRate: totalChanges ? Math.round((Number(bucket.reopenCount || 0) / totalChanges) * 100) : 0,
    delayedCandidates: bucket.delayedCandidates || 0,
    delayedResolved: bucket.delayedResolved || 0,
    delayedResolutionRate: bucket.delayedCandidates ? Math.round((bucket.delayedResolved / bucket.delayedCandidates) * 100) : 0,
    unresolvedDelayedItems: bucket.unresolvedDelayedItems || 0,
    terminalChanges: bucket.terminalChanges || 0,
    avgProcessingDays: processingAverage === null ? null : Number(processingAverage.toFixed(2)),
    lastChangedAt: bucket.lastChangedAt || ""
  };
  return {
    ...metrics,
    sla: calibrationAuditSlaEvaluation(metrics)
  };
}

function applyCalibrationAuditQualityLog(bucket = {}, log = {}, firstLogByVersion = new Map()) {
  bucket.totalChanges += 1;
  if (log.operationType === "bulk") {
    bucket.bulkItemChanges += 1;
    if (log.operationId) bucket.bulkOperations.add(log.operationId);
  } else {
    bucket.singleChanges += 1;
  }
  if ((log.changedFields || []).includes("adminMemo")) bucket.memoChangeCount += 1;
  if (calibrationAuditReviewTerminalStatus(log.before?.reviewStatus) && calibrationAuditReviewOpenStatus(log.after?.reviewStatus)) {
    bucket.reopenCount += 1;
  }
  const wasDelayed = calibrationAuditLogWasDelayed(log);
  if (wasDelayed) bucket.delayedCandidates += 1;
  if (wasDelayed && calibrationAuditReviewTerminalStatus(log.after?.reviewStatus)) bucket.delayedResolved += 1;
  const processingDays = calibrationAuditProcessingDaysForLog(log, firstLogByVersion);
  if (processingDays !== null) {
    bucket.processingDays.push(processingDays);
    bucket.terminalChanges += 1;
  }
  if (!bucket.lastChangedAt || String(log.changedAt || "").localeCompare(bucket.lastChangedAt) > 0) {
    bucket.lastChangedAt = log.changedAt || bucket.lastChangedAt;
  }
}

function applyCalibrationAuditQualityLatestState(bucket = {}, log = {}) {
  const dueDate = log.after?.followUpDueDate || "";
  const isUnresolvedDelayed = Boolean(
    dueDate &&
    dueDate < kstDate(0) &&
    calibrationAuditReviewOpenStatus(log.after?.reviewStatus)
  );
  if (isUnresolvedDelayed) bucket.unresolvedDelayedItems += 1;
}

function calibrationAuditOperationQuality(logs = []) {
  const normalized = logs.map(normalizeCalibrationAuditReviewLog)
    .filter((log) => log.versionId && log.changedAt)
    .sort((a, b) => String(a.changedAt || "").localeCompare(String(b.changedAt || "")));
  const firstLogByVersion = new Map();
  const latestLogByVersion = new Map();
  normalized.forEach((log) => {
    if (!firstLogByVersion.has(log.versionId)) firstLogByVersion.set(log.versionId, log);
    latestLogByVersion.set(log.versionId, log);
  });
  const summaryBucket = calibrationAuditQualityBucket();
  const monthlyMap = new Map();
  const ownerMap = new Map();
  const ownerMonthMap = new Map();
  normalized.forEach((log) => {
    const month = calibrationAuditLogMonth(log);
    const owner = calibrationAuditLogOwner(log);
    if (!monthlyMap.has(month)) monthlyMap.set(month, calibrationAuditQualityBucket({ month }));
    if (!ownerMap.has(owner)) ownerMap.set(owner, calibrationAuditQualityBucket({ owner }));
    const ownerMonthKey = `${month}|${owner}`;
    if (!ownerMonthMap.has(ownerMonthKey)) ownerMonthMap.set(ownerMonthKey, calibrationAuditQualityBucket({ month, owner }));
    [summaryBucket, monthlyMap.get(month), ownerMap.get(owner), ownerMonthMap.get(ownerMonthKey)]
      .forEach((bucket) => applyCalibrationAuditQualityLog(bucket, log, firstLogByVersion));
  });
  latestLogByVersion.forEach((log) => {
    const month = calibrationAuditLogMonth(log);
    const owner = calibrationAuditLogOwner(log);
    const ownerMonthKey = `${month}|${owner}`;
    if (!monthlyMap.has(month)) monthlyMap.set(month, calibrationAuditQualityBucket({ month }));
    if (!ownerMap.has(owner)) ownerMap.set(owner, calibrationAuditQualityBucket({ owner }));
    if (!ownerMonthMap.has(ownerMonthKey)) ownerMonthMap.set(ownerMonthKey, calibrationAuditQualityBucket({ month, owner }));
    [summaryBucket, monthlyMap.get(month), ownerMap.get(owner), ownerMonthMap.get(ownerMonthKey)]
      .forEach((bucket) => applyCalibrationAuditQualityLatestState(bucket, log));
  });
  const monthly = [...monthlyMap.values()]
    .map(finalizeCalibrationAuditQualityBucket)
    .sort((a, b) => String(b.month || "").localeCompare(String(a.month || "")));
  const ownerPerformance = [...ownerMap.values()]
    .map(finalizeCalibrationAuditQualityBucket)
    .sort((a, b) => b.totalChanges - a.totalChanges || String(a.owner).localeCompare(String(b.owner)));
  return {
    summary: finalizeCalibrationAuditQualityBucket(summaryBucket),
    latestMonth: monthly[0] || finalizeCalibrationAuditQualityBucket(calibrationAuditQualityBucket({ month: monthKey(kstDate(0)) })),
    monthly,
    ownerPerformance,
    ownerMonthly: [...ownerMonthMap.values()]
      .map(finalizeCalibrationAuditQualityBucket)
      .sort((a, b) => String(b.month || "").localeCompare(String(a.month || "")) || b.totalChanges - a.totalChanges)
  };
}

function normalizeCalibrationSlaActionPriority(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["urgent", "high", "medium", "low"].includes(text)) return text;
  return "";
}

function normalizeCalibrationSlaActionStatus(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["candidate", "planned", "in_progress", "done", "dismissed"].includes(text)) return text;
  return "candidate";
}

function normalizeCalibrationSlaActionStatusFilter(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["candidate", "planned", "in_progress", "done", "dismissed"].includes(text)) return text;
  return "";
}

function calibrationSlaActionPriorityRank(priority = "") {
  const rank = { urgent: 0, high: 1, medium: 2, low: 3 };
  return rank[normalizeCalibrationSlaActionPriority(priority)] ?? 2;
}

function shiftCalibrationSlaActionPriority(priority = "medium", direction = "neutral", action = {}) {
  const order = ["urgent", "high", "medium", "low"];
  const currentIndex = calibrationSlaActionPriorityRank(priority);
  let nextIndex = currentIndex;
  if (direction === "boost") nextIndex = Math.max(0, currentIndex - 1);
  if (direction === "downgrade") nextIndex = Math.min(order.length - 1, currentIndex + 1);
  const severity = String(action.slaLevel || action.severity || "").trim().toLowerCase();
  if (severity === "danger") nextIndex = Math.min(nextIndex, 1);
  return order[nextIndex] || "medium";
}

function calibrationSlaActionPriorityForIssue(issue = {}) {
  if (issue.severity === "danger") return issue.key === "unresolved_delayed_items" ? "urgent" : "high";
  if (issue.severity === "warning") return "medium";
  return "low";
}

function calibrationSlaActionRecommendation(issue = {}, metrics = {}) {
  if (issue.key === "avg_processing_days") {
    return "Split the oldest follow-up items by owner, set near-term due dates, and review blockers until average processing time returns to SLA.";
  }
  if (issue.key === "delayed_resolution_rate") {
    return "Create a focused overdue-resolution pass, assign unresolved items to owners, and close or defer stale follow-ups with explicit reasons.";
  }
  if (issue.key === "reopen_rate") {
    return "Review recently reopened items, tighten completion criteria, and add a second check before marking high-risk follow-ups done.";
  }
  if (issue.key === "unresolved_delayed_items") {
    return `Resolve or reassign ${Number(metrics.unresolvedDelayedItems || 0)} open delayed follow-up item(s) and update due dates for items that need deferral.`;
  }
  return "Review the SLA warning, identify the source metric, and assign a corrective owner with a concrete target date.";
}

function calibrationSlaActionRootMetric(issue = {}, metrics = {}) {
  if (issue.key === "avg_processing_days") return `avgProcessingDays=${metrics.avgProcessingDays ?? "-"}`;
  if (issue.key === "delayed_resolution_rate") return `delayedResolutionRate=${metrics.delayedResolutionRate || 0}%`;
  if (issue.key === "reopen_rate") return `reopenRate=${metrics.reopenRate || 0}%`;
  if (issue.key === "unresolved_delayed_items") return `unresolvedDelayedItems=${metrics.unresolvedDelayedItems || 0}`;
  return issue.key || "sla";
}

function calibrationSlaActionSourceLabel(scopeType = "", metrics = {}) {
  if (scopeType === "month") return `Month ${metrics.month || "-"}`;
  if (scopeType === "owner") return `Owner ${metrics.owner || "unassigned"}`;
  return "Overall SLA";
}

function calibrationSlaActionSourceKey(scopeType = "", metrics = {}, issue = {}) {
  return [
    scopeType || "summary",
    metrics.month || "",
    metrics.owner || "",
    issue.key || "",
    issue.severity || ""
  ].join("|");
}

function normalizeCalibrationSlaAction(input = {}) {
  const sourceKey = String(input.sourceKey || "").trim();
  const now = new Date().toISOString();
  const issueKey = String(input.issueKey || "").trim();
  const severity = String(input.severity || "").trim().toLowerCase();
  const priority = normalizeCalibrationSlaActionPriority(input.priority) || (severity === "danger" ? "high" : "medium");
  return {
    actionId: String(input.actionId || hashId("lcsa", sourceKey || `${issueKey}|${now}`)).trim(),
    sourceKey,
    sourceType: String(input.sourceType || "summary").trim() || "summary",
    sourceLabel: String(input.sourceLabel || "").trim(),
    month: String(input.month || "").trim(),
    owner: String(input.owner || "").trim(),
    slaLevel: String(input.slaLevel || "").trim() || (severity === "danger" ? "danger" : "warning"),
    issueKey,
    severity: severity || "warning",
    rootMetric: String(input.rootMetric || "").trim(),
    recommendation: String(input.recommendation || "").trim(),
    priority,
    assignee: String(input.assignee || input.owner || "").trim(),
    targetDate: isoDate(input.targetDate || input.dueDate || ""),
    status: normalizeCalibrationSlaActionStatus(input.status),
    createdAt: input.createdAt || now,
    createdBy: String(input.createdBy || input.updatedBy || "admin").trim() || "admin",
    updatedAt: input.updatedAt || now,
    updatedBy: String(input.updatedBy || input.createdBy || "admin").trim() || "admin",
    completedAt: input.completedAt || "",
    completedBy: String(input.completedBy || "").trim(),
    completionQualitySnapshot: input.completionQualitySnapshot && typeof input.completionQualitySnapshot === "object"
      ? input.completionQualitySnapshot
      : null,
    historyAdjustment: input.historyAdjustment && typeof input.historyAdjustment === "object"
      ? input.historyAdjustment
      : null,
    sourceMetrics: input.sourceMetrics && typeof input.sourceMetrics === "object" ? input.sourceMetrics : {}
  };
}

function calibrationSlaActionCandidate(scopeType = "", metrics = {}, issue = {}) {
  const sourceKey = calibrationSlaActionSourceKey(scopeType, metrics, issue);
  const priority = calibrationSlaActionPriorityForIssue(issue);
  const targetOffset = priority === "urgent" ? 2 : priority === "high" ? 4 : 7;
  return normalizeCalibrationSlaAction({
    actionId: hashId("lcsa", sourceKey),
    sourceKey,
    sourceType: scopeType || "summary",
    sourceLabel: calibrationSlaActionSourceLabel(scopeType, metrics),
    month: metrics.month || "",
    owner: metrics.owner || "",
    slaLevel: metrics.sla?.level || issue.severity || "warning",
    issueKey: issue.key || "",
    severity: issue.severity || "warning",
    rootMetric: calibrationSlaActionRootMetric(issue, metrics),
    recommendation: calibrationSlaActionRecommendation(issue, metrics),
    priority,
    assignee: metrics.owner || "",
    targetDate: kstDate(targetOffset),
    status: "candidate",
    createdBy: "system",
    updatedBy: "system",
    sourceMetrics: {
      totalChanges: metrics.totalChanges || 0,
      avgProcessingDays: metrics.avgProcessingDays,
      delayedResolutionRate: metrics.delayedResolutionRate || 0,
      reopenRate: metrics.reopenRate || 0,
      unresolvedDelayedItems: metrics.unresolvedDelayedItems || 0,
      memoChangeCount: metrics.memoChangeCount || 0
    }
  });
}

function calibrationSlaActionCandidatesFromQuality(quality = {}) {
  const rows = [
    { scopeType: "summary", metrics: quality.summary || {} },
    ...(quality.monthly || []).map((metrics) => ({ scopeType: "month", metrics })),
    ...(quality.ownerPerformance || []).map((metrics) => ({ scopeType: "owner", metrics }))
  ];
  return rows.flatMap(({ scopeType, metrics }) => {
    const issues = metrics.sla?.improvementItems || [];
    if (!["warning", "danger"].includes(metrics.sla?.level) || !issues.length) return [];
    return issues.map((issue) => calibrationSlaActionCandidate(scopeType, metrics, issue));
  });
}

function mergeCalibrationSlaActions(candidates = [], savedActions = []) {
  const savedBySourceKey = new Map(savedActions.map((item) => [item.sourceKey, normalizeCalibrationSlaAction(item)]));
  const candidateSourceKeys = new Set(candidates.map((item) => item.sourceKey));
  const mergedCandidates = candidates.map((candidate) => {
    const saved = savedBySourceKey.get(candidate.sourceKey);
    return saved ? { ...candidate, ...saved, isSaved: true, candidateStatus: "saved" } : { ...candidate, isSaved: false, candidateStatus: "generated" };
  });
  const orphanSaved = savedActions
    .map(normalizeCalibrationSlaAction)
    .filter((item) => item.sourceKey && !candidateSourceKeys.has(item.sourceKey))
    .map((item) => ({ ...item, isSaved: true, candidateStatus: "saved_only" }));
  return [...mergedCandidates, ...orphanSaved]
    .sort((a, b) => {
      const levelRank = { danger: 0, warning: 1, normal: 2 };
      const priorityRank = { urgent: 0, high: 1, medium: 2, low: 3 };
      return (levelRank[a.slaLevel] ?? 9) - (levelRank[b.slaLevel] ?? 9) ||
        (priorityRank[a.priority] ?? 9) - (priorityRank[b.priority] ?? 9) ||
        String(a.targetDate || "").localeCompare(String(b.targetDate || ""));
    });
}

function calibrationSlaActionSummary(actions = []) {
  return {
    total: actions.length,
    generated: actions.filter((item) => item.candidateStatus === "generated").length,
    saved: actions.filter((item) => item.isSaved).length,
    open: actions.filter((item) => !["done", "dismissed"].includes(item.status)).length,
    danger: actions.filter((item) => item.slaLevel === "danger").length,
    warning: actions.filter((item) => item.slaLevel === "warning").length,
    byStatus: actions.reduce((acc, item) => {
      acc[item.status] = (acc[item.status] || 0) + 1;
      return acc;
    }, {})
  };
}

function calibrationSlaActionIsOpen(action = {}) {
  return !["done", "dismissed"].includes(normalizeCalibrationSlaActionStatus(action.status));
}

function calibrationSlaActionDueState(action = {}) {
  if (!calibrationSlaActionIsOpen(action)) return "closed";
  const targetDate = isoDate(action.targetDate || "");
  if (!targetDate) return "no_due";
  if (targetDate < kstDate(0)) return "overdue";
  if (targetDate <= kstDate(7)) return "this_week";
  return "upcoming";
}

function calibrationSlaActionRiskLevel(action = {}) {
  const level = String(action.slaLevel || action.severity || "").trim().toLowerCase();
  if (level === "danger") return "high";
  if (level === "warning") return "medium";
  return "low";
}

function normalizeCalibrationSlaActionRisk(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["danger", "high"].includes(text)) return "high";
  if (["warning", "medium"].includes(text)) return "medium";
  if (["normal", "low"].includes(text)) return "low";
  return "";
}

function enrichCalibrationSlaActionQueueItem(action = {}) {
  const normalized = normalizeCalibrationSlaAction(action);
  const dueState = calibrationSlaActionDueState(normalized);
  const riskLevel = calibrationSlaActionRiskLevel(normalized);
  return {
    ...normalized,
    isSaved: Boolean(action.isSaved),
    candidateStatus: action.candidateStatus || (action.isSaved ? "saved" : "generated"),
    dueState,
    riskLevel,
    isOpen: calibrationSlaActionIsOpen(normalized),
    isOverdue: dueState === "overdue",
    isThisWeek: dueState === "this_week",
    isCompleted: normalized.status === "done"
  };
}

function calibrationSlaActionQueueSummary(items = []) {
  const openItems = items.filter((item) => item.isOpen);
  const ownerMap = new Map();
  openItems.forEach((item) => {
    const owner = item.assignee || item.owner || "unassigned";
    const current = ownerMap.get(owner) || { owner, open: 0, overdue: 0, thisWeek: 0, urgent: 0, highRisk: 0 };
    current.open += 1;
    if (item.isOverdue) current.overdue += 1;
    if (item.isThisWeek) current.thisWeek += 1;
    if (item.priority === "urgent") current.urgent += 1;
    if (item.riskLevel === "high") current.highRisk += 1;
    ownerMap.set(owner, current);
  });
  return {
    total: items.length,
    saved: items.filter((item) => item.isSaved).length,
    generated: items.filter((item) => item.candidateStatus === "generated").length,
    open: openItems.length,
    overdue: openItems.filter((item) => item.isOverdue).length,
    thisWeek: openItems.filter((item) => item.isThisWeek).length,
    noDueDate: openItems.filter((item) => item.dueState === "no_due").length,
    done: items.filter((item) => item.status === "done").length,
    dismissed: items.filter((item) => item.status === "dismissed").length,
    urgent: openItems.filter((item) => item.priority === "urgent").length,
    highRisk: openItems.filter((item) => item.riskLevel === "high").length,
    byStatus: items.reduce((acc, item) => {
      acc[item.status] = (acc[item.status] || 0) + 1;
      return acc;
    }, {}),
    byPriority: items.reduce((acc, item) => {
      acc[item.priority] = (acc[item.priority] || 0) + 1;
      return acc;
    }, {}),
    byRisk: items.reduce((acc, item) => {
      acc[item.riskLevel] = (acc[item.riskLevel] || 0) + 1;
      return acc;
    }, {}),
    byOwnerOpen: [...ownerMap.values()]
      .sort((a, b) => b.open - a.open || b.overdue - a.overdue || String(a.owner).localeCompare(String(b.owner)))
  };
}

function filterCalibrationSlaActionQueueItems(items = [], payload = {}) {
  const status = normalizeCalibrationSlaActionStatusFilter(payload.status || "");
  const owner = String(payload.owner || "").trim().toLowerCase();
  const dueState = String(payload.dueState || "").trim().toLowerCase();
  const priority = normalizeCalibrationSlaActionPriority(payload.priority || "");
  const risk = normalizeCalibrationSlaActionRisk(payload.risk || "");
  const month = String(payload.month || "").trim();
  const includeGenerated = String(payload.includeGenerated ?? "true").trim().toLowerCase() !== "false";
  return items
    .filter((item) => includeGenerated || item.isSaved)
    .filter((item) => !status || item.status === status)
    .filter((item) => !owner || (owner === "unassigned" && !(item.assignee || item.owner)) || String(item.assignee || item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !dueState || item.dueState === dueState)
    .filter((item) => !priority || item.priority === priority)
    .filter((item) => !risk || item.riskLevel === risk)
    .filter((item) => !month || item.month === month || item.sourceType === "summary");
}

function sortCalibrationSlaActionQueueItems(items = []) {
  const dueRank = { overdue: 0, this_week: 1, no_due: 2, upcoming: 3, closed: 4 };
  const riskRank = { high: 0, medium: 1, low: 2 };
  const priorityRank = { urgent: 0, high: 1, medium: 2, low: 3 };
  return [...items].sort((a, b) => {
    return (dueRank[a.dueState] ?? 9) - (dueRank[b.dueState] ?? 9) ||
      (riskRank[a.riskLevel] ?? 9) - (riskRank[b.riskLevel] ?? 9) ||
      (priorityRank[a.priority] ?? 9) - (priorityRank[b.priority] ?? 9) ||
      String(a.targetDate || "9999-99-99").localeCompare(String(b.targetDate || "9999-99-99")) ||
      String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""));
  });
}

function calibrationSlaActionQueueFocus(items = []) {
  const open = items.filter((item) => item.isOpen);
  return {
    overdue: sortCalibrationSlaActionQueueItems(open.filter((item) => item.isOverdue)).slice(0, 12),
    thisWeek: sortCalibrationSlaActionQueueItems(open.filter((item) => item.isThisWeek)).slice(0, 12),
    ownerOpen: calibrationSlaActionQueueSummary(items).byOwnerOpen.slice(0, 12)
  };
}

function calibrationSlaActionMetricSubset(metrics = {}) {
  return {
    totalChanges: metrics.totalChanges || 0,
    avgProcessingDays: metrics.avgProcessingDays ?? null,
    delayedResolutionRate: metrics.delayedResolutionRate || 0,
    reopenRate: metrics.reopenRate || 0,
    unresolvedDelayedItems: metrics.unresolvedDelayedItems || 0,
    memoChangeCount: metrics.memoChangeCount || 0,
    lastChangedAt: metrics.lastChangedAt || ""
  };
}

function calibrationSlaActionIssueMetricKey(issueKey = "") {
  const key = String(issueKey || "").trim();
  if (key === "avg_processing_days") return "avgProcessingDays";
  if (key === "delayed_resolution_rate") return "delayedResolutionRate";
  if (key === "reopen_rate") return "reopenRate";
  if (key === "unresolved_delayed_items") return "unresolvedDelayedItems";
  return "";
}

function calibrationSlaActionMetricScale(metricKey = "") {
  if (metricKey === "avgProcessingDays") return 10;
  if (metricKey === "delayedResolutionRate") return 0.6;
  if (metricKey === "reopenRate") return 1.2;
  if (metricKey === "unresolvedDelayedItems") return 15;
  return 1;
}

function calibrationSlaActionMetricImprovementDelta(issueKey = "", beforeMetrics = {}, afterMetrics = {}) {
  const metricKey = calibrationSlaActionIssueMetricKey(issueKey);
  if (!metricKey) return null;
  const before = Number(beforeMetrics[metricKey]);
  const after = Number(afterMetrics[metricKey]);
  if (!Number.isFinite(before) || !Number.isFinite(after)) return null;
  if (metricKey === "delayedResolutionRate") return Number((after - before).toFixed(2));
  return Number((before - after).toFixed(2));
}

function calibrationSlaActionMetricDelta(baseline = {}, current = {}) {
  return ["avgProcessingDays", "delayedResolutionRate", "reopenRate", "unresolvedDelayedItems"].reduce((acc, key) => {
    const before = Number(baseline[key]);
    const after = Number(current[key]);
    acc[key] = Number.isFinite(before) && Number.isFinite(after) ? Number((after - before).toFixed(2)) : null;
    return acc;
  }, {});
}

function calibrationSlaActionImprovementState(issueKey = "", baseline = {}, current = {}) {
  const key = String(issueKey || "").trim();
  const metricKey = key === "avg_processing_days"
    ? "avgProcessingDays"
    : key === "delayed_resolution_rate"
      ? "delayedResolutionRate"
      : key === "reopen_rate"
        ? "reopenRate"
        : key === "unresolved_delayed_items"
          ? "unresolvedDelayedItems"
          : "";
  if (!metricKey) return "unknown";
  const before = Number(baseline[metricKey]);
  const after = Number(current[metricKey]);
  if (!Number.isFinite(before) || !Number.isFinite(after)) return "unknown";
  const diff = after - before;
  if (Math.abs(diff) < 0.01) return "unchanged";
  if (metricKey === "delayedResolutionRate") return diff > 0 ? "improved" : "worse";
  return diff < 0 ? "improved" : "worse";
}

function scopedCalibrationSlaActionLogs(logs = [], action = {}, sinceIso = "") {
  const month = action.sourceType === "month" ? action.month : "";
  const owner = action.sourceType === "owner" ? String(action.owner || action.assignee || "").trim().toLowerCase() : "";
  return logs
    .map(normalizeCalibrationAuditReviewLog)
    .filter((log) => !month || calibrationAuditLogMonth(log) === month)
    .filter((log) => !owner || calibrationAuditLogOwner(log).toLowerCase().includes(owner))
    .filter((log) => !sinceIso || String(log.changedAt || "").localeCompare(sinceIso) > 0);
}

function calibrationSlaActionIssueStillActive(issueKey = "", sla = {}) {
  return ["warning", "danger"].includes(String(sla.level || "").trim()) &&
    (sla.improvementItems || []).some((item) => item.key === issueKey);
}

function calibrationSlaActionEffectScore(issueKey = "", snapshotMetrics = {}, currentMetrics = {}, currentSla = {}, postLogCount = 0) {
  const metricKey = calibrationSlaActionIssueMetricKey(issueKey);
  const improvementDelta = calibrationSlaActionMetricImprovementDelta(issueKey, snapshotMetrics, currentMetrics);
  let score = 50;
  if (Number.isFinite(improvementDelta)) {
    const scaled = improvementDelta * calibrationSlaActionMetricScale(metricKey);
    score += Math.max(-30, Math.min(30, scaled));
  }
  if (currentSla.level === "normal") score += 15;
  if (currentSla.level === "warning") score -= 5;
  if (currentSla.level === "danger") score -= 20;
  if (calibrationSlaActionIssueStillActive(issueKey, currentSla)) score -= 15;
  if (!postLogCount) score -= 5;
  return Math.max(0, Math.min(100, Math.round(score)));
}

function calibrationSlaActionEvaluationState(effectScore = 50, issueKey = "", snapshotMetrics = {}, currentMetrics = {}, recurrence = false) {
  const state = calibrationSlaActionImprovementState(issueKey, snapshotMetrics, currentMetrics);
  if (recurrence && effectScore < 60) return "worse";
  if (state === "improved" && effectScore >= 60) return "improved";
  if (state === "worse" || effectScore <= 40) return "worse";
  return "unchanged";
}

function calibrationSlaActionFollowUpReason(reassessment = {}) {
  if (reassessment.recurrence) return "The same SLA issue is still active after the completed action.";
  if (reassessment.effectScore < 45) return "The post-completion quality score deteriorated below the operating threshold.";
  if (reassessment.currentSla?.level === "danger") return "Current operational quality is still in the risk range.";
  if (!reassessment.postCompletionLogCount) return "No post-completion operational log exists yet, so follow-up monitoring is required.";
  return "";
}

function reassessCalibrationSlaAction(action = {}, logs = []) {
  const normalized = enrichCalibrationSlaActionQueueItem(action);
  const snapshot = normalized.completionQualitySnapshot || {};
  const capturedAt = snapshot.capturedAt || normalized.completedAt || "";
  const allScopedLogs = scopedCalibrationSlaActionLogs(logs, normalized);
  const postScopedLogs = scopedCalibrationSlaActionLogs(logs, normalized, capturedAt);
  const selectedLogs = postScopedLogs.length ? postScopedLogs : allScopedLogs;
  const quality = calibrationAuditOperationQuality(selectedLogs);
  const currentMetrics = calibrationSlaActionMetricSubset(quality.summary || {});
  const snapshotMetrics = calibrationSlaActionMetricSubset(snapshot.current || snapshot.baseline || normalized.sourceMetrics || {});
  const deltas = calibrationSlaActionMetricDelta(snapshotMetrics, currentMetrics);
  const issueDelta = calibrationSlaActionMetricImprovementDelta(normalized.issueKey, snapshotMetrics, currentMetrics);
  const currentSla = quality.summary?.sla || {};
  const recurrence = calibrationSlaActionIssueStillActive(normalized.issueKey, currentSla);
  const effectScore = calibrationSlaActionEffectScore(normalized.issueKey, snapshotMetrics, currentMetrics, currentSla, postScopedLogs.length);
  const evaluationState = calibrationSlaActionEvaluationState(effectScore, normalized.issueKey, snapshotMetrics, currentMetrics, recurrence);
  const followUpNeeded = Boolean(recurrence || effectScore < 60 || currentSla.level === "danger");
  const reassessment = {
    evaluatedAt: new Date().toISOString(),
    evaluationState,
    effectScore,
    recurrence,
    followUpNeeded,
    followUpReason: followUpNeeded ? calibrationSlaActionFollowUpReason({ recurrence, effectScore, currentSla, postCompletionLogCount: postScopedLogs.length }) : "",
    postCompletionLogCount: postScopedLogs.length,
    scopedLogCount: allScopedLogs.length,
    issueMetricKey: calibrationSlaActionIssueMetricKey(normalized.issueKey),
    issueMetricDelta: issueDelta,
    snapshotMetrics,
    currentMetrics,
    deltas,
    currentSla,
    completionSnapshot: snapshot
  };
  return {
    ...normalized,
    reassessment,
    followUpCandidate: followUpNeeded ? calibrationSlaActionFollowUpCandidate(normalized, reassessment) : null
  };
}

function calibrationSlaActionFollowUpCandidate(action = {}, reassessment = {}) {
  const severity = reassessment.currentSla?.level === "danger" || reassessment.effectScore < 45 ? "danger" : "warning";
  const priority = severity === "danger" ? "high" : "medium";
  const sourceKey = `followup|${action.actionId || action.sourceKey}|${action.issueKey || "sla"}`;
  const metricSource = {
    ...(reassessment.currentMetrics || {}),
    effectScore: reassessment.effectScore,
    recurrence: reassessment.recurrence ? 1 : 0
  };
  return normalizeCalibrationSlaAction({
    actionId: hashId("lcsa", sourceKey),
    sourceKey,
    sourceType: action.sourceType || "summary",
    sourceLabel: `${action.sourceLabel || action.actionId || "SLA action"} follow-up`,
    month: action.month || "",
    owner: action.owner || "",
    slaLevel: severity,
    issueKey: action.issueKey || "",
    severity,
    rootMetric: calibrationSlaActionRootMetric({ key: action.issueKey || "" }, reassessment.currentMetrics || {}),
    recommendation: [
      "Open a follow-up SLA action because the completed action did not produce a stable improvement.",
      reassessment.followUpReason || "",
      `Latest effect score: ${reassessment.effectScore}.`
    ].filter(Boolean).join(" "),
    priority,
    assignee: action.assignee || action.owner || "",
    targetDate: kstDate(priority === "high" ? 4 : 7),
    status: "candidate",
    createdBy: "system",
    updatedBy: "system",
    sourceMetrics: metricSource
  });
}

async function calibrationSlaActionCompletionSnapshot(action = {}) {
  const data = await readLearningCalibrationAuditReviewLogs();
  const logs = scopedCalibrationSlaActionLogs(data.items || [], action);
  const quality = calibrationAuditOperationQuality(logs);
  const metrics = quality.summary || {};
  const current = calibrationSlaActionMetricSubset(metrics);
  const baseline = calibrationSlaActionMetricSubset(action.sourceMetrics || {});
  return {
    capturedAt: new Date().toISOString(),
    sourceType: action.sourceType || "summary",
    sourceLabel: action.sourceLabel || "",
    month: action.month || "",
    owner: action.owner || action.assignee || "",
    issueKey: action.issueKey || "",
    rootMetric: action.rootMetric || "",
    baseline,
    current,
    deltas: calibrationSlaActionMetricDelta(baseline, current),
    improvementState: calibrationSlaActionImprovementState(action.issueKey, baseline, current),
    sla: metrics.sla || {}
  };
}

async function calibrationSlaActionsForQuality(quality = {}) {
  const [data, historyData, adjustmentData] = await Promise.all([
    readLearningCalibrationSlaActions(),
    readSlaActionReassessmentHistory(),
    readSlaActionRecommendationAdjustments()
  ]);
  const savedActions = (data.items || []).map(normalizeCalibrationSlaAction);
  const historyItems = historyData.items || [];
  const adjustmentItems = adjustmentData.items || [];
  const rawCandidates = calibrationSlaActionCandidatesFromQuality(quality);
  const candidates = [];
  for (const candidate of rawCandidates) {
    const applied = await applyCalibrationSlaHistoryAdjustment(candidate, historyItems, adjustmentItems);
    candidates.push(applied);
  }
  return mergeCalibrationSlaActions(candidates, savedActions);
}

async function attachCalibrationSlaActionsToQuality(quality = {}) {
  const actions = await calibrationSlaActionsForQuality(quality);
  return {
    ...quality,
    slaActions: {
      summary: calibrationSlaActionSummary(actions),
      items: actions.slice(0, 80)
    }
  };
}

async function upsertLearningCalibrationSlaAction(payload = {}) {
  const data = await readLearningCalibrationSlaActions();
  const items = Array.isArray(data.items) ? data.items : [];
  const existing = items.find((item) => item.actionId === payload.actionId || (payload.sourceKey && item.sourceKey === payload.sourceKey));
  const now = new Date().toISOString();
  let action = normalizeCalibrationSlaAction({
    ...(existing || {}),
    ...payload,
    createdAt: existing?.createdAt || payload.createdAt || now,
    createdBy: existing?.createdBy || payload.createdBy || payload.updatedBy || "admin",
    updatedAt: now,
    updatedBy: payload.updatedBy || payload.changedBy || "admin"
  });
  if (action.status === "done") {
    const snapshot = await calibrationSlaActionCompletionSnapshot(action);
    action = normalizeCalibrationSlaAction({
      ...action,
      completedAt: existing?.completedAt || payload.completedAt || now,
      completedBy: payload.updatedBy || payload.changedBy || payload.completedBy || "admin",
      completionQualitySnapshot: snapshot
    });
  }
  const updated = await writeLearningCalibrationSlaActions({
    ...data,
    items: [
      action,
      ...items.filter((item) => item.actionId !== action.actionId && item.sourceKey !== action.sourceKey)
    ]
  });
  return {
    learningCalibrationSlaActions: {
      schema: updated.schema || "learning_calibration_sla_actions_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    action
  };
}

async function appendLearningCalibrationAuditReviewLogs(logs = []) {
  const normalized = logs.map(normalizeCalibrationAuditReviewLog)
    .filter((log) => log.versionId && log.changedFields.length);
  if (!normalized.length) {
    return {
      learningCalibrationAuditReviewLogs: null,
      appended: 0,
      logs: []
    };
  }
  const data = await readLearningCalibrationAuditReviewLogs();
  const updated = await writeLearningCalibrationAuditReviewLogs({
    ...data,
    items: [
      ...normalized,
      ...(Array.isArray(data.items) ? data.items : [])
    ]
  });
  return {
    learningCalibrationAuditReviewLogs: {
      schema: updated.schema || "learning_calibration_audit_review_logs_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    appended: normalized.length,
    logs: normalized
  };
}

function calibrationAuditVersionMatchesStatus(version = {}, status = "") {
  const filter = normalizeCalibrationAuditStatus(status);
  if (!filter) return true;
  const events = version.events || [];
  if (filter === "approved") return Boolean(version.approvedAt) || events.some((event) => event.eventType === "approved");
  if (filter === "rollback") return version.source === "rollback" || events.some((event) => event.eventType === "rollback");
  if (filter === "drafted") return version.status === "draft" || events.some((event) => event.eventType === "drafted");
  if (filter === "applied") return events.some((event) => event.eventType === "applied");
  if (filter === "proposed") return version.status === "proposed" || events.some((event) => event.eventType === "proposed");
  return version.status === filter || events.some((event) => event.eventType === filter);
}

function calibrationAuditVersionMatchesReviewStatus(version = {}, reviewStatus = "") {
  const filter = normalizeCalibrationAuditReviewStatus(reviewStatus);
  if (!filter) return true;
  return (version.auditReview?.reviewStatus || "pending") === filter;
}

function learningCalibrationAuditDrilldown(version = {}) {
  return {
    proposal: {
      versionId: version.versionId || "",
      versionNumber: version.versionNumber || 0,
      status: version.status || "",
      riskLevel: version.riskLevel || calibrationAuditRiskLevel(version),
      source: version.source || "",
      sourceCompanyId: version.sourceCompanyId || "",
      sourceTargetMonth: version.sourceTargetMonth || "",
      proposedBy: version.proposedBy || "",
      proposedAt: version.proposedAt || null,
      approvedBy: version.approvedBy || "",
      approvedAt: version.approvedAt || null,
      rejectedBy: version.rejectedBy || "",
      rejectedAt: version.rejectedAt || null,
      appliedBy: version.appliedBy || "",
      appliedAt: version.appliedAt || null,
      reason: version.reason || version.reviewReason || version.rejectReason || "",
      reviewChecklistSummary: version.reviewChecklistSummary || {},
      settings: version.settings || {},
      events: version.events || []
    },
    operationalReview: version.auditReview || defaultCalibrationAuditReview(version),
    operationalReviewHistory: {
      summary: version.auditReviewLogSummary || calibrationAuditReviewLogSummary(version.auditReviewLogs || []),
      recent: version.auditReviewLogs || []
    },
    impactStrategies: (version.impactItems || []).map((item) => ({
      strategyId: item.strategyId || "",
      category: item.category || "",
      title: item.title || "",
      current: item.current || {},
      simulated: item.simulated || {},
      deltas: item.deltas || {},
      riskLevel: item.riskLevel || "low",
      riskReasons: item.riskReasons || []
    })),
    matchedExecutionPlans: version.executionPerformance?.plans || []
  };
}

function calibrationAuditFilterOptions(versions = [], companyMap = new Map()) {
  const statusCounts = {};
  const riskCounts = {};
  const reviewStatusCounts = {};
  const monthCounts = {};
  const companyCounts = {};
  versions.forEach((version) => {
    const risk = version.riskLevel || calibrationAuditRiskLevel(version);
    riskCounts[risk] = (riskCounts[risk] || 0) + 1;
    const reviewStatus = version.auditReview?.reviewStatus || "pending";
    reviewStatusCounts[reviewStatus] = (reviewStatusCounts[reviewStatus] || 0) + 1;
    const month = version.eventMonth || monthKey(version.proposedAt || version.appliedAt || version.rejectedAt) || "unknown";
    monthCounts[month] = (monthCounts[month] || 0) + 1;
    const companyId = version.sourceCompanyId || "";
    if (companyId) companyCounts[companyId] = (companyCounts[companyId] || 0) + 1;
    const statuses = new Set([version.status || ""]);
    (version.events || []).forEach((event) => statuses.add(event.eventType || ""));
    statuses.forEach((status) => {
      if (status) statusCounts[status] = (statusCounts[status] || 0) + 1;
    });
  });
  const companies = Object.entries(companyCounts)
    .map(([companyId, count]) => {
      const company = companyMap.get(companyId) || {};
      return {
        companyId,
        name: company.canonicalName || company.name || companyId,
        region: company.region || "",
        category: company.category || "",
        count
      };
    })
    .sort((a, b) => b.count - a.count || String(a.name).localeCompare(String(b.name)));
  return {
    months: Object.entries(monthCounts)
      .map(([month, count]) => ({ month, count }))
      .sort((a, b) => String(b.month).localeCompare(String(a.month))),
    companies,
    statuses: Object.entries(statusCounts)
      .map(([status, count]) => ({ status, count }))
      .sort((a, b) => String(a.status).localeCompare(String(b.status))),
    risks: ["high", "medium", "low", "none"].map((risk) => ({ risk, count: riskCounts[risk] || 0 })),
    reviewStatuses: ["pending", "in_review", "action_required", "resolved", "deferred"]
      .map((reviewStatus) => ({ reviewStatus, count: reviewStatusCounts[reviewStatus] || 0 }))
  };
}

function calibrationAuditExportRows(report = {}) {
  return (report.items || []).map((item) => {
    const logSummary = item.auditReviewLogSummary || calibrationAuditReviewLogSummary(item.auditReviewLogs || []);
    return {
      versionId: item.versionId || "",
      versionNumber: item.versionNumber || 0,
      status: item.status || "",
      riskLevel: item.riskLevel || "",
      reviewStatus: item.auditReview?.reviewStatus || "pending",
      adminMemo: item.auditReview?.adminMemo || "",
      followUpOwner: item.auditReview?.followUpOwner || "",
      followUpDueDate: item.auditReview?.followUpDueDate || "",
      followUpOverdue: calibrationAuditReviewIsOverdue(item.auditReview || {}) ? "yes" : "no",
      reviewUpdatedBy: item.auditReview?.updatedBy || "",
      reviewUpdatedAt: item.auditReview?.updatedAt || "",
      reviewChangeCount: logSummary.count || 0,
      reviewLastChangedBy: logSummary.latestChangedBy || "",
      reviewLastChangedAt: logSummary.latestChangedAt || "",
      reviewLastOperationType: logSummary.latestOperationType || "",
      reviewLastChangedFields: (logSummary.latestChangedFields || []).join("|"),
      reviewHistorySummary: logSummary.latestSummary || "",
      eventMonth: item.eventMonth || "",
      sourceCompanyId: item.sourceCompanyId || "",
      sourceTargetMonth: item.sourceTargetMonth || "",
      proposedBy: item.proposedBy || "",
      proposedAt: item.proposedAt || "",
      approvedBy: item.approvedBy || "",
      approvedAt: item.approvedAt || "",
      rejectedBy: item.rejectedBy || "",
      rejectedAt: item.rejectedAt || "",
      eventTypes: (item.events || []).map((event) => event.eventType).filter(Boolean).join("|"),
      highRiskCount: item.impactSummary?.highRiskCount || 0,
      mediumRiskCount: item.impactSummary?.mediumRiskCount || 0,
      affectedStrategies: item.executionPerformance?.strategyCount || 0,
      matchedPlans: item.executionPerformance?.matchedPlans || 0,
      completedPlans: item.executionPerformance?.completedPlans || 0,
      overduePlans: item.executionPerformance?.overduePlans || 0,
      avgProgress: item.executionPerformance?.avgProgress || 0,
      avgRetrospectiveScore: item.executionPerformance?.avgRetrospectiveScore || 0,
      reason: item.reviewReason || item.rejectReason || item.reason || ""
    };
  });
}

function calibrationAuditCsv(report = {}) {
  const columns = [
    "versionId",
    "versionNumber",
    "status",
    "riskLevel",
    "reviewStatus",
    "adminMemo",
    "followUpOwner",
    "followUpDueDate",
    "followUpOverdue",
    "reviewUpdatedBy",
    "reviewUpdatedAt",
    "reviewChangeCount",
    "reviewLastChangedBy",
    "reviewLastChangedAt",
    "reviewLastOperationType",
    "reviewLastChangedFields",
    "reviewHistorySummary",
    "eventMonth",
    "sourceCompanyId",
    "sourceTargetMonth",
    "proposedBy",
    "proposedAt",
    "approvedBy",
    "approvedAt",
    "rejectedBy",
    "rejectedAt",
    "eventTypes",
    "highRiskCount",
    "mediumRiskCount",
    "affectedStrategies",
    "matchedPlans",
    "completedPlans",
    "overduePlans",
    "avgProgress",
    "avgRetrospectiveScore",
    "reason"
  ];
  const rows = calibrationAuditExportRows(report);
  return `\uFEFF${[
    columns.join(","),
    ...rows.map((row) => columns.map((column) => csvEscape(row[column])).join(","))
  ].join("\n")}`;
}

function learningCalibrationAuditExportUrl(filters = {}, format = "json") {
  const params = new URLSearchParams();
  ["companyId", "month", "status", "risk", "reviewStatus", "limit"].forEach((key) => {
    if (filters[key]) params.set(key, filters[key]);
  });
  params.set("format", format);
  return `/api/admin/master-db/learning-calibration-audit?${params.toString()}`;
}

function learningCalibrationAuditFilename(filters = {}, ext = "json") {
  const parts = [
    "learning-calibration-audit",
    filters.companyId || "all",
    filters.month || "all",
    filters.status || "all",
    filters.risk || "all",
    filters.reviewStatus || "all"
  ].map((item) => String(item || "all").replace(/[^a-z0-9_-]+/gi, "-"));
  return `${parts.join("_")}.${ext}`;
}

async function learningCalibrationAuditReport(payload = {}) {
  const [settingsData, executionData, companyData, reviewData, reviewLogData] = await Promise.all([
    readLearningCalibrationSettings(),
    readStrategyExecutionPlans(),
    readCompanyMaster(),
    readLearningCalibrationAuditReviews(),
    readLearningCalibrationAuditReviewLogs()
  ]);
  const companyId = String(payload.companyId || "").trim();
  const month = String(payload.month || "").trim();
  const status = normalizeCalibrationAuditStatus(payload.status || "");
  const risk = normalizeCalibrationAuditRisk(payload.risk || "");
  const reviewStatus = normalizeCalibrationAuditReviewStatus(payload.reviewStatus || "");
  const limit = Math.max(1, Math.min(200, Number(payload.limit || 80)));
  const companyMap = new Map((companyData.items || []).map((company) => [company.companyId, company]));
  const reviewMap = calibrationAuditReviewMap(reviewData);
  const reviewLogMap = calibrationAuditReviewLogMap(reviewLogData);
  const allVersions = (settingsData.items || []).map((version) => {
    const publicVersion = publicLearningCalibrationVersion(version);
    const events = calibrationAuditEventRecords([publicVersion]);
    const baseVersion = {
      ...publicVersion,
      eventMonth: monthKey(publicVersion.proposedAt || publicVersion.appliedAt || publicVersion.rejectedAt),
      riskLevel: calibrationAuditRiskLevel(publicVersion),
      events
    };
    const auditReview = normalizeCalibrationAuditReview(reviewMap.get(publicVersion.versionId) || {}, baseVersion);
    const auditReviewLogs = reviewLogMap.get(publicVersion.versionId) || [];
    return {
      ...baseVersion,
      auditReview,
      auditReviewLogSummary: calibrationAuditReviewLogSummary(auditReviewLogs),
      auditReviewLogs: auditReviewLogs.slice(0, 10)
    };
  });
  const scopedVersions = allVersions
    .filter((version) => !companyId || version.sourceCompanyId === companyId)
    .filter((version) => {
      if (!month) return true;
      return [version.proposedAt, version.appliedAt, version.approvedAt, version.rejectedAt]
        .some((value) => monthKey(value) === month);
    })
    .filter((version) => calibrationAuditVersionMatchesStatus(version, status))
    .filter((version) => !risk || version.riskLevel === risk)
    .filter((version) => calibrationAuditVersionMatchesReviewStatus(version, reviewStatus));
  const versions = scopedVersions;
  const events = calibrationAuditEventRecords(versions);
  const enrichedVersions = versions
    .map((version) => ({
      ...version,
      events: events.filter((event) => event.versionId === version.versionId),
      executionPerformance: calibrationVersionExecutionPerformance(version, executionData.items || [])
    }))
    .map((version) => ({
      ...version,
      drilldown: learningCalibrationAuditDrilldown(version)
    }));
  const monthly = calibrationAuditMonthly(events, versions)
    .map((row) => {
      const related = enrichedVersions.filter((item) => row.versionIds.includes(item.versionId));
      const matched = related.filter((item) => Number(item.executionPerformance?.matchedPlans || 0) > 0);
      return {
        ...row,
        affectedStrategies: related.reduce((sum, item) => sum + Number(item.executionPerformance?.strategyCount || 0), 0),
        matchedPlans: related.reduce((sum, item) => sum + Number(item.executionPerformance?.matchedPlans || 0), 0),
        completedPlans: related.reduce((sum, item) => sum + Number(item.executionPerformance?.completedPlans || 0), 0),
        overduePlans: related.reduce((sum, item) => sum + Number(item.executionPerformance?.overduePlans || 0), 0),
        avgMatchedPlanProgress: safeScore(average(matched.map((item) => item.executionPerformance?.avgProgress))) || 0,
        avgMatchedPlanScore: safeScore(average(matched.map((item) => item.executionPerformance?.avgRetrospectiveScore))) || 0
      };
    });
  const items = enrichedVersions
    .sort((a, b) => String(b.proposedAt || b.appliedAt || b.rejectedAt || "").localeCompare(String(a.proposedAt || a.appliedAt || a.rejectedAt || "")))
    .slice(0, limit);
  const matchedVersions = enrichedVersions.filter((item) => Number(item.executionPerformance?.matchedPlans || 0) > 0);
  const scopedVersionIds = new Set(versions.map((item) => item.versionId));
  const scopedReviewLogs = (reviewLogData.items || [])
    .map(normalizeCalibrationAuditReviewLog)
    .filter((log) => scopedVersionIds.has(log.versionId));
  const bulkOperations = calibrationAuditBulkOperations(scopedReviewLogs);
  const operationQuality = await attachCalibrationSlaActionsToQuality(calibrationAuditOperationQuality(scopedReviewLogs));
  return {
    role: "admin",
    reportType: "learning_calibration_audit_report",
    generatedAt: new Date().toISOString(),
    filters: {
      companyId,
      month,
      status,
      risk,
      reviewStatus,
      limit
    },
    availableFilters: calibrationAuditFilterOptions(allVersions, companyMap),
    exportUrls: {
      json: learningCalibrationAuditExportUrl({ companyId, month, status, risk, reviewStatus, limit }, "json"),
      csv: learningCalibrationAuditExportUrl({ companyId, month, status, risk, reviewStatus, limit }, "csv")
    },
    activeVersion: publicLearningCalibrationVersion(activeLearningCalibrationVersion(settingsData)),
    summary: {
      totalVersions: versions.length,
      proposed: events.filter((event) => event.eventType === "proposed").length,
      approved: events.filter((event) => event.eventType === "approved").length,
      rejected: events.filter((event) => event.eventType === "rejected").length,
      rollback: events.filter((event) => event.eventType === "rollback").length,
      highRiskVersions: versions.filter((version) => Number(version.impactSummary?.highRiskCount || 0) > 0).length,
      reviewStatusCounts: versions.reduce((acc, version) => {
        const key = version.auditReview?.reviewStatus || "pending";
        acc[key] = (acc[key] || 0) + 1;
        return acc;
      }, {}),
      openFollowUps: versions.filter((version) => version.auditReview?.followUpOwner && !["resolved", "deferred"].includes(version.auditReview.reviewStatus)).length,
      overdueFollowUps: versions.filter((version) => calibrationAuditReviewIsOverdue(version.auditReview || {})).length,
      auditReviewLogCount: scopedReviewLogs.length,
      bulkOperationCount: bulkOperations.length,
      affectedStrategies: enrichedVersions.reduce((sum, item) => sum + Number(item.executionPerformance?.strategyCount || 0), 0),
      matchedPlans: enrichedVersions.reduce((sum, item) => sum + Number(item.executionPerformance?.matchedPlans || 0), 0),
      completedPlans: enrichedVersions.reduce((sum, item) => sum + Number(item.executionPerformance?.completedPlans || 0), 0),
      overduePlans: enrichedVersions.reduce((sum, item) => sum + Number(item.executionPerformance?.overduePlans || 0), 0),
      avgMatchedPlanProgress: safeScore(average(matchedVersions.map((item) => item.executionPerformance.avgProgress))) || 0,
      avgMatchedPlanScore: safeScore(average(matchedVersions.map((item) => item.executionPerformance.avgRetrospectiveScore))) || 0
    },
    monthly,
    items,
    reviewHistory: {
      totalLogs: scopedReviewLogs.length,
      recentLogs: scopedReviewLogs
        .sort((a, b) => String(b.changedAt || "").localeCompare(String(a.changedAt || "")))
        .slice(0, 20),
      bulkOperations: bulkOperations.slice(0, 20)
    },
    operationQuality,
    exportRows: calibrationAuditExportRows({ items }),
    reportBoundaries: {
      source: "admin-only learning calibration settings history, proposal impact snapshots, and matched strategy execution plans",
      hiddenFromBusiness: ["calibration versions", "review checklist", "settings history", "impact snapshots", "audit formulas", "audit review notes", "follow-up owners"]
    }
  };
}

async function upsertLearningCalibrationAuditReview(payload = {}) {
  const versionId = String(payload.versionId || "").trim();
  if (!versionId) {
    const error = new Error("Learning calibration audit versionId is required.");
    error.statusCode = 400;
    throw error;
  }
  const [reviewData, settingsData] = await Promise.all([
    readLearningCalibrationAuditReviews(),
    readLearningCalibrationSettings()
  ]);
  const items = Array.isArray(reviewData.items) ? reviewData.items : [];
  const existing = items.find((item) => item.versionId === versionId);
  const updatedAt = new Date().toISOString();
  const beforeReview = calibrationAuditReviewBeforeFromExisting(existing, payload, settingsData);
  const review = calibrationAuditReviewFromPayload(payload, existing, settingsData, updatedAt);
  const changedBy = String(payload.updatedBy || payload.reviewedBy || "admin").trim() || "admin";
  const operationId = hashId("lcaop", `single|${versionId}|${updatedAt}|${changedBy}|${crypto.randomUUID()}`);
  const log = calibrationAuditReviewLogForChange({
    operationId,
    operationType: "single",
    beforeReview,
    afterReview: review,
    changedBy,
    changedAt: updatedAt
  });
  const updated = await writeLearningCalibrationAuditReviews({
    ...reviewData,
    items: [
      review,
      ...items.filter((item) => item.versionId !== versionId)
    ]
  });
  const logResult = await appendLearningCalibrationAuditReviewLogs(log ? [log] : []);
  return {
    learningCalibrationAuditReviews: {
      schema: updated.schema || "learning_calibration_audit_reviews_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    learningCalibrationAuditReviewLogs: logResult.learningCalibrationAuditReviewLogs,
    auditReviewLog: log,
    review
  };
}

function calibrationAuditReviewVersionForPayload(payload = {}, settingsData = {}) {
  const versionId = String(payload.versionId || "").trim();
  return (settingsData.items || [])
    .map(publicLearningCalibrationVersion)
    .find((item) => item.versionId === versionId) || {
      versionId,
      sourceCompanyId: payload.companyId || payload.sourceCompanyId || "",
      sourceTargetMonth: payload.targetMonth || payload.sourceTargetMonth || "",
      proposedAt: payload.auditMonth || ""
    };
}

function calibrationAuditReviewFromPayload(payload = {}, existing = {}, settingsData = {}, updatedAt = new Date().toISOString()) {
  const versionId = String(payload.versionId || "").trim();
  const version = calibrationAuditReviewVersionForPayload({ ...existing, ...payload, versionId }, settingsData);
  return normalizeCalibrationAuditReview({
    ...(existing || {}),
    ...payload,
    versionId,
    updatedBy: payload.updatedBy || payload.reviewedBy || "admin",
    updatedAt,
    createdAt: existing?.createdAt || updatedAt
  }, {
    ...version,
    eventMonth: monthKey(version.proposedAt || version.appliedAt || version.rejectedAt) || payload.auditMonth || ""
  });
}

function calibrationAuditReviewBeforeFromExisting(existing = {}, payload = {}, settingsData = {}) {
  const versionId = String(payload.versionId || existing?.versionId || "").trim();
  const version = calibrationAuditReviewVersionForPayload({ ...(existing || {}), ...payload, versionId }, settingsData);
  return normalizeCalibrationAuditReview(existing || {}, {
    ...version,
    eventMonth: monthKey(version.proposedAt || version.appliedAt || version.rejectedAt) || payload.auditMonth || existing?.auditMonth || ""
  });
}

function calibrationAuditReviewLogForChange({ operationId, operationType, beforeReview, afterReview, changedBy, changedAt, allowedFields } = {}) {
  const before = calibrationAuditReviewSnapshot(beforeReview || {});
  const after = calibrationAuditReviewSnapshot(afterReview || {});
  const changedFields = calibrationAuditReviewChangedFields(before, after, allowedFields);
  if (!changedFields.length) return null;
  return normalizeCalibrationAuditReviewLog({
    operationId,
    operationType,
    versionId: afterReview?.versionId || beforeReview?.versionId || "",
    companyId: afterReview?.companyId || beforeReview?.companyId || "",
    targetMonth: afterReview?.targetMonth || beforeReview?.targetMonth || "",
    auditMonth: afterReview?.auditMonth || beforeReview?.auditMonth || "",
    changedBy,
    changedAt,
    changedFields,
    before,
    after
  });
}

async function bulkUpsertLearningCalibrationAuditReviews(payload = {}) {
  const rawItems = Array.isArray(payload.items) ? payload.items : [];
  const updates = payload.updates && typeof payload.updates === "object" ? payload.updates : {};
  const updateKeys = ["reviewStatus", "followUpOwner", "followUpDueDate", "adminMemo"]
    .filter((key) => Object.prototype.hasOwnProperty.call(updates, key));
  const targets = rawItems
    .map((item) => ({
      ...item,
      versionId: String(item?.versionId || "").trim()
    }))
    .filter((item) => item.versionId);
  if (!targets.length) {
    const error = new Error("At least one learning calibration audit version must be selected.");
    error.statusCode = 400;
    throw error;
  }
  if (!updateKeys.length) {
    const error = new Error("At least one audit review field update is required.");
    error.statusCode = 400;
    throw error;
  }
  const [reviewData, settingsData] = await Promise.all([
    readLearningCalibrationAuditReviews(),
    readLearningCalibrationSettings()
  ]);
  const items = Array.isArray(reviewData.items) ? reviewData.items : [];
  const existingByVersionId = new Map(items.map((item) => [item.versionId, item]));
  const updatedAt = new Date().toISOString();
  const updatedBy = String(payload.updatedBy || updates.updatedBy || "admin").trim() || "admin";
  const operationId = hashId("lcaop", `bulk|${updatedAt}|${updatedBy}|${targets.map((item) => item.versionId).join("|")}|${crypto.randomUUID()}`);
  const seen = new Set();
  const reviews = targets
    .filter((item) => {
      if (seen.has(item.versionId)) return false;
      seen.add(item.versionId);
      return true;
    })
    .map((item) => calibrationAuditReviewFromPayload({
      ...item,
      ...updates,
      updatedBy
    }, existingByVersionId.get(item.versionId), settingsData, updatedAt));
  const logs = reviews
    .map((review) => calibrationAuditReviewLogForChange({
      operationId,
      operationType: "bulk",
      beforeReview: calibrationAuditReviewBeforeFromExisting(existingByVersionId.get(review.versionId), review, settingsData),
      afterReview: review,
      changedBy: updatedBy,
      changedAt: updatedAt,
      allowedFields: updateKeys
    }))
    .filter(Boolean);
  const reviewVersionIds = new Set(reviews.map((item) => item.versionId));
  const updated = await writeLearningCalibrationAuditReviews({
    ...reviewData,
    items: [
      ...reviews,
      ...items.filter((item) => !reviewVersionIds.has(item.versionId))
    ]
  });
  const logResult = await appendLearningCalibrationAuditReviewLogs(logs);
  return {
    learningCalibrationAuditReviews: {
      schema: updated.schema || "learning_calibration_audit_reviews_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    learningCalibrationAuditReviewLogs: logResult.learningCalibrationAuditReviewLogs,
    bulkReview: {
      requested: rawItems.length,
      updated: reviews.length,
      logged: logs.length,
      operationId,
      updatedBy,
      updatedAt,
      appliedFields: updateKeys,
      versionIds: reviews.map((item) => item.versionId)
    },
    auditReviewLogs: logs,
    reviews
  };
}

function calibrationAuditQueueItem(item = {}) {
  const review = item.auditReview || defaultCalibrationAuditReview(item);
  const dueState = calibrationAuditReviewDueState(review);
  const company = item.company || {};
  return {
    queueId: review.reviewId || hashId("lcaq", item.versionId || ""),
    versionId: item.versionId || "",
    versionNumber: item.versionNumber || 0,
    workflowStatus: item.status || "",
    riskLevel: item.riskLevel || "none",
    eventMonth: item.eventMonth || "",
    companyId: item.sourceCompanyId || review.companyId || "",
    companyName: company.canonicalName || company.name || item.sourceCompanyId || review.companyId || "",
    companyRegion: company.region || "",
    companyCategory: company.category || "",
    targetMonth: item.sourceTargetMonth || review.targetMonth || "",
    reason: item.reviewReason || item.rejectReason || item.reason || "",
    proposedAt: item.proposedAt || null,
    approvedAt: item.approvedAt || null,
    rejectedAt: item.rejectedAt || null,
    reviewStatus: review.reviewStatus || "pending",
    adminMemo: review.adminMemo || "",
    followUpOwner: review.followUpOwner || "",
    followUpDueDate: review.followUpDueDate || "",
    dueState,
    isOverdue: dueState === "overdue",
    isThisWeek: dueState === "this_week",
    isOpen: calibrationAuditReviewIsOpen(review),
    updatedBy: review.updatedBy || "",
    updatedAt: review.updatedAt || null,
    auditReviewLogSummary: item.auditReviewLogSummary || calibrationAuditReviewLogSummary(item.auditReviewLogs || []),
    auditReviewLogs: item.auditReviewLogs || [],
    impactSummary: item.impactSummary || {},
    executionPerformance: item.executionPerformance || {}
  };
}

function filterCalibrationAuditQueueItems(items = [], payload = {}) {
  const reviewStatus = normalizeCalibrationAuditReviewStatus(payload.reviewStatus || "");
  const owner = String(payload.owner || "").trim().toLowerCase();
  const dueState = String(payload.dueState || "").trim().toLowerCase();
  const companyId = String(payload.companyId || "").trim();
  const risk = normalizeCalibrationAuditRisk(payload.risk || "");
  const month = String(payload.month || "").trim();
  return items
    .filter((item) => !reviewStatus || item.reviewStatus === reviewStatus)
    .filter((item) => !owner || (owner === "unassigned" && !item.followUpOwner) || String(item.followUpOwner || "").toLowerCase().includes(owner))
    .filter((item) => !dueState || item.dueState === dueState)
    .filter((item) => !companyId || item.companyId === companyId)
    .filter((item) => !risk || item.riskLevel === risk)
    .filter((item) => !month || item.eventMonth === month || item.targetMonth === month);
}

function calibrationAuditQueueSummary(items = []) {
  const openItems = items.filter((item) => item.isOpen);
  const ownerMap = new Map();
  openItems.forEach((item) => {
    const owner = item.followUpOwner || "unassigned";
    const current = ownerMap.get(owner) || { owner, open: 0, overdue: 0, thisWeek: 0 };
    current.open += 1;
    if (item.isOverdue) current.overdue += 1;
    if (item.isThisWeek) current.thisWeek += 1;
    ownerMap.set(owner, current);
  });
  return {
    total: items.length,
    open: openItems.length,
    resolved: items.filter((item) => item.reviewStatus === "resolved").length,
    deferred: items.filter((item) => item.reviewStatus === "deferred").length,
    overdue: items.filter((item) => item.isOverdue).length,
    thisWeek: items.filter((item) => item.isThisWeek).length,
    unassignedOpen: openItems.filter((item) => !item.followUpOwner).length,
    byReviewStatus: items.reduce((acc, item) => {
      acc[item.reviewStatus] = (acc[item.reviewStatus] || 0) + 1;
      return acc;
    }, {}),
    byOwnerOpen: [...ownerMap.values()]
      .sort((a, b) => b.open - a.open || String(a.owner).localeCompare(String(b.owner)))
  };
}

function calibrationAuditQueueFilterOptions(items = []) {
  const ownerCounts = {};
  const monthCounts = {};
  const companyCounts = {};
  items.forEach((item) => {
    const owner = item.followUpOwner || "unassigned";
    ownerCounts[owner] = (ownerCounts[owner] || 0) + 1;
    const month = item.eventMonth || item.targetMonth || "unknown";
    monthCounts[month] = (monthCounts[month] || 0) + 1;
    if (item.companyId) {
      const company = companyCounts[item.companyId] || {
        companyId: item.companyId,
        name: item.companyName || item.companyId,
        region: item.companyRegion || "",
        count: 0
      };
      company.count += 1;
      companyCounts[item.companyId] = company;
    }
  });
  return {
    owners: Object.entries(ownerCounts)
      .map(([owner, count]) => ({ owner, count }))
      .sort((a, b) => b.count - a.count || String(a.owner).localeCompare(String(b.owner))),
    months: Object.entries(monthCounts)
      .map(([month, count]) => ({ month, count }))
      .sort((a, b) => String(b.month).localeCompare(String(a.month))),
    companies: Object.values(companyCounts)
      .sort((a, b) => b.count - a.count || String(a.name).localeCompare(String(b.name))),
    reviewStatuses: ["pending", "in_review", "action_required", "resolved", "deferred"],
    dueStates: ["overdue", "this_week", "upcoming", "no_due"],
    risks: ["high", "medium", "low", "none"]
  };
}

async function learningCalibrationAuditQueue(payload = {}) {
  const report = await learningCalibrationAuditReport({
    limit: 200,
    companyId: payload.companyId,
    month: payload.month,
    risk: payload.risk,
    reviewStatus: payload.reviewStatus
  });
  const companyData = await readCompanyMaster();
  const companyMap = new Map((companyData.items || []).map((company) => [company.companyId, company]));
  const allItems = (report.items || []).map((item) => calibrationAuditQueueItem({
    ...item,
    company: companyMap.get(item.sourceCompanyId || item.auditReview?.companyId || "")
  }));
  const filtered = filterCalibrationAuditQueueItems(allItems, payload);
  const limit = Math.max(1, Math.min(200, Number(payload.limit || 80)));
  const sorted = filtered
    .sort((a, b) => {
      const dueRank = { overdue: 0, this_week: 1, upcoming: 2, no_due: 3 };
      return (dueRank[a.dueState] ?? 9) - (dueRank[b.dueState] ?? 9) ||
        String(a.followUpDueDate || "9999-99-99").localeCompare(String(b.followUpDueDate || "9999-99-99")) ||
        String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
    })
    .slice(0, limit);
  return {
    role: "admin",
    reportType: "learning_calibration_audit_followup_queue",
    generatedAt: new Date().toISOString(),
    filters: {
      companyId: String(payload.companyId || "").trim(),
      month: String(payload.month || "").trim(),
      reviewStatus: normalizeCalibrationAuditReviewStatus(payload.reviewStatus || ""),
      owner: String(payload.owner || "").trim(),
      dueState: String(payload.dueState || "").trim(),
      risk: normalizeCalibrationAuditRisk(payload.risk || ""),
      limit
    },
    summary: calibrationAuditQueueSummary(filtered),
    fullSummary: calibrationAuditQueueSummary(allItems),
    availableFilters: calibrationAuditQueueFilterOptions(allItems),
    reviewHistory: {
      totalLogs: report.reviewHistory?.totalLogs || 0,
      recentBulkOperations: report.reviewHistory?.bulkOperations || []
    },
    operationQuality: report.operationQuality || calibrationAuditOperationQuality([]),
    items: sorted,
    reportBoundaries: {
      source: "admin-only calibration audit review records merged with calibration audit versions",
      hiddenFromBusiness: ["audit review queue", "admin memos", "follow-up owners", "due dates", "settings history"]
    }
  };
}

