function calibrationSlaActionReassessmentSummary(items = []) {
  return {
    total: items.length,
    improved: items.filter((item) => item.reassessment?.evaluationState === "improved").length,
    unchanged: items.filter((item) => item.reassessment?.evaluationState === "unchanged").length,
    worse: items.filter((item) => item.reassessment?.evaluationState === "worse").length,
    recurrence: items.filter((item) => item.reassessment?.recurrence).length,
    followUpNeeded: items.filter((item) => item.reassessment?.followUpNeeded).length,
    noPostLogs: items.filter((item) => !item.reassessment?.postCompletionLogCount).length,
    averageEffectScore: items.length
      ? Math.round(items.reduce((sum, item) => sum + Number(item.reassessment?.effectScore || 0), 0) / items.length)
      : 0
  };
}

function slaActionReassessmentHistoryId(item = {}) {
  return hashId("sarh", [
    item.actionId || "",
    item.evaluatedDate || "",
    item.evaluationState || "",
    item.effectScore ?? "",
    item.recurrence ? "recurrence" : "no_recurrence",
    item.followUpNeeded ? "followup" : "no_followup"
  ].join("|"));
}

function normalizeSlaActionReassessmentHistoryItem(input = {}) {
  const reassessment = input.reassessment || {};
  const evaluatedAt = input.evaluatedAt || reassessment.evaluatedAt || new Date().toISOString();
  const evaluatedDate = String(input.evaluatedDate || evaluatedAt).slice(0, 10);
  const evaluatedMonth = String(input.evaluatedMonth || monthKey(evaluatedAt) || monthKey(evaluatedDate) || "unknown");
  const issueKey = String(input.issueKey || "").trim();
  const rootMetric = String(input.rootMetric || "").trim();
  const effectScore = Math.max(0, Math.min(100, Math.round(Number(input.effectScore ?? reassessment.effectScore ?? 0))));
  const evaluationState = String(input.evaluationState || reassessment.evaluationState || "unchanged").trim();
  const recurrence = Boolean(input.recurrence ?? reassessment.recurrence);
  const followUpNeeded = Boolean(input.followUpNeeded ?? reassessment.followUpNeeded);
  const followUpCreated = Boolean(input.followUpCreated);
  const normalized = {
    historyId: String(input.historyId || "").trim(),
    actionId: String(input.actionId || "").trim(),
    sourceKey: String(input.sourceKey || "").trim(),
    sourceType: String(input.sourceType || "summary").trim() || "summary",
    sourceLabel: String(input.sourceLabel || "").trim(),
    month: String(input.month || "").trim(),
    owner: String(input.owner || "").trim(),
    assignee: String(input.assignee || input.owner || "").trim(),
    issueKey,
    rootMetric,
    issueMetricKey: String(input.issueMetricKey || reassessment.issueMetricKey || calibrationSlaActionIssueMetricKey(issueKey)).trim(),
    issueMetricDelta: input.issueMetricDelta ?? reassessment.issueMetricDelta ?? null,
    riskLevel: normalizeCalibrationSlaActionRisk(input.riskLevel || input.slaLevel || input.severity || ""),
    completedAt: input.completedAt || "",
    evaluatedAt,
    evaluatedDate,
    evaluatedMonth,
    effectScore,
    evaluationState,
    recurrence,
    followUpNeeded,
    followUpReason: String(input.followUpReason || reassessment.followUpReason || "").trim(),
    followUpCreated,
    followUpActionId: String(input.followUpActionId || "").trim(),
    followUpActionSourceKey: String(input.followUpActionSourceKey || "").trim(),
    followUpCreatedAt: input.followUpCreatedAt || "",
    postCompletionLogCount: Number(input.postCompletionLogCount ?? reassessment.postCompletionLogCount ?? 0) || 0,
    scopedLogCount: Number(input.scopedLogCount ?? reassessment.scopedLogCount ?? 0) || 0,
    currentSlaLevel: String(input.currentSlaLevel || reassessment.currentSla?.level || "").trim(),
    snapshotMetrics: input.snapshotMetrics && typeof input.snapshotMetrics === "object" ? input.snapshotMetrics : (reassessment.snapshotMetrics || {}),
    currentMetrics: input.currentMetrics && typeof input.currentMetrics === "object" ? input.currentMetrics : (reassessment.currentMetrics || {}),
    deltas: input.deltas && typeof input.deltas === "object" ? input.deltas : (reassessment.deltas || {}),
    recordedAt: input.recordedAt || new Date().toISOString(),
    recordedBy: String(input.recordedBy || "system").trim() || "system"
  };
  return {
    ...normalized,
    historyId: normalized.historyId || slaActionReassessmentHistoryId(normalized)
  };
}

function historyItemFromSlaActionReassessment(item = {}, options = {}) {
  const reassessment = item.reassessment || {};
  const followUpAction = options.followUpAction || null;
  return normalizeSlaActionReassessmentHistoryItem({
    actionId: item.actionId || "",
    sourceKey: item.sourceKey || "",
    sourceType: item.sourceType || "summary",
    sourceLabel: item.sourceLabel || "",
    month: item.month || "",
    owner: item.owner || "",
    assignee: item.assignee || item.owner || "",
    issueKey: item.issueKey || "",
    rootMetric: item.rootMetric || "",
    riskLevel: item.riskLevel || calibrationSlaActionRiskLevel(item),
    completedAt: item.completedAt || item.updatedAt || "",
    reassessment,
    followUpCreated: Boolean(followUpAction || options.followUpCreated),
    followUpActionId: followUpAction?.actionId || options.followUpActionId || "",
    followUpActionSourceKey: followUpAction?.sourceKey || options.followUpActionSourceKey || "",
    followUpCreatedAt: followUpAction?.createdAt || followUpAction?.updatedAt || options.followUpCreatedAt || "",
    recordedBy: options.recordedBy || "system"
  });
}

async function upsertSlaActionReassessmentHistoryItems(items = [], options = {}) {
  const normalized = items
    .map((item) => historyItemFromSlaActionReassessment(item, options))
    .filter((item) => item.actionId && item.historyId);
  if (!normalized.length) {
    return {
      slaActionReassessmentHistory: null,
      upserted: 0,
      items: []
    };
  }
  const data = await readSlaActionReassessmentHistory();
  const existing = Array.isArray(data.items) ? data.items.map(normalizeSlaActionReassessmentHistoryItem) : [];
  const byId = new Map(existing.map((item) => [item.historyId, item]));
  normalized.forEach((item) => {
    const previous = byId.get(item.historyId);
    byId.set(item.historyId, {
      ...(previous || {}),
      ...item,
      followUpCreated: Boolean(item.followUpCreated || previous?.followUpCreated),
      followUpActionId: item.followUpActionId || previous?.followUpActionId || "",
      followUpActionSourceKey: item.followUpActionSourceKey || previous?.followUpActionSourceKey || "",
      followUpCreatedAt: item.followUpCreatedAt || previous?.followUpCreatedAt || ""
    });
  });
  const updatedItems = [...byId.values()]
    .sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")));
  const updated = await writeSlaActionReassessmentHistory({
    ...data,
    items: updatedItems
  });
  return {
    slaActionReassessmentHistory: {
      schema: updated.schema || "sla_action_reassessment_history_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    upserted: normalized.length,
    items: normalized
  };
}

async function markSlaActionReassessmentHistoryFollowUp(sourceItem = {}, followUpAction = {}, recordedBy = "admin") {
  const data = await readSlaActionReassessmentHistory();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaActionReassessmentHistoryItem) : [];
  const sourceActionId = sourceItem.actionId || "";
  let latestIndex = -1;
  items.forEach((item, index) => {
    if (item.actionId !== sourceActionId) return;
    if (latestIndex === -1 || String(item.evaluatedAt || "").localeCompare(String(items[latestIndex].evaluatedAt || "")) > 0) {
      latestIndex = index;
    }
  });
  if (latestIndex >= 0) {
    items[latestIndex] = normalizeSlaActionReassessmentHistoryItem({
      ...items[latestIndex],
      followUpCreated: true,
      followUpActionId: followUpAction.actionId || "",
      followUpActionSourceKey: followUpAction.sourceKey || "",
      followUpCreatedAt: followUpAction.createdAt || followUpAction.updatedAt || new Date().toISOString(),
      recordedBy
    });
    const updated = await writeSlaActionReassessmentHistory({
      ...data,
      items: items.sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")))
    });
    return {
      slaActionReassessmentHistory: {
        schema: updated.schema || "sla_action_reassessment_history_v1",
        total: updated.items.length,
        updatedAt: updated.updatedAt
      },
      updated: 1,
      item: items[latestIndex]
    };
  }
  const upsert = await upsertSlaActionReassessmentHistoryItems([sourceItem], { followUpAction, recordedBy });
  return {
    slaActionReassessmentHistory: upsert.slaActionReassessmentHistory,
    updated: upsert.upserted,
    item: upsert.items?.[0] || null
  };
}

function filterSlaActionReassessmentHistoryItems(items = [], payload = {}) {
  const owner = String(payload.owner || "").trim().toLowerCase();
  const month = String(payload.month || "").trim();
  const issueKey = String(payload.issueKey || payload.rootMetric || "").trim();
  const outcome = String(payload.outcome || "").trim().toLowerCase();
  const followUp = String(payload.followUp || "").trim().toLowerCase();
  return items
    .filter((item) => !owner || String(item.assignee || item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !month || item.evaluatedMonth === month || item.month === month)
    .filter((item) => !issueKey || item.issueKey === issueKey || item.rootMetric.includes(issueKey))
    .filter((item) => !outcome || item.evaluationState === outcome)
    .filter((item) => followUp === "created" ? item.followUpCreated : followUp === "needed" ? item.followUpNeeded : followUp === "none" ? !item.followUpNeeded : true);
}

function slaActionReassessmentHistorySummary(items = []) {
  return {
    total: items.length,
    improved: items.filter((item) => item.evaluationState === "improved").length,
    unchanged: items.filter((item) => item.evaluationState === "unchanged").length,
    worse: items.filter((item) => item.evaluationState === "worse").length,
    recurrence: items.filter((item) => item.recurrence).length,
    followUpNeeded: items.filter((item) => item.followUpNeeded).length,
    followUpCreated: items.filter((item) => item.followUpCreated).length,
    averageEffectScore: items.length
      ? Math.round(items.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / items.length)
      : 0
  };
}

function slaActionReassessmentHistoryGroups(items = [], keyFn = () => "", labelFn = (key) => key) {
  const map = new Map();
  items.forEach((item) => {
    const key = keyFn(item) || "unknown";
    const row = map.get(key) || {
      key,
      label: labelFn(key, item),
      total: 0,
      improved: 0,
      unchanged: 0,
      worse: 0,
      recurrence: 0,
      followUpNeeded: 0,
      followUpCreated: 0,
      scoreTotal: 0,
      latestEvaluatedAt: ""
    };
    row.total += 1;
    row.improved += item.evaluationState === "improved" ? 1 : 0;
    row.unchanged += item.evaluationState === "unchanged" ? 1 : 0;
    row.worse += item.evaluationState === "worse" ? 1 : 0;
    row.recurrence += item.recurrence ? 1 : 0;
    row.followUpNeeded += item.followUpNeeded ? 1 : 0;
    row.followUpCreated += item.followUpCreated ? 1 : 0;
    row.scoreTotal += Number(item.effectScore || 0);
    row.latestEvaluatedAt = String(item.evaluatedAt || "").localeCompare(row.latestEvaluatedAt || "") > 0 ? item.evaluatedAt : row.latestEvaluatedAt;
    map.set(key, row);
  });
  return [...map.values()]
    .map((row) => ({
      ...row,
      averageEffectScore: row.total ? Math.round(row.scoreTotal / row.total) : 0,
      improvedRate: row.total ? Math.round((row.improved / row.total) * 100) : 0,
      recurrenceRate: row.total ? Math.round((row.recurrence / row.total) * 100) : 0,
      followUpCreatedRate: row.followUpNeeded ? Math.round((row.followUpCreated / row.followUpNeeded) * 100) : 0
    }))
    .sort((a, b) => b.total - a.total || b.averageEffectScore - a.averageEffectScore || String(a.label).localeCompare(String(b.label)));
}

function slaActionReassessmentHistoryAggregates(items = []) {
  const byIssue = slaActionReassessmentHistoryGroups(
    items,
    (item) => item.issueKey || item.rootMetric || "unknown",
    (key, item) => item.issueKey || item.rootMetric || key
  );
  return {
    byMonth: slaActionReassessmentHistoryGroups(items, (item) => item.evaluatedMonth || "unknown"),
    byAssignee: slaActionReassessmentHistoryGroups(items, (item) => item.assignee || item.owner || "unassigned"),
    byIssue,
    effectiveActionTypes: [...byIssue]
      .filter((row) => row.total > 0)
      .sort((a, b) => b.averageEffectScore - a.averageEffectScore || b.improvedRate - a.improvedRate)
      .slice(0, 8),
    weakActionTypes: [...byIssue]
      .filter((row) => row.total > 0)
      .sort((a, b) => a.averageEffectScore - b.averageEffectScore || b.recurrenceRate - a.recurrenceRate)
      .slice(0, 8)
  };
}

function calibrationSlaHistoryStats(items = []) {
  const total = items.length;
  const averageEffectScore = total
    ? Math.round(items.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / total)
    : 50;
  return {
    total,
    averageEffectScore,
    improvedRate: total ? Math.round((items.filter((item) => item.evaluationState === "improved").length / total) * 100) : 0,
    worseRate: total ? Math.round((items.filter((item) => item.evaluationState === "worse").length / total) * 100) : 0,
    recurrenceRate: total ? Math.round((items.filter((item) => item.recurrence).length / total) * 100) : 0,
    followUpNeededRate: total ? Math.round((items.filter((item) => item.followUpNeeded).length / total) * 100) : 0
  };
}

function calibrationSlaHistoryWeightedScore(parts = []) {
  const active = parts.filter((part) => part.stats.total > 0 && part.weight > 0);
  if (!active.length) {
    return {
      score: 50,
      sampleSize: 0
    };
  }
  const weightTotal = active.reduce((sum, part) => sum + part.weight, 0);
  return {
    score: Math.round(active.reduce((sum, part) => sum + part.stats.averageEffectScore * part.weight, 0) / weightTotal),
    sampleSize: active.reduce((sum, part) => sum + part.stats.total, 0)
  };
}

function calibrationSlaActionHistoryAdjustment(action = {}, historyItems = []) {
  const normalizedHistory = historyItems.map(normalizeSlaActionReassessmentHistoryItem);
  const issueKey = action.issueKey || "";
  const assignee = String(action.assignee || action.owner || "").trim().toLowerCase();
  const month = String(action.month || "").trim();
  const issueItems = normalizedHistory.filter((item) => item.issueKey === issueKey);
  const assigneeItems = assignee
    ? normalizedHistory.filter((item) => String(item.assignee || item.owner || "").toLowerCase() === assignee)
    : [];
  const monthItems = month
    ? normalizedHistory.filter((item) => item.evaluatedMonth === month || item.month === month)
    : [];
  const issueStats = calibrationSlaHistoryStats(issueItems);
  const assigneeStats = calibrationSlaHistoryStats(assigneeItems);
  const monthStats = calibrationSlaHistoryStats(monthItems);
  const weighted = calibrationSlaHistoryWeightedScore([
    { weight: 0.6, stats: issueStats },
    { weight: 0.25, stats: assigneeStats },
    { weight: 0.15, stats: monthStats }
  ]);
  const sampleSize = new Set([...issueItems, ...assigneeItems, ...monthItems].map((item) => item.historyId || item.actionId)).size;
  let direction = "neutral";
  if (sampleSize > 0 && weighted.score >= 70 && issueStats.improvedRate >= 50 && issueStats.recurrenceRate <= 25) {
    direction = "boost";
  } else if (sampleSize > 0 && (weighted.score < 45 || issueStats.recurrenceRate >= 50 || issueStats.worseRate >= 50)) {
    direction = "downgrade";
  }
  const originalPriority = normalizeCalibrationSlaActionPriority(action.priority) || "medium";
  const adjustedPriority = shiftCalibrationSlaActionPriority(originalPriority, direction, action);
  const reasons = [];
  if (sampleSize > 0) {
    reasons.push(`History score ${weighted.score} from ${sampleSize} reassessment row(s).`);
    if (issueStats.total) {
      reasons.push(`${issueKey || "same issue"} history: avg ${issueStats.averageEffectScore}, improved ${issueStats.improvedRate}%, recurrence ${issueStats.recurrenceRate}%.`);
    }
    if (assigneeStats.total) {
      reasons.push(`Assignee history: avg ${assigneeStats.averageEffectScore} across ${assigneeStats.total} row(s).`);
    }
    if (monthStats.total) {
      reasons.push(`Month history: avg ${monthStats.averageEffectScore} across ${monthStats.total} row(s).`);
    }
  } else {
    reasons.push("No reassessment history yet; base SLA priority is unchanged.");
  }
  if (direction === "boost" && adjustedPriority !== originalPriority) {
    reasons.push(`Priority raised from ${originalPriority} to ${adjustedPriority}.`);
  } else if (direction === "downgrade" && adjustedPriority !== originalPriority) {
    reasons.push(`Priority lowered from ${originalPriority} to ${adjustedPriority}.`);
  } else if (direction !== "neutral") {
    reasons.push(`History suggests ${direction}, but the current SLA severity keeps priority at ${adjustedPriority}.`);
  }
  return {
    applied: sampleSize > 0,
    direction,
    historyEffectScore: weighted.score,
    sampleSize,
    originalPriority,
    adjustedPriority,
    issueStats,
    assigneeStats,
    monthStats,
    reasons,
    recommendationNote: reasons.join(" ")
  };
}

function slaActionRecommendationAdjustmentId(sourceKey = "", adjustment = {}) {
  return hashId("sara", [
    sourceKey || "",
    adjustment.direction || "neutral",
    adjustment.historyEffectScore ?? "",
    adjustment.originalPriority || "",
    adjustment.adjustedPriority || ""
  ].join("|"));
}

function normalizeSlaActionRecommendationAdjustmentStatus(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["proposed", "approved", "rejected"].includes(text)) return text;
  return "proposed";
}

function normalizeSlaActionRecommendationApprovalMode(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["auto", "manual", "none"].includes(text)) return text;
  return "none";
}

const SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY = Object.freeze({
  policyVersion: "sla_rec_auto_approval_v1",
  enabled: true,
  minSampleSize: 3,
  maxPriorityStepChange: 1,
  minHistoricalApprovalSuccessRate: 70,
  issueRules: {},
  boost: {
    minEffectScore: 75,
    minImprovementRate: 60,
    maxRecurrenceRate: 20
  },
  downgrade: {
    maxEffectScore: 35,
    minRecurrenceRate: 60,
    maxImprovementRate: 40
  },
  impactScope: {
    low: ["owner"],
    medium: ["month"],
    high: ["summary"]
  }
});

function cloneSlaAutoApprovalPolicy(policy = SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  return JSON.parse(JSON.stringify(policy));
}

function normalizeSlaAutoApprovalPolicyAdjustmentStatus(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["proposed", "approved", "rejected"].includes(text)) return text;
  return "proposed";
}

function slaAutoApprovalPolicyAdjustmentId(candidate = {}) {
  return hashId("saapa", [
    candidate.type || candidate.candidateType || "",
    candidate.target || "",
    candidate.issueKey || "",
    candidate.priority || "",
    candidate.basis || ""
  ].join("|"));
}

function slaAutoApprovalPolicySnapshot(policy = {}, candidate = {}) {
  const issueKey = String(candidate.issueKey || candidate.target || "").trim();
  const issuePolicy = slaAutoApprovalPolicyForProposal(policy, { issueKey });
  return {
    policyVersion: policy.policyVersion || SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY.policyVersion,
    issueKey,
    enabled: Boolean(policy.enabled),
    issueAutoApprovalEnabled: issuePolicy.enabled,
    minSampleSize: issuePolicy.minSampleSize,
    maxPriorityStepChange: issuePolicy.maxPriorityStepChange,
    minHistoricalApprovalSuccessRate: issuePolicy.minHistoricalApprovalSuccessRate,
    boost: issuePolicy.boost,
    downgrade: issuePolicy.downgrade
  };
}

function slaAutoApprovalPolicyPatchFromCandidate(candidate = {}, policy = SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  const issueKey = String(candidate.issueKey || candidate.target || "").trim();
  if (candidateType === "rollback_policy_adjustment") {
    const sourceBefore = candidate.sourceBeforePolicy && typeof candidate.sourceBeforePolicy === "object" ? candidate.sourceBeforePolicy : {};
    const sourcePatch = candidate.sourcePolicyPatch && typeof candidate.sourcePolicyPatch === "object" ? candidate.sourcePolicyPatch : {};
    if (sourcePatch.global) {
      return {
        global: {
          minSampleSize: Math.max(2, Number(sourceBefore.minSampleSize || policy.minSampleSize || 3))
        }
      };
    }
    if (issueKey) {
      return {
        issueRules: {
          [issueKey]: {
            autoApprovalEnabled: sourceBefore.issueAutoApprovalEnabled !== false,
            minSampleSize: Math.max(2, Number(sourceBefore.minSampleSize || policy.minSampleSize || 3)),
            maxPriorityStepChange: Math.max(0, Number(sourceBefore.maxPriorityStepChange || policy.maxPriorityStepChange || 1)),
            minHistoricalApprovalSuccessRate: Math.max(0, Number(sourceBefore.minHistoricalApprovalSuccessRate || policy.minHistoricalApprovalSuccessRate || 70)),
            reason: candidate.recommendation || "Rollback candidate generated from weak post-change policy effectiveness."
          }
        }
      };
    }
  }
  if (candidateType === "partial_relaxation_policy" && issueKey) {
    const issuePolicy = slaAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: true,
          minSampleSize: Math.max(2, Number(issuePolicy.minSampleSize || 3) - 1),
          minHistoricalApprovalSuccessRate: Math.max(60, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) - 3),
          reason: candidate.recommendation || "Partial relaxation candidate generated after stable manual review conversion."
        }
      }
    };
  }
  if (candidateType === "additional_tightening_policy" && issueKey) {
    const issuePolicy = slaAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: false,
          minSampleSize: Math.max(Number(issuePolicy.minSampleSize || 3) + 1, Number(policy.minSampleSize || 3) + 1),
          minHistoricalApprovalSuccessRate: Math.min(95, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) + 5),
          reason: candidate.recommendation || "Additional tightening candidate generated from recurring post-change failures."
        }
      }
    };
  }
  if (candidateType === "tighten_issue_policy" && issueKey) {
    const issuePolicy = slaAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: false,
          minSampleSize: Math.max(Number(issuePolicy.minSampleSize || 3), Number(policy.minSampleSize || 3) + 1),
          reason: candidate.recommendation || "Manual review required until auto approval outcomes improve."
        }
      }
    };
  }
  if (candidateType === "consider_relaxing_issue_policy" && issueKey) {
    const issuePolicy = slaAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: true,
          minSampleSize: Math.max(2, Number(issuePolicy.minSampleSize || 3) - 1),
          minHistoricalApprovalSuccessRate: Math.max(60, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) - 5),
          reason: candidate.recommendation || "Stable issue history can carry a slightly lighter review threshold."
        }
      }
    };
  }
  if (candidateType === "increase_monitoring_window") {
    return {
      global: {
        minSampleSize: Math.max(3, Number(policy.minSampleSize || 3) + 1)
      }
    };
  }
  return {};
}

function slaAutoApprovalExpectedImpact(candidate = {}) {
  const metrics = candidate.metrics || {};
  const currentSuccessRate = Number(metrics.successRate ?? 0);
  let expectedSuccessRate = currentSuccessRate;
  if ((candidate.candidateType || candidate.type) === "rollback_policy_adjustment") {
    expectedSuccessRate = Number(metrics.beforeSuccessRate ?? Math.max(currentSuccessRate, Number(metrics.successRateBefore || 0)));
  } else if ((candidate.candidateType || candidate.type) === "partial_relaxation_policy") {
    expectedSuccessRate = Math.max(0, currentSuccessRate - 5);
  } else if ((candidate.candidateType || candidate.type) === "additional_tightening_policy") {
    expectedSuccessRate = Math.min(100, currentSuccessRate + 10);
  } else if ((candidate.candidateType || candidate.type) === "tighten_issue_policy") {
    const riskPressure = Math.round((Number(metrics.falsePositiveRate || 0) + Number(metrics.rollbackRate || 0) + Number(metrics.recurrenceRate || 0)) / 6);
    expectedSuccessRate = Math.min(100, currentSuccessRate + Math.max(8, riskPressure));
  } else if ((candidate.candidateType || candidate.type) === "consider_relaxing_issue_policy") {
    expectedSuccessRate = Math.max(0, currentSuccessRate - 5);
  } else if ((candidate.candidateType || candidate.type) === "increase_monitoring_window") {
    expectedSuccessRate = Math.min(100, currentSuccessRate + 5);
  }
  return {
    scope: (candidate.candidateType || candidate.type) === "increase_monitoring_window" ? "global_policy" : "issue_policy",
    affectedTarget: String(candidate.target || candidate.issueKey || "").trim(),
    currentSuccessRate,
    expectedSuccessRate,
    expectedSuccessRateChange: expectedSuccessRate - currentSuccessRate,
    currentFalsePositiveRate: Number(metrics.falsePositiveRate || 0),
    currentRollbackRate: Number(metrics.rollbackRate || 0),
    currentRecurrenceRate: Number(metrics.recurrenceRate || 0),
    evaluated: Number(metrics.evaluated || 0),
    total: Number(metrics.total || 0),
    basis: candidate.basis || ""
  };
}

function normalizeSlaAutoApprovalPolicyAdjustment(input = {}) {
  const now = new Date().toISOString();
  const candidateType = String(input.candidateType || input.type || "policy_adjustment").trim();
  const target = String(input.target || input.issueKey || "").trim();
  const policyPatch = input.policyPatch && typeof input.policyPatch === "object"
    ? input.policyPatch
    : slaAutoApprovalPolicyPatchFromCandidate({ ...input, candidateType, target });
  return {
    policyAdjustmentId: String(input.policyAdjustmentId || slaAutoApprovalPolicyAdjustmentId({ ...input, candidateType, target })).trim(),
    candidateType,
    target,
    issueKey: String(input.issueKey || target).trim(),
    priority: normalizeCalibrationSlaActionPriority(input.priority || "medium"),
    basis: String(input.basis || "").trim(),
    recommendation: String(input.recommendation || "").trim(),
    status: normalizeSlaAutoApprovalPolicyAdjustmentStatus(input.status || "proposed"),
    policyPatch,
    beforePolicy: input.beforePolicy && typeof input.beforePolicy === "object" ? input.beforePolicy : {},
    afterPolicy: input.afterPolicy && typeof input.afterPolicy === "object" ? input.afterPolicy : {},
    expectedImpact: input.expectedImpact && typeof input.expectedImpact === "object" ? input.expectedImpact : slaAutoApprovalExpectedImpact(input),
    metrics: input.metrics && typeof input.metrics === "object" ? input.metrics : {},
    qualityCalibration: input.qualityCalibration && typeof input.qualityCalibration === "object" ? input.qualityCalibration : {},
    sourceContext: input.sourceContext && typeof input.sourceContext === "object" ? input.sourceContext : {},
    sourcePolicyAdjustmentId: String(input.sourcePolicyAdjustmentId || input.sourceContext?.policyAdjustmentId || "").trim(),
    sourceEffectOutcome: String(input.sourceEffectOutcome || input.sourceContext?.outcome || "").trim(),
    sourceEffectScore: Number.isFinite(Number(input.sourceEffectScore ?? input.sourceContext?.effectScore)) ? Number(input.sourceEffectScore ?? input.sourceContext?.effectScore) : null,
    duplicateStatus: String(input.duplicateStatus || "").trim(),
    duplicateOfPolicyAdjustmentId: String(input.duplicateOfPolicyAdjustmentId || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    reviewReason: String(input.reviewReason || "").trim(),
    approvedAt: input.approvedAt || "",
    rejectedAt: input.rejectedAt || "",
    updatedAt: input.updatedAt || input.reviewedAt || input.proposedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system"
  };
}

function slaAutoApprovalPolicyForProposal(policy = {}, proposal = {}) {
  const issueRule = policy.issueRules?.[proposal.issueKey] || {};
  return {
    enabled: policy.enabled && issueRule.autoApprovalEnabled !== false,
    minSampleSize: Number(issueRule.minSampleSize ?? policy.minSampleSize ?? 3),
    maxPriorityStepChange: Number(issueRule.maxPriorityStepChange ?? policy.maxPriorityStepChange ?? 1),
    minHistoricalApprovalSuccessRate: Number(issueRule.minHistoricalApprovalSuccessRate ?? policy.minHistoricalApprovalSuccessRate ?? 70),
    boost: {
      minEffectScore: Number(issueRule.boost?.minEffectScore ?? policy.boost?.minEffectScore ?? 75),
      minImprovementRate: Number(issueRule.boost?.minImprovementRate ?? policy.boost?.minImprovementRate ?? 60),
      maxRecurrenceRate: Number(issueRule.boost?.maxRecurrenceRate ?? policy.boost?.maxRecurrenceRate ?? 20)
    },
    downgrade: {
      maxEffectScore: Number(issueRule.downgrade?.maxEffectScore ?? policy.downgrade?.maxEffectScore ?? 35),
      minRecurrenceRate: Number(issueRule.downgrade?.minRecurrenceRate ?? policy.downgrade?.minRecurrenceRate ?? 60),
      maxImprovementRate: Number(issueRule.downgrade?.maxImprovementRate ?? policy.downgrade?.maxImprovementRate ?? 40)
    },
    issueRule
  };
}

function applySlaAutoApprovalPolicyPatch(policy = {}, patch = {}) {
  const next = cloneSlaAutoApprovalPolicy(policy);
  if (patch.global && typeof patch.global === "object") {
    Object.entries(patch.global).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== "") next[key] = value;
    });
  }
  if (patch.issueRules && typeof patch.issueRules === "object") {
    next.issueRules = {
      ...(next.issueRules || {})
    };
    Object.entries(patch.issueRules).forEach(([issueKey, rule]) => {
      next.issueRules[issueKey] = {
        ...(next.issueRules[issueKey] || {}),
        ...(rule || {})
      };
    });
  }
  return next;
}

function activeSlaAutoApprovalPolicy(policyAdjustments = []) {
  const approved = policyAdjustments
    .map(normalizeSlaAutoApprovalPolicyAdjustment)
    .filter((item) => item.status === "approved")
    .sort((a, b) => String(a.approvedAt || a.updatedAt || "").localeCompare(String(b.approvedAt || b.updatedAt || "")));
  const policy = approved.reduce((current, item) => applySlaAutoApprovalPolicyPatch(current, item.policyPatch || {}), cloneSlaAutoApprovalPolicy());
  return {
    ...policy,
    policyVersion: `${SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY.policyVersion}+${approved.length}`,
    activeAdjustmentIds: approved.map((item) => item.policyAdjustmentId)
  };
}

function slaActionRecommendationPriorityDistance(originalPriority = "", proposedPriority = "") {
  return Math.abs(calibrationSlaActionPriorityRank(originalPriority) - calibrationSlaActionPriorityRank(proposedPriority));
}

function slaActionRecommendationImpactScope(proposal = {}, policy = SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const sourceType = String(proposal.sourceType || "summary").trim() || "summary";
  let level = "medium";
  if ((policy.impactScope?.low || []).includes(sourceType)) level = "low";
  if ((policy.impactScope?.high || []).includes(sourceType)) level = "high";
  const priorityStepChange = slaActionRecommendationPriorityDistance(proposal.originalPriority, proposal.proposedPriority);
  const proposalPolicy = slaAutoApprovalPolicyForProposal(policy, proposal);
  if (priorityStepChange > proposalPolicy.maxPriorityStepChange) level = "high";
  return {
    sourceType,
    level,
    priorityStepChange,
    reason: level === "low"
      ? "Owner-scoped correction with limited blast radius."
      : level === "medium"
        ? "Month-scoped correction requires manual review unless evidence becomes stronger."
        : "Summary-level or large priority movement can affect broad SLA operations."
  };
}

function slaActionRecommendationHistoricalApprovalStats(proposal = {}, existingItems = []) {
  const reviewed = existingItems
    .map(normalizeSlaActionRecommendationAdjustment)
    .filter((item) => item.adjustmentId !== proposal.adjustmentId)
    .filter((item) => ["approved", "rejected"].includes(item.status))
    .filter((item) => item.issueKey === proposal.issueKey && item.direction === proposal.direction);
  const approved = reviewed.filter((item) => item.status === "approved").length;
  const rejected = reviewed.filter((item) => item.status === "rejected").length;
  const total = approved + rejected;
  return {
    reviewed: total,
    approved,
    rejected,
    successRate: total ? Math.round((approved / total) * 100) : 100,
    basis: total ? "same issue and direction review history" : "no prior conflict; default neutral success baseline"
  };
}

function evaluateSlaRecommendationAutoApproval(proposal = {}, existingItems = [], policy = SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const proposalPolicy = slaAutoApprovalPolicyForProposal(policy, proposal);
  const impact = slaActionRecommendationImpactScope(proposal, policy);
  const historicalApproval = slaActionRecommendationHistoricalApprovalStats(proposal, existingItems);
  const sampleSize = Number(proposal.sampleSize || 0);
  const effectScore = Number(proposal.historyEffectScore || 0);
  const recurrenceRate = Number(proposal.recurrenceRate || 0);
  const improvementRate = Number(proposal.improvementRate || 0);
  const direction = String(proposal.direction || "neutral").trim();
  const criteria = {
    policyEnabled: proposalPolicy.enabled,
    sampleSizeOk: sampleSize >= proposalPolicy.minSampleSize,
    impactScopeOk: impact.level === "low",
    priorityStepOk: impact.priorityStepChange <= proposalPolicy.maxPriorityStepChange,
    historicalApprovalOk: historicalApproval.successRate >= proposalPolicy.minHistoricalApprovalSuccessRate,
    directionEvidenceOk: false
  };
  if (direction === "boost") {
    criteria.directionEvidenceOk = effectScore >= proposalPolicy.boost.minEffectScore &&
      improvementRate >= proposalPolicy.boost.minImprovementRate &&
      recurrenceRate <= proposalPolicy.boost.maxRecurrenceRate;
  } else if (direction === "downgrade") {
    criteria.directionEvidenceOk = (effectScore <= proposalPolicy.downgrade.maxEffectScore || recurrenceRate >= proposalPolicy.downgrade.minRecurrenceRate) &&
      improvementRate <= proposalPolicy.downgrade.maxImprovementRate;
  }
  const blockingReasons = [];
  if (!proposalPolicy.enabled) blockingReasons.push("Auto approval policy is disabled for this issue.");
  if (!criteria.sampleSizeOk) blockingReasons.push(`Sample size ${sampleSize} is below ${proposalPolicy.minSampleSize}.`);
  if (!criteria.impactScopeOk) blockingReasons.push(`Impact scope is ${impact.level}, not low.`);
  if (!criteria.priorityStepOk) blockingReasons.push(`Priority movement is ${impact.priorityStepChange} step(s).`);
  if (!criteria.historicalApprovalOk) blockingReasons.push(`Historical approval success ${historicalApproval.successRate}% is below ${proposalPolicy.minHistoricalApprovalSuccessRate}%.`);
  if (!criteria.directionEvidenceOk) blockingReasons.push("Direction evidence is not strong enough for automatic approval.");
  let riskLevel = "low";
  if (blockingReasons.length) riskLevel = "medium";
  if (impact.level === "high" || sampleSize < 2 || historicalApproval.successRate < 50) riskLevel = "high";
  const eligible = proposalPolicy.enabled && riskLevel === "low" && Object.values(criteria).every(Boolean);
  const reasons = eligible
    ? [
        `Auto-approved by ${policy.policyVersion}.`,
        `Samples ${sampleSize}, score ${effectScore}, improvement ${improvementRate}%, recurrence ${recurrenceRate}%.`,
        `Impact ${impact.level}, historical approval success ${historicalApproval.successRate}%.`
      ]
    : blockingReasons;
  return {
    policyVersion: policy.policyVersion,
    activeAdjustmentIds: policy.activeAdjustmentIds || [],
    evaluatedAt: new Date().toISOString(),
    eligible,
    riskLevel,
    criteria,
    metrics: {
      sampleSize,
      effectScore,
      recurrenceRate,
      improvementRate,
      direction,
      originalPriority: proposal.originalPriority || "",
      proposedPriority: proposal.proposedPriority || ""
    },
    impact,
    historicalApproval,
    reasons
  };
}

function slaActionRecommendationAutoApprovalLogId(adjustmentId = "", eventType = "", eventAt = "") {
  return hashId("sraal", [adjustmentId, eventType, eventAt].join("|"));
}

function normalizeSlaActionRecommendationAutoApprovalLog(input = {}) {
  const eventAt = input.eventAt || new Date().toISOString();
  const adjustmentId = String(input.adjustmentId || "").trim();
  const eventType = String(input.eventType || "auto_approved").trim();
  return {
    logId: String(input.logId || slaActionRecommendationAutoApprovalLogId(adjustmentId, eventType, eventAt)).trim(),
    adjustmentId,
    sourceKey: String(input.sourceKey || "").trim(),
    eventType,
    eventAt,
    eventBy: String(input.eventBy || "system_auto").trim() || "system_auto",
    previousStatus: String(input.previousStatus || "").trim(),
    nextStatus: String(input.nextStatus || "").trim(),
    rollbackAvailable: Boolean(input.rollbackAvailable),
    rolledBack: Boolean(input.rolledBack),
    policyDecision: input.policyDecision && typeof input.policyDecision === "object" ? input.policyDecision : {},
    reason: String(input.reason || "").trim()
  };
}

async function appendSlaActionRecommendationAutoApprovalLog(entry = {}) {
  const data = await readSlaActionRecommendationAutoApprovalLogs();
  const normalized = normalizeSlaActionRecommendationAutoApprovalLog(entry);
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaActionRecommendationAutoApprovalLog) : [];
  if (items.some((item) => item.adjustmentId === normalized.adjustmentId && item.eventType === normalized.eventType && item.nextStatus === normalized.nextStatus)) {
    return {
      log: normalized,
      data
    };
  }
  const updated = await writeSlaActionRecommendationAutoApprovalLogs({
    ...data,
    items: [normalized, ...items].sort((a, b) => String(b.eventAt || "").localeCompare(String(a.eventAt || "")))
  });
  return {
    log: normalized,
    data: updated
  };
}

function normalizeSlaActionRecommendationAdjustment(input = {}) {
  const now = new Date().toISOString();
  const sourceKey = String(input.sourceKey || "").trim();
  const adjustment = input.adjustment && typeof input.adjustment === "object" ? input.adjustment : {};
  const proposedPriority = normalizeCalibrationSlaActionPriority(input.proposedPriority || adjustment.adjustedPriority || input.originalPriority || adjustment.originalPriority || "medium") || "medium";
  const originalPriority = normalizeCalibrationSlaActionPriority(input.originalPriority || adjustment.originalPriority || proposedPriority) || proposedPriority;
  const statusValue = normalizeSlaActionRecommendationAdjustmentStatus(input.status);
  const approvedAt = input.approvedAt || (statusValue === "approved" ? now : "");
  const rejectedAt = input.rejectedAt || (statusValue === "rejected" ? now : "");
  return {
    adjustmentId: String(input.adjustmentId || slaActionRecommendationAdjustmentId(sourceKey, adjustment)).trim(),
    sourceKey,
    actionId: String(input.actionId || "").trim(),
    sourceType: String(input.sourceType || "summary").trim() || "summary",
    sourceLabel: String(input.sourceLabel || "").trim(),
    month: String(input.month || "").trim(),
    owner: String(input.owner || "").trim(),
    issueKey: String(input.issueKey || "").trim(),
    rootMetric: String(input.rootMetric || "").trim(),
    originalPriority,
    proposedPriority,
    activePriority: normalizeCalibrationSlaActionPriority(input.activePriority || (statusValue === "approved" ? proposedPriority : "")),
    direction: String(input.direction || adjustment.direction || "neutral").trim(),
    historyEffectScore: Math.max(0, Math.min(100, Math.round(Number(input.historyEffectScore ?? adjustment.historyEffectScore ?? 50)))),
    recurrenceRate: Math.max(0, Math.min(100, Math.round(Number(input.recurrenceRate ?? adjustment.issueStats?.recurrenceRate ?? 0)))),
    improvementRate: Math.max(0, Math.min(100, Math.round(Number(input.improvementRate ?? adjustment.issueStats?.improvedRate ?? 0)))),
    sampleSize: Math.max(0, Math.round(Number(input.sampleSize ?? adjustment.sampleSize ?? 0))),
    recommendationBefore: String(input.recommendationBefore || "").trim(),
    recommendationAfter: String(input.recommendationAfter || "").trim(),
    reason: String(input.reason || adjustment.recommendationNote || "").trim(),
    adjustment,
    status: statusValue,
    approvalMode: normalizeSlaActionRecommendationApprovalMode(input.approvalMode || (statusValue === "approved" && String(input.reviewedBy || "").startsWith("system_auto") ? "auto" : statusValue === "approved" || statusValue === "rejected" ? "manual" : "none")),
    autoApprovalPolicy: input.autoApprovalPolicy && typeof input.autoApprovalPolicy === "object" ? input.autoApprovalPolicy : null,
    rollbackAvailable: Boolean(input.rollbackAvailable),
    rolledBackAt: input.rolledBackAt || "",
    rolledBackBy: String(input.rolledBackBy || "").trim(),
    rollbackReason: String(input.rollbackReason || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || approvedAt || rejectedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    reviewReason: String(input.reviewReason || "").trim(),
    approvedAt,
    rejectedAt,
    updatedAt: input.updatedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system"
  };
}

function activeSlaRecommendationAdjustmentForAction(action = {}, adjustments = []) {
  const sourceKey = action.sourceKey || "";
  const candidates = adjustments
    .map(normalizeSlaActionRecommendationAdjustment)
    .filter((item) => item.status === "approved" && item.sourceKey === sourceKey);
  return candidates.sort((a, b) => String(b.approvedAt || b.updatedAt || "").localeCompare(String(a.approvedAt || a.updatedAt || "")))[0] || null;
}

function proposedSlaRecommendationAdjustmentForAction(action = {}, adjustments = [], calculated = {}) {
  const sourceKey = action.sourceKey || "";
  const calculatedId = slaActionRecommendationAdjustmentId(sourceKey, calculated);
  return adjustments
    .map(normalizeSlaActionRecommendationAdjustment)
    .find((item) => item.adjustmentId === calculatedId || (item.status === "proposed" && item.sourceKey === sourceKey && item.direction === calculated.direction && item.proposedPriority === calculated.adjustedPriority));
}

async function upsertSlaActionRecommendationAdjustmentProposal(action = {}, adjustment = {}) {
  if (!adjustment.applied || adjustment.direction === "neutral") return null;
  const [data, policyAdjustmentData] = await Promise.all([
    readSlaActionRecommendationAdjustments(),
    readSlaAutoApprovalPolicyAdjustments()
  ]);
  const existingItems = Array.isArray(data.items) ? data.items.map(normalizeSlaActionRecommendationAdjustment) : [];
  const activePolicy = activeSlaAutoApprovalPolicy(policyAdjustmentData.items || []);
  const baseProposal = normalizeSlaActionRecommendationAdjustment({
    sourceKey: action.sourceKey || "",
    actionId: action.actionId || "",
    sourceType: action.sourceType || "summary",
    sourceLabel: action.sourceLabel || "",
    month: action.month || "",
    owner: action.owner || "",
    issueKey: action.issueKey || "",
    rootMetric: action.rootMetric || "",
    originalPriority: adjustment.originalPriority,
    proposedPriority: adjustment.adjustedPriority,
    direction: adjustment.direction,
    historyEffectScore: adjustment.historyEffectScore,
    recurrenceRate: adjustment.issueStats?.recurrenceRate || 0,
    improvementRate: adjustment.issueStats?.improvedRate || 0,
    sampleSize: adjustment.sampleSize,
    recommendationBefore: action.recommendation || "",
    recommendationAfter: [action.recommendation || "", `History adjustment: ${adjustment.recommendationNote}`].filter(Boolean).join(" "),
    reason: adjustment.recommendationNote,
    adjustment,
    status: "proposed",
    proposedBy: "system"
  });
  const activeSame = existingItems.find((item) => item.status === "approved" && item.sourceKey === baseProposal.sourceKey);
  const reviewedSame = existingItems.find((item) => item.adjustmentId === baseProposal.adjustmentId && ["approved", "rejected"].includes(item.status));
  if (activeSame || reviewedSame) {
    return reviewedSame || activeSame || null;
  }
  const byId = new Map(existingItems.map((item) => [item.adjustmentId, item]));
  const existingProposal = byId.get(baseProposal.adjustmentId) || null;
  const proposal = normalizeSlaActionRecommendationAdjustment({
    ...(existingProposal || {}),
    ...baseProposal,
    proposedAt: existingProposal?.proposedAt || baseProposal.proposedAt,
    proposedBy: existingProposal?.proposedBy || baseProposal.proposedBy
  });
  const policyDecision = evaluateSlaRecommendationAutoApproval(proposal, existingItems, activePolicy);
  const finalProposal = normalizeSlaActionRecommendationAdjustment(policyDecision.eligible
    ? {
        ...proposal,
        status: "approved",
        activePriority: proposal.proposedPriority,
        approvalMode: "auto",
        autoApprovalPolicy: policyDecision,
        rollbackAvailable: true,
        reviewedAt: policyDecision.evaluatedAt,
        reviewedBy: "system_auto",
        reviewReason: policyDecision.reasons.join(" "),
        approvedAt: policyDecision.evaluatedAt,
        updatedAt: policyDecision.evaluatedAt,
        updatedBy: "system_auto"
      }
    : {
        ...proposal,
        status: "proposed",
        approvalMode: "none",
        autoApprovalPolicy: policyDecision,
        rollbackAvailable: false,
        updatedAt: policyDecision.evaluatedAt,
        updatedBy: "system"
      });
  byId.set(finalProposal.adjustmentId, finalProposal);
  await writeSlaActionRecommendationAdjustments({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  if (finalProposal.status === "approved" && finalProposal.approvalMode === "auto" && existingProposal?.status !== "approved") {
    await appendSlaActionRecommendationAutoApprovalLog({
      adjustmentId: finalProposal.adjustmentId,
      sourceKey: finalProposal.sourceKey,
      eventType: "auto_approved",
      eventAt: finalProposal.approvedAt || finalProposal.reviewedAt,
      eventBy: "system_auto",
      previousStatus: existingProposal?.status || "proposed",
      nextStatus: "approved",
      rollbackAvailable: true,
      policyDecision,
      reason: finalProposal.reviewReason
    });
  }
  return finalProposal;
}

function applyApprovedSlaRecommendationAdjustment(action = {}, adjustment = null, calculated = {}) {
  const proposed = adjustment || null;
  if (!proposed || proposed.status !== "approved") {
    return {
      ...action,
      historyAdjustment: {
        ...calculated,
        workflowStatus: calculated.applied ? "proposed" : "none",
        activeApplied: false,
        proposedAdjustmentId: proposed?.adjustmentId || ""
      }
    };
  }
  const recommendation = [
    action.recommendation || "",
    `Approved history adjustment: ${proposed.reason || calculated.recommendationNote || ""}`
  ].filter(Boolean).join(" ");
  return normalizeCalibrationSlaAction({
    ...action,
    priority: proposed.activePriority || proposed.proposedPriority || action.priority,
    recommendation,
    historyAdjustment: {
      ...calculated,
      workflowStatus: "approved",
      activeApplied: true,
      adjustmentId: proposed.adjustmentId,
      approvedAt: proposed.approvedAt || proposed.reviewedAt || "",
      approvedBy: proposed.reviewedBy || ""
    }
  });
}

async function applyCalibrationSlaHistoryAdjustment(action = {}, historyItems = [], adjustmentItems = []) {
  const adjustment = calibrationSlaActionHistoryAdjustment(action, historyItems);
  if (!adjustment.applied) {
    return {
      ...action,
      historyAdjustment: {
        ...adjustment,
        workflowStatus: "none",
        activeApplied: false
      }
    };
  }
  const active = activeSlaRecommendationAdjustmentForAction(action, adjustmentItems);
  const proposed = active || await upsertSlaActionRecommendationAdjustmentProposal(action, adjustment);
  const activeAdjustment = active || (proposed?.status === "approved" ? proposed : null);
  const result = applyApprovedSlaRecommendationAdjustment(action, activeAdjustment, adjustment);
  if (result.historyAdjustment && !result.historyAdjustment.activeApplied) {
    result.historyAdjustment = {
      ...result.historyAdjustment,
      workflowStatus: proposed?.status || "proposed",
      proposedAdjustmentId: proposed?.adjustmentId || "",
      proposedPriority: adjustment.adjustedPriority
    };
  }
  return result;
}

function filterCalibrationSlaActionReassessmentItems(items = [], payload = {}) {
  const owner = String(payload.owner || "").trim().toLowerCase();
  const outcome = String(payload.outcome || "").trim().toLowerCase();
  const followUp = String(payload.followUp || "").trim().toLowerCase();
  const risk = normalizeCalibrationSlaActionRisk(payload.risk || "");
  const month = String(payload.month || "").trim();
  return items
    .filter((item) => !owner || String(item.assignee || item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !outcome || item.reassessment?.evaluationState === outcome)
    .filter((item) => followUp === "needed" ? item.reassessment?.followUpNeeded : followUp === "none" ? !item.reassessment?.followUpNeeded : true)
    .filter((item) => !risk || item.riskLevel === risk)
    .filter((item) => !month || item.month === month || item.sourceType === "summary");
}

async function learningCalibrationSlaActionReassessmentReport(payload = {}) {
  const month = String(payload.month || "").trim();
  const quality = await learningCalibrationAuditOperationQualityReport({ month });
  const data = await readLearningCalibrationAuditReviewLogs();
  const logs = data.items || [];
  const allItems = (await calibrationSlaActionsForQuality(quality))
    .map(enrichCalibrationSlaActionQueueItem)
    .filter((item) => item.status === "done" && item.completionQualitySnapshot)
    .map((item) => reassessCalibrationSlaAction(item, logs));
  const shouldPersist = String(payload.persist ?? "true").trim().toLowerCase() !== "false";
  const historyWrite = shouldPersist
    ? await upsertSlaActionReassessmentHistoryItems(allItems, { recordedBy: payload.recordedBy || "system" })
    : null;
  const filtered = filterCalibrationSlaActionReassessmentItems(allItems, payload);
  const sorted = [...filtered].sort((a, b) => {
    return Number(b.reassessment?.followUpNeeded || 0) - Number(a.reassessment?.followUpNeeded || 0) ||
      (a.reassessment?.effectScore || 0) - (b.reassessment?.effectScore || 0) ||
      String(b.completedAt || b.updatedAt || "").localeCompare(String(a.completedAt || a.updatedAt || ""));
  });
  const limit = Math.max(1, Math.min(200, Number(payload.limit || 80)));
  return {
    role: "admin",
    reportType: "learning_calibration_sla_action_reassessment",
    generatedAt: new Date().toISOString(),
    filters: {
      owner: String(payload.owner || "").trim(),
      outcome: String(payload.outcome || "").trim(),
      followUp: String(payload.followUp || "").trim(),
      risk: normalizeCalibrationSlaActionRisk(payload.risk || ""),
      month,
      limit
    },
    summary: calibrationSlaActionReassessmentSummary(filtered),
    fullSummary: calibrationSlaActionReassessmentSummary(allItems),
    historyWrite: historyWrite?.slaActionReassessmentHistory || null,
    items: sorted.slice(0, limit),
    reportBoundaries: {
      source: "admin-only completed SLA action reassessment records",
      hiddenFromBusiness: ["SLA action reassessment", "completion snapshots", "effect score", "recurrence flag", "follow-up action candidates"]
    }
  };
}

async function slaActionReassessmentHistoryReport(payload = {}) {
  const data = await readSlaActionReassessmentHistory();
  const allItems = (data.items || []).map(normalizeSlaActionReassessmentHistoryItem);
  const filtered = filterSlaActionReassessmentHistoryItems(allItems, payload);
  const sorted = [...filtered].sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")));
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_action_reassessment_history",
    generatedAt: new Date().toISOString(),
    filters: {
      owner: String(payload.owner || "").trim(),
      month: String(payload.month || "").trim(),
      issueKey: String(payload.issueKey || payload.rootMetric || "").trim(),
      outcome: String(payload.outcome || "").trim(),
      followUp: String(payload.followUp || "").trim(),
      limit
    },
    summary: slaActionReassessmentHistorySummary(filtered),
    fullSummary: slaActionReassessmentHistorySummary(allItems),
    aggregates: slaActionReassessmentHistoryAggregates(filtered),
    items: sorted.slice(0, limit),
    reportBoundaries: {
      source: "admin-only persisted SLA action reassessment history",
      hiddenFromBusiness: ["SLA reassessment history", "effect score history", "recurrence history", "follow-up creation history", "operational owner scoring"]
    }
  };
}

function filterSlaActionRecommendationAdjustments(items = [], payload = {}) {
  const status = normalizeSlaActionRecommendationAdjustmentStatus(payload.status || "");
  const owner = String(payload.owner || "").trim().toLowerCase();
  const issueKey = String(payload.issueKey || "").trim();
  const direction = String(payload.direction || "").trim().toLowerCase();
  return items
    .filter((item) => !payload.status || item.status === status)
    .filter((item) => !owner || String(item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !issueKey || item.issueKey === issueKey || item.rootMetric.includes(issueKey))
    .filter((item) => !direction || item.direction === direction);
}

function slaActionRecommendationAdjustmentSummary(items = []) {
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    autoApproved: items.filter((item) => item.status === "approved" && item.approvalMode === "auto").length,
    manualRequired: items.filter((item) => item.status === "proposed").length,
    rollbackAvailable: items.filter((item) => item.rollbackAvailable && item.status === "approved").length,
    boost: items.filter((item) => item.direction === "boost").length,
    downgrade: items.filter((item) => item.direction === "downgrade").length,
    averageEffectScore: items.length
      ? Math.round(items.reduce((sum, item) => sum + Number(item.historyEffectScore || 0), 0) / items.length)
      : 0
  };
}

async function slaActionRecommendationAdjustmentsReport(payload = {}) {
  const [data, logData, policyAdjustmentData] = await Promise.all([
    readSlaActionRecommendationAdjustments(),
    readSlaActionRecommendationAutoApprovalLogs(),
    readSlaAutoApprovalPolicyAdjustments()
  ]);
  const activePolicy = activeSlaAutoApprovalPolicy(policyAdjustmentData.items || []);
  const allItems = (data.items || []).map(normalizeSlaActionRecommendationAdjustment);
  const autoApprovalLogs = (logData.items || []).map(normalizeSlaActionRecommendationAutoApprovalLog);
  const filtered = filterSlaActionRecommendationAdjustments(allItems, payload);
  const sorted = [...filtered].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, rejected: 2 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
  });
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const filteredIds = new Set(filtered.map((item) => item.adjustmentId));
  return {
    role: "admin",
    reportType: "sla_action_recommendation_adjustments",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      owner: String(payload.owner || "").trim(),
      issueKey: String(payload.issueKey || "").trim(),
      direction: String(payload.direction || "").trim(),
      limit
    },
    summary: slaActionRecommendationAdjustmentSummary(filtered),
    fullSummary: slaActionRecommendationAdjustmentSummary(allItems),
    autoApprovalPolicy: activePolicy,
    autoApprovalLogs: autoApprovalLogs
      .filter((log) => !filteredIds.size || filteredIds.has(log.adjustmentId))
      .slice(0, 80),
    items: sorted.slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA action recommendation adjustment proposals and review history",
      hiddenFromBusiness: ["recommendation adjustment proposals", "approval history", "priority calibration evidence", "history effect scores"]
    }
  };
}

async function rollbackSlaActionRecommendationAutoApproval(payload = {}) {
  const adjustmentId = String(payload.adjustmentId || "").trim();
  if (!adjustmentId) {
    const error = new Error("Adjustment id is required for rollback.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaActionRecommendationAdjustments();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaActionRecommendationAdjustment) : [];
  const target = items.find((item) => item.adjustmentId === adjustmentId);
  if (!target) {
    const error = new Error("SLA recommendation adjustment proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  if (target.status !== "approved" || target.approvalMode !== "auto" || !target.rollbackAvailable) {
    const error = new Error("Only rollback-available auto-approved adjustments can be rolled back.");
    error.statusCode = 400;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reason = String(payload.rollbackReason || payload.reason || "").trim();
  const rolledBack = normalizeSlaActionRecommendationAdjustment({
    ...target,
    status: "rejected",
    activePriority: "",
    approvalMode: "auto",
    rollbackAvailable: false,
    rolledBackAt: now,
    rolledBackBy: reviewer,
    rollbackReason: reason,
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason: reason ? `Auto approval rolled back: ${reason}` : "Auto approval rolled back.",
    rejectedAt: now,
    updatedAt: now,
    updatedBy: reviewer
  });
  const updated = await writeSlaActionRecommendationAdjustments({
    ...data,
    items: items.map((item) => item.adjustmentId === adjustmentId ? rolledBack : item)
      .sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  await appendSlaActionRecommendationAutoApprovalLog({
    adjustmentId,
    sourceKey: target.sourceKey,
    eventType: "rollback",
    eventAt: now,
    eventBy: reviewer,
    previousStatus: "approved",
    nextStatus: "rejected",
    rollbackAvailable: false,
    rolledBack: true,
    policyDecision: target.autoApprovalPolicy || {},
    reason: rolledBack.reviewReason
  });
  return {
    role: "admin",
    reportType: "sla_action_recommendation_adjustment_rollback",
    generatedAt: now,
    adjustment: rolledBack,
    slaActionRecommendationAdjustments: {
      schema: updated.schema || "sla_action_recommendation_adjustments_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    reportBoundaries: {
      source: "admin-only rollback of auto-approved SLA recommendation adjustment",
      hiddenFromBusiness: ["auto approval rollback", "policy decision", "review reason", "priority calibration evidence"]
    }
  };
}

function slaAutoApprovalLinkedHistory(adjustment = {}, historyItems = []) {
  const approvedAt = adjustment.approvedAt || adjustment.reviewedAt || adjustment.updatedAt || "";
  const approvedTime = new Date(approvedAt).getTime();
  const owner = String(adjustment.owner || "").trim().toLowerCase();
  const issueKey = String(adjustment.issueKey || "").trim();
  return historyItems
    .map(normalizeSlaActionReassessmentHistoryItem)
    .filter((item) => {
      const evaluatedTime = new Date(item.evaluatedAt || item.recordedAt || "").getTime();
      const afterApproval = !Number.isFinite(approvedTime) || !Number.isFinite(evaluatedTime) || evaluatedTime >= approvedTime;
      const sameSource = item.sourceKey && item.sourceKey === adjustment.sourceKey;
      const sameIssue = issueKey && item.issueKey === issueKey;
      const sameOwner = !owner || String(item.assignee || item.owner || "").toLowerCase() === owner;
      return afterApproval && (sameSource || (sameIssue && sameOwner));
    })
    .sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")));
}

function slaAutoApprovalPerformanceOutcome(adjustment = {}, linkedHistory = [], logs = []) {
  const rolledBack = Boolean(adjustment.rolledBackAt || logs.some((log) => log.adjustmentId === adjustment.adjustmentId && log.eventType === "rollback"));
  const evaluatedCount = linkedHistory.length;
  const avgEffectScore = evaluatedCount ? Math.round(linkedHistory.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / evaluatedCount) : 0;
  const improved = linkedHistory.filter((item) => item.evaluationState === "improved").length;
  const worse = linkedHistory.filter((item) => item.evaluationState === "worse").length;
  const recurrence = linkedHistory.filter((item) => item.recurrence).length;
  const followUpNeeded = linkedHistory.filter((item) => item.followUpNeeded).length;
  const improvedRate = evaluatedCount ? Math.round((improved / evaluatedCount) * 100) : 0;
  const worseRate = evaluatedCount ? Math.round((worse / evaluatedCount) * 100) : 0;
  const recurrenceRate = evaluatedCount ? Math.round((recurrence / evaluatedCount) * 100) : 0;
  const followUpNeededRate = evaluatedCount ? Math.round((followUpNeeded / evaluatedCount) * 100) : 0;
  const falsePositive = evaluatedCount > 0 && (worseRate >= 50 || recurrenceRate >= 50 || avgEffectScore < 45 || followUpNeededRate >= 50);
  const successful = evaluatedCount > 0 && !falsePositive && avgEffectScore >= 60 && improvedRate >= 50 && recurrenceRate < 50;
  let outcome = "pending";
  if (rolledBack) outcome = "rolled_back";
  else if (falsePositive) outcome = "false_positive";
  else if (successful) outcome = "successful";
  else if (evaluatedCount > 0) outcome = "mixed";
  return {
    outcome,
    evaluatedCount,
    avgEffectScore,
    improved,
    improvedRate,
    worse,
    worseRate,
    recurrence,
    recurrenceRate,
    followUpNeeded,
    followUpNeededRate,
    falsePositive,
    successful,
    rolledBack
  };
}

function slaAutoApprovalPerformanceItem(adjustment = {}, historyItems = [], autoApprovalLogs = []) {
  const logs = autoApprovalLogs.filter((log) => log.adjustmentId === adjustment.adjustmentId);
  const linkedHistory = slaAutoApprovalLinkedHistory(adjustment, historyItems);
  const outcome = slaAutoApprovalPerformanceOutcome(adjustment, linkedHistory, logs);
  return {
    adjustmentId: adjustment.adjustmentId,
    sourceKey: adjustment.sourceKey,
    sourceType: adjustment.sourceType,
    sourceLabel: adjustment.sourceLabel,
    approvalMonth: monthKey(adjustment.approvedAt || adjustment.reviewedAt || adjustment.updatedAt || adjustment.proposedAt),
    approvedAt: adjustment.approvedAt || adjustment.reviewedAt || "",
    owner: adjustment.owner || "",
    issueKey: adjustment.issueKey || "",
    rootMetric: adjustment.rootMetric || "",
    direction: adjustment.direction || "",
    originalPriority: adjustment.originalPriority || "",
    proposedPriority: adjustment.proposedPriority || "",
    activePriority: adjustment.activePriority || "",
    policyRiskLevel: adjustment.autoApprovalPolicy?.riskLevel || "",
    policyVersion: adjustment.autoApprovalPolicy?.policyVersion || "",
    rollbackAvailable: Boolean(adjustment.rollbackAvailable),
    rolledBackAt: adjustment.rolledBackAt || "",
    rolledBackBy: adjustment.rolledBackBy || "",
    outcome,
    linkedHistory: linkedHistory.slice(0, 6).map((item) => ({
      historyId: item.historyId,
      evaluatedAt: item.evaluatedAt,
      evaluatedMonth: item.evaluatedMonth,
      effectScore: item.effectScore,
      evaluationState: item.evaluationState,
      recurrence: item.recurrence,
      followUpNeeded: item.followUpNeeded
    })),
    logCount: logs.length
  };
}

function emptySlaAutoApprovalPerformanceAggregate(key = "", label = "") {
  return {
    key,
    label: label || key || "unknown",
    total: 0,
    evaluated: 0,
    successful: 0,
    mixed: 0,
    falsePositive: 0,
    pending: 0,
    rolledBack: 0,
    recurrence: 0,
    effectScoreTotal: 0
  };
}

function finalizeSlaAutoApprovalPerformanceAggregate(row = {}) {
  const evaluated = row.evaluated || 0;
  return {
    ...row,
    successRate: evaluated ? Math.round((row.successful / evaluated) * 100) : 0,
    rollbackRate: row.total ? Math.round((row.rolledBack / row.total) * 100) : 0,
    recurrenceRate: evaluated ? Math.round((row.recurrence / evaluated) * 100) : 0,
    falsePositiveRate: evaluated ? Math.round((row.falsePositive / evaluated) * 100) : 0,
    avgEffectScore: evaluated ? Math.round(row.effectScoreTotal / evaluated) : 0
  };
}

function slaAutoApprovalPerformanceGroups(items = [], keyFn = () => "", labelFn = (key) => key) {
  const map = new Map();
  items.forEach((item) => {
    const key = String(keyFn(item) || "unknown");
    const row = map.get(key) || emptySlaAutoApprovalPerformanceAggregate(key, labelFn(key, item));
    const outcome = item.outcome || {};
    row.total += 1;
    if (outcome.evaluatedCount > 0) {
      row.evaluated += 1;
      row.effectScoreTotal += Number(outcome.avgEffectScore || 0);
    }
    if (outcome.successful) row.successful += 1;
    if (outcome.outcome === "mixed") row.mixed += 1;
    if (outcome.falsePositive) row.falsePositive += 1;
    if (outcome.outcome === "pending") row.pending += 1;
    if (outcome.rolledBack) row.rolledBack += 1;
    if (outcome.recurrence > 0) row.recurrence += 1;
    map.set(key, row);
  });
  return [...map.values()]
    .map(finalizeSlaAutoApprovalPerformanceAggregate)
    .sort((a, b) => b.total - a.total || a.falsePositiveRate - b.falsePositiveRate || String(a.label).localeCompare(String(b.label)));
}

function slaAutoApprovalPerformanceSummary(items = []) {
  return finalizeSlaAutoApprovalPerformanceAggregate(items.reduce((row, item) => {
    const outcome = item.outcome || {};
    row.total += 1;
    if (outcome.evaluatedCount > 0) {
      row.evaluated += 1;
      row.effectScoreTotal += Number(outcome.avgEffectScore || 0);
    }
    if (outcome.successful) row.successful += 1;
    if (outcome.outcome === "mixed") row.mixed += 1;
    if (outcome.falsePositive) row.falsePositive += 1;
    if (outcome.outcome === "pending") row.pending += 1;
    if (outcome.rolledBack) row.rolledBack += 1;
    if (outcome.recurrence > 0) row.recurrence += 1;
    return row;
  }, emptySlaAutoApprovalPerformanceAggregate("all", "All auto approvals")));
}

function slaAutoApprovalPolicyAdjustmentCandidates(items = [], aggregates = {}) {
  const candidates = [];
  const riskyIssues = (aggregates.byIssue || []).filter((row) => row.evaluated >= 1 && (row.falsePositiveRate >= 40 || row.recurrenceRate >= 50 || row.rollbackRate >= 30));
  riskyIssues.slice(0, 6).forEach((row) => {
    candidates.push({
      type: "tighten_issue_policy",
      priority: row.falsePositiveRate >= 50 || row.rollbackRate >= 40 ? "high" : "medium",
      target: row.label,
      issueKey: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `False positive ${row.falsePositiveRate}%, recurrence ${row.recurrenceRate}%, rollback ${row.rollbackRate}% across ${row.evaluated} evaluated auto approvals.`,
      recommendation: "Keep this issue in manual review or raise the sample/effect threshold before auto approval."
    });
  });
  const strongIssues = (aggregates.byIssue || []).filter((row) => row.evaluated >= 3 && row.successRate >= 80 && row.falsePositiveRate === 0 && row.rollbackRate === 0);
  strongIssues.slice(0, 4).forEach((row) => {
    candidates.push({
      type: "consider_relaxing_issue_policy",
      priority: "low",
      target: row.label,
      issueKey: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `Success ${row.successRate}% with no false positives or rollbacks across ${row.evaluated} evaluated auto approvals.`,
      recommendation: "Consider allowing the same issue to remain auto-approved, while keeping broad summary scopes manual."
    });
  });
  const pendingRate = items.length ? Math.round((items.filter((item) => item.outcome?.outcome === "pending").length / items.length) * 100) : 0;
  if (pendingRate >= 60 && items.length >= 3) {
    candidates.push({
      type: "increase_monitoring_window",
      priority: "medium",
      target: "pending_auto_approval_followup",
      issueKey: "pending_auto_approval_followup",
      metrics: {
        total: items.length,
        evaluated: items.filter((item) => item.outcome?.evaluatedCount > 0).length,
        successRate: slaAutoApprovalPerformanceSummary(items).successRate,
        falsePositiveRate: slaAutoApprovalPerformanceSummary(items).falsePositiveRate,
        rollbackRate: slaAutoApprovalPerformanceSummary(items).rollbackRate,
        recurrenceRate: slaAutoApprovalPerformanceSummary(items).recurrenceRate,
        pendingRate
      },
      basis: `${pendingRate}% of auto approvals do not yet have linked reassessment history.`,
      recommendation: "Require completion/reassessment capture before widening auto approval coverage."
    });
  }
  return candidates;
}

function buildSlaAutoApprovalPolicyAdjustmentProposal(candidate = {}, policy = SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY, existing = null) {
  const candidateType = String(candidate.candidateType || candidate.type || "policy_adjustment").trim();
  const target = String(candidate.target || candidate.issueKey || "").trim();
  const policyPatch = candidate.policyPatch && typeof candidate.policyPatch === "object"
    ? candidate.policyPatch
    : slaAutoApprovalPolicyPatchFromCandidate({ ...candidate, candidateType, target }, policy);
  const beforePolicy = slaAutoApprovalPolicySnapshot(policy, { ...candidate, candidateType, target });
  const afterPolicy = slaAutoApprovalPolicySnapshot(applySlaAutoApprovalPolicyPatch(policy, policyPatch), { ...candidate, candidateType, target });
  return normalizeSlaAutoApprovalPolicyAdjustment({
    ...(existing || {}),
    ...candidate,
    candidateType,
    target,
    issueKey: candidate.issueKey || target,
    policyPatch,
    beforePolicy,
    afterPolicy,
    expectedImpact: candidate.expectedImpact && typeof candidate.expectedImpact === "object"
      ? candidate.expectedImpact
      : slaAutoApprovalExpectedImpact({ ...candidate, candidateType, target }),
    status: existing?.status || "proposed",
    proposedAt: existing?.proposedAt || new Date().toISOString(),
    proposedBy: existing?.proposedBy || "system",
    updatedAt: existing?.updatedAt || new Date().toISOString(),
    updatedBy: existing?.updatedBy || "system"
  });
}

async function upsertSlaAutoApprovalPolicyAdjustmentProposals(candidates = [], activePolicy = SLA_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const data = await readSlaAutoApprovalPolicyAdjustments();
  const existingItems = Array.isArray(data.items) ? data.items.map(normalizeSlaAutoApprovalPolicyAdjustment) : [];
  const byId = new Map(existingItems.map((item) => [item.policyAdjustmentId, item]));
  const proposals = [];
  candidates.forEach((candidate) => {
    const candidateId = String(candidate.policyAdjustmentId || slaAutoApprovalPolicyAdjustmentId(candidate)).trim();
    const existing = byId.get(candidateId) || null;
    if (existing && ["approved", "rejected"].includes(existing.status)) {
      proposals.push(normalizeSlaAutoApprovalPolicyAdjustment({
        ...existing,
        duplicateStatus: `existing_${existing.status}`,
        duplicateOfPolicyAdjustmentId: existing.policyAdjustmentId
      }));
      return;
    }
    const proposal = normalizeSlaAutoApprovalPolicyAdjustment({
      ...buildSlaAutoApprovalPolicyAdjustmentProposal(candidate, activePolicy, existing),
      duplicateStatus: existing ? "existing_proposed" : "created",
      duplicateOfPolicyAdjustmentId: existing?.policyAdjustmentId || ""
    });
    byId.set(proposal.policyAdjustmentId, proposal);
    proposals.push(proposal);
  });
  const sorted = [...byId.values()].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, rejected: 2 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
  });
  await writeSlaAutoApprovalPolicyAdjustments({
    ...data,
    items: sorted
  });
  return proposals;
}

function filterSlaAutoApprovalPolicyAdjustments(items = [], payload = {}) {
  const status = normalizeSlaAutoApprovalPolicyAdjustmentStatus(payload.status || "");
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  return items
    .filter((item) => !payload.status || item.status === status)
    .filter((item) => !target || String(item.target || item.issueKey || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type);
}

function slaAutoApprovalPolicyAdjustmentSummary(items = []) {
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    high: items.filter((item) => item.priority === "high").length,
    medium: items.filter((item) => item.priority === "medium").length,
    low: items.filter((item) => item.priority === "low").length,
    expectedSuccessRateChangeAvg: items.length
      ? Math.round(items.reduce((sum, item) => sum + Number(item.expectedImpact?.expectedSuccessRateChange || 0), 0) / items.length)
      : 0
  };
}

async function slaAutoApprovalPolicyAdjustmentsReport(payload = {}) {
  const data = await readSlaAutoApprovalPolicyAdjustments();
  const allItems = (data.items || []).map(normalizeSlaAutoApprovalPolicyAdjustment);
  const activePolicy = activeSlaAutoApprovalPolicy(allItems);
  const filtered = filterSlaAutoApprovalPolicyAdjustments(allItems, payload);
  const sorted = [...filtered].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, rejected: 2 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.reviewedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.reviewedAt || a.proposedAt || ""));
  });
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_auto_approval_policy_adjustments",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      target: String(payload.target || payload.issueKey || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      limit
    },
    summary: slaAutoApprovalPolicyAdjustmentSummary(filtered),
    fullSummary: slaAutoApprovalPolicyAdjustmentSummary(allItems),
    activePolicy,
    items: sorted.slice(0, limit),
    approvalHistory: allItems
      .filter((item) => ["approved", "rejected"].includes(item.status))
      .sort((a, b) => String(b.reviewedAt || b.updatedAt || "").localeCompare(String(a.reviewedAt || a.updatedAt || "")))
      .slice(0, 80),
    reportBoundaries: {
      source: "admin-only SLA auto approval policy adjustment workflow",
      hiddenFromBusiness: ["auto approval policy thresholds", "policy adjustment proposals", "approval history", "expected policy impact"]
    }
  };
}

function slaPolicyEffectTimestamp(item = {}) {
  return item.approvedAt || item.reviewedAt || item.updatedAt || item.proposedAt || "";
}

function slaPolicyEffectTime(value = "") {
  const time = new Date(value).getTime();
  return Number.isFinite(time) ? time : null;
}

function slaPolicyEffectWindowContains(value = "", startTime = null, endTime = null) {
  const time = slaPolicyEffectTime(value);
  if (!Number.isFinite(time)) return false;
  if (Number.isFinite(startTime) && time < startTime) return false;
  if (Number.isFinite(endTime) && time >= endTime) return false;
  return true;
}

function slaPolicyEffectScopeMatcher(policyAdjustment = {}) {
  const target = String(policyAdjustment.issueKey || policyAdjustment.target || "").trim();
  const globalScope = !target ||
    policyAdjustment.candidateType === "increase_monitoring_window" ||
    target === "pending_auto_approval_followup";
  return (item = {}) => {
    if (globalScope) return true;
    const issueKey = String(item.issueKey || "").trim();
    const rootMetric = String(item.rootMetric || "").trim();
    return issueKey === target || rootMetric === target;
  };
}

function slaPolicyEffectProposalBucket(items = []) {
  const total = items.length;
  const autoApproved = items.filter((item) => item.status === "approved" && item.approvalMode === "auto").length;
  const manualReview = total - autoApproved;
  return {
    totalProposals: total,
    autoApproved,
    manualReview,
    proposed: items.filter((item) => item.status === "proposed").length,
    manualApproved: items.filter((item) => item.status === "approved" && item.approvalMode !== "auto").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    manualReviewConversionRate: total ? Math.round((manualReview / total) * 100) : 0
  };
}

function slaPolicyEffectMetrics(performanceItems = [], proposalItems = []) {
  const autoSummary = slaAutoApprovalPerformanceSummary(performanceItems);
  const proposalSummary = slaPolicyEffectProposalBucket(proposalItems);
  return {
    ...proposalSummary,
    autoApprovals: autoSummary.total || 0,
    evaluatedAutoApprovals: autoSummary.evaluated || 0,
    successRate: autoSummary.successRate || 0,
    falsePositiveRate: autoSummary.falsePositiveRate || 0,
    rollbackRate: autoSummary.rollbackRate || 0,
    recurrenceRate: autoSummary.recurrenceRate || 0,
    avgEffectScore: autoSummary.avgEffectScore || 0,
    pendingRate: autoSummary.total ? Math.round(((autoSummary.pending || 0) / autoSummary.total) * 100) : 0
  };
}

function slaPolicyEffectWindowedPerformanceItem(item = {}, startTime = null, endTime = null) {
  const linkedHistory = (item.linkedHistory || [])
    .filter((history) => slaPolicyEffectWindowContains(history.evaluatedAt || history.evaluatedMonth || "", startTime, endTime));
  const outcome = slaAutoApprovalPerformanceOutcome(
    {
      adjustmentId: item.adjustmentId,
      rolledBackAt: item.rolledBackAt || ""
    },
    linkedHistory,
    []
  );
  return {
    ...item,
    outcome,
    linkedHistory
  };
}

function slaPolicyEffectMetricDelta(before = {}, after = {}) {
  return {
    totalProposals: Number(after.totalProposals || 0) - Number(before.totalProposals || 0),
    autoApprovals: Number(after.autoApprovals || 0) - Number(before.autoApprovals || 0),
    evaluatedAutoApprovals: Number(after.evaluatedAutoApprovals || 0) - Number(before.evaluatedAutoApprovals || 0),
    successRate: Number(after.successRate || 0) - Number(before.successRate || 0),
    falsePositiveRate: Number(after.falsePositiveRate || 0) - Number(before.falsePositiveRate || 0),
    rollbackRate: Number(after.rollbackRate || 0) - Number(before.rollbackRate || 0),
    recurrenceRate: Number(after.recurrenceRate || 0) - Number(before.recurrenceRate || 0),
    manualReviewConversionRate: Number(after.manualReviewConversionRate || 0) - Number(before.manualReviewConversionRate || 0),
    avgEffectScore: Number(after.avgEffectScore || 0) - Number(before.avgEffectScore || 0)
  };
}

function slaPolicyEffectIsTighteningType(candidateType = "") {
  return [
    "tighten_issue_policy",
    "additional_tightening_policy",
    "tighten_rereview_action_auto_policy",
    "additional_rereview_tightening",
    "tighten_effect_quality_action_auto_policy",
    "additional_effect_quality_tightening"
  ].includes(String(candidateType || "").trim());
}

function slaPolicyEffectScore(policyAdjustment = {}, before = {}, after = {}, delta = {}) {
  const hasAfterEvidence = Number(after.totalProposals || 0) > 0 || Number(after.autoApprovals || 0) > 0 || Number(after.evaluatedAutoApprovals || 0) > 0;
  if (!hasAfterEvidence) return null;
  const tightenWeight = slaPolicyEffectIsTighteningType(policyAdjustment.candidateType) ? 0.12 : -0.08;
  const raw = 50 +
    Number(delta.successRate || 0) * 0.35 -
    Number(delta.falsePositiveRate || 0) * 0.3 -
    Number(delta.rollbackRate || 0) * 0.25 -
    Number(delta.recurrenceRate || 0) * 0.25 +
    Number(delta.manualReviewConversionRate || 0) * tightenWeight +
    Number(delta.avgEffectScore || 0) * 0.2;
  return safeScore(raw);
}

function slaPolicyEffectOutcome(effectScore = null, before = {}, after = {}) {
  const hasAfterEvidence = Number(after.totalProposals || 0) > 0 || Number(after.autoApprovals || 0) > 0 || Number(after.evaluatedAutoApprovals || 0) > 0;
  if (!hasAfterEvidence) return "pending";
  if (effectScore === null || effectScore === undefined) return "pending";
  if (effectScore >= 65) return "improved";
  if (effectScore <= 40) return "worse";
  return "unchanged";
}

function slaPolicyEffectSuggestions(policyAdjustment = {}, before = {}, after = {}, delta = {}, outcome = "pending") {
  const suggestions = [];
  if (outcome === "pending") {
    suggestions.push({
      type: "collect_more_evidence",
      priority: "medium",
      label: "Collect more post-change evidence",
      reason: "There is not enough after-approval proposal or outcome data to judge this policy change."
    });
  }
  if (outcome === "worse" || Number(after.falsePositiveRate || 0) >= 50 || Number(after.rollbackRate || 0) >= 30) {
    suggestions.push({
      type: "rollback_policy_adjustment",
      priority: "high",
      label: "Review rollback of this policy adjustment",
      reason: `Post-change false positive ${after.falsePositiveRate || 0}%, rollback ${after.rollbackRate || 0}%, recurrence ${after.recurrenceRate || 0}%.`
    });
  }
  if (policyAdjustment.candidateType === "tighten_issue_policy" && Number(after.manualReviewConversionRate || 0) >= 80 && Number(after.falsePositiveRate || 0) <= Number(before.falsePositiveRate || 0)) {
    suggestions.push({
      type: "consider_partial_relaxation",
      priority: "medium",
      label: "Consider partial relaxation after stable manual review",
      reason: `Manual review conversion reached ${after.manualReviewConversionRate || 0}% while false positives did not worsen.`
    });
  }
  if (Number(after.recurrenceRate || 0) > Number(before.recurrenceRate || 0) && Number(after.recurrenceRate || 0) >= 40) {
    suggestions.push({
      type: "additional_tightening",
      priority: "high",
      label: "Add recurrence-focused tightening",
      reason: `Recurrence rose by ${delta.recurrenceRate || 0}p after this policy change.`
    });
  }
  if (!suggestions.length) {
    suggestions.push({
      type: "maintain_policy_adjustment",
      priority: "low",
      label: "Maintain and keep monitoring",
      reason: "Post-change metrics do not require rollback or additional tightening yet."
    });
  }
  return suggestions;
}

function slaPolicyEffectSuggestionCandidateType(suggestionType = "") {
  const type = String(suggestionType || "").trim();
  if (type === "rollback_policy_adjustment") return "rollback_policy_adjustment";
  if (type === "consider_partial_relaxation") return "partial_relaxation_policy";
  if (type === "additional_tightening") return "additional_tightening_policy";
  return "";
}

function slaPolicyEffectGeneratedCandidateId(effectItem = {}, suggestion = {}) {
  return hashId("saapae", [
    effectItem.policyAdjustmentId || "",
    suggestion.type || "",
    effectItem.issueKey || effectItem.target || ""
  ].join("|"));
}

function slaPolicyEffectCandidateMetrics(effectItem = {}) {
  return {
    beforeSuccessRate: Number(effectItem.before?.successRate || 0),
    afterSuccessRate: Number(effectItem.after?.successRate || 0),
    successRate: Number(effectItem.after?.successRate || 0),
    beforeFalsePositiveRate: Number(effectItem.before?.falsePositiveRate || 0),
    afterFalsePositiveRate: Number(effectItem.after?.falsePositiveRate || 0),
    falsePositiveRate: Number(effectItem.after?.falsePositiveRate || 0),
    beforeRollbackRate: Number(effectItem.before?.rollbackRate || 0),
    afterRollbackRate: Number(effectItem.after?.rollbackRate || 0),
    rollbackRate: Number(effectItem.after?.rollbackRate || 0),
    beforeRecurrenceRate: Number(effectItem.before?.recurrenceRate || 0),
    afterRecurrenceRate: Number(effectItem.after?.recurrenceRate || 0),
    recurrenceRate: Number(effectItem.after?.recurrenceRate || 0),
    beforeManualReviewConversionRate: Number(effectItem.before?.manualReviewConversionRate || 0),
    afterManualReviewConversionRate: Number(effectItem.after?.manualReviewConversionRate || 0),
    manualReviewConversionRate: Number(effectItem.after?.manualReviewConversionRate || 0),
    effectScore: Number(effectItem.effectScore || 0),
    evaluated: Number(effectItem.after?.evaluatedAutoApprovals || 0),
    total: Number(effectItem.after?.totalProposals || 0)
  };
}

function slaPolicyEffectCandidateExpectedImpact(effectItem = {}, suggestion = {}, candidateType = "") {
  const metrics = slaPolicyEffectCandidateMetrics(effectItem);
  let expectedSuccessRate = metrics.afterSuccessRate;
  if (candidateType === "rollback_policy_adjustment") {
    expectedSuccessRate = Math.max(metrics.beforeSuccessRate, metrics.afterSuccessRate);
  } else if (candidateType === "partial_relaxation_policy") {
    expectedSuccessRate = Math.max(0, metrics.afterSuccessRate - 5);
  } else if (candidateType === "additional_tightening_policy") {
    expectedSuccessRate = Math.min(100, metrics.afterSuccessRate + 10);
  }
  return {
    scope: effectItem.candidateType === "increase_monitoring_window" ? "global_policy" : "issue_policy",
    affectedTarget: effectItem.target || effectItem.issueKey || "",
    currentSuccessRate: metrics.afterSuccessRate,
    expectedSuccessRate,
    expectedSuccessRateChange: expectedSuccessRate - metrics.afterSuccessRate,
    currentFalsePositiveRate: metrics.afterFalsePositiveRate,
    currentRollbackRate: metrics.afterRollbackRate,
    currentRecurrenceRate: metrics.afterRecurrenceRate,
    evaluated: metrics.evaluated,
    total: metrics.total,
    basis: suggestion.reason || ""
  };
}

function slaPolicyCandidateQualityCalibrationBasis(qualityReport = {}, candidateType = "") {
  const row = (qualityReport.byType || []).find((item) => item.candidateType === candidateType) || {};
  const total = Number(row.total || 0);
  const repeatRecommended = Number(row.repeatRecommended || 0);
  const topRejection = row.rejectionReasons?.[0] || null;
  return {
    candidateType,
    total,
    proposed: Number(row.proposed || 0),
    approved: Number(row.approved || 0),
    rejected: Number(row.rejected || 0),
    evaluated: Number(row.evaluated || 0),
    successful: Number(row.successful || 0),
    failed: Number(row.failed || 0),
    repeatRecommended,
    approvalRate: Number(row.approvalRate || 0),
    approvalSuccessRate: Number(row.approvalSuccessRate || 0),
    repeatRecommendationRate: total ? Math.round((repeatRecommended / total) * 100) : 0,
    topRejectionReason: topRejection?.reason || "",
    topRejectionCount: Number(topRejection?.count || 0),
    rejectionReasons: (row.rejectionReasons || []).slice(0, 3)
  };
}

function slaPolicyCandidateQualityCalibration(candidate = {}, qualityReport = {}) {
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  const priorityBefore = normalizeCalibrationSlaActionPriority(candidate.priority || "medium") || "medium";
  const previousQuality = slaPolicyCandidateQualityCalibrationBasis(qualityReport, candidateType);
  const hasHistory = previousQuality.total > 0;
  const reviewed = previousQuality.approved + previousQuality.rejected;
  const strongHistory = previousQuality.evaluated >= 1 &&
    previousQuality.approved >= 1 &&
    previousQuality.approvalSuccessRate >= 70 &&
    previousQuality.repeatRecommendationRate <= 30 &&
    previousQuality.rejected <= previousQuality.approved;
  const weakHistory = (previousQuality.evaluated >= 1 && previousQuality.approvalSuccessRate <= 40) ||
    (reviewed >= 2 && previousQuality.rejected > previousQuality.approved) ||
    (previousQuality.total >= 2 && previousQuality.repeatRecommendationRate >= 50) ||
    (previousQuality.rejected >= 2 && previousQuality.approved === 0);
  let direction = "neutral";
  if (weakHistory) direction = "downgrade";
  else if (strongHistory) direction = "boost";
  const priorityAfter = direction === "neutral"
    ? priorityBefore
    : shiftCalibrationSlaActionPriority(priorityBefore, direction);
  const reason = !hasHistory
    ? `No previous quality data exists for ${candidateType}; priority remains ${priorityBefore}.`
    : direction === "boost"
      ? `Previous ${candidateType} candidates show ${previousQuality.approvalSuccessRate}% approved-success across ${previousQuality.evaluated} evaluated items with ${previousQuality.repeatRecommendationRate}% repeat recommendation; priority ${priorityBefore} -> ${priorityAfter}.`
      : direction === "downgrade"
        ? `Previous ${candidateType} candidates show ${previousQuality.approvalSuccessRate}% approved-success, ${previousQuality.repeatRecommendationRate}% repeat recommendation, and ${previousQuality.rejected} rejections${previousQuality.topRejectionReason ? `; top rejection reason: ${previousQuality.topRejectionReason}` : ""}; priority ${priorityBefore} -> ${priorityAfter}.`
        : `Previous ${candidateType} quality is mixed or still too thin; priority remains ${priorityBefore}.`;
  return {
    applied: direction !== "neutral" && priorityAfter !== priorityBefore,
    direction,
    candidateType,
    priorityBefore,
    priorityAfter,
    reason,
    previousQuality
  };
}

function slaPolicyCandidateQualityCalibrationId(candidate = {}) {
  return hashId("spcqc", [
    candidate.policyAdjustmentId || "",
    candidate.candidateType || candidate.type || "",
    candidate.target || candidate.issueKey || ""
  ].join("|"));
}

function normalizeSlaPolicyCandidateQualityCalibrationStatus(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["proposed", "approved", "rejected", "overridden", "deactivated"].includes(text)) return text;
  return "proposed";
}

function slaPolicyCandidateQualityCalibrationActive(item = {}) {
  return ["approved", "overridden"].includes(item.status);
}

function slaPolicyCandidateQualityCalibrationEvent(input = {}) {
  return {
    eventId: String(input.eventId || hashId("spcqce", [
      input.calibrationId || "",
      input.eventType || input.decision || "",
      input.eventAt || new Date().toISOString(),
      input.eventBy || ""
    ].join("|"))).trim(),
    eventType: String(input.eventType || input.decision || "updated").trim(),
    eventAt: input.eventAt || new Date().toISOString(),
    eventBy: String(input.eventBy || input.reviewedBy || input.updatedBy || "system").trim() || "system",
    previousStatus: String(input.previousStatus || "").trim(),
    nextStatus: String(input.nextStatus || "").trim(),
    reason: String(input.reason || input.reviewReason || "").trim(),
    overridePriorityAfter: normalizeCalibrationSlaActionPriority(input.overridePriorityAfter || ""),
    overrideReason: String(input.overrideReason || "").trim()
  };
}

function slaPolicyCandidateQualityCalibrationSimulation(candidate = {}, suggested = {}, active = null) {
  const priorityBefore = normalizeCalibrationSlaActionPriority(candidate.priority || suggested.priorityBefore || "medium") || "medium";
  const suggestedPriorityAfter = normalizeCalibrationSlaActionPriority(suggested.priorityAfter || priorityBefore) || priorityBefore;
  const activePriorityAfter = active
    ? normalizeCalibrationSlaActionPriority(active.priorityAfter || suggestedPriorityAfter) || suggestedPriorityAfter
    : priorityBefore;
  const recommendationBefore = String(candidate.recommendation || "").trim();
  const suggestedRecommendationAfter = [recommendationBefore, `Quality calibration: ${suggested.reason || ""}`].filter(Boolean).join(" ");
  const activeRecommendationAfter = active
    ? [recommendationBefore, `Approved quality calibration: ${active.reason || suggested.reason || ""}`].filter(Boolean).join(" ")
    : recommendationBefore;
  return {
    priorityBefore,
    suggestedPriorityAfter,
    activePriorityAfter,
    recommendationBefore,
    suggestedRecommendationAfter,
    activeRecommendationAfter,
    expectedImpactBefore: candidate.expectedImpact || {},
    expectedImpactAfter: {
      ...(candidate.expectedImpact || {}),
      priorityBefore,
      suggestedPriorityAfter,
      activePriorityAfter,
      calibrationApplied: Boolean(active),
      calibrationBasis: active?.reason || suggested.reason || ""
    }
  };
}

function normalizeSlaPolicyCandidateQualityCalibration(input = {}) {
  const now = new Date().toISOString();
  const suggested = input.suggestedCalibration && typeof input.suggestedCalibration === "object"
    ? input.suggestedCalibration
    : input.qualityCalibration && typeof input.qualityCalibration === "object"
      ? input.qualityCalibration
      : {};
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(input.status || "proposed");
  const activeCalibration = input.activeCalibration && typeof input.activeCalibration === "object"
    ? input.activeCalibration
    : slaPolicyCandidateQualityCalibrationActive({ status })
      ? suggested
      : null;
  return {
    calibrationId: String(input.calibrationId || slaPolicyCandidateQualityCalibrationId(input)).trim(),
    policyAdjustmentId: String(input.policyAdjustmentId || "").trim(),
    candidateType: String(input.candidateType || input.type || suggested.candidateType || "").trim(),
    target: String(input.target || input.issueKey || "").trim(),
    issueKey: String(input.issueKey || input.target || "").trim(),
    sourcePolicyAdjustmentId: String(input.sourcePolicyAdjustmentId || input.sourceContext?.policyAdjustmentId || "").trim(),
    sourceSuggestionType: String(input.sourceSuggestionType || input.sourceContext?.suggestionType || "").trim(),
    sourceEffectOutcome: String(input.sourceEffectOutcome || input.sourceContext?.outcome || "").trim(),
    sourceEffectScore: Number.isFinite(Number(input.sourceEffectScore ?? input.sourceContext?.effectScore)) ? Number(input.sourceEffectScore ?? input.sourceContext?.effectScore) : null,
    status,
    active: slaPolicyCandidateQualityCalibrationActive({ status }),
    suggestedCalibration: suggested,
    activeCalibration,
    simulation: input.simulation && typeof input.simulation === "object" ? input.simulation : {},
    previousQuality: input.previousQuality && typeof input.previousQuality === "object" ? input.previousQuality : (suggested.previousQuality || {}),
    reviewReason: String(input.reviewReason || input.reason || "").trim(),
    overrideReason: String(input.overrideReason || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    updatedAt: input.updatedAt || input.reviewedAt || input.proposedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system",
    events: Array.isArray(input.events) ? input.events.map(slaPolicyCandidateQualityCalibrationEvent) : []
  };
}

function slaPolicyCandidateQualityCalibrationMap(items = []) {
  return new Map(items
    .map(normalizeSlaPolicyCandidateQualityCalibration)
    .map((item) => [item.calibrationId, item]));
}

function approvedSlaPolicyCandidateQualityCalibration(candidate = {}, workflowItems = []) {
  const item = slaPolicyCandidateQualityCalibrationMap(workflowItems).get(slaPolicyCandidateQualityCalibrationId(candidate));
  if (!item || !slaPolicyCandidateQualityCalibrationActive(item)) return null;
  return item;
}

function applySlaPolicyCandidateQualityCalibration(candidate = {}, qualityReport = {}, workflowItems = []) {
  const calibrationId = slaPolicyCandidateQualityCalibrationId(candidate);
  const suggestedCalibration = slaPolicyCandidateQualityCalibration(candidate, qualityReport);
  const workflowItem = slaPolicyCandidateQualityCalibrationMap(workflowItems).get(calibrationId) || null;
  const activeWorkflow = workflowItem && slaPolicyCandidateQualityCalibrationActive(workflowItem) ? workflowItem : null;
  const activeCalibration = activeWorkflow?.activeCalibration || null;
  const effectiveCalibration = activeCalibration || null;
  const simulation = slaPolicyCandidateQualityCalibrationSimulation(candidate, suggestedCalibration, effectiveCalibration);
  const qualityText = effectiveCalibration ? `Approved quality calibration: ${effectiveCalibration.reason || suggestedCalibration.reason}` : "";
  const priorityAfter = effectiveCalibration?.priorityAfter || suggestedCalibration.priorityBefore;
  const qualityCalibration = {
    calibrationId,
    status: workflowItem?.status || "proposed",
    active: Boolean(effectiveCalibration),
    applied: Boolean(effectiveCalibration && priorityAfter !== suggestedCalibration.priorityBefore),
    direction: effectiveCalibration?.direction || suggestedCalibration.direction,
    candidateType: suggestedCalibration.candidateType,
    priorityBefore: suggestedCalibration.priorityBefore,
    priorityAfter,
    suggestedPriorityAfter: suggestedCalibration.priorityAfter,
    reason: effectiveCalibration?.reason || suggestedCalibration.reason,
    reviewReason: workflowItem?.reviewReason || "",
    overrideReason: workflowItem?.overrideReason || "",
    previousQuality: suggestedCalibration.previousQuality,
    suggestedCalibration,
    activeCalibration: effectiveCalibration,
    simulation,
    reviewedAt: workflowItem?.reviewedAt || "",
    reviewedBy: workflowItem?.reviewedBy || ""
  };
  return {
    ...candidate,
    priority: priorityAfter,
    basis: [candidate.basis, qualityText].filter(Boolean).join(" "),
    recommendation: [candidate.recommendation, qualityText].filter(Boolean).join(" "),
    qualityCalibration,
    sourceContext: {
      ...(candidate.sourceContext || {}),
      qualityCalibration
    }
  };
}

function slaPolicyEffectAdjustmentCandidates(effectItems = [], qualityReport = {}, workflowItems = []) {
  const candidates = [];
  effectItems.forEach((effectItem) => {
    (effectItem.suggestions || []).forEach((suggestion) => {
      const candidateType = slaPolicyEffectSuggestionCandidateType(suggestion.type);
      if (!candidateType) return;
      const metrics = slaPolicyEffectCandidateMetrics(effectItem);
      const candidate = {
        policyAdjustmentId: slaPolicyEffectGeneratedCandidateId(effectItem, suggestion),
        type: candidateType,
        candidateType,
        target: effectItem.target || effectItem.issueKey || "",
        issueKey: effectItem.issueKey || effectItem.target || "",
        priority: suggestion.priority || (candidateType === "rollback_policy_adjustment" || candidateType === "additional_tightening_policy" ? "high" : "medium"),
        basis: [
          `Generated from post-change effectiveness of ${effectItem.policyAdjustmentId}.`,
          `Outcome ${effectItem.outcome}, effect score ${effectItem.effectScore ?? "pending"}.`,
          `Success ${effectItem.before?.successRate || 0}% -> ${effectItem.after?.successRate || 0}%, false positive ${effectItem.before?.falsePositiveRate || 0}% -> ${effectItem.after?.falsePositiveRate || 0}%, recurrence ${effectItem.before?.recurrenceRate || 0}% -> ${effectItem.after?.recurrenceRate || 0}%.`,
          suggestion.reason || ""
        ].filter(Boolean).join(" "),
        recommendation: suggestion.label ? `${suggestion.label}: ${suggestion.reason || ""}` : suggestion.reason || "",
        metrics,
        expectedImpact: slaPolicyEffectCandidateExpectedImpact(effectItem, suggestion, candidateType),
        sourcePolicyAdjustmentId: effectItem.policyAdjustmentId,
        sourceEffectOutcome: effectItem.outcome,
        sourceEffectScore: effectItem.effectScore,
        sourceBeforePolicy: effectItem.sourceBeforePolicy || {},
        sourceAfterPolicy: effectItem.sourceAfterPolicy || {},
        sourcePolicyPatch: effectItem.sourcePolicyPatch || {},
        sourceContext: {
          source: "sla_policy_effectiveness",
          policyAdjustmentId: effectItem.policyAdjustmentId,
          suggestionType: suggestion.type,
          outcome: effectItem.outcome,
          effectScore: effectItem.effectScore,
          windowDays: effectItem.windowDays,
          beforeWindow: effectItem.beforeWindow,
          afterWindow: effectItem.afterWindow
        }
      };
      candidates.push(applySlaPolicyCandidateQualityCalibration(candidate, qualityReport, workflowItems));
    });
  });
  return candidates;
}

function attachSlaPolicyEffectGeneratedProposals(effectItems = [], candidates = [], proposals = []) {
  const candidateByKey = new Map(candidates.map((candidate) => [
    [candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "", candidate.sourceContext?.suggestionType || ""].join("|"),
    candidate
  ]));
  const proposalById = new Map(proposals.map((proposal) => [proposal.policyAdjustmentId, proposal]));
  return effectItems.map((effectItem) => ({
    ...effectItem,
    suggestions: (effectItem.suggestions || []).map((suggestion) => {
      const candidate = candidateByKey.get([effectItem.policyAdjustmentId || "", suggestion.type || ""].join("|"));
      if (!candidate) return suggestion;
      const proposal = proposalById.get(candidate.policyAdjustmentId) || null;
      return {
        ...suggestion,
        generatedCandidateType: candidate.candidateType,
        generatedProposal: {
          policyAdjustmentId: candidate.policyAdjustmentId,
          status: proposal?.status || "proposed",
          duplicateStatus: proposal?.duplicateStatus || "created",
          duplicateOfPolicyAdjustmentId: proposal?.duplicateOfPolicyAdjustmentId || "",
          priority: proposal?.priority || candidate.priority,
          target: proposal?.target || candidate.target,
          qualityCalibration: proposal?.qualityCalibration || candidate.qualityCalibration || {}
        }
      };
    })
  }));
}

function shouldStoreSlaPolicyCandidateQualityCalibration(candidate = {}) {
  const calibration = candidate.qualityCalibration || {};
  const suggested = calibration.suggestedCalibration || calibration;
  return Boolean(suggested?.previousQuality?.total || suggested?.direction !== "neutral");
}

function buildSlaPolicyCandidateQualityCalibrationProposal(candidate = {}, existing = null) {
  const calibration = candidate.qualityCalibration || {};
  const suggested = calibration.suggestedCalibration || calibration;
  const now = new Date().toISOString();
  const existingNormalized = existing ? normalizeSlaPolicyCandidateQualityCalibration(existing) : null;
  const status = existingNormalized?.status || "proposed";
  const activeCalibration = slaPolicyCandidateQualityCalibrationActive({ status })
    ? existingNormalized?.activeCalibration || suggested
    : null;
  const creationEvent = slaPolicyCandidateQualityCalibrationEvent({
    calibrationId: calibration.calibrationId,
    eventType: "proposed",
    eventAt: existingNormalized?.proposedAt || now,
    eventBy: existingNormalized?.proposedBy || "system",
    previousStatus: "",
    nextStatus: status,
    reason: "Quality calibration proposal generated from effect-based candidate quality."
  });
  return normalizeSlaPolicyCandidateQualityCalibration({
    ...(existingNormalized || {}),
    calibrationId: calibration.calibrationId || slaPolicyCandidateQualityCalibrationId(candidate),
    policyAdjustmentId: candidate.policyAdjustmentId,
    candidateType: candidate.candidateType,
    target: candidate.target,
    issueKey: candidate.issueKey,
    sourcePolicyAdjustmentId: candidate.sourcePolicyAdjustmentId,
    sourceSuggestionType: candidate.sourceContext?.suggestionType || "",
    sourceEffectOutcome: candidate.sourceEffectOutcome,
    sourceEffectScore: candidate.sourceEffectScore,
    status,
    activeCalibration,
    suggestedCalibration: suggested,
    simulation: calibration.simulation || slaPolicyCandidateQualityCalibrationSimulation(candidate, suggested, activeCalibration),
    previousQuality: suggested.previousQuality || {},
    proposedAt: existingNormalized?.proposedAt || now,
    proposedBy: existingNormalized?.proposedBy || "system",
    reviewedAt: existingNormalized?.reviewedAt || "",
    reviewedBy: existingNormalized?.reviewedBy || "",
    reviewReason: existingNormalized?.reviewReason || "",
    overrideReason: existingNormalized?.overrideReason || "",
    updatedAt: status === "proposed" ? now : existingNormalized?.updatedAt || now,
    updatedBy: status === "proposed" ? "system" : existingNormalized?.updatedBy || "system",
    events: existingNormalized?.events?.length ? existingNormalized.events : [creationEvent]
  });
}

async function upsertSlaPolicyCandidateQualityCalibrationProposals(candidates = []) {
  const data = await readSlaPolicyCandidateQualityCalibrations();
  const existingItems = Array.isArray(data.items) ? data.items.map(normalizeSlaPolicyCandidateQualityCalibration) : [];
  const byId = new Map(existingItems.map((item) => [item.calibrationId, item]));
  const touched = [];
  candidates
    .filter(shouldStoreSlaPolicyCandidateQualityCalibration)
    .forEach((candidate) => {
      const calibrationId = candidate.qualityCalibration?.calibrationId || slaPolicyCandidateQualityCalibrationId(candidate);
      const proposal = buildSlaPolicyCandidateQualityCalibrationProposal(candidate, byId.get(calibrationId) || null);
      byId.set(calibrationId, proposal);
      touched.push(proposal);
    });
  await writeSlaPolicyCandidateQualityCalibrations({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return touched;
}

function slaPolicyCandidateQualityCalibrationSummary(items = []) {
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    overridden: items.filter((item) => item.status === "overridden").length,
    deactivated: items.filter((item) => item.status === "deactivated").length,
    active: items.filter(slaPolicyCandidateQualityCalibrationActive).length,
    boostSuggested: items.filter((item) => item.suggestedCalibration?.direction === "boost").length,
    downgradeSuggested: items.filter((item) => item.suggestedCalibration?.direction === "downgrade").length
  };
}

function filterSlaPolicyCandidateQualityCalibrations(items = [], payload = {}) {
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(payload.status || "");
  const hasStatusFilter = String(payload.status || "").trim();
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  return items
    .filter((item) => !hasStatusFilter || item.status === status)
    .filter((item) => !target || String(item.target || item.issueKey || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type);
}

function slaPolicyCandidateQualityCalibrationWorkflowReport(items = [], payload = {}) {
  const normalized = items.map(normalizeSlaPolicyCandidateQualityCalibration);
  const filtered = filterSlaPolicyCandidateQualityCalibrations(normalized, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const sorted = [...filtered].sort((a, b) => {
    const statusRank = { proposed: 0, overridden: 1, approved: 2, rejected: 3 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.reviewedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.reviewedAt || a.proposedAt || ""));
  });
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_calibrations",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      target: String(payload.target || payload.issueKey || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      limit
    },
    summary: slaPolicyCandidateQualityCalibrationSummary(filtered),
    fullSummary: slaPolicyCandidateQualityCalibrationSummary(normalized),
    items: sorted.slice(0, limit),
    reportBoundaries: {
      source: "admin-only effect-based SLA policy candidate quality calibration workflow",
      hiddenFromBusiness: ["quality calibration proposals", "approval status", "override reasons", "candidate quality history", "operator review events"]
    }
  };
}

function slaPolicyCalibrationRate(count = 0, total = 0) {
  return total ? Math.round((Number(count || 0) / Number(total || 0)) * 100) : 0;
}

function slaPolicyCalibrationPerformanceScore(candidate = {}, quality = {}, calibration = {}) {
  let score = 50;
  if (candidate.status === "approved") score += 15;
  if (candidate.status === "rejected") score -= 25;
  if (quality.qualityOutcome === "successful") score += 25;
  if (quality.qualityOutcome === "neutral") score += 5;
  if (quality.qualityOutcome === "failed") score -= 30;
  if (quality.qualityOutcome === "pending_review") score -= 5;
  if (quality.repeatRecommended) score -= 20;
  if (calibration.status === "overridden" && quality.qualityOutcome === "successful") score += 5;
  return safeScore(score);
}

function slaPolicyCalibrationPerformanceState(score = 0) {
  if (score >= 70) return "well_matched";
  if (score <= 45) return "weak_match";
  return "watch";
}

function slaPolicyCalibrationReReviewReason(item = {}) {
  if (!item.active) return "";
  if (item.candidateStatus === "rejected") return "The active calibration led to a policy candidate that was rejected.";
  if (item.qualityOutcome === "failed") return "The approved policy candidate later produced weak post-change effectiveness.";
  if (item.repeatRecommended) return item.repeatRecommendationReason || "The same candidate type was recommended again after the calibration.";
  if (Number(item.performanceScore || 0) <= 45) return "The active calibration performance score is below the review threshold.";
  return "";
}

function slaPolicyCandidateQualityCalibrationPerformanceItem(calibration = {}, policyById = new Map(), effectByPolicyId = new Map()) {
  const item = normalizeSlaPolicyCandidateQualityCalibration(calibration);
  const candidate = policyById.get(item.policyAdjustmentId) || normalizeSlaAutoApprovalPolicyAdjustment({
    policyAdjustmentId: item.policyAdjustmentId,
    candidateType: item.candidateType,
    target: item.target,
    issueKey: item.issueKey,
    priority: item.activeCalibration?.priorityAfter || item.suggestedCalibration?.priorityBefore || "medium",
    status: "proposed",
    sourceContext: {
      source: "sla_policy_effectiveness",
      policyAdjustmentId: item.sourcePolicyAdjustmentId,
      outcome: item.sourceEffectOutcome,
      effectScore: item.sourceEffectScore
    },
    sourcePolicyAdjustmentId: item.sourcePolicyAdjustmentId,
    sourceEffectOutcome: item.sourceEffectOutcome,
    sourceEffectScore: item.sourceEffectScore
  });
  const quality = slaPolicyCandidateQualityItem(candidate, effectByPolicyId);
  const previous = item.previousQuality || item.suggestedCalibration?.previousQuality || {};
  const reviewedBefore = Number(previous.approved || 0) + Number(previous.rejected || 0);
  const candidateReviewed = ["approved", "rejected"].includes(candidate.status);
  const evaluated = Boolean(quality.evaluated);
  const performanceScore = slaPolicyCalibrationPerformanceScore(candidate, quality, item);
  const state = slaPolicyCalibrationPerformanceState(performanceScore);
  const result = {
    calibrationId: item.calibrationId,
    policyAdjustmentId: item.policyAdjustmentId,
    candidateType: item.candidateType,
    target: item.target || item.issueKey,
    status: item.status,
    active: slaPolicyCandidateQualityCalibrationActive(item),
    decisionType: item.status,
    direction: item.activeCalibration?.direction || item.suggestedCalibration?.direction || "neutral",
    priorityBefore: item.suggestedCalibration?.priorityBefore || "",
    suggestedPriorityAfter: item.suggestedCalibration?.priorityAfter || "",
    activePriorityAfter: item.activeCalibration?.priorityAfter || "",
    reviewedAt: item.reviewedAt,
    reviewedBy: item.reviewedBy,
    candidateStatus: candidate.status,
    candidatePriority: candidate.priority,
    candidateReviewed,
    candidateApproved: candidate.status === "approved",
    candidateRejected: candidate.status === "rejected",
    qualityOutcome: quality.qualityOutcome,
    postEffectOutcome: quality.postEffectOutcome,
    postEffectScore: quality.postEffectScore,
    successful: quality.successful,
    evaluated,
    repeatRecommended: quality.repeatRecommended,
    repeatRecommendationReason: quality.repeatRecommendationReason,
    performanceScore,
    performanceState: state,
    previousQuality: previous,
    beforeMetrics: {
      approvalRate: Number(previous.approvalRate || 0),
      rejectionRate: reviewedBefore ? slaPolicyCalibrationRate(previous.rejected, reviewedBefore) : 0,
      postSuccessRate: Number(previous.approvalSuccessRate || 0),
      repeatRecommendationRate: Number(previous.repeatRecommendationRate || 0)
    },
    afterMetrics: {
      approvalRate: candidateReviewed ? (candidate.status === "approved" ? 100 : 0) : 0,
      rejectionRate: candidateReviewed ? (candidate.status === "rejected" ? 100 : 0) : 0,
      overrideRate: item.status === "overridden" ? 100 : 0,
      postSuccessRate: evaluated ? (quality.successful ? 100 : 0) : 0,
      repeatRecommendationRate: quality.repeatRecommended ? 100 : 0
    },
    reviewReason: item.reviewReason,
    overrideReason: item.overrideReason
  };
  const reason = slaPolicyCalibrationReReviewReason(result);
  return {
    ...result,
    reReviewNeeded: Boolean(reason),
    reReviewReason: reason,
    recommendedAction: reason ? "reopen_quality_calibration_review" : ""
  };
}

function emptySlaPolicyCalibrationPerformanceBucket(key = "", label = "") {
  return {
    key,
    label: label || key || "all",
    total: 0,
    active: 0,
    approvedDecisions: 0,
    overriddenDecisions: 0,
    rejectedDecisions: 0,
    candidateReviewed: 0,
    candidateApproved: 0,
    candidateRejected: 0,
    evaluated: 0,
    successful: 0,
    failed: 0,
    repeatRecommended: 0,
    reReviewNeeded: 0,
    scoreTotal: 0,
    beforeApprovalRateTotal: 0,
    beforeRejectionRateTotal: 0,
    beforePostSuccessRateTotal: 0,
    beforeRepeatRateTotal: 0
  };
}

function addSlaPolicyCalibrationPerformanceBucket(row = emptySlaPolicyCalibrationPerformanceBucket(), item = {}) {
  row.total += 1;
  if (item.active) row.active += 1;
  if (item.status === "approved") row.approvedDecisions += 1;
  if (item.status === "overridden") row.overriddenDecisions += 1;
  if (item.status === "rejected") row.rejectedDecisions += 1;
  if (item.candidateReviewed) row.candidateReviewed += 1;
  if (item.candidateApproved) row.candidateApproved += 1;
  if (item.candidateRejected) row.candidateRejected += 1;
  if (item.evaluated) row.evaluated += 1;
  if (item.successful) row.successful += 1;
  if (item.qualityOutcome === "failed") row.failed += 1;
  if (item.repeatRecommended) row.repeatRecommended += 1;
  if (item.reReviewNeeded) row.reReviewNeeded += 1;
  row.scoreTotal += Number(item.performanceScore || 0);
  row.beforeApprovalRateTotal += Number(item.beforeMetrics?.approvalRate || 0);
  row.beforeRejectionRateTotal += Number(item.beforeMetrics?.rejectionRate || 0);
  row.beforePostSuccessRateTotal += Number(item.beforeMetrics?.postSuccessRate || 0);
  row.beforeRepeatRateTotal += Number(item.beforeMetrics?.repeatRecommendationRate || 0);
  return row;
}

function finalizeSlaPolicyCalibrationPerformanceBucket(row = emptySlaPolicyCalibrationPerformanceBucket()) {
  const total = Number(row.total || 0);
  return {
    key: row.key,
    label: row.label,
    total,
    active: row.active,
    approvedDecisions: row.approvedDecisions,
    overriddenDecisions: row.overriddenDecisions,
    rejectedDecisions: row.rejectedDecisions,
    candidateReviewed: row.candidateReviewed,
    candidateApproved: row.candidateApproved,
    candidateRejected: row.candidateRejected,
    evaluated: row.evaluated,
    successful: row.successful,
    failed: row.failed,
    repeatRecommended: row.repeatRecommended,
    reReviewNeeded: row.reReviewNeeded,
    avgPerformanceScore: total ? Math.round(row.scoreTotal / total) : 0,
    before: {
      approvalRate: total ? Math.round(row.beforeApprovalRateTotal / total) : 0,
      rejectionRate: total ? Math.round(row.beforeRejectionRateTotal / total) : 0,
      postSuccessRate: total ? Math.round(row.beforePostSuccessRateTotal / total) : 0,
      repeatRecommendationRate: total ? Math.round(row.beforeRepeatRateTotal / total) : 0,
      overrideRate: 0
    },
    after: {
      approvalRate: slaPolicyCalibrationRate(row.candidateApproved, row.candidateReviewed),
      rejectionRate: slaPolicyCalibrationRate(row.candidateRejected, row.candidateReviewed),
      overrideRate: slaPolicyCalibrationRate(row.overriddenDecisions, total),
      postSuccessRate: slaPolicyCalibrationRate(row.successful, row.evaluated),
      repeatRecommendationRate: slaPolicyCalibrationRate(row.repeatRecommended, total)
    },
    performanceState: row.reReviewNeeded > 0 || (total && row.scoreTotal / total <= 45)
      ? "weak_match"
      : total && row.scoreTotal / total >= 70
        ? "well_matched"
        : "watch"
  };
}

function groupSlaPolicyCalibrationPerformance(items = [], groupKeyFn = () => "all", labelFn = groupKeyFn) {
  const map = new Map();
  items.forEach((item) => {
    const key = String(groupKeyFn(item) || "unknown");
    const label = String(labelFn(item) || key);
    const row = map.get(key) || emptySlaPolicyCalibrationPerformanceBucket(key, label);
    addSlaPolicyCalibrationPerformanceBucket(row, item);
    map.set(key, row);
  });
  return [...map.values()]
    .map(finalizeSlaPolicyCalibrationPerformanceBucket)
    .sort((a, b) => b.total - a.total || a.avgPerformanceScore - b.avgPerformanceScore || String(a.label).localeCompare(String(b.label)));
}

function slaPolicyCandidateQualityCalibrationPerformanceReport(calibrations = [], policyAdjustments = [], effectItems = [], payload = {}) {
  const policyById = new Map(policyAdjustments.map(normalizeSlaAutoApprovalPolicyAdjustment).map((item) => [item.policyAdjustmentId, item]));
  const effectByPolicyId = new Map(effectItems.map((item) => [item.policyAdjustmentId, item]));
  const allItems = calibrations
    .map(normalizeSlaPolicyCandidateQualityCalibration)
    .filter((item) => ["approved", "overridden", "rejected"].includes(item.status))
    .map((item) => slaPolicyCandidateQualityCalibrationPerformanceItem(item, policyById, effectByPolicyId));
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  const filtered = allItems
    .filter((item) => !target || String(item.target || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const summary = finalizeSlaPolicyCalibrationPerformanceBucket(filtered.reduce((row, item) => addSlaPolicyCalibrationPerformanceBucket(row, item), emptySlaPolicyCalibrationPerformanceBucket("all", "All quality calibrations")));
  const byDecision = groupSlaPolicyCalibrationPerformance(filtered, (item) => item.decisionType, (item) => item.decisionType);
  const byType = groupSlaPolicyCalibrationPerformance(
    filtered,
    (item) => [item.candidateType || "unknown", item.direction || "neutral", item.decisionType || ""].join("|"),
    (item) => `${item.candidateType || "unknown"} / ${item.direction || "neutral"} / ${item.decisionType || ""}`
  );
  const strongTypes = byType.filter((row) => row.performanceState === "well_matched").slice(0, 6);
  const weakTypes = byType.filter((row) => row.performanceState === "weak_match").slice(0, 6);
  const reReviewCandidates = filtered
    .filter((item) => item.reReviewNeeded)
    .sort((a, b) => Number(a.performanceScore || 0) - Number(b.performanceScore || 0) || String(b.reviewedAt || "").localeCompare(String(a.reviewedAt || "")))
    .slice(0, limit);
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_calibration_performance",
    generatedAt: new Date().toISOString(),
    summary,
    byDecision,
    byType,
    strongTypes,
    weakTypes,
    reReviewCandidates,
    items: filtered
      .sort((a, b) => Number(a.performanceScore || 0) - Number(b.performanceScore || 0) || String(b.reviewedAt || "").localeCompare(String(a.reviewedAt || "")))
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA policy candidate quality calibration performance tracking",
      hiddenFromBusiness: ["quality calibration performance", "re-review candidates", "candidate approval outcomes", "post-change SLA effects", "operator review metrics"]
    }
  };
}

function normalizeSlaPolicyCandidateQualityRereviewStatus(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["open", "in_progress", "completed", "deferred", "dismissed"].includes(text)) return text;
  return "open";
}

function normalizeSlaPolicyCandidateQualityRereviewAction(value = "") {
  const text = String(value || "").trim().toLowerCase();
  if (["maintain_active", "deactivate_active", "propose_modified_calibration", "watch", "none"].includes(text)) return text;
  return "watch";
}

function slaPolicyCandidateQualityRereviewId(item = {}) {
  return hashId("spcqrr", [
    item.calibrationId || "",
    item.policyAdjustmentId || "",
    item.candidateType || "",
    item.target || ""
  ].join("|"));
}

function slaPolicyCandidateQualityRereviewDueState(dueDate = "") {
  const text = String(dueDate || "").slice(0, 10);
  if (!text) return "no_due";
  const today = kstDate(0);
  if (text < today) return "overdue";
  const days = dateDiffDays(today, text);
  return Number.isFinite(days) && days <= 7 ? "this_week" : "scheduled";
}

function normalizeSlaPolicyCandidateQualityRereviewLog(input = {}) {
  const changedAt = input.changedAt || new Date().toISOString();
  const fields = input.fields && typeof input.fields === "object" ? input.fields : {};
  const linkedCalibration = input.linkedCalibration && typeof input.linkedCalibration === "object" ? input.linkedCalibration : null;
  return {
    logId: String(input.logId || hashId("spcqrl", [
      input.rereviewId || "",
      input.eventType || input.changeType || "",
      changedAt,
      input.changedBy || ""
    ].join("|"))).trim(),
    rereviewId: String(input.rereviewId || "").trim(),
    calibrationId: String(input.calibrationId || "").trim(),
    policyAdjustmentId: String(input.policyAdjustmentId || "").trim(),
    eventType: String(input.eventType || input.changeType || "updated").trim(),
    changedAt,
    changedBy: String(input.changedBy || input.updatedBy || "admin").trim() || "admin",
    fields,
    changedFields: Object.keys(fields),
    before: input.before && typeof input.before === "object" ? input.before : {},
    after: input.after && typeof input.after === "object" ? input.after : {},
    completionResult: String(input.completionResult || "").trim(),
    linkedCalibration,
    memo: String(input.memo || "").trim()
  };
}

function slaPolicyCandidateQualityRereviewLogFields(before = {}, after = {}) {
  const fields = {};
  ["status", "owner", "dueDate", "memo", "followUpActionType", "completionResult"].forEach((key) => {
    const beforeValue = before?.[key] ?? "";
    const afterValue = after?.[key] ?? "";
    if (String(beforeValue) !== String(afterValue)) {
      fields[key] = {
        before: beforeValue,
        after: afterValue
      };
    }
  });
  return fields;
}

function summarizeSlaPolicyCandidateQualityRereviewLogs(logs = []) {
  const normalized = logs.map(normalizeSlaPolicyCandidateQualityRereviewLog)
    .sort((a, b) => String(b.changedAt || "").localeCompare(String(a.changedAt || "")));
  const fieldCounts = normalized.reduce((acc, log) => {
    (log.changedFields || []).forEach((field) => {
      acc[field] = (acc[field] || 0) + 1;
    });
    return acc;
  }, {});
  return {
    totalLogs: normalized.length,
    latestChangedAt: normalized[0]?.changedAt || "",
    latestChangedBy: normalized[0]?.changedBy || "",
    latestEventType: normalized[0]?.eventType || "",
    changedFieldSummary: Object.entries(fieldCounts)
      .map(([field, count]) => `${field}:${count}`)
      .join("; "),
    completionEvents: normalized.filter((log) => log.eventType === "completed").length,
    linkedCalibrationEvents: normalized.filter((log) => log.linkedCalibration).length,
    recent: normalized.slice(0, 6)
  };
}

async function appendSlaPolicyCandidateQualityRereviewLog(log = {}) {
  const normalized = normalizeSlaPolicyCandidateQualityRereviewLog(log);
  if (!normalized.rereviewId || (!normalized.changedFields.length && normalized.eventType !== "completed" && !normalized.linkedCalibration)) {
    return null;
  }
  const data = await readSlaPolicyCandidateQualityRereviewLogs();
  await writeSlaPolicyCandidateQualityRereviewLogs({
    ...data,
    items: [
      normalized,
      ...(Array.isArray(data.items) ? data.items : [])
    ]
  });
  return normalized;
}

function slaPolicyCandidateQualityRereviewLogMap(logs = []) {
  const map = new Map();
  logs.map(normalizeSlaPolicyCandidateQualityRereviewLog).forEach((log) => {
    if (!log.rereviewId) return;
    const list = map.get(log.rereviewId) || [];
    list.push(log);
    map.set(log.rereviewId, list);
  });
  return map;
}

function slaPolicyCandidateQualityRereviewHoursBetween(startAt = "", endAt = "") {
  const start = new Date(startAt).getTime();
  const end = new Date(endAt).getTime();
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return null;
  return Number(((end - start) / 3600000).toFixed(1));
}

function slaPolicyCandidateQualityRereviewStatusTransition(log = {}) {
  const statusField = log.fields?.status || {};
  const before = String(statusField.before ?? log.before?.status ?? "").trim();
  const after = String(statusField.after ?? log.after?.status ?? "").trim();
  return { before, after };
}

function slaPolicyCandidateQualityRereviewLinkedOutcome(metric = {}) {
  const actionType = String(metric.completionActionType || "").trim();
  const nextStatus = String(metric.linkedCalibrationStatus || "").trim();
  if (["failed", "failure", "error"].includes(nextStatus)) return "failed";
  if (actionType === "deactivate_active" || nextStatus === "deactivated") return "deactivated";
  if (actionType === "propose_modified_calibration" || nextStatus === "proposed") return "modified_proposed";
  if (actionType === "maintain_active" || (nextStatus && nextStatus === metric.linkedCalibrationPreviousStatus)) return "maintained";
  return actionType || nextStatus || "none";
}

function slaPolicyCandidateQualityRereviewRequiresLinkage(actionType = "") {
  return ["maintain_active", "deactivate_active", "propose_modified_calibration"].includes(String(actionType || "").trim());
}

function slaPolicyCandidateQualityRereviewOperationalMetric(item = {}, logs = []) {
  const orderedLogs = logs.map(normalizeSlaPolicyCandidateQualityRereviewLog)
    .sort((a, b) => String(a.changedAt || "").localeCompare(String(b.changedAt || "")));
  const statusLogs = orderedLogs.filter((log) => log.changedFields?.includes("status"));
  const completionLogs = orderedLogs.filter((log) => log.eventType === "completed" || slaPolicyCandidateQualityRereviewStatusTransition(log).after === "completed");
  const linkedLogs = orderedLogs.filter((log) => log.linkedCalibration);
  const firstLog = orderedLogs[0] || null;
  const latestLog = orderedLogs[orderedLogs.length - 1] || null;
  const latestCompletionLog = completionLogs[completionLogs.length - 1] || null;
  const latestLinkedLog = linkedLogs[linkedLogs.length - 1] || null;
  const linked = latestLinkedLog?.linkedCalibration || null;
  const createdAt = item.createdAt || firstLog?.changedAt || "";
  const completedAt = item.completedAt || latestCompletionLog?.changedAt || "";
  const latestActivityAt = completedAt || latestLog?.changedAt || item.updatedAt || createdAt || "";
  const reopenCount = statusLogs.filter((log) => {
    const transition = slaPolicyCandidateQualityRereviewStatusTransition(log);
    return transition.before === "completed" && transition.after && transition.after !== "completed";
  }).length;
  const completionActionType = linked?.actionType || item.completionResult || latestCompletionLog?.completionResult || "";
  const terminal = ["completed", "dismissed"].includes(item.status || "");
  const delayedIncomplete = !terminal && item.dueState === "overdue";
  const requiresActiveCalibrationLink = item.status === "completed" && slaPolicyCandidateQualityRereviewRequiresLinkage(completionActionType);
  const metric = {
    rereviewId: item.rereviewId || "",
    calibrationId: item.calibrationId || "",
    policyAdjustmentId: item.policyAdjustmentId || "",
    status: item.status || "",
    owner: item.owner || latestCompletionLog?.changedBy || latestLog?.changedBy || "unassigned",
    createdAt,
    completedAt,
    latestActivityAt,
    activityMonth: monthKey(latestActivityAt) || "unknown",
    completedMonth: monthKey(completedAt) || "",
    processingHours: completedAt ? slaPolicyCandidateQualityRereviewHoursBetween(createdAt, completedAt) : null,
    statusTransitionCount: statusLogs.length,
    reopenCount,
    logCount: orderedLogs.length,
    linkedCalibrationEvents: linkedLogs.length,
    completionActionType,
    linkedCalibrationPreviousStatus: linked?.previousStatus || "",
    linkedCalibrationStatus: linked?.nextStatus || "",
    linkedCalibrationChangedAt: linked?.changedAt || latestLinkedLog?.changedAt || "",
    linkedCalibrationChangedBy: linked?.changedBy || latestLinkedLog?.changedBy || "",
    delayedIncomplete,
    requiresActiveCalibrationLink
  };
  const linkedCalibrationResult = slaPolicyCandidateQualityRereviewLinkedOutcome(metric);
  const activeCalibrationLinkProcessed = requiresActiveCalibrationLink &&
    ["maintained", "deactivated", "modified_proposed"].includes(linkedCalibrationResult) &&
    linkedLogs.length > 0;
  const activeCalibrationLinkFailed = requiresActiveCalibrationLink && linkedLogs.length > 0 && !activeCalibrationLinkProcessed;
  const activeCalibrationLinkUnprocessed = requiresActiveCalibrationLink && linkedLogs.length === 0;
  return {
    ...metric,
    linkedCalibrationResult,
    activeCalibrationLinkProcessed,
    activeCalibrationLinkFailed,
    activeCalibrationLinkUnprocessed,
    activeCalibrationLinkIssue: requiresActiveCalibrationLink && !activeCalibrationLinkProcessed
  };
}

function emptySlaPolicyCandidateQualityRereviewOperationalAggregate(key = "", label = "") {
  return {
    key,
    label: label || key || "unknown",
    total: 0,
    completed: 0,
    open: 0,
    inProgress: 0,
    deferred: 0,
    dismissed: 0,
    processingSamples: 0,
    processingHoursTotal: 0,
    statusTransitionCount: 0,
    reopenedItems: 0,
    reopenCount: 0,
    linkedCalibrationEvents: 0,
    delayedIncompleteItems: 0,
    activeLinkRequired: 0,
    activeLinkUnprocessed: 0,
    activeLinkFailed: 0,
    activeLinkIssue: 0,
    maintained: 0,
    deactivated: 0,
    modifiedProposed: 0,
    noLinkedAction: 0,
    latestActivityAt: ""
  };
}

function addSlaPolicyCandidateQualityRereviewOperationalMetric(row = {}, metric = {}) {
  row.total += 1;
  if (metric.status === "completed") row.completed += 1;
  if (metric.status === "open") row.open += 1;
  if (metric.status === "in_progress") row.inProgress += 1;
  if (metric.status === "deferred") row.deferred += 1;
  if (metric.status === "dismissed") row.dismissed += 1;
  if (metric.processingHours !== null && metric.processingHours !== undefined && metric.processingHours !== "" && Number.isFinite(Number(metric.processingHours))) {
    row.processingSamples += 1;
    row.processingHoursTotal += Number(metric.processingHours);
  }
  row.statusTransitionCount += Number(metric.statusTransitionCount || 0);
  row.reopenCount += Number(metric.reopenCount || 0);
  if (Number(metric.reopenCount || 0) > 0) row.reopenedItems += 1;
  row.linkedCalibrationEvents += Number(metric.linkedCalibrationEvents || 0);
  if (metric.delayedIncomplete) row.delayedIncompleteItems += 1;
  if (metric.requiresActiveCalibrationLink) row.activeLinkRequired += 1;
  if (metric.activeCalibrationLinkUnprocessed) row.activeLinkUnprocessed += 1;
  if (metric.activeCalibrationLinkFailed) row.activeLinkFailed += 1;
  if (metric.activeCalibrationLinkIssue || metric.activeCalibrationLinkUnprocessed || metric.activeCalibrationLinkFailed) row.activeLinkIssue += 1;
  const outcome = slaPolicyCandidateQualityRereviewLinkedOutcome(metric);
  if (outcome === "maintained") row.maintained += 1;
  else if (outcome === "deactivated") row.deactivated += 1;
  else if (outcome === "modified_proposed") row.modifiedProposed += 1;
  else row.noLinkedAction += 1;
  if (String(metric.latestActivityAt || "") > String(row.latestActivityAt || "")) row.latestActivityAt = metric.latestActivityAt || "";
  return row;
}

function slaPolicyCandidateQualityRereviewSlaEvaluation(metrics = {}, scope = "summary") {
  const issues = [];
  const avgHours = metrics.avgProcessingHours;
  const reopenRate = Number(metrics.reopenRate || 0);
  const delayedIncomplete = Number(metrics.delayedIncompleteItems || 0);
  const activeLinkUnprocessed = Number(metrics.activeLinkUnprocessed || 0);
  const activeLinkFailed = Number(metrics.activeLinkFailed || 0);
  const activeLinkIssue = Number(metrics.activeLinkIssue ?? activeLinkUnprocessed + activeLinkFailed);
  const activeLinkIssueRate = Number(metrics.activeLinkIssueRate ?? metrics.activeLinkUnprocessedRate ?? 0);
  const completionRate = Number(metrics.completionRate || 0);
  const total = Number(metrics.total || 0);
  if (avgHours !== null && avgHours !== undefined && Number(avgHours) > 120) {
    issues.push({ key: "avg_processing_hours", severity: "danger", label: "Average processing time over 120h" });
  } else if (avgHours !== null && avgHours !== undefined && Number(avgHours) > 72) {
    issues.push({ key: "avg_processing_hours", severity: "warning", label: "Average processing time over 72h" });
  }
  if (reopenRate > 25) {
    issues.push({ key: "reopen_rate", severity: "danger", label: "Reopen rate over 25%" });
  } else if (reopenRate > 10) {
    issues.push({ key: "reopen_rate", severity: "warning", label: "Reopen rate over 10%" });
  }
  if (delayedIncomplete >= 3) {
    issues.push({ key: "delayed_incomplete_items", severity: "danger", label: "3+ overdue incomplete re-reviews" });
  } else if (delayedIncomplete > 0) {
    issues.push({ key: "delayed_incomplete_items", severity: "warning", label: "Overdue incomplete re-reviews remain" });
  }
  if (activeLinkIssue >= 2 || activeLinkIssueRate > 25) {
    issues.push({ key: "active_link_issue", severity: "danger", label: "Active calibration linkage failed or unresolved" });
  } else if (activeLinkIssue > 0) {
    issues.push({ key: "active_link_issue", severity: "warning", label: "Active calibration linkage needs review" });
  }
  if (activeLinkFailed > 0) {
    issues.push({ key: "active_link_failed", severity: activeLinkFailed >= 2 ? "danger" : "warning", label: "Active calibration linkage failure logged" });
  }
  if (scope === "owner" && total >= 2 && completionRate < 50) {
    issues.push({ key: "owner_throughput", severity: "danger", label: "Owner completion rate below 50%" });
  } else if (scope === "owner" && total >= 2 && completionRate < 70) {
    issues.push({ key: "owner_throughput", severity: "warning", label: "Owner completion rate below 70%" });
  }
  const hasDanger = issues.some((item) => item.severity === "danger");
  const hasWarning = issues.some((item) => item.severity === "warning");
  const level = hasDanger ? "danger" : hasWarning ? "warning" : "normal";
  return {
    level,
    label: level === "danger" ? "Risk" : level === "warning" ? "Watch" : "Normal",
    grade: level === "danger" ? "위험" : level === "warning" ? "주의" : "정상",
    improvementItems: issues,
    criteria: {
      normal: "avgProcessingHours <= 72, reopenRate <= 10%, delayedIncompleteItems = 0, activeLinkIssue = 0, owner completion >= 70%",
      warning: "avgProcessingHours <= 120, reopenRate <= 25%, delayedIncompleteItems <= 2, activeLinkIssue <= 1",
      danger: "Any metric outside warning criteria"
    }
  };
}

function finalizeSlaPolicyCandidateQualityRereviewOperationalAggregate(row = {}, scope = "summary") {
  const completed = Number(row.completed || 0);
  const total = Number(row.total || 0);
  const activeLinkRequired = Number(row.activeLinkRequired || 0);
  const metrics = {
    ...row,
    avgProcessingHours: row.processingSamples ? Number((row.processingHoursTotal / row.processingSamples).toFixed(1)) : null,
    avgStatusTransitions: total ? Number((row.statusTransitionCount / total).toFixed(1)) : 0,
    completionRate: total ? Math.round((completed / total) * 100) : 0,
    reopenRate: total ? Math.round((Number(row.reopenedItems || 0) / total) * 100) : 0,
    delayedIncompleteRate: total ? Math.round((Number(row.delayedIncompleteItems || 0) / total) * 100) : 0,
    activeLinkUnprocessedRate: activeLinkRequired ? Math.round((Number(row.activeLinkUnprocessed || 0) / activeLinkRequired) * 100) : 0,
    activeLinkFailedRate: activeLinkRequired ? Math.round((Number(row.activeLinkFailed || 0) / activeLinkRequired) * 100) : 0,
    activeLinkIssueRate: activeLinkRequired ? Math.round((Number(row.activeLinkIssue || 0) / activeLinkRequired) * 100) : 0,
    maintainRate: completed ? Math.round((Number(row.maintained || 0) / completed) * 100) : 0,
    deactivateRate: completed ? Math.round((Number(row.deactivated || 0) / completed) * 100) : 0,
    modifiedProposalRate: completed ? Math.round((Number(row.modifiedProposed || 0) / completed) * 100) : 0
  };
  return {
    ...metrics,
    sla: slaPolicyCandidateQualityRereviewSlaEvaluation(metrics, scope)
  };
}

function slaPolicyCandidateQualityRereviewOperationalQuality(items = []) {
  const metrics = items.map((item) => item.operationalMetric || slaPolicyCandidateQualityRereviewOperationalMetric(item, []));
  const summary = finalizeSlaPolicyCandidateQualityRereviewOperationalAggregate(metrics.reduce(
    (row, metric) => addSlaPolicyCandidateQualityRereviewOperationalMetric(row, metric),
    emptySlaPolicyCandidateQualityRereviewOperationalAggregate("all", "All re-reviews")
  ), "summary");
  const monthMap = new Map();
  const ownerMap = new Map();
  metrics.forEach((metric) => {
    const month = metric.activityMonth || "unknown";
    monthMap.set(month, addSlaPolicyCandidateQualityRereviewOperationalMetric(
      monthMap.get(month) || emptySlaPolicyCandidateQualityRereviewOperationalAggregate(month, month),
      metric
    ));
    const owner = metric.owner || "unassigned";
    ownerMap.set(owner, addSlaPolicyCandidateQualityRereviewOperationalMetric(
      ownerMap.get(owner) || emptySlaPolicyCandidateQualityRereviewOperationalAggregate(owner, owner),
      metric
    ));
  });
  return {
    summary,
    monthly: [...monthMap.values()]
      .map((row) => finalizeSlaPolicyCandidateQualityRereviewOperationalAggregate(row, "month"))
      .sort((a, b) => String(b.key || "").localeCompare(String(a.key || ""))),
    ownerPerformance: [...ownerMap.values()]
      .map((row) => finalizeSlaPolicyCandidateQualityRereviewOperationalAggregate(row, "owner"))
      .sort((a, b) => Number(b.completed || 0) - Number(a.completed || 0) ||
        Number(a.avgProcessingHours ?? 999999) - Number(b.avgProcessingHours ?? 999999) ||
        String(a.label || "").localeCompare(String(b.label || ""))),
    itemMetrics: metrics
      .sort((a, b) => String(b.latestActivityAt || "").localeCompare(String(a.latestActivityAt || "")))
      .slice(0, 120),
    reportBoundaries: {
      source: "admin-only SLA quality calibration re-review audit log operational metrics",
      hiddenFromBusiness: ["re-review processing time", "operator throughput", "status transitions", "active calibration linkage outcomes", "reopen and follow-up ratios", "SLA warning levels"]
    }
  };
}

function slaPolicyCandidateQualityRereviewActionPriority(issue = {}) {
  if (issue.severity === "danger") {
    return ["active_link_unprocessed", "active_link_issue", "active_link_failed", "delayed_incomplete_items"].includes(issue.key) ? "urgent" : "high";
  }
  return issue.severity === "warning" ? "medium" : "low";
}

function slaPolicyCandidateQualityRereviewActionRecommendation(issue = {}, metrics = {}) {
  if (issue.key === "avg_processing_hours") {
    return "Split long-running re-review items by owner, set near-term due dates, and review blockers until average processing time returns to SLA.";
  }
  if (issue.key === "reopen_rate") {
    return "Review recently reopened re-reviews, tighten completion criteria, and add a second check before marking high-risk quality calibration reviews done.";
  }
  if (issue.key === "delayed_incomplete_items") {
    return `Resolve or reassign ${Number(metrics.delayedIncompleteItems || 0)} overdue open re-review item(s) and update due dates for deferred cases.`;
  }
  if (issue.key === "active_link_unprocessed" || issue.key === "active_link_issue") {
    return `Verify ${Number(metrics.activeLinkIssue || metrics.activeLinkUnprocessed || 0)} completed re-review item(s) whose active calibration linkage failed or has not been applied/logged.`;
  }
  if (issue.key === "active_link_failed") {
    return `Review ${Number(metrics.activeLinkFailed || 0)} active calibration linkage failure log(s), confirm the intended maintain/deactivate/modify result, and retry or roll back the failed linkage.`;
  }
  if (issue.key === "owner_throughput") {
    return "Rebalance the owner workload, assign backup reviewers, and convert stale candidate actions into planned work with target dates.";
  }
  return "Review the re-review SLA warning, identify the source metric, assign an owner, and set a concrete target date.";
}

function slaPolicyCandidateQualityRereviewActionRootMetric(issue = {}, metrics = {}) {
  if (issue.key === "avg_processing_hours") return `avgProcessingHours=${metrics.avgProcessingHours ?? "-"}`;
  if (issue.key === "reopen_rate") return `reopenRate=${metrics.reopenRate || 0}%`;
  if (issue.key === "delayed_incomplete_items") return `delayedIncompleteItems=${metrics.delayedIncompleteItems || 0}`;
  if (issue.key === "active_link_unprocessed") return `activeLinkUnprocessed=${metrics.activeLinkUnprocessed || 0}`;
  if (issue.key === "active_link_issue") return `activeLinkIssue=${metrics.activeLinkIssue || metrics.activeLinkUnprocessed || 0}`;
  if (issue.key === "active_link_failed") return `activeLinkFailed=${metrics.activeLinkFailed || 0}`;
  if (issue.key === "owner_throughput") return `completionRate=${metrics.completionRate || 0}%`;
  return issue.key || "re_review_sla";
}

function slaPolicyCandidateQualityRereviewActionSourceLabel(scopeType = "", metrics = {}) {
  if (scopeType === "month") return `Re-review month ${metrics.key || metrics.label || "-"}`;
  if (scopeType === "owner") return `Re-review owner ${metrics.key || metrics.label || "unassigned"}`;
  return "Re-review overall SLA";
}

function slaPolicyCandidateQualityRereviewActionSourceKey(scopeType = "", metrics = {}, issue = {}) {
  return [
    "rereview_sla",
    scopeType || "summary",
    metrics.key || metrics.month || metrics.owner || "",
    issue.key || "",
    issue.severity || ""
  ].join("|");
}

function slaPolicyCandidateQualityRereviewActionHistoryStats(items = []) {
  const total = items.length;
  const followUpNeeded = items.filter((item) => item.followUpNeeded).length;
  return {
    total,
    averageEffectScore: total
      ? Math.round(items.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / total)
      : 50,
    improvedRate: total ? Math.round((items.filter((item) => item.outcome === "improved").length / total) * 100) : 0,
    worseRate: total ? Math.round((items.filter((item) => item.outcome === "worse").length / total) * 100) : 0,
    recurrenceRate: total ? Math.round((items.filter((item) => item.recurrence).length / total) * 100) : 0,
    followUpNeededRate: total ? Math.round((followUpNeeded / total) * 100) : 0,
    followUpCreatedRate: followUpNeeded
      ? Math.round((items.filter((item) => item.followUpCreated).length / followUpNeeded) * 100)
      : 0
  };
}

function slaPolicyCandidateQualityRereviewActionHistoryWeightedScore(parts = []) {
  const active = parts.filter((part) => part.stats.total > 0 && part.weight > 0);
  if (!active.length) {
    return {
      score: 50,
      sampleSize: 0
    };
  }
  const weightTotal = active.reduce((sum, part) => sum + part.weight, 0);
  return {
    score: Math.round(active.reduce((sum, part) => sum + part.stats.averageEffectScore * part.weight, 0) / weightTotal),
    sampleSize: active.reduce((sum, part) => sum + part.stats.total, 0)
  };
}

function slaPolicyCandidateQualityRereviewActionHistoryIssueMatch(item = {}, action = {}) {
  const actionIssue = String(action.issueKey || "").trim();
  const actionRootMetric = String(action.rootMetric || "").trim();
  const itemKeys = [
    item.issueKey,
    item.rootMetric,
    item.metricKey,
    item.metricLabel
  ].map((value) => String(value || "").trim()).filter(Boolean);
  if (actionIssue && itemKeys.includes(actionIssue)) return true;
  if (actionRootMetric && itemKeys.includes(actionRootMetric)) return true;
  return Boolean(actionIssue && itemKeys.some((value) => value.toLowerCase().includes(actionIssue.toLowerCase())));
}

function slaPolicyCandidateQualityRereviewActionHistoryAdjustment(action = {}, historyItems = []) {
  const normalizedHistory = historyItems.map(normalizeSlaPolicyCandidateQualityRereviewActionReassessmentHistoryItem);
  const assignee = String(action.assignee || action.owner || "").trim().toLowerCase();
  const month = String(action.month || monthKey(action.targetDate) || "").trim();
  const issueItems = normalizedHistory.filter((item) => slaPolicyCandidateQualityRereviewActionHistoryIssueMatch(item, action));
  const assigneeItems = assignee
    ? normalizedHistory.filter((item) => String(item.assignee || item.owner || "").toLowerCase() === assignee)
    : [];
  const monthItems = month
    ? normalizedHistory.filter((item) => item.evaluatedMonth === month || monthKey(item.targetDate) === month)
    : [];
  const issueStats = slaPolicyCandidateQualityRereviewActionHistoryStats(issueItems);
  const assigneeStats = slaPolicyCandidateQualityRereviewActionHistoryStats(assigneeItems);
  const monthStats = slaPolicyCandidateQualityRereviewActionHistoryStats(monthItems);
  const weighted = slaPolicyCandidateQualityRereviewActionHistoryWeightedScore([
    { weight: 0.55, stats: issueStats },
    { weight: 0.25, stats: assigneeStats },
    { weight: 0.2, stats: monthStats }
  ]);
  const sampleSize = new Set([...issueItems, ...assigneeItems, ...monthItems].map((item) => item.historyId || item.reassessmentId || item.actionId)).size;
  let direction = "neutral";
  if (sampleSize > 0 && weighted.score >= 70 && issueStats.improvedRate >= 50 && issueStats.recurrenceRate <= 25 && issueStats.worseRate <= 25) {
    direction = "boost";
  } else if (sampleSize > 0 && (weighted.score < 45 || issueStats.recurrenceRate >= 50 || issueStats.worseRate >= 50 || issueStats.followUpNeededRate >= 75)) {
    direction = "downgrade";
  }
  const originalPriority = normalizeCalibrationSlaActionPriority(action.priority) || "medium";
  const adjustedPriority = shiftCalibrationSlaActionPriority(originalPriority, direction, action);
  const reasons = [];
  if (sampleSize > 0) {
    reasons.push(`Re-review action history score ${weighted.score} from ${sampleSize} reassessment row(s).`);
    if (issueStats.total) {
      reasons.push(`${action.issueKey || action.rootMetric || "same issue"} history: avg ${issueStats.averageEffectScore}, improved ${issueStats.improvedRate}%, worse ${issueStats.worseRate}%, recurrence ${issueStats.recurrenceRate}%.`);
    }
    if (assigneeStats.total) {
      reasons.push(`Assignee history: avg ${assigneeStats.averageEffectScore} across ${assigneeStats.total} row(s).`);
    }
    if (monthStats.total) {
      reasons.push(`Month history: avg ${monthStats.averageEffectScore} across ${monthStats.total} row(s).`);
    }
  } else {
    reasons.push("No re-review action reassessment history yet; base priority is unchanged.");
  }
  if (direction === "boost" && adjustedPriority !== originalPriority) {
    reasons.push(`Priority raised from ${originalPriority} to ${adjustedPriority}.`);
  } else if (direction === "downgrade" && adjustedPriority !== originalPriority) {
    reasons.push(`Priority lowered from ${originalPriority} to ${adjustedPriority}.`);
  } else if (direction !== "neutral") {
    reasons.push(`History suggests ${direction}, but the current SLA severity keeps priority at ${adjustedPriority}.`);
  }
  return {
    applied: sampleSize > 0,
    workflowStatus: sampleSize > 0 ? "active" : "none",
    activeApplied: sampleSize > 0 && direction !== "neutral" && adjustedPriority !== originalPriority,
    direction,
    historyEffectScore: weighted.score,
    sampleSize,
    originalPriority,
    adjustedPriority,
    issueStats,
    assigneeStats,
    monthStats,
    reasons,
    recommendationNote: reasons.join(" ")
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentId(sourceKey = "", adjustment = {}) {
  return hashId("spcqraadj", [
    sourceKey || "",
    adjustment.direction || "neutral",
    adjustment.historyEffectScore ?? "",
    adjustment.originalPriority || "",
    adjustment.adjustedPriority || ""
  ].join("|"));
}

const SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY = Object.freeze({
  policyVersion: "sla_rereview_action_rec_auto_approval_v1",
  enabled: true,
  minSampleSize: 3,
  maxPriorityStepChange: 1,
  minHistoricalApprovalSuccessRate: 70,
  issueRules: {},
  boost: {
    minEffectScore: 75,
    minImprovementRate: 60,
    maxRecurrenceRate: 20
  },
  downgrade: {
    maxEffectScore: 35,
    minRecurrenceRate: 60,
    maxImprovementRate: 40
  },
  impactScope: {
    low: ["owner"],
    medium: ["month"],
    high: ["summary"]
  }
});

function cloneSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policy = SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  return JSON.parse(JSON.stringify(policy));
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentId(candidate = {}) {
  return hashId("spcqraapa", [
    candidate.type || candidate.candidateType || "",
    candidate.target || "",
    candidate.issueKey || "",
    candidate.priority || "",
    candidate.basis || ""
  ].join("|"));
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy = {}, proposal = {}) {
  const issueRule = policy.issueRules?.[proposal.issueKey] || {};
  return {
    enabled: policy.enabled !== false && issueRule.autoApprovalEnabled !== false,
    minSampleSize: Number(issueRule.minSampleSize ?? policy.minSampleSize ?? 3),
    maxPriorityStepChange: Number(issueRule.maxPriorityStepChange ?? policy.maxPriorityStepChange ?? 1),
    minHistoricalApprovalSuccessRate: Number(issueRule.minHistoricalApprovalSuccessRate ?? policy.minHistoricalApprovalSuccessRate ?? 70),
    boost: {
      minEffectScore: Number(issueRule.boost?.minEffectScore ?? policy.boost?.minEffectScore ?? 75),
      minImprovementRate: Number(issueRule.boost?.minImprovementRate ?? policy.boost?.minImprovementRate ?? 60),
      maxRecurrenceRate: Number(issueRule.boost?.maxRecurrenceRate ?? policy.boost?.maxRecurrenceRate ?? 20)
    },
    downgrade: {
      maxEffectScore: Number(issueRule.downgrade?.maxEffectScore ?? policy.downgrade?.maxEffectScore ?? 35),
      minRecurrenceRate: Number(issueRule.downgrade?.minRecurrenceRate ?? policy.downgrade?.minRecurrenceRate ?? 60),
      maxImprovementRate: Number(issueRule.downgrade?.maxImprovementRate ?? policy.downgrade?.maxImprovementRate ?? 40)
    },
    issueRule
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicySnapshot(policy = {}, candidate = {}) {
  const issueKey = String(candidate.issueKey || candidate.target || "").trim();
  const issuePolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy, { issueKey });
  return {
    policyVersion: policy.policyVersion || SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY.policyVersion,
    issueKey,
    enabled: Boolean(policy.enabled !== false),
    issueAutoApprovalEnabled: issuePolicy.enabled,
    minSampleSize: issuePolicy.minSampleSize,
    maxPriorityStepChange: issuePolicy.maxPriorityStepChange,
    minHistoricalApprovalSuccessRate: issuePolicy.minHistoricalApprovalSuccessRate,
    boost: issuePolicy.boost,
    downgrade: issuePolicy.downgrade
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyPatchFromCandidate(candidate = {}, policy = SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  const issueKey = String(candidate.issueKey || candidate.target || "").trim();
  if (candidateType === "rollback_rereview_auto_policy_adjustment") {
    const sourceBefore = candidate.sourceBeforePolicy && typeof candidate.sourceBeforePolicy === "object" ? candidate.sourceBeforePolicy : {};
    const sourcePatch = candidate.sourcePolicyPatch && typeof candidate.sourcePolicyPatch === "object" ? candidate.sourcePolicyPatch : {};
    if (sourcePatch.global) {
      return {
        global: {
          minSampleSize: Math.max(2, Number(sourceBefore.minSampleSize || policy.minSampleSize || 3))
        }
      };
    }
    if (issueKey) {
      return {
        issueRules: {
          [issueKey]: {
            autoApprovalEnabled: sourceBefore.issueAutoApprovalEnabled !== false,
            minSampleSize: Math.max(2, Number(sourceBefore.minSampleSize || policy.minSampleSize || 3)),
            maxPriorityStepChange: Math.max(0, Number(sourceBefore.maxPriorityStepChange || policy.maxPriorityStepChange || 1)),
            minHistoricalApprovalSuccessRate: Math.max(0, Number(sourceBefore.minHistoricalApprovalSuccessRate || policy.minHistoricalApprovalSuccessRate || 70)),
            reason: candidate.recommendation || "Rollback candidate generated from weak post-change re-review auto-approval policy effectiveness."
          }
        }
      };
    }
  }
  if (candidateType === "partial_rereview_auto_policy_relaxation" && issueKey) {
    const issuePolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: true,
          minSampleSize: Math.max(2, Number(issuePolicy.minSampleSize || 3) - 1),
          minHistoricalApprovalSuccessRate: Math.max(60, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) - 3),
          reason: candidate.recommendation || "Partial relaxation candidate generated after stable re-review manual-review conversion."
        }
      }
    };
  }
  if (candidateType === "additional_rereview_tightening" && issueKey) {
    const issuePolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: false,
          minSampleSize: Math.max(Number(issuePolicy.minSampleSize || 3) + 1, Number(policy.minSampleSize || 3) + 1),
          minHistoricalApprovalSuccessRate: Math.min(95, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) + 5),
          reason: candidate.recommendation || "Additional tightening candidate generated from recurring post-change re-review policy failures."
        }
      }
    };
  }
  if (candidateType === "tighten_rereview_action_auto_policy" && issueKey) {
    const issuePolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: false,
          minSampleSize: Math.max(Number(issuePolicy.minSampleSize || 3) + 1, Number(policy.minSampleSize || 3) + 1),
          minHistoricalApprovalSuccessRate: Math.min(95, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) + 5),
          reason: candidate.recommendation || "Manual review required until re-review auto-approval outcomes improve."
        }
      }
    };
  }
  if (candidateType === "consider_relaxing_rereview_action_auto_policy" && issueKey) {
    const issuePolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy, { issueKey });
    return {
      issueRules: {
        [issueKey]: {
          autoApprovalEnabled: true,
          minSampleSize: Math.max(2, Number(issuePolicy.minSampleSize || 3) - 1),
          minHistoricalApprovalSuccessRate: Math.max(60, Number(issuePolicy.minHistoricalApprovalSuccessRate || 70) - 5),
          reason: candidate.recommendation || "Stable re-review action outcomes can carry a slightly lighter auto-approval threshold."
        }
      }
    };
  }
  if (candidateType === "increase_rereview_auto_approval_monitoring_window") {
    return {
      global: {
        minSampleSize: Math.max(3, Number(policy.minSampleSize || 3) + 1)
      }
    };
  }
  return {};
}

function applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyPatch(policy = {}, patch = {}) {
  const next = cloneSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policy);
  if (patch.global && typeof patch.global === "object") {
    Object.entries(patch.global).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== "") next[key] = value;
    });
  }
  if (patch.issueRules && typeof patch.issueRules === "object") {
    next.issueRules = {
      ...(next.issueRules || {})
    };
    Object.entries(patch.issueRules).forEach(([issueKey, rule]) => {
      next.issueRules[issueKey] = {
        ...(next.issueRules[issueKey] || {}),
        ...(rule || {})
      };
    });
  }
  return next;
}

function activeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policyAdjustments = []) {
  const approved = policyAdjustments
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment)
    .filter((item) => item.status === "approved")
    .sort((a, b) => String(a.approvedAt || a.updatedAt || "").localeCompare(String(b.approvedAt || b.updatedAt || "")));
  const policy = approved.reduce(
    (current, item) => applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyPatch(current, item.policyPatch || {}),
    cloneSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy()
  );
  return {
    ...policy,
    policyVersion: `${SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY.policyVersion}+${approved.length}`,
    activeAdjustmentIds: approved.map((item) => item.policyAdjustmentId)
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalExpectedImpact(candidate = {}) {
  const metrics = candidate.metrics || {};
  const currentSuccessRate = Number(metrics.successRate ?? 0);
  let expectedSuccessRate = currentSuccessRate;
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  if (candidateType === "rollback_rereview_auto_policy_adjustment") {
    expectedSuccessRate = Number(metrics.beforeSuccessRate ?? Math.max(currentSuccessRate, Number(metrics.successRateBefore || 0)));
  } else if (candidateType === "partial_rereview_auto_policy_relaxation") {
    expectedSuccessRate = Math.max(0, currentSuccessRate - 3);
  } else if (candidateType === "additional_rereview_tightening") {
    expectedSuccessRate = Math.min(100, currentSuccessRate + 10);
  } else if (candidateType === "tighten_rereview_action_auto_policy") {
    const riskPressure = Math.round((Number(metrics.falsePositiveRate || 0) + Number(metrics.rollbackRate || 0) + Number(metrics.recurrenceRate || 0)) / 6);
    expectedSuccessRate = Math.min(100, currentSuccessRate + Math.max(8, riskPressure));
  } else if (candidateType === "consider_relaxing_rereview_action_auto_policy") {
    expectedSuccessRate = Math.max(0, currentSuccessRate - 5);
  } else if (candidateType === "increase_rereview_auto_approval_monitoring_window") {
    expectedSuccessRate = Math.min(100, currentSuccessRate + 5);
  }
  return {
    scope: candidateType === "increase_rereview_auto_approval_monitoring_window" ? "global_policy" : "issue_policy",
    affectedTarget: String(candidate.target || candidate.issueKey || "").trim(),
    currentSuccessRate,
    expectedSuccessRate,
    expectedSuccessRateChange: expectedSuccessRate - currentSuccessRate,
    currentFalsePositiveRate: Number(metrics.falsePositiveRate || 0),
    currentRollbackRate: Number(metrics.rollbackRate || 0),
    currentRecurrenceRate: Number(metrics.recurrenceRate || 0),
    evaluated: Number(metrics.evaluated || 0),
    total: Number(metrics.total || 0),
    basis: candidate.basis || ""
  };
}

function normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment(input = {}) {
  const now = new Date().toISOString();
  const candidateType = String(input.candidateType || input.type || "policy_adjustment").trim();
  const target = String(input.target || input.issueKey || "").trim();
  const policyPatch = input.policyPatch && typeof input.policyPatch === "object"
    ? input.policyPatch
    : slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyPatchFromCandidate({ ...input, candidateType, target });
  return {
    policyAdjustmentId: String(input.policyAdjustmentId || slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentId({ ...input, candidateType, target })).trim(),
    candidateType,
    target,
    issueKey: String(input.issueKey || target).trim(),
    priority: normalizeCalibrationSlaActionPriority(input.priority || "medium"),
    basis: String(input.basis || "").trim(),
    recommendation: String(input.recommendation || "").trim(),
    status: normalizeSlaAutoApprovalPolicyAdjustmentStatus(input.status || "proposed"),
    policyPatch,
    beforePolicy: input.beforePolicy && typeof input.beforePolicy === "object" ? input.beforePolicy : {},
    afterPolicy: input.afterPolicy && typeof input.afterPolicy === "object" ? input.afterPolicy : {},
    expectedImpact: input.expectedImpact && typeof input.expectedImpact === "object"
      ? input.expectedImpact
      : slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalExpectedImpact(input),
    metrics: input.metrics && typeof input.metrics === "object" ? input.metrics : {},
    sourceContext: input.sourceContext && typeof input.sourceContext === "object" ? input.sourceContext : {},
    sourcePolicyAdjustmentId: String(input.sourcePolicyAdjustmentId || input.sourceContext?.policyAdjustmentId || "").trim(),
    sourceSuggestionType: String(input.sourceSuggestionType || input.sourceContext?.suggestionType || "").trim(),
    sourceEffectOutcome: String(input.sourceEffectOutcome || input.sourceContext?.outcome || "").trim(),
    sourceEffectScore: Number.isFinite(Number(input.sourceEffectScore ?? input.sourceContext?.effectScore)) ? Number(input.sourceEffectScore ?? input.sourceContext?.effectScore) : null,
    sourceBeforePolicy: input.sourceBeforePolicy && typeof input.sourceBeforePolicy === "object" ? input.sourceBeforePolicy : {},
    sourceAfterPolicy: input.sourceAfterPolicy && typeof input.sourceAfterPolicy === "object" ? input.sourceAfterPolicy : {},
    sourcePolicyPatch: input.sourcePolicyPatch && typeof input.sourcePolicyPatch === "object" ? input.sourcePolicyPatch : {},
    qualityLearningAdjustment: input.qualityLearningAdjustment && typeof input.qualityLearningAdjustment === "object"
      ? input.qualityLearningAdjustment
      : input.sourceContext?.qualityLearningAdjustment && typeof input.sourceContext.qualityLearningAdjustment === "object"
        ? input.sourceContext.qualityLearningAdjustment
        : {},
    duplicateStatus: String(input.duplicateStatus || "").trim(),
    duplicateOfPolicyAdjustmentId: String(input.duplicateOfPolicyAdjustmentId || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    reviewReason: String(input.reviewReason || "").trim(),
    approvedAt: input.approvedAt || "",
    rejectedAt: input.rejectedAt || "",
    updatedAt: input.updatedAt || input.reviewedAt || input.proposedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system"
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationImpactScope(proposal = {}, policy = SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const sourceType = String(proposal.sourceType || "summary").trim() || "summary";
  let level = "medium";
  if ((policy.impactScope?.low || []).includes(sourceType)) level = "low";
  if ((policy.impactScope?.high || []).includes(sourceType)) level = "high";
  const proposalPolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(policy, proposal);
  const priorityStepChange = slaActionRecommendationPriorityDistance(proposal.originalPriority, proposal.proposedPriority);
  if (priorityStepChange > proposalPolicy.maxPriorityStepChange) level = "high";
  return {
    sourceType,
    level,
    priorityStepChange,
    reason: level === "low"
      ? "Owner-scoped re-review action correction with limited operational blast radius."
      : level === "medium"
        ? "Month-scoped re-review action correction remains in manual review."
        : "Summary-level or large priority movement can affect broad re-review operations."
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationHistoricalApprovalStats(proposal = {}, existingItems = []) {
  const reviewed = existingItems
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment)
    .filter((item) => item.adjustmentId !== proposal.adjustmentId)
    .filter((item) => ["approved", "rejected"].includes(item.status))
    .filter((item) => item.issueKey === proposal.issueKey && item.direction === proposal.direction);
  const approved = reviewed.filter((item) => item.status === "approved").length;
  const rejected = reviewed.filter((item) => item.status === "rejected").length;
  const total = approved + rejected;
  return {
    reviewed: total,
    approved,
    rejected,
    successRate: total ? Math.round((approved / total) * 100) : 100,
    basis: total ? "same issue and direction re-review adjustment history" : "no prior conflict; default neutral success baseline"
  };
}

function evaluateSlaPolicyCandidateQualityRereviewActionRecommendationAutoApproval(
  proposal = {},
  existingItems = [],
  policy = SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY
) {
  const activePolicy = cloneSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policy);
  const proposalPolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyForProposal(activePolicy, proposal);
  const impact = slaPolicyCandidateQualityRereviewActionRecommendationImpactScope(proposal, activePolicy);
  const historicalApproval = slaPolicyCandidateQualityRereviewActionRecommendationHistoricalApprovalStats(proposal, existingItems);
  const sampleSize = Number(proposal.sampleSize || 0);
  const effectScore = Number(proposal.historyEffectScore || 0);
  const recurrenceRate = Number(proposal.recurrenceRate || 0);
  const improvementRate = Number(proposal.improvementRate || 0);
  const direction = String(proposal.direction || "neutral").trim();
  const criteria = {
    policyEnabled: proposalPolicy.enabled,
    sampleSizeOk: sampleSize >= proposalPolicy.minSampleSize,
    impactScopeOk: impact.level === "low",
    priorityStepOk: impact.priorityStepChange <= proposalPolicy.maxPriorityStepChange,
    historicalApprovalOk: historicalApproval.successRate >= proposalPolicy.minHistoricalApprovalSuccessRate,
    directionEvidenceOk: false
  };
  if (direction === "boost") {
    criteria.directionEvidenceOk = effectScore >= proposalPolicy.boost.minEffectScore &&
      improvementRate >= proposalPolicy.boost.minImprovementRate &&
      recurrenceRate <= proposalPolicy.boost.maxRecurrenceRate;
  } else if (direction === "downgrade") {
    criteria.directionEvidenceOk = (effectScore <= proposalPolicy.downgrade.maxEffectScore || recurrenceRate >= proposalPolicy.downgrade.minRecurrenceRate) &&
      improvementRate <= proposalPolicy.downgrade.maxImprovementRate;
  }
  const blockingReasons = [];
  if (!proposalPolicy.enabled) blockingReasons.push("Auto approval policy is disabled for this re-review issue.");
  if (!criteria.sampleSizeOk) blockingReasons.push(`Sample size ${sampleSize} is below ${proposalPolicy.minSampleSize}.`);
  if (!criteria.impactScopeOk) blockingReasons.push(`Impact scope is ${impact.level}, not low.`);
  if (!criteria.priorityStepOk) blockingReasons.push(`Priority movement is ${impact.priorityStepChange} step(s).`);
  if (!criteria.historicalApprovalOk) blockingReasons.push(`Historical approval success ${historicalApproval.successRate}% is below ${proposalPolicy.minHistoricalApprovalSuccessRate}%.`);
  if (!criteria.directionEvidenceOk) blockingReasons.push("Direction evidence is not strong enough for automatic approval.");
  let riskLevel = "low";
  if (blockingReasons.length) riskLevel = "medium";
  if (impact.level === "high" || sampleSize < 2 || historicalApproval.successRate < 50) riskLevel = "high";
  const eligible = proposalPolicy.enabled && riskLevel === "low" && Object.values(criteria).every(Boolean);
  const reasons = eligible
    ? [
        `Auto-approved by ${activePolicy.policyVersion}.`,
        `Samples ${sampleSize}, score ${effectScore}, improvement ${improvementRate}%, recurrence ${recurrenceRate}%.`,
        `Impact ${impact.level}, historical approval success ${historicalApproval.successRate}%.`
      ]
    : blockingReasons;
  return {
    policyVersion: activePolicy.policyVersion,
    evaluatedAt: new Date().toISOString(),
    eligible,
    riskLevel,
    criteria,
    thresholds: proposalPolicy,
    metrics: {
      sampleSize,
      effectScore,
      recurrenceRate,
      improvementRate,
      direction,
      originalPriority: proposal.originalPriority || "",
      proposedPriority: proposal.proposedPriority || ""
    },
    impact,
    historicalApproval,
    reasons
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLogId(adjustmentId = "", eventType = "", eventAt = "") {
  return hashId("spcqraal", [adjustmentId, eventType, eventAt].join("|"));
}

function normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog(input = {}) {
  const eventAt = input.eventAt || new Date().toISOString();
  const adjustmentId = String(input.adjustmentId || "").trim();
  const eventType = String(input.eventType || "auto_approved").trim();
  return {
    logId: String(input.logId || slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLogId(adjustmentId, eventType, eventAt)).trim(),
    adjustmentId,
    sourceKey: String(input.sourceKey || "").trim(),
    eventType,
    eventAt,
    eventBy: String(input.eventBy || "system_auto").trim() || "system_auto",
    previousStatus: String(input.previousStatus || "").trim(),
    nextStatus: String(input.nextStatus || "").trim(),
    rollbackAvailable: Boolean(input.rollbackAvailable),
    rolledBack: Boolean(input.rolledBack),
    policyDecision: input.policyDecision && typeof input.policyDecision === "object" ? input.policyDecision : {},
    reason: String(input.reason || "").trim()
  };
}

async function appendSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog(entry = {}) {
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLogs();
  const normalized = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog(entry);
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog)
    : [];
  if (items.some((item) => item.adjustmentId === normalized.adjustmentId && item.eventType === normalized.eventType && item.nextStatus === normalized.nextStatus)) {
    return {
      log: normalized,
      data
    };
  }
  const updated = await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLogs({
    ...data,
    items: [normalized, ...items].sort((a, b) => String(b.eventAt || "").localeCompare(String(a.eventAt || "")))
  });
  return {
    log: normalized,
    data: updated
  };
}

function normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment(input = {}) {
  const now = new Date().toISOString();
  const sourceKey = String(input.sourceKey || "").trim();
  const adjustment = input.adjustment && typeof input.adjustment === "object" ? input.adjustment : {};
  const proposedPriority = normalizeCalibrationSlaActionPriority(input.proposedPriority || adjustment.adjustedPriority || input.originalPriority || adjustment.originalPriority || "medium") || "medium";
  const originalPriority = normalizeCalibrationSlaActionPriority(input.originalPriority || adjustment.originalPriority || proposedPriority) || proposedPriority;
  const statusValue = normalizeSlaActionRecommendationAdjustmentStatus(input.status);
  const approvedAt = input.approvedAt || (statusValue === "approved" ? now : "");
  const rejectedAt = input.rejectedAt || (statusValue === "rejected" ? now : "");
  const activePriority = normalizeCalibrationSlaActionPriority(input.activePriority || (statusValue === "approved" ? proposedPriority : ""));
  const historyEffectScore = Math.max(0, Math.min(100, Math.round(Number(input.historyEffectScore ?? adjustment.historyEffectScore ?? 50))));
  const recurrenceRate = Math.max(0, Math.min(100, Math.round(Number(input.recurrenceRate ?? adjustment.issueStats?.recurrenceRate ?? 0))));
  const improvementRate = Math.max(0, Math.min(100, Math.round(Number(input.improvementRate ?? adjustment.issueStats?.improvedRate ?? 0))));
  const worseRate = Math.max(0, Math.min(100, Math.round(Number(input.worseRate ?? adjustment.issueStats?.worseRate ?? 0))));
  const followUpNeededRate = Math.max(0, Math.min(100, Math.round(Number(input.followUpNeededRate ?? adjustment.issueStats?.followUpNeededRate ?? 0))));
  const sampleSize = Math.max(0, Math.round(Number(input.sampleSize ?? adjustment.sampleSize ?? 0)));
  const manualApprovalRequired = Boolean(input.manualApprovalRequired);
  const autoApprovalSuppressed = Boolean(input.autoApprovalSuppressed);
  const workflowType = String(input.workflowType || (manualApprovalRequired ? "manual_review" : "auto_policy")).trim();
  const recommendationBefore = String(input.recommendationBefore || "").trim();
  const recommendationAfter = String(input.recommendationAfter || "").trim();
  const impactComparison = input.impactComparison && typeof input.impactComparison === "object"
    ? input.impactComparison
    : {
        priorityBefore: originalPriority,
        proposedPriority,
        activePriority: activePriority || "",
        priorityAfterApproval: proposedPriority,
        priorityIfRejected: originalPriority,
        recommendationBefore,
        recommendationAfter,
        historyEffectScore,
        recurrenceRate,
        improvementRate,
        worseRate,
        followUpNeededRate,
        sampleSize
      };
  const decisionHistory = Array.isArray(input.decisionHistory)
    ? input.decisionHistory
    : [];
  if (["approved", "rejected"].includes(statusValue) && (input.reviewedAt || approvedAt || rejectedAt)) {
    const decisionAt = input.reviewedAt || approvedAt || rejectedAt || now;
    const decisionKey = `${statusValue}|${decisionAt}|${input.reviewedBy || ""}`;
    if (!decisionHistory.some((item) => `${item.decision || item.status || ""}|${item.decidedAt || item.reviewedAt || ""}|${item.decidedBy || item.reviewedBy || ""}` === decisionKey)) {
      decisionHistory.unshift({
        decision: statusValue,
        decidedAt: decisionAt,
        decidedBy: String(input.reviewedBy || "").trim(),
        reviewReason: String(input.reviewReason || "").trim(),
        priorityBefore: originalPriority,
        priorityAfter: statusValue === "approved" ? proposedPriority : originalPriority,
        historyEffectScore,
        recurrenceRate
      });
    }
  }
  return {
    adjustmentId: String(input.adjustmentId || slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentId(sourceKey, adjustment)).trim(),
    sourceKey,
    actionId: String(input.actionId || "").trim(),
    sourceType: String(input.sourceType || "summary").trim() || "summary",
    sourceLabel: String(input.sourceLabel || "").trim(),
    month: String(input.month || "").trim(),
    owner: String(input.owner || "").trim(),
    issueKey: String(input.issueKey || "").trim(),
    rootMetric: String(input.rootMetric || "").trim(),
    originalPriority,
    proposedPriority,
    activePriority,
    direction: String(input.direction || adjustment.direction || "neutral").trim(),
    historyEffectScore,
    recurrenceRate,
    improvementRate,
    worseRate,
    followUpNeededRate,
    sampleSize,
    recommendationBefore,
    recommendationAfter,
    reason: String(input.reason || adjustment.recommendationNote || "").trim(),
    adjustment,
    workflowType,
    manualApprovalRequired,
    autoApprovalSuppressed,
    impactComparison,
    decisionHistory: decisionHistory.slice(0, 20),
    status: statusValue,
    approvalMode: normalizeSlaActionRecommendationApprovalMode(input.approvalMode || (statusValue === "approved" && String(input.reviewedBy || "").startsWith("system_auto") ? "auto" : statusValue === "approved" || statusValue === "rejected" ? "manual" : "none")),
    autoApprovalPolicy: input.autoApprovalPolicy && typeof input.autoApprovalPolicy === "object" ? input.autoApprovalPolicy : null,
    rollbackAvailable: Boolean(input.rollbackAvailable),
    rolledBackAt: input.rolledBackAt || "",
    rolledBackBy: String(input.rolledBackBy || "").trim(),
    rollbackReason: String(input.rollbackReason || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || approvedAt || rejectedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    reviewReason: String(input.reviewReason || "").trim(),
    approvedAt,
    rejectedAt,
    updatedAt: input.updatedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system"
  };
}

function activeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustmentForAction(action = {}, adjustments = []) {
  const sourceKey = action.sourceKey || "";
  return adjustments
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment)
    .filter((item) => item.status === "approved" && item.sourceKey === sourceKey)
    .sort((a, b) => String(b.approvedAt || b.updatedAt || "").localeCompare(String(a.approvedAt || a.updatedAt || "")))[0] || null;
}

function existingSlaPolicyCandidateQualityRereviewActionRecommendationAdjustmentForAction(action = {}, adjustments = [], calculated = {}) {
  const sourceKey = action.sourceKey || "";
  const calculatedId = slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentId(sourceKey, calculated);
  return adjustments
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment)
    .find((item) => item.adjustmentId === calculatedId || (item.sourceKey === sourceKey && item.direction === calculated.direction && item.proposedPriority === calculated.adjustedPriority));
}

async function upsertSlaPolicyCandidateQualityRereviewActionRecommendationAdjustmentProposal(action = {}, adjustment = {}) {
  if (!adjustment.applied || adjustment.direction === "neutral") return null;
  const [data, policyAdjustmentData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments()
  ]);
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment)
    : [];
  const activePolicy = activeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policyAdjustmentData.items || []);
  const baseProposal = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment({
    sourceKey: action.sourceKey || "",
    actionId: action.actionId || "",
    sourceType: action.sourceType || "summary",
    sourceLabel: action.sourceLabel || "",
    month: action.month || "",
    owner: action.owner || action.assignee || "",
    issueKey: action.issueKey || "",
    rootMetric: action.rootMetric || "",
    originalPriority: adjustment.originalPriority,
    proposedPriority: adjustment.adjustedPriority,
    direction: adjustment.direction,
    historyEffectScore: adjustment.historyEffectScore,
    recurrenceRate: adjustment.issueStats?.recurrenceRate || 0,
    improvementRate: adjustment.issueStats?.improvedRate || 0,
    worseRate: adjustment.issueStats?.worseRate || 0,
    followUpNeededRate: adjustment.issueStats?.followUpNeededRate || 0,
    sampleSize: adjustment.sampleSize,
    recommendationBefore: action.recommendation || "",
    recommendationAfter: [action.recommendation || "", `History adjustment: ${adjustment.recommendationNote}`].filter(Boolean).join(" "),
    reason: adjustment.recommendationNote,
    adjustment,
    status: "proposed",
    proposedBy: "system"
  });
  const activeSame = existingItems.find((item) => item.status === "approved" && item.sourceKey === baseProposal.sourceKey);
  const reviewedSame = existingItems.find((item) => item.adjustmentId === baseProposal.adjustmentId && ["approved", "rejected"].includes(item.status));
  if (activeSame || reviewedSame) return reviewedSame || activeSame;
  const byId = new Map(existingItems.map((item) => [item.adjustmentId, item]));
  const existingProposal = byId.get(baseProposal.adjustmentId) || null;
  const proposal = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment({
    ...(existingProposal || {}),
    ...baseProposal,
    proposedAt: existingProposal?.proposedAt || baseProposal.proposedAt,
    proposedBy: existingProposal?.proposedBy || baseProposal.proposedBy
  });
  const policyDecision = evaluateSlaPolicyCandidateQualityRereviewActionRecommendationAutoApproval(proposal, existingItems, activePolicy);
  const finalProposal = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment(policyDecision.eligible
    ? {
        ...proposal,
        status: "approved",
        activePriority: proposal.proposedPriority,
        approvalMode: "auto",
        autoApprovalPolicy: policyDecision,
        rollbackAvailable: true,
        reviewedAt: policyDecision.evaluatedAt,
        reviewedBy: "system_auto",
        reviewReason: policyDecision.reasons.join(" "),
        approvedAt: policyDecision.evaluatedAt,
        updatedAt: policyDecision.evaluatedAt,
        updatedBy: "system_auto"
      }
    : {
        ...proposal,
        status: "proposed",
        approvalMode: "none",
        autoApprovalPolicy: policyDecision,
        rollbackAvailable: false,
        updatedAt: policyDecision.evaluatedAt,
        updatedBy: "system"
      });
  byId.set(finalProposal.adjustmentId, finalProposal);
  await writeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  if (finalProposal.status === "approved" && finalProposal.approvalMode === "auto" && existingProposal?.status !== "approved") {
    await appendSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog({
      adjustmentId: finalProposal.adjustmentId,
      sourceKey: finalProposal.sourceKey,
      eventType: "auto_approved",
      eventAt: finalProposal.approvedAt || finalProposal.reviewedAt,
      eventBy: "system_auto",
      previousStatus: existingProposal?.status || "proposed",
      nextStatus: "approved",
      rollbackAvailable: true,
      policyDecision,
      reason: finalProposal.reviewReason
    });
  }
  return finalProposal;
}

function applyApprovedSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment(action = {}, approved = null, calculated = {}) {
  if (!approved || approved.status !== "approved") {
    return {
      ...action,
      historyAdjustment: {
        ...calculated,
        workflowStatus: calculated.applied ? "proposed" : "none",
        activeApplied: false,
        proposedAdjustmentId: approved?.adjustmentId || ""
      }
    };
  }
  return normalizeSlaPolicyCandidateQualityRereviewSlaAction({
    ...action,
    priority: approved.activePriority || approved.proposedPriority || action.priority,
    recommendation: [
      action.recommendation || "",
      `Approved history adjustment: ${approved.reason || calculated.recommendationNote || ""}`
    ].filter(Boolean).join(" "),
    historyAdjustment: {
      ...calculated,
      workflowStatus: "approved",
      activeApplied: true,
      adjustmentId: approved.adjustmentId,
      approvedAt: approved.approvedAt || approved.reviewedAt || "",
      approvedBy: approved.reviewedBy || ""
    }
  });
}

async function applySlaPolicyCandidateQualityRereviewActionHistoryAdjustment(action = {}, historyItems = [], adjustmentItems = []) {
  const adjustment = slaPolicyCandidateQualityRereviewActionHistoryAdjustment(action, historyItems);
  if (!adjustment.applied) {
    return {
      ...action,
      historyAdjustment: adjustment
    };
  }
  const active = activeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustmentForAction(action, adjustmentItems);
  const existing = active || existingSlaPolicyCandidateQualityRereviewActionRecommendationAdjustmentForAction(action, adjustmentItems, adjustment);
  const proposal = existing || await upsertSlaPolicyCandidateQualityRereviewActionRecommendationAdjustmentProposal(action, adjustment);
  const activeAdjustment = active || (proposal?.status === "approved" ? proposal : null);
  const result = applyApprovedSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment(action, activeAdjustment, adjustment);
  if (result.historyAdjustment && !result.historyAdjustment.activeApplied) {
    result.historyAdjustment = {
      ...result.historyAdjustment,
      workflowStatus: proposal?.status || "proposed",
      proposedAdjustmentId: proposal?.adjustmentId || "",
      proposedPriority: adjustment.adjustedPriority
    };
  }
  return result;
}

function filterSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments(items = [], payload = {}) {
  const status = normalizeSlaActionRecommendationAdjustmentStatus(payload.status || "");
  const rawStatus = String(payload.status || "").trim();
  const direction = String(payload.direction || "").trim().toLowerCase();
  const owner = String(payload.owner || payload.assignee || "").trim().toLowerCase();
  const issue = String(payload.issueKey || payload.rootMetric || "").trim().toLowerCase();
  return items
    .filter((item) => !rawStatus || item.status === status)
    .filter((item) => !direction || item.direction === direction)
    .filter((item) => !owner || String(item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !issue || [item.issueKey, item.rootMetric, item.sourceLabel, item.reason].some((value) => String(value || "").toLowerCase().includes(issue)));
}

function slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentSummary(items = []) {
  const total = items.length;
  return {
    total,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    autoApproved: items.filter((item) => item.status === "approved" && item.approvalMode === "auto").length,
    manualRequired: items.filter((item) => item.status === "proposed").length,
    rollbackAvailable: items.filter((item) => item.rollbackAvailable && item.status === "approved").length,
    boost: items.filter((item) => item.direction === "boost").length,
    downgrade: items.filter((item) => item.direction === "downgrade").length,
    averageEffectScore: total
      ? Math.round(items.reduce((sum, item) => sum + Number(item.historyEffectScore || 0), 0) / total)
      : 0,
    averageRecurrenceRate: total
      ? Math.round(items.reduce((sum, item) => sum + Number(item.recurrenceRate || 0), 0) / total)
      : 0
  };
}

async function slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentsReport(payload = {}) {
  const [data, logData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLogs()
  ]);
  const allItems = (data.items || []).map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment);
  const autoApprovalLogs = (logData.items || []).map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog);
  const filtered = filterSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments(allItems, payload);
  const filteredIds = new Set(filtered.map((item) => item.adjustmentId));
  const limit = Math.max(1, Math.min(300, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_adjustments",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      direction: String(payload.direction || "").trim(),
      owner: String(payload.owner || payload.assignee || "").trim(),
      issue: String(payload.issueKey || payload.rootMetric || "").trim(),
      limit
    },
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionRecommendationAdjustmentSummary(allItems),
    autoApprovalPolicy: cloneSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(),
    autoApprovalLogs: autoApprovalLogs
      .filter((log) => !filteredIds.size || filteredIds.has(log.adjustmentId))
      .slice(0, 80),
    items: filtered
      .sort((a, b) => {
        const statusRank = { proposed: 0, approved: 1, rejected: 2 };
        return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
          String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
      })
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA quality re-review action recommendation adjustment proposals and review decisions",
      hiddenFromBusiness: ["re-review recommendation adjustment proposals", "approval history", "auto-approval policy", "auto-approval logs", "effect scores", "recurrence evidence", "priority calibration reasons"]
    }
  };
}

async function reviewSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment(payload = {}) {
  const adjustmentId = String(payload.adjustmentId || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  if (!adjustmentId || !["approved", "rejected"].includes(decision)) {
    const error = new Error("Adjustment id and approved/rejected decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment)
    : [];
  const target = items.find((item) => item.adjustmentId === adjustmentId);
  if (!target) {
    const error = new Error("SLA quality re-review action recommendation adjustment proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const updatedTarget = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment({
    ...target,
    status: decision,
    activePriority: decision === "approved" ? target.proposedPriority : "",
    approvalMode: "manual",
    rollbackAvailable: false,
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason: String(payload.reviewReason || payload.reason || "").trim(),
    approvedAt: decision === "approved" ? now : "",
    rejectedAt: decision === "rejected" ? now : "",
    updatedAt: now,
    updatedBy: reviewer
  });
  const updatedItems = items.map((item) => {
    if (item.adjustmentId === adjustmentId) return updatedTarget;
    if (decision === "approved" && item.sourceKey === target.sourceKey && item.status === "approved") {
      return normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment({
        ...item,
        status: "rejected",
        activePriority: "",
        rollbackAvailable: false,
        reviewedAt: now,
        reviewedBy: reviewer,
        reviewReason: `Superseded by approved re-review action adjustment ${adjustmentId}.`,
        rejectedAt: now,
        updatedAt: now,
        updatedBy: reviewer
      });
    }
    return item;
  });
  const updated = await writeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_adjustment_review",
    generatedAt: now,
    adjustment: updatedTarget,
    slaPolicyCandidateQualityRereviewActionRecommendationAdjustments: {
      schema: updated.schema || "sla_policy_candidate_quality_rereview_action_recommendation_adjustments_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    reportBoundaries: {
      source: "admin-only review decision for SLA quality re-review action recommendation adjustment",
      hiddenFromBusiness: ["approval decision", "review reason", "priority calibration evidence", "effect scores"]
    }
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLinkedHistory(adjustment = {}, historyItems = []) {
  const approvedAt = adjustment.approvedAt || adjustment.reviewedAt || adjustment.updatedAt || "";
  const approvedTime = new Date(approvedAt).getTime();
  const owner = String(adjustment.owner || "").trim().toLowerCase();
  const issueKey = String(adjustment.issueKey || "").trim();
  return historyItems
    .map(normalizeSlaPolicyCandidateQualityRereviewActionReassessmentHistoryItem)
    .filter((item) => {
      const evaluatedTime = new Date(item.evaluatedAt || item.recordedAt || "").getTime();
      const afterApproval = !Number.isFinite(approvedTime) || !Number.isFinite(evaluatedTime) || evaluatedTime >= approvedTime;
      const sameSource = item.sourceKey && item.sourceKey === adjustment.sourceKey;
      const sameIssue = issueKey && item.issueKey === issueKey;
      const sameOwner = !owner || String(item.assignee || item.owner || "").toLowerCase() === owner;
      return afterApproval && (sameSource || (sameIssue && sameOwner));
    })
    .sort((a, b) => String(b.evaluatedAt || "").localeCompare(String(a.evaluatedAt || "")));
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPerformanceOutcome(adjustment = {}, linkedHistory = [], logs = []) {
  const rolledBack = Boolean(adjustment.rolledBackAt || logs.some((log) => log.adjustmentId === adjustment.adjustmentId && log.eventType === "rollback"));
  const evaluatedCount = linkedHistory.length;
  const avgEffectScore = evaluatedCount ? Math.round(linkedHistory.reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / evaluatedCount) : 0;
  const improved = linkedHistory.filter((item) => item.outcome === "improved").length;
  const worse = linkedHistory.filter((item) => item.outcome === "worse").length;
  const recurrence = linkedHistory.filter((item) => item.recurrence).length;
  const followUpNeeded = linkedHistory.filter((item) => item.followUpNeeded).length;
  const improvedRate = evaluatedCount ? Math.round((improved / evaluatedCount) * 100) : 0;
  const worseRate = evaluatedCount ? Math.round((worse / evaluatedCount) * 100) : 0;
  const recurrenceRate = evaluatedCount ? Math.round((recurrence / evaluatedCount) * 100) : 0;
  const followUpNeededRate = evaluatedCount ? Math.round((followUpNeeded / evaluatedCount) * 100) : 0;
  const falsePositive = evaluatedCount > 0 && (worseRate >= 50 || recurrenceRate >= 50 || avgEffectScore < 45 || followUpNeededRate >= 50);
  const successful = evaluatedCount > 0 && !falsePositive && avgEffectScore >= 60 && improvedRate >= 50 && recurrenceRate < 50;
  let outcome = "pending";
  if (rolledBack) outcome = "rolled_back";
  else if (falsePositive) outcome = "false_positive";
  else if (successful) outcome = "successful";
  else if (evaluatedCount > 0) outcome = "mixed";
  return {
    outcome,
    evaluatedCount,
    avgEffectScore,
    improved,
    improvedRate,
    worse,
    worseRate,
    recurrence,
    recurrenceRate,
    followUpNeeded,
    followUpNeededRate,
    falsePositive,
    successful,
    rolledBack
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPerformanceItem(adjustment = {}, historyItems = [], autoApprovalLogs = []) {
  const logs = autoApprovalLogs.filter((log) => log.adjustmentId === adjustment.adjustmentId);
  const linkedHistory = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLinkedHistory(adjustment, historyItems);
  const outcome = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPerformanceOutcome(adjustment, linkedHistory, logs);
  return {
    adjustmentId: adjustment.adjustmentId,
    sourceKey: adjustment.sourceKey,
    sourceType: adjustment.sourceType,
    sourceLabel: adjustment.sourceLabel,
    approvalMonth: monthKey(adjustment.approvedAt || adjustment.reviewedAt || adjustment.updatedAt || adjustment.proposedAt),
    approvedAt: adjustment.approvedAt || adjustment.reviewedAt || "",
    owner: adjustment.owner || "",
    issueKey: adjustment.issueKey || "",
    rootMetric: adjustment.rootMetric || "",
    direction: adjustment.direction || "",
    originalPriority: adjustment.originalPriority || "",
    proposedPriority: adjustment.proposedPriority || "",
    activePriority: adjustment.activePriority || "",
    policyRiskLevel: adjustment.autoApprovalPolicy?.riskLevel || "",
    policyVersion: adjustment.autoApprovalPolicy?.policyVersion || "",
    rollbackAvailable: Boolean(adjustment.rollbackAvailable),
    rolledBackAt: adjustment.rolledBackAt || "",
    rolledBackBy: adjustment.rolledBackBy || "",
    outcome,
    linkedHistory: linkedHistory.slice(0, 6).map((item) => ({
      historyId: item.historyId,
      evaluatedAt: item.evaluatedAt,
      evaluatedMonth: item.evaluatedMonth,
      effectScore: item.effectScore,
      evaluationState: item.outcome,
      recurrence: item.recurrence,
      followUpNeeded: item.followUpNeeded
    })),
    logCount: logs.length
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyCandidates(items = [], aggregates = {}) {
  const candidates = [];
  const riskyIssues = (aggregates.byIssue || []).filter((row) => row.evaluated >= 1 && (row.falsePositiveRate >= 40 || row.recurrenceRate >= 50 || row.rollbackRate >= 30));
  riskyIssues.slice(0, 6).forEach((row) => {
    candidates.push({
      candidateId: hashId("spcqraapc", ["tighten", row.key || row.label || "", row.falsePositiveRate, row.rollbackRate, row.recurrenceRate].join("|")),
      type: "tighten_rereview_action_auto_policy",
      priority: row.falsePositiveRate >= 50 || row.rollbackRate >= 40 ? "high" : "medium",
      target: row.label,
      issueKey: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `False positive ${row.falsePositiveRate}%, recurrence ${row.recurrenceRate}%, rollback ${row.rollbackRate}% across ${row.evaluated} evaluated re-review auto approvals.`,
      recommendation: "Keep this re-review issue in manual review or raise sample/effect thresholds before automatic approval."
    });
  });
  const strongIssues = (aggregates.byIssue || []).filter((row) => row.evaluated >= 3 && row.successRate >= 80 && row.falsePositiveRate === 0 && row.rollbackRate === 0);
  strongIssues.slice(0, 4).forEach((row) => {
    candidates.push({
      candidateId: hashId("spcqraapc", ["relax", row.key || row.label || "", row.successRate, row.evaluated].join("|")),
      type: "consider_relaxing_rereview_action_auto_policy",
      priority: "low",
      target: row.label,
      issueKey: row.key || row.label,
      metrics: {
        total: row.total,
        evaluated: row.evaluated,
        successRate: row.successRate,
        falsePositiveRate: row.falsePositiveRate,
        rollbackRate: row.rollbackRate,
        recurrenceRate: row.recurrenceRate,
        avgEffectScore: row.avgEffectScore
      },
      basis: `Success ${row.successRate}% with no false positives or rollbacks across ${row.evaluated} evaluated re-review auto approvals.`,
      recommendation: "Consider keeping owner-scoped re-review action corrections auto-approved while broad scopes stay manual."
    });
  });
  const pendingRate = items.length ? Math.round((items.filter((item) => item.outcome?.outcome === "pending").length / items.length) * 100) : 0;
  if (pendingRate >= 60 && items.length >= 3) {
    const summary = slaAutoApprovalPerformanceSummary(items);
    candidates.push({
      candidateId: hashId("spcqraapc", ["monitoring", pendingRate, items.length].join("|")),
      type: "increase_rereview_auto_approval_monitoring_window",
      priority: "medium",
      target: "pending_rereview_auto_approval_followup",
      issueKey: "pending_rereview_auto_approval_followup",
      metrics: {
        total: items.length,
        evaluated: items.filter((item) => item.outcome?.evaluatedCount > 0).length,
        successRate: summary.successRate,
        falsePositiveRate: summary.falsePositiveRate,
        rollbackRate: summary.rollbackRate,
        recurrenceRate: summary.recurrenceRate,
        pendingRate
      },
      basis: `${pendingRate}% of re-review auto approvals still have no linked post-assessment evidence.`,
      recommendation: "Require post-assessment capture before widening re-review auto-approval coverage."
    });
  }
  return candidates;
}

function buildSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentProposal(
  candidate = {},
  policy = SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY,
  existing = null
) {
  const candidateType = String(candidate.candidateType || candidate.type || "policy_adjustment").trim();
  const target = String(candidate.target || candidate.issueKey || "").trim();
  const policyPatch = candidate.policyPatch && typeof candidate.policyPatch === "object"
    ? candidate.policyPatch
    : slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyPatchFromCandidate({ ...candidate, candidateType, target }, policy);
  const beforePolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicySnapshot(policy, { ...candidate, candidateType, target });
  const afterPolicy = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicySnapshot(
    applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyPatch(policy, policyPatch),
    { ...candidate, candidateType, target }
  );
  return normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment({
    ...(existing || {}),
    ...candidate,
    candidateType,
    target,
    issueKey: candidate.issueKey || target,
    policyPatch,
    beforePolicy,
    afterPolicy,
    expectedImpact: candidate.expectedImpact && typeof candidate.expectedImpact === "object"
      ? candidate.expectedImpact
      : slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalExpectedImpact({ ...candidate, candidateType, target }),
    status: existing?.status || "proposed",
    proposedAt: existing?.proposedAt || new Date().toISOString(),
    proposedBy: existing?.proposedBy || "system",
    updatedAt: existing?.updatedAt || new Date().toISOString(),
    updatedBy: existing?.updatedBy || "system"
  });
}

async function upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentProposals(candidates = [], activePolicy = SLA_POLICY_CANDIDATE_QUALITY_REREVIEW_ACTION_RECOMMENDATION_AUTO_APPROVAL_POLICY) {
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments();
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment)
    : [];
  const byId = new Map(existingItems.map((item) => [item.policyAdjustmentId, item]));
  const proposals = [];
  candidates.forEach((candidate) => {
    const candidateId = String(candidate.policyAdjustmentId || slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentId(candidate)).trim();
    const existing = byId.get(candidateId) || null;
    if (existing && ["approved", "rejected"].includes(existing.status)) {
      proposals.push(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment({
        ...existing,
        duplicateStatus: `existing_${existing.status}`,
        duplicateOfPolicyAdjustmentId: existing.policyAdjustmentId
      }));
      return;
    }
    const proposal = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment({
      ...buildSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentProposal(candidate, activePolicy, existing),
      duplicateStatus: existing ? "existing_proposed" : "created",
      duplicateOfPolicyAdjustmentId: existing?.policyAdjustmentId || ""
    });
    byId.set(proposal.policyAdjustmentId, proposal);
    proposals.push(proposal);
  });
  const sorted = [...byId.values()].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, rejected: 2 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
  });
  await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments({
    ...data,
    items: sorted
  });
  return proposals;
}

function filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments(items = [], payload = {}) {
  const status = normalizeSlaAutoApprovalPolicyAdjustmentStatus(payload.status || "");
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  return items
    .filter((item) => !payload.status || item.status === status)
    .filter((item) => !target || String(item.target || item.issueKey || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type);
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentSummary(items = []) {
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    high: items.filter((item) => item.priority === "high").length,
    medium: items.filter((item) => item.priority === "medium").length,
    low: items.filter((item) => item.priority === "low").length,
    expectedSuccessRateChangeAvg: items.length
      ? Math.round(items.reduce((sum, item) => sum + Number(item.expectedImpact?.expectedSuccessRateChange || 0), 0) / items.length)
      : 0
  };
}

async function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentsReport(payload = {}) {
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments();
  const allItems = (data.items || []).map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment);
  const activePolicy = activeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(allItems);
  const filtered = filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments(allItems, payload);
  const sorted = [...filtered].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, rejected: 2 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.reviewedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.reviewedAt || a.proposedAt || ""));
  });
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_adjustments",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      target: String(payload.target || payload.issueKey || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      limit
    },
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentSummary(allItems),
    activePolicy,
    items: sorted.slice(0, limit),
    approvalHistory: allItems
      .filter((item) => ["approved", "rejected"].includes(item.status))
      .sort((a, b) => String(b.reviewedAt || b.updatedAt || "").localeCompare(String(a.reviewedAt || a.updatedAt || "")))
      .slice(0, 80),
    reportBoundaries: {
      source: "admin-only SLA quality re-review action recommendation auto approval policy adjustment workflow",
      hiddenFromBusiness: ["re-review auto approval policy thresholds", "policy adjustment proposals", "approval history", "expected policy impact"]
    }
  };
}

async function reviewSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment(payload = {}) {
  const policyAdjustmentId = String(payload.policyAdjustmentId || payload.adjustmentId || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  if (!policyAdjustmentId || !["approved", "rejected"].includes(decision)) {
    const error = new Error("Policy adjustment id and approved/rejected decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment)
    : [];
  const target = items.find((item) => item.policyAdjustmentId === policyAdjustmentId);
  if (!target) {
    const error = new Error("SLA quality re-review action auto-approval policy adjustment proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const updatedTarget = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment({
    ...target,
    status: decision,
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason: String(payload.reviewReason || payload.reason || "").trim(),
    approvedAt: decision === "approved" ? now : "",
    rejectedAt: decision === "rejected" ? now : "",
    updatedAt: now,
    updatedBy: reviewer
  });
  const updatedItems = items.map((item) => item.policyAdjustmentId === policyAdjustmentId ? updatedTarget : item);
  const updated = await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_adjustment_review",
    generatedAt: now,
    item: updatedTarget,
    activePolicy: activeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(updatedItems),
    slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments: {
      schema: updated.schema || "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_adjustments_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    reportBoundaries: {
      source: "admin-only review decision for SLA quality re-review action auto-approval policy adjustment",
      hiddenFromBusiness: ["policy adjustment approval decision", "review reason", "policy thresholds", "expected impact"]
    }
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectScopeMatcher(policyAdjustment = {}) {
  const target = String(policyAdjustment.issueKey || policyAdjustment.target || "").trim();
  const candidateType = String(policyAdjustment.candidateType || "").trim();
  const globalScope = !target ||
    candidateType === "increase_rereview_auto_approval_monitoring_window" ||
    target === "pending_rereview_auto_approval_followup";
  return (item = {}) => {
    if (globalScope) return true;
    const issueKey = String(item.issueKey || "").trim();
    const rootMetric = String(item.rootMetric || "").trim();
    const itemTarget = String(item.target || "").trim();
    return issueKey === target || rootMetric === target || itemTarget === target;
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectSuggestions(policyAdjustment = {}, before = {}, after = {}, delta = {}, outcome = "pending") {
  const suggestions = [];
  if (outcome === "pending") {
    suggestions.push({
      type: "collect_more_rereview_auto_policy_evidence",
      priority: "medium",
      label: "Collect more re-review policy evidence",
      reason: "There is not enough post-change re-review auto-approval outcome data to judge this policy adjustment.",
      recommendation: "Keep this policy change visible in the admin review queue until enough follow-up reassessment rows are linked."
    });
  }
  if (outcome === "worse" || Number(after.falsePositiveRate || 0) >= 50 || Number(after.rollbackRate || 0) >= 30) {
    suggestions.push({
      type: "rollback_rereview_auto_policy_adjustment",
      priority: "high",
      label: "Review rollback of this re-review auto policy",
      reason: `Post-change false positive ${after.falsePositiveRate || 0}%, rollback ${after.rollbackRate || 0}%, recurrence ${after.recurrenceRate || 0}%.`,
      recommendation: "Prepare rollback or stricter thresholds before this policy adjustment continues to influence re-review action auto approvals."
    });
  }
  if (
    policyAdjustment.candidateType === "tighten_rereview_action_auto_policy" &&
    Number(after.manualReviewConversionRate || 0) >= 80 &&
    Number(after.falsePositiveRate || 0) <= Number(before.falsePositiveRate || 0)
  ) {
    suggestions.push({
      type: "consider_rereview_partial_relaxation",
      priority: "medium",
      label: "Consider partial relaxation after stable manual review",
      reason: `Manual-review conversion reached ${after.manualReviewConversionRate || 0}% while false positives did not worsen.`,
      recommendation: "Keep broad auto approval blocked, but consider owner-scoped or higher-sample relaxation if the next window stays stable."
    });
  }
  if (Number(after.recurrenceRate || 0) > Number(before.recurrenceRate || 0) && Number(after.recurrenceRate || 0) >= 40) {
    suggestions.push({
      type: "additional_rereview_tightening",
      priority: "high",
      label: "Add recurrence-focused re-review tightening",
      reason: `Recurrence rose by ${delta.recurrenceRate || 0}p after this policy adjustment.`,
      recommendation: "Raise sample or effect-score thresholds for this re-review issue before future auto approvals."
    });
  }
  if (!suggestions.length) {
    suggestions.push({
      type: "maintain_rereview_auto_policy_adjustment",
      priority: "low",
      label: "Maintain and keep monitoring",
      reason: "Post-change re-review metrics do not require rollback or additional tightening yet.",
      recommendation: "Keep the policy adjustment active and continue tracking the next reassessment window."
    });
  }
  return suggestions;
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectSuggestionCandidateType(suggestionType = "") {
  const type = String(suggestionType || "").trim();
  if (type === "rollback_rereview_auto_policy_adjustment") return "rollback_rereview_auto_policy_adjustment";
  if (type === "consider_rereview_partial_relaxation") return "partial_rereview_auto_policy_relaxation";
  if (type === "additional_rereview_tightening") return "additional_rereview_tightening";
  return "";
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectGeneratedCandidateId(effectItem = {}, suggestion = {}) {
  return hashId("spcqraape", [
    effectItem.policyAdjustmentId || "",
    suggestion.type || "",
    effectItem.issueKey || effectItem.target || ""
  ].join("|"));
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityBasis(qualityReport = {}, candidateType = "") {
  const row = (qualityReport.byType || []).find((item) => item.candidateType === candidateType) || {};
  const total = Number(row.total || 0);
  const rejected = Number(row.rejected || 0);
  const repeatRecommended = Number(row.repeatRecommended || 0);
  const topRejection = row.rejectionReasons?.[0] || null;
  return {
    candidateType,
    total,
    proposed: Number(row.proposed || 0),
    approved: Number(row.approved || 0),
    rejected,
    evaluated: Number(row.evaluated || 0),
    successful: Number(row.successful || 0),
    failed: Number(row.failed || 0),
    approvalRate: Number(row.approvalRate || 0),
    approvalSuccessRate: Number(row.approvalSuccessRate || 0),
    repeatRecommended,
    repeatRecommendationRate: Number(row.repeatRecommendationRate || (total ? Math.round((repeatRecommended / total) * 100) : 0)),
    rejectionRate: total ? Math.round((rejected / total) * 100) : 0,
    topRejectionReason: topRejection?.reason || "",
    topRejectionCount: Number(topRejection?.count || 0),
    rejectionReasons: (row.rejectionReasons || []).slice(0, 3)
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearning(candidate = {}, qualityReport = {}) {
  const candidateType = String(candidate.candidateType || candidate.type || "").trim();
  const previousQuality = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityBasis(qualityReport, candidateType);
  const priorityBefore = normalizeCalibrationSlaActionPriority(candidate.priority || "medium") || "medium";
  const strongHistory = previousQuality.evaluated >= 2 &&
    previousQuality.approvalSuccessRate >= 70 &&
    previousQuality.repeatRecommendationRate <= 25 &&
    previousQuality.rejectionRate <= 40;
  const weakHistory = (previousQuality.evaluated >= 1 && previousQuality.approvalSuccessRate <= 40) ||
    previousQuality.repeatRecommendationRate >= 50 ||
    (previousQuality.rejected >= 2 && previousQuality.approvalRate <= 40);
  const direction = strongHistory ? "boost" : weakHistory ? "downgrade" : "neutral";
  const priorityAfter = shiftCalibrationSlaActionPriority(priorityBefore, direction);
  const applied = direction !== "neutral" && priorityAfter !== priorityBefore;
  let reason = "No prior effect-based candidate quality history; base priority is retained.";
  if (previousQuality.total > 0 && direction === "boost") {
    reason = `Previous ${candidateType} candidates show ${previousQuality.approvalSuccessRate}% approved-success across ${previousQuality.evaluated} evaluated item(s), ${previousQuality.repeatRecommendationRate}% repeat recommendation, and ${previousQuality.rejectionRate}% rejection; priority ${priorityBefore} -> ${priorityAfter}.`;
  } else if (previousQuality.total > 0 && direction === "downgrade") {
    reason = `Previous ${candidateType} candidates show ${previousQuality.approvalSuccessRate}% approved-success, ${previousQuality.repeatRecommendationRate}% repeat recommendation, and ${previousQuality.rejectionRate}% rejection${previousQuality.topRejectionReason ? `; top rejection reason: ${previousQuality.topRejectionReason}` : ""}; priority ${priorityBefore} -> ${priorityAfter}.`;
  } else if (previousQuality.total > 0) {
    reason = `Previous ${candidateType} candidate quality is mixed: approved-success ${previousQuality.approvalSuccessRate}%, repeat ${previousQuality.repeatRecommendationRate}%, rejection ${previousQuality.rejectionRate}%; priority remains ${priorityBefore}.`;
  }
  return {
    applied,
    direction,
    candidateType,
    priorityBefore,
    priorityAfter,
    reason,
    previousQuality
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningCalibrationId(candidate = {}) {
  return hashId("spcqraapql", [
    candidate.candidateType || candidate.type || "",
    "effect_candidate_quality_learning"
  ].join("|"));
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningSimulation(candidate = {}, suggested = {}, active = null) {
  const priorityBefore = normalizeCalibrationSlaActionPriority(candidate.priority || suggested.priorityBefore || "medium") || "medium";
  const suggestedPriorityAfter = normalizeCalibrationSlaActionPriority(suggested.priorityAfter || priorityBefore) || priorityBefore;
  const activePriorityAfter = active
    ? normalizeCalibrationSlaActionPriority(active.priorityAfter || suggestedPriorityAfter) || suggestedPriorityAfter
    : priorityBefore;
  const recommendationBefore = String(candidate.recommendation || "").trim();
  const suggestedRecommendationAfter = [recommendationBefore, `Quality learning proposal: ${suggested.reason || ""}`].filter(Boolean).join(" ");
  const activeRecommendationAfter = active
    ? [recommendationBefore, `Approved quality learning: ${active.reason || suggested.reason || ""}`].filter(Boolean).join(" ")
    : recommendationBefore;
  return {
    priorityBefore,
    suggestedPriorityAfter,
    activePriorityAfter,
    recommendationBefore,
    suggestedRecommendationAfter,
    activeRecommendationAfter,
    expectedImpactBefore: candidate.expectedImpact || {},
    expectedImpactAfter: {
      ...(candidate.expectedImpact || {}),
      priorityBefore,
      suggestedPriorityAfter,
      activePriorityAfter,
      learningApplied: Boolean(active),
      learningBasis: active?.reason || suggested.reason || "",
      previousQuality: suggested.previousQuality || {}
    }
  };
}

function normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration(input = {}) {
  const now = new Date().toISOString();
  const suggested = input.suggestedLearning && typeof input.suggestedLearning === "object"
    ? input.suggestedLearning
    : input.qualityLearningAdjustment?.suggestedLearning && typeof input.qualityLearningAdjustment.suggestedLearning === "object"
      ? input.qualityLearningAdjustment.suggestedLearning
      : input.qualityLearningAdjustment && typeof input.qualityLearningAdjustment === "object"
        ? input.qualityLearningAdjustment
        : {};
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(input.status || "proposed");
  const activeLearning = input.activeLearning && typeof input.activeLearning === "object"
    ? input.activeLearning
    : slaPolicyCandidateQualityCalibrationActive({ status })
      ? suggested
      : null;
  return {
    calibrationId: String(input.calibrationId || slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningCalibrationId(input)).trim(),
    candidateType: String(input.candidateType || input.type || suggested.candidateType || "").trim(),
    target: String(input.target || input.issueKey || "").trim(),
    issueKey: String(input.issueKey || input.target || "").trim(),
    status,
    active: slaPolicyCandidateQualityCalibrationActive({ status }),
    suggestedLearning: suggested,
    activeLearning,
    simulation: input.simulation && typeof input.simulation === "object" ? input.simulation : {},
    previousQuality: input.previousQuality && typeof input.previousQuality === "object" ? input.previousQuality : suggested.previousQuality || {},
    reviewReason: String(input.reviewReason || input.reason || "").trim(),
    overrideReason: String(input.overrideReason || "").trim(),
    proposedAt: input.proposedAt || now,
    proposedBy: String(input.proposedBy || "system").trim() || "system",
    reviewedAt: input.reviewedAt || "",
    reviewedBy: String(input.reviewedBy || "").trim(),
    updatedAt: input.updatedAt || input.reviewedAt || input.proposedAt || now,
    updatedBy: String(input.updatedBy || input.reviewedBy || input.proposedBy || "system").trim() || "system",
    events: Array.isArray(input.events) ? input.events.map(slaPolicyCandidateQualityCalibrationEvent) : []
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationMap(items = []) {
  return new Map(items
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration)
    .map((item) => [item.calibrationId, item]));
}

function applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearning(candidate = {}, qualityReport = {}, workflowItems = []) {
  const calibrationId = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningCalibrationId(candidate);
  const suggestedLearning = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearning(candidate, qualityReport);
  const workflowItem = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationMap(workflowItems).get(calibrationId) || null;
  const activeWorkflow = workflowItem && slaPolicyCandidateQualityCalibrationActive(workflowItem) ? workflowItem : null;
  const activeLearning = activeWorkflow?.activeLearning || null;
  const priorityAfter = activeLearning?.priorityAfter || suggestedLearning.priorityBefore;
  const learningText = activeLearning ? `Approved quality learning: ${activeLearning.reason || suggestedLearning.reason}` : "";
  const simulation = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningSimulation(candidate, suggestedLearning, activeLearning);
  const qualityLearningAdjustment = {
    calibrationId,
    status: workflowItem?.status || (suggestedLearning.previousQuality?.total ? "proposed" : "none"),
    active: Boolean(activeLearning),
    applied: Boolean(activeLearning && priorityAfter !== suggestedLearning.priorityBefore),
    direction: activeLearning?.direction || suggestedLearning.direction,
    candidateType: suggestedLearning.candidateType,
    priorityBefore: suggestedLearning.priorityBefore,
    priorityAfter,
    suggestedPriorityAfter: suggestedLearning.priorityAfter,
    reason: activeLearning?.reason || suggestedLearning.reason,
    reviewReason: workflowItem?.reviewReason || "",
    overrideReason: workflowItem?.overrideReason || "",
    previousQuality: suggestedLearning.previousQuality,
    suggestedLearning,
    activeLearning,
    simulation,
    reviewedAt: workflowItem?.reviewedAt || "",
    reviewedBy: workflowItem?.reviewedBy || ""
  };
  return {
    ...candidate,
    priority: priorityAfter,
    basis: [candidate.basis, learningText].filter(Boolean).join(" "),
    recommendation: [candidate.recommendation, learningText].filter(Boolean).join(" "),
    qualityLearningAdjustment,
    sourceContext: {
      ...(candidate.sourceContext || {}),
      qualityLearningAdjustment
    }
  };
}

function shouldStoreSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration(candidate = {}) {
  const learning = candidate.qualityLearningAdjustment || {};
  const suggested = learning.suggestedLearning || learning;
  return Boolean(suggested?.previousQuality?.total || suggested?.direction !== "neutral");
}

function buildSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationProposal(candidate = {}, existing = null) {
  const learning = candidate.qualityLearningAdjustment || {};
  const suggested = learning.suggestedLearning || learning;
  const existingNormalized = existing ? normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration(existing) : null;
  const status = existingNormalized?.status || "proposed";
  const activeLearning = slaPolicyCandidateQualityCalibrationActive({ status })
    ? existingNormalized?.activeLearning || suggested
    : null;
  const creationEvent = slaPolicyCandidateQualityCalibrationEvent({
    calibrationId: learning.calibrationId || slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningCalibrationId(candidate),
    eventType: existingNormalized ? "refreshed" : "proposed",
    previousStatus: existingNormalized?.status || "",
    nextStatus: status,
    reason: "Re-review effect candidate quality learning proposal generated."
  });
  return normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration({
    ...(existing || {}),
    calibrationId: learning.calibrationId || slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningCalibrationId(candidate),
    candidateType: candidate.candidateType,
    target: candidate.target,
    issueKey: candidate.issueKey,
    status,
    suggestedLearning: suggested,
    activeLearning,
    simulation: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningSimulation(candidate, suggested, activeLearning),
    previousQuality: suggested.previousQuality || {},
    reviewReason: existingNormalized?.reviewReason || "",
    overrideReason: existingNormalized?.overrideReason || "",
    proposedAt: existingNormalized?.proposedAt || new Date().toISOString(),
    proposedBy: existingNormalized?.proposedBy || "system",
    updatedAt: new Date().toISOString(),
    updatedBy: "system",
    events: existingNormalized?.events?.length ? existingNormalized.events : [creationEvent]
  });
}

async function upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationProposals(candidates = []) {
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations();
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration)
    : [];
  const byId = new Map(existingItems.map((item) => [item.calibrationId, item]));
  candidates
    .filter(shouldStoreSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration)
    .forEach((candidate) => {
      const calibrationId = candidate.qualityLearningAdjustment?.calibrationId ||
        slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningCalibrationId(candidate);
      const proposal = buildSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationProposal(candidate, byId.get(calibrationId) || null);
      byId.set(calibrationId, proposal);
    });
  const sorted = [...byId.values()].sort((a, b) => {
    const statusRank = { proposed: 0, approved: 1, overridden: 2, rejected: 3, deactivated: 4 };
    return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
      String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || ""));
  });
  await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations({
    ...data,
    items: sorted
  });
  return sorted;
}

function filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations(items = [], payload = {}) {
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(payload.status || "");
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  return items
    .filter((item) => !payload.status || item.status === status)
    .filter((item) => !type || item.candidateType === type);
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationSummary(items = []) {
  return {
    total: items.length,
    proposed: items.filter((item) => item.status === "proposed").length,
    approved: items.filter((item) => item.status === "approved").length,
    overridden: items.filter((item) => item.status === "overridden").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    active: items.filter((item) => slaPolicyCandidateQualityCalibrationActive(item)).length,
    boost: items.filter((item) => (item.suggestedLearning || {}).direction === "boost").length,
    downgrade: items.filter((item) => (item.suggestedLearning || {}).direction === "downgrade").length
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationWorkflowReport(items = [], payload = {}) {
  const normalized = items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration);
  const filtered = filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations(normalized, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_effect_quality_calibrations",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      limit
    },
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationSummary(normalized),
    items: filtered
      .sort((a, b) => {
        const statusRank = { proposed: 0, approved: 1, overridden: 2, rejected: 3, deactivated: 4 };
        return (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9) ||
          String(b.updatedAt || b.reviewedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.reviewedAt || a.proposedAt || ""));
      })
      .slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA quality re-review effect candidate quality learning calibration workflow",
      hiddenFromBusiness: ["quality learning proposals", "approval status", "override reasons", "candidate quality history", "operator review events"]
    }
  };
}

async function reviewSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration(payload = {}) {
  const calibrationId = String(payload.calibrationId || payload.id || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  const status = decision === "override" ? "overridden" : normalizeSlaPolicyCandidateQualityCalibrationStatus(decision);
  if (!calibrationId || !["approved", "rejected", "overridden"].includes(status)) {
    const error = new Error("Quality learning calibration id and approved/rejected/override decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration)
    : [];
  const target = items.find((item) => item.calibrationId === calibrationId);
  if (!target) {
    const error = new Error("SLA quality re-review effect candidate quality learning calibration proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reviewReason = String(payload.reviewReason || payload.reason || "").trim();
  const overrideReason = String(payload.overrideReason || "").trim();
  const suggested = target.suggestedLearning || {};
  let activeLearning = null;
  if (status === "approved") {
    activeLearning = {
      ...suggested,
      applied: suggested.direction !== "neutral" && suggested.priorityAfter !== suggested.priorityBefore,
      reason: reviewReason || suggested.reason || "Admin approved suggested re-review effect candidate quality learning."
    };
  } else if (status === "overridden") {
    const priorityBefore = normalizeCalibrationSlaActionPriority(suggested.priorityBefore || "medium") || "medium";
    const overridePriorityAfter = normalizeCalibrationSlaActionPriority(payload.overridePriorityAfter || payload.priorityAfter || suggested.priorityAfter || priorityBefore) || priorityBefore;
    const beforeRank = calibrationSlaActionPriorityRank(priorityBefore);
    const afterRank = calibrationSlaActionPriorityRank(overridePriorityAfter);
    activeLearning = {
      ...suggested,
      direction: afterRank < beforeRank ? "boost" : afterRank > beforeRank ? "downgrade" : "neutral",
      priorityAfter: overridePriorityAfter,
      applied: overridePriorityAfter !== priorityBefore,
      reason: overrideReason || reviewReason || `Admin override set active quality learning priority ${priorityBefore} -> ${overridePriorityAfter}.`
    };
  }
  const simulationCandidate = {
    priority: suggested.priorityBefore,
    recommendation: target.simulation?.recommendationBefore || "",
    expectedImpact: target.simulation?.expectedImpactBefore || {}
  };
  const updatedTarget = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration({
    ...target,
    status,
    activeLearning,
    simulation: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearningSimulation(
      simulationCandidate,
      suggested,
      activeLearning
    ),
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason,
    overrideReason,
    updatedAt: now,
    updatedBy: reviewer,
    events: [
      slaPolicyCandidateQualityCalibrationEvent({
        calibrationId,
        eventType: status,
        eventAt: now,
        eventBy: reviewer,
        previousStatus: target.status,
        nextStatus: status,
        reason: reviewReason,
        overridePriorityAfter: activeLearning?.priorityAfter || "",
        overrideReason
      }),
      ...(target.events || [])
    ]
  });
  const updatedItems = items.map((item) => item.calibrationId === calibrationId ? updatedTarget : item);
  await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    ok: true,
    item: updatedTarget,
    workflow: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationWorkflowReport(updatedItems, {}),
    reportBoundaries: {
      source: "admin-only SLA quality re-review effect candidate quality learning calibration review decision",
      hiddenFromBusiness: ["quality learning approval status", "override reason", "candidate quality evidence", "review events"]
    }
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectAdjustmentCandidates(effectItems = [], qualityReport = {}, workflowItems = []) {
  const candidates = [];
  effectItems.forEach((effectItem) => {
    (effectItem.suggestions || []).forEach((suggestion) => {
      const candidateType = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectSuggestionCandidateType(suggestion.type);
      if (!candidateType) return;
      const metrics = slaPolicyEffectCandidateMetrics(effectItem);
      const candidate = {
        policyAdjustmentId: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectGeneratedCandidateId(effectItem, suggestion),
        type: candidateType,
        candidateType,
        target: effectItem.target || effectItem.issueKey || "",
        issueKey: effectItem.issueKey || effectItem.target || "",
        priority: suggestion.priority || (candidateType === "rollback_rereview_auto_policy_adjustment" || candidateType === "additional_rereview_tightening" ? "high" : "medium"),
        basis: [
          `Generated from post-change re-review auto policy effectiveness of ${effectItem.policyAdjustmentId}.`,
          `Outcome ${effectItem.outcome}, effect score ${effectItem.effectScore ?? "pending"}.`,
          `Success ${effectItem.before?.successRate || 0}% -> ${effectItem.after?.successRate || 0}%, false positive ${effectItem.before?.falsePositiveRate || 0}% -> ${effectItem.after?.falsePositiveRate || 0}%, rollback ${effectItem.before?.rollbackRate || 0}% -> ${effectItem.after?.rollbackRate || 0}%, recurrence ${effectItem.before?.recurrenceRate || 0}% -> ${effectItem.after?.recurrenceRate || 0}%.`,
          suggestion.reason || ""
        ].filter(Boolean).join(" "),
        recommendation: suggestion.recommendation || (suggestion.label ? `${suggestion.label}: ${suggestion.reason || ""}` : suggestion.reason || ""),
        metrics,
        expectedImpact: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalExpectedImpact({
          candidateType,
          target: effectItem.target || effectItem.issueKey || "",
          issueKey: effectItem.issueKey || effectItem.target || "",
          metrics,
          basis: suggestion.reason || ""
        }),
        sourcePolicyAdjustmentId: effectItem.policyAdjustmentId,
        sourceSuggestionType: suggestion.type,
        sourceEffectOutcome: effectItem.outcome,
        sourceEffectScore: effectItem.effectScore,
        sourceBeforePolicy: effectItem.sourceBeforePolicy || {},
        sourceAfterPolicy: effectItem.sourceAfterPolicy || {},
        sourcePolicyPatch: effectItem.sourcePolicyPatch || {},
        sourceContext: {
          source: "sla_rereview_auto_policy_effectiveness",
          policyAdjustmentId: effectItem.policyAdjustmentId,
          suggestionType: suggestion.type,
          outcome: effectItem.outcome,
          effectScore: effectItem.effectScore,
          windowDays: effectItem.windowDays,
          beforeWindow: effectItem.beforeWindow,
          afterWindow: effectItem.afterWindow
        }
      };
      candidates.push(applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityLearning(candidate, qualityReport, workflowItems));
    });
  });
  return candidates;
}

function attachSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectGeneratedProposals(effectItems = [], candidates = [], proposals = []) {
  const candidateByKey = new Map(candidates.map((candidate) => [
    [candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "", candidate.sourceContext?.suggestionType || ""].join("|"),
    candidate
  ]));
  const proposalById = new Map(proposals.map((proposal) => [proposal.policyAdjustmentId, proposal]));
  return effectItems.map((effectItem) => ({
    ...effectItem,
    suggestions: (effectItem.suggestions || []).map((suggestion) => {
      const candidate = candidateByKey.get([effectItem.policyAdjustmentId || "", suggestion.type || ""].join("|"));
      if (!candidate) return suggestion;
      const proposal = proposalById.get(candidate.policyAdjustmentId) || null;
      return {
        ...suggestion,
        generatedCandidateType: candidate.candidateType,
        generatedProposal: {
          policyAdjustmentId: candidate.policyAdjustmentId,
          status: proposal?.status || "proposed",
          duplicateStatus: proposal?.duplicateStatus || "created",
          duplicateOfPolicyAdjustmentId: proposal?.duplicateOfPolicyAdjustmentId || "",
          priority: proposal?.priority || candidate.priority,
          target: proposal?.target || candidate.target
        }
      };
    })
  }));
}

function isSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectGeneratedAdjustment(item = {}) {
  return item.sourceContext?.source === "sla_rereview_auto_policy_effectiveness" ||
    ["rollback_rereview_auto_policy_adjustment", "additional_rereview_tightening", "partial_rereview_auto_policy_relaxation"].includes(item.candidateType);
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityOutcome(candidate = {}, postEffect = null) {
  if (candidate.status === "rejected") return "rejected";
  if (candidate.status !== "approved") return "pending_review";
  if (!postEffect || postEffect.outcome === "pending") return "pending_effect";
  if (postEffect.outcome === "improved") return "successful";
  if (postEffect.outcome === "worse") return "failed";
  return "neutral";
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityRepeat(candidate = {}, postEffect = null) {
  const postSuggestionTypes = (postEffect?.suggestions || [])
    .map((suggestion) => slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectSuggestionCandidateType(suggestion.type))
    .filter(Boolean);
  const sameTypeSuggested = postSuggestionTypes.includes(candidate.candidateType);
  const rejectedHighRisk = candidate.status === "rejected" &&
    ["worse", "pending"].includes(candidate.sourceEffectOutcome) &&
    ["high", "urgent"].includes(candidate.priority);
  const failedApproved = candidate.status === "approved" && postEffect?.outcome === "worse";
  return {
    repeatRecommended: Boolean(sameTypeSuggested || rejectedHighRisk || failedApproved),
    reason: sameTypeSuggested
      ? "Post-approval re-review effect generated the same candidate type again."
      : rejectedHighRisk
        ? "Rejected high-risk re-review effect still indicates weak policy performance."
        : failedApproved
          ? "Approved re-review effect candidate produced worse post-change effectiveness."
          : ""
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityItem(candidate = {}, effectByPolicyId = new Map()) {
  const postEffect = effectByPolicyId.get(candidate.policyAdjustmentId) || null;
  const repeat = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityRepeat(candidate, postEffect);
  const outcome = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityOutcome(candidate, postEffect);
  return {
    policyAdjustmentId: candidate.policyAdjustmentId,
    candidateType: candidate.candidateType,
    target: candidate.target,
    issueKey: candidate.issueKey,
    priority: candidate.priority,
    status: candidate.status,
    sourcePolicyAdjustmentId: candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "",
    sourceSuggestionType: candidate.sourceSuggestionType || candidate.sourceContext?.suggestionType || "",
    sourceEffectOutcome: candidate.sourceEffectOutcome || candidate.sourceContext?.outcome || "",
    sourceEffectScore: candidate.sourceEffectScore,
    proposedAt: candidate.proposedAt,
    reviewedAt: candidate.reviewedAt,
    reviewedBy: candidate.reviewedBy,
    reviewReason: candidate.reviewReason,
    postEffectOutcome: postEffect?.outcome || "",
    postEffectScore: postEffect?.effectScore ?? null,
    postEffectDelta: postEffect?.delta || {},
    qualityOutcome: outcome,
    successful: outcome === "successful",
    evaluated: ["successful", "failed", "neutral"].includes(outcome),
    repeatRecommended: repeat.repeatRecommended,
    repeatRecommendationReason: repeat.reason
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityGroup(items = [], candidateType = "all") {
  const total = items.length;
  const approved = items.filter((item) => item.status === "approved").length;
  const rejected = items.filter((item) => item.status === "rejected").length;
  const proposed = items.filter((item) => item.status === "proposed").length;
  const evaluated = items.filter((item) => item.evaluated).length;
  const successful = items.filter((item) => item.successful).length;
  const failed = items.filter((item) => item.qualityOutcome === "failed").length;
  const repeatRecommended = items.filter((item) => item.repeatRecommended).length;
  const rejectionReasonMap = new Map();
  items
    .filter((item) => item.status === "rejected")
    .forEach((item) => {
      const reason = item.reviewReason || "No rejection reason recorded.";
      rejectionReasonMap.set(reason, (rejectionReasonMap.get(reason) || 0) + 1);
    });
  return {
    candidateType,
    total,
    proposed,
    approved,
    rejected,
    evaluated,
    successful,
    failed,
    repeatRecommended,
    approvalRate: approved + rejected ? Math.round((approved / (approved + rejected)) * 100) : 0,
    approvalSuccessRate: evaluated ? Math.round((successful / evaluated) * 100) : 0,
    repeatRecommendationRate: total ? Math.round((repeatRecommended / total) * 100) : 0,
    rejectionReasons: [...rejectionReasonMap.entries()]
      .map(([reason, count]) => ({ reason, count }))
      .sort((a, b) => b.count - a.count || String(a.reason).localeCompare(String(b.reason)))
      .slice(0, 8)
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityReport(policyAdjustments = [], effectItems = [], payload = {}) {
  const effectByPolicyId = new Map(effectItems.map((item) => [item.policyAdjustmentId, item]));
  const allItems = policyAdjustments
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment)
    .filter(isSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectGeneratedAdjustment)
    .map((item) => slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityItem(item, effectByPolicyId));
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  const filtered = allItems
    .filter((item) => !target || String(item.target || item.issueKey || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type);
  const candidateTypes = [...new Set(allItems.map((item) => item.candidateType || "unknown"))].sort();
  const byType = candidateTypes
    .map((candidateType) => slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityGroup(filtered.filter((item) => item.candidateType === candidateType), candidateType))
    .filter((row) => row.total > 0);
  return {
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityGroup(filtered, "all"),
    byType,
    items: filtered
      .sort((a, b) => Number(b.repeatRecommended || 0) - Number(a.repeatRecommended || 0) ||
        String(b.reviewedAt || b.proposedAt || "").localeCompare(String(a.reviewedAt || a.proposedAt || "")))
      .slice(0, Math.max(1, Math.min(500, Number(payload.limit || 120))))
  };
}

function normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetric(input = {}) {
  const total = Number(input.total || 0);
  const approved = Number(input.approved || 0);
  const rejected = Number(input.rejected || 0);
  const reviewed = approved + rejected;
  const evaluated = Number(input.evaluated || 0);
  const successful = Number(input.successful || 0);
  const repeatRecommended = Number(input.repeatRecommended || 0);
  const rejectionReasons = Array.isArray(input.rejectionReasons)
    ? input.rejectionReasons.map((item) => ({
        reason: String(item.reason || "").trim(),
        count: Number(item.count || 0)
      })).filter((item) => item.reason)
    : [];
  const topRejection = rejectionReasons[0] || null;
  return {
    total,
    proposed: Number(input.proposed || 0),
    approved,
    rejected,
    reviewed,
    evaluated,
    successful,
    failed: Number(input.failed || 0),
    repeatRecommended,
    approvalRate: Number(input.approvalRate ?? (reviewed ? Math.round((approved / reviewed) * 100) : 0)),
    approvalSuccessRate: Number(input.approvalSuccessRate ?? (evaluated ? Math.round((successful / evaluated) * 100) : 0)),
    repeatRecommendationRate: Number(input.repeatRecommendationRate ?? (total ? Math.round((repeatRecommended / total) * 100) : 0)),
    rejectionRate: Number(input.rejectionRate ?? (reviewed ? Math.round((rejected / reviewed) * 100) : total ? Math.round((rejected / total) * 100) : 0)),
    topRejectionReason: String(input.topRejectionReason || topRejection?.reason || "").trim(),
    topRejectionCount: Number(input.topRejectionCount || topRejection?.count || 0),
    rejectionReasons
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetricDelta(before = {}, after = {}) {
  return {
    total: Number(after.total || 0) - Number(before.total || 0),
    reviewed: Number(after.reviewed || 0) - Number(before.reviewed || 0),
    evaluated: Number(after.evaluated || 0) - Number(before.evaluated || 0),
    approvalRate: Number(after.approvalRate || 0) - Number(before.approvalRate || 0),
    approvalSuccessRate: Number(after.approvalSuccessRate || 0) - Number(before.approvalSuccessRate || 0),
    repeatRecommendationRate: Number(after.repeatRecommendationRate || 0) - Number(before.repeatRecommendationRate || 0),
    rejectionRate: Number(after.rejectionRate || 0) - Number(before.rejectionRate || 0)
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceScore(before = {}, after = {}, status = "") {
  const delta = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetricDelta(before, after);
  const hasAfterEvidence = Number(after.reviewed || 0) > 0 || Number(after.evaluated || 0) > 0 || Number(after.total || 0) > 0;
  if (!hasAfterEvidence) return 50;
  const decisionWeight = status === "rejected" ? -5 : status === "overridden" ? 2 : status === "approved" ? 4 : 0;
  return safeScore(50 +
    Number(delta.approvalRate || 0) * 0.2 +
    Number(delta.approvalSuccessRate || 0) * 0.35 -
    Number(delta.repeatRecommendationRate || 0) * 0.25 -
    Number(delta.rejectionRate || 0) * 0.2 +
    decisionWeight);
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceState(item = {}) {
  const after = item.after || {};
  const hasAfterEvidence = Number(after.reviewed || 0) > 0 || Number(after.evaluated || 0) > 0 || Number(after.total || 0) > 0;
  if (!hasAfterEvidence) return "pending";
  if (item.active && (
    Number(item.performanceScore || 0) <= 45 ||
    (Number(after.evaluated || 0) > 0 && Number(after.approvalSuccessRate || 0) <= 40) ||
    Number(after.repeatRecommendationRate || 0) >= 50 ||
    Number(after.rejectionRate || 0) >= 60
  )) {
    return "weak_active";
  }
  if (Number(item.performanceScore || 0) >= 70 && Number(after.approvalSuccessRate || 0) >= 70 && Number(after.repeatRecommendationRate || 0) <= 25) {
    return "strong_match";
  }
  return "watch";
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceItem(calibration = {}, candidateQualityReport = {}) {
  const normalized = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration(calibration);
  const byType = new Map((candidateQualityReport.byType || []).map((row) => [row.candidateType, row]));
  const before = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetric(
    normalized.previousQuality || normalized.suggestedLearning?.previousQuality || {}
  );
  const after = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetric(
    byType.get(normalized.candidateType) || {}
  );
  const delta = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityMetricDelta(before, after);
  const performanceScore = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceScore(before, after, normalized.status);
  const base = {
    calibrationId: normalized.calibrationId,
    candidateType: normalized.candidateType,
    target: normalized.target || normalized.issueKey,
    issueKey: normalized.issueKey || normalized.target,
    status: normalized.status,
    active: slaPolicyCandidateQualityCalibrationActive(normalized),
    decisionType: normalized.status,
    decisionAt: normalized.reviewedAt || normalized.updatedAt || normalized.proposedAt,
    decisionBy: normalized.reviewedBy || normalized.updatedBy || normalized.proposedBy,
    reviewReason: normalized.reviewReason,
    overrideReason: normalized.overrideReason,
    direction: normalized.activeLearning?.direction || normalized.suggestedLearning?.direction || "neutral",
    priorityBefore: normalized.suggestedLearning?.priorityBefore || "",
    suggestedPriorityAfter: normalized.suggestedLearning?.priorityAfter || "",
    activePriorityAfter: normalized.activeLearning?.priorityAfter || "",
    before,
    after,
    delta,
    rejectionReasonChange: {
      beforeTopReason: before.topRejectionReason || "",
      beforeTopCount: before.topRejectionCount || 0,
      afterTopReason: after.topRejectionReason || "",
      afterTopCount: after.topRejectionCount || 0,
      changed: String(before.topRejectionReason || "") !== String(after.topRejectionReason || "")
    },
    performanceScore,
    performanceGrade: performanceGrade(performanceScore)
  };
  const performanceState = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceState(base);
  const reReviewReason = performanceState === "weak_active"
    ? `Active ${normalized.candidateType} quality learning is underperforming: score ${performanceScore}, approval success ${after.approvalSuccessRate}%, repeat ${after.repeatRecommendationRate}%, rejection ${after.rejectionRate}%.`
    : "";
  return {
    ...base,
    performanceState,
    reReviewNeeded: Boolean(reReviewReason),
    reReviewReason
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceSummary(items = []) {
  const scored = items.filter((item) => Number.isFinite(Number(item.performanceScore)));
  const rejectionReasonChanges = items.filter((item) => item.rejectionReasonChange?.changed).length;
  const afterRejectionReasonMap = new Map();
  items.forEach((item) => {
    const reason = String(item.rejectionReasonChange?.afterTopReason || item.after?.topRejectionReason || "").trim();
    if (!reason) return;
    afterRejectionReasonMap.set(reason, (afterRejectionReasonMap.get(reason) || 0) + 1);
  });
  return {
    total: items.length,
    reviewed: items.filter((item) => ["approved", "overridden", "rejected"].includes(item.status)).length,
    active: items.filter((item) => item.active).length,
    approved: items.filter((item) => item.status === "approved").length,
    overridden: items.filter((item) => item.status === "overridden").length,
    rejected: items.filter((item) => item.status === "rejected").length,
    weakActive: items.filter((item) => item.performanceState === "weak_active").length,
    strongMatch: items.filter((item) => item.performanceState === "strong_match").length,
    pending: items.filter((item) => item.performanceState === "pending").length,
    rejectionReasonChanges,
    avgPerformanceScore: scored.length ? Math.round(scored.reduce((sum, item) => sum + Number(item.performanceScore || 0), 0) / scored.length) : 0,
    avgApprovalRateDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.approvalRate || 0), 0) / items.length) : 0,
    avgApprovalSuccessDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.approvalSuccessRate || 0), 0) / items.length) : 0,
    avgRepeatDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.repeatRecommendationRate || 0), 0) / items.length) : 0,
    avgRejectionDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.rejectionRate || 0), 0) / items.length) : 0,
    topAfterRejectionReasons: [...afterRejectionReasonMap.entries()]
      .map(([reason, count]) => ({ reason, count }))
      .sort((a, b) => b.count - a.count || String(a.reason).localeCompare(String(b.reason)))
      .slice(0, 5)
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceGroup(items = [], groupKeyFn = () => "all", labelFn = groupKeyFn) {
  const map = new Map();
  items.forEach((item) => {
    const key = String(groupKeyFn(item) || "unknown");
    const label = String(labelFn(item) || key);
    const row = map.get(key) || {
      key,
      label,
      items: []
    };
    row.items.push(item);
    map.set(key, row);
  });
  return [...map.values()]
    .map((row) => ({
      key: row.key,
      label: row.label,
      ...slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceSummary(row.items),
      topRejectionReasonAfter: row.items
        .map((item) => item.after?.topRejectionReason || "")
        .filter(Boolean)[0] || ""
    }))
    .sort((a, b) => Number(b.weakActive || 0) - Number(a.weakActive || 0) ||
      Number(a.avgPerformanceScore || 0) - Number(b.avgPerformanceScore || 0) ||
      String(a.label || "").localeCompare(String(b.label || "")));
}

