function filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceItems(items = [], payload = {}) {
  const status = normalizeSlaPolicyCandidateQualityCalibrationStatus(payload.status || "");
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  const state = String(payload.performanceState || payload.state || "").trim().toLowerCase();
  return items
    .filter((item) => !payload.status || item.status === status)
    .filter((item) => !type || item.candidateType === type)
    .filter((item) => !state || item.performanceState === state);
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceReport(calibrations = [], candidateQualityReport = {}, payload = {}) {
  const allItems = calibrations
    .map((item) => slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceItem(item, candidateQualityReport))
    .filter((item) => ["approved", "overridden", "rejected"].includes(item.status));
  const filtered = filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityPerformanceItems(allItems, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const sorted = [...filtered].sort((a, b) => {
    const stateRank = { weak_active: 0, watch: 1, pending: 2, strong_match: 3 };
    return (stateRank[a.performanceState] ?? 9) - (stateRank[b.performanceState] ?? 9) ||
      Number(a.performanceScore || 0) - Number(b.performanceScore || 0) ||
      String(b.decisionAt || "").localeCompare(String(a.decisionAt || ""));
  });
  const reReviewCandidates = sorted
    .filter((item) => item.reReviewNeeded && item.active)
    .map(slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityReReviewCandidate);
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_effect_quality_performance",
    generatedAt: new Date().toISOString(),
    filters: {
      status: String(payload.status || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      performanceState: String(payload.performanceState || payload.state || "").trim(),
      limit
    },
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceSummary(allItems),
    byDecision: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceGroup(filtered, (item) => item.decisionType, (item) => item.decisionType),
    byType: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceGroup(filtered, (item) => item.candidateType, (item) => item.candidateType),
    reReviewCandidates: reReviewCandidates.slice(0, limit),
    items: sorted.slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA quality re-review effect quality learning decision performance",
      hiddenFromBusiness: ["quality learning performance", "approval and override decisions", "re-review candidates", "candidate approval outcomes", "rejection reason changes", "operator quality signals"]
    }
  };
}

