    status: current?.status || "open",
    memo: current?.memo || "",
    followUpActionType: current?.followUpActionType || "watch",
    performanceScore: candidate.performanceScore,
    performanceState: candidate.performanceState,
    decisionType: candidate.decisionType,
    decisionAt: candidate.decisionAt,
    reReviewReason: candidate.reason || candidate.reReviewReason,
