function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLogMap(logs = []) {
  const map = new Map();
  logs.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLog).forEach((log) => {
    if (!log.rereviewId) return;
    const list = map.get(log.rereviewId) || [];
    list.push(log);
    map.set(log.rereviewId, list);
  });
  return map;
}

async function appendSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLog(log = {}) {
  const normalized = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLog(log);
  if (!normalized.rereviewId || (!normalized.changedFields.length && normalized.eventType !== "completed" && !normalized.linkedCalibration)) {
    return null;
  }
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLogs();
  await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLogs({
    ...data,
    items: [
      normalized,
      ...(Array.isArray(data.items) ? data.items : [])
    ]
  });
  return normalized;
}

