async function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewReport(items = [], payload = {}, logs = [], savedActions = [], effectHistoryItems = [], adjustmentItems = []) {
  const logMap = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLogMap(logs);
  const normalized = items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereview).map((item) => {
    const itemLogs = logMap.get(item.rereviewId) || [];
    const changeHistorySummary = summarizeSlaPolicyCandidateQualityRereviewLogs(itemLogs);
    const operationalMetric = slaPolicyCandidateQualityRereviewOperationalMetric(item, itemLogs);
    const linkedCalibrationHistory = changeHistorySummary.recent
      .filter((log) => log.linkedCalibration)
      .map((log) => ({
        eventType: log.eventType,
        changedAt: log.changedAt,
        changedBy: log.changedBy,
        linkedCalibration: log.linkedCalibration
      }));
    if (!linkedCalibrationHistory.length && item.linkedCalibrationResult) {
      linkedCalibrationHistory.push({
        eventType: "completed",
        changedAt: item.linkedCalibrationResult.changedAt || item.completedAt || item.updatedAt || "",
        changedBy: item.linkedCalibrationResult.changedBy || item.completedBy || item.updatedBy || "",
        linkedCalibration: item.linkedCalibrationResult
      });
    }
    return {
      ...item,
      operationalMetric,
      changeHistorySummary,
      changeLogs: changeHistorySummary.recent,
      linkedCalibrationHistory
    };
  });
  const filtered = filterSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviews(normalized, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const filters = {
    status: String(payload.status || "").trim(),
    owner: String(payload.owner || "").trim(),
    due: String(payload.due || payload.dueState || "").trim(),
    minScore: payload.minScore ?? "",
    maxScore: payload.maxScore ?? "",
    limit
  };
  const report = {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_effect_quality_rereviews",
    generatedAt: new Date().toISOString(),
    filters,
    summary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSummary(normalized),
    operationalQuality: await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewOperationalQuality(filtered, savedActions, payload, effectHistoryItems, adjustmentItems),
    items: filtered
      .sort((a, b) => Number(a.performanceScore || 0) - Number(b.performanceScore || 0) ||
        String(a.dueDate || "9999-99-99").localeCompare(String(b.dueDate || "9999-99-99")) ||
        String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
      .slice(0, limit),
    exportUrls: {
      json: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewExportUrl(filters, "json"),
      csv: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewExportUrl(filters, "csv")
    },
    reportBoundaries: {
      source: "admin-only SLA effect quality learning re-review operations queue",
      hiddenFromBusiness: ["effect quality learning re-review queue", "owners", "due dates", "follow-up actions", "operational memos", "active learning calibration linkage", "change history", "operational quality metrics"]
    }
  };
  return {
    ...report,
    exportRows: slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewExportRows(report)
  };
}

