async function upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaAction(payload = {}) {
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions();
  const items = Array.isArray(data.items) ? data.items : [];
  const existing = items.find((item) => item.actionId === payload.actionId || (payload.sourceKey && item.sourceKey === payload.sourceKey));
  const now = new Date().toISOString();
  let action = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
    ...(existing || {}),
    ...payload,
    actionId: payload.actionId || existing?.actionId || (payload.sourceKey ? hashId("spcqraapqlsa", payload.sourceKey) : ""),
    createdAt: existing?.createdAt || payload.createdAt || now,
    createdBy: existing?.createdBy || payload.createdBy || payload.updatedBy || "admin",
    updatedAt: now,
    updatedBy: payload.updatedBy || payload.changedBy || "admin"
  });
  if (action.status === "done") {
    action = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
      ...action,
      completedAt: existing?.completedAt || payload.completedAt || now,
      completedBy: payload.updatedBy || payload.changedBy || payload.completedBy || "admin"
    });
    if (!existing?.completionQualitySnapshot || existing.status !== "done" || payload.refreshCompletionSnapshot) {
      const completionSnapshot = String(action.sourceKey || "").startsWith(EFFECT_CANDIDATE_QUALITY_LEARNING_REREVIEW_SLA_ACTION_SOURCE)
        ? await effectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewSlaActionCompletionSnapshot({
            ...action,
            riskLevel: calibrationSlaActionRiskLevel(action)
          })
        : await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActionCompletionSnapshot({
            ...action,
            riskLevel: calibrationSlaActionRiskLevel(action)
      });
      action = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
        ...action,
        completionQualitySnapshot: completionSnapshot
      });
    }
  }
  const updated = await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions({
    ...data,
    items: [
      action,
      ...items.filter((item) => item.actionId !== action.actionId && item.sourceKey !== action.sourceKey)
    ]
  });
  return {
    ok: true,
    slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions: {
      schema: updated.schema || "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_effect_quality_rereview_sla_actions_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    action,
    actions: await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActionsReport({ limit: 200 }),
    reportBoundaries: {
      source: "admin-only SLA effect quality learning re-review improvement action update",
      hiddenFromBusiness: ["effect quality re-review SLA action candidates", "owners", "target dates", "recommended corrective actions", "SLA source metrics"]
    }
  };
}

async function createSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActionFollowUp(payload = {}) {
  const actionId = String(payload.actionId || payload.parentActionId || "").trim();
  if (!actionId) {
    const error = new Error("Completed effect-quality re-review SLA action id is required.");
    error.statusCode = 400;
    throw error;
  }
  const existingActionData = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions();
  const existingActionItems = Array.isArray(existingActionData.items) ? existingActionData.items : [];
  const existingSourceAction = existingActionItems.map(normalizeSlaPolicyCandidateQualityRereviewSlaAction)
    .find((item) => item.actionId === actionId);
  if (existingSourceAction && String(existingSourceAction.sourceKey || "").startsWith(EFFECT_CANDIDATE_QUALITY_LEARNING_REREVIEW_SLA_ACTION_SOURCE)) {
    return createEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewSlaActionFollowUp(
      payload,
      existingSourceAction,
      existingActionData
    );
  }
  const reassessmentReport = await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActionReassessmentReport({
    followUpNeeded: payload.followUpNeeded || "",
    limit: 200
  });
  const reassessment = (reassessmentReport.items || []).find((item) => item.actionId === actionId);
  if (!reassessment) {
    const error = new Error("Completed effect-quality re-review SLA action reassessment not found.");
    error.statusCode = 404;
    throw error;
  }
  const data = existingActionData;
  const items = existingActionItems;
  const sourceAction = existingSourceAction;
  if (!sourceAction) {
    const error = new Error("Source effect-quality re-review SLA action not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.createdBy || "admin").trim() || "admin";
  const sourceKey = [
    "effect_quality_rereview_sla_followup",
    sourceAction.sourceKey || sourceAction.actionId,
    reassessment.outcome,
    monthKey(now) || kstDate(0)
  ].join("|");
  const existing = items.find((item) => item.sourceKey === sourceKey);
  const priority = reassessment.outcome === "worse" || reassessment.recurrence ? "urgent" : "high";
  const followUp = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
    ...(existing || {}),
    actionId: existing?.actionId || hashId("spcqraapqlsa", sourceKey),
    sourceKey,
    sourceType: sourceAction.sourceType || "summary",
    sourceLabel: `${sourceAction.sourceLabel || "Effect quality re-review SLA action"} follow-up`,
    month: sourceAction.month || monthKey(sourceAction.targetDate) || "",
    owner: sourceAction.owner || sourceAction.assignee || "",
    slaLevel: reassessment.outcome === "worse" || reassessment.current?.sla?.level === "danger" ? "danger" : "warning",
    issueKey: sourceAction.issueKey || reassessment.issueKey || "",
    severity: reassessment.outcome === "worse" || reassessment.current?.sla?.level === "danger" ? "danger" : "warning",
    rootMetric: sourceAction.rootMetric || reassessment.metric?.key || "",
    recommendation: payload.recommendation || reassessment.suggestedFollowUp,
    priority,
    assignee: payload.assignee || sourceAction.assignee || sourceAction.owner || "",
    targetDate: payload.targetDate || kstDate(priority === "urgent" ? 3 : 7),
    status: payload.status || "planned",
    parentActionId: sourceAction.actionId,
    followUpForActionId: sourceAction.actionId,
    followUpReason: payload.followUpReason || reassessment.followUpReason,
    reassessmentId: reassessment.reassessmentId,
    reassessmentOutcome: reassessment.outcome,
    sourceMetrics: {
      metric: reassessment.metric,
      baseline: reassessment.baseline,
      current: reassessment.current,
      comparison: reassessment.comparison,
      effectScore: reassessment.effectScore,
      recurrence: reassessment.recurrence,
      followUpNeeded: reassessment.followUpNeeded
    },
    createdAt: existing?.createdAt || now,
    createdBy: existing?.createdBy || actor,
    updatedAt: now,
    updatedBy: actor
  });
  const saved = await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions({
    ...data,
    items: [
      followUp,
      ...items.filter((item) => item.actionId !== followUp.actionId && item.sourceKey !== followUp.sourceKey)
    ]
  });
  const historyUpdate = await markEffectQualityRereviewSlaActionReassessmentHistoryFollowUp(
    reassessment,
    followUp,
    actor
  );
  return {
    ok: true,
    followUp,
    reassessment,
    slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions: {
      schema: saved.schema || "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_effect_quality_rereview_sla_actions_v1",
      total: saved.items.length,
      updatedAt: saved.updatedAt
    },
    effectQualityRereviewSlaActionReassessmentHistory: historyUpdate.effectQualityRereviewSlaActionReassessmentHistory,
    actions: await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActionsReport({ includeGenerated: false, limit: 200 }),
    reassessmentReport: await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActionReassessmentReport({ limit: 200 }),
    reportBoundaries: {
      source: "admin-only follow-up action created from effect-quality re-review SLA post-completion reassessment",
      hiddenFromBusiness: ["effect-quality post-completion reassessment", "effect score", "recurrence reason", "follow-up action linkage"]
    }
  };
}

async function applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewCompletion(rereview = {}, payload = {}) {
  if (rereview.status !== "completed") return null;
  const actionType = normalizeSlaPolicyCandidateQualityRereviewAction(rereview.followUpActionType);
  if (!rereview.calibrationId || actionType === "none" || actionType === "watch") return null;
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration)
    : [];
  const target = items.find((item) => item.calibrationId === rereview.calibrationId);
  if (!target) return null;
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.completedBy || rereview.completedBy || "admin").trim() || "admin";
  let updatedTarget = target;
  if (actionType === "maintain_active") {
    updatedTarget = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration({
      ...target,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "effect_quality_rereview_maintained",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: target.status,
          reason: rereview.memo || rereview.reReviewReason
        }),
        ...(target.events || [])
      ]
    });
  } else if (actionType === "deactivate_active") {
    updatedTarget = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration({
      ...target,
      status: "deactivated",
      activeLearning: null,
      reviewReason: rereview.memo || target.reviewReason,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "effect_quality_rereview_deactivated",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: "deactivated",
          reason: rereview.memo || rereview.reReviewReason
        }),
        ...(target.events || [])
      ]
    });
  } else if (actionType === "propose_modified_calibration") {
    const suggested = target.suggestedLearning || {};
    const active = target.activeLearning || suggested;
    updatedTarget = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibration({
      ...target,
      status: "proposed",
      activeLearning: null,
      suggestedLearning: {
        ...suggested,
        direction: active?.direction || suggested.direction || "neutral",
        priorityAfter: active?.priorityAfter || suggested.priorityAfter || suggested.priorityBefore || "medium",
        reason: rereview.memo || `Re-review proposes modifying active effect quality learning after performance score ${rereview.performanceScore}.`
      },
      reviewReason: rereview.memo || target.reviewReason,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "effect_quality_rereview_modify_proposed",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: "proposed",
          reason: rereview.memo || rereview.reReviewReason,
          overridePriorityAfter: active?.priorityAfter || ""
        }),
        ...(target.events || [])
      ]
    });
  }
  const updatedItems = items.map((item) => item.calibrationId === rereview.calibrationId ? updatedTarget : item);
  await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    ...updatedTarget,
    linkSummary: {
      calibrationId: target.calibrationId,
      actionType,
      previousStatus: target.status,
      nextStatus: updatedTarget.status,
      previousActive: Boolean(target.activeLearning),
      nextActive: Boolean(updatedTarget.activeLearning),
      changedAt: now,
      changedBy: actor
    }
  };
}

async function upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereview(payload = {}) {
  const rereviewId = String(payload.rereviewId || payload.id || "").trim();
  if (!rereviewId) {
    const error = new Error("SLA effect quality learning re-review id is required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviews();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereview)
    : [];
  const existing = items.find((item) => item.rereviewId === rereviewId);
  if (!existing) {
    const error = new Error("SLA effect quality learning re-review item not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.owner || "admin").trim() || "admin";
  const nextStatus = payload.status ? normalizeSlaPolicyCandidateQualityRereviewStatus(payload.status) : existing.status;
  const updated = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereview({
    ...existing,
    owner: payload.owner !== undefined ? payload.owner : existing.owner,
    dueDate: payload.dueDate !== undefined ? payload.dueDate : existing.dueDate,
    status: nextStatus,
    memo: payload.memo !== undefined ? payload.memo : existing.memo,
    followUpActionType: payload.followUpActionType !== undefined ? payload.followUpActionType : existing.followUpActionType,
    updatedAt: now,
    updatedBy: actor,
    completedAt: nextStatus === "completed" ? existing.completedAt || now : existing.completedAt,
    completedBy: nextStatus === "completed" ? String(payload.completedBy || actor).trim() : existing.completedBy,
    completionResult: nextStatus === "completed" ? normalizeSlaPolicyCandidateQualityRereviewAction(payload.followUpActionType || existing.followUpActionType) : existing.completionResult,
    events: [
      {
        eventType: nextStatus === "completed" ? "completed" : "updated",
        eventAt: now,
        eventBy: actor,
        previousStatus: existing.status,
        nextStatus,
        reason: String(payload.memo || payload.reason || "").trim(),
        followUpActionType: normalizeSlaPolicyCandidateQualityRereviewAction(payload.followUpActionType || existing.followUpActionType)
      },
      ...(existing.events || [])
    ]
  });
  const linkedCalibration = await applySlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewCompletion(updated, payload);
  const finalUpdated = normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereview({
    ...updated,
    linkedCalibrationResult: linkedCalibration?.linkSummary || updated.linkedCalibrationResult || null
  });
  const updatedItems = items.map((item) => item.rereviewId === rereviewId ? finalUpdated : item);
  const saved = await writeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviews({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  const changedFields = slaPolicyCandidateQualityRereviewLogFields(existing, finalUpdated);
  const log = await appendSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLog({
    rereviewId: finalUpdated.rereviewId,
    calibrationId: finalUpdated.calibrationId,
    eventType: nextStatus === "completed" ? "completed" : "updated",
    changedAt: now,
    changedBy: actor,
    fields: changedFields,
    before: {
      status: existing.status,
      owner: existing.owner,
      dueDate: existing.dueDate,
      memo: existing.memo,
      followUpActionType: existing.followUpActionType,
      completionResult: existing.completionResult
    },
    after: {
      status: finalUpdated.status,
      owner: finalUpdated.owner,
      dueDate: finalUpdated.dueDate,
      memo: finalUpdated.memo,
      followUpActionType: finalUpdated.followUpActionType,
      completionResult: finalUpdated.completionResult
    },
    completionResult: finalUpdated.completionResult,
    linkedCalibration: linkedCalibration?.linkSummary || null,
    memo: finalUpdated.memo
  });
  const [logData, actionData, effectHistoryData, adjustmentData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLogs(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions(),
    readEffectQualityRereviewSlaActionReassessmentHistory(),
    readEffectQualityRereviewSlaActionRecommendationAdjustments()
  ]);
  const rereviews = await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewReport(saved.items || [], {}, logData.items || [], actionData.items || [], effectHistoryData.items || [], adjustmentData.items || []);
  return {
    ok: true,
    item: rereviews.items.find((item) => item.rereviewId === finalUpdated.rereviewId) || finalUpdated,
    log,
    linkedCalibration,
    rereviews,
    reportBoundaries: {
      source: "admin-only SLA effect quality learning re-review update",
      hiddenFromBusiness: ["effect quality learning re-review operations", "owners", "due dates", "memos", "follow-up actions", "change history", "active learning calibration linkage"]
    }
  };
}

function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectReportItem(policyAdjustment = {}, performanceItems = [], proposalItems = [], payload = {}) {
  const approvedAt = policyAdjustment.approvedAt || policyAdjustment.reviewedAt || policyAdjustment.updatedAt || "";
  const approvedTime = slaPolicyEffectTime(approvedAt);
  const windowDays = Math.max(7, Math.min(365, Number(payload.windowDays || 45)));
  const windowMs = windowDays * 24 * 60 * 60 * 1000;
  const beforeStart = Number.isFinite(approvedTime) ? approvedTime - windowMs : null;
  const beforeEnd = approvedTime;
  const afterStart = approvedTime;
  const afterEnd = Number.isFinite(approvedTime) ? approvedTime + windowMs : null;
  const matchesScope = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectScopeMatcher(policyAdjustment);
  const scopedPerformance = performanceItems.filter(matchesScope);
  const scopedProposals = proposalItems.filter(matchesScope);
  const beforePerformance = scopedPerformance
    .filter((item) => slaPolicyEffectWindowContains(item.approvedAt, beforeStart, beforeEnd))
    .map((item) => slaPolicyEffectWindowedPerformanceItem(item, beforeStart, beforeEnd));
  const afterPerformance = scopedPerformance
    .filter((item) => slaPolicyEffectWindowContains(item.approvedAt, afterStart, afterEnd))
    .map((item) => slaPolicyEffectWindowedPerformanceItem(item, afterStart, afterEnd));
  const beforeProposals = scopedProposals.filter((item) => slaPolicyEffectWindowContains(slaPolicyEffectTimestamp(item), beforeStart, beforeEnd));
  const afterProposals = scopedProposals.filter((item) => slaPolicyEffectWindowContains(slaPolicyEffectTimestamp(item), afterStart, afterEnd));
  const before = slaPolicyEffectMetrics(beforePerformance, beforeProposals);
  const after = slaPolicyEffectMetrics(afterPerformance, afterProposals);
  const delta = slaPolicyEffectMetricDelta(before, after);
  const effectScore = slaPolicyEffectScore(policyAdjustment, before, after, delta);
  const outcome = slaPolicyEffectOutcome(effectScore, before, after);
  const suggestions = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectSuggestions(policyAdjustment, before, after, delta, outcome);
  return {
    policyAdjustmentId: policyAdjustment.policyAdjustmentId,
    candidateType: policyAdjustment.candidateType,
    target: policyAdjustment.target,
    issueKey: policyAdjustment.issueKey,
    priority: policyAdjustment.priority,
    approvedAt,
    approvedBy: policyAdjustment.reviewedBy || policyAdjustment.updatedBy || "",
    windowDays,
    beforeWindow: {
      start: beforeStart ? new Date(beforeStart).toISOString() : "",
      end: beforeEnd ? new Date(beforeEnd).toISOString() : ""
    },
    afterWindow: {
      start: afterStart ? new Date(afterStart).toISOString() : "",
      end: afterEnd ? new Date(afterEnd).toISOString() : ""
    },
    before,
    after,
    delta,
    effectScore,
    outcome,
    suggestions,
    sourceBeforePolicy: policyAdjustment.beforePolicy || {},
    sourceAfterPolicy: policyAdjustment.afterPolicy || {},
    sourcePolicyPatch: policyAdjustment.policyPatch || {},
    expectedImpact: policyAdjustment.expectedImpact || {},
    rollbackSuggested: suggestions.some((item) => item.type === "rollback_rereview_auto_policy_adjustment"),
    additionalAdjustmentSuggested: suggestions.some((item) => ["consider_rereview_partial_relaxation", "additional_rereview_tightening"].includes(item.type)),
    sourceCounts: {
      scopedPerformanceItems: scopedPerformance.length,
      scopedProposalItems: scopedProposals.length,
      beforePerformanceItems: beforePerformance.length,
      afterPerformanceItems: afterPerformance.length,
      beforeProposalItems: beforeProposals.length,
      afterProposalItems: afterProposals.length
    }
  };
}

async function slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectivenessReport(payload = {}) {
  const [policyAdjustmentData, adjustmentData, historyData, logData, qualityLearningData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustments(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments(),
    readSlaPolicyCandidateQualityRereviewActionReassessmentHistory(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLogs(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrations()
  ]);
  const approvedPolicies = (policyAdjustmentData.items || [])
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment)
    .filter((item) => item.status === "approved");
  const proposalItems = (adjustmentData.items || []).map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAdjustment);
  const historyItems = historyData.items || [];
  const logs = (logData.items || []).map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalLog);
  const performanceItems = proposalItems
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible)
    .map((item) => slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPerformanceItem(item, historyItems, logs));
  const effectItems = approvedPolicies
    .map((item) => slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectReportItem(item, performanceItems, proposalItems, payload))
    .sort((a, b) => {
      const outcomeRank = { worse: 0, pending: 1, unchanged: 2, improved: 3 };
      return (outcomeRank[a.outcome] ?? 9) - (outcomeRank[b.outcome] ?? 9) ||
        Number(b.rollbackSuggested || 0) - Number(a.rollbackSuggested || 0) ||
        String(b.approvedAt || "").localeCompare(String(a.approvedAt || ""));
    });
  const activePolicy = activeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicy(policyAdjustmentData.items || []);
  const candidateQualityBasis = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityReport(
    policyAdjustmentData.items || [],
    effectItems,
    { limit: payload.limit }
  );
  const draftEffectGeneratedCandidates = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectAdjustmentCandidates(
    effectItems,
    candidateQualityBasis,
    qualityLearningData.items || []
  );
  const qualityLearningProposals = await upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationProposals(draftEffectGeneratedCandidates);
  const qualityLearningWorkflow = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityCalibrationWorkflowReport(qualityLearningProposals, payload);
  const effectGeneratedCandidates = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectAdjustmentCandidates(
    effectItems,
    candidateQualityBasis,
    qualityLearningProposals
  );
  const effectGeneratedProposals = effectGeneratedCandidates.length
    ? await upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustmentProposals(effectGeneratedCandidates, activePolicy)
    : [];
  const annotatedEffectItems = attachSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectGeneratedProposals(
    effectItems,
    effectGeneratedCandidates,
    effectGeneratedProposals
  );
  const policyAdjustmentsForQuality = new Map((policyAdjustmentData.items || [])
    .map(normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment)
    .map((item) => [item.policyAdjustmentId, item]));
  effectGeneratedProposals.forEach((item) => {
    policyAdjustmentsForQuality.set(item.policyAdjustmentId, normalizeSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyAdjustment(item));
  });
  const effectCandidateQuality = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectCandidateQualityReport(
    [...policyAdjustmentsForQuality.values()],
    annotatedEffectItems,
    payload
  );
  const qualityLearningPerformance = slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityDecisionPerformanceReport(
    qualityLearningProposals,
    effectCandidateQuality,
    payload
  );
  await upsertSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewCandidates(qualityLearningPerformance);
  const [qualityLearningRereviewData, qualityLearningRereviewLogData, qualityLearningRereviewActionData, effectHistoryData, effectAdjustmentData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviews(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewLogs(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewSlaActions(),
    readEffectQualityRereviewSlaActionReassessmentHistory(),
    readEffectQualityRereviewSlaActionRecommendationAdjustments()
  ]);
  const qualityLearningRereviews = await slaPolicyCandidateQualityRereviewActionRecommendationAutoApprovalPolicyEffectQualityRereviewReport(qualityLearningRereviewData.items || [], {
    status: payload.rereviewStatus,
    owner: payload.rereviewOwner,
    due: payload.rereviewDue,
    minScore: payload.rereviewMinScore,
    maxScore: payload.rereviewMaxScore,
    actionStatus: payload.rereviewActionStatus,
    actionOwner: payload.rereviewActionOwner,
    actionDue: payload.rereviewActionDue,
    actionTargetDate: payload.rereviewActionTargetDate,
    actionPriority: payload.rereviewActionPriority,
    actionRisk: payload.rereviewActionRisk,
    actionIssue: payload.rereviewActionIssue,
    actionIncludeGenerated: payload.rereviewActionIncludeGenerated,
    reassessmentOwner: payload.rereviewActionOwner,
    reassessmentIssue: payload.rereviewActionIssue,
    reassessmentOutcome: payload.rereviewActionReassessmentOutcome,
    reassessmentFollowUpNeeded: payload.rereviewActionFollowUpNeeded,
    limit: payload.limit
  }, qualityLearningRereviewLogData.items || [], qualityLearningRereviewActionData.items || [], effectHistoryData.items || [], effectAdjustmentData.items || []);
  const effectQualitySlaActionReassessmentItems = qualityLearningRereviews.operationalQuality?.slaActions?.postReassessment?.items || [];
  const effectQualitySlaActionReassessmentHistoryWrite = await upsertEffectQualityRereviewSlaActionReassessmentHistoryItems(effectQualitySlaActionReassessmentItems, {
    recordedBy: "system"
  });
  const effectQualitySlaActionReassessmentHistory = await effectQualityRereviewSlaActionReassessmentHistoryReport({
    owner: payload.rereviewActionOwner,
    issueKey: payload.rereviewActionIssue,
    outcome: payload.rereviewActionReassessmentOutcome,
    followUp: payload.rereviewActionFollowUpNeeded,
    limit: payload.limit
  });
  if (qualityLearningRereviews.operationalQuality?.slaActions?.postReassessment) {
    qualityLearningRereviews.operationalQuality.slaActions.postReassessment.historyWrite = effectQualitySlaActionReassessmentHistoryWrite.effectQualityRereviewSlaActionReassessmentHistory;
    qualityLearningRereviews.operationalQuality.slaActions.postReassessment.history = effectQualitySlaActionReassessmentHistory;
  }
  const filtered = filterSlaPolicyEffectItems(annotatedEffectItems, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_action_recommendation_auto_approval_policy_effectiveness",
    generatedAt: new Date().toISOString(),
    filters: {
      target: String(payload.target || payload.issueKey || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      outcome: String(payload.outcome || "").trim(),
      windowDays: Math.max(7, Math.min(365, Number(payload.windowDays || 45))),
      limit
    },
    summary: slaPolicyEffectSummary(filtered),
    fullSummary: slaPolicyEffectSummary(annotatedEffectItems),
    candidateQualityBasis,
    qualityLearningWorkflow,
    qualityLearningPerformance,
    qualityLearningRereviews,
    effectGeneratedCandidates: effectGeneratedCandidates.slice(0, limit),
    effectGeneratedProposals: effectGeneratedProposals.slice(0, limit),
    effectCandidateQuality,
    items: filtered.slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA quality re-review action auto approval policy post-change effectiveness tracking",
      hiddenFromBusiness: ["re-review auto approval policy effectiveness", "policy adjustment ids", "rollback suggestions", "manual review conversion", "effect-based policy candidates", "candidate approval quality", "rejection reasons", "repeat recommendations", "operator quality outcomes", "post-change policy formulas"]
    }
  };
}

