function effectQualityRereviewSlaActionHistoryAdjustment(action = {}, historyItems = []) {
  const normalizedHistory = historyItems.map(normalizeSlaPolicyCandidateQualityRereviewActionReassessmentHistoryItem);
  const assignee = String(action.assignee || action.owner || "").trim().toLowerCase();
  const month = String(action.month || monthKey(action.targetDate) || "").trim();
  const issueItems = normalizedHistory.filter((item) => slaPolicyCandidateQualityRereviewActionHistoryIssueMatch(item, action));
  const assigneeItems = assignee
    ? normalizedHistory.filter((item) => String(item.assignee || item.owner || "").toLowerCase() === assignee)
    : [];
  const monthItems = month
    ? normalizedHistory.filter((item) => item.evaluatedMonth === month || monthKey(item.targetDate) === month)
    : [];
  const issueStats = slaPolicyCandidateQualityRereviewActionHistoryStats(issueItems);
  const assigneeStats = slaPolicyCandidateQualityRereviewActionHistoryStats(assigneeItems);
  const monthStats = slaPolicyCandidateQualityRereviewActionHistoryStats(monthItems);
  const weighted = slaPolicyCandidateQualityRereviewActionHistoryWeightedScore([
    { weight: 0.55, stats: issueStats },
    { weight: 0.25, stats: assigneeStats },
    { weight: 0.2, stats: monthStats }
  ]);
  const sampleSize = new Set([...issueItems, ...assigneeItems, ...monthItems].map((item) => item.historyId || item.reassessmentId || item.actionId)).size;
  let direction = "neutral";
  if (sampleSize > 0 && weighted.score >= 72 && issueStats.improvedRate >= 50 && issueStats.recurrenceRate <= 25 && issueStats.worseRate <= 25) {
    direction = "boost";
  } else if (sampleSize > 0 && (weighted.score < 45 || issueStats.recurrenceRate >= 50 || issueStats.worseRate >= 50 || issueStats.followUpNeededRate >= 70)) {
    direction = "downgrade";
  }
  const originalPriority = normalizeCalibrationSlaActionPriority(action.priority) || "medium";
  const adjustedPriority = shiftCalibrationSlaActionPriority(originalPriority, direction, action);
  const reasons = [];
  if (sampleSize > 0) {
    reasons.push(`Effect-quality SLA action history score ${weighted.score} from ${sampleSize} reassessment row(s).`);
    if (issueStats.total) {
      reasons.push(`${action.issueKey || action.rootMetric || "same issue"} history: avg ${issueStats.averageEffectScore}, improved ${issueStats.improvedRate}%, worse ${issueStats.worseRate}%, recurrence ${issueStats.recurrenceRate}%.`);
    }
    if (assigneeStats.total) {
      reasons.push(`Assignee history: avg ${assigneeStats.averageEffectScore} across ${assigneeStats.total} row(s).`);
    }
    if (monthStats.total) {
      reasons.push(`Month history: avg ${monthStats.averageEffectScore} across ${monthStats.total} row(s).`);
    }
  } else {
    reasons.push("No effect-quality SLA action reassessment history yet; base priority is unchanged.");
  }
  if (direction === "boost" && adjustedPriority !== originalPriority) {
    reasons.push(`Priority raised from ${originalPriority} to ${adjustedPriority}.`);
  } else if (direction === "downgrade" && adjustedPriority !== originalPriority) {
    reasons.push(`Priority lowered from ${originalPriority} to ${adjustedPriority}.`);
  } else if (direction !== "neutral") {
    reasons.push(`History suggests ${direction}, but the current SLA severity keeps priority at ${adjustedPriority}.`);
  }
  return {
    applied: sampleSize > 0,
    workflowStatus: sampleSize > 0 ? "active" : "none",
    activeApplied: sampleSize > 0 && direction !== "neutral" && adjustedPriority !== originalPriority,
    direction,
    historyEffectScore: weighted.score,
    sampleSize,
    originalPriority,
    adjustedPriority,
    issueStats,
    assigneeStats,
    monthStats,
    calculationBasis: {
      issueWeight: 55,
      assigneeWeight: 25,
      monthWeight: 20,
      boostRule: "score >= 72, issue improved >= 50%, recurrence <= 25%, worse <= 25%",
      downgradeRule: "score < 45, recurrence >= 50%, worse >= 50%, or follow-up-needed >= 70%"
    },
    reasons,
    recommendationNote: reasons.join(" ")
  };
}

