    byType: effectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningPerformanceGroup(filtered, (item) => item.candidateType, (item) => item.candidateType),
    reReviewCandidates: reReviewCandidates.slice(0, limit),
