async function upsertEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewCandidates(performance = {}) {
  const data = await readEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviews();
  const existingItems = Array.isArray(data.items)
    ? data.items.map(normalizeEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereview)
    : [];
  const byId = new Map(existingItems.map((item) => [item.rereviewId, item]));
  const touched = [];
  const createdLogs = [];
  (performance.reReviewCandidates || []).forEach((candidate) => {
    const rereviewId = effectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewId(candidate);
    const existing = byId.get(rereviewId) || null;
    if (existing && ["completed", "dismissed"].includes(existing.status)) {
      touched.push(existing);
      return;
    }
    const item = buildEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewCandidate(candidate, existing);
    byId.set(item.rereviewId, item);
    touched.push(item);
    if (!existing) {
      createdLogs.push({
        rereviewId: item.rereviewId,
        calibrationId: item.calibrationId,
        eventType: "created",
        changedAt: item.createdAt,
        changedBy: item.createdBy || "system",
        fields: {
          status: { before: "", after: item.status },
          owner: { before: "", after: item.owner },
          dueDate: { before: "", after: item.dueDate },
          followUpActionType: { before: "", after: item.followUpActionType }
        },
        after: {
          status: item.status,
          owner: item.owner,
          dueDate: item.dueDate,
          followUpActionType: item.followUpActionType
        },
        memo: item.reReviewReason || ""
      });
    }
  });
  await writeEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviews({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  for (const log of createdLogs) {
    await appendEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLog(log);
  }
  return touched;
}

