function effectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLogMap(logs = []) {
  const map = new Map();
  logs.map(normalizeEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLog).forEach((log) => {
    if (!log.rereviewId) return;
    const list = map.get(log.rereviewId) || [];
    list.push(log);
    map.set(log.rereviewId, list);
  });
  return map;
}

async function appendEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLog(log = {}) {
  const normalized = normalizeEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLog(log);
  if (!normalized.rereviewId || (!normalized.changedFields.length && normalized.eventType !== "completed" && normalized.eventType !== "created" && !normalized.linkedCalibration)) {
    return null;
  }
  const data = await readEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLogs();
  await writeEffectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewLogs({
    ...data,
    items: [
      normalized,
      ...(Array.isArray(data.items) ? data.items : [])
    ]
  });
  return normalized;
}

