function effectQualityRereviewSlaActionRecommendationAutoApprovalPolicyEffectCandidateQualityLearningRereviewCombinedLogs(fileLogs = [], fallbackEventLogs = []) {
  const logs = fileLogs.length
    ? [
        ...fileLogs,
        ...fallbackEventLogs.filter((log) => log.eventType === "created" && !fileLogs.some((fileLog) => fileLog.eventType === "created"))
      ]
    : fallbackEventLogs;
  const seen = new Set();
  return logs.filter((log) => {
    const key = log.logId || [
      log.rereviewId || "",
      log.eventType || "",
      log.changedAt || "",
      log.changedBy || ""
    ].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

