async function reviewEffectQualityRereviewSlaActionRecommendationAdjustment(payload = {}) {
  const adjustmentId = String(payload.adjustmentId || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  if (!adjustmentId || !["approved", "rejected"].includes(decision)) {
    const error = new Error("Adjustment id and approved/rejected decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readEffectQualityRereviewSlaActionRecommendationAdjustments();
  const items = Array.isArray(data.items)
    ? data.items.map(normalizeEffectQualityRereviewSlaActionRecommendationAdjustment)
    : [];
  const target = items.find((item) => item.adjustmentId === adjustmentId);
  if (!target) {
    const error = new Error("Effect-quality SLA action recommendation adjustment proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const updatedTarget = normalizeEffectQualityRereviewSlaActionRecommendationAdjustment({
    ...target,
    status: decision,
    activePriority: decision === "approved" ? target.proposedPriority : "",
    approvalMode: "manual",
    rollbackAvailable: false,
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason: String(payload.reviewReason || payload.reason || "").trim(),
    approvedAt: decision === "approved" ? now : "",
    rejectedAt: decision === "rejected" ? now : "",
    updatedAt: now,
    updatedBy: reviewer
  });
  const updatedItems = items.map((item) => {
    if (item.adjustmentId === adjustmentId) return updatedTarget;
    if (decision === "approved" && item.sourceKey === target.sourceKey && item.status === "approved") {
      return normalizeEffectQualityRereviewSlaActionRecommendationAdjustment({
        ...item,
        status: "rejected",
        activePriority: "",
        rollbackAvailable: false,
        reviewedAt: now,
        reviewedBy: reviewer,
        reviewReason: `Superseded by approved effect-quality SLA action adjustment ${adjustmentId}.`,
        rejectedAt: now,
        updatedAt: now,
        updatedBy: reviewer
      });
    }
    return item;
  });
  const updated = await writeEffectQualityRereviewSlaActionRecommendationAdjustments({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    role: "admin",
    reportType: "effect_quality_rereview_sla_action_recommendation_adjustment_review",
    generatedAt: now,
    adjustment: updatedTarget,
    effectQualityRereviewSlaActionRecommendationAdjustments: {
      schema: updated.schema || "effect_quality_rereview_sla_action_recommendation_adjustments_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    reportBoundaries: {
      source: "admin-only review decision for effect-quality SLA action recommendation adjustment",
      hiddenFromBusiness: ["approval decision", "review reason", "priority calibration evidence", "effect scores"]
    }
  };
}

function slaPolicyCandidateQualityRereviewActionReassessmentBlock(quality = {}, actions = [], payload = {}) {
  const savedActions = actions.filter((item) => item.isSaved);
  const items = savedActions
    .filter((item) => item.isSaved)
    .filter((item) => item.status === "done")
    .filter((item) => item.completionQualitySnapshot)
    .map((item) => {
      const reassessment = slaPolicyCandidateQualityRereviewActionReassessmentItem(item, quality);
      const followUp = savedActions.find((action) => action.parentActionId === item.actionId || action.followUpForActionId === item.actionId);
      return {
        ...reassessment,
        followUpCreated: Boolean(followUp),
        followUpActionId: followUp?.actionId || "",
        followUpActionSourceKey: followUp?.sourceKey || "",
        followUpCreatedAt: followUp?.createdAt || followUp?.updatedAt || ""
      };
    });
  const filtered = filterSlaPolicyCandidateQualityRereviewActionReassessments(items, payload);
  const limit = Math.max(1, Math.min(200, Number(payload.reassessmentLimit || payload.limit || 80)));
  return {
    summary: slaPolicyCandidateQualityRereviewActionReassessmentSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionReassessmentSummary(items),
    filters: {
      owner: String(payload.reassessmentOwner || payload.owner || payload.actionOwner || "").trim(),
      issue: String(payload.reassessmentIssue || payload.issueKey || payload.actionIssue || "").trim(),
      outcome: String(payload.reassessmentOutcome || payload.outcome || "").trim(),
      followUpNeeded: String(payload.followUpNeeded ?? payload.reassessmentFollowUpNeeded ?? "").trim()
    },
    items: filtered
      .sort((a, b) => Number(a.effectScore || 0) - Number(b.effectScore || 0) || String(b.completedAt || "").localeCompare(String(a.completedAt || "")))
      .slice(0, limit)
  };
}

function slaPolicyCandidateQualityRereviewActionDueState(action = {}) {
  return calibrationSlaActionDueState({
    status: action.status,
    targetDate: action.targetDate
  });
}

function enrichSlaPolicyCandidateQualityRereviewAction(action = {}) {
  const normalized = normalizeSlaPolicyCandidateQualityRereviewSlaAction(action);
  const dueState = slaPolicyCandidateQualityRereviewActionDueState(normalized);
  const riskLevel = calibrationSlaActionRiskLevel(normalized);
  return {
    ...normalized,
    isSaved: Boolean(action.isSaved),
    candidateStatus: action.candidateStatus || (action.isSaved ? "saved" : "generated"),
    dueState,
    riskLevel,
    isOpen: calibrationSlaActionIsOpen(normalized),
    isOverdue: dueState === "overdue",
    isThisWeek: dueState === "this_week",
    isCompleted: normalized.status === "done"
  };
}

async function slaPolicyCandidateQualityRereviewActionsForQuality(quality = {}, savedActions = [], historyItems = [], adjustmentItems = []) {
  const candidates = await slaPolicyCandidateQualityRereviewActionCandidatesFromQuality(quality, historyItems, adjustmentItems);
  return mergeSlaPolicyCandidateQualityRereviewActions(candidates, savedActions)
    .map(enrichSlaPolicyCandidateQualityRereviewAction);
}

async function attachSlaPolicyCandidateQualityRereviewActionsToQuality(quality = {}, savedActions = [], payload = {}, historyItems = [], adjustmentItems = []) {
  const actions = await slaPolicyCandidateQualityRereviewActionsForQuality(quality, savedActions, historyItems, adjustmentItems);
  const displayed = filterSlaPolicyCandidateQualityRereviewActions(actions, {
    status: payload.actionStatus,
    owner: payload.actionOwner,
    due: payload.actionDue,
    targetDate: payload.actionTargetDate,
    priority: payload.actionPriority,
    risk: payload.actionRisk,
    issueKey: payload.actionIssue,
    rootMetric: payload.actionRootMetric,
    includeGenerated: payload.actionIncludeGenerated
  });
  const queueItems = filterSlaPolicyCandidateQualityRereviewActions(actions, {
    status: payload.actionStatus,
    owner: payload.actionOwner,
    due: payload.actionDue,
    targetDate: payload.actionTargetDate,
    priority: payload.actionPriority,
    risk: payload.actionRisk,
    issueKey: payload.actionIssue,
    rootMetric: payload.actionRootMetric,
    includeGenerated: false
  });
  const postReassessment = slaPolicyCandidateQualityRereviewActionReassessmentBlock(quality, actions, payload);
  return {
    ...quality,
    slaActions: {
      summary: slaPolicyCandidateQualityRereviewActionSummary(displayed),
      fullSummary: slaPolicyCandidateQualityRereviewActionSummary(actions),
      operationQueue: {
        summary: slaPolicyCandidateQualityRereviewActionQueueSummary(queueItems),
        fullSummary: slaPolicyCandidateQualityRereviewActionQueueSummary(actions.filter((item) => item.isSaved)),
        focus: slaPolicyCandidateQualityRereviewActionQueueFocus(queueItems),
        items: queueItems.slice(0, 120)
      },
      postReassessment,
      filters: {
        status: String(payload.actionStatus || "").trim(),
        owner: String(payload.actionOwner || "").trim(),
        due: String(payload.actionDue || "").trim(),
        targetDate: String(payload.actionTargetDate || "").trim(),
        priority: String(payload.actionPriority || "").trim(),
        risk: String(payload.actionRisk || "").trim(),
        issue: String(payload.actionIssue || payload.actionRootMetric || "").trim(),
        includeGenerated: String(payload.actionIncludeGenerated ?? "true")
      },
      items: displayed.slice(0, 100)
    }
  };
}

function normalizeSlaPolicyCandidateQualityRereview(input = {}) {
  const now = new Date().toISOString();
  const status = normalizeSlaPolicyCandidateQualityRereviewStatus(input.status || input.reviewStatus || "open");
  const dueDate = String(input.dueDate || input.targetDate || "").slice(0, 10);
  return {
    rereviewId: String(input.rereviewId || slaPolicyCandidateQualityRereviewId(input)).trim(),
    calibrationId: String(input.calibrationId || "").trim(),
    policyAdjustmentId: String(input.policyAdjustmentId || "").trim(),
    candidateType: String(input.candidateType || "").trim(),
    target: String(input.target || input.issueKey || "").trim(),
    issueKey: String(input.issueKey || input.target || "").trim(),
    owner: String(input.owner || input.assignee || "").trim(),
    dueDate,
    dueState: slaPolicyCandidateQualityRereviewDueState(dueDate),
    status,
    memo: String(input.memo || "").trim(),
    followUpActionType: normalizeSlaPolicyCandidateQualityRereviewAction(input.followUpActionType || input.actionType || "watch"),
    performanceScore: Math.max(0, Math.min(100, Math.round(Number(input.performanceScore || 0)))),
    performanceState: String(input.performanceState || "").trim(),
    reReviewReason: String(input.reReviewReason || input.reason || "").trim(),
    candidateStatus: String(input.candidateStatus || "").trim(),
    qualityOutcome: String(input.qualityOutcome || "").trim(),
    repeatRecommended: Boolean(input.repeatRecommended),
    sourceSnapshot: input.sourceSnapshot && typeof input.sourceSnapshot === "object" ? input.sourceSnapshot : {},
    createdAt: input.createdAt || now,
    createdBy: String(input.createdBy || "system").trim() || "system",
    updatedAt: input.updatedAt || now,
    updatedBy: String(input.updatedBy || input.owner || "system").trim() || "system",
    completedAt: input.completedAt || "",
    completedBy: String(input.completedBy || "").trim(),
    completionResult: String(input.completionResult || "").trim(),
    events: Array.isArray(input.events) ? input.events : []
  };
}

function buildSlaPolicyCandidateQualityRereviewCandidate(item = {}, existing = null) {
  const current = existing ? normalizeSlaPolicyCandidateQualityRereview(existing) : null;
  const now = new Date().toISOString();
  return normalizeSlaPolicyCandidateQualityRereview({
    ...(current || {}),
    calibrationId: item.calibrationId,
    policyAdjustmentId: item.policyAdjustmentId,
    candidateType: item.candidateType,
    target: item.target,
    issueKey: item.target,
    owner: current?.owner || "",
    dueDate: current?.dueDate || "",
    status: current?.status || "open",
    memo: current?.memo || "",
    followUpActionType: current?.followUpActionType || "watch",
    performanceScore: item.performanceScore,
    performanceState: item.performanceState,
    reReviewReason: item.reReviewReason,
    candidateStatus: item.candidateStatus,
    qualityOutcome: item.qualityOutcome,
    repeatRecommended: item.repeatRecommended,
    sourceSnapshot: {
      calibrationId: item.calibrationId,
      policyAdjustmentId: item.policyAdjustmentId,
      decisionType: item.decisionType,
      direction: item.direction,
      priorityBefore: item.priorityBefore,
      activePriorityAfter: item.activePriorityAfter,
      candidateStatus: item.candidateStatus,
      qualityOutcome: item.qualityOutcome,
      postEffectOutcome: item.postEffectOutcome,
      postEffectScore: item.postEffectScore,
      performanceScore: item.performanceScore,
      reReviewReason: item.reReviewReason
    },
    createdAt: current?.createdAt || now,
    createdBy: current?.createdBy || "system",
    updatedAt: current ? now : now,
    updatedBy: current ? current.updatedBy || "system" : "system",
    completedAt: current?.completedAt || "",
    completedBy: current?.completedBy || "",
    completionResult: current?.completionResult || "",
    events: current?.events?.length ? current.events : [{
      eventType: "created",
      eventAt: now,
      eventBy: "system",
      reason: item.reReviewReason || "Quality calibration performance requires re-review."
    }]
  });
}

async function upsertSlaPolicyCandidateQualityRereviewCandidates(performance = {}) {
  const data = await readSlaPolicyCandidateQualityRereviews();
  const existingItems = Array.isArray(data.items) ? data.items.map(normalizeSlaPolicyCandidateQualityRereview) : [];
  const byId = new Map(existingItems.map((item) => [item.rereviewId, item]));
  const touched = [];
  (performance.reReviewCandidates || []).forEach((candidate) => {
    const rereviewId = slaPolicyCandidateQualityRereviewId(candidate);
    const existing = byId.get(rereviewId) || null;
    if (existing && ["completed", "dismissed"].includes(existing.status)) {
      touched.push(existing);
      return;
    }
    const item = buildSlaPolicyCandidateQualityRereviewCandidate(candidate, existing);
    byId.set(item.rereviewId, item);
    touched.push(item);
  });
  await writeSlaPolicyCandidateQualityRereviews({
    ...data,
    items: [...byId.values()].sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  return touched;
}

function slaPolicyCandidateQualityRereviewSummary(items = []) {
  return {
    total: items.length,
    open: items.filter((item) => item.status === "open").length,
    inProgress: items.filter((item) => item.status === "in_progress").length,
    completed: items.filter((item) => item.status === "completed").length,
    deferred: items.filter((item) => item.status === "deferred").length,
    dismissed: items.filter((item) => item.status === "dismissed").length,
    overdue: items.filter((item) => item.status !== "completed" && item.dueState === "overdue").length,
    thisWeek: items.filter((item) => item.status !== "completed" && item.dueState === "this_week").length,
    avgPerformanceScore: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.performanceScore || 0), 0) / items.length) : 0
  };
}

function filterSlaPolicyCandidateQualityRereviews(items = [], payload = {}) {
  const statusText = String(payload.status || "").trim();
  const status = normalizeSlaPolicyCandidateQualityRereviewStatus(statusText);
  const owner = String(payload.owner || "").trim().toLowerCase();
  const due = String(payload.due || payload.dueState || "").trim();
  const minScore = payload.minScore === undefined || payload.minScore === null || payload.minScore === "" ? null : Number(payload.minScore);
  const maxScore = payload.maxScore === undefined || payload.maxScore === null || payload.maxScore === "" ? null : Number(payload.maxScore);
  return items
    .filter((item) => !statusText || item.status === status)
    .filter((item) => !owner || String(item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !due || item.dueState === due)
    .filter((item) => !Number.isFinite(minScore) || Number(item.performanceScore || 0) >= minScore)
    .filter((item) => !Number.isFinite(maxScore) || Number(item.performanceScore || 0) <= maxScore);
}

function slaPolicyCandidateQualityRereviewExportUrl(filters = {}, format = "json") {
  const params = new URLSearchParams();
  ["status", "owner", "due", "minScore", "maxScore", "limit"].forEach((key) => {
    const value = filters[key];
    if (value !== undefined && value !== null && String(value).trim()) params.set(key, value);
  });
  params.set("format", format);
  return `/api/admin/master-db/sla-policy-candidate-quality-rereviews?${params.toString()}`;
}

function slaPolicyCandidateQualityRereviewFilename(filters = {}, ext = "json") {
  const parts = [
    "sla-quality-rereviews",
    filters.status || "all",
    filters.owner || "all",
    filters.due || "all",
    filters.maxScore || "all"
  ].map((item) => String(item || "all").replace(/[^a-z0-9_-]+/gi, "-"));
  return `${parts.join("_")}.${ext}`;
}

function slaPolicyCandidateQualityRereviewExportRows(report = {}) {
  return (report.items || []).map((item) => ({
    rereviewId: item.rereviewId || "",
    calibrationId: item.calibrationId || "",
    policyAdjustmentId: item.policyAdjustmentId || "",
    candidateType: item.candidateType || "",
    target: item.target || "",
    status: item.status || "",
    owner: item.owner || "",
    dueDate: item.dueDate || "",
    dueState: item.dueState || "",
    performanceScore: item.performanceScore ?? "",
    followUpActionType: item.followUpActionType || "",
    completionResult: item.completionResult || "",
    completedAt: item.completedAt || "",
    completedBy: item.completedBy || "",
    changeLogCount: item.changeHistorySummary?.totalLogs || 0,
    latestChangeAt: item.changeHistorySummary?.latestChangedAt || "",
    latestChangeBy: item.changeHistorySummary?.latestChangedBy || "",
    latestEventType: item.changeHistorySummary?.latestEventType || "",
    changedFieldSummary: item.changeHistorySummary?.changedFieldSummary || "",
    linkedCalibrationEvents: item.changeHistorySummary?.linkedCalibrationEvents || 0,
    processingHours: item.operationalMetric?.processingHours ?? "",
    statusTransitionCount: item.operationalMetric?.statusTransitionCount ?? "",
    reopenCount: item.operationalMetric?.reopenCount ?? "",
    activityMonth: item.operationalMetric?.activityMonth || "",
    linkedCalibrationResult: item.operationalMetric?.linkedCalibrationResult || "",
    delayedIncomplete: item.operationalMetric?.delayedIncomplete ? "yes" : "no",
    activeCalibrationLinkUnprocessed: item.operationalMetric?.activeCalibrationLinkUnprocessed ? "yes" : "no",
    memo: item.memo || ""
  }));
}

function slaPolicyCandidateQualityRereviewCsv(report = {}) {
  const columns = [
    "rereviewId",
    "calibrationId",
    "policyAdjustmentId",
    "candidateType",
    "target",
    "status",
    "owner",
    "dueDate",
    "dueState",
    "performanceScore",
    "followUpActionType",
    "completionResult",
    "completedAt",
    "completedBy",
    "changeLogCount",
    "latestChangeAt",
    "latestChangeBy",
    "latestEventType",
    "changedFieldSummary",
    "linkedCalibrationEvents",
    "processingHours",
    "statusTransitionCount",
    "reopenCount",
    "activityMonth",
    "linkedCalibrationResult",
    "delayedIncomplete",
    "activeCalibrationLinkUnprocessed",
    "memo"
  ];
  const rows = slaPolicyCandidateQualityRereviewExportRows(report);
  return `\uFEFF${[
    columns.join(","),
    ...rows.map((row) => columns.map((column) => csvEscape(row[column])).join(","))
  ].join("\n")}`;
}

async function slaPolicyCandidateQualityRereviewReport(items = [], payload = {}, logs = [], actions = [], actionReassessmentHistory = [], actionRecommendationAdjustments = []) {
  const logMap = slaPolicyCandidateQualityRereviewLogMap(logs);
  const normalized = items.map(normalizeSlaPolicyCandidateQualityRereview).map((item) => {
    const itemLogs = logMap.get(item.rereviewId) || [];
    const changeHistorySummary = summarizeSlaPolicyCandidateQualityRereviewLogs(itemLogs);
    const operationalMetric = slaPolicyCandidateQualityRereviewOperationalMetric(item, itemLogs);
    return {
      ...item,
      operationalMetric,
      changeHistorySummary,
      changeLogs: changeHistorySummary.recent,
      linkedCalibrationHistory: changeHistorySummary.recent
        .filter((log) => log.linkedCalibration)
        .map((log) => ({
          eventType: log.eventType,
          changedAt: log.changedAt,
          changedBy: log.changedBy,
          linkedCalibration: log.linkedCalibration
        }))
    };
  });
  const filtered = filterSlaPolicyCandidateQualityRereviews(normalized, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const filters = {
    status: String(payload.status || "").trim(),
    owner: String(payload.owner || "").trim(),
    due: String(payload.due || payload.dueState || "").trim(),
    minScore: payload.minScore ?? "",
    maxScore: payload.maxScore ?? "",
    limit
  };
  const operationalQuality = await attachSlaPolicyCandidateQualityRereviewActionsToQuality(
    slaPolicyCandidateQualityRereviewOperationalQuality(filtered),
    actions,
    payload,
    actionReassessmentHistory,
    actionRecommendationAdjustments
  );
  const report = {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereviews",
    generatedAt: new Date().toISOString(),
    filters,
    summary: slaPolicyCandidateQualityRereviewSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewSummary(normalized),
    operationalQuality,
    items: filtered
      .sort((a, b) => Number(a.performanceScore || 0) - Number(b.performanceScore || 0) ||
        String(a.dueDate || "9999-99-99").localeCompare(String(b.dueDate || "9999-99-99")) ||
        String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
      .slice(0, limit),
    exportUrls: {
      json: slaPolicyCandidateQualityRereviewExportUrl(filters, "json"),
      csv: slaPolicyCandidateQualityRereviewExportUrl(filters, "csv")
    },
    reportBoundaries: {
      source: "admin-only SLA quality calibration re-review operations queue",
      hiddenFromBusiness: ["quality calibration re-review queue", "owners", "due dates", "follow-up actions", "operational memos", "change history", "operational quality metrics", "SLA warning levels", "history-based priority correction", "re-review action effect scores"]
    }
  };
  return {
    ...report,
    exportRows: slaPolicyCandidateQualityRereviewExportRows(report)
  };
}

async function slaPolicyCandidateQualityRereviewsReport(payload = {}) {
  const [data, logData, actionData, actionHistoryData, actionAdjustmentData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviews(),
    readSlaPolicyCandidateQualityRereviewLogs(),
    readSlaPolicyCandidateQualityRereviewActions(),
    readSlaPolicyCandidateQualityRereviewActionReassessmentHistory(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments()
  ]);
  return slaPolicyCandidateQualityRereviewReport(data.items || [], payload, logData.items || [], actionData.items || [], actionHistoryData.items || [], actionAdjustmentData.items || []);
}

async function applySlaPolicyCandidateQualityRereviewCompletion(rereview = {}, payload = {}) {
  if (rereview.status !== "completed") return null;
  const actionType = normalizeSlaPolicyCandidateQualityRereviewAction(rereview.followUpActionType);
  if (!rereview.calibrationId || actionType === "none" || actionType === "watch") return null;
  const data = await readSlaPolicyCandidateQualityCalibrations();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaPolicyCandidateQualityCalibration) : [];
  const target = items.find((item) => item.calibrationId === rereview.calibrationId);
  if (!target) return null;
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.completedBy || rereview.completedBy || "admin").trim() || "admin";
  let updatedTarget = target;
  if (actionType === "maintain_active") {
    updatedTarget = normalizeSlaPolicyCandidateQualityCalibration({
      ...target,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "rereview_maintained",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: target.status,
          reason: rereview.memo || rereview.reReviewReason
        }),
        ...(target.events || [])
      ]
    });
  } else if (actionType === "deactivate_active") {
    updatedTarget = normalizeSlaPolicyCandidateQualityCalibration({
      ...target,
      status: "deactivated",
      activeCalibration: null,
      reviewReason: rereview.memo || target.reviewReason,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "rereview_deactivated",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: "deactivated",
          reason: rereview.memo || rereview.reReviewReason
        }),
        ...(target.events || [])
      ]
    });
  } else if (actionType === "propose_modified_calibration") {
    const suggested = target.suggestedCalibration || {};
    const active = target.activeCalibration || suggested;
    updatedTarget = normalizeSlaPolicyCandidateQualityCalibration({
      ...target,
      status: "proposed",
      activeCalibration: null,
      suggestedCalibration: {
        ...suggested,
        direction: active?.direction || suggested.direction || "neutral",
        priorityAfter: active?.priorityAfter || suggested.priorityAfter || suggested.priorityBefore || "medium",
        reason: rereview.memo || `Re-review proposes modifying active calibration after performance score ${rereview.performanceScore}.`
      },
      reviewReason: rereview.memo || target.reviewReason,
      updatedAt: now,
      updatedBy: actor,
      events: [
        slaPolicyCandidateQualityCalibrationEvent({
          calibrationId: target.calibrationId,
          eventType: "rereview_modify_proposed",
          eventAt: now,
          eventBy: actor,
          previousStatus: target.status,
          nextStatus: "proposed",
          reason: rereview.memo || rereview.reReviewReason,
          overridePriorityAfter: active?.priorityAfter || ""
        }),
        ...(target.events || [])
      ]
    });
  }
  const updatedItems = items.map((item) => item.calibrationId === rereview.calibrationId ? updatedTarget : item);
  await writeSlaPolicyCandidateQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    ...updatedTarget,
    linkSummary: {
      calibrationId: target.calibrationId,
      actionType,
      previousStatus: target.status,
      nextStatus: updatedTarget.status,
      previousActive: Boolean(target.activeCalibration),
      nextActive: Boolean(updatedTarget.activeCalibration),
      changedAt: now,
      changedBy: actor
    }
  };
}

async function upsertSlaPolicyCandidateQualityRereview(payload = {}) {
  const rereviewId = String(payload.rereviewId || payload.id || "").trim();
  if (!rereviewId) {
    const error = new Error("SLA quality calibration re-review id is required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityRereviews();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaPolicyCandidateQualityRereview) : [];
  const existing = items.find((item) => item.rereviewId === rereviewId);
  if (!existing) {
    const error = new Error("SLA quality calibration re-review item not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.owner || "admin").trim() || "admin";
  const nextStatus = payload.status ? normalizeSlaPolicyCandidateQualityRereviewStatus(payload.status) : existing.status;
  const updated = normalizeSlaPolicyCandidateQualityRereview({
    ...existing,
    owner: payload.owner !== undefined ? payload.owner : existing.owner,
    dueDate: payload.dueDate !== undefined ? payload.dueDate : existing.dueDate,
    status: nextStatus,
    memo: payload.memo !== undefined ? payload.memo : existing.memo,
    followUpActionType: payload.followUpActionType !== undefined ? payload.followUpActionType : existing.followUpActionType,
    updatedAt: now,
    updatedBy: actor,
    completedAt: nextStatus === "completed" ? existing.completedAt || now : existing.completedAt,
    completedBy: nextStatus === "completed" ? String(payload.completedBy || actor).trim() : existing.completedBy,
    completionResult: nextStatus === "completed" ? normalizeSlaPolicyCandidateQualityRereviewAction(payload.followUpActionType || existing.followUpActionType) : existing.completionResult,
    events: [
      {
        eventType: nextStatus === "completed" ? "completed" : "updated",
        eventAt: now,
        eventBy: actor,
        previousStatus: existing.status,
        nextStatus,
        reason: String(payload.memo || payload.reason || "").trim(),
        followUpActionType: normalizeSlaPolicyCandidateQualityRereviewAction(payload.followUpActionType || existing.followUpActionType)
      },
      ...(existing.events || [])
    ]
  });
  const linkedCalibration = await applySlaPolicyCandidateQualityRereviewCompletion(updated, payload);
  const changedFields = slaPolicyCandidateQualityRereviewLogFields(existing, updated);
  const log = await appendSlaPolicyCandidateQualityRereviewLog({
    rereviewId: updated.rereviewId,
    calibrationId: updated.calibrationId,
    policyAdjustmentId: updated.policyAdjustmentId,
    eventType: nextStatus === "completed" ? "completed" : "updated",
    changedAt: now,
    changedBy: actor,
    fields: changedFields,
    before: {
      status: existing.status,
      owner: existing.owner,
      dueDate: existing.dueDate,
      memo: existing.memo,
      followUpActionType: existing.followUpActionType,
      completionResult: existing.completionResult
    },
    after: {
      status: updated.status,
      owner: updated.owner,
      dueDate: updated.dueDate,
      memo: updated.memo,
      followUpActionType: updated.followUpActionType,
      completionResult: updated.completionResult
    },
    completionResult: updated.completionResult,
    linkedCalibration: linkedCalibration?.linkSummary || null,
    memo: updated.memo
  });
  const updatedItems = items.map((item) => item.rereviewId === rereviewId ? updated : item);
  const saved = await writeSlaPolicyCandidateQualityRereviews({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || "")))
  });
  const [logData, actionData, actionHistoryData, actionAdjustmentData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviewLogs(),
    readSlaPolicyCandidateQualityRereviewActions(),
    readSlaPolicyCandidateQualityRereviewActionReassessmentHistory(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments()
  ]);
  const rereviews = await slaPolicyCandidateQualityRereviewReport(saved.items || [], {}, logData.items || [], actionData.items || [], actionHistoryData.items || [], actionAdjustmentData.items || []);
  return {
    ok: true,
    item: rereviews.items.find((item) => item.rereviewId === updated.rereviewId) || updated,
    log,
    linkedCalibration,
    rereviews,
    reportBoundaries: {
      source: "admin-only SLA quality calibration re-review update",
      hiddenFromBusiness: ["quality calibration re-review operations", "owners", "due dates", "memos", "follow-up actions", "change history", "active calibration linkage"]
    }
  };
}

function filterSlaPolicyCandidateQualityRereviewActions(items = [], payload = {}) {
  const status = normalizeCalibrationSlaActionStatusFilter(payload.status || payload.actionStatus || "");
  const owner = String(payload.owner || payload.assignee || payload.actionOwner || "").trim().toLowerCase();
  const month = String(payload.month || "").trim();
  const sourceType = String(payload.sourceType || "").trim();
  const priority = normalizeCalibrationSlaActionPriority(payload.priority || payload.actionPriority || "");
  const risk = normalizeCalibrationSlaActionRisk(payload.risk || payload.actionRisk || "");
  const dueState = String(payload.due || payload.dueState || payload.actionDue || "").trim();
  const targetDate = isoDate(payload.targetDate || payload.actionTargetDate || "");
  const issue = String(payload.issueKey || payload.rootMetric || payload.actionIssue || payload.actionRootMetric || "").trim().toLowerCase();
  const includeGenerated = String(payload.includeGenerated ?? payload.actionIncludeGenerated ?? "true").trim().toLowerCase() !== "false";
  return items
    .filter((item) => includeGenerated || item.isSaved)
    .filter((item) => !status || item.status === status)
    .filter((item) => !owner || (owner === "unassigned" && !(item.assignee || item.owner)) || String(item.assignee || item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !month || item.month === month || item.sourceType === "summary")
    .filter((item) => !sourceType || item.sourceType === sourceType)
    .filter((item) => !priority || item.priority === priority)
    .filter((item) => !risk || item.riskLevel === risk)
    .filter((item) => !dueState || item.dueState === dueState)
    .filter((item) => !targetDate || item.targetDate === targetDate)
    .filter((item) => !issue || [
      item.issueKey,
      item.rootMetric,
      item.sourceLabel,
      item.recommendation
    ].some((value) => String(value || "").toLowerCase().includes(issue)));
}

async function slaPolicyCandidateQualityRereviewActionsReport(payload = {}) {
  const report = await slaPolicyCandidateQualityRereviewsReport({
    status: payload.rereviewStatus,
    owner: payload.rereviewOwner,
    due: payload.rereviewDue,
    minScore: payload.rereviewMinScore,
    maxScore: payload.rereviewMaxScore,
    limit: payload.limit
  });
  const allItems = report.operationalQuality?.slaActions?.items || [];
  const filtered = filterSlaPolicyCandidateQualityRereviewActions(allItems, payload);
  return {
    role: "admin",
    reportType: "sla_policy_candidate_quality_rereview_actions",
    generatedAt: new Date().toISOString(),
    filters: {
      status: normalizeCalibrationSlaActionStatusFilter(payload.status || ""),
      owner: String(payload.owner || payload.assignee || "").trim(),
      month: String(payload.month || "").trim(),
      sourceType: String(payload.sourceType || "").trim(),
      priority: normalizeCalibrationSlaActionPriority(payload.priority || ""),
      risk: normalizeCalibrationSlaActionRisk(payload.risk || ""),
      due: String(payload.due || payload.dueState || "").trim(),
      targetDate: String(payload.targetDate || "").trim(),
      issue: String(payload.issueKey || payload.rootMetric || "").trim(),
      includeGenerated: String(payload.includeGenerated ?? "true")
    },
    summary: slaPolicyCandidateQualityRereviewActionSummary(filtered),
    fullSummary: slaPolicyCandidateQualityRereviewActionSummary(allItems),
    operationQueue: {
      summary: slaPolicyCandidateQualityRereviewActionQueueSummary(filterSlaPolicyCandidateQualityRereviewActions(allItems, {
        ...payload,
        includeGenerated: false
      })),
      fullSummary: slaPolicyCandidateQualityRereviewActionQueueSummary(allItems.filter((item) => item.isSaved)),
      focus: slaPolicyCandidateQualityRereviewActionQueueFocus(filterSlaPolicyCandidateQualityRereviewActions(allItems, {
        ...payload,
        includeGenerated: false
      })),
      items: filterSlaPolicyCandidateQualityRereviewActions(allItems, {
        ...payload,
        includeGenerated: false
      })
    },
    items: filtered,
    postReassessment: report.operationalQuality?.slaActions?.postReassessment || { summary: {}, items: [] },
    operationalQuality: report.operationalQuality,
    reportBoundaries: {
      source: "admin-only SLA quality re-review improvement action candidates and saved actions",
      hiddenFromBusiness: ["re-review SLA action candidates", "owners", "target dates", "recommended corrective actions", "SLA source metrics", "history-based priority correction", "re-review action effect scores"]
    }
  };
}

function compactSlaPolicyCandidateQualityRereviewQualitySnapshot(row = {}) {
  if (!row || typeof row !== "object") return null;
  return {
    key: row.key || "",
    label: row.label || "",
    total: row.total || 0,
    completed: row.completed || 0,
    completionRate: row.completionRate || 0,
    avgProcessingHours: row.avgProcessingHours,
    reopenRate: row.reopenRate || 0,
    delayedIncompleteItems: row.delayedIncompleteItems || 0,
    activeLinkRequired: row.activeLinkRequired || 0,
    activeLinkUnprocessed: row.activeLinkUnprocessed || 0,
    activeLinkUnprocessedRate: row.activeLinkUnprocessedRate || 0,
    activeLinkFailed: row.activeLinkFailed || 0,
    activeLinkFailedRate: row.activeLinkFailedRate || 0,
    activeLinkIssue: row.activeLinkIssue || 0,
    activeLinkIssueRate: row.activeLinkIssueRate || 0,
    sla: row.sla
      ? {
          level: row.sla.level || "",
          label: row.sla.label || "",
          improvementItems: row.sla.improvementItems || []
        }
      : null
  };
}

async function slaPolicyCandidateQualityRereviewActionCompletionSnapshot(action = {}) {
  const [data, logData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviews(),
    readSlaPolicyCandidateQualityRereviewLogs()
  ]);
  const report = await slaPolicyCandidateQualityRereviewReport(data.items || [], {}, logData.items || [], []);
  const quality = report.operationalQuality || {};
  const actionMonth = action.month || monthKey(action.targetDate) || "";
  const actionOwner = action.owner || action.assignee || "";
  const monthRow = (quality.monthly || []).find((row) => row.key === actionMonth || row.label === actionMonth) || null;
  const ownerRow = (quality.ownerPerformance || []).find((row) => row.key === actionOwner || row.label === actionOwner) || null;
  return {
    capturedAt: new Date().toISOString(),
    actionId: action.actionId || "",
    sourceKey: action.sourceKey || "",
    status: action.status || "",
    assignee: action.assignee || "",
    targetDate: action.targetDate || "",
    priority: action.priority || "",
    riskLevel: action.riskLevel || "",
    issueKey: action.issueKey || "",
    rootMetric: action.rootMetric || "",
    summary: compactSlaPolicyCandidateQualityRereviewQualitySnapshot(quality.summary || {}),
    month: compactSlaPolicyCandidateQualityRereviewQualitySnapshot(monthRow || {}),
    owner: compactSlaPolicyCandidateQualityRereviewQualitySnapshot(ownerRow || {}),
    sourceMetrics: action.sourceMetrics || {},
    reportBoundaries: {
      source: "admin-only SLA quality re-review operational quality snapshot at action completion",
      hiddenFromBusiness: ["re-review operational quality", "SLA action completion evidence", "owner workload and SLA warning details"]
    }
  };
}

async function upsertSlaPolicyCandidateQualityRereviewAction(payload = {}) {
  const data = await readSlaPolicyCandidateQualityRereviewActions();
  const items = Array.isArray(data.items) ? data.items : [];
  const existing = items.find((item) => item.actionId === payload.actionId || (payload.sourceKey && item.sourceKey === payload.sourceKey));
  const now = new Date().toISOString();
  let action = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
    ...(existing || {}),
    ...payload,
    createdAt: existing?.createdAt || payload.createdAt || now,
    createdBy: existing?.createdBy || payload.createdBy || payload.updatedBy || "admin",
    updatedAt: now,
    updatedBy: payload.updatedBy || payload.changedBy || "admin"
  });
  if (action.status === "done") {
    action = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
      ...action,
      completedAt: existing?.completedAt || payload.completedAt || now,
      completedBy: payload.updatedBy || payload.changedBy || payload.completedBy || "admin"
    });
    if (!existing?.completionQualitySnapshot || existing.status !== "done" || payload.refreshCompletionSnapshot) {
      action = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
        ...action,
        completionQualitySnapshot: await slaPolicyCandidateQualityRereviewActionCompletionSnapshot({
          ...action,
          riskLevel: calibrationSlaActionRiskLevel(action)
        })
      });
    }
  }
  const updated = await writeSlaPolicyCandidateQualityRereviewActions({
    ...data,
    items: [
      action,
      ...items.filter((item) => item.actionId !== action.actionId && item.sourceKey !== action.sourceKey)
    ]
  });
  return {
    ok: true,
    slaPolicyCandidateQualityRereviewActions: {
      schema: updated.schema || "sla_policy_candidate_quality_rereview_actions_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    action,
    actions: await slaPolicyCandidateQualityRereviewActionsReport({ limit: 200 }),
    reportBoundaries: {
      source: "admin-only SLA quality re-review improvement action update",
      hiddenFromBusiness: ["re-review SLA action candidates", "owners", "target dates", "recommended corrective actions", "SLA source metrics"]
    }
  };
}

