async function createSlaPolicyCandidateQualityRereviewActionFollowUp(payload = {}) {
  const actionId = String(payload.actionId || payload.parentActionId || "").trim();
  if (!actionId) {
    const error = new Error("Completed re-review SLA action id is required.");
    error.statusCode = 400;
    throw error;
  }
  const reassessmentReport = await slaPolicyCandidateQualityRereviewActionReassessmentReport({
    followUpNeeded: payload.followUpNeeded || "",
    limit: 200
  });
  const reassessment = (reassessmentReport.items || []).find((item) => item.actionId === actionId);
  if (!reassessment) {
    const error = new Error("Completed re-review SLA action reassessment not found.");
    error.statusCode = 404;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityRereviewActions();
  const items = Array.isArray(data.items) ? data.items : [];
  const sourceAction = items.map(normalizeSlaPolicyCandidateQualityRereviewSlaAction)
    .find((item) => item.actionId === actionId);
  if (!sourceAction) {
    const error = new Error("Source re-review SLA action not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const actor = String(payload.updatedBy || payload.createdBy || "admin").trim() || "admin";
  const sourceKey = [
    "rereview_sla_followup",
    sourceAction.sourceKey || sourceAction.actionId,
    reassessment.outcome,
    monthKey(now) || kstDate(0)
  ].join("|");
  const existing = items.find((item) => item.sourceKey === sourceKey);
  const priority = reassessment.outcome === "worse" || reassessment.recurrence ? "urgent" : "high";
  const followUp = normalizeSlaPolicyCandidateQualityRereviewSlaAction({
    ...(existing || {}),
    actionId: existing?.actionId || hashId("spcqra", sourceKey),
    sourceKey,
    sourceType: sourceAction.sourceType || "summary",
    sourceLabel: `${sourceAction.sourceLabel || "Re-review SLA action"} follow-up`,
    month: sourceAction.month || monthKey(sourceAction.targetDate) || "",
    owner: sourceAction.owner || sourceAction.assignee || "",
    slaLevel: reassessment.outcome === "worse" || reassessment.current?.sla?.level === "danger" ? "danger" : "warning",
    issueKey: sourceAction.issueKey || reassessment.issueKey || "",
    severity: reassessment.outcome === "worse" || reassessment.current?.sla?.level === "danger" ? "danger" : "warning",
    rootMetric: sourceAction.rootMetric || reassessment.metric?.key || "",
    recommendation: payload.recommendation || reassessment.suggestedFollowUp,
    priority,
    assignee: payload.assignee || sourceAction.assignee || sourceAction.owner || "",
    targetDate: payload.targetDate || kstDate(priority === "urgent" ? 3 : 7),
    status: payload.status || "planned",
    parentActionId: sourceAction.actionId,
    followUpForActionId: sourceAction.actionId,
    followUpReason: payload.followUpReason || reassessment.followUpReason,
    reassessmentId: reassessment.reassessmentId,
    reassessmentOutcome: reassessment.outcome,
    sourceMetrics: {
      metric: reassessment.metric,
      baseline: reassessment.baseline,
      current: reassessment.current,
      comparison: reassessment.comparison,
      effectScore: reassessment.effectScore,
      recurrence: reassessment.recurrence,
      followUpNeeded: reassessment.followUpNeeded
    },
    createdAt: existing?.createdAt || now,
    createdBy: existing?.createdBy || actor,
    updatedAt: now,
    updatedBy: actor
  });
  const saved = await writeSlaPolicyCandidateQualityRereviewActions({
    ...data,
    items: [
      followUp,
      ...items.filter((item) => item.actionId !== followUp.actionId && item.sourceKey !== followUp.sourceKey)
    ]
  });
  const historyUpdate = await markSlaPolicyCandidateQualityRereviewActionReassessmentHistoryFollowUp(
    reassessment,
    followUp,
    actor
  );
  return {
    ok: true,
    followUp,
    reassessment,
    slaPolicyCandidateQualityRereviewActions: {
      schema: saved.schema || "sla_policy_candidate_quality_rereview_actions_v1",
      total: saved.items.length,
      updatedAt: saved.updatedAt
    },
    slaPolicyCandidateQualityRereviewActionReassessmentHistory: historyUpdate.slaPolicyCandidateQualityRereviewActionReassessmentHistory,
    actions: await slaPolicyCandidateQualityRereviewActionsReport({ includeGenerated: false, limit: 200 }),
    reportBoundaries: {
      source: "admin-only follow-up action created from re-review SLA post-completion reassessment",
      hiddenFromBusiness: ["post-completion reassessment", "effect score", "recurrence reason", "follow-up action linkage"]
    }
  };
}

async function slaPolicyCandidateQualityCalibrationsReport(payload = {}) {
  const data = await readSlaPolicyCandidateQualityCalibrations();
  return slaPolicyCandidateQualityCalibrationWorkflowReport(data.items || [], payload);
}

async function reviewSlaPolicyCandidateQualityCalibration(payload = {}) {
  const calibrationId = String(payload.calibrationId || payload.id || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  const status = decision === "override" ? "overridden" : normalizeSlaPolicyCandidateQualityCalibrationStatus(decision);
  if (!calibrationId || !["approved", "rejected", "overridden"].includes(status)) {
    const error = new Error("Calibration id and approved/rejected/override decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaPolicyCandidateQualityCalibrations();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaPolicyCandidateQualityCalibration) : [];
  const target = items.find((item) => item.calibrationId === calibrationId);
  if (!target) {
    const error = new Error("SLA policy candidate quality calibration proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const reviewReason = String(payload.reviewReason || payload.reason || "").trim();
  const overrideReason = String(payload.overrideReason || "").trim();
  const suggested = target.suggestedCalibration || {};
  let activeCalibration = null;
  if (status === "approved") {
    activeCalibration = {
      ...suggested,
      applied: suggested.direction !== "neutral" && suggested.priorityAfter !== suggested.priorityBefore,
      reason: reviewReason || suggested.reason || "Admin approved suggested quality calibration."
    };
  } else if (status === "overridden") {
    const priorityBefore = normalizeCalibrationSlaActionPriority(suggested.priorityBefore || "medium") || "medium";
    const overridePriorityAfter = normalizeCalibrationSlaActionPriority(payload.overridePriorityAfter || payload.priorityAfter || suggested.priorityAfter || priorityBefore) || priorityBefore;
    const beforeRank = calibrationSlaActionPriorityRank(priorityBefore);
    const afterRank = calibrationSlaActionPriorityRank(overridePriorityAfter);
    activeCalibration = {
      ...suggested,
      direction: afterRank < beforeRank ? "boost" : afterRank > beforeRank ? "downgrade" : "neutral",
      priorityAfter: overridePriorityAfter,
      applied: overridePriorityAfter !== priorityBefore,
      reason: overrideReason || reviewReason || `Admin override set active priority ${priorityBefore} -> ${overridePriorityAfter}.`
    };
  }
  const updatedTarget = normalizeSlaPolicyCandidateQualityCalibration({
    ...target,
    status,
    activeCalibration,
    simulation: slaPolicyCandidateQualityCalibrationSimulation(
      {
        priority: suggested.priorityBefore,
        recommendation: target.simulation?.recommendationBefore || "",
        expectedImpact: target.simulation?.expectedImpactBefore || {}
      },
      suggested,
      activeCalibration
    ),
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason,
    overrideReason,
    updatedAt: now,
    updatedBy: reviewer,
    events: [
      slaPolicyCandidateQualityCalibrationEvent({
        calibrationId,
        eventType: status,
        eventAt: now,
        eventBy: reviewer,
        previousStatus: target.status,
        nextStatus: status,
        reason: reviewReason,
        overridePriorityAfter: activeCalibration?.priorityAfter || "",
        overrideReason
      }),
      ...(target.events || [])
    ]
  });
  const updatedItems = items.map((item) => item.calibrationId === calibrationId ? updatedTarget : item);
  await writeSlaPolicyCandidateQualityCalibrations({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    ok: true,
    item: updatedTarget,
    workflow: slaPolicyCandidateQualityCalibrationWorkflowReport(updatedItems, {}),
    reportBoundaries: {
      source: "admin-only SLA policy candidate quality calibration review decision",
      hiddenFromBusiness: ["quality calibration approval status", "override reason", "candidate quality evidence", "review events"]
    }
  };
}

function slaPolicyEffectReportItem(policyAdjustment = {}, performanceItems = [], proposalItems = [], payload = {}) {
  const approvedAt = policyAdjustment.approvedAt || policyAdjustment.reviewedAt || policyAdjustment.updatedAt || "";
  const approvedTime = slaPolicyEffectTime(approvedAt);
  const windowDays = Math.max(7, Math.min(365, Number(payload.windowDays || 90)));
  const windowMs = windowDays * 24 * 60 * 60 * 1000;
  const beforeStart = Number.isFinite(approvedTime) ? approvedTime - windowMs : null;
  const beforeEnd = approvedTime;
  const afterStart = approvedTime;
  const afterEnd = Number.isFinite(approvedTime) ? approvedTime + windowMs : null;
  const matchesScope = slaPolicyEffectScopeMatcher(policyAdjustment);
  const scopedPerformance = performanceItems.filter(matchesScope);
  const scopedProposals = proposalItems.filter(matchesScope);
  const beforePerformance = scopedPerformance
    .filter((item) => slaPolicyEffectWindowContains(item.approvedAt, beforeStart, beforeEnd))
    .map((item) => slaPolicyEffectWindowedPerformanceItem(item, beforeStart, beforeEnd));
  const afterPerformance = scopedPerformance
    .filter((item) => slaPolicyEffectWindowContains(item.approvedAt, afterStart, afterEnd))
    .map((item) => slaPolicyEffectWindowedPerformanceItem(item, afterStart, afterEnd));
  const beforeProposals = scopedProposals.filter((item) => slaPolicyEffectWindowContains(slaPolicyEffectTimestamp(item), beforeStart, beforeEnd));
  const afterProposals = scopedProposals.filter((item) => slaPolicyEffectWindowContains(slaPolicyEffectTimestamp(item), afterStart, afterEnd));
  const before = slaPolicyEffectMetrics(beforePerformance, beforeProposals);
  const after = slaPolicyEffectMetrics(afterPerformance, afterProposals);
  const delta = slaPolicyEffectMetricDelta(before, after);
  const effectScore = slaPolicyEffectScore(policyAdjustment, before, after, delta);
  const outcome = slaPolicyEffectOutcome(effectScore, before, after);
  const suggestions = slaPolicyEffectSuggestions(policyAdjustment, before, after, delta, outcome);
  return {
    policyAdjustmentId: policyAdjustment.policyAdjustmentId,
    candidateType: policyAdjustment.candidateType,
    target: policyAdjustment.target,
    issueKey: policyAdjustment.issueKey,
    priority: policyAdjustment.priority,
    approvedAt,
    approvedBy: policyAdjustment.reviewedBy || policyAdjustment.updatedBy || "",
    windowDays,
    beforeWindow: {
      start: beforeStart ? new Date(beforeStart).toISOString() : "",
      end: beforeEnd ? new Date(beforeEnd).toISOString() : ""
    },
    afterWindow: {
      start: afterStart ? new Date(afterStart).toISOString() : "",
      end: afterEnd ? new Date(afterEnd).toISOString() : ""
    },
    before,
    after,
    delta,
    effectScore,
    outcome,
    suggestions,
    sourceBeforePolicy: policyAdjustment.beforePolicy || {},
    sourceAfterPolicy: policyAdjustment.afterPolicy || {},
    sourcePolicyPatch: policyAdjustment.policyPatch || {},
    rollbackSuggested: suggestions.some((item) => item.type === "rollback_policy_adjustment"),
    additionalAdjustmentSuggested: suggestions.some((item) => ["consider_partial_relaxation", "additional_tightening"].includes(item.type)),
    sourceCounts: {
      scopedPerformanceItems: scopedPerformance.length,
      scopedProposalItems: scopedProposals.length,
      beforePerformanceItems: beforePerformance.length,
      afterPerformanceItems: afterPerformance.length,
      beforeProposalItems: beforeProposals.length,
      afterProposalItems: afterProposals.length
    }
  };
}

function filterSlaPolicyEffectItems(items = [], payload = {}) {
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  const outcome = String(payload.outcome || "").trim().toLowerCase();
  return items
    .filter((item) => !target || String(item.target || item.issueKey || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type)
    .filter((item) => !outcome || item.outcome === outcome);
}

function slaPolicyEffectSummary(items = []) {
  return {
    total: items.length,
    pending: items.filter((item) => item.outcome === "pending").length,
    improved: items.filter((item) => item.outcome === "improved").length,
    unchanged: items.filter((item) => item.outcome === "unchanged").length,
    worse: items.filter((item) => item.outcome === "worse").length,
    rollbackSuggested: items.filter((item) => item.rollbackSuggested).length,
    additionalAdjustmentSuggested: items.filter((item) => item.additionalAdjustmentSuggested).length,
    avgEffectScore: items.filter((item) => item.effectScore !== null && item.effectScore !== undefined).length
      ? Math.round(items.filter((item) => item.effectScore !== null && item.effectScore !== undefined).reduce((sum, item) => sum + Number(item.effectScore || 0), 0) / items.filter((item) => item.effectScore !== null && item.effectScore !== undefined).length)
      : 0,
    avgSuccessRateDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.successRate || 0), 0) / items.length) : 0,
    avgFalsePositiveDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.falsePositiveRate || 0), 0) / items.length) : 0,
    avgManualReviewDelta: items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.delta?.manualReviewConversionRate || 0), 0) / items.length) : 0
  };
}

function isSlaPolicyEffectGeneratedAdjustment(item = {}) {
  return item.sourceContext?.source === "sla_policy_effectiveness" ||
    Boolean(item.sourcePolicyAdjustmentId) ||
    ["rollback_policy_adjustment", "partial_relaxation_policy", "additional_tightening_policy"].includes(item.candidateType);
}

function slaPolicyCandidateQualityOutcome(candidate = {}, postEffect = null) {
  if (candidate.status === "rejected") return "rejected";
  if (candidate.status !== "approved") return "pending_review";
  if (!postEffect || postEffect.outcome === "pending") return "pending_effect";
  if (postEffect.outcome === "improved") return "successful";
  if (postEffect.outcome === "worse") return "failed";
  return "neutral";
}

function slaPolicyCandidateQualityRepeat(candidate = {}, postEffect = null) {
  const postSuggestionTypes = (postEffect?.suggestions || [])
    .map((suggestion) => slaPolicyEffectSuggestionCandidateType(suggestion.type))
    .filter(Boolean);
  const sameTypeSuggested = postSuggestionTypes.includes(candidate.candidateType);
  const rejectedHighRisk = candidate.status === "rejected" &&
    ["worse", "pending"].includes(candidate.sourceEffectOutcome) &&
    ["high", "urgent"].includes(candidate.priority);
  const failedApproved = candidate.status === "approved" && postEffect?.outcome === "worse";
  return {
    repeatRecommended: Boolean(sameTypeSuggested || rejectedHighRisk || failedApproved),
    reason: sameTypeSuggested
      ? "Post-approval effect generated the same candidate type again."
      : rejectedHighRisk
        ? "Rejected high-risk source effect still indicates weak policy performance."
        : failedApproved
          ? "Approved candidate produced worse post-change effectiveness."
          : ""
  };
}

function slaPolicyCandidateQualityItem(candidate = {}, effectByPolicyId = new Map()) {
  const postEffect = effectByPolicyId.get(candidate.policyAdjustmentId) || null;
  const repeat = slaPolicyCandidateQualityRepeat(candidate, postEffect);
  const outcome = slaPolicyCandidateQualityOutcome(candidate, postEffect);
  return {
    policyAdjustmentId: candidate.policyAdjustmentId,
    candidateType: candidate.candidateType,
    target: candidate.target,
    issueKey: candidate.issueKey,
    priority: candidate.priority,
    status: candidate.status,
    sourcePolicyAdjustmentId: candidate.sourcePolicyAdjustmentId || candidate.sourceContext?.policyAdjustmentId || "",
    sourceEffectOutcome: candidate.sourceEffectOutcome || candidate.sourceContext?.outcome || "",
    sourceEffectScore: candidate.sourceEffectScore,
    proposedAt: candidate.proposedAt,
    reviewedAt: candidate.reviewedAt,
    reviewedBy: candidate.reviewedBy,
    reviewReason: candidate.reviewReason,
    postEffectOutcome: postEffect?.outcome || "",
    postEffectScore: postEffect?.effectScore ?? null,
    postEffectDelta: postEffect?.delta || {},
    qualityOutcome: outcome,
    successful: outcome === "successful",
    evaluated: ["successful", "failed", "neutral"].includes(outcome),
    repeatRecommended: repeat.repeatRecommended,
    repeatRecommendationReason: repeat.reason
  };
}

function slaPolicyCandidateQualityGroup(items = [], candidateType = "all") {
  const total = items.length;
  const approved = items.filter((item) => item.status === "approved").length;
  const rejected = items.filter((item) => item.status === "rejected").length;
  const proposed = items.filter((item) => item.status === "proposed").length;
  const evaluated = items.filter((item) => item.evaluated).length;
  const successful = items.filter((item) => item.successful).length;
  const failed = items.filter((item) => item.qualityOutcome === "failed").length;
  const repeatRecommended = items.filter((item) => item.repeatRecommended).length;
  const rejectionReasonMap = new Map();
  items
    .filter((item) => item.status === "rejected")
    .forEach((item) => {
      const reason = item.reviewReason || "No rejection reason recorded.";
      rejectionReasonMap.set(reason, (rejectionReasonMap.get(reason) || 0) + 1);
    });
  return {
    candidateType,
    total,
    proposed,
    approved,
    rejected,
    evaluated,
    successful,
    failed,
    repeatRecommended,
    approvalRate: approved + rejected ? Math.round((approved / (approved + rejected)) * 100) : 0,
    approvalSuccessRate: evaluated ? Math.round((successful / evaluated) * 100) : 0,
    rejectionReasons: [...rejectionReasonMap.entries()]
      .map(([reason, count]) => ({ reason, count }))
      .sort((a, b) => b.count - a.count || String(a.reason).localeCompare(String(b.reason)))
      .slice(0, 8)
  };
}

function slaPolicyCandidateQualityReport(policyAdjustments = [], effectItems = [], payload = {}) {
  const effectByPolicyId = new Map(effectItems.map((item) => [item.policyAdjustmentId, item]));
  const allItems = policyAdjustments
    .map(normalizeSlaAutoApprovalPolicyAdjustment)
    .filter(isSlaPolicyEffectGeneratedAdjustment)
    .map((item) => slaPolicyCandidateQualityItem(item, effectByPolicyId));
  const target = String(payload.target || payload.issueKey || "").trim().toLowerCase();
  const type = String(payload.type || payload.candidateType || "").trim().toLowerCase();
  const filtered = allItems
    .filter((item) => !target || String(item.target || item.issueKey || "").toLowerCase().includes(target))
    .filter((item) => !type || item.candidateType === type);
  const byType = [...new Set(allItems.map((item) => item.candidateType || "unknown"))]
    .sort()
    .map((candidateType) => slaPolicyCandidateQualityGroup(filtered.filter((item) => item.candidateType === candidateType), candidateType))
    .filter((row) => row.total > 0);
  return {
    summary: slaPolicyCandidateQualityGroup(filtered, "all"),
    byType,
    items: filtered
      .sort((a, b) => {
        return Number(b.repeatRecommended || 0) - Number(a.repeatRecommended || 0) ||
          String(b.reviewedAt || b.proposedAt || "").localeCompare(String(a.reviewedAt || a.proposedAt || ""));
      })
      .slice(0, Math.max(1, Math.min(500, Number(payload.limit || 120))))
  };
}

async function slaAutoApprovalPolicyEffectivenessReport(payload = {}) {
  const [policyData, adjustmentData, historyData, logData, qualityCalibrationData] = await Promise.all([
    readSlaAutoApprovalPolicyAdjustments(),
    readSlaActionRecommendationAdjustments(),
    readSlaActionReassessmentHistory(),
    readSlaActionRecommendationAutoApprovalLogs(),
    readSlaPolicyCandidateQualityCalibrations()
  ]);
  const approvedPolicies = (policyData.items || [])
    .map(normalizeSlaAutoApprovalPolicyAdjustment)
    .filter((item) => item.status === "approved");
  const proposalItems = (adjustmentData.items || []).map(normalizeSlaActionRecommendationAdjustment);
  const historyItems = historyData.items || [];
  const logs = (logData.items || []).map(normalizeSlaActionRecommendationAutoApprovalLog);
  const performanceItems = proposalItems
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible)
    .map((item) => slaAutoApprovalPerformanceItem(item, historyItems, logs));
  const effectItems = approvedPolicies
    .map((item) => slaPolicyEffectReportItem(item, performanceItems, proposalItems, payload))
    .sort((a, b) => {
      const outcomeRank = { worse: 0, pending: 1, unchanged: 2, improved: 3 };
      return (outcomeRank[a.outcome] ?? 9) - (outcomeRank[b.outcome] ?? 9) ||
        String(b.approvedAt || "").localeCompare(String(a.approvedAt || ""));
  });
  const activePolicy = activeSlaAutoApprovalPolicy(policyData.items || []);
  const candidateQualityBasis = slaPolicyCandidateQualityReport(policyData.items || [], effectItems, payload);
  const draftEffectGeneratedCandidates = slaPolicyEffectAdjustmentCandidates(effectItems, candidateQualityBasis, qualityCalibrationData.items || []);
  const qualityCalibrationProposals = await upsertSlaPolicyCandidateQualityCalibrationProposals(draftEffectGeneratedCandidates);
  const qualityCalibrationWorkflow = slaPolicyCandidateQualityCalibrationWorkflowReport(qualityCalibrationProposals, payload);
  const effectGeneratedCandidates = slaPolicyEffectAdjustmentCandidates(effectItems, candidateQualityBasis, qualityCalibrationProposals);
  const effectGeneratedProposals = effectGeneratedCandidates.length
    ? await upsertSlaAutoApprovalPolicyAdjustmentProposals(effectGeneratedCandidates, activePolicy)
    : [];
  const annotatedEffectItems = attachSlaPolicyEffectGeneratedProposals(effectItems, effectGeneratedCandidates, effectGeneratedProposals);
  const policyAdjustmentsForQuality = new Map((policyData.items || [])
    .map(normalizeSlaAutoApprovalPolicyAdjustment)
    .map((item) => [item.policyAdjustmentId, item]));
  effectGeneratedProposals.forEach((item) => {
    policyAdjustmentsForQuality.set(item.policyAdjustmentId, normalizeSlaAutoApprovalPolicyAdjustment(item));
  });
  const effectCandidateQuality = slaPolicyCandidateQualityReport([...policyAdjustmentsForQuality.values()], annotatedEffectItems, payload);
  const qualityCalibrationPerformance = slaPolicyCandidateQualityCalibrationPerformanceReport(
    qualityCalibrationProposals,
    [...policyAdjustmentsForQuality.values()],
    annotatedEffectItems,
    payload
  );
  await upsertSlaPolicyCandidateQualityRereviewCandidates(qualityCalibrationPerformance);
  const [qualityRereviewData, qualityRereviewLogData, qualityRereviewActionData, qualityRereviewActionHistoryData, qualityRereviewActionAdjustmentData] = await Promise.all([
    readSlaPolicyCandidateQualityRereviews(),
    readSlaPolicyCandidateQualityRereviewLogs(),
    readSlaPolicyCandidateQualityRereviewActions(),
    readSlaPolicyCandidateQualityRereviewActionReassessmentHistory(),
    readSlaPolicyCandidateQualityRereviewActionRecommendationAdjustments()
  ]);
  const qualityCalibrationRereviews = await slaPolicyCandidateQualityRereviewReport(qualityRereviewData.items || [], {
    status: payload.rereviewStatus,
    owner: payload.rereviewOwner,
    due: payload.rereviewDue,
    minScore: payload.rereviewMinScore,
    maxScore: payload.rereviewMaxScore,
    actionStatus: payload.rereviewActionStatus,
    actionOwner: payload.rereviewActionOwner,
    actionDue: payload.rereviewActionDue,
    actionTargetDate: payload.rereviewActionTargetDate,
    actionPriority: payload.rereviewActionPriority,
    actionRisk: payload.rereviewActionRisk,
    actionIssue: payload.rereviewActionIssue,
    actionIncludeGenerated: payload.rereviewActionIncludeGenerated,
    reassessmentOwner: payload.rereviewActionOwner,
    reassessmentIssue: payload.rereviewActionIssue,
    reassessmentOutcome: payload.rereviewActionReassessmentOutcome,
    reassessmentFollowUpNeeded: payload.rereviewActionFollowUpNeeded,
    limit: payload.limit
  }, qualityRereviewLogData.items || [], qualityRereviewActionData.items || [], qualityRereviewActionHistoryData.items || [], qualityRereviewActionAdjustmentData.items || []);
  const rereviewReassessmentItems = qualityCalibrationRereviews.operationalQuality?.slaActions?.postReassessment?.items || [];
  const rereviewReassessmentHistoryWrite = await upsertSlaPolicyCandidateQualityRereviewActionReassessmentHistoryItems(rereviewReassessmentItems, {
    recordedBy: "system"
  });
  const rereviewReassessmentHistory = await slaPolicyCandidateQualityRereviewActionReassessmentHistoryReport({
    owner: payload.rereviewActionOwner,
    issueKey: payload.rereviewActionIssue,
    outcome: payload.rereviewActionReassessmentOutcome,
    followUp: payload.rereviewActionFollowUpNeeded,
    limit: payload.limit
  });
  if (qualityCalibrationRereviews.operationalQuality?.slaActions?.postReassessment) {
    qualityCalibrationRereviews.operationalQuality.slaActions.postReassessment.historyWrite = rereviewReassessmentHistoryWrite.slaPolicyCandidateQualityRereviewActionReassessmentHistory;
    qualityCalibrationRereviews.operationalQuality.slaActions.postReassessment.history = rereviewReassessmentHistory;
  }
  const filtered = filterSlaPolicyEffectItems(annotatedEffectItems, payload);
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  return {
    role: "admin",
    reportType: "sla_auto_approval_policy_effectiveness",
    generatedAt: new Date().toISOString(),
    filters: {
      target: String(payload.target || payload.issueKey || "").trim(),
      type: String(payload.type || payload.candidateType || "").trim(),
      outcome: String(payload.outcome || "").trim(),
      rereviewStatus: String(payload.rereviewStatus || "").trim(),
      rereviewOwner: String(payload.rereviewOwner || "").trim(),
      rereviewDue: String(payload.rereviewDue || "").trim(),
      rereviewMaxScore: String(payload.rereviewMaxScore || "").trim(),
      windowDays: Math.max(7, Math.min(365, Number(payload.windowDays || 90))),
      limit
    },
    summary: slaPolicyEffectSummary(filtered),
    fullSummary: slaPolicyEffectSummary(annotatedEffectItems),
    effectGeneratedCandidates: effectGeneratedCandidates.slice(0, limit),
    effectGeneratedProposals: effectGeneratedProposals.slice(0, limit),
    candidateQualityBasis,
    qualityCalibrationWorkflow,
    qualityCalibrationPerformance,
    qualityCalibrationRereviews,
    effectCandidateQuality,
    items: filtered.slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA auto approval policy post-change effectiveness tracking",
      hiddenFromBusiness: ["auto approval policy effectiveness", "policy adjustment ids", "rollback suggestions", "manual review conversion", "effect-based policy candidates", "operator quality outcomes"]
    }
  };
}

async function reviewSlaAutoApprovalPolicyAdjustment(payload = {}) {
  const policyAdjustmentId = String(payload.policyAdjustmentId || payload.adjustmentId || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  if (!policyAdjustmentId || !["approved", "rejected"].includes(decision)) {
    const error = new Error("Policy adjustment id and approved/rejected decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaAutoApprovalPolicyAdjustments();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaAutoApprovalPolicyAdjustment) : [];
  const target = items.find((item) => item.policyAdjustmentId === policyAdjustmentId);
  if (!target) {
    const error = new Error("SLA auto approval policy adjustment proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const updatedTarget = normalizeSlaAutoApprovalPolicyAdjustment({
    ...target,
    status: decision,
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason: String(payload.reviewReason || payload.reason || "").trim(),
    approvedAt: decision === "approved" ? now : "",
    rejectedAt: decision === "rejected" ? now : "",
    updatedAt: now,
    updatedBy: reviewer
  });
  const updatedItems = items.map((item) => item.policyAdjustmentId === policyAdjustmentId ? updatedTarget : item);
  await writeSlaAutoApprovalPolicyAdjustments({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    ok: true,
    item: updatedTarget,
    activePolicy: activeSlaAutoApprovalPolicy(updatedItems),
    reportBoundaries: {
      source: "admin-only SLA auto approval policy review decision",
      hiddenFromBusiness: ["auto approval policy review decisions", "policy threshold patches", "review history"]
    }
  };
}

function filterSlaAutoApprovalPerformanceItems(items = [], payload = {}) {
  const month = String(payload.month || "").trim();
  const owner = String(payload.owner || "").trim().toLowerCase();
  const issueKey = String(payload.issueKey || "").trim();
  const outcome = String(payload.outcome || "").trim().toLowerCase();
  return items
    .filter((item) => !month || item.approvalMonth === month || item.linkedHistory.some((history) => history.evaluatedMonth === month))
    .filter((item) => !owner || String(item.owner || "").toLowerCase().includes(owner))
    .filter((item) => !issueKey || item.issueKey === issueKey || item.rootMetric.includes(issueKey))
    .filter((item) => !outcome || item.outcome?.outcome === outcome);
}

async function slaActionRecommendationAutoApprovalPerformanceReport(payload = {}) {
  const [adjustmentData, historyData, logData, policyAdjustmentData] = await Promise.all([
    readSlaActionRecommendationAdjustments(),
    readSlaActionReassessmentHistory(),
    readSlaActionRecommendationAutoApprovalLogs(),
    readSlaAutoApprovalPolicyAdjustments()
  ]);
  const activePolicy = activeSlaAutoApprovalPolicy(policyAdjustmentData.items || []);
  const historyItems = historyData.items || [];
  const logs = (logData.items || []).map(normalizeSlaActionRecommendationAutoApprovalLog);
  const autoAdjustments = (adjustmentData.items || [])
    .map(normalizeSlaActionRecommendationAdjustment)
    .filter((item) => item.approvalMode === "auto" || item.autoApprovalPolicy?.eligible);
  const allItems = autoAdjustments
    .map((item) => slaAutoApprovalPerformanceItem(item, historyItems, logs))
    .sort((a, b) => String(b.approvedAt || "").localeCompare(String(a.approvedAt || "")));
  const filtered = filterSlaAutoApprovalPerformanceItems(allItems, payload);
  const aggregates = {
    byMonth: slaAutoApprovalPerformanceGroups(filtered, (item) => item.approvalMonth || "unknown"),
    byIssue: slaAutoApprovalPerformanceGroups(filtered, (item) => item.issueKey || item.rootMetric || "unknown"),
    byOwner: slaAutoApprovalPerformanceGroups(filtered, (item) => item.owner || "unassigned")
  };
  const limit = Math.max(1, Math.min(500, Number(payload.limit || 120)));
  const policyAdjustmentCandidates = slaAutoApprovalPolicyAdjustmentCandidates(filtered, aggregates);
  const policyAdjustmentProposals = await upsertSlaAutoApprovalPolicyAdjustmentProposals(policyAdjustmentCandidates, activePolicy);
  return {
    role: "admin",
    reportType: "sla_action_recommendation_auto_approval_performance",
    generatedAt: new Date().toISOString(),
    filters: {
      month: String(payload.month || "").trim(),
      owner: String(payload.owner || "").trim(),
      issueKey: String(payload.issueKey || "").trim(),
      outcome: String(payload.outcome || "").trim(),
      limit
    },
    summary: slaAutoApprovalPerformanceSummary(filtered),
    fullSummary: slaAutoApprovalPerformanceSummary(allItems),
    aggregates,
    activePolicy,
    policyAdjustmentCandidates,
    policyAdjustmentProposals,
    items: filtered.slice(0, limit),
    reportBoundaries: {
      source: "admin-only SLA recommendation auto approval performance tracking",
      hiddenFromBusiness: ["auto approval policy performance", "rollback rate", "false positive rate", "operator quality outcomes", "policy adjustment candidates"]
    }
  };
}

async function reviewSlaActionRecommendationAdjustment(payload = {}) {
  const adjustmentId = String(payload.adjustmentId || "").trim();
  const decision = String(payload.decision || payload.status || "").trim().toLowerCase();
  if (!adjustmentId || !["approved", "rejected"].includes(decision)) {
    const error = new Error("Adjustment id and approved/rejected decision are required.");
    error.statusCode = 400;
    throw error;
  }
  const data = await readSlaActionRecommendationAdjustments();
  const items = Array.isArray(data.items) ? data.items.map(normalizeSlaActionRecommendationAdjustment) : [];
  const target = items.find((item) => item.adjustmentId === adjustmentId);
  if (!target) {
    const error = new Error("SLA recommendation adjustment proposal not found.");
    error.statusCode = 404;
    throw error;
  }
  const now = new Date().toISOString();
  const reviewer = String(payload.reviewedBy || payload.updatedBy || "admin").trim() || "admin";
  const updatedTarget = normalizeSlaActionRecommendationAdjustment({
    ...target,
    status: decision,
    activePriority: decision === "approved" ? target.proposedPriority : "",
    approvalMode: "manual",
    rollbackAvailable: false,
    reviewedAt: now,
    reviewedBy: reviewer,
    reviewReason: String(payload.reviewReason || payload.reason || "").trim(),
    approvedAt: decision === "approved" ? now : "",
    rejectedAt: decision === "rejected" ? now : "",
    updatedAt: now,
    updatedBy: reviewer
  });
  const updatedItems = items.map((item) => {
    if (item.adjustmentId === adjustmentId) return updatedTarget;
    if (decision === "approved" && item.sourceKey === target.sourceKey && item.status === "approved") {
      return normalizeSlaActionRecommendationAdjustment({
        ...item,
        status: "rejected",
        activePriority: "",
        rollbackAvailable: false,
        reviewedAt: now,
        reviewedBy: reviewer,
        reviewReason: `Superseded by approved adjustment ${adjustmentId}.`,
        rejectedAt: now,
        updatedAt: now,
        updatedBy: reviewer
      });
    }
    return item;
  });
  const updated = await writeSlaActionRecommendationAdjustments({
    ...data,
    items: updatedItems.sort((a, b) => String(b.updatedAt || b.proposedAt || "").localeCompare(String(a.updatedAt || a.proposedAt || "")))
  });
  return {
    role: "admin",
    reportType: "sla_action_recommendation_adjustment_review",
    generatedAt: now,
    adjustment: updatedTarget,
    slaActionRecommendationAdjustments: {
      schema: updated.schema || "sla_action_recommendation_adjustments_v1",
      total: updated.items.length,
      updatedAt: updated.updatedAt
    },
    reportBoundaries: {
      source: "admin-only SLA recommendation adjustment review decision",
      hiddenFromBusiness: ["approval decision", "review reason", "priority calibration evidence"]
    }
  };
}

async function createLearningCalibrationSlaActionFollowUp(payload = {}) {
  const actionId = String(payload.actionId || "").trim();
  const report = await learningCalibrationSlaActionReassessmentReport({ limit: 200 });
  const item = (report.items || []).find((entry) => entry.actionId === actionId);
  if (!item) {
    const error = new Error("Completed SLA action reassessment not found.");
    error.statusCode = 404;
    throw error;
  }
  if (!item.followUpCandidate) {
    const error = new Error("This completed SLA action does not require a follow-up action.");
    error.statusCode = 400;
    throw error;
  }
  const result = await upsertLearningCalibrationSlaAction({
    ...item.followUpCandidate,
    status: payload.status || "planned",
    assignee: payload.assignee || item.followUpCandidate.assignee || item.assignee || "",
    targetDate: payload.targetDate || item.followUpCandidate.targetDate,
    updatedBy: payload.updatedBy || payload.createdBy || "admin",
    createdBy: payload.createdBy || payload.updatedBy || "admin",
    recommendation: payload.recommendation || item.followUpCandidate.recommendation
  });
  const historyUpdate = await markSlaActionReassessmentHistoryFollowUp(
    item,
    result.action,
    payload.updatedBy || payload.createdBy || "admin"
  );
  return {
    role: "admin",
    reportType: "learning_calibration_sla_action_followup_create",
    generatedAt: new Date().toISOString(),
    sourceAction: {
      actionId: item.actionId,
      sourceLabel: item.sourceLabel,
      reassessment: item.reassessment
    },
    followUpAction: result.action,
    learningCalibrationSlaActions: result.learningCalibrationSlaActions,
    slaActionReassessmentHistory: historyUpdate.slaActionReassessmentHistory,
    reportBoundaries: {
      source: "admin-only follow-up action generated from completed SLA action reassessment",
      hiddenFromBusiness: ["follow-up action source", "effect score", "recurrence flag", "operational quality snapshot"]
    }
  };
}

async function rollbackLearningCalibrationSettings(payload = {}) {
  const data = await readLearningCalibrationSettings();
  const items = Array.isArray(data.items) ? data.items : [];
  const targetVersionId = String(payload.versionId || "").trim();
  const target = targetVersionId === "lcv_default"
    ? defaultLearningCalibrationVersion()
    : items.find((item) => item.versionId === targetVersionId);
  if (!target) {
    const error = new Error("Learning calibration version not found.");
    error.statusCode = 404;
    throw error;
  }
  const currentActive = activeLearningCalibrationVersion(data);
  const settings = normalizeLearningCalibrationOptions(target.settings || {});
  const appliedAt = new Date().toISOString();
  const versionNumber = nextLearningCalibrationVersionNumber(items);
  const version = {
    versionId: learningCalibrationVersionId(settings, appliedAt, "rollback"),
    versionNumber,
    status: "active",
    settings,
    appliedBy: String(payload.appliedBy || "admin").trim() || "admin",
    appliedAt,
    reason: String(payload.reason || `Rollback to ${target.versionId}.`).trim(),
    source: "rollback",
    rollbackFromVersionId: target.versionId,
    previousActiveVersionId: currentActive.versionId || ""
  };
  const updatedItems = [
    version,
    ...items.map((item) => ({
      ...item,
      status: item.status === "active" ? "superseded" : item.status || "superseded"
    }))
  ];
  const updated = await writeLearningCalibrationSettings({
    ...data,
    activeVersionId: version.versionId,
    items: updatedItems
  });
  return {
    learningCalibrationSettings: learningCalibrationSettingsSummary(updated),
    appliedVersion: publicLearningCalibrationVersion(version)
  };
}

function integratedLearningForStrategy(recommendation = {}, qualityLearning = {}, experimentLearning = {}, calibrationOptions = {}) {
  const calibration = normalizeLearningCalibrationOptions(calibrationOptions);
  const qualityScore = qualityLearning.hasHistory && qualityLearning.avgScore !== null && qualityLearning.avgScore !== undefined
    ? Number(qualityLearning.avgScore)
    : null;
  const experimentScore = experimentLearning.hasExperimentHistory && experimentLearning.avgScore !== null && experimentLearning.avgScore !== undefined
    ? Number(experimentLearning.avgScore)
    : null;
  const hasQuality = qualityScore !== null && Number.isFinite(qualityScore);
  const hasExperiment = experimentScore !== null && Number.isFinite(experimentScore);
  const hasIntegratedLearning = hasQuality || hasExperiment;
  const qualityWeight = hasQuality && hasExperiment ? calibration.retrospectiveShare : hasQuality ? 1 : 0;
  const experimentWeight = hasQuality && hasExperiment ? calibration.experimentShare : hasExperiment ? 1 : 0;
  const integratedScore = hasIntegratedLearning
    ? safeScore((hasQuality ? qualityScore * qualityWeight : 0) + (hasExperiment ? experimentScore * experimentWeight : 0)) || 0
    : null;
  const qualityHistoryCount = Number(qualityLearning.historyCount || 0);
  const experimentHistoryCount = Number(experimentLearning.historyCount || 0);
  const lowQualityCount = Number(qualityLearning.lowQualityCount || 0);
  const experimentStopCount = Number(experimentLearning.stopCount || 0);
  const riskCount = lowQualityCount + experimentStopCount;
  const successCount = Number(experimentLearning.successCount || 0) + Math.max(0, qualityHistoryCount - lowQualityCount);
  const successPriorityBonus = Math.round(clampNumber(calibration.successBonus, 0, 2));
  const priorityAdjustment = !hasIntegratedLearning
    ? 0
    : integratedScore < calibration.lowScoreThreshold || riskCount >= calibration.riskTriggerCount
      ? 2
      : integratedScore < calibration.midScoreThreshold || riskCount >= 1
        ? 1
        : integratedScore >= calibration.highScoreThreshold && successCount >= calibration.successTriggerCount
          ? -successPriorityBonus
          : 0;
  const readinessAdjustment = !hasIntegratedLearning
    ? 0
    : Math.round(clampNumber(
      (integratedScore - 65) * 0.45 - riskCount * calibration.readinessRiskPenalty + successCount * calibration.readinessSuccessBonus,
      -18,
      14
    ));
  const candidateScoreAdjustment = !hasIntegratedLearning
    ? 0
    : Math.round(clampNumber(
      (integratedScore - 60) * 0.35 - riskCount * calibration.riskPenalty + successCount * calibration.successBonus,
      -20,
      20
    ));
  const baseConfidenceScore = confidenceBaseScore(recommendation.confidenceGrade);
  const evidenceBonus = Math.min(10, (qualityHistoryCount + experimentHistoryCount) * 2);
  const recommendationConfidenceScore = Math.round(clampNumber(
    baseConfidenceScore +
      (hasIntegratedLearning ? (integratedScore - 60) * 0.28 : 0) +
      evidenceBonus -
      riskCount * calibration.riskPenalty,
    0,
    100
  ));
  return {
    hasIntegratedLearning,
    integratedScore,
    integratedGrade: hasIntegratedLearning ? performanceGrade(integratedScore) : "-",
    priorityAdjustment,
    readinessAdjustment,
    candidateScoreAdjustment,
    recommendationConfidenceScore,
    recommendationConfidenceGrade: confidenceGrade(recommendationConfidenceScore),
    publicSummary: hasIntegratedLearning ? "지난 실행/실험 결과 반영됨" : "",
    adminReason: hasIntegratedLearning
      ? `Integrated learning score ${integratedScore} from retrospective ${hasQuality ? qualityScore : "-"} and experiment ${hasExperiment ? experimentScore : "-"}; priority adjustment ${priorityAdjustment}, readiness adjustment ${readinessAdjustment}, candidate adjustment ${candidateScoreAdjustment}.`
      : "No retrospective or experiment learning history is available.",
    formula: `integratedScore = retrospective quality score ${calibration.retrospectiveWeight}% + A/B experiment score ${calibration.experimentWeight}% when both exist; priority/readiness/candidate adjustments derive from integratedScore, success count, and risk count`,
    inputs: {
      retrospectiveQualityScore: hasQuality ? qualityScore : null,
      retrospectiveWeight: qualityWeight,
      retrospectiveHistoryCount: qualityHistoryCount,
      retrospectiveLowQualityCount: lowQualityCount,
      experimentPerformanceScore: hasExperiment ? experimentScore : null,
      experimentWeight,
      experimentHistoryCount,
      experimentStopCount,
      successCount,
      riskCount,
      baseConfidenceScore,
      evidenceBonus,
      calibration
    },
    contributions: {
      retrospective: hasQuality ? safeScore(qualityScore * qualityWeight) : 0,
      experiment: hasExperiment ? safeScore(experimentScore * experimentWeight) : 0,
      priorityAdjustment,
      readinessAdjustment,
      candidateScoreAdjustment,
      recommendationConfidenceScore
    }
  };
}

function calibrationDelta(nextValue, currentValue) {
  const nextNumber = Number(nextValue);
  const currentNumber = Number(currentValue);
  if (!Number.isFinite(nextNumber) || !Number.isFinite(currentNumber)) return null;
  return Math.round(nextNumber - currentNumber);
}

function buildIntegratedLearningCalibration(report = {}, calibrationOptions = {}, settingsData = {}) {
  const settings = normalizeLearningCalibrationOptions(calibrationOptions);
  const formulas = (report.strategyRecommendations || []).map((item) => ({
    strategyId: item.strategyId,
    category: item.category,
    title: item.title,
    confidenceGrade: item.confidenceGrade,
    priority: item.priority,
    originalPriority: item.originalPriority ?? item.priority,
    learningAdjustment: item.adminReview?.learningAdjustment || item.learningAdjustment || {},
    segmentLearningAdjustment: item.adminReview?.segmentLearningAdjustment || item.segmentLearningAdjustment || {},
    experimentLearningAdjustment: item.adminReview?.experimentLearningAdjustment || item.experimentLearningAdjustment || {},
    integratedLearningAdjustment: item.adminReview?.integratedLearningAdjustment || item.integratedLearningAdjustment || {}
  }));
  const experimentsByStrategy = new Map((report.adminStrategyExperiments || report.strategyExperiments || []).map((item) => [item.strategyId, item]));
  const items = formulas.map((item) => {
    const simulatedIntegrated = integratedLearningForStrategy(
      item,
      item.learningAdjustment || {},
      item.experimentLearningAdjustment || {},
      settings
    );
    const currentIntegrated = item.integratedLearningAdjustment || {};
    const basePriority = Number(item.originalPriority ?? item.priority ?? 3);
    const segmentPriorityAdjustment = Number(item.segmentLearningAdjustment?.priorityAdjustment || 0);
    const currentPriority = Number(item.priority || 3);
    const simulatedPriority = Math.round(clampNumber(
      basePriority + segmentPriorityAdjustment + Number(simulatedIntegrated.priorityAdjustment || 0),
      1,
      5
    ));
    const currentCandidateBase = candidateBaseScore("new_recommendation", item, null, {
      ...item,
      priority: currentPriority
    });
    const simulatedCandidateBase = candidateBaseScore("new_recommendation", item, null, {
      ...item,
      priority: simulatedPriority
    });
    const currentCandidateScore = Math.round(clampNumber(
      currentCandidateBase + Number(currentIntegrated.candidateScoreAdjustment || 0),
      0,
      100
    ));
    const simulatedCandidateScore = Math.round(clampNumber(
      simulatedCandidateBase + Number(simulatedIntegrated.candidateScoreAdjustment || 0),
      0,
      100
    ));
    const experiment = experimentsByStrategy.get(item.strategyId) || null;
    const currentReadinessScore = experiment ? Number(experiment.readinessScore || 0) : null;
    const baseReadinessScore = currentReadinessScore === null
      ? null
      : currentReadinessScore - Number(currentIntegrated.readinessAdjustment || 0);
    const simulatedReadinessScore = baseReadinessScore === null
      ? null
      : Math.round(clampNumber(baseReadinessScore + Number(simulatedIntegrated.readinessAdjustment || 0), 0, 100));
    return {
      strategyId: item.strategyId,
      category: item.category,
      title: item.title,
      current: {
        integratedScore: currentIntegrated.integratedScore ?? null,
        integratedGrade: currentIntegrated.integratedGrade || "-",
        recommendationConfidenceScore: currentIntegrated.recommendationConfidenceScore ?? null,
        recommendationConfidenceGrade: currentIntegrated.recommendationConfidenceGrade || item.confidenceGrade || "-",
        priorityAdjustment: currentIntegrated.priorityAdjustment || 0,
        finalPriority: currentPriority,
        readinessAdjustment: currentIntegrated.readinessAdjustment || 0,
        readinessScore: currentReadinessScore,
        candidateScoreAdjustment: currentIntegrated.candidateScoreAdjustment || 0,
        candidateScore: currentCandidateScore,
        candidateGrade: confidenceGrade(currentCandidateScore)
      },
      simulated: {
        integratedScore: simulatedIntegrated.integratedScore ?? null,
        integratedGrade: simulatedIntegrated.integratedGrade || "-",
        recommendationConfidenceScore: simulatedIntegrated.recommendationConfidenceScore ?? null,
        recommendationConfidenceGrade: simulatedIntegrated.recommendationConfidenceGrade || item.confidenceGrade || "-",
        priorityAdjustment: simulatedIntegrated.priorityAdjustment || 0,
        finalPriority: simulatedPriority,
        readinessAdjustment: simulatedIntegrated.readinessAdjustment || 0,
        readinessScore: simulatedReadinessScore,
        candidateScoreAdjustment: simulatedIntegrated.candidateScoreAdjustment || 0,
        candidateScore: simulatedCandidateScore,
        candidateGrade: confidenceGrade(simulatedCandidateScore)
      },
      deltas: {
        integratedScore: calibrationDelta(simulatedIntegrated.integratedScore, currentIntegrated.integratedScore),
        recommendationConfidenceScore: calibrationDelta(
          simulatedIntegrated.recommendationConfidenceScore,
          currentIntegrated.recommendationConfidenceScore
        ),
        finalPriority: calibrationDelta(simulatedPriority, currentPriority),
        readinessScore: calibrationDelta(simulatedReadinessScore, currentReadinessScore),
        candidateScore: calibrationDelta(simulatedCandidateScore, currentCandidateScore)
      },
      adminReview: {
        currentIntegratedLearning: currentIntegrated,
        simulatedIntegratedLearning: simulatedIntegrated,
        segmentLearningAdjustment: item.segmentLearningAdjustment || {},
        learningAdjustment: item.learningAdjustment || {},
        experimentLearningAdjustment: item.experimentLearningAdjustment || {},
        experimentReadiness: experiment?.adminReview || null
      }
    };
  });
  const simulatedScores = items.map((item) => item.simulated.integratedScore).filter((value) => value !== null && value !== undefined);
  const simulatedConfidence = items.map((item) => item.simulated.recommendationConfidenceScore).filter((value) => value !== null && value !== undefined);
  const simulatedCandidateScores = items.map((item) => item.simulated.candidateScore).filter((value) => value !== null && value !== undefined);
  return {
    reportType: "integrated_learning_calibration_draft",
    generatedAt: new Date().toISOString(),
    settings,
    settingsState: learningCalibrationSettingsSummary(settingsData),
    defaultSettings: normalizeLearningCalibrationOptions(DEFAULT_LEARNING_CALIBRATION),
    summary: {
      total: items.length,
      withIntegratedLearning: items.filter((item) => item.simulated.integratedScore !== null && item.simulated.integratedScore !== undefined).length,
      avgIntegratedScore: safeScore(average(simulatedScores)) || 0,
      avgRecommendationConfidence: safeScore(average(simulatedConfidence)) || 0,
      avgCandidateScore: safeScore(average(simulatedCandidateScores)) || 0,
      priorityChanged: items.filter((item) => item.deltas.finalPriority !== null && item.deltas.finalPriority !== 0).length,
      readinessChanged: items.filter((item) => item.deltas.readinessScore !== null && item.deltas.readinessScore !== 0).length,
      candidateChanged: items.filter((item) => item.deltas.candidateScore !== null && item.deltas.candidateScore !== 0).length
    },
    formula: {
      score: "integratedScore = retrospective quality score * retrospectiveWeight + A/B experiment score * experimentWeight",
      confidence: "recommendationConfidence = base confidence + integrated score contribution + evidence bonus - risk count * riskPenalty",
      priority: "priority adjustment uses low/mid/high score thresholds, risk trigger count, and success trigger count",
      readiness: "experiment readiness adjustment uses integrated score, risk penalty, and success bonus",
      candidate: "candidate score adjustment uses integrated score, risk penalty, and success bonus"
    },
    items
  };
}

function applyStrategyQualityLearning(items = [], historyItems = [], segmentLearning = {}, experimentHistoryItems = [], targetMonth = "", calibrationOptions = {}) {
  return items
    .map((item) => {
      const learningAdjustment = qualityLearningForStrategy(item.strategyId, historyItems, targetMonth);
      const segmentLearningAdjustment = segmentLearningForStrategy(item.strategyId, segmentLearning);
      const experimentLearningAdjustment = experimentLearningForStrategy(item, experimentHistoryItems, targetMonth);
      const integratedLearningAdjustment = integratedLearningForStrategy(item, learningAdjustment, experimentLearningAdjustment, calibrationOptions);
      const adjustedPriority = Math.round(clampNumber(
        Number(item.priority || 3) +
          Number(segmentLearningAdjustment.priorityAdjustment || 0) +
          Number(integratedLearningAdjustment.priorityAdjustment || 0),
        1,
        5
      ));
      return {
        ...item,
        priority: adjustedPriority,
        originalPriority: item.priority,
        learningAdjustment,
        segmentLearningAdjustment,
        experimentLearningAdjustment,
        integratedLearningAdjustment,
        adminReview: {
          ...(item.adminReview || {}),
          learningAdjustment,
          segmentLearningAdjustment,
          experimentLearningAdjustment,
          integratedLearningAdjustment
        }
      };
    })
    .sort((a, b) => {
      if (a.priority !== b.priority) return a.priority - b.priority;
      return String(a.title || "").localeCompare(String(b.title || ""), "ko");
    });
}

function buildStrategyRecommendations(targetCompany, myMetrics, comparableMetrics, regionalMetrics, nextMonth, qualityHistoryItems = [], segmentLearning = {}, experimentHistoryItems = [], calibrationOptions = {}) {
  const snapshot = metricSnapshot(myMetrics, comparableMetrics, regionalMetrics, targetCompany);
  const items = [];
  const priceStatus = snapshot.price.position.status;
  const reservationStatus = snapshot.reservation.position.status;
  const leadtimeStatus = snapshot.leadtime.position.status;
  const interestStatus = snapshot.interest.position.status;

  items.push(makeStrategyRecommendation({
    category: "가격 전략",
    title: priceStatus === "below_baseline" ? "주중/비성수 가격 방어선 재점검" : priceStatus === "above_baseline" ? "핵심 날짜 단계적 인상 테스트" : "가격 대신 제공가치 차별화",
    action: priceStatus === "below_baseline"
      ? `${nextMonth} 예약률이 비교군보다 낮은 날짜부터 가격을 1차 조정하고, 주말은 리드타임 반응을 보고 유지하십시오.`
      : priceStatus === "above_baseline"
        ? `${nextMonth} 주말과 인기 객실은 소폭 인상하고, 평일은 패키지 혜택으로 전환하십시오.`
        : `${nextMonth} 평균 가격은 유지하되 바비큐, 조식, 온수풀 등 제공사항을 가격표와 상세페이지에 명확히 분리하십시오.`,
    rationale: "가격 평균, 예약률 위치, 리드타임 booking pace를 함께 비교했습니다.",
    metricKeys: ["price", "reservation", "leadtime"],
    snapshot,
    formula: "price position + reservation position + leadtime pace position",
    priority: priceStatus === "near_baseline" ? 3 : 1
  }));

  items.push(makeStrategyRecommendation({
    category: "채널 전략",
    title: snapshot.ota.myChannelCount < Math.max(2, snapshot.ota.comparableChannelCount) ? "OTA 노출 채널 보강" : "채널별 가격·재고 차등 운영",
    action: snapshot.ota.myChannelCount < Math.max(2, snapshot.ota.comparableChannelCount)
      ? "네이버 외 야놀자/NOL, 여기어때, 떠나요 노출 여부와 URL 매칭을 우선 검수하십시오."
      : "이미 노출된 채널은 동일 가격 복제보다 채널별 재고량과 부가혜택을 다르게 배치하십시오.",
    rationale: "내 OTA 채널 수와 비교군 채널 수, B2B 노출 상태를 함께 사용했습니다.",
    metricKeys: ["ota", "b2b", "reliability"],
    snapshot,
    formula: "my OTA channel count vs comparable channel count + B2B eligibility",
    priority: snapshot.ota.myChannelCount < Math.max(2, snapshot.ota.comparableChannelCount) ? 1 : 4
  }));

  items.push(makeStrategyRecommendation({
    category: "상품/패키지 전략",
    title: reservationStatus === "below_baseline" ? "예약 전환형 패키지 구성" : "고수요 날짜 업셀 패키지",
    action: reservationStatus === "below_baseline"
      ? "가격 할인만 쓰기보다 바비큐, 불멍, 조식, 얼리체크인 중 하나를 묶어 비교군과 다른 선택 이유를 만드십시오."
      : "예약 속도가 양호한 날짜는 할인 대신 프리미엄 객실, 온수풀, 바비큐 세트를 묶어 객단가를 올리십시오.",
    rationale: "예약률 위치, 가격 위치, 관심도 점수를 결합했습니다.",
    metricKeys: ["reservation", "price", "interest"],
    snapshot,
    formula: "reservation position + price position + interest standard score",
    priority: reservationStatus === "below_baseline" ? 1 : 3
  }));

  items.push(makeStrategyRecommendation({
    category: "콘텐츠/SNS 전략",
    title: interestStatus === "below_baseline" ? "지역 키워드 콘텐츠 보강" : "관심도 높은 키워드 전환 강화",
    action: interestStatus === "below_baseline"
      ? "지역명+업종 키워드와 숙소명 키워드의 네이버/SNS 콘텐츠를 보강하고, 대표 이미지와 후기 노출을 먼저 정비하십시오."
      : "관심도 점수가 높은 키워드를 상세페이지 제목, 네이버 플레이스 소식, SNS 게시물에 반복 반영하십시오.",
    rationale: "검색량, 트렌드, SNS 언급량의 표준점수와 비교군 위치를 사용했습니다.",
    metricKeys: ["interest", "reservation", "reliability"],
    snapshot,
    formula: "interest standard score vs comparables + reservation position",
    priority: interestStatus === "below_baseline" ? 1 : 2
  }));

  items.push(makeStrategyRecommendation({
    category: "리드타임 운영 전략",
    title: leadtimeStatus === "below_baseline" ? "초기 리드타임 예약 가속" : "잔여일별 재고·가격 차등",
    action: leadtimeStatus === "below_baseline"
      ? "다음달 핵심 날짜는 D-30, D-14, D-7 관측을 나누고 초기 예약이 느린 날짜에만 제한 프로모션을 적용하십시오."
      : "booking pace가 좋은 날짜는 조기 할인보다 잔여 객실이 줄어드는 시점에 가격을 단계적으로 올리십시오.",
    rationale: "리드타임 booking pace, 지역 패턴 샘플 수, 예약률 위치를 사용했습니다.",
    metricKeys: ["leadtime", "reservation", "price"],
    snapshot,
    formula: "booking pace position + regional leadtime pattern count + reservation position",
    priority: snapshot.leadtime.regionalPatternCount < 5 || leadtimeStatus === "below_baseline" ? 1 : 3
  }));

  return applyStrategyQualityLearning(items, qualityHistoryItems, segmentLearning, experimentHistoryItems, nextMonth, calibrationOptions).slice(0, 5);
}

async function adminStrategyRecommendations(payload = {}) {
  const report = await businessReport({ ...payload, includeAdminReview: true });
  if (!report) return null;
  const experimentQualityHistorySync = await upsertExperimentQualityHistoryFromReport(report);
  const [qualityHistory, experimentQualityHistory, calibrationSettings] = await Promise.all([
    readStrategyQualityHistory(),
    readExperimentQualityHistory(),
    readLearningCalibrationSettings()
  ]);
  const activeCalibration = activeLearningCalibrationVersion(calibrationSettings);
  const qualityHistoryFiltered = filterStrategyQualityHistory(qualityHistory, new URLSearchParams({
    companyId: report.company.companyId
  }));
  const experimentQualityHistoryFiltered = filterExperimentQualityHistory(experimentQualityHistory, new URLSearchParams({
    companyId: report.company.companyId
  }));
  const strategySegmentLearning = report.adminStrategySegmentLearning || {};
  const nextMonthCandidates = await nextMonthPlanCandidates({
    companyId: report.company.companyId,
    sourceMonth: report.targetMonth,
    includeAdminReview: true
  });
  const learningCalibrationAudit = await learningCalibrationAuditReport({
    companyId: report.company.companyId,
    limit: 20
  });
  return {
    role: "admin",
    generatedAt: new Date().toISOString(),
    company: report.company,
    targetMonth: report.targetMonth,
    recommendations: report.strategyRecommendations,
    strategyExperiments: report.adminStrategyExperiments || report.strategyExperiments || [],
    strategyExperimentExecution: report.strategyExperimentExecution || {},
    strategyExperimentResults: report.strategyExperimentResults || {},
    executionProgress: report.strategyExecutionProgress,
    monthlyExecution: buildMonthlyOperationsBoard(report, {}),
    monthlyRetrospective: buildMonthlyRetrospective(report, { includeAdminReview: true }),
    strategyQualityHistory: qualityHistoryFiltered,
    experimentQualityHistory: experimentQualityHistoryFiltered,
    experimentQualityHistorySync,
    strategySegmentLearning,
    nextMonthPlanCandidates: nextMonthCandidates,
    learningCalibrationSettings: learningCalibrationSettingsSummary(calibrationSettings),
    learningCalibration: buildIntegratedLearningCalibration(report, activeCalibration.settings, calibrationSettings),
    learningCalibrationAudit,
    adminReview: {
      source: "business report strategyRecommendations.adminReview",
      formulas: (report.strategyRecommendations || []).map((item) => ({
        strategyId: item.strategyId,
        category: item.category,
        title: item.title,
        confidenceGrade: item.confidenceGrade,
        priority: item.priority,
        originalPriority: item.originalPriority ?? item.priority,
        learningAdjustment: item.adminReview?.learningAdjustment || item.learningAdjustment || {},
        segmentLearningAdjustment: item.adminReview?.segmentLearningAdjustment || item.segmentLearningAdjustment || {},
        experimentLearningAdjustment: item.adminReview?.experimentLearningAdjustment || item.experimentLearningAdjustment || {},
        integratedLearningAdjustment: item.adminReview?.integratedLearningAdjustment || item.integratedLearningAdjustment || {},
        experiment: (report.adminStrategyExperiments || []).find((experiment) => experiment.strategyId === item.strategyId) || null,
        executionDifficulty: item.executionDifficulty,
        expectedEffect: item.expectedEffect,
        recommendedTiming: item.recommendedTiming,
        executionPlan: item.executionPlan,
        formula: item.adminReview?.formula || "",
        metricKeys: item.adminReview?.metricKeys || [],
        reviewStatus: item.adminReview?.reviewStatus || {},
        rawMetricSnapshot: item.adminReview?.rawMetricSnapshot || {}
      }))
    }
  };
}

async function integratedLearningCalibrationReport(payload = {}) {
  const [report, calibrationSettings] = await Promise.all([
    businessReport({
      companyId: payload.companyId,
      targetMonth: payload.targetMonth,
      includeAdminReview: true
    }),
    readLearningCalibrationSettings()
  ]);
  if (!report) return null;
  const activeCalibration = activeLearningCalibrationVersion(calibrationSettings);
  const calibrationOptions = hasLearningCalibrationOverride(payload.calibrationOptions || payload)
    ? payload.calibrationOptions || payload
    : activeCalibration.settings;
  return {
    role: "admin",
    generatedAt: new Date().toISOString(),
    company: report.company,
    targetMonth: report.targetMonth,
    learningCalibrationSettings: learningCalibrationSettingsSummary(calibrationSettings),
    learningCalibration: buildIntegratedLearningCalibration(report, calibrationOptions, calibrationSettings),
    reportBoundaries: {
      source: "admin-only strategy recommendation formula snapshots, retrospective quality history, experiment quality history, and integrated learning calibration settings",
      hiddenFromBusiness: ["calibration settings", "formula inputs", "risk and success coefficients", "raw learning adjustment details"]
    }
  };
}

