const SUBSCRIPTION_STATUS_LABELS = {
  trial: "체험",
  active: "정상",
  past_due: "결제 확인",
  paused: "일시중지",
  cancelled: "해지"
};

function normalizeCommercialPlan(value = "") {
  const plan = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(COMMERCIAL_PLAN_POLICIES, plan) ? plan : "free";
}

function normalizeSubscriptionStatus(value = "") {
  const status = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(SUBSCRIPTION_STATUS_LABELS, status) ? status : "trial";
}

function subscriptionIdForCompany(companyId = "") {
  return hashId("sub", String(companyId || "").trim());
}

function defaultCompanySubscription(company = {}) {
  const now = new Date().toISOString();
  return {
    subscriptionId: subscriptionIdForCompany(company.companyId),
    companyId: company.companyId,
    plan: "free",
    status: "trial",
    trialEndsAt: "",
    currentPeriodEndsAt: "",
    paymentMemo: "",
    accessMemo: "Default free access until an operator assigns a commercial plan.",
    createdAt: now,
    updatedAt: now,
    updatedBy: "system"
  };
}

function companySubscriptionForCompany(data = {}, company = {}) {
  const companyId = String(company.companyId || "").trim();
  const found = (data.items || []).find((item) => item.companyId === companyId);
  return {
    ...defaultCompanySubscription(company),
    ...(found || {}),
    subscriptionId: found?.subscriptionId || subscriptionIdForCompany(companyId),
    companyId,
    plan: normalizeCommercialPlan(found?.plan),
    status: normalizeSubscriptionStatus(found?.status)
  };
}

function publicSubscriptionAccess(subscription = {}) {
  const planKey = normalizeCommercialPlan(subscription.plan);
  const policy = COMMERCIAL_PLAN_POLICIES[planKey];
  const status = normalizeSubscriptionStatus(subscription.status);
  const featureAccess = Object.fromEntries(
    Object.entries(policy.features).map(([key, value]) => [key, { ...value }])
  );
  return {
    subscriptionId: subscription.subscriptionId,
    companyId: subscription.companyId,
    plan: planKey,
    planLabel: policy.label,
    status,
    statusLabel: SUBSCRIPTION_STATUS_LABELS[status] || status,
    trialEndsAt: subscription.trialEndsAt || "",
    currentPeriodEndsAt: subscription.currentPeriodEndsAt || "",
    reportAccess: {
      reportScope: policy.reportScope,
      regionCardScope: policy.regionCardScope,
      strategyLimit: policy.strategyLimit
    },
    featureAccess
  };
}

function lockedBusinessFeature(featureKey = "", access = {}) {
  const feature = access.featureAccess?.[featureKey] || {};
  const requiredPlan = feature.requiredPlan || "pro";
  const requiredLabel = COMMERCIAL_PLAN_POLICIES[requiredPlan]?.label || requiredPlan;
  return {
    locked: true,
    featureKey,
    label: feature.label || featureKey,
    requiredPlan,
    requiredPlanLabel: requiredLabel,
    message: `${requiredLabel} 요금제부터 사용할 수 있습니다.`
  };
}

function businessFeatureLocks(access = {}) {
  return Object.entries(access.featureAccess || {})
    .filter(([, value]) => value && value.allowed === false)
    .map(([key]) => lockedBusinessFeature(key, access));
}

function applyBusinessReportEntitlements(report = {}, access = {}) {
  const strategyFeature = access.featureAccess?.strategyRecommendations || {};
  const limit = strategyFeature.limit === null || strategyFeature.limit === undefined
    ? null
    : Math.max(0, Number(strategyFeature.limit || 0));
  const strategyRecommendations = Array.isArray(report.strategyRecommendations)
    ? (limit === null ? report.strategyRecommendations : report.strategyRecommendations.slice(0, limit))
    : [];
  const hiddenStrategyCount = Math.max(0, (report.strategyRecommendations || []).length - strategyRecommendations.length);
  const nextMonthStrategySummary = Array.isArray(report.nextMonthStrategySummary)
    ? (limit === null ? report.nextMonthStrategySummary : report.nextMonthStrategySummary.slice(0, limit))
    : [];
  return {
    ...report,
    subscription: access,
    featureAccess: access.featureAccess,
    featureLocks: businessFeatureLocks(access),
    upgradePrompts: businessFeatureLocks(access),
    strategyRecommendations,
    strategyRecommendationAccess: {
      ...strategyFeature,
      visibleCount: strategyRecommendations.length,
      hiddenCount: hiddenStrategyCount
    },
    strategyExperiments: access.featureAccess?.strategyExperiments?.allowed ? report.strategyExperiments || [] : [],
    strategyExperimentResults: access.featureAccess?.strategyExperiments?.allowed ? report.strategyExperimentResults : {
      locked: true,
      summary: { total: 0 },
      items: []
    },
    nextMonthStrategySummary,
    entitlementSummary: [
      `${access.planLabel || "-"} 요금제`,
      `리포트 ${access.reportAccess?.reportScope || "summary"}`,
      `전략 ${limit === null ? "전체" : `${strategyRecommendations.length}개`}`
    ].join(" · ")
  };
}

async function businessSubscriptionAccess(company = {}) {
  const subscriptions = await readCompanySubscriptions();
  return publicSubscriptionAccess(companySubscriptionForCompany(subscriptions, company));
}

function subscriptionStatusTone(status = "") {
  if (status === "active") return "good";
  if (status === "trial") return "neutral";
  if (status === "past_due") return "warning";
  return "muted";
}

async function upsertCompanySubscription(payload = {}) {
  const companyId = String(payload.companyId || "").trim();
  if (!companyId) return null;
  const [subscriptions, companies] = await Promise.all([
    readCompanySubscriptions(),
    readCompanyMaster()
  ]);
  const company = (companies.items || []).find((item) => item.companyId === companyId) || { companyId };
  const current = companySubscriptionForCompany(subscriptions, company);
  const now = new Date().toISOString();
  const next = {
    ...current,
    subscriptionId: current.subscriptionId || subscriptionIdForCompany(companyId),
    companyId,
    plan: normalizeCommercialPlan(payload.plan ?? current.plan),
    status: normalizeSubscriptionStatus(payload.status ?? current.status),
    trialEndsAt: String(payload.trialEndsAt ?? current.trialEndsAt ?? "").trim(),
    currentPeriodEndsAt: String(payload.currentPeriodEndsAt ?? current.currentPeriodEndsAt ?? "").trim(),
    paymentMemo: String(payload.paymentMemo ?? current.paymentMemo ?? "").trim(),
    accessMemo: String(payload.accessMemo ?? current.accessMemo ?? "").trim(),
    updatedAt: now,
    updatedBy: String(payload.updatedBy || "admin").trim() || "admin",
    createdAt: current.createdAt || now
  };
  const others = (subscriptions.items || []).filter((item) => item.companyId !== companyId);
  const updated = await writeCompanySubscriptions({
    ...subscriptions,
    items: [...others, next].sort((a, b) => String(a.companyId).localeCompare(String(b.companyId), "ko"))
  });
  return {
    subscription: next,
    publicSubscription: publicSubscriptionAccess(next),
    counts: { subscriptions: updated.items?.length || 0 }
  };
}

async function adminCompanySubscriptions(params = new URLSearchParams()) {
  const [companiesData, subscriptions, onboarding] = await Promise.all([
    readCompanyMaster(),
    readCompanySubscriptions(),
    adminBusinessOnboardingSummary(new URLSearchParams({ q: params.get("q") || "", limit: "1000" }))
  ]);
  const query = compactKeyword(params.get("q") || "");
  const planFilter = normalizeCommercialPlan(params.get("plan") || "");
  const statusFilter = normalizeSubscriptionStatus(params.get("status") || "");
  const hasPlanFilter = Boolean(String(params.get("plan") || "").trim());
  const hasStatusFilter = Boolean(String(params.get("status") || "").trim());
  const onboardingByCompanyId = new Map((onboarding.items || []).map((item) => [item.companyId, item]));
  const items = (companiesData.items || [])
    .filter((company) => !query || compactKeyword(`${company.canonicalName || company.name || ""} ${company.region || ""} ${company.category || ""} ${company.companyId || ""}`).includes(query))
    .map((company) => {
      const subscription = companySubscriptionForCompany(subscriptions, company);
      const publicAccess = publicSubscriptionAccess(subscription);
      const onboardingItem = onboardingByCompanyId.get(company.companyId) || {};
      return {
        companyId: company.companyId,
        name: company.canonicalName || company.name || "",
        region: company.region || "",
        category: company.category || "",
        subscription: publicAccess,
        payment: {
          paymentMemo: subscription.paymentMemo || "",
          accessMemo: subscription.accessMemo || "",
          updatedBy: subscription.updatedBy || "",
          updatedAt: subscription.updatedAt || ""
        },
        onboarding: {
          status: onboardingItem.onboardingStatus || "",
          label: onboardingItem.onboardingLabel || "",
          tone: onboardingItem.onboardingTone || "",
          reportReady: Boolean(onboardingItem.reportReadiness?.ready),
          locationReady: Boolean(onboardingItem.locationCard?.publicReady),
          reliabilityGrade: onboardingItem.dataReliability?.grade || "",
          executionPlanCount: onboardingItem.executionPlan?.count || 0
        }
      };
    })
    .filter((item) => !hasPlanFilter || item.subscription.plan === planFilter)
    .filter((item) => !hasStatusFilter || item.subscription.status === statusFilter)
    .sort((a, b) => String(a.name || a.companyId).localeCompare(String(b.name || b.companyId), "ko"));
  const summary = items.reduce((acc, item) => {
    acc.total += 1;
    acc.byPlan[item.subscription.plan] = (acc.byPlan[item.subscription.plan] || 0) + 1;
    acc.byStatus[item.subscription.status] = (acc.byStatus[item.subscription.status] || 0) + 1;
    if (item.subscription.featureAccess.executionPlan?.allowed) acc.executionPlanEnabled += 1;
    if (item.subscription.featureAccess.monthlyRetrospective?.allowed) acc.retrospectiveEnabled += 1;
    return acc;
  }, { total: 0, byPlan: {}, byStatus: {}, executionPlanEnabled: 0, retrospectiveEnabled: 0 });
  const limit = Math.max(1, Math.min(300, Number(params.get("limit") || 100)));
  return {
    role: "admin",
    generatedAt: new Date().toISOString(),
    plans: Object.values(COMMERCIAL_PLAN_POLICIES).map((policy) => ({
      plan: policy.plan,
      label: policy.label,
      reportScope: policy.reportScope,
      regionCardScope: policy.regionCardScope,
      strategyLimit: policy.strategyLimit,
      features: policy.features
    })),
    statuses: Object.entries(SUBSCRIPTION_STATUS_LABELS).map(([status, label]) => ({ status, label })),
    summary,
    items: items.slice(0, limit)
  };
}

async function businessReport(payload = {}) {
  const companyId = String(payload.companyId || "").trim();
  if (!companyId) return null;
  const [companies, profiles, observations, leadtimePatterns, locationCards, locationCardRequests, interestSignals, executionPlans, experimentPlans, qualityHistory, experimentQualityHistory, calibrationSettings, subscriptions] = await Promise.all([
    readCompanyMaster(),
    readVerifiedProfiles(),
    readPropertyObservations(),
    readLeadtimePatterns(),
    readLocationCards(),
    readLocationCardRequests(),
    readInterestSignals(),
    readStrategyExecutionPlans(),
    readStrategyExperimentPlans(),
    readStrategyQualityHistory(),
    readExperimentQualityHistory(),
    readLearningCalibrationSettings(),
    readCompanySubscriptions()
  ]);
  const profilesById = new Map((profiles.items || []).map((item) => [item.companyId, item]));
  const patterns = leadtimePatterns.items || [];
  const resolvedCompanies = (companies.items || [])
    .map((company) => resolvedCompanyForReport(company, profilesById, observations.items || [], patterns));
  const target = resolvedCompanies.find((company) => company.companyId === companyId);
  if (!target) return null;
  const subscriptionAccess = publicSubscriptionAccess(companySubscriptionForCompany(subscriptions, target));

  const visibleCompanies = resolvedCompanies.filter(reportCompanyVisible);
  const nationalIds = visibleCompanies.map((company) => company.companyId);
  const regionIds = visibleCompanies
    .filter((company) => !target.region || company.region === target.region)
    .map((company) => company.companyId);
  const comparableIds = visibleCompanies
    .filter((company) => company.companyId !== target.companyId)
    .filter((company) => !target.region || company.region === target.region)
    .filter((company) => !target.category || !company.category || company.category === target.category)
    .map((company) => company.companyId);
  const myIds = [target.companyId];
  const allObservations = observations.items || [];
  const nextMonth = payload.targetMonth || nextMonthKey();
  const myScope = reportScope("내 숙소 흐름", myIds, allObservations, patterns);
  const comparableScope = reportScope("비교군 흐름", comparableIds, allObservations, patterns);
  const regionScope = reportScope("지역 흐름", regionIds, allObservations, patterns);
  const nationalScope = reportScope("전국 흐름", nationalIds, allObservations, patterns);
  const interestAnalytics = buildInterestAnalytics(target, visibleCompanies, interestSignals.items || []);
  nationalScope.metrics.interest = interestAnalytics.national;
  regionScope.metrics.interest = interestAnalytics.region;
  myScope.metrics.interest = interestAnalytics.myProperty;
  comparableScope.metrics.interest = interestAnalytics.comparables;
  const targetObservations = allObservations.filter((item) => item.companyId === target.companyId);
  const regionCard = buildRegionCard(
    target,
    visibleCompanies,
    allObservations,
    leadtimePatterns,
    interestSignals.items || [],
    interestAnalytics,
    publicLocationCardForTarget(locationCards.items || [], target),
    publicLocationCardReadiness(locationCards.items || [], target, targetObservations)
  );
  regionCard.locationCardRequestStatus = publicLocationCardRequestSummary(locationCardRequests.items || [], target);
  const companyQualityHistory = (qualityHistory.items || []).filter((item) => item.companyId === target.companyId);
  const companyExperimentQualityHistory = (experimentQualityHistory.items || []).filter((item) => item.companyId === target.companyId);
  const activeCalibration = activeLearningCalibrationVersion(calibrationSettings);
  const strategySegmentLearning = buildStrategySegmentLearning(
    target,
    nextMonth,
    qualityHistory.items || [],
    visibleCompanies,
    interestSignals.items || [],
    leadtimePatterns
  );
  const rawStrategyRecommendations = attachExecutionPlans(
    target.companyId,
    nextMonth,
    buildStrategyRecommendations(
      target,
      myScope.metrics,
      comparableScope.metrics,
      regionScope.metrics,
      nextMonth,
      companyQualityHistory,
      strategySegmentLearning,
      companyExperimentQualityHistory,
      activeCalibration.settings
    ),
    executionPlans.items || []
  );
  const targetExperimentPlans = (experimentPlans.items || [])
    .filter((plan) => plan.companyId === target.companyId && plan.targetMonth === nextMonth);
  const rawStrategyExperiments = attachExperimentExecutionPlans(
    buildStrategyExperiments(
      { companyId: target.companyId, name: target.name, region: target.region, category: target.category },
      nextMonth,
      rawStrategyRecommendations
    ),
    targetExperimentPlans
  );
  const rawStrategyExperimentResults = buildStrategyExperimentResults(
    rawStrategyExperiments,
    targetExperimentPlans,
    { includeAdminReview: Boolean(payload.includeAdminReview) }
  );
  const integratedLearningItems = rawStrategyRecommendations
    .map((item) => item.integratedLearningAdjustment || {})
    .filter((item) => item.hasIntegratedLearning);
  const integratedLearningSummary = {
    total: integratedLearningItems.length,
    avgIntegratedScore: safeScore(average(integratedLearningItems.map((item) => item.integratedScore))) || 0,
    avgRecommendationConfidence: safeScore(average(rawStrategyRecommendations.map((item) => item.integratedLearningAdjustment?.recommendationConfidenceScore))) || 0,
    publicSummary: integratedLearningItems.length ? "지난 실행/실험 결과 반영됨" : ""
  };
  const executionProgress = executionProgressForPlans(rawStrategyRecommendations.map((item) => item.executionPlan));
  const strategyRecommendations = payload.includeAdminReview
    ? rawStrategyRecommendations
    : rawStrategyRecommendations.map(publicStrategyRecommendation);
  const strategyExperiments = payload.includeAdminReview
    ? rawStrategyExperiments
    : rawStrategyExperiments.map(publicStrategyExperiment);

  const report = {
    role: "business",
    reportType: "lodging_intelligence_draft",
    generatedAt: new Date().toISOString(),
    targetMonth: nextMonth,
    company: {
      companyId: target.companyId,
      name: target.name,
      region: target.region,
      category: target.category,
      b2bVisibility: target.b2bVisibility,
      verifiedStatus: target.verifiedStatus,
      confidenceGrade: target.confidenceGrade,
      roomTotal: target.roomTotal,
      dayUseTotal: target.dayUseTotal
    },
    flows: {
      national: nationalScope,
      region: regionScope,
      myProperty: myScope,
      comparables: comparableScope
    },
    regionCard,
    strategySegmentLearning: publicStrategySegmentLearning(strategySegmentLearning),
    adminStrategySegmentLearning: payload.includeAdminReview ? strategySegmentLearning : undefined,
    adminLearningCalibrationSettings: payload.includeAdminReview ? learningCalibrationSettingsSummary(calibrationSettings) : undefined,
    objectiveIndicators: {
      pricePosition: compareMetric(myScope.metrics.price.avg, comparableScope.metrics.price.avg, false),
      reservationPosition: compareMetric(myScope.metrics.reservation.avgRate, comparableScope.metrics.reservation.avgRate, true),
      leadtimePosition: compareMetric(myScope.metrics.leadtime.avgBookingPaceScore, comparableScope.metrics.leadtime.avgBookingPaceScore, true),
      interestPosition: compareMetric(myScope.metrics.interest.score, comparableScope.metrics.interest.score, true),
      interestDemand: {
        myScore: myScope.metrics.interest.score,
        myGrade: myScope.metrics.interest.grade,
        regionScore: regionScope.metrics.interest.score,
        regionGrade: regionScope.metrics.interest.grade,
        comparableScore: comparableScope.metrics.interest.score,
        comparableGrade: comparableScope.metrics.interest.grade,
        confidenceGrade: myScope.metrics.interest.confidenceGrade,
        signalCount: myScope.metrics.interest.signalCount,
        basis: myScope.metrics.interest.basis
      },
      otaExposure: {
        myChannelCount: myScope.metrics.otaExposure.channelCount,
        comparableChannelCount: comparableScope.metrics.otaExposure.channelCount,
        channels: myScope.metrics.otaExposure.channels,
        myExposureScore: myScope.metrics.otaExposure.exposureScore,
        comparableExposureScore: comparableScope.metrics.otaExposure.exposureScore,
        basis: myScope.metrics.otaExposure.basis
      },
      b2bExposure: {
        status: target.b2bVisibility,
        eligible: target.b2bVisibility === "eligible",
        verifiedStatus: target.verifiedStatus
      },
      reliability: {
        companyConfidenceGrade: target.confidenceGrade,
        leadtimeConfidenceGrade: myScope.metrics.leadtime.confidenceGrade,
        leadtimePatternCount: myScope.metrics.leadtime.patternCount,
        observationCount: myScope.metrics.observationCount
      }
    },
    strategyRecommendations,
    strategyExperiments,
    adminStrategyExperiments: payload.includeAdminReview ? rawStrategyExperiments : undefined,
    experimentQualityLearning: {
      summary: experimentQualityHistorySummary(companyExperimentQualityHistory),
      publicSummary: companyExperimentQualityHistory.length ? "지난 실험 결과 반영됨" : ""
    },
    integratedLearning: {
      ...integratedLearningSummary,
      avgIntegratedGrade: integratedLearningSummary.total ? performanceGrade(integratedLearningSummary.avgIntegratedScore) : "-",
      avgRecommendationConfidenceGrade: integratedLearningSummary.avgRecommendationConfidence ? confidenceGrade(integratedLearningSummary.avgRecommendationConfidence) : "-"
    },
    adminExperimentQualityHistory: payload.includeAdminReview ? filterExperimentQualityHistory(experimentQualityHistory, new URLSearchParams({
      companyId: target.companyId
    })) : undefined,
    strategyExperimentExecution: experimentExecutionSummary(targetExperimentPlans),
    strategyExperimentResults: rawStrategyExperimentResults,
    strategyExecutionProgress: executionProgress,
    nextMonthStrategySummary: strategyRecommendations.map((item) => item.action).slice(0, 5),
    reportBoundaries: {
      source: "company master, verified profile, automatic observations, derived lead-time patterns, public-safe admin location card summaries, public-safe interest signal scores, public-safe strategy quality summaries, experiment quality summaries, integrated learning summaries, and segment-level recommendation learning",
      hidden: ROLE_DATA_POLICIES.business.hide,
      excluded: ["source observation rows", "source interest values", "operator notes", "admin location card memos", "review history", "version history", "file paths", "external IDs", "channel URLs", "internal scoring details", "failure diagnostics", "calibration settings", "segment learning source history"]
    }
  };
  if (payload.includeAdminReview) return report;
  return stripBusinessInternalQualityFields(applyBusinessReportEntitlements(report, subscriptionAccess));
}

function businessReportObservationCount(report = {}) {
  return Object.values(report.flows || {}).reduce((sum, flow) => (
    sum + Number(flow?.metrics?.observationCount || 0)
  ), 0);
}

function businessOnboardingStep(key, label, status, summary, action, href = "#businessFlowGrid") {
  const tone = status === "done" ? "good" : status === "current" ? "warning" : "muted";
  return { key, label, status, tone, summary, action, href };
}

async function businessOnboarding(payload = {}) {
  const companyId = String(payload.companyId || "").trim();
  if (!companyId) return null;
  const report = await businessReport({
    companyId,
    targetMonth: payload.targetMonth
  });
  if (!report) return null;
  const planData = await readStrategyExecutionPlans();
  const targetMonth = report.targetMonth || payload.targetMonth || nextMonthKey();
  const plans = (planData.items || []).filter((plan) => (
    plan.companyId === companyId && (!targetMonth || plan.targetMonth === targetMonth)
  ));
  const observationCount = businessReportObservationCount(report);
  const recommendations = report.strategyRecommendations || [];
  const locationTrust = report.regionCard?.locationCardTrust || {};
  const requestSummary = report.regionCard?.locationCardRequestStatus || {};
  const latestRequest = requestSummary.latest || null;
  const reportReady = observationCount > 0;
  const locationReady = locationTrust.status === "trusted";
  const locationRequested = Boolean(latestRequest && latestRequest.status !== "dismissed");
  const executionReady = plans.length > 0;
  const steps = [
    businessOnboardingStep(
      "select_company",
      "업체 선택",
      "done",
      `${report.company?.name || "선택한 업체"} 리포트 기준이 잡혔습니다.`,
      "리포트 흐름을 확인하세요.",
      "#businessCompanySelect"
    ),
    businessOnboardingStep(
      "review_report",
      "리포트 확인",
      reportReady ? "done" : "current",
      reportReady
        ? `관측 ${observationCount}건으로 시장/지역/내 숙소 흐름을 볼 수 있습니다.`
        : "리포트 판단을 위한 수집값이 부족합니다.",
      reportReady ? "지역카드와 전략 추천으로 이동하세요." : "빠른검색 또는 상세검색 보강을 요청하세요.",
      "#businessFlowGrid"
    ),
    businessOnboardingStep(
      "request_location_card",
      "입지카드 보강 요청",
      locationReady ? "done" : locationRequested ? "current" : "todo",
      locationReady
        ? `입지 신뢰도 ${locationTrust.confidenceGrade || "-"} 등급으로 반영됐습니다.`
        : locationRequested
          ? `요청 상태: ${latestRequest.label || latestRequest.status || "진행중"}`
          : "지역 구조와 수요 근거 보강 요청이 필요합니다.",
      locationReady ? "전략 추천을 실행계획으로 옮기세요." : "지역카드 보강 요청 CTA를 누르세요.",
      "#businessRegionCard"
    ),
    businessOnboardingStep(
      "save_execution_plan",
      "실행계획 저장",
      executionReady ? "done" : recommendations.length ? "current" : "todo",
      executionReady
        ? `이번 달 실행계획 ${plans.length}건이 운영보드에 저장됐습니다.`
        : recommendations.length
          ? `추천 전략 ${recommendations.length}건 중 실행할 카드를 저장하세요.`
          : "전략 추천을 만들기 위한 지표가 더 필요합니다.",
      executionReady ? "운영보드에서 담당자와 KPI를 관리하세요." : "전략 카드의 담당자/목표일/KPI를 입력하면 자동 저장됩니다.",
      "#businessStrategySummary"
    )
  ];
  const completed = steps.filter((step) => step.status === "done").length;
  const nextStep = steps.find((step) => step.status !== "done") || steps[steps.length - 1];
  return stripBusinessInternalQualityFields({
    role: "business",
    generatedAt: new Date().toISOString(),
    company: report.company,
    targetMonth,
    summary: {
      completed,
      total: steps.length,
      progress: Math.round((completed / steps.length) * 100),
      nextAction: nextStep?.action || "월간 운영보드를 확인하세요."
    },
    steps
  });
}

function adminBusinessOnboardingStatus({ reportReady = false, locationReady = false, qualityGrade = "D", planCount = 0, activeRequestCount = 0 } = {}) {
  if (reportReady && locationReady && ["A", "B"].includes(String(qualityGrade || "").toUpperCase()) && planCount > 0) {
    return { status: "ready", label: "상용 준비", tone: "good" };
  }
  if (activeRequestCount > 0 || !locationReady) return { status: "in_progress", label: "보강 진행", tone: "warning" };
  if (!reportReady || ["C", "D"].includes(String(qualityGrade || "").toUpperCase())) {
    return { status: "needs_data", label: "데이터 보강", tone: "warning" };
  }
  return { status: "needs_plan", label: "실행계획 필요", tone: "neutral" };
}

async function adminBusinessOnboardingSummary(params = new URLSearchParams()) {
  const [companiesData, profilesData, observationsData, leadtimePatternsData, locationCardsData, locationRequestsData, planData, reliabilityAudit] = await Promise.all([
    readCompanyMaster(),
    readVerifiedProfiles(),
    readPropertyObservations(),
    readLeadtimePatterns(),
    readLocationCards(),
    readLocationCardRequests(),
    readStrategyExecutionPlans(),
    dataReliabilityAudit(new URLSearchParams({ limit: "1000" }))
  ]);
  const query = compactKeyword(params.get("q") || "");
  const limit = Math.max(1, Math.min(300, Number(params.get("limit") || 100)));
  const profilesById = new Map((profilesData.items || []).map((item) => [item.companyId, item]));
  const reliabilityByCompanyId = new Map((reliabilityAudit.items || []).map((item) => [item.companyId, item]));
  const observationsByCompanyId = new Map();
  (observationsData.items || []).forEach((item) => {
    if (!observationsByCompanyId.has(item.companyId)) observationsByCompanyId.set(item.companyId, []);
    observationsByCompanyId.get(item.companyId).push(item);
  });
  const patternsByCompanyId = new Map();
  (leadtimePatternsData.items || []).forEach((item) => {
    if (!patternsByCompanyId.has(item.companyId)) patternsByCompanyId.set(item.companyId, []);
    patternsByCompanyId.get(item.companyId).push(item);
  });
  const requestsByCompanyId = new Map();
  (locationRequestsData.items || []).forEach((item) => {
    if (!requestsByCompanyId.has(item.companyId)) requestsByCompanyId.set(item.companyId, []);
    requestsByCompanyId.get(item.companyId).push(item);
  });
  const plansByCompanyId = new Map();
  (planData.items || []).forEach((item) => {
    if (!plansByCompanyId.has(item.companyId)) plansByCompanyId.set(item.companyId, []);
    plansByCompanyId.get(item.companyId).push(item);
  });
  const companies = (companiesData.items || [])
    .map((company) => resolvedCompanyForReport(company, profilesById, observationsData.items || [], leadtimePatternsData.items || []))
    .filter(reportCompanyVisible)
    .filter((company) => !query || compactKeyword(`${company.name} ${company.region} ${company.category}`).includes(query));
  const items = companies.map((company) => {
    const observations = observationsByCompanyId.get(company.companyId) || [];
    const patterns = patternsByCompanyId.get(company.companyId) || [];
    const requests = (requestsByCompanyId.get(company.companyId) || [])
      .sort((a, b) => String(b.updatedAt || b.requestedAt || "").localeCompare(String(a.updatedAt || a.requestedAt || "")));
    const activeRequests = requests.filter((item) => !["completed", "dismissed"].includes(item.status));
    const readiness = publicLocationCardReadiness(locationCardsData.items || [], company, observations);
    const locationReady = readiness.status === "trusted";
    const reliability = reliabilityByCompanyId.get(company.companyId) || {};
    const plans = plansByCompanyId.get(company.companyId) || [];
    const reportReady = observations.length > 0;
    const status = adminBusinessOnboardingStatus({
      reportReady,
      locationReady,
      qualityGrade: reliability.qualityGrade || company.confidenceGrade,
      planCount: plans.length,
      activeRequestCount: activeRequests.length
    });
    const nextActions = [];
    if (!reportReady) nextActions.push("빠른검색/상세검색 수집");
    if (!locationReady) nextActions.push(activeRequests.length ? "입지카드 요청 처리" : "입지카드 초안 생성");
    if (["C", "D"].includes(String(reliability.qualityGrade || company.confidenceGrade || "").toUpperCase())) nextActions.push("데이터 신뢰도 보강");
    if (!plans.length) nextActions.push("실행계획 저장 유도");
    return {
      companyId: company.companyId,
      name: company.name,
      region: company.region,
      category: company.category,
      onboardingStatus: status.status,
      onboardingLabel: status.label,
      onboardingTone: status.tone,
      reportReadiness: {
        ready: reportReady,
        observationCount: observations.length,
        leadtimePatternCount: patterns.length
      },
      locationCard: {
        status: readiness.status,
        label: readiness.label,
        confidenceGrade: readiness.confidenceGrade || "D",
        publicReady: locationReady,
        latestRequest: publicLocationCardRequest(requests[0] || null),
        activeRequestCount: activeRequests.length
      },
      dataReliability: {
        grade: reliability.qualityGrade || company.confidenceGrade || "D",
        score: reliability.qualityScore || 0,
        recommendedActions: (reliability.recommendedActions || []).slice(0, 3)
      },
      executionPlan: {
        count: plans.length,
        doneCount: plans.filter((plan) => plan.status === "done").length
      },
      nextActions: nextActions.length ? nextActions : ["사업자 온보딩 완료 후 월간 운영 점검"]
    };
  });
  const summary = items.reduce((acc, item) => {
    acc.total += 1;
    acc.byStatus[item.onboardingStatus] = (acc.byStatus[item.onboardingStatus] || 0) + 1;
    if (item.reportReadiness.ready) acc.reportReady += 1;
    if (item.locationCard.publicReady) acc.locationCardReady += 1;
    if (item.locationCard.activeRequestCount) acc.activeLocationRequests += item.locationCard.activeRequestCount;
    if (["C", "D"].includes(String(item.dataReliability.grade || "").toUpperCase())) acc.dataReliabilityNeeds += 1;
    if (item.executionPlan.count) acc.executionPlanReady += 1;
    return acc;
  }, {
    total: 0,
    byStatus: {},
    reportReady: 0,
    locationCardReady: 0,
    activeLocationRequests: 0,
    dataReliabilityNeeds: 0,
    executionPlanReady: 0
  });
  return {
    role: "admin",
    generatedAt: new Date().toISOString(),
    summary,
    items: items
      .sort((a, b) => (
        (a.onboardingStatus === "ready" ? 1 : 0) - (b.onboardingStatus === "ready" ? 1 : 0)
        || String(a.name).localeCompare(String(b.name), "ko")
      ))
      .slice(0, limit)
  };
}

async function businessRegionCard(payload = {}) {
  const companyId = String(payload.companyId || "").trim();
  if (!companyId) return null;
  const [companies, profiles, observations, leadtimePatterns, locationCards, locationCardRequests, interestSignals] = await Promise.all([
    readCompanyMaster(),
    readVerifiedProfiles(),
    readPropertyObservations(),
    readLeadtimePatterns(),
    readLocationCards(),
    readLocationCardRequests(),
    readInterestSignals()
  ]);
  const profilesById = new Map((profiles.items || []).map((item) => [item.companyId, item]));
  const patterns = leadtimePatterns.items || [];
  const resolvedCompanies = (companies.items || [])
    .map((company) => resolvedCompanyForReport(company, profilesById, observations.items || [], patterns));
  const target = resolvedCompanies.find((company) => company.companyId === companyId);
  if (!target) return null;
  const visibleCompanies = resolvedCompanies.filter(reportCompanyVisible);
  const interestAnalytics = buildInterestAnalytics(target, visibleCompanies, interestSignals.items || []);
  const targetObservations = (observations.items || []).filter((item) => item.companyId === target.companyId);
  const regionCard = buildRegionCard(
    target,
    visibleCompanies,
    observations.items || [],
    leadtimePatterns,
    interestSignals.items || [],
    interestAnalytics,
    publicLocationCardForTarget(locationCards.items || [], target),
    publicLocationCardReadiness(locationCards.items || [], target, targetObservations)
  );
  regionCard.locationCardRequestStatus = publicLocationCardRequestSummary(locationCardRequests.items || [], target);
  return stripBusinessInternalQualityFields({
    role: "business",
    companyId,
    generatedAt: new Date().toISOString(),
    regionCard,
    reportBoundaries: {
      source: "region profile, public-safe admin location card summaries, automatic observations, OTA exposure observations, derived lead-time patterns, and public-safe interest signal scores",
      hidden: ROLE_DATA_POLICIES.business.hide,
      excluded: ["source observation rows", "source interest values", "operator notes", "admin location card memos", "review history", "version history", "file paths", "external IDs", "collected URLs"]
    }
  });
}

async function businessCompanies(params = new URLSearchParams(), options = {}) {
  const [companies, profiles, observations, leadtimePatterns] = await Promise.all([
    readCompanyMaster(),
    readVerifiedProfiles(),
    readPropertyObservations(),
    readLeadtimePatterns()
  ]);
  const query = compactKeyword(params.get("q") || "");
  const limit = Math.max(1, Math.min(200, Number(params.get("limit") || 100)));
  const profilesById = new Map((profiles.items || []).map((item) => [item.companyId, item]));
  const patterns = leadtimePatterns.items || [];
  const allowedCompanyIds = Array.isArray(options.allowedCompanyIds) ? new Set(options.allowedCompanyIds) : null;
  const items = (companies.items || [])
    .filter((company) => !allowedCompanyIds || allowedCompanyIds.has(company.companyId))
    .map((company) => resolvedCompanyForReport(company, profilesById, observations.items || [], patterns))
    .filter(reportCompanyVisible)
    .filter((company) => !query || compactKeyword(`${company.name} ${company.region} ${company.category}`).includes(query))
    .sort((a, b) => String(a.name).localeCompare(String(b.name), "ko"))
    .slice(0, limit)
    .map((company) => ({
      companyId: company.companyId,
      name: company.name,
      region: company.region,
      category: company.category,
      confidenceGrade: company.confidenceGrade,
      verifiedStatus: company.verifiedStatus,
      b2bVisibility: company.b2bVisibility
    }));
  return { items };
}

